&lt;h2 id=&#34;六、环境搭建&#34;&gt;&lt;a href=&#34;#六、环境搭建&#34; class=&#34;headerlink&#34; title=&#34;六、环境搭建&#34;&gt;&lt;/a&gt;六、环境搭建&lt;/h2&gt;&lt;h3 id=&#34;本地环境要求&#34;&gt;&lt;a href=&#34;#本地环境要求&#34; class=&#34;headerlink&#34; title=&#34;本地环境要求&#34;&gt;&lt;/a&gt;本地环境要求&lt;/h3&gt;&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;工具&lt;/th&gt;
&lt;th&gt;最低版本&lt;/th&gt;
&lt;th&gt;说明&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;Docker Desktop&lt;/td&gt;
&lt;td&gt;20.10+&lt;/td&gt;
&lt;td&gt;自带 K8s 集群（macOS&amp;#x2F;Windows）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;minikube&lt;/td&gt;
&lt;td&gt;v1.30+&lt;/td&gt;
&lt;td&gt;轻量本地集群&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;kubectl&lt;/td&gt;
&lt;td&gt;v1.28+&lt;/td&gt;
&lt;td&gt;K8s 命令行工具&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Helm&lt;/td&gt;
&lt;td&gt;v3.12+&lt;/td&gt;
&lt;td&gt;K8s 包管理器&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;h3 id=&#34;推荐一键安装&#34;&gt;&lt;a href=&#34;#推荐一键安装&#34; class=&#34;headerlink&#34; title=&#34;推荐一键安装&#34;&gt;&lt;/a&gt;推荐一键安装&lt;/h3&gt;&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# Windows (choco)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;choco install kubernetes-cli helm minikube&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# macOS (brew)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;brew install kubectl helm minikube&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# Linux&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;curl -LO &lt;span class=&#34;string&#34;&gt;&amp;quot;https://dl.k8s.io/release/&lt;span class=&#34;subst&#34;&gt;$(curl -L -s https://dl.k8s.io/release/stable.txt)&lt;/span&gt;/bin/linux/amd64/kubectl&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h3 id=&#34;快速启动集群&#34;&gt;&lt;a href=&#34;#快速启动集群&#34; class=&#34;headerlink&#34; title=&#34;快速启动集群&#34;&gt;&lt;/a&gt;快速启动集群&lt;/h3&gt;&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# minikube&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;minikube start --cpus=4 --memory=8g&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;kubectl get nodes&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# Helm 初始化（v3 不需要 tiller）&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;helm repo add bitnami https://charts.bitnami.com/bitnami&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;helm repo update&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;helm search repo bitnami/nginx&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;hr&gt;
&lt;h2 id=&#34;七、学习工具推荐&#34;&gt;&lt;a href=&#34;#七、学习工具推荐&#34; class=&#34;headerlink&#34; title=&#34;七、学习工具推荐&#34;&gt;&lt;/a&gt;七、学习工具推荐&lt;/h2&gt;&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;用途&lt;/th&gt;
&lt;th&gt;工具&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;笔记&lt;/td&gt;
&lt;td&gt;Obsidian &amp;#x2F; Notion &amp;#x2F; 飞书文档&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;思维导图&lt;/td&gt;
&lt;td&gt;XMind &amp;#x2F; 飞书思维导图&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;命令行录屏&lt;/td&gt;
&lt;td&gt;asciinema（记录实操回放）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;K8s 可视化&lt;/td&gt;
&lt;td&gt;k9s（终端 UI） &amp;#x2F; Lens（桌面端）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;YAML 校验&lt;/td&gt;
&lt;td&gt;&lt;code&gt;kubectl explain&lt;/code&gt; &amp;#x2F; &lt;code&gt;helm lint&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;在线实验&lt;/td&gt;
&lt;td&gt;Play with Kubernetes (killer.sh)&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;刷题&lt;/td&gt;
&lt;td&gt;CKAD 模拟题 &amp;#x2F; killer.sh&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;hr&gt;
&lt;h2 id=&#34;八、小技巧&#34;&gt;&lt;a href=&#34;#八、小技巧&#34; class=&#34;headerlink&#34; title=&#34;八、小技巧&#34;&gt;&lt;/a&gt;八、小技巧&lt;/h2&gt;&lt;ol&gt;
&lt;li&gt;&lt;strong&gt;学一个做一个&lt;/strong&gt;：看完一个概念，立刻 &lt;code&gt;kubectl&lt;/code&gt; 敲一遍，不要光看不练&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;用别名省时间&lt;/strong&gt;：&lt;code&gt;alias k=kubectl&lt;/code&gt;，&lt;code&gt;alias kgp=&amp;#39;kubectl get pods&amp;#39;&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;日报驱动学习&lt;/strong&gt;：每周写一篇 K8s 学习笔记发博客，输出倒逼输入&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;加班日稳住节奏&lt;/strong&gt;：哪怕只看 10 分钟文档也要保持每日连续性&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;善用 &lt;code&gt;kubectl explain&lt;/code&gt;&lt;/strong&gt;：比查文档快，随时随地查资源字段&lt;/li&gt;
&lt;/ol&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 必设别名&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;alias&lt;/span&gt; k=&lt;span class=&#34;string&#34;&gt;&amp;#x27;kubectl&amp;#x27;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;alias&lt;/span&gt; kgp=&lt;span class=&#34;string&#34;&gt;&amp;#x27;k get pods&amp;#x27;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;alias&lt;/span&gt; kgs=&lt;span class=&#34;string&#34;&gt;&amp;#x27;k get svc&amp;#x27;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;alias&lt;/span&gt; kgd=&lt;span class=&#34;string&#34;&gt;&amp;#x27;k get deployment&amp;#x27;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;alias&lt;/span&gt; kaf=&lt;span class=&#34;string&#34;&gt;&amp;#x27;k apply -f&amp;#x27;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;alias&lt;/span&gt; kdf=&lt;span class=&#34;string&#34;&gt;&amp;#x27;k delete -f&amp;#x27;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;hr&gt;
&lt;h2 id=&#34;九、学习计划时间表（日历视图）&#34;&gt;&lt;a href=&#34;#九、学习计划时间表（日历视图）&#34; class=&#34;headerlink&#34; title=&#34;九、学习计划时间表（日历视图）&#34;&gt;&lt;/a&gt;九、学习计划时间表（日历视图）&lt;/h2&gt;&lt;h3 id=&#34;每周重复节奏&#34;&gt;&lt;a href=&#34;#每周重复节奏&#34; class=&#34;headerlink&#34; title=&#34;每周重复节奏&#34;&gt;&lt;/a&gt;每周重复节奏&lt;/h3&gt;&lt;figure class=&#34;highlight x86asm&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;周一 🕐 加班日 → 最小动作（复习 + &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt; 知识点）&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;周二 🕐 加班日 → 最小动作&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;周三 🌟 自由日 → 动手实践（&lt;span class=&#34;number&#34;&gt;2h&lt;/span&gt;）&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;周四 🕐 加班日 → 最小动作&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;周五 🌟 自由日 → 动手实践（&lt;span class=&#34;number&#34;&gt;2h&lt;/span&gt;）&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;周六 🎯 → 集中攻坚（&lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;-&lt;span class=&#34;number&#34;&gt;4h&lt;/span&gt;）&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;周日 🎯 → 集中攻坚（&lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;-&lt;span class=&#34;number&#34;&gt;4h&lt;/span&gt;）&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;&lt;strong&gt;每周保底投入：&lt;/strong&gt; 4 天×1h（加班日） + 2 天×2h（自由日晚） + 2 天×3h（周末） ≈ &lt;strong&gt;14h&amp;#x2F;周&lt;/strong&gt;&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;坚持这个节奏，6 周就能从零到上手干活 💪&lt;/p&gt;
&lt;/blockquote&gt;

 &lt;h2 id=&#34;今日热点&#34;&gt;&lt;a href=&#34;#今日热点&#34; class=&#34;headerlink&#34; title=&#34;今日热点&#34;&gt;&lt;/a&gt;今日热点&lt;/h2&gt;&lt;p&gt;AI 领域今天上演了一场多方大戏。GitHub 上 &lt;code&gt;addyosmani/agent-skills&lt;/code&gt; 单日斩获 3000+ Star，AI Coding Agent 技能工程化成为社区共识；xAI 正式更名为 SpaceXAI，与 Anthropic 达成计算合作；OpenAI 联合 AMD、NVIDIA 等巨头发布 MRC 超算网络协议；Subquadratic 初创公司声称实现 1000 倍 AI 效率提升。本地化和 Agent 化是今日两大关键词。&lt;/p&gt;
&lt;hr&gt;
&lt;h2 id=&#34;GitHub-热门-AI-项目&#34;&gt;&lt;a href=&#34;#GitHub-热门-AI-项目&#34; class=&#34;headerlink&#34; title=&#34;GitHub 热门 AI 项目&#34;&gt;&lt;/a&gt;GitHub 热门 AI 项目&lt;/h2&gt;&lt;h3 id=&#34;🔥-1-addyosmani-agent-skills-—-AI-Coding-Agent-技能库&#34;&gt;&lt;a href=&#34;#🔥-1-addyosmani-agent-skills-—-AI-Coding-Agent-技能库&#34; class=&#34;headerlink&#34; title=&#34;🔥 1. addyosmani&amp;#x2F;agent-skills — AI Coding Agent 技能库&#34;&gt;&lt;/a&gt;🔥 1. &lt;a href=&#34;https://github.com/addyosmani/agent-skills&#34;&gt;addyosmani&amp;#x2F;agent-skills&lt;/a&gt; — AI Coding Agent 技能库&lt;/h3&gt;&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Star&lt;/strong&gt;: 32,335（今日 +3,058）&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;语言&lt;/strong&gt;: Shell&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;是什么&lt;/strong&gt;: 一套面向 AI 编程 Agent 的生产级工程技能集合。由 Chrome 团队 Addy Osmani 打造，帮你教会 AI Agent 如何进行代码审查、调试、性能优化等专业操作。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;这是今天的绝对明星项目。它的核心理念是：&lt;strong&gt;AI Agent 的能力上限不取决于模型本身，而取决于你教它的”技能清单”&lt;/strong&gt;。项目内置了从 Git 工作流、依赖管理到安全审计等数十个技能模板，每个技能都是一个标准化的 prompt + 工具调用组合。配合 MCP（Model Context Protocol）使用效果更佳。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;为何爆火&lt;/strong&gt;：DeepSeek、Claude Code、Codex 等编程 Agent 的普及让开发者意识到”调教 Agent”本身就是一门技术，这个项目恰好填补了这一空白——把最佳实践打包成可复用的技能包。&lt;/p&gt;
&lt;h3 id=&#34;🔬-2-z-lab-dflash-—-块扩散推测解码&#34;&gt;&lt;a href=&#34;#🔬-2-z-lab-dflash-—-块扩散推测解码&#34; class=&#34;headerlink&#34; title=&#34;🔬 2. z-lab&amp;#x2F;dflash — 块扩散推测解码&#34;&gt;&lt;/a&gt;🔬 2. &lt;a href=&#34;https://github.com/z-lab/dflash&#34;&gt;z-lab&amp;#x2F;dflash&lt;/a&gt; — 块扩散推测解码&lt;/h3&gt;&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Star&lt;/strong&gt;: 3,299（今日 +654）&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;语言&lt;/strong&gt;: Python&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;是什么&lt;/strong&gt;: DFlash（Block Diffusion for Flash Speculative Decoding）—— 一种全新的 LLM 推理加速方法，通过块级别的扩散模型实现推测解码。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;推测解码（Speculative Decoding）是今年推理优化最火热的方向之一。传统方法用一个小模型逐 token 生成草稿，大模型验证；DFlash 的创新在于用块扩散一次生成多个 token 的草稿，大幅降低了验证轮次。简单说：&lt;strong&gt;别人逐字猜，你整句猜，猜对的概率还更高&lt;/strong&gt;。&lt;/p&gt;
&lt;figure class=&#34;highlight plaintext&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;flowchart LR&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    A[输入 Prompt] --&amp;gt; B[块扩散草稿模型]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    B --&amp;gt; C[生成 N-token 块草稿]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    C --&amp;gt; D&amp;#123;目标 LLM 并行验证&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    D --&amp;gt;|全部接受| E[输出完整块]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    D --&amp;gt;|部分拒绝| F[保留接受部分&amp;lt;br&amp;gt;重新生成剩余]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    E --&amp;gt; G[下一轮]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    F --&amp;gt; B&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h3 id=&#34;🧠-3-LearningCircuit-local-deep-research&#34;&gt;&lt;a href=&#34;#🧠-3-LearningCircuit-local-deep-research&#34; class=&#34;headerlink&#34; title=&#34;🧠 3. LearningCircuit&amp;#x2F;local-deep-research&#34;&gt;&lt;/a&gt;🧠 3. &lt;a href=&#34;https://github.com/LearningCircuit/local-deep-research&#34;&gt;LearningCircuit&amp;#x2F;local-deep-research&lt;/a&gt;&lt;/h3&gt;&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Star&lt;/strong&gt;: 6,031（今日 +564）&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;语言&lt;/strong&gt;: Python&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;是什么&lt;/strong&gt;: 完全本地化的深度研究（Deep Research）工具，在 SimpleQA 上达到约 95% 的准确率（用 Qwen3.6-27B 跑在 RTX 3090 上）。支持 10+ 搜索引擎包括 arXiv、PubMed，支持所有本地和云端 LLM（llama.cpp、Ollama、Google 等）。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;亮点&lt;/strong&gt;：纯本地、全加密，数据不出本机。对于需要处理敏感场景的用户（金融、医疗、法律行业）来说，这几乎是唯一可行的 Deep Research 方案。它在方法论上做得也很扎实——不是简单搜了就给答案，而是多轮搜索-阅读-总结迭代。&lt;/p&gt;
&lt;h3 id=&#34;⚡-4-Anthropics-financial-services&#34;&gt;&lt;a href=&#34;#⚡-4-Anthropics-financial-services&#34; class=&#34;headerlink&#34; title=&#34;⚡ 4. Anthropics&amp;#x2F;financial-services&#34;&gt;&lt;/a&gt;⚡ 4. &lt;a href=&#34;https://github.com/anthropics/financial-services&#34;&gt;Anthropics&amp;#x2F;financial-services&lt;/a&gt;&lt;/h3&gt;&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Star&lt;/strong&gt;: 10,215（今日 +1,367）&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;语言&lt;/strong&gt;: Python&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;是什么&lt;/strong&gt;: Anthropic 官方发布的金融服务 AI 参考实现。包含反欺诈检测、合规审查、交易分析等场景的最佳实践。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;Anthropic 正在加速行业落地。金融行业的监管要求极其严苛，这个项目展示了如何用 Claude 在合规框架下处理敏感金融数据。今日 +1,367 Star 说明开发者社区对垂直行业 AI 落地的关注度正在加速。&lt;/p&gt;
&lt;h3 id=&#34;🏗️-5-InsForge-InsForge&#34;&gt;&lt;a href=&#34;#🏗️-5-InsForge-InsForge&#34; class=&#34;headerlink&#34; title=&#34;🏗️ 5. InsForge&amp;#x2F;InsForge&#34;&gt;&lt;/a&gt;🏗️ 5. &lt;a href=&#34;https://github.com/InsForge/InsForge&#34;&gt;InsForge&amp;#x2F;InsForge&lt;/a&gt;&lt;/h3&gt;&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Star&lt;/strong&gt;: 8,705（今日 +459）&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;语言&lt;/strong&gt;: TypeScript&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;是什么&lt;/strong&gt;: 基于 Postgres 的全栈后端平台，集成了认证、存储、计算、托管和 AI 网关，专为 Coding Agent 构建。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;Agent 时代的 Supabase。在 Agent 需要自主运行后端的场景下，传统的 BaaS 不够灵活、自建又太重。InsForge 瞄准了这个缝隙——Agent 自己就能用它搭起一个完整的后端服务。&lt;/p&gt;
&lt;h3 id=&#34;📊-6-PriorLabs-TabPFN&#34;&gt;&lt;a href=&#34;#📊-6-PriorLabs-TabPFN&#34; class=&#34;headerlink&#34; title=&#34;📊 6. PriorLabs&amp;#x2F;TabPFN&#34;&gt;&lt;/a&gt;📊 6. &lt;a href=&#34;https://github.com/PriorLabs/TabPFN&#34;&gt;PriorLabs&amp;#x2F;TabPFN&lt;/a&gt;&lt;/h3&gt;&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Star&lt;/strong&gt;: 6,718（今日 +233）&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;语言&lt;/strong&gt;: Python&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;是什么&lt;/strong&gt;: 表格数据的 Foundation Model。用 Transformer 架构直接对表格数据进行推理，零样本效果媲美数百棵树的 XGBoost 集成。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;如果你做数据科学，TabPFN 值得关注。传统的表格数据建模需要特征工程、调参、集成学习，TabPFN 的做法是：把整个数据集当作序列喂给 Transformer，一步到位。这可能是 AutoML 的下一个范式。&lt;/p&gt;
&lt;figure class=&#34;highlight plaintext&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;flowchart TB&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    subgraph 传统流程&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        A1[原始表格] --&amp;gt; A2[特征工程]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        A2 --&amp;gt; A3[模型选择/调参]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        A3 --&amp;gt; A4[集成验证]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        A4 --&amp;gt; A5[预测]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    end&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    subgraph TabPFN 流程&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        B1[原始表格] --&amp;gt; B2[序列化编码]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        B2 --&amp;gt; B3[Pre-trained Transformer]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        B3 --&amp;gt; B4[一步预测]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    end&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    style A5 fill:#f96,stroke:#333&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    style B4 fill:#6f9,stroke:#333&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h3 id=&#34;🤖-7-vercel-labs-open-agents&#34;&gt;&lt;a href=&#34;#🤖-7-vercel-labs-open-agents&#34; class=&#34;headerlink&#34; title=&#34;🤖 7. vercel-labs&amp;#x2F;open-agents&#34;&gt;&lt;/a&gt;🤖 7. &lt;a href=&#34;https://github.com/vercel-labs/open-agents&#34;&gt;vercel-labs&amp;#x2F;open-agents&lt;/a&gt;&lt;/h3&gt;&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Star&lt;/strong&gt;: 4,920（今日 +406）&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;语言&lt;/strong&gt;: TypeScript&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;是什么&lt;/strong&gt;: Vercel 推出的开源云 Agent 模板，用于快速构建和部署 AI Agent。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;Vercel 做 Agent 框架了。&lt;code&gt;open-agents&lt;/code&gt; 是一个端到端的云 Agent 模板，内置了流式响应、工具调用、会话管理等特性，部署在 Vercel Edge 上。Vercel 的直觉是对的——Agent 需要后端（持久化、任务队列、认证），而 Vercel 刚好是这个生态的默认选项。&lt;/p&gt;
&lt;h3 id=&#34;🛠️-8-decolua-9router&#34;&gt;&lt;a href=&#34;#🛠️-8-decolua-9router&#34; class=&#34;headerlink&#34; title=&#34;🛠️ 8. decolua&amp;#x2F;9router&#34;&gt;&lt;/a&gt;🛠️ 8. &lt;a href=&#34;https://github.com/decolua/9router&#34;&gt;decolua&amp;#x2F;9router&lt;/a&gt;&lt;/h3&gt;&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Star&lt;/strong&gt;: 4,189（今日 +130）&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;语言&lt;/strong&gt;: JavaScript&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;是什么&lt;/strong&gt;: 免费的 AI 路由层。为 Claude Code、Codex、Cursor、Cline、Copilot 等提供到 40+ 个 LLM 提供商的免费路由，自动故障切换，节省 40% 令牌。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;Agent 时代的网络代理。9router 解决了”API Key 用完了怎么办”这个现实问题——它聚合了 40+ 提供商的免费额度，自动分配和故障切换。对于重度使用 AI 编程工具的开发者来说，这是个降低成本的实用方案。&lt;/p&gt;
&lt;h3 id=&#34;🎬-9-Augani-openreel-video&#34;&gt;&lt;a href=&#34;#🎬-9-Augani-openreel-video&#34; class=&#34;headerlink&#34; title=&#34;🎬 9. Augani&amp;#x2F;openreel-video&#34;&gt;&lt;/a&gt;🎬 9. &lt;a href=&#34;https://github.com/Augani/openreel-video&#34;&gt;Augani&amp;#x2F;openreel-video&lt;/a&gt;&lt;/h3&gt;&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Star&lt;/strong&gt;: 1,259（今日 +208）&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;语言&lt;/strong&gt;: TypeScript&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;是什么&lt;/strong&gt;: 浏览器端专业视频编辑器，开源 CapCut 替代品。100% 浏览器运行，无需安装、无需上传。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;AI 视频编辑的开源化趋势。虽然今天增长不高，但这类工具是 AI 原生创作的重要组件。&lt;/p&gt;
&lt;hr&gt;
&lt;h2 id=&#34;新工具-产品速览&#34;&gt;&lt;a href=&#34;#新工具-产品速览&#34; class=&#34;headerlink&#34; title=&#34;新工具&amp;#x2F;产品速览&#34;&gt;&lt;/a&gt;新工具&amp;#x2F;产品速览&lt;/h2&gt;&lt;h3 id=&#34;🚀-OpenAI-GPT-5-5-Instant-内存透明化&#34;&gt;&lt;a href=&#34;#🚀-OpenAI-GPT-5-5-Instant-内存透明化&#34; class=&#34;headerlink&#34; title=&#34;🚀 OpenAI GPT-5.5 Instant + 内存透明化&#34;&gt;&lt;/a&gt;🚀 OpenAI GPT-5.5 Instant + 内存透明化&lt;/h3&gt;&lt;p&gt;OpenAI 将 ChatGPT 默认模型更新为 GPT-5.5 Instant，新增”记忆透明”功能——终于展示哪些上下文影响了模型的回答。虽然是”部分透明”（只展示部分推理上下文），但这标志着大模型从黑盒走向可解释的关键一步。同时 OpenAI 为 8,000 名开发者 10 倍提升了 Codex 速率限制，有效期至 6 月 5 日。&lt;/p&gt;
&lt;h3 id=&#34;🤖-Hugging-Face-Reachy-Mini-App-Store&#34;&gt;&lt;a href=&#34;#🤖-Hugging-Face-Reachy-Mini-App-Store&#34; class=&#34;headerlink&#34; title=&#34;🤖 Hugging Face Reachy Mini App Store&#34;&gt;&lt;/a&gt;🤖 Hugging Face Reachy Mini App Store&lt;/h3&gt;&lt;p&gt;Hugging Face 推出了开源 Reachy Mini 机器人应用商店，首发 200+ 社区构建的机器人应用，免费下载。这是”机器人的 App Store”，每个应用都可以通过自然语言唤醒和操控机器人完成不同任务——从抓取物体到导航避障。&lt;/p&gt;
&lt;h3 id=&#34;⚡-Subquadratic-宣称-1000-倍-AI-效率提升&#34;&gt;&lt;a href=&#34;#⚡-Subquadratic-宣称-1000-倍-AI-效率提升&#34; class=&#34;headerlink&#34; title=&#34;⚡ Subquadratic 宣称 1000 倍 AI 效率提升&#34;&gt;&lt;/a&gt;⚡ Subquadratic 宣称 1000 倍 AI 效率提升&lt;/h3&gt;&lt;p&gt;迈阿密初创公司 Subquadratic 走出隐身模式，声称其 SubQ 模型完全脱离了 2017 年以来定义所有主流 AI 系统的数学约束（即 Transformer 的二次方注意力复杂度）。研究者们要求独立验证。如果属实，这将是对 AI 基础设施的一次范式级冲击。&lt;/p&gt;
&lt;h3 id=&#34;🏢-Microsoft-Agent-365-正式-GA&#34;&gt;&lt;a href=&#34;#🏢-Microsoft-Agent-365-正式-GA&#34; class=&#34;headerlink&#34; title=&#34;🏢 Microsoft Agent 365 正式 GA&#34;&gt;&lt;/a&gt;🏢 Microsoft Agent 365 正式 GA&lt;/h3&gt;&lt;p&gt;微软将 Agent 365 从预览转为正式版，定位为”AI Agent 的统一控制平面”，让企业 IT 和安全团队跨 Microsoft 生态、AWS Bedrock、Google Cloud 和员工终端统一治理 AI Agent。Shadow AI（影子 AI）成为企业新威胁，Agent 365 瞄准的就是这个痛点。&lt;/p&gt;
&lt;h3 id=&#34;💳-AMEX-Agentic-Commerce-Stack&#34;&gt;&lt;a href=&#34;#💳-AMEX-Agentic-Commerce-Stack&#34; class=&#34;headerlink&#34; title=&#34;💳 AMEX Agentic Commerce Stack&#34;&gt;&lt;/a&gt;💳 AMEX Agentic Commerce Stack&lt;/h3&gt;&lt;p&gt;美国运通正在构建一套让 AI Agent 能自主购物和支付的系统，核心设计包括”意图合约”（Intent Contracts）和”一次性令牌”（Single-Use Tokens），确保 Agent 可以在用户授权范围内完成交易。&lt;/p&gt;
&lt;hr&gt;
&lt;h2 id=&#34;行业动态&#34;&gt;&lt;a href=&#34;#行业动态&#34; class=&#34;headerlink&#34; title=&#34;行业动态&#34;&gt;&lt;/a&gt;行业动态&lt;/h2&gt;&lt;h3 id=&#34;🧑‍⚖️-Musk-v-Altman-庭审持续发酵&#34;&gt;&lt;a href=&#34;#🧑‍⚖️-Musk-v-Altman-庭审持续发酵&#34; class=&#34;headerlink&#34; title=&#34;🧑‍⚖️ Musk v. Altman 庭审持续发酵&#34;&gt;&lt;/a&gt;🧑‍⚖️ Musk v. Altman 庭审持续发酵&lt;/h3&gt;&lt;p&gt;OpenAI 前董事会成员 Helen Toner 的关键证词披露了更多细节：Sam Altman 被解雇的核心原因是对 OpenAI 创业基金的利益冲突不够坦诚，以及”不诚实和不坦诚的行为模式”。xAI 正式更名为 SpaceXAI，Elon Musk 整合 AI 业务的意图更加明确。&lt;/p&gt;
&lt;h3 id=&#34;🤝-xAI-→-SpaceXAI，与-Anthropic-达成计算合作&#34;&gt;&lt;a href=&#34;#🤝-xAI-→-SpaceXAI，与-Anthropic-达成计算合作&#34; class=&#34;headerlink&#34; title=&#34;🤝 xAI → SpaceXAI，与 Anthropic 达成计算合作&#34;&gt;&lt;/a&gt;🤝 xAI → SpaceXAI，与 Anthropic 达成计算合作&lt;/h3&gt;&lt;p&gt;更名后的 SpaceXAI 与 Anthropic 宣布计算合作，这在 AI 行业竞争格局中是一个出人意料但值得玩味的组合。&lt;/p&gt;
&lt;h3 id=&#34;🌐-OpenAI-MRC-超算网络协议&#34;&gt;&lt;a href=&#34;#🌐-OpenAI-MRC-超算网络协议&#34; class=&#34;headerlink&#34; title=&#34;🌐 OpenAI MRC 超算网络协议&#34;&gt;&lt;/a&gt;🌐 OpenAI MRC 超算网络协议&lt;/h3&gt;&lt;p&gt;OpenAI 联合 AMD、Broadcom、Intel、Microsoft、NVIDIA 发布 Multipath Reliable Connection（MRC）协议，专为大规模 GPU 训练集群优化网络性能。协议已经通过 Open Compute Project 公开，可能成为 AI 数据中心的网络新标准。&lt;/p&gt;
&lt;h3 id=&#34;📊-43-美国人将数据中心视为电费上涨主因&#34;&gt;&lt;a href=&#34;#📊-43-美国人将数据中心视为电费上涨主因&#34; class=&#34;headerlink&#34; title=&#34;📊 43% 美国人将数据中心视为电费上涨主因&#34;&gt;&lt;/a&gt;📊 43% 美国人将数据中心视为电费上涨主因&lt;/h3&gt;&lt;p&gt;Pew Research 调查显示，数据中心对电力基础设施的压力已经成为两党共识议题。这对 AI 行业的扩张节奏可能产生深远影响——算力需求和能源约束的矛盾将持续激化。&lt;/p&gt;
&lt;h3 id=&#34;🏛️-美国政府扩大-AI-国防供应商名录，重新评估-Anthropic-角色&#34;&gt;&lt;a href=&#34;#🏛️-美国政府扩大-AI-国防供应商名录，重新评估-Anthropic-角色&#34; class=&#34;headerlink&#34; title=&#34;🏛️ 美国政府扩大 AI 国防供应商名录，重新评估 Anthropic 角色&#34;&gt;&lt;/a&gt;🏛️ 美国政府扩大 AI 国防供应商名录，重新评估 Anthropic 角色&lt;/h3&gt;&lt;p&gt;美国政府在 AI 国防领域的动作加速，同时正在重新审视 Anthropic 的角色定位。&lt;/p&gt;
&lt;hr&gt;
&lt;h2 id=&#34;技术洞见&#34;&gt;&lt;a href=&#34;#技术洞见&#34; class=&#34;headerlink&#34; title=&#34;技术洞见&#34;&gt;&lt;/a&gt;技术洞见&lt;/h2&gt;&lt;h3 id=&#34;趋势一：Agent-技能工程化-——-从”调-Prompt”到”教技能”&#34;&gt;&lt;a href=&#34;#趋势一：Agent-技能工程化-——-从”调-Prompt”到”教技能”&#34; class=&#34;headerlink&#34; title=&#34;趋势一：Agent 技能工程化 —— 从”调 Prompt”到”教技能”&#34;&gt;&lt;/a&gt;趋势一：Agent 技能工程化 —— 从”调 Prompt”到”教技能”&lt;/h3&gt;&lt;p&gt;&lt;code&gt;addyosmani/agent-skills&lt;/code&gt; 单日 +3,058 Star 不是一个孤立事件。它反映了 AI 开发社区的一个深层转向：&lt;strong&gt;最优秀的 AI 开发者不再花时间调 prompt，而是花时间教 AI 学会一整套工程技能&lt;/strong&gt;。&lt;/p&gt;
&lt;p&gt;这个趋势早期的信号是 Anthropic 的 MCP 协议和 OpenAI 的 Function Calling，现在的深化是像 &lt;code&gt;agent-skills&lt;/code&gt; 这样成体系的技能包。未来的 AI 工程师的核心能力不再是写代码，而是设计”Agent 课程”——如何把人类专家的隐性知识转化为 Agent 可复用的技能。&lt;/p&gt;
&lt;figure class=&#34;highlight plaintext&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;flowchart LR&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    subgraph &amp;quot;传统开发模式&amp;quot;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        D1[开发者写代码] --&amp;gt; D2[调试/部署]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        D2 --&amp;gt; D3[维护]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    end&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    subgraph &amp;quot;过渡模式 (现在)&amp;quot;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        E1[开发者写 Prompt] --&amp;gt; E2[Agent 生成代码]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        E2 --&amp;gt; E3[人工审查/修正]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    end&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    subgraph &amp;quot;Agent 技能模式 (未来)&amp;quot;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        F1[开发者设计技能包] --&amp;gt; F2[Agent 自学/执行]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        F2 --&amp;gt; F3[自动验证/迭代]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        F3 --&amp;gt;|结果反馈| F1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    end&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    D3 -.-&amp;gt; E1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    E3 -.-&amp;gt; F1&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h3 id=&#34;趋势二：本地化-AI-的全面觉醒&#34;&gt;&lt;a href=&#34;#趋势二：本地化-AI-的全面觉醒&#34; class=&#34;headerlink&#34; title=&#34;趋势二：本地化 AI 的全面觉醒&#34;&gt;&lt;/a&gt;趋势二：本地化 AI 的全面觉醒&lt;/h3&gt;&lt;p&gt;&lt;code&gt;local-deep-research&lt;/code&gt; 6k+ Star、&lt;code&gt;llama.cpp&lt;/code&gt; 生态持续繁荣、DeepSeek 模型的本地部署热潮——这不是巧合。有几个驱动因素：&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;&lt;strong&gt;隐私合规&lt;/strong&gt;：金融、医疗、法律行业不能把敏感数据送到云端&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;成本控制&lt;/strong&gt;：API 调用成本随着使用量增长非线性膨胀，本地部署有固定的硬件成本天花板&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;延迟需求&lt;/strong&gt;：Agent 需要毫秒级的工具调用决策，云端延迟不可接受&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;模型能力拐点&lt;/strong&gt;：Qwen3、DeepSeek 等开源模型在特定任务上已经媲美 GPT-4，本地部署不再意味着降级&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;值得关注的是 &lt;code&gt;local-deep-research&lt;/code&gt; 实现了一套完整的多轮搜索-阅读-迭代框架，而非简单的”搜了就给”。它采用的 Iterative Deep Research 方法与 OpenAI 的 Deep Research 在架构上有异曲同工之妙——区别在于全部跑在本地。&lt;/p&gt;
&lt;h3 id=&#34;对未来一周的判断&#34;&gt;&lt;a href=&#34;#对未来一周的判断&#34; class=&#34;headerlink&#34; title=&#34;对未来一周的判断&#34;&gt;&lt;/a&gt;对未来一周的判断&lt;/h3&gt;&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Agent 工具链将继续爆发&lt;/strong&gt;：&lt;code&gt;open-agents&lt;/code&gt;、&lt;code&gt;InsForge&lt;/code&gt;、&lt;code&gt;agent-skills&lt;/code&gt; 分别代表了 Agent 开发的不同层面——应用模板、后端基础设施、技能设计。接下来会有更多 Agent 编排、监控、调试工具出现&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;推理优化进入快车道&lt;/strong&gt;：DFlash 的块扩散推测解码，Subquadratic 的 SubQ 模型，都在冲击 Transformer 架构的推理瓶颈。推理成本每季度下降 50% 的趋势可能还会加速&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;AI 立法和数据中心能源将进入舆论中心&lt;/strong&gt;：美国两党在数据中心问题上已形成共识，后续政策变化可能影响云厂商的扩张计划&lt;/li&gt;
&lt;/ul&gt;
&lt;hr&gt;
&lt;p&gt;&lt;em&gt;本日报由 AI 自动生成，数据来源包括 GitHub Trending、The Verge、VentureBeat、AI News。部分链接以标题形式呈现，可通过项目名称直达。&lt;/em&gt;&lt;/p&gt;

 &lt;blockquote&gt;
&lt;p&gt;本文是 Hermes Agent 系列的第二篇。如果你还没安装，建议先阅读 &lt;a href=&#34;/Hermes-Agent-%E5%AE%89%E8%A3%85%E4%B8%8E%E4%BD%BF%E7%94%A8%E6%8C%87%E5%8D%97/&#34;&gt;《Hermes Agent 安装与使用指南》&lt;/a&gt;。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h2 id=&#34;概览&#34;&gt;&lt;a href=&#34;#概览&#34; class=&#34;headerlink&#34; title=&#34;概览&#34;&gt;&lt;/a&gt;概览&lt;/h2&gt;&lt;p&gt;安装只是第一步，真正让 Hermes Agent 发挥全部威力的是&lt;strong&gt;深度配置&lt;/strong&gt;与&lt;strong&gt;进阶用法&lt;/strong&gt;。本文将从核心配置文件出发，一步步带你掌握自定义技能开发、多代理协作、自定义后端、安全强化等高级主题。&lt;/p&gt;
&lt;figure class=&#34;highlight plaintext&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;flowchart TD&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    subgraph &amp;quot;配置层&amp;quot;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        A[config.yaml] --&amp;gt; B[模型路由]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        A --&amp;gt; C[终端后端]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        A --&amp;gt; D[消息网关]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        A --&amp;gt; E[安全策略]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    end&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    subgraph &amp;quot;能力层&amp;quot;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        F[自定义技能开发]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        G[多代理管线]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        H[记忆策略调优]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        I[定时任务编排]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    end&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    subgraph &amp;quot;部署层&amp;quot;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        J[Docker Compose]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        K[SSH 集群]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        L[Daytona Cloud]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        M[Modal Serverless]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    end&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    B &amp;amp; C &amp;amp; D &amp;amp; E --&amp;gt; F &amp;amp; G &amp;amp; H &amp;amp; I&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    F &amp;amp; G &amp;amp; H &amp;amp; I --&amp;gt; J &amp;amp; K &amp;amp; L &amp;amp; M&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    style A fill:#7C3AED,color:#fff&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    style F fill:#F59E0B,color:#000&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    style J fill:#10B981,color:#fff&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;hr&gt;
&lt;h2 id=&#34;1-核心配置深度解析&#34;&gt;&lt;a href=&#34;#1-核心配置深度解析&#34; class=&#34;headerlink&#34; title=&#34;1. 核心配置深度解析&#34;&gt;&lt;/a&gt;1. 核心配置深度解析&lt;/h2&gt;&lt;p&gt;Hermes Agent 的配置体系分为两层：&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;层级&lt;/th&gt;
&lt;th&gt;文件&lt;/th&gt;
&lt;th&gt;用途&lt;/th&gt;
&lt;th&gt;示例&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;非敏感配置&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;~/.hermes/config.yaml&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;模型、后端、平台、行为&lt;/td&gt;
&lt;td&gt;默认模型、终端类型&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;密钥配置&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;~/.hermes/.env&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;API Keys、Tokens&lt;/td&gt;
&lt;td&gt;&lt;code&gt;ANTHROPIC_API_KEY=sk-ant-xxx&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;h3 id=&#34;1-1-config-yaml-全字段详解&#34;&gt;&lt;a href=&#34;#1-1-config-yaml-全字段详解&#34; class=&#34;headerlink&#34; title=&#34;1.1 config.yaml 全字段详解&#34;&gt;&lt;/a&gt;1.1 config.yaml 全字段详解&lt;/h3&gt;&lt;figure class=&#34;highlight yaml&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# ============ 模型配置 ============&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attr&#34;&gt;model:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;anthropic/claude-sonnet-4-20250514&lt;/span&gt;    &lt;span class=&#34;comment&#34;&gt;# 默认模型&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 模型格式: provider/model-name&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 常见: openai/gpt-4o, deepseek/deepseek-chat, google/gemini-2.5-flash&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# ============ 回退模型 ============&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attr&#34;&gt;fallback_models:&lt;/span&gt;                              &lt;span class=&#34;comment&#34;&gt;# 主模型不可用时自动回退&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;bullet&#34;&gt;-&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;anthropic/claude-haiku-3-20250313&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;bullet&#34;&gt;-&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;openai/gpt-4o-mini&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;bullet&#34;&gt;-&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;openrouter/meta-llama/llama-4-scout&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# ============ 上下文窗口 ============&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attr&#34;&gt;max_tokens:&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;200000&lt;/span&gt;                            &lt;span class=&#34;comment&#34;&gt;# 最大上下文 token 数&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attr&#34;&gt;max_output_tokens:&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;8192&lt;/span&gt;                       &lt;span class=&#34;comment&#34;&gt;# 每次回复最大输出&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attr&#34;&gt;context_compression:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;auto&lt;/span&gt;                     &lt;span class=&#34;comment&#34;&gt;# auto | manual | off&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attr&#34;&gt;compress_at_pct:&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;80&lt;/span&gt;                           &lt;span class=&#34;comment&#34;&gt;# 上下文使用达 80% 时自动压缩&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# ============ 温度与采样 ============&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attr&#34;&gt;temperature:&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;0.3&lt;/span&gt;                              &lt;span class=&#34;comment&#34;&gt;# 创造力 (0.0-2.0)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attr&#34;&gt;top_p:&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;0.95&lt;/span&gt;                                   &lt;span class=&#34;comment&#34;&gt;# 核采样阈值&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attr&#34;&gt;top_k:&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;40&lt;/span&gt;                                     &lt;span class=&#34;comment&#34;&gt;# Top-K 采样&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# ============ 终端后端 ============&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attr&#34;&gt;terminal:&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;backend:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;local&lt;/span&gt;                              &lt;span class=&#34;comment&#34;&gt;# local | docker | ssh | daytona | modal&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;work_dir:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;/home/user/hermes-workspace&lt;/span&gt;       &lt;span class=&#34;comment&#34;&gt;# 默认工作目录&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;isolated:&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;true&lt;/span&gt;                              &lt;span class=&#34;comment&#34;&gt;# 隔离模式（禁止访问 ~ 外目录）&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;network:&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;false&lt;/span&gt;                              &lt;span class=&#34;comment&#34;&gt;# 禁止终端访问网络&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;timeout:&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;120&lt;/span&gt;                                &lt;span class=&#34;comment&#34;&gt;# 命令最长时间（秒）&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# ============ 消息网关 ============&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attr&#34;&gt;gateway:&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;host:&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;0.0&lt;/span&gt;&lt;span class=&#34;number&#34;&gt;.0&lt;/span&gt;&lt;span class=&#34;number&#34;&gt;.0&lt;/span&gt;                               &lt;span class=&#34;comment&#34;&gt;# 监听地址&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;port:&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;6742&lt;/span&gt;                                  &lt;span class=&#34;comment&#34;&gt;# SDK 端口&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;auto_start:&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;true&lt;/span&gt;                            &lt;span class=&#34;comment&#34;&gt;# 会话启动时自动启动网关&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;whitelist:&lt;/span&gt;                                   &lt;span class=&#34;comment&#34;&gt;# 白名单用户（为空则拒绝所有）&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;bullet&#34;&gt;-&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;telegram:123456789&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;bullet&#34;&gt;-&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;discord:user@example.com&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# ============ 记忆配置 ============&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attr&#34;&gt;memory:&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;engine:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;builtin&lt;/span&gt;                             &lt;span class=&#34;comment&#34;&gt;# builtin | honcho | qdrant&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;auto_summarize:&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;true&lt;/span&gt;                        &lt;span class=&#34;comment&#34;&gt;# 自动摘要旧会话&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;retention_days:&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;90&lt;/span&gt;                          &lt;span class=&#34;comment&#34;&gt;# 会话保留天数&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;user_profile:&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;true&lt;/span&gt;                          &lt;span class=&#34;comment&#34;&gt;# 启用用户画像&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;profile_depth:&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;                            &lt;span class=&#34;comment&#34;&gt;# 画像分析深度 (1-5)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# ============ 技能系统 ============&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attr&#34;&gt;skills:&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;auto_create:&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;true&lt;/span&gt;                           &lt;span class=&#34;comment&#34;&gt;# 代理自主创建技能&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;hub:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;https://agentskills.io&lt;/span&gt;                 &lt;span class=&#34;comment&#34;&gt;# 技能市场地址&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;local_dir:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;~/.hermes/skills&lt;/span&gt;                &lt;span class=&#34;comment&#34;&gt;# 本地技能存放目录&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# ============ 安全策略 ============&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attr&#34;&gt;security:&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;approval_required:&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;true&lt;/span&gt;                     &lt;span class=&#34;comment&#34;&gt;# 高危命令需审批&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;sandbox:&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;false&lt;/span&gt;                              &lt;span class=&#34;comment&#34;&gt;# 强制沙箱执行&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;allowed_commands:&lt;/span&gt;                           &lt;span class=&#34;comment&#34;&gt;# 命令白名单&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;bullet&#34;&gt;-&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;git&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;bullet&#34;&gt;-&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;npm&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;bullet&#34;&gt;-&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;python3&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;blocked_commands:&lt;/span&gt;                           &lt;span class=&#34;comment&#34;&gt;# 命令黑名单&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;bullet&#34;&gt;-&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;rm&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;-rf&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;/&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;bullet&#34;&gt;-&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;dd&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;rate_limit:&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;30&lt;/span&gt;                              &lt;span class=&#34;comment&#34;&gt;# 每分钟最大命令数&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# ============ 定时任务 ============&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attr&#34;&gt;scheduler:&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;enabled:&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;true&lt;/span&gt;                               &lt;span class=&#34;comment&#34;&gt;# 启用 Cron 调度&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;timezone:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;Asia/Shanghai&lt;/span&gt;                     &lt;span class=&#34;comment&#34;&gt;# 时区&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;max_concurrent:&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;                           &lt;span class=&#34;comment&#34;&gt;# 最大并行任务数&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# ============ 日志与调试 ============&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attr&#34;&gt;logging:&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;level:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;info&lt;/span&gt;                                 &lt;span class=&#34;comment&#34;&gt;# debug | info | warn | error&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;file:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;~/.hermes/logs/hermes.log&lt;/span&gt;            &lt;span class=&#34;comment&#34;&gt;# 日志文件路径&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;max_size:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;50MB&lt;/span&gt;                              &lt;span class=&#34;comment&#34;&gt;# 日志轮转大小&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h3 id=&#34;1-2-配置生效顺序&#34;&gt;&lt;a href=&#34;#1-2-配置生效顺序&#34; class=&#34;headerlink&#34; title=&#34;1.2 配置生效顺序&#34;&gt;&lt;/a&gt;1.2 配置生效顺序&lt;/h3&gt;&lt;figure class=&#34;highlight plaintext&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;flowchart LR&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    A[默认值] --&amp;gt; B[config.yaml]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    B --&amp;gt; C[CLI 参数]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    C --&amp;gt; D[会话内 /model 命令]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    D --&amp;gt; E[最终配置]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    A -.- F[&amp;quot;最低安全配置&amp;quot;]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    B -.- G[&amp;quot;用户偏好&amp;quot;]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    C -.- H[&amp;quot;临时覆盖&amp;quot;]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    D -.- I[&amp;quot;实时切换&amp;quot;]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    style E fill:#7C3AED,color:#fff&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    style I fill:#F59E0B,color:#000&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;即：&lt;strong&gt;会话内 &lt;code&gt;/model&lt;/code&gt; → CLI 参数 → config.yaml → 硬编码默认值&lt;/strong&gt;，优先级从高到低。&lt;/p&gt;
&lt;h3 id=&#34;1-3-env-密钥管理&#34;&gt;&lt;a href=&#34;#1-3-env-密钥管理&#34; class=&#34;headerlink&#34; title=&#34;1.3 .env 密钥管理&#34;&gt;&lt;/a&gt;1.3 .env 密钥管理&lt;/h3&gt;&lt;p&gt;所有 API Key 统一存放在 &lt;code&gt;~/.hermes/.env&lt;/code&gt;：&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 模型提供商&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;ANTHROPIC_API_KEY=sk-ant-xxxxxxxxxxxx&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;OPENAI_API_KEY=sk-proj-xxxxxxxxxxxx&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;DEEPSEEK_API_KEY=sk-xxxxxxxxxxxx&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;OPENROUTER_API_KEY=sk-or-xxxxxxxxxxxx&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;GOOGLE_API_KEY=AIzaxxxxxxxxxxxx&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;GROQ_API_KEY=gsk_xxxxxxxxxxxx&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;XAI_API_KEY=xai-xxxxxxxxxxxx&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;MISTRAL_API_KEY=xxxxxxxxxxxx&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 消息平台&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;TELEGRAM_BOT_TOKEN=123456:ABC-DEF1234&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;DISCORD_BOT_TOKEN=MTE4Mzxxxxxxxxx&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;SLACK_BOT_TOKEN=xoxb-xxxxxxxxx&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;FEISHU_APP_ID=cli_xxxxxxxxx&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;FEISHU_APP_SECRET=xxxxxxxxx&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 其他服务&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 你可以在这里添加任意自定义密钥&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;blockquote&gt;
&lt;p&gt;⚠️ &lt;strong&gt;安全提醒&lt;/strong&gt;：&lt;code&gt;.env&lt;/code&gt; 文件权限自动设为 &lt;code&gt;600&lt;/code&gt;（仅所有者可读写），永远不要将这个文件提交到 Git。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;hr&gt;
&lt;h2 id=&#34;2-多模型策略&#34;&gt;&lt;a href=&#34;#2-多模型策略&#34; class=&#34;headerlink&#34; title=&#34;2. 多模型策略&#34;&gt;&lt;/a&gt;2. 多模型策略&lt;/h2&gt;&lt;h3 id=&#34;2-1-按任务类型路由&#34;&gt;&lt;a href=&#34;#2-1-按任务类型路由&#34; class=&#34;headerlink&#34; title=&#34;2.1 按任务类型路由&#34;&gt;&lt;/a&gt;2.1 按任务类型路由&lt;/h3&gt;&lt;p&gt;通过 Hermes 的&lt;strong&gt;提示词注入&lt;/strong&gt;能力，你可以让不同模型处理不同类型的任务：&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 编码类任务 → DeepSeek Coder&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;hermes -m deepseek/deepseek-coder &lt;span class=&#34;string&#34;&gt;&amp;quot;用 Python 写一个快速排序&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 创意类任务 → Claude Sonnet&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;hermes -m anthropic/claude-sonnet-4 &lt;span class=&#34;string&#34;&gt;&amp;quot;写一首关于代码的诗&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 快速回答 → GPT-4o-mini&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;hermes -m openai/gpt-4o-mini &lt;span class=&#34;string&#34;&gt;&amp;quot;今天天气怎么样？&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h3 id=&#34;2-2-模型回退链&#34;&gt;&lt;a href=&#34;#2-2-模型回退链&#34; class=&#34;headerlink&#34; title=&#34;2.2 模型回退链&#34;&gt;&lt;/a&gt;2.2 模型回退链&lt;/h3&gt;&lt;p&gt;当主模型限流或不可用时，Hermes 自动按 &lt;code&gt;fallback_models&lt;/code&gt; 列表降级：&lt;/p&gt;
&lt;figure class=&#34;highlight text&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;主模型: Claude Sonnet 4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  ↓ 限流/超时&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;回退 1: Claude Haiku 3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  ↓ 仍不可用&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;回退 2: GPT-4o-mini&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  ↓ 还不行&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;回退 3: Llama 4 Scout（OpenRouter）&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;每种回退触发都会记录日志，你可以后续查看并调整提供商配额。&lt;/p&gt;
&lt;h3 id=&#34;2-3-自定义模型端点&#34;&gt;&lt;a href=&#34;#2-3-自定义模型端点&#34; class=&#34;headerlink&#34; title=&#34;2.3 自定义模型端点&#34;&gt;&lt;/a&gt;2.3 自定义模型端点&lt;/h3&gt;&lt;p&gt;想用本地部署的模型（Ollama &amp;#x2F; VLLM &amp;#x2F; LM Studio）？配置自定义提供商：&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;hermes config &lt;span class=&#34;built_in&#34;&gt;set&lt;/span&gt; CUSTOM_LLAMA_BASE_URL http://localhost:11434/v1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;hermes config &lt;span class=&#34;built_in&#34;&gt;set&lt;/span&gt; CUSTOM_LLAMA_MODEL llama3.1:70b&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;然后在 &lt;code&gt;.env&lt;/code&gt; 中添加：&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 不需要额外 Key（本地模型）&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;CUSTOM_LLAMA_API_KEY=not-needed&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;之后就可以用 &lt;code&gt;custom-llama/llama3.1:70b&lt;/code&gt; 来调用。&lt;/p&gt;
&lt;hr&gt;
&lt;h2 id=&#34;3-记忆系统深度配置&#34;&gt;&lt;a href=&#34;#3-记忆系统深度配置&#34; class=&#34;headerlink&#34; title=&#34;3. 记忆系统深度配置&#34;&gt;&lt;/a&gt;3. 记忆系统深度配置&lt;/h2&gt;&lt;h3 id=&#34;3-1-三种记忆引擎对比&#34;&gt;&lt;a href=&#34;#3-1-三种记忆引擎对比&#34; class=&#34;headerlink&#34; title=&#34;3.1 三种记忆引擎对比&#34;&gt;&lt;/a&gt;3.1 三种记忆引擎对比&lt;/h3&gt;&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;引擎&lt;/th&gt;
&lt;th&gt;存储方式&lt;/th&gt;
&lt;th&gt;适用场景&lt;/th&gt;
&lt;th&gt;查询能力&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;builtin&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;文件系统（Markdown）&lt;/td&gt;
&lt;td&gt;单机、个人使用&lt;/td&gt;
&lt;td&gt;FTS5 全文搜索&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;honcho&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;外部 Honcho 服务&lt;/td&gt;
&lt;td&gt;辩证用户画像&lt;/td&gt;
&lt;td&gt;语义搜索 + 辩证建模&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;qdrant&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Qdrant 向量数据库&lt;/td&gt;
&lt;td&gt;大规模语义检索&lt;/td&gt;
&lt;td&gt;向量相似度搜索&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;p&gt;切换引擎：&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;hermes config &lt;span class=&#34;built_in&#34;&gt;set&lt;/span&gt; memory.engine qdrant&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;hermes config &lt;span class=&#34;built_in&#34;&gt;set&lt;/span&gt; memory.qdrant_url http://localhost:6333&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h3 id=&#34;3-2-记忆调优参数&#34;&gt;&lt;a href=&#34;#3-2-记忆调优参数&#34; class=&#34;headerlink&#34; title=&#34;3.2 记忆调优参数&#34;&gt;&lt;/a&gt;3.2 记忆调优参数&lt;/h3&gt;&lt;figure class=&#34;highlight yaml&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attr&#34;&gt;memory:&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;engine:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;builtin&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;comment&#34;&gt;# —— 自动摘要 ——&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;auto_summarize:&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;true&lt;/span&gt;          &lt;span class=&#34;comment&#34;&gt;# 每次会话结束时自动生成摘要&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;summary_model:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;openai/gpt-4o-mini&lt;/span&gt;  &lt;span class=&#34;comment&#34;&gt;# 专门用于摘要的轻量模型&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;summary_length:&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;300&lt;/span&gt;           &lt;span class=&#34;comment&#34;&gt;# 摘要最大字数&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;comment&#34;&gt;# —— 记忆持久化 ——&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;retention_days:&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;90&lt;/span&gt;            &lt;span class=&#34;comment&#34;&gt;# 超过 90 天自动归档&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;archive_after:&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;30&lt;/span&gt;             &lt;span class=&#34;comment&#34;&gt;# 30 天后转为归档（不在活跃搜索中）&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;comment&#34;&gt;# —— 用户画像 ——&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;user_profile:&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;true&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;profile_depth:&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;              &lt;span class=&#34;comment&#34;&gt;# 1=基础事实，3=深度习惯与偏好，5=行为预测&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;profile_interval:&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;7&lt;/span&gt;           &lt;span class=&#34;comment&#34;&gt;# 每 7 天更新一次用户画像&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;comment&#34;&gt;# —— 回想要点 ——&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;recall_max_results:&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;5&lt;/span&gt;         &lt;span class=&#34;comment&#34;&gt;# 每次搜索返回最多 5 条结果&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;recall_min_score:&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;0.6&lt;/span&gt;         &lt;span class=&#34;comment&#34;&gt;# 相似度阈值&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h3 id=&#34;3-3-记忆维护操作&#34;&gt;&lt;a href=&#34;#3-3-记忆维护操作&#34; class=&#34;headerlink&#34; title=&#34;3.3 记忆维护操作&#34;&gt;&lt;/a&gt;3.3 记忆维护操作&lt;/h3&gt;&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 手动触发记忆维护&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;hermes memory vacuum                   &lt;span class=&#34;comment&#34;&gt;# 清理过期记忆&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;hermes memory summarize --all          &lt;span class=&#34;comment&#34;&gt;# 为所有旧会话生成摘要&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;hermes memory rebuild --engine qdrant  &lt;span class=&#34;comment&#34;&gt;# 重建向量索引&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 查看记忆状态&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;hermes memory stats                    &lt;span class=&#34;comment&#34;&gt;# 查看记忆规模&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;hermes memory search &lt;span class=&#34;string&#34;&gt;&amp;quot;数据库设计&amp;quot;&lt;/span&gt;      &lt;span class=&#34;comment&#34;&gt;# 搜索记忆&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 直接编辑&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;hermes memory edit MEMORY.md           &lt;span class=&#34;comment&#34;&gt;# 在编辑器中打开记忆文件&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;hr&gt;
&lt;h2 id=&#34;4-自定义技能开发&#34;&gt;&lt;a href=&#34;#4-自定义技能开发&#34; class=&#34;headerlink&#34; title=&#34;4. 自定义技能开发&#34;&gt;&lt;/a&gt;4. 自定义技能开发&lt;/h2&gt;&lt;p&gt;这是 Hermes Agent 最强大的能力之一——你可以&lt;strong&gt;教它做任何事&lt;/strong&gt;，而且它会自己记住。&lt;/p&gt;
&lt;h3 id=&#34;4-1-技能结构&#34;&gt;&lt;a href=&#34;#4-1-技能结构&#34; class=&#34;headerlink&#34; title=&#34;4.1 技能结构&#34;&gt;&lt;/a&gt;4.1 技能结构&lt;/h3&gt;&lt;p&gt;每个技能是一个包含 &lt;code&gt;SKILL.md&lt;/code&gt; 的目录：&lt;/p&gt;
&lt;figure class=&#34;highlight text&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;~/.hermes/skills/&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── database-admin/&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── SKILL.md              # 技能描述 + 使用说明（必须）&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── init.sh                # 初始化脚本（可选）&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   └── assets/                # 资源文件（可选）&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── my-custom-deploy/&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   └── SKILL.md&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;└── weather-reporter/&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    └── SKILL.md&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h3 id=&#34;4-2-编写-SKILL-md&#34;&gt;&lt;a href=&#34;#4-2-编写-SKILL-md&#34; class=&#34;headerlink&#34; title=&#34;4.2 编写 SKILL.md&#34;&gt;&lt;/a&gt;4.2 编写 SKILL.md&lt;/h3&gt;&lt;figure class=&#34;highlight markdown&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;---&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;name: database-admin&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;description: MySQL/PostgreSQL 数据库管理和维护&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;author: 沉鱼&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;version: 1.0.0&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;triggers:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;bullet&#34;&gt;  -&lt;/span&gt; pattern: &amp;quot;备份数据库&amp;quot;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;code&#34;&gt;    action: run_backup&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;code&#34;&gt;  - pattern: &amp;quot;查看表结构&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;code&#34;&gt;    action: describe_table&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;code&#34;&gt;---&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;code&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;section&#34;&gt;## 使用说明&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;section&#34;&gt;### 查询&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;code&#34;&gt;```sql&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;code&#34;&gt;-- 在对话中直接说&amp;quot;查一下用户表的数据&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;code&#34;&gt;SELECT * FROM users LIMIT 10;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h3 id=&#34;数据库备份&#34;&gt;&lt;a href=&#34;#数据库备份&#34; class=&#34;headerlink&#34; title=&#34;数据库备份&#34;&gt;&lt;/a&gt;数据库备份&lt;/h3&gt;&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 说&amp;quot;备份生产数据库到 S3&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 自动执行:&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;pg_dump -h &lt;span class=&#34;variable&#34;&gt;$DB_HOST&lt;/span&gt; -U &lt;span class=&#34;variable&#34;&gt;$DB_USER&lt;/span&gt; -d &lt;span class=&#34;variable&#34;&gt;$DB_NAME&lt;/span&gt; | gzip | \&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  aws s3 &lt;span class=&#34;built_in&#34;&gt;cp&lt;/span&gt; - s3://my-backups/db-$(&lt;span class=&#34;built_in&#34;&gt;date&lt;/span&gt; +%Y%m%d).sql.gz&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h3 id=&#34;安全约束&#34;&gt;&lt;a href=&#34;#安全约束&#34; class=&#34;headerlink&#34; title=&#34;安全约束&#34;&gt;&lt;/a&gt;安全约束&lt;/h3&gt;&lt;ol&gt;
&lt;li&gt;永远不要在 &lt;code&gt;production&lt;/code&gt; 环境执行 &lt;code&gt;DROP TABLE&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;写操作前必须要求用户确认&lt;/li&gt;
&lt;li&gt;连接字符串从 &lt;code&gt;.env&lt;/code&gt; 读取，不硬编码&lt;/li&gt;
&lt;/ol&gt;
&lt;h2 id=&#34;配置&#34;&gt;&lt;a href=&#34;#配置&#34; class=&#34;headerlink&#34; title=&#34;配置&#34;&gt;&lt;/a&gt;配置&lt;/h2&gt;&lt;p&gt;需要以下环境变量：&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;DB_HOST=localhost&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;DB_PORT=5432&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;DB_USER=admin&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;DB_PASSWORD=***    &lt;span class=&#34;comment&#34;&gt;# 存放在 .env&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;figure class=&#34;highlight clean&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;### &lt;span class=&#34;number&#34;&gt;4.3&lt;/span&gt; 技能注册&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;技能写好之后，重新加载即可自动注册为斜杠命令：&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;```bash&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;hermes skills reload                    # 重载所有本地技能&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;hermes skills list                      # 确认已注册&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight jboss-cli&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;📦 已安装技能 &lt;span class=&#34;params&#34;&gt;(8)&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;string&#34;&gt;/database-admin&lt;/span&gt;      数据库管理         v1.0  沉鱼&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;string&#34;&gt;/gif-search&lt;/span&gt;          GIF 搜索           v2.1  openai&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;string&#34;&gt;/github-pr&lt;/span&gt;           PR 工作流          v1.3  community&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;string&#34;&gt;/weather&lt;/span&gt;            天气预报            v0.9  official&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;string&#34;&gt;...&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h3 id=&#34;4-4-技能版本控制&#34;&gt;&lt;a href=&#34;#4-4-技能版本控制&#34; class=&#34;headerlink&#34; title=&#34;4.4 技能版本控制&#34;&gt;&lt;/a&gt;4.4 技能版本控制&lt;/h3&gt;&lt;p&gt;建议将技能目录纳入 Git 管理：&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;cd&lt;/span&gt; ~/.hermes/skills&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;git init&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;git add my-custom-deploy/&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;git commit -m &lt;span class=&#34;string&#34;&gt;&amp;quot;feat: 添加自动部署技能 v1.0&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;git tag v1.0.0&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;Hermes 会自动检测技能版本并将其记录在 &lt;code&gt;hermes skills list&lt;/code&gt; 中。&lt;/p&gt;
&lt;h3 id=&#34;4-5-从代理学习创建技能&#34;&gt;&lt;a href=&#34;#4-5-从代理学习创建技能&#34; class=&#34;headerlink&#34; title=&#34;4.5 从代理学习创建技能&#34;&gt;&lt;/a&gt;4.5 从代理学习创建技能&lt;/h3&gt;&lt;p&gt;你也可以让 Hermes &lt;strong&gt;自主创建技能&lt;/strong&gt;——完成一次复杂任务后，它可能会问：&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;“我刚才完成了一个复杂的数据库迁移任务。是否要将其保存为可复用的技能？”&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;回答”是”后，Hermes 会自动生成 &lt;code&gt;SKILL.md&lt;/code&gt;，未来的类似任务可以直接调用。&lt;/p&gt;
&lt;figure class=&#34;highlight plaintext&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;sequenceDiagram&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    participant 用户&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    participant Hermes&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    participant 技能系统&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    用户-&amp;gt;&amp;gt;Hermes: &amp;quot;把生产数据库迁移到新服务器&amp;quot;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    Hermes-&amp;gt;&amp;gt;Hermes: 执行迁移步骤&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    Hermes-&amp;gt;&amp;gt;Hermes: 分析复杂度和可复用性&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    Hermes-&amp;gt;&amp;gt;用户: &amp;quot;此操作共执行了 12 个步骤。是否保存为技能？&amp;quot;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    用户-&amp;gt;&amp;gt;Hermes: &amp;quot;保存&amp;quot;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    Hermes-&amp;gt;&amp;gt;技能系统: 生成 migration-db SKILL.md&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    技能系统--&amp;gt;&amp;gt;Hermes: 注册 /migration-db&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    Note over Hermes,技能系统: 下次只需说&amp;quot;做数据库迁移&amp;quot;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    Hermes-&amp;gt;&amp;gt;用户: &amp;quot;好的，立即执行 /migration-db&amp;quot;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;hr&gt;
&lt;h2 id=&#34;5-多代理协作&#34;&gt;&lt;a href=&#34;#5-多代理协作&#34; class=&#34;headerlink&#34; title=&#34;5. 多代理协作&#34;&gt;&lt;/a&gt;5. 多代理协作&lt;/h2&gt;&lt;h3 id=&#34;5-1-子代理（Sub-Agents）&#34;&gt;&lt;a href=&#34;#5-1-子代理（Sub-Agents）&#34; class=&#34;headerlink&#34; title=&#34;5.1 子代理（Sub-Agents）&#34;&gt;&lt;/a&gt;5.1 子代理（Sub-Agents）&lt;/h3&gt;&lt;p&gt;Hermes 可以派生多个&lt;strong&gt;孤立子代理&lt;/strong&gt;并行处理任务：&lt;/p&gt;
&lt;figure class=&#34;highlight text&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;你: &amp;quot;帮我做三件事：&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;     1. 分析这个 API 的性能瓶颈&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;     2. 写一份新功能的原型代码&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;     3. 起草一封给客户的邮件&amp;quot;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;Hermes: &amp;quot;好的，我并行处理这三件事：&amp;quot;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;figure class=&#34;highlight plaintext&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;flowchart TD&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    P[主代理：协调] --&amp;gt; A[子代理 1：性能分析]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    P --&amp;gt; B[子代理 2：原型开发]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    P --&amp;gt; C[子代理 3：邮件起草]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    A --&amp;gt; R1[分析报告]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    B --&amp;gt; R2[原型代码]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    C --&amp;gt; R3[邮件草稿]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    R1 &amp;amp; R2 &amp;amp; R3 --&amp;gt; M[主代理合并结果]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    M --&amp;gt; U[呈现给用户]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    style P fill:#7C3AED,color:#fff&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    style A fill:#F59E0B,color:#000&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    style B fill:#F59E0B,color:#000&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    style C fill:#F59E0B,color:#000&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    style M fill:#10B981,color:#fff&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;每个子代理是&lt;strong&gt;完全隔离&lt;/strong&gt;的：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;拥有独立的上下文窗口&lt;/li&gt;
&lt;li&gt;无法访问其他子代理的工作目录&lt;/li&gt;
&lt;li&gt;互不干扰，各自失败不会影响其他任务&lt;/li&gt;
&lt;li&gt;主代理负责合并结果和解决冲突&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;5-2-代理管线（Pipelines）&#34;&gt;&lt;a href=&#34;#5-2-代理管线（Pipelines）&#34; class=&#34;headerlink&#34; title=&#34;5.2 代理管线（Pipelines）&#34;&gt;&lt;/a&gt;5.2 代理管线（Pipelines）&lt;/h3&gt;&lt;p&gt;通过技能组合，你可以构建多步骤自动化管线：&lt;/p&gt;
&lt;figure class=&#34;highlight yaml&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# pipeline: code-review.yml&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attr&#34;&gt;name:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;代码审查管线&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attr&#34;&gt;steps:&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;bullet&#34;&gt;-&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;agent:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;main&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;task:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;运行 lint 检查代码风格&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;bullet&#34;&gt;-&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;agent:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;sub&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;skill:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;security-audit&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;task:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;检查代码中的安全漏洞&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;bullet&#34;&gt;-&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;agent:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;sub&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;skill:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;performance-review&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;task:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;分析性能瓶颈&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;bullet&#34;&gt;-&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;agent:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;main&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;task:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;综合以上结果，输出审查报告&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;执行管线：&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;hermes pipeline run code-review.yml&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h3 id=&#34;5-3-后台任务&#34;&gt;&lt;a href=&#34;#5-3-后台任务&#34; class=&#34;headerlink&#34; title=&#34;5.3 后台任务&#34;&gt;&lt;/a&gt;5.3 后台任务&lt;/h3&gt;&lt;p&gt;长时间运行的任务可以放入后台：&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;hermes chat&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;gt; /background &lt;span class=&#34;string&#34;&gt;&amp;quot;遍历项目目录，统计各模块代码行数并生成报表&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;任务在后台执行，你可以继续聊天。完成后 Hermes 会通知你。&lt;/p&gt;
&lt;hr&gt;
&lt;h2 id=&#34;6-自定义终端后端&#34;&gt;&lt;a href=&#34;#6-自定义终端后端&#34; class=&#34;headerlink&#34; title=&#34;6. 自定义终端后端&#34;&gt;&lt;/a&gt;6. 自定义终端后端&lt;/h2&gt;&lt;h3 id=&#34;6-1-Docker-后端&#34;&gt;&lt;a href=&#34;#6-1-Docker-后端&#34; class=&#34;headerlink&#34; title=&#34;6.1 Docker 后端&#34;&gt;&lt;/a&gt;6.1 Docker 后端&lt;/h3&gt;&lt;p&gt;最适合安全沙箱：&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;hermes config &lt;span class=&#34;built_in&#34;&gt;set&lt;/span&gt; terminal.backend docker&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;默认镜像 &lt;code&gt;hermes-agent/terminal:latest&lt;/code&gt; 包含：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Python 3.12&lt;/li&gt;
&lt;li&gt;Node.js 22&lt;/li&gt;
&lt;li&gt;Git &amp;#x2F; Curl &amp;#x2F; Wget&lt;/li&gt;
&lt;li&gt;常见开发工具&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;自定义镜像：&lt;/p&gt;
&lt;figure class=&#34;highlight yaml&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# config.yaml&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attr&#34;&gt;terminal:&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;backend:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;docker&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;docker:&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;image:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;my-custom-image:latest&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;volumes:&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;span class=&#34;bullet&#34;&gt;-&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;/data:/data:ro&lt;/span&gt;               &lt;span class=&#34;comment&#34;&gt;# 只读挂载&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;span class=&#34;bullet&#34;&gt;-&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;~/.ssh:/home/hermes/.ssh:ro&lt;/span&gt;  &lt;span class=&#34;comment&#34;&gt;# SSH 密钥&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;network:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;bridge&lt;/span&gt;                   &lt;span class=&#34;comment&#34;&gt;# bridge | none | host&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;memory_limit:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;4g&lt;/span&gt;                  &lt;span class=&#34;comment&#34;&gt;# 内存限制&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;cpu_limit:&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;                      &lt;span class=&#34;comment&#34;&gt;# CPU 核心数&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h3 id=&#34;6-2-SSH-后端&#34;&gt;&lt;a href=&#34;#6-2-SSH-后端&#34; class=&#34;headerlink&#34; title=&#34;6.2 SSH 后端&#34;&gt;&lt;/a&gt;6.2 SSH 后端&lt;/h3&gt;&lt;p&gt;远程服务器执行：&lt;/p&gt;
&lt;figure class=&#34;highlight yaml&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attr&#34;&gt;terminal:&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;backend:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;ssh&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;ssh:&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;host:&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;192.168&lt;/span&gt;&lt;span class=&#34;number&#34;&gt;.1&lt;/span&gt;&lt;span class=&#34;number&#34;&gt;.100&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;port:&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;22&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;user:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;hermes&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;key:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;~/.ssh/hermes_ed25519&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;work_dir:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;/home/hermes/workspace&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;blockquote&gt;
&lt;p&gt;建议为 Hermes 创建一个&lt;strong&gt;专用 Linux 用户&lt;/strong&gt;，限制其权限。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h3 id=&#34;6-3-Daytona-云后端&#34;&gt;&lt;a href=&#34;#6-3-Daytona-云后端&#34; class=&#34;headerlink&#34; title=&#34;6.3 Daytona 云后端&#34;&gt;&lt;/a&gt;6.3 Daytona 云后端&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;按需启动、闲置休眠&lt;/strong&gt;，近乎零成本：&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;hermes config &lt;span class=&#34;built_in&#34;&gt;set&lt;/span&gt; terminal.backend daytona&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;hermes config &lt;span class=&#34;built_in&#34;&gt;set&lt;/span&gt; DAYTONA_API_KEY dtn_xxxxx&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;Daytona 会自动：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;首次执行时创建工作空间&lt;/li&gt;
&lt;li&gt;执行完成后保留状态&lt;/li&gt;
&lt;li&gt;闲置 15 分钟后休眠&lt;/li&gt;
&lt;li&gt;下次命令时秒级唤醒&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;6-4-后端切换策略&#34;&gt;&lt;a href=&#34;#6-4-后端切换策略&#34; class=&#34;headerlink&#34; title=&#34;6.4 后端切换策略&#34;&gt;&lt;/a&gt;6.4 后端切换策略&lt;/h3&gt;&lt;figure class=&#34;highlight plaintext&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;flowchart LR&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    subgraph &amp;quot;本地&amp;quot;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        A[local 本地终端]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    end&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    subgraph &amp;quot;安全隔离&amp;quot;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        B[Docker 沙箱]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        C[SSH 远程]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    end&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    subgraph &amp;quot;云上&amp;quot;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        D[Daytona 弹窗]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        E[Modal Serverless]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    end&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    F&amp;#123;任务类型?&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    F --&amp;gt;|&amp;quot;日常查询/文件操作&amp;quot;| A&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    F --&amp;gt;|&amp;quot;危险命令/第三方代码&amp;quot;| B&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    F --&amp;gt;|&amp;quot;访问内网服务器&amp;quot;| C&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    F --&amp;gt;|&amp;quot;重型编译/渲染&amp;quot;| D&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    F --&amp;gt;|&amp;quot;短时批量任务&amp;quot;| E&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    style F fill:#7C3AED,color:#fff&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;hr&gt;
&lt;h2 id=&#34;7-安全强化&#34;&gt;&lt;a href=&#34;#7-安全强化&#34; class=&#34;headerlink&#34; title=&#34;7. 安全强化&#34;&gt;&lt;/a&gt;7. 安全强化&lt;/h2&gt;&lt;h3 id=&#34;7-1-命令审批&#34;&gt;&lt;a href=&#34;#7-1-命令审批&#34; class=&#34;headerlink&#34; title=&#34;7.1 命令审批&#34;&gt;&lt;/a&gt;7.1 命令审批&lt;/h3&gt;&lt;p&gt;对于 &lt;code&gt;production&lt;/code&gt;、&lt;code&gt;DELETE&lt;/code&gt;、&lt;code&gt;DROP&lt;/code&gt; 等高危操作，Hermes 会自动暂停并请求确认：&lt;/p&gt;
&lt;figure class=&#34;highlight text&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;Hermes: &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  即将执行命令: DELETE FROM users WHERE id = 1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  影响范围: production 数据库&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  请确认: [/approve] 继续  |  [/reject] 取消&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h3 id=&#34;7-2-沙箱强制执行&#34;&gt;&lt;a href=&#34;#7-2-沙箱强制执行&#34; class=&#34;headerlink&#34; title=&#34;7.2 沙箱强制执行&#34;&gt;&lt;/a&gt;7.2 沙箱强制执行&lt;/h3&gt;&lt;p&gt;强制所有命令在沙箱中执行：&lt;/p&gt;
&lt;figure class=&#34;highlight yaml&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attr&#34;&gt;security:&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;sandbox:&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;true&lt;/span&gt;                &lt;span class=&#34;comment&#34;&gt;# 全局强制沙箱&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;sandbox_backend:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;docker&lt;/span&gt;      &lt;span class=&#34;comment&#34;&gt;# 使用 Docker 作沙箱&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;sandbox_image:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;hermes-sandbox:latest&lt;/span&gt;  &lt;span class=&#34;comment&#34;&gt;# 最小化镜像（无网络工具）&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h3 id=&#34;7-3-精细权限控制&#34;&gt;&lt;a href=&#34;#7-3-精细权限控制&#34; class=&#34;headerlink&#34; title=&#34;7.3 精细权限控制&#34;&gt;&lt;/a&gt;7.3 精细权限控制&lt;/h3&gt;&lt;figure class=&#34;highlight yaml&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attr&#34;&gt;security:&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;comment&#34;&gt;# 按路径限制&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;allowed_paths:&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;bullet&#34;&gt;-&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;/home/user/projects&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;bullet&#34;&gt;-&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;/tmp/hermes&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;blocked_paths:&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;bullet&#34;&gt;-&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;/etc&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;bullet&#34;&gt;-&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;/var/log&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;comment&#34;&gt;# 按命令限制&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;command_rules:&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;bullet&#34;&gt;-&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;pattern:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;rm&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;span class=&#34;attr&#34;&gt;require_approval:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;always&lt;/span&gt;   &lt;span class=&#34;comment&#34;&gt;# 所有 rm 命令都要审批&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;bullet&#34;&gt;-&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;pattern:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;git push&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;span class=&#34;attr&#34;&gt;require_approval:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;on-diff&lt;/span&gt;  &lt;span class=&#34;comment&#34;&gt;# git push 在非 master 分支时自动审批&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;bullet&#34;&gt;-&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;pattern:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;curl&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;span class=&#34;attr&#34;&gt;blocked:&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;true&lt;/span&gt;              &lt;span class=&#34;comment&#34;&gt;# 禁止 curl&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;comment&#34;&gt;# 用户白名单&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;whitelist:&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;bullet&#34;&gt;-&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;telegram:123456789&lt;/span&gt;         &lt;span class=&#34;comment&#34;&gt;# 只允许此用户&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h3 id=&#34;7-4-审计日志&#34;&gt;&lt;a href=&#34;#7-4-审计日志&#34; class=&#34;headerlink&#34; title=&#34;7.4 审计日志&#34;&gt;&lt;/a&gt;7.4 审计日志&lt;/h3&gt;&lt;p&gt;所有命令执行记录在日志中：&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;hermes logs --filter &lt;span class=&#34;built_in&#34;&gt;command&lt;/span&gt; --level info --last 50&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出示例：&lt;/p&gt;
&lt;figure class=&#34;highlight routeros&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;2026-05-07 10:15:23 [COMMAND] &lt;span class=&#34;attribute&#34;&gt;user&lt;/span&gt;=telegram:123456789 &lt;span class=&#34;attribute&#34;&gt;cmd&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;git status&amp;quot;&lt;/span&gt; &lt;span class=&#34;attribute&#34;&gt;status&lt;/span&gt;=ok &lt;span class=&#34;attribute&#34;&gt;cwd&lt;/span&gt;=/projects/blog&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2026-05-07 10:15:30 [COMMAND] &lt;span class=&#34;attribute&#34;&gt;user&lt;/span&gt;=telegram:123456789 &lt;span class=&#34;attribute&#34;&gt;cmd&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;rm -rf node_modules&amp;quot;&lt;/span&gt; &lt;span class=&#34;attribute&#34;&gt;status&lt;/span&gt;=approved &lt;span class=&#34;attribute&#34;&gt;cwd&lt;/span&gt;=/projects/blog&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2026-05-07 10:16:01 [SECURITY] &lt;span class=&#34;attribute&#34;&gt;user&lt;/span&gt;=discord:98765 blocked: &lt;span class=&#34;attribute&#34;&gt;cmd&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;curl http://malicious.site&amp;quot;&lt;/span&gt; &lt;span class=&#34;attribute&#34;&gt;reason&lt;/span&gt;=blocked_command&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;hr&gt;
&lt;h2 id=&#34;8-网关与多平台高级配置&#34;&gt;&lt;a href=&#34;#8-网关与多平台高级配置&#34; class=&#34;headerlink&#34; title=&#34;8. 网关与多平台高级配置&#34;&gt;&lt;/a&gt;8. 网关与多平台高级配置&lt;/h2&gt;&lt;h3 id=&#34;8-1-网关高可用&#34;&gt;&lt;a href=&#34;#8-1-网关高可用&#34; class=&#34;headerlink&#34; title=&#34;8.1 网关高可用&#34;&gt;&lt;/a&gt;8.1 网关高可用&lt;/h3&gt;&lt;figure class=&#34;highlight yaml&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attr&#34;&gt;gateway:&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;host:&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;0.0&lt;/span&gt;&lt;span class=&#34;number&#34;&gt;.0&lt;/span&gt;&lt;span class=&#34;number&#34;&gt;.0&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;port:&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;6742&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;comment&#34;&gt;# TLS 加密&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;tls:&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;enable:&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;true&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;cert:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;/etc/hermes/cert.pem&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;key:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;/etc/hermes/key.pem&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;comment&#34;&gt;# 反向代理友好&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;trust_proxy:&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;true&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;proxy_headers:&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;bullet&#34;&gt;-&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;X-Forwarded-For&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;bullet&#34;&gt;-&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;X-Real-IP&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h3 id=&#34;8-2-平台路由&#34;&gt;&lt;a href=&#34;#8-2-平台路由&#34; class=&#34;headerlink&#34; title=&#34;8.2 平台路由&#34;&gt;&lt;/a&gt;8.2 平台路由&lt;/h3&gt;&lt;p&gt;不同平台 -&amp;gt; 不同行为：&lt;/p&gt;
&lt;figure class=&#34;highlight yaml&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attr&#34;&gt;gateway:&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;platforms:&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;telegram:&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;span class=&#34;attr&#34;&gt;allow_commands:&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;true&lt;/span&gt;        &lt;span class=&#34;comment&#34;&gt;# Telegram 允许执行命令&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;span class=&#34;attr&#34;&gt;max_context:&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;100000&lt;/span&gt;         &lt;span class=&#34;comment&#34;&gt;# 减少 token 消耗&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;span class=&#34;attr&#34;&gt;greeting:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;你好！我是你的 AI 助手&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;discord:&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;span class=&#34;attr&#34;&gt;allow_commands:&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;false&lt;/span&gt;       &lt;span class=&#34;comment&#34;&gt;# Discord 只允许对话&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;span class=&#34;attr&#34;&gt;thread_only:&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;true&lt;/span&gt;           &lt;span class=&#34;comment&#34;&gt;# 仅在线程中回复&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;email:&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;span class=&#34;attr&#34;&gt;max_reply_length:&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;500&lt;/span&gt;       &lt;span class=&#34;comment&#34;&gt;# 邮件回复不超过 500 字&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;span class=&#34;attr&#34;&gt;signature:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;\n--\n沉鱼的 AI 助手&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h3 id=&#34;8-3-系统服务管理&#34;&gt;&lt;a href=&#34;#8-3-系统服务管理&#34; class=&#34;headerlink&#34; title=&#34;8.3 系统服务管理&#34;&gt;&lt;/a&gt;8.3 系统服务管理&lt;/h3&gt;&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 安装为系统服务&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;hermes gateway install              &lt;span class=&#34;comment&#34;&gt;# systemd / launchd / NSSM（Windows）&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 日常管理&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;hermes gateway start&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;hermes gateway stop&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;hermes gateway restart&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;hermes gateway status               &lt;span class=&#34;comment&#34;&gt;# 查看运行状态和平台连接数&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;hr&gt;
&lt;h2 id=&#34;9-定时任务编排&#34;&gt;&lt;a href=&#34;#9-定时任务编排&#34; class=&#34;headerlink&#34; title=&#34;9. 定时任务编排&#34;&gt;&lt;/a&gt;9. 定时任务编排&lt;/h2&gt;&lt;h3 id=&#34;9-1-高级-Cron-配置&#34;&gt;&lt;a href=&#34;#9-1-高级-Cron-配置&#34; class=&#34;headerlink&#34; title=&#34;9.1 高级 Cron 配置&#34;&gt;&lt;/a&gt;9.1 高级 Cron 配置&lt;/h3&gt;&lt;figure class=&#34;highlight yaml&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attr&#34;&gt;scheduler:&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;jobs:&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;bullet&#34;&gt;-&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;name:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;每日博客备份&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;span class=&#34;attr&#34;&gt;schedule:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;0 3 * * *&amp;quot;&lt;/span&gt;            &lt;span class=&#34;comment&#34;&gt;# 每天凌晨 3 点&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;span class=&#34;attr&#34;&gt;task:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;备份 /data/blog 到 S3&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;span class=&#34;attr&#34;&gt;platform:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;telegram&lt;/span&gt;                &lt;span class=&#34;comment&#34;&gt;# 完成后通过 Telegram 通知&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;span class=&#34;attr&#34;&gt;timeout:&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;600&lt;/span&gt;                      &lt;span class=&#34;comment&#34;&gt;# 超时 10 分钟&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;span class=&#34;attr&#34;&gt;retry:&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;                          &lt;span class=&#34;comment&#34;&gt;# 失败重试 3 次&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;bullet&#34;&gt;-&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;name:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;每周性能报告&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;span class=&#34;attr&#34;&gt;schedule:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;0 9 * * 1&amp;quot;&lt;/span&gt;            &lt;span class=&#34;comment&#34;&gt;# 每周一上午 9 点&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;span class=&#34;attr&#34;&gt;task:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;检查服务器磁盘、CPU、内存使用率并生成报告&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;span class=&#34;attr&#34;&gt;platform:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;email&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;span class=&#34;attr&#34;&gt;to:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;admin@example.com&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;bullet&#34;&gt;-&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;name:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;GitHub 每日动态&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;span class=&#34;attr&#34;&gt;schedule:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;0 8 * * *&amp;quot;&lt;/span&gt;            &lt;span class=&#34;comment&#34;&gt;# 每天早上 8 点&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;span class=&#34;attr&#34;&gt;task:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;查看我仓库的 Issues / PR 状态，汇总给我&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;span class=&#34;attr&#34;&gt;platform:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;discord&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h3 id=&#34;9-2-自然语言设定&#34;&gt;&lt;a href=&#34;#9-2-自然语言设定&#34; class=&#34;headerlink&#34; title=&#34;9.2 自然语言设定&#34;&gt;&lt;/a&gt;9.2 自然语言设定&lt;/h3&gt;&lt;p&gt;直接在对话中说：&lt;/p&gt;
&lt;figure class=&#34;highlight dts&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;symbol&#34;&gt;Hermes:&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt; 用户: &lt;span class=&#34;string&#34;&gt;&amp;quot;帮我设个定时任务，每天晚上 10 点检查服务器磁盘使用率，超过 80% 就通知我&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;symbol&#34;&gt; Hermes:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;已创建定时任务。每天 22:00 检查磁盘使用率，&amp;gt;80% 时通过当前平台通知你。&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h3 id=&#34;9-3-任务管理命令&#34;&gt;&lt;a href=&#34;#9-3-任务管理命令&#34; class=&#34;headerlink&#34; title=&#34;9.3 任务管理命令&#34;&gt;&lt;/a&gt;9.3 任务管理命令&lt;/h3&gt;&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;hermes cron list              &lt;span class=&#34;comment&#34;&gt;# 查看所有定时任务&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;hermes cron pause backup      &lt;span class=&#34;comment&#34;&gt;# 暂停 backup 任务&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;hermes cron resume backup     &lt;span class=&#34;comment&#34;&gt;# 恢复&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;hermes cron delete backup     &lt;span class=&#34;comment&#34;&gt;# 删除&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;hermes cron run backup --now  &lt;span class=&#34;comment&#34;&gt;# 立即执行（不等待调度）&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;hr&gt;
&lt;h2 id=&#34;10-性能调优&#34;&gt;&lt;a href=&#34;#10-性能调优&#34; class=&#34;headerlink&#34; title=&#34;10. 性能调优&#34;&gt;&lt;/a&gt;10. 性能调优&lt;/h2&gt;&lt;h3 id=&#34;10-1-上下文压缩策略&#34;&gt;&lt;a href=&#34;#10-1-上下文压缩策略&#34; class=&#34;headerlink&#34; title=&#34;10.1 上下文压缩策略&#34;&gt;&lt;/a&gt;10.1 上下文压缩策略&lt;/h3&gt;&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;策略&lt;/th&gt;
&lt;th&gt;行为&lt;/th&gt;
&lt;th&gt;适用场景&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;&lt;code&gt;auto&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;达到阈值自动压缩&lt;/td&gt;
&lt;td&gt;日常使用&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;manual&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;手动 &lt;code&gt;/compress&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;需要精确控制&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;off&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;从不压缩&lt;/td&gt;
&lt;td&gt;超长上下文模型&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;h3 id=&#34;10-2-响应速度优化&#34;&gt;&lt;a href=&#34;#10-2-响应速度优化&#34; class=&#34;headerlink&#34; title=&#34;10.2 响应速度优化&#34;&gt;&lt;/a&gt;10.2 响应速度优化&lt;/h3&gt;&lt;figure class=&#34;highlight yaml&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 流式输出&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attr&#34;&gt;streaming:&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;true&lt;/span&gt;                          &lt;span class=&#34;comment&#34;&gt;# 逐字输出，减少等待感&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 并行工具调用&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attr&#34;&gt;parallel_tool_calls:&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;true&lt;/span&gt;                &lt;span class=&#34;comment&#34;&gt;# 同时调用多个工具&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 缓存&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attr&#34;&gt;cache:&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;model_responses:&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;true&lt;/span&gt;                  &lt;span class=&#34;comment&#34;&gt;# 缓存相同输入的回复&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;ttl:&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;300&lt;/span&gt;                               &lt;span class=&#34;comment&#34;&gt;# 缓存 5 分钟&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;max_size:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;100MB&lt;/span&gt;                        &lt;span class=&#34;comment&#34;&gt;# 缓存最大 100MB&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h3 id=&#34;10-3-资源配置建议&#34;&gt;&lt;a href=&#34;#10-3-资源配置建议&#34; class=&#34;headerlink&#34; title=&#34;10.3 资源配置建议&#34;&gt;&lt;/a&gt;10.3 资源配置建议&lt;/h3&gt;&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;使用场景&lt;/th&gt;
&lt;th&gt;推荐模型&lt;/th&gt;
&lt;th&gt;上下文&lt;/th&gt;
&lt;th&gt;终端后端&lt;/th&gt;
&lt;th&gt;记忆引擎&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;日常聊天&amp;#x2F;问答&lt;/td&gt;
&lt;td&gt;GPT-4o-mini&lt;/td&gt;
&lt;td&gt;128K&lt;/td&gt;
&lt;td&gt;local&lt;/td&gt;
&lt;td&gt;builtin&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;编码开发&lt;/td&gt;
&lt;td&gt;Claude Sonnet 4&lt;/td&gt;
&lt;td&gt;200K&lt;/td&gt;
&lt;td&gt;local&lt;/td&gt;
&lt;td&gt;builtin&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;重型代码项目&lt;/td&gt;
&lt;td&gt;DeepSeek Coder&lt;/td&gt;
&lt;td&gt;128K&lt;/td&gt;
&lt;td&gt;docker&lt;/td&gt;
&lt;td&gt;qdrant&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;服务器运维&lt;/td&gt;
&lt;td&gt;Claude Haiku 3&lt;/td&gt;
&lt;td&gt;200K&lt;/td&gt;
&lt;td&gt;ssh&lt;/td&gt;
&lt;td&gt;builtin&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;多平台服务&lt;/td&gt;
&lt;td&gt;Claude Sonnet 4&lt;/td&gt;
&lt;td&gt;200K&lt;/td&gt;
&lt;td&gt;daytona&lt;/td&gt;
&lt;td&gt;honcho&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;研究分析&lt;/td&gt;
&lt;td&gt;Gemini 2.5 Pro&lt;/td&gt;
&lt;td&gt;1M&lt;/td&gt;
&lt;td&gt;daytona&lt;/td&gt;
&lt;td&gt;qdrant&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;hr&gt;
&lt;h2 id=&#34;11-常见问题与排查&#34;&gt;&lt;a href=&#34;#11-常见问题与排查&#34; class=&#34;headerlink&#34; title=&#34;11. 常见问题与排查&#34;&gt;&lt;/a&gt;11. 常见问题与排查&lt;/h2&gt;&lt;h3 id=&#34;网关连接失败&#34;&gt;&lt;a href=&#34;#网关连接失败&#34; class=&#34;headerlink&#34; title=&#34;网关连接失败&#34;&gt;&lt;/a&gt;网关连接失败&lt;/h3&gt;&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;hermes doctor                    &lt;span class=&#34;comment&#34;&gt;# 全面诊断&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;hermes gateway status            &lt;span class=&#34;comment&#34;&gt;# 查看网关状态&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;telnet localhost 6742            &lt;span class=&#34;comment&#34;&gt;# 测试端口连通性&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h3 id=&#34;模型限流&#34;&gt;&lt;a href=&#34;#模型限流&#34; class=&#34;headerlink&#34; title=&#34;模型限流&#34;&gt;&lt;/a&gt;模型限流&lt;/h3&gt;&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 检查限流状态&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;hermes model status&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 临时切换模型&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;/model gpt-4o-mini&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 永久切换默认模型&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;hermes config &lt;span class=&#34;built_in&#34;&gt;set&lt;/span&gt; model openrouter/meta-llama/llama-4-scout&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h3 id=&#34;记忆膨胀&#34;&gt;&lt;a href=&#34;#记忆膨胀&#34; class=&#34;headerlink&#34; title=&#34;记忆膨胀&#34;&gt;&lt;/a&gt;记忆膨胀&lt;/h3&gt;&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;hermes memory stats              &lt;span class=&#34;comment&#34;&gt;# 查看记忆大小&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;hermes memory vacuum             &lt;span class=&#34;comment&#34;&gt;# 清理过期记忆&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;hermes memory rebuild            &lt;span class=&#34;comment&#34;&gt;# 重建索引&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h3 id=&#34;日志分析&#34;&gt;&lt;a href=&#34;#日志分析&#34; class=&#34;headerlink&#34; title=&#34;日志分析&#34;&gt;&lt;/a&gt;日志分析&lt;/h3&gt;&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;hermes logs --level warn --since &lt;span class=&#34;string&#34;&gt;&amp;quot;2h ago&amp;quot;&lt;/span&gt;   &lt;span class=&#34;comment&#34;&gt;# 最近 2 小时的警告&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;hermes logs --filter error --&lt;span class=&#34;built_in&#34;&gt;tail&lt;/span&gt; 20        &lt;span class=&#34;comment&#34;&gt;# 最近 20 条错误&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;hr&gt;
&lt;h2 id=&#34;12-总结&#34;&gt;&lt;a href=&#34;#12-总结&#34; class=&#34;headerlink&#34; title=&#34;12. 总结&#34;&gt;&lt;/a&gt;12. 总结&lt;/h2&gt;&lt;p&gt;Hermes Agent 的配置体系非常灵活，进阶使用可以从以下几个方向深入：&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;方向&lt;/th&gt;
&lt;th align=&#34;center&#34;&gt;难度&lt;/th&gt;
&lt;th align=&#34;center&#34;&gt;价值&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;📝 自定义技能开发&lt;/td&gt;
&lt;td align=&#34;center&#34;&gt;⭐⭐⭐&lt;/td&gt;
&lt;td align=&#34;center&#34;&gt;最高——将重复工作自动化&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;🔄 多代理管线&lt;/td&gt;
&lt;td align=&#34;center&#34;&gt;⭐⭐⭐⭐&lt;/td&gt;
&lt;td align=&#34;center&#34;&gt;处理复杂多步骤任务&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;🔧 自定义后端&lt;/td&gt;
&lt;td align=&#34;center&#34;&gt;⭐⭐&lt;/td&gt;
&lt;td align=&#34;center&#34;&gt;安全与性能平衡&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;🔐 安全强化&lt;/td&gt;
&lt;td align=&#34;center&#34;&gt;⭐⭐&lt;/td&gt;
&lt;td align=&#34;center&#34;&gt;生产环境必备&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;⏰ 任务编排&lt;/td&gt;
&lt;td align=&#34;center&#34;&gt;⭐&lt;/td&gt;
&lt;td align=&#34;center&#34;&gt;日常效率倍增器&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;🧠 记忆策略&lt;/td&gt;
&lt;td align=&#34;center&#34;&gt;⭐⭐⭐&lt;/td&gt;
&lt;td align=&#34;center&#34;&gt;长期使用体验质变&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;p&gt;&lt;strong&gt;推荐学习路径：&lt;/strong&gt;&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;✅ 先配置好 &lt;code&gt;config.yaml&lt;/code&gt; 基础项（模型、后端）&lt;/li&gt;
&lt;li&gt;✅ 尝试编写 1-2 个简单技能&lt;/li&gt;
&lt;li&gt;✅ 配置定时任务优化日常流程&lt;/li&gt;
&lt;li&gt;✅ 探索子代理并行任务&lt;/li&gt;
&lt;li&gt;🔜 深入学习记忆策略调优&lt;/li&gt;
&lt;/ol&gt;
&lt;hr&gt;
&lt;h3 id=&#34;延伸阅读&#34;&gt;&lt;a href=&#34;#延伸阅读&#34; class=&#34;headerlink&#34; title=&#34;延伸阅读&#34;&gt;&lt;/a&gt;延伸阅读&lt;/h3&gt;&lt;ul&gt;
&lt;li&gt;&lt;a href=&#34;/Hermes-Agent-%E5%AE%89%E8%A3%85%E4%B8%8E%E4%BD%BF%E7%94%A8%E6%8C%87%E5%8D%97/&#34;&gt;Hermes Agent 安装与使用指南&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&#34;https://hermes-agent.nousresearch.com/docs/&#34;&gt;Hermes Agent 官方文档&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&#34;https://github.com/NousResearch/hermes-agent&#34;&gt;GitHub 仓库&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&#34;https://agentskills.io/&#34;&gt;Skills Hub&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;

 &lt;h2 id=&#34;什么是-Hermes-Agent？&#34;&gt;&lt;a href=&#34;#什么是-Hermes-Agent？&#34; class=&#34;headerlink&#34; title=&#34;什么是 Hermes Agent？&#34;&gt;&lt;/a&gt;什么是 Hermes Agent？&lt;/h2&gt;&lt;p&gt;Hermes Agent 是由 &lt;strong&gt;Nous Research&lt;/strong&gt; 开发的一款&lt;strong&gt;自进化 AI 代理&lt;/strong&gt;。它不只是一个对话机器人——它内置了完整的&lt;strong&gt;学习循环&lt;/strong&gt;：从经验中创建技能、在使用中自我改进、主动持久化知识、搜索自己的过往对话，并在一次次会话中建立越来越深刻的用户画像。&lt;/p&gt;
&lt;figure class=&#34;highlight plaintext&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;flowchart TD&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    A[用户输入] --&amp;gt; B[Hermes Agent 循环]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    B --&amp;gt; C&amp;#123;是否需要新技能?&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    C --&amp;gt;|是| D[自主创建技能]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    C --&amp;gt;|否| E[执行任务]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    D --&amp;gt; E&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    E --&amp;gt; F[经验总结]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    F --&amp;gt; G[知识持久化]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    G --&amp;gt; H[记忆 &amp;amp; 用户画像]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    H --&amp;gt; B&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    style B fill:#7C3AED,color:#fff&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    style D fill:#F59E0B,color:#000&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    style G fill:#10B981,color:#fff&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h3 id=&#34;核心特性一览&#34;&gt;&lt;a href=&#34;#核心特性一览&#34; class=&#34;headerlink&#34; title=&#34;核心特性一览&#34;&gt;&lt;/a&gt;核心特性一览&lt;/h3&gt;&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;特性&lt;/th&gt;
&lt;th&gt;说明&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;🧠 &lt;strong&gt;自我进化&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;自主创建技能，在使用中自改进，建立长期记忆&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;🔧 &lt;strong&gt;模型中立&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;支持 30+ 模型提供商，随时切换，零锁定&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;🌐 &lt;strong&gt;多平台连接&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Telegram &amp;#x2F; Discord &amp;#x2F; Slack &amp;#x2F; WhatsApp &amp;#x2F; Signal &amp;#x2F; 钉钉 &amp;#x2F; 飞书 &amp;#x2F; 微信 &amp;#x2F; QQ 等&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;🖥️ &lt;strong&gt;终端 TUI&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;完整终端界面，多行编辑，斜杠命令自动补全&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;⏰ &lt;strong&gt;定时任务&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;内置 Cron 调度器，支持自然语言设定&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;🚚 &lt;strong&gt;子代理并行&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;派生孤立子代理并行工作，管线化复杂任务&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;🏠 &lt;strong&gt;6 种终端后端&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;本地 &amp;#x2F; Docker &amp;#x2F; SSH &amp;#x2F; Daytona &amp;#x2F; Singularity &amp;#x2F; Modal，服务器优雅托管&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;📦 &lt;strong&gt;Skills 生态&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;兼容 agentskills.io 开放标准，支持 MCP 协议&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;hr&gt;
&lt;h2 id=&#34;安装指南&#34;&gt;&lt;a href=&#34;#安装指南&#34; class=&#34;headerlink&#34; title=&#34;安装指南&#34;&gt;&lt;/a&gt;安装指南&lt;/h2&gt;&lt;h3 id=&#34;快速安装（推荐）&#34;&gt;&lt;a href=&#34;#快速安装（推荐）&#34; class=&#34;headerlink&#34; title=&#34;快速安装（推荐）&#34;&gt;&lt;/a&gt;快速安装（推荐）&lt;/h3&gt;&lt;p&gt;Hermes Agent 支持 &lt;strong&gt;Linux、macOS、WSL2&lt;/strong&gt;，一行命令搞定：&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;curl -fsSL https://raw.githubusercontent.com/NousResearch/hermes-agent/main/scripts/install.sh | bash&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;安装完成后，刷新 shell 配置并启动：&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;source&lt;/span&gt; ~/.bashrc   &lt;span class=&#34;comment&#34;&gt;# 或 source ~/.zshrc&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;hermes              &lt;span class=&#34;comment&#34;&gt;# 开始聊天！&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h3 id=&#34;Windows-用户&#34;&gt;&lt;a href=&#34;#Windows-用户&#34; class=&#34;headerlink&#34; title=&#34;Windows 用户&#34;&gt;&lt;/a&gt;Windows 用户&lt;/h3&gt;&lt;p&gt;Windows 原生不支持，请先安装 &lt;strong&gt;WSL2&lt;/strong&gt;：&lt;/p&gt;
&lt;figure class=&#34;highlight powershell&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# PowerShell（管理员）&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;wsl &lt;span class=&#34;literal&#34;&gt;--install&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;-d&lt;/span&gt; Ubuntu&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;然后在 WSL2 终端中执行安装命令。&lt;/p&gt;
&lt;h3 id=&#34;Android-Termux&#34;&gt;&lt;a href=&#34;#Android-Termux&#34; class=&#34;headerlink&#34; title=&#34;Android &amp;#x2F; Termux&#34;&gt;&lt;/a&gt;Android &amp;#x2F; Termux&lt;/h3&gt;&lt;p&gt;手机安装的详细手动步骤见 &lt;a href=&#34;https://hermes-agent.nousresearch.com/docs/getting-started/termux&#34;&gt;Termux 指南&lt;/a&gt;。&lt;/p&gt;
&lt;hr&gt;
&lt;h2 id=&#34;配置模型提供商&#34;&gt;&lt;a href=&#34;#配置模型提供商&#34; class=&#34;headerlink&#34; title=&#34;配置模型提供商&#34;&gt;&lt;/a&gt;配置模型提供商&lt;/h2&gt;&lt;p&gt;安装后最重要的一步：&lt;strong&gt;选择 LLM 提供商&lt;/strong&gt;。&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;hermes model    &lt;span class=&#34;comment&#34;&gt;# 交互式配置向导&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;支持 30+ 提供商，常见选择：&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;提供商&lt;/th&gt;
&lt;th&gt;接入方式&lt;/th&gt;
&lt;th&gt;说明&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;Nous Portal&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;OAuth 登录&lt;/td&gt;
&lt;td&gt;零配置订阅&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;OpenAI Codex&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;设备码认证&lt;/td&gt;
&lt;td&gt;ChatGPT OAuth&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;Anthropic Claude&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;OAuth 或 API Key&lt;/td&gt;
&lt;td&gt;Max 计划 + 额外用量&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;OpenRouter&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;API Key&lt;/td&gt;
&lt;td&gt;200+ 模型自由路由&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;DeepSeek&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;API Key&lt;/td&gt;
&lt;td&gt;直接接入&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;阿里云 DashScope&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;API Key&lt;/td&gt;
&lt;td&gt;Qwen 系列模型&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;Z.AI &amp;#x2F; GLM&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;API Key&lt;/td&gt;
&lt;td&gt;智谱模型&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;Kimi &amp;#x2F; Moonshot&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;API Key&lt;/td&gt;
&lt;td&gt;月之暗面模型&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;MiniMax&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;OAuth &amp;#x2F; API Key&lt;/td&gt;
&lt;td&gt;MiniMax-M2.7&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;自定义端点&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Base URL + Key&lt;/td&gt;
&lt;td&gt;VLLM &amp;#x2F; Ollama &amp;#x2F; SGLang 等&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;blockquote&gt;
&lt;p&gt;⚠️ &lt;strong&gt;最低要求：64K 上下文窗口&lt;/strong&gt;。Hermes 需要至少 64K tokens 的工作记忆。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h3 id=&#34;配置架构&#34;&gt;&lt;a href=&#34;#配置架构&#34; class=&#34;headerlink&#34; title=&#34;配置架构&#34;&gt;&lt;/a&gt;配置架构&lt;/h3&gt;&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;密钥&amp;#x2F;Token&lt;/strong&gt; → &lt;code&gt;~/.hermes/.env&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;非敏感设置&lt;/strong&gt; → &lt;code&gt;~/.hermes/config.yaml&lt;/code&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;通过 CLI 设置自动分流：&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;hermes config &lt;span class=&#34;built_in&#34;&gt;set&lt;/span&gt; model anthropic/claude-sonnet-4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;hermes config &lt;span class=&#34;built_in&#34;&gt;set&lt;/span&gt; terminal.backend docker&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;hermes config &lt;span class=&#34;built_in&#34;&gt;set&lt;/span&gt; OPENROUTER_API_KEY sk-or-xxx&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;hr&gt;
&lt;h2 id=&#34;CLI-使用&#34;&gt;&lt;a href=&#34;#CLI-使用&#34; class=&#34;headerlink&#34; title=&#34;CLI 使用&#34;&gt;&lt;/a&gt;CLI 使用&lt;/h2&gt;&lt;figure class=&#34;highlight plaintext&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;flowchart LR&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    A[hermes 启动] --&amp;gt; B&amp;#123;选择界面&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    B --&amp;gt; C[hermes 经典 CLI]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    B --&amp;gt; D[hermes --tui 现代 TUI]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    C --&amp;gt; E[交互对话]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    D --&amp;gt; E&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    E --&amp;gt; F[斜杠命令 /]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    F --&amp;gt; G[/model 换模型]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    F --&amp;gt; H[/skills 浏览技能]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    F --&amp;gt; I[/compress 压缩上下文]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    E --&amp;gt; J[退出 / 保存]&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h3 id=&#34;启动方式&#34;&gt;&lt;a href=&#34;#启动方式&#34; class=&#34;headerlink&#34; title=&#34;启动方式&#34;&gt;&lt;/a&gt;启动方式&lt;/h3&gt;&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;hermes                &lt;span class=&#34;comment&#34;&gt;# 经典 CLI&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;hermes --tui          &lt;span class=&#34;comment&#34;&gt;# 现代 TUI（推荐）&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;hermes -c             &lt;span class=&#34;comment&#34;&gt;# 恢复上次会话&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;hermes -s &amp;lt;skill&amp;gt;     &lt;span class=&#34;comment&#34;&gt;# 预加载技能&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;hermes chat -q &lt;span class=&#34;string&#34;&gt;&amp;quot;你好&amp;quot;&lt;/span&gt; &lt;span class=&#34;comment&#34;&gt;# 单次查询&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;hermes -w             &lt;span class=&#34;comment&#34;&gt;# 隔离工作目录&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h3 id=&#34;状态栏&#34;&gt;&lt;a href=&#34;#状态栏&#34; class=&#34;headerlink&#34; title=&#34;状态栏&#34;&gt;&lt;/a&gt;状态栏&lt;/h3&gt;&lt;p&gt;会话中底部会实时显示状态：&lt;/p&gt;
&lt;figure class=&#34;highlight mathematica&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;⚕ &lt;span class=&#34;variable&#34;&gt;claude&lt;/span&gt;&lt;span class=&#34;operator&#34;&gt;-&lt;/span&gt;&lt;span class=&#34;variable&#34;&gt;sonnet&lt;/span&gt;&lt;span class=&#34;operator&#34;&gt;-&lt;/span&gt;&lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;&lt;span class=&#34;operator&#34;&gt;-&lt;/span&gt;&lt;span class=&#34;number&#34;&gt;20250514&lt;/span&gt; │ &lt;span class=&#34;number&#34;&gt;12.4&lt;/span&gt;&lt;span class=&#34;built_in&#34;&gt;K&lt;/span&gt;&lt;span class=&#34;operator&#34;&gt;/&lt;/span&gt;&lt;span class=&#34;number&#34;&gt;200&lt;/span&gt;&lt;span class=&#34;built_in&#34;&gt;K&lt;/span&gt; │ &lt;span class=&#34;punctuation&#34;&gt;[&lt;/span&gt;██████░░░░&lt;span class=&#34;punctuation&#34;&gt;]&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;6&lt;/span&gt;&lt;span class=&#34;operator&#34;&gt;%&lt;/span&gt; │ &lt;span class=&#34;variable&#34;&gt;$0&lt;/span&gt;&lt;span class=&#34;number&#34;&gt;.06&lt;/span&gt; │ &lt;span class=&#34;number&#34;&gt;15&lt;/span&gt;&lt;span class=&#34;variable&#34;&gt;m&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;元素&lt;/th&gt;
&lt;th&gt;含义&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;模型名&lt;/td&gt;
&lt;td&gt;当前模型&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Token 计数&lt;/td&gt;
&lt;td&gt;已用 &amp;#x2F; 最大上下文&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;彩色进度条&lt;/td&gt;
&lt;td&gt;绿 &amp;lt; 50% → 黄 50-80% → 橙 80-95% → 红 ≥ 95%&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;费用&lt;/td&gt;
&lt;td&gt;估算会话成本&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;时长&lt;/td&gt;
&lt;td&gt;已用时&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;h3 id=&#34;常用斜杠命令&#34;&gt;&lt;a href=&#34;#常用斜杠命令&#34; class=&#34;headerlink&#34; title=&#34;常用斜杠命令&#34;&gt;&lt;/a&gt;常用斜杠命令&lt;/h3&gt;&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;命令&lt;/th&gt;
&lt;th&gt;功能&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;&lt;code&gt;/help&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;显示所有命令&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;/model&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;切换模型&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;/tools&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;列出可用工具&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;/skills browse&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;浏览 Skills Hub&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;/personality pirate&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;换人格（pirate &amp;#x2F; kawaii &amp;#x2F; 等）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;/retry&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;重试上一轮&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;/undo&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;撤销最后一轮&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;/compress&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;压缩上下文&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;/voice on&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;启用语音模式&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;/background &amp;lt;prompt&amp;gt;&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;后台执行任务&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;/title My Session&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;命名当前会话&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;h3 id=&#34;快捷键&#34;&gt;&lt;a href=&#34;#快捷键&#34; class=&#34;headerlink&#34; title=&#34;快捷键&#34;&gt;&lt;/a&gt;快捷键&lt;/h3&gt;&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;按键&lt;/th&gt;
&lt;th&gt;操作&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;&lt;code&gt;Enter&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;发送消息&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;Alt+Enter&lt;/code&gt; &amp;#x2F; &lt;code&gt;Ctrl+J&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;换行（多行输入）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;Tab&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;自动补全&amp;#x2F;接受建议&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;Ctrl+C&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;中断当前操作&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;Ctrl+B&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;开始&amp;#x2F;停止语音录制&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;Ctrl+G&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;在编辑器中编辑输入&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;hr&gt;
&lt;h2 id=&#34;消息网关：连接多平台&#34;&gt;&lt;a href=&#34;#消息网关：连接多平台&#34; class=&#34;headerlink&#34; title=&#34;消息网关：连接多平台&#34;&gt;&lt;/a&gt;消息网关：连接多平台&lt;/h2&gt;&lt;p&gt;Hermes Agent 最强大的特性之一——&lt;strong&gt;一个后台进程同时连接所有平台&lt;/strong&gt;。&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;hermes gateway setup    &lt;span class=&#34;comment&#34;&gt;# 交互式配置&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;hermes gateway          &lt;span class=&#34;comment&#34;&gt;# 前台启动&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;hermes gateway install  &lt;span class=&#34;comment&#34;&gt;# 安装为系统服务&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;hermes gateway start    &lt;span class=&#34;comment&#34;&gt;# 启动服务&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;hermes gateway stop     &lt;span class=&#34;comment&#34;&gt;# 停止服务&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;hermes gateway status   &lt;span class=&#34;comment&#34;&gt;# 查看状态&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h3 id=&#34;支持平台&#34;&gt;&lt;a href=&#34;#支持平台&#34; class=&#34;headerlink&#34; title=&#34;支持平台&#34;&gt;&lt;/a&gt;支持平台&lt;/h3&gt;&lt;table&gt;
