pan&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;          &lt;span class=&#34;attr&#34;&gt;headers&lt;/span&gt;: &amp;#123;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;            &lt;span class=&#34;string&#34;&gt;&amp;#x27;Content-Type&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;application/json&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;            &lt;span class=&#34;string&#34;&gt;&amp;#x27;Authorization&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;`Bearer &lt;span class=&#34;subst&#34;&gt;$&amp;#123;API_KEY&amp;#125;&lt;/span&gt;`&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;          &amp;#125;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;          &lt;span class=&#34;attr&#34;&gt;body&lt;/span&gt;: &lt;span class=&#34;title class_&#34;&gt;JSON&lt;/span&gt;.&lt;span class=&#34;title function_&#34;&gt;stringify&lt;/span&gt;(&amp;#123;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;            &lt;span class=&#34;attr&#34;&gt;model&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;gpt-4o&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;            &lt;span class=&#34;attr&#34;&gt;messages&lt;/span&gt;: [&amp;#123; &lt;span class=&#34;attr&#34;&gt;role&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;user&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;attr&#34;&gt;content&lt;/span&gt;: prompt &amp;#125;],&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;            &lt;span class=&#34;attr&#34;&gt;stream&lt;/span&gt;: &lt;span class=&#34;literal&#34;&gt;true&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;          &amp;#125;),&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;        &amp;#125;);&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;const&lt;/span&gt; reader = res.&lt;span class=&#34;property&#34;&gt;body&lt;/span&gt;.&lt;span class=&#34;title function_&#34;&gt;getReader&lt;/span&gt;();&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;const&lt;/span&gt; decoder = &lt;span class=&#34;keyword&#34;&gt;new&lt;/span&gt; &lt;span class=&#34;title class_&#34;&gt;TextDecoder&lt;/span&gt;();&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;let&lt;/span&gt; buffer = &lt;span class=&#34;string&#34;&gt;&amp;#x27;&amp;#x27;&lt;/span&gt;;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;while&lt;/span&gt; (&lt;span class=&#34;literal&#34;&gt;true&lt;/span&gt;) &amp;#123;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;          &lt;span class=&#34;keyword&#34;&gt;const&lt;/span&gt; &amp;#123; done, value &amp;#125; = &lt;span class=&#34;keyword&#34;&gt;await&lt;/span&gt; reader.&lt;span class=&#34;title function_&#34;&gt;read&lt;/span&gt;();&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;          &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (done) &lt;span class=&#34;keyword&#34;&gt;break&lt;/span&gt;;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;          &lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;          buffer += decoder.&lt;span class=&#34;title function_&#34;&gt;decode&lt;/span&gt;(value, &amp;#123; &lt;span class=&#34;attr&#34;&gt;stream&lt;/span&gt;: &lt;span class=&#34;literal&#34;&gt;true&lt;/span&gt; &amp;#125;);&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;          &lt;span class=&#34;keyword&#34;&gt;const&lt;/span&gt; lines = buffer.&lt;span class=&#34;title function_&#34;&gt;split&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&amp;#x27;\n&amp;#x27;&lt;/span&gt;);&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;          buffer = lines.&lt;span class=&#34;title function_&#34;&gt;pop&lt;/span&gt;() || &lt;span class=&#34;string&#34;&gt;&amp;#x27;&amp;#x27;&lt;/span&gt;;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;          &lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;          &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; (&lt;span class=&#34;keyword&#34;&gt;const&lt;/span&gt; line &lt;span class=&#34;keyword&#34;&gt;of&lt;/span&gt; lines) &amp;#123;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;            &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (!line.&lt;span class=&#34;title function_&#34;&gt;startsWith&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&amp;#x27;data: &amp;#x27;&lt;/span&gt;) || line.&lt;span class=&#34;title function_&#34;&gt;includes&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&amp;#x27;[DONE]&amp;#x27;&lt;/span&gt;)) &lt;span class=&#34;keyword&#34;&gt;continue&lt;/span&gt;;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;            &lt;span class=&#34;keyword&#34;&gt;try&lt;/span&gt; &amp;#123;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;              &lt;span class=&#34;keyword&#34;&gt;const&lt;/span&gt; chunk = &lt;span class=&#34;title class_&#34;&gt;JSON&lt;/span&gt;.&lt;span class=&#34;title function_&#34;&gt;parse&lt;/span&gt;(line.&lt;span class=&#34;title function_&#34;&gt;slice&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;6&lt;/span&gt;));&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;              &lt;span class=&#34;keyword&#34;&gt;const&lt;/span&gt; content = chunk.&lt;span class=&#34;property&#34;&gt;choices&lt;/span&gt;?.[&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;]?.&lt;span class=&#34;property&#34;&gt;delta&lt;/span&gt;?.&lt;span class=&#34;property&#34;&gt;content&lt;/span&gt;;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;              &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (content) aiDiv.&lt;span class=&#34;property&#34;&gt;textContent&lt;/span&gt; += content;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;            &amp;#125; &lt;span class=&#34;keyword&#34;&gt;catch&lt;/span&gt;(e) &amp;#123;&amp;#125;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;          &amp;#125;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;          chat.&lt;span class=&#34;property&#34;&gt;scrollTop&lt;/span&gt; = chat.&lt;span class=&#34;property&#34;&gt;scrollHeight&lt;/span&gt;;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;        &amp;#125;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;      &amp;#125; &lt;span class=&#34;keyword&#34;&gt;catch&lt;/span&gt; (e) &amp;#123;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;        aiDiv.&lt;span class=&#34;property&#34;&gt;textContent&lt;/span&gt; = &lt;span class=&#34;string&#34;&gt;&amp;#x27;请求失败：&amp;#x27;&lt;/span&gt; + e.&lt;span class=&#34;property&#34;&gt;message&lt;/span&gt;;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;      &amp;#125;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;      &lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;      aiDiv.&lt;span class=&#34;property&#34;&gt;classList&lt;/span&gt;.&lt;span class=&#34;title function_&#34;&gt;remove&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&amp;#x27;cursor&amp;#x27;&lt;/span&gt;);&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;      sendBtn.&lt;span class=&#34;property&#34;&gt;disabled&lt;/span&gt; = &lt;span class=&#34;literal&#34;&gt;false&lt;/span&gt;;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;    &amp;#125;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;    sendBtn.&lt;span class=&#34;title function_&#34;&gt;addEventListener&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&amp;#x27;click&amp;#x27;&lt;/span&gt;, send);&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;    input.&lt;span class=&#34;title function_&#34;&gt;addEventListener&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&amp;#x27;keydown&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;function&#34;&gt;(&lt;span class=&#34;params&#34;&gt;e&lt;/span&gt;) =&amp;gt;&lt;/span&gt; &amp;#123;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;      &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (e.&lt;span class=&#34;property&#34;&gt;key&lt;/span&gt; === &lt;span class=&#34;string&#34;&gt;&amp;#x27;Enter&amp;#x27;&lt;/span&gt; &amp;amp;&amp;amp; !e.&lt;span class=&#34;property&#34;&gt;shiftKey&lt;/span&gt;) &amp;#123; e.&lt;span class=&#34;title function_&#34;&gt;preventDefault&lt;/span&gt;(); &lt;span class=&#34;title function_&#34;&gt;send&lt;/span&gt;(); &amp;#125;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;    &amp;#125;);&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;  &lt;/span&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;script&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;body&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;html&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;效果：实时流式打字、闪烁光标、自动滚动。保存为 &lt;code&gt;.html&lt;/code&gt; 就可以直接用。&lt;/p&gt;
&lt;hr&gt;
&lt;h2 id=&#34;第五章：服务端中转-——-保护-API-Key&#34;&gt;&lt;a href=&#34;#第五章：服务端中转-——-保护-API-Key&#34; class=&#34;headerlink&#34; title=&#34;第五章：服务端中转 —— 保护 API Key&#34;&gt;&lt;/a&gt;第五章：服务端中转 —— 保护 API Key&lt;/h2&gt;&lt;p&gt;前端直接调 OpenAI API 会暴露 API Key，正确做法是加一个后端代理：&lt;/p&gt;
&lt;figure class=&#34;highlight javascript&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;// server.js —— Node.js 中转服务&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;const&lt;/span&gt; express = &lt;span class=&#34;built_in&#34;&gt;require&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&amp;#x27;express&amp;#x27;&lt;/span&gt;);&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;const&lt;/span&gt; app = &lt;span class=&#34;title function_&#34;&gt;express&lt;/span&gt;();&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;app.&lt;span class=&#34;title function_&#34;&gt;use&lt;/span&gt;(express.&lt;span class=&#34;title function_&#34;&gt;json&lt;/span&gt;());&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;app.&lt;span class=&#34;title function_&#34;&gt;use&lt;/span&gt;(express.&lt;span class=&#34;title function_&#34;&gt;static&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&amp;#x27;public&amp;#x27;&lt;/span&gt;));  &lt;span class=&#34;comment&#34;&gt;// 前端页面&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;app.&lt;span class=&#34;title function_&#34;&gt;post&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&amp;#x27;/api/chat&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;keyword&#34;&gt;async&lt;/span&gt; (req, res) =&amp;gt; &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;keyword&#34;&gt;const&lt;/span&gt; &amp;#123; prompt &amp;#125; = req.&lt;span class=&#34;property&#34;&gt;body&lt;/span&gt;;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;comment&#34;&gt;// 设置 SSE 响应头&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  res.&lt;span class=&#34;title function_&#34;&gt;writeHead&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;200&lt;/span&gt;, &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;#x27;Content-Type&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;text/event-stream&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;#x27;Cache-Control&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;no-cache&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;#x27;Connection&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;keep-alive&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &amp;#125;);&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;keyword&#34;&gt;try&lt;/span&gt; &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;// 转发给 OpenAI&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;const&lt;/span&gt; aiResponse = &lt;span class=&#34;keyword&#34;&gt;await&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;fetch&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&amp;#x27;https://api.openai.com/v1/chat/completions&amp;#x27;&lt;/span&gt;, &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;span class=&#34;attr&#34;&gt;method&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;POST&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;span class=&#34;attr&#34;&gt;headers&lt;/span&gt;: &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;string&#34;&gt;&amp;#x27;Content-Type&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;application/json&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;string&#34;&gt;&amp;#x27;Authorization&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;`Bearer &lt;span class=&#34;subst&#34;&gt;$&amp;#123;process.env.OPENAI_API_KEY&amp;#125;&lt;/span&gt;`&lt;/span&gt;,  &lt;span class=&#34;comment&#34;&gt;// Key 在服务端&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &amp;#125;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;span class=&#34;attr&#34;&gt;body&lt;/span&gt;: &lt;span class=&#34;title class_&#34;&gt;JSON&lt;/span&gt;.&lt;span class=&#34;title function_&#34;&gt;stringify&lt;/span&gt;(&amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;attr&#34;&gt;model&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;gpt-4o&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;attr&#34;&gt;messages&lt;/span&gt;: [&amp;#123; &lt;span class=&#34;attr&#34;&gt;role&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;user&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;attr&#34;&gt;content&lt;/span&gt;: prompt &amp;#125;],&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;attr&#34;&gt;stream&lt;/span&gt;: &lt;span class=&#34;literal&#34;&gt;true&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &amp;#125;),&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &amp;#125;);&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;const&lt;/span&gt; reader = aiResponse.&lt;span class=&#34;property&#34;&gt;body&lt;/span&gt;.&lt;span class=&#34;title function_&#34;&gt;getReader&lt;/span&gt;();&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;const&lt;/span&gt; decoder = &lt;span class=&#34;keyword&#34;&gt;new&lt;/span&gt; &lt;span class=&#34;title class_&#34;&gt;TextDecoder&lt;/span&gt;();&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;while&lt;/span&gt; (&lt;span class=&#34;literal&#34;&gt;true&lt;/span&gt;) &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;span class=&#34;keyword&#34;&gt;const&lt;/span&gt; &amp;#123; done, value &amp;#125; = &lt;span class=&#34;keyword&#34;&gt;await&lt;/span&gt; reader.&lt;span class=&#34;title function_&#34;&gt;read&lt;/span&gt;();&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (done) &lt;span class=&#34;keyword&#34;&gt;break&lt;/span&gt;;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;span class=&#34;keyword&#34;&gt;const&lt;/span&gt; text = decoder.&lt;span class=&#34;title function_&#34;&gt;decode&lt;/span&gt;(value, &amp;#123; &lt;span class=&#34;attr&#34;&gt;stream&lt;/span&gt;: &lt;span class=&#34;literal&#34;&gt;true&lt;/span&gt; &amp;#125;);&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;span class=&#34;comment&#34;&gt;// 直接透传原始 SSE 数据&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      res.&lt;span class=&#34;title function_&#34;&gt;write&lt;/span&gt;(text);&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    res.&lt;span class=&#34;title function_&#34;&gt;end&lt;/span&gt;();&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &amp;#125; &lt;span class=&#34;keyword&#34;&gt;catch&lt;/span&gt; (error) &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    res.&lt;span class=&#34;title function_&#34;&gt;write&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;`event: error\ndata: &lt;span class=&#34;subst&#34;&gt;$&amp;#123;&lt;span class=&#34;built_in&#34;&gt;JSON&lt;/span&gt;.stringify(&amp;#123; error: error.message &amp;#125;)&amp;#125;&lt;/span&gt;\n\n`&lt;/span&gt;);&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    res.&lt;span class=&#34;title function_&#34;&gt;end&lt;/span&gt;();&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;);&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;app.&lt;span class=&#34;title function_&#34;&gt;listen&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;3000&lt;/span&gt;, &lt;span class=&#34;function&#34;&gt;() =&amp;gt;&lt;/span&gt; &lt;span class=&#34;variable language_&#34;&gt;console&lt;/span&gt;.&lt;span class=&#34;title function_&#34;&gt;log&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&amp;#x27;Server on http://localhost:3000&amp;#x27;&lt;/span&gt;));&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;这样前端只需调 &lt;code&gt;/api/chat&lt;/code&gt;，API Key 安全存放在服务端环境变量中。&lt;/p&gt;
&lt;hr&gt;
&lt;h2 id=&#34;第六章：高级话题&#34;&gt;&lt;a href=&#34;#第六章：高级话题&#34; class=&#34;headerlink&#34; title=&#34;第六章：高级话题&#34;&gt;&lt;/a&gt;第六章：高级话题&lt;/h2&gt;&lt;h3 id=&#34;6-1-SSE-vs-WebSocket-的技术细节&#34;&gt;&lt;a href=&#34;#6-1-SSE-vs-WebSocket-的技术细节&#34; class=&#34;headerlink&#34; title=&#34;6.1 SSE vs WebSocket 的技术细节&#34;&gt;&lt;/a&gt;6.1 SSE vs WebSocket 的技术细节&lt;/h3&gt;&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;维度&lt;/th&gt;
&lt;th&gt;SSE&lt;/th&gt;
&lt;th&gt;WebSocket&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;协议&lt;/td&gt;
&lt;td&gt;HTTP&amp;#x2F;1.1 或 HTTP&amp;#x2F;2&lt;/td&gt;
&lt;td&gt;独立协议（ws:&amp;#x2F;&amp;#x2F; wss:&amp;#x2F;&amp;#x2F;）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;浏览器 API&lt;/td&gt;
&lt;td&gt;&lt;code&gt;EventSource&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;WebSocket&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;二进制数据&lt;/td&gt;
&lt;td&gt;不支持（仅文本）&lt;/td&gt;
&lt;td&gt;支持&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;自动重连&lt;/td&gt;
&lt;td&gt;原生支持&lt;/td&gt;
&lt;td&gt;需手动实现&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;连接数限制&lt;/td&gt;
&lt;td&gt;HTTP&amp;#x2F;1.1 每域名 6 个&lt;/td&gt;
&lt;td&gt;无限制&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;HTTP&amp;#x2F;2 多路复用&lt;/td&gt;
&lt;td&gt;完美支持&lt;/td&gt;
&lt;td&gt;不适用&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;穿透代理&lt;/td&gt;
&lt;td&gt;天然支持&lt;/td&gt;
&lt;td&gt;可能被某些代理阻断&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;消息方向&lt;/td&gt;
&lt;td&gt;单向（S→C）&lt;/td&gt;
&lt;td&gt;双向&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;关键优势&lt;/strong&gt;：在 HTTP&amp;#x2F;2 下，多个 SSE 连接可以复用同一条 TCP 连接，不再有 6 连接限制。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h3 id=&#34;6-2-流式思考（Streaming-Thinking）&#34;&gt;&lt;a href=&#34;#6-2-流式思考（Streaming-Thinking）&#34; class=&#34;headerlink&#34; title=&#34;6.2 流式思考（Streaming Thinking）&#34;&gt;&lt;/a&gt;6.2 流式思考（Streaming Thinking）&lt;/h3&gt;&lt;p&gt;Claude 等模型支持”思考过程”流式输出——在正式回答之前，先把推理过程实时展示给用户：&lt;/p&gt;
&lt;figure class=&#34;highlight json&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;// content_block_start: thinking&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;punctuation&#34;&gt;&amp;#123;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;&amp;quot;type&amp;quot;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;content_block_start&amp;quot;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;&amp;quot;content_block&amp;quot;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;:&lt;/span&gt; &lt;span class=&#34;punctuation&#34;&gt;&amp;#123;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;&amp;quot;type&amp;quot;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;thinking&amp;quot;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;&amp;quot;thinking&amp;quot;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;让我分析这个问题...&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;punctuation&#34;&gt;&amp;#125;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;punctuation&#34;&gt;&amp;#125;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;// content_block_delta: thinking&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;punctuation&#34;&gt;&amp;#123;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;&amp;quot;type&amp;quot;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;content_block_delta&amp;quot;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;&amp;quot;delta&amp;quot;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;:&lt;/span&gt; &lt;span class=&#34;punctuation&#34;&gt;&amp;#123;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;&amp;quot;type&amp;quot;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;thinking_delta&amp;quot;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;&amp;quot;thinking&amp;quot;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;首先考虑时间复杂度...&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;punctuation&#34;&gt;&amp;#125;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;punctuation&#34;&gt;&amp;#125;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;这给用户透明度和信任感——知道 AI 不是瞎猜的。&lt;/p&gt;
&lt;h3 id=&#34;6-3-断线续传&#34;&gt;&lt;a href=&#34;#6-3-断线续传&#34; class=&#34;headerlink&#34; title=&#34;6.3 断线续传&#34;&gt;&lt;/a&gt;6.3 断线续传&lt;/h3&gt;&lt;p&gt;EventSource 的 &lt;code&gt;lastEventId&lt;/code&gt; 机制支持断线续传：&lt;/p&gt;
&lt;figure class=&#34;highlight javascript&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;// 客户端自动在重连时发送 Last-Event-ID&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;// 服务端读取并恢复&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;const&lt;/span&gt; lastId = req.&lt;span class=&#34;property&#34;&gt;headers&lt;/span&gt;[&lt;span class=&#34;string&#34;&gt;&amp;#x27;last-event-id&amp;#x27;&lt;/span&gt;];&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (lastId) &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;comment&#34;&gt;// 从这条消息之后继续发送&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;title function_&#34;&gt;resumeFrom&lt;/span&gt;(lastId);&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;在 AI 场景中，这意味着如果网络断了，可以恢复连接继续输出而不是从头开始。&lt;/p&gt;
&lt;h3 id=&#34;6-4-多模态流式输出&#34;&gt;&lt;a href=&#34;#6-4-多模态流式输出&#34; class=&#34;headerlink&#34; title=&#34;6.4 多模态流式输出&#34;&gt;&lt;/a&gt;6.4 多模态流式输出&lt;/h3&gt;&lt;p&gt;最新的多模态模型支持流式输出混合内容（文本 + 图片 + 音频）：&lt;/p&gt;
&lt;figure class=&#34;highlight avrasm&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;symbol&#34;&gt;data:&lt;/span&gt; &amp;#123;&lt;span class=&#34;string&#34;&gt;&amp;quot;type&amp;quot;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;quot;text&amp;quot;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;quot;content&amp;quot;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;quot;这是生成的文字...&amp;quot;&lt;/span&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;symbol&#34;&gt;data:&lt;/span&gt; &amp;#123;&lt;span class=&#34;string&#34;&gt;&amp;quot;type&amp;quot;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;quot;image&amp;quot;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;quot;content&amp;quot;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;quot;base64...&amp;quot;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;quot;mime&amp;quot;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;quot;image/png&amp;quot;&lt;/span&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;symbol&#34;&gt;data:&lt;/span&gt; &amp;#123;&lt;span class=&#34;string&#34;&gt;&amp;quot;type&amp;quot;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;quot;audio&amp;quot;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;quot;content&amp;quot;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;quot;base64...&amp;quot;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;quot;mime&amp;quot;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;quot;audio/wav&amp;quot;&lt;/span&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;前端需要解析不同的 content type 并分别渲染。&lt;/p&gt;
&lt;hr&gt;
&lt;h2 id=&#34;第七章：调试与排错&#34;&gt;&lt;a href=&#34;#第七章：调试与排错&#34; class=&#34;headerlink&#34; title=&#34;第七章：调试与排错&#34;&gt;&lt;/a&gt;第七章：调试与排错&lt;/h2&gt;&lt;h3 id=&#34;常见问题&#34;&gt;&lt;a href=&#34;#常见问题&#34; class=&#34;headerlink&#34; title=&#34;常见问题&#34;&gt;&lt;/a&gt;常见问题&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;Q：EventSource 为什么连不上？&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;检查：&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;响应头 &lt;code&gt;Content-Type: text/event-stream&lt;/code&gt; 是否正确&lt;/li&gt;
&lt;li&gt;跨域问题 → 服务端加 &lt;code&gt;Access-Control-Allow-Origin&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;EventSource 不支持自定义 Header → 用 &lt;code&gt;fetch&lt;/code&gt; + &lt;code&gt;ReadableStream&lt;/code&gt; 代替&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;&lt;strong&gt;Q：为什么中间会断？&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;可能原因：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;代理服务器超时（nginx 默认 60s） → 加 &lt;code&gt;: keepalive&lt;/code&gt; 注释或调大超时&lt;/li&gt;
&lt;li&gt;服务端没处理 &lt;code&gt;req.on(&amp;#39;close&amp;#39;)&lt;/code&gt; → 客户端断开后还在写数据&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Q：数据乱了怎么办？&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;SSE 以空行分隔消息。如果数据中有空行会乱。处理时积累 &lt;code&gt;buffer&lt;/code&gt;，只在遇到完整事件后才解析。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Q：浏览器标签页切到后台，SSE 会暂停吗？&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;不会停止接收，但 &lt;code&gt;setTimeout&lt;/code&gt;&amp;#x2F;&lt;code&gt;setInterval&lt;/code&gt; 会被降频。UI 更新尽量用 &lt;code&gt;requestAnimationFrame&lt;/code&gt;。&lt;/p&gt;
&lt;hr&gt;
&lt;h2 id=&#34;总结&#34;&gt;&lt;a href=&#34;#总结&#34; class=&#34;headerlink&#34; title=&#34;总结&#34;&gt;&lt;/a&gt;总结&lt;/h2&gt;&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;知识点&lt;/th&gt;
&lt;th&gt;一句话&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;SSE 是什么&lt;/td&gt;
&lt;td&gt;HTTP 长连接，服务器单向推送文本事件流&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;和 WebSocket 区别&lt;/td&gt;
&lt;td&gt;SSE 单向（S→C）、基于 HTTP、更简单；WS 双向、独立协议&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;AI 为什么用 SSE&lt;/td&gt;
&lt;td&gt;LLM 逐 token 生成，天然流式，首字延迟极低&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;EventSource&lt;/td&gt;
&lt;td&gt;浏览器原生 API，但只支持 GET + 标准 Header&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;fetch + ReadableStream&lt;/td&gt;
&lt;td&gt;手动解析 SSE，支持 POST + 自定义 Header&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;生产环境注意&lt;/td&gt;
&lt;td&gt;服务端代理保护 Key、防超时、断线续传&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;p&gt;SSE 不是什么新技术（2009 年就标准化了），但伴随着 LLM 的爆发，它成为了 AI 应用中最核心的通信协议之一。掌握它，你就能理解市面上几乎所有 AI 产品的”打字效果”是怎么实现的。&lt;/p&gt;

 &lt;h2 id=&#34;前言：你为什么要读这篇文章？&#34;&gt;&lt;a href=&#34;#前言：你为什么要读这篇文章？&#34; class=&#34;headerlink&#34; title=&#34;前言：你为什么要读这篇文章？&#34;&gt;&lt;/a&gt;前言：你为什么要读这篇文章？&lt;/h2&gt;&lt;p&gt;假设你有几百份 PDF 合同、几十篇技术文档、一堆内部 Wiki 页面。每次想查个信息，要么翻半天文件夹，要么在几个系统之间来回切换。&lt;/p&gt;
&lt;p&gt;大语言模型（LLM）很强，但它有个致命缺陷：&lt;strong&gt;不知道自己不知道什么&lt;/strong&gt;。你问 ChatGPT “我们公司上季度的销售政策是什么”，它要么编一个答案，要么说”我没有这方面的信息”。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;RAG（Retrieval-Augmented Generation，检索增强生成）&lt;/strong&gt; 就是解决这个问题的。简单说：&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;先把你的文档”喂”给系统 → 系统理解并存储 → 你提问时，系统先检索相关文档片段 → 再让 LLM 基于这些片段生成答案。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;就像一个&lt;strong&gt;随身带着你全部文档的新员工&lt;/strong&gt;——记性好、不编造、有问必答。&lt;/p&gt;
&lt;p&gt;本文从零开始，带你用最主流的方式搭建一个属于自己的 LLM 知识库。&lt;/p&gt;
&lt;hr&gt;
&lt;h2 id=&#34;第一章：理解-RAG-的基本原理&#34;&gt;&lt;a href=&#34;#第一章：理解-RAG-的基本原理&#34; class=&#34;headerlink&#34; title=&#34;第一章：理解 RAG 的基本原理&#34;&gt;&lt;/a&gt;第一章：理解 RAG 的基本原理&lt;/h2&gt;&lt;h3 id=&#34;1-1-不用-RAG-的-LLM-有什么问题？&#34;&gt;&lt;a href=&#34;#1-1-不用-RAG-的-LLM-有什么问题？&#34; class=&#34;headerlink&#34; title=&#34;1.1 不用 RAG 的 LLM 有什么问题？&#34;&gt;&lt;/a&gt;1.1 不用 RAG 的 LLM 有什么问题？&lt;/h3&gt;&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;问题&lt;/th&gt;
&lt;th&gt;说明&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;❌ 知识截止&lt;/td&gt;
&lt;td&gt;训练数据有时间限制，不知道之后的事&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;❌ 幻觉&lt;/td&gt;
&lt;td&gt;不知道的问题会编造答案，还编得一本正经&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;❌ 领域盲区&lt;/td&gt;
&lt;td&gt;不懂你公司内部的术语、流程、文档&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;❌ 上下文窗口&lt;/td&gt;
&lt;td&gt;一次能塞进去的文档量有限&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;h3 id=&#34;1-2-RAG-是怎么工作的？&#34;&gt;&lt;a href=&#34;#1-2-RAG-是怎么工作的？&#34; class=&#34;headerlink&#34; title=&#34;1.2 RAG 是怎么工作的？&#34;&gt;&lt;/a&gt;1.2 RAG 是怎么工作的？&lt;/h3&gt;&lt;p&gt;整个流程分两步：&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;离线阶段（准备知识）——只做一次：&lt;/strong&gt;&lt;/p&gt;
&lt;figure class=&#34;highlight awk&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;你的文档（PDF&lt;span class=&#34;regexp&#34;&gt;/Word/&lt;/span&gt;Markdown/网页）&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        ▼&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;┌──────────────────┐&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│  文档解析 &amp;amp; 切分   │  把长文档切成合适大小的小块（chunk）&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;└──────────────────┘&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        ▼&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;┌──────────────────┐&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│  向量化（Embedding）│  用 Embedding 模型把文字变成数学向量&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;└──────────────────┘&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        ▼&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;┌──────────────────┐&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│  存入向量数据库     │  向量 + 原文一起存&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;└──────────────────┘&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;&lt;strong&gt;在线阶段（回答问题）——每次提问都执行：&lt;/strong&gt;&lt;/p&gt;
&lt;figure class=&#34;highlight mipsasm&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;用户提问：&lt;span class=&#34;string&#34;&gt;&amp;quot;合同里违约金怎么算？&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        ▼&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;┌──────────────────┐&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│  问题向量化        │  把问题也变成向量&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;└──────────────────┘&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        ▼&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;┌──────────────────┐&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│  语义检索          │  在向量数据库中找最相关的文档片段&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;└──────────────────┘&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        ▼&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;┌──────────────────┐&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│  组装 Prompt       │  把检索到的片段 + 问题拼成完整提示词&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;└──────────────────┘&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        ▼&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;┌──────────────────┐&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│  &lt;span class=&#34;keyword&#34;&gt;LLM &lt;/span&gt;生成答案      │  基于提供的文档内容回答问题&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;└──────────────────┘&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h3 id=&#34;1-3-关键概念解释&#34;&gt;&lt;a href=&#34;#1-3-关键概念解释&#34; class=&#34;headerlink&#34; title=&#34;1.3 关键概念解释&#34;&gt;&lt;/a&gt;1.3 关键概念解释&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;Embedding（向量化）&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;把一段文字转换成一串数字（向量）。语义相近的文字，向量也相近。比如”苹果很好吃”和”这个水果真甜”在向量空间中距离很近，”苹果发布了新手机”则离得很远。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Chunk（文档分块）&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;LLM 一次能处理的文字有限（上下文窗口），而且检索粒度太粗也没用。所以把长文档切成小块，每块通常 300-1000 个字符，块与块之间可以有重叠（防止一句话被拦腰截断）。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;向量数据库&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;专门存储和检索向量的数据库。流行的有：&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;数据库&lt;/th&gt;
&lt;th&gt;特点&lt;/th&gt;
&lt;th&gt;适用场景&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;Chroma&lt;/td&gt;
&lt;td&gt;轻量、Python 原生、零配置&lt;/td&gt;
&lt;td&gt;本地开发 &amp;#x2F; 小项目&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Milvus&lt;/td&gt;
&lt;td&gt;高性能、分布式&lt;/td&gt;
&lt;td&gt;企业级 &amp;#x2F; 百万级文档&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Qdrant&lt;/td&gt;
&lt;td&gt;Rust 编写、性能好&lt;/td&gt;
&lt;td&gt;中大型项目&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Weaviate&lt;/td&gt;
&lt;td&gt;GraphQL 接口、功能全&lt;/td&gt;
&lt;td&gt;有复杂查询需求&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;FAISS&lt;/td&gt;
&lt;td&gt;Meta 开源、纯向量搜索&lt;/td&gt;
&lt;td&gt;嵌入式 &amp;#x2F; 高性能场景&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;pgvector&lt;/td&gt;
&lt;td&gt;PostgreSQL 插件&lt;/td&gt;
&lt;td&gt;已有 PG 技术栈的团队&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;p&gt;&lt;strong&gt;重排序（Rerank）&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;第一次检索返回的文档片段不一定是最相关的（粗排），可以用 Rerank 模型做二次精排，提高准确率。&lt;/p&gt;
&lt;hr&gt;
&lt;h2 id=&#34;第二章：选型对比&#34;&gt;&lt;a href=&#34;#第二章：选型对比&#34; class=&#34;headerlink&#34; title=&#34;第二章：选型对比&#34;&gt;&lt;/a&gt;第二章：选型对比&lt;/h2&gt;&lt;p&gt;市面上的 LLM 知识库方案很多，先做一个快速对比帮你选型。&lt;/p&gt;
&lt;h3 id=&#34;2-1-主流方案一览&#34;&gt;&lt;a href=&#34;#2-1-主流方案一览&#34; class=&#34;headerlink&#34; title=&#34;2.1 主流方案一览&#34;&gt;&lt;/a&gt;2.1 主流方案一览&lt;/h3&gt;&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;方案&lt;/th&gt;
&lt;th&gt;定位&lt;/th&gt;
&lt;th&gt;上手难度&lt;/th&gt;
&lt;th&gt;适合谁&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;Dify&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;全能 LLM 应用平台&lt;/td&gt;
&lt;td&gt;⭐ 简单&lt;/td&gt;
&lt;td&gt;所有人，首选&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;FastGPT&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;专注知识库问答&lt;/td&gt;
&lt;td&gt;⭐ 简单&lt;/td&gt;
&lt;td&gt;只想做知识库&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;AnythingLLM&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;桌面端一键部署&lt;/td&gt;
&lt;td&gt;⭐ 最简单&lt;/td&gt;
&lt;td&gt;个人用户、不想折腾&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;MaxKB&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;国产知识库问答&lt;/td&gt;
&lt;td&gt;⭐ 简单&lt;/td&gt;
&lt;td&gt;中文场景、企业用&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;LangChain&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;开发框架&lt;/td&gt;
&lt;td&gt;⭐⭐⭐ 中等&lt;/td&gt;
&lt;td&gt;开发者、需要定制&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;LlamaIndex&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;数据索引框架&lt;/td&gt;
&lt;td&gt;⭐⭐⭐ 中等&lt;/td&gt;
&lt;td&gt;复杂数据管道&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;h3 id=&#34;2-2-新手推荐：Dify&#34;&gt;&lt;a href=&#34;#2-2-新手推荐：Dify&#34; class=&#34;headerlink&#34; title=&#34;2.2 新手推荐：Dify&#34;&gt;&lt;/a&gt;2.2 新手推荐：Dify&lt;/h3&gt;&lt;p&gt;推荐理由：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;开箱即用&lt;/strong&gt;：Docker 一条命令启动，有 Web 管理界面&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;功能完整&lt;/strong&gt;：不只是知识库，还包括工作流编排、Agent、对话日志&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;社区活跃&lt;/strong&gt;：GitHub 6 万+ Star，中文文档完善&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;模型灵活&lt;/strong&gt;：支持 OpenAI &amp;#x2F; Claude &amp;#x2F; 本地模型 &amp;#x2F; 各种国产模型&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;有云版本&lt;/strong&gt;：不想自己部署可以用 Dify Cloud 直接开始&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;本文以 &lt;strong&gt;Dify 自部署版&lt;/strong&gt;为主进行实操讲解。其他方案思路类似，一通百通。&lt;/p&gt;
&lt;hr&gt;
&lt;h2 id=&#34;第三章：环境准备&#34;&gt;&lt;a href=&#34;#第三章：环境准备&#34; class=&#34;headerlink&#34; title=&#34;第三章：环境准备&#34;&gt;&lt;/a&gt;第三章：环境准备&lt;/h2&gt;&lt;h3 id=&#34;3-1-硬件要求&#34;&gt;&lt;a href=&#34;#3-1-硬件要求&#34; class=&#34;headerlink&#34; title=&#34;3.1 硬件要求&#34;&gt;&lt;/a&gt;3.1 硬件要求&lt;/h3&gt;&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;配置&lt;/th&gt;
&lt;th&gt;最低要求&lt;/th&gt;
&lt;th&gt;推荐配置&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;CPU&lt;/td&gt;
&lt;td&gt;2 核&lt;/td&gt;
&lt;td&gt;4 核+&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;内存&lt;/td&gt;
&lt;td&gt;4 GB&lt;/td&gt;
&lt;td&gt;8 GB+&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;磁盘&lt;/td&gt;
&lt;td&gt;20 GB&lt;/td&gt;
&lt;td&gt;50 GB+ (看文档量)&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;GPU&lt;/td&gt;
&lt;td&gt;不需要&lt;/td&gt;
&lt;td&gt;本地跑模型时建议&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;blockquote&gt;
&lt;p&gt;如果你只是用云端 API（OpenAI &amp;#x2F; Claude &amp;#x2F; 国产模型），&lt;strong&gt;不需要 GPU&lt;/strong&gt;。只有当你打算本地部署开源模型时才需要。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h3 id=&#34;3-2-安装-Docker&#34;&gt;&lt;a href=&#34;#3-2-安装-Docker&#34; class=&#34;headerlink&#34; title=&#34;3.2 安装 Docker&#34;&gt;&lt;/a&gt;3.2 安装 Docker&lt;/h3&gt;&lt;p&gt;Dify 通过 Docker 部署，先安装 Docker：&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Windows：&lt;/strong&gt;&lt;/p&gt;
&lt;figure class=&#34;highlight powershell&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 方式一：直接下载 Docker Desktop&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# https://www.docker.com/products/docker-desktop/&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 方式二：WinGet&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;winget install Docker.DockerDesktop&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;&lt;strong&gt;macOS：&lt;/strong&gt;&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;brew install --cask docker&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;&lt;strong&gt;Linux（Ubuntu&amp;#x2F;Debian）：&lt;/strong&gt;&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;curl -fsSL https://get.docker.com | bash&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;sudo usermod -aG docker &lt;span class=&#34;variable&#34;&gt;$USER&lt;/span&gt;  &lt;span class=&#34;comment&#34;&gt;# 免 sudo&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;验证安装：&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;docker --version&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;docker compose version&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h3 id=&#34;3-3-获取-API-Key&#34;&gt;&lt;a href=&#34;#3-3-获取-API-Key&#34; class=&#34;headerlink&#34; title=&#34;3.3 获取 API Key&#34;&gt;&lt;/a&gt;3.3 获取 API Key&lt;/h3&gt;&lt;p&gt;你需要至少一个 LLM 的 API Key。可选方案：&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;提供商&lt;/th&gt;
&lt;th&gt;获取方式&lt;/th&gt;
&lt;th&gt;费用&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;OpenAI&lt;/td&gt;
&lt;td&gt;&lt;a href=&#34;https://platform.openai.com/&#34;&gt;platform.openai.com&lt;/a&gt; → API Keys&lt;/td&gt;
&lt;td&gt;按量付费&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Anthropic&lt;/td&gt;
&lt;td&gt;&lt;a href=&#34;https://console.anthropic.com/&#34;&gt;console.anthropic.com&lt;/a&gt; → API Keys&lt;/td&gt;
&lt;td&gt;按量付费&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;智谱 (GLM)&lt;/td&gt;
&lt;td&gt;&lt;a href=&#34;https://open.bigmodel.cn/&#34;&gt;open.bigmodel.cn&lt;/a&gt; → API Keys&lt;/td&gt;
&lt;td&gt;有免费额度&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;DeepSeek&lt;/td&gt;
&lt;td&gt;&lt;a href=&#34;https://platform.deepseek.com/&#34;&gt;platform.deepseek.com&lt;/a&gt; → API Keys&lt;/td&gt;
&lt;td&gt;极便宜&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;阿里通义&lt;/td&gt;
&lt;td&gt;&lt;a href=&#34;https://dashscope.aliyun.com/&#34;&gt;dashscope.aliyun.com&lt;/a&gt; → API Keys&lt;/td&gt;
&lt;td&gt;有免费额度&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;SiliconFlow&lt;/td&gt;
&lt;td&gt;&lt;a href=&#34;https://siliconflow.cn/&#34;&gt;siliconflow.cn&lt;/a&gt; → API Keys&lt;/td&gt;
&lt;td&gt;聚合多模型&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;新手建议&lt;/strong&gt;：先用 DeepSeek 或智谱，有免费额度，够你学完整套流程。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;hr&gt;
&lt;h2 id=&#34;第四章：部署-Dify&#34;&gt;&lt;a href=&#34;#第四章：部署-Dify&#34; class=&#34;headerlink&#34; title=&#34;第四章：部署 Dify&#34;&gt;&lt;/a&gt;第四章：部署 Dify&lt;/h2&gt;&lt;h3 id=&#34;4-1-一条命令启动&#34;&gt;&lt;a href=&#34;#4-1-一条命令启动&#34; class=&#34;headerlink&#34; title=&#34;4.1 一条命令启动&#34;&gt;&lt;/a&gt;4.1 一条命令启动&lt;/h3&gt;&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 克隆项目&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;git &lt;span class=&#34;built_in&#34;&gt;clone&lt;/span&gt; https://github.com/langgenius/dify.git&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;cd&lt;/span&gt; dify/docker&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 复制环境变量配置&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;cp&lt;/span&gt; .env.example .&lt;span class=&#34;built_in&#34;&gt;env&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 启动所有服务&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;docker compose up -d&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;Docker 会自动拉取并启动以下服务：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;api&lt;/code&gt; — Dify 后端 API&lt;/li&gt;
&lt;li&gt;&lt;code&gt;web&lt;/code&gt; — Dify 前端界面&lt;/li&gt;
&lt;li&gt;&lt;code&gt;db&lt;/code&gt; — PostgreSQL 数据库&lt;/li&gt;
&lt;li&gt;&lt;code&gt;redis&lt;/code&gt; — 缓存&lt;/li&gt;
&lt;li&gt;&lt;code&gt;weaviate&lt;/code&gt; — 向量数据库&lt;/li&gt;
&lt;li&gt;&lt;code&gt;nginx&lt;/code&gt; — 反向代理&lt;/li&gt;
&lt;li&gt;&lt;code&gt;sandbox&lt;/code&gt; — 代码执行沙箱&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;等几分钟后，浏览器打开 &lt;code&gt;http://localhost&lt;/code&gt;，你会看到初始化页面。&lt;/p&gt;
&lt;h3 id=&#34;4-2-初始化设置&#34;&gt;&lt;a href=&#34;#4-2-初始化设置&#34; class=&#34;headerlink&#34; title=&#34;4.2 初始化设置&#34;&gt;&lt;/a&gt;4.2 初始化设置&lt;/h3&gt;&lt;ol&gt;
&lt;li&gt;设置管理员邮箱和密码&lt;/li&gt;
&lt;li&gt;点击「初始化」&lt;/li&gt;
&lt;li&gt;登录后进入 Dify 主界面&lt;/li&gt;
&lt;/ol&gt;
&lt;h3 id=&#34;4-3-配置模型&#34;&gt;&lt;a href=&#34;#4-3-配置模型&#34; class=&#34;headerlink&#34; title=&#34;4.3 配置模型&#34;&gt;&lt;/a&gt;4.3 配置模型&lt;/h3&gt;&lt;p&gt;登录后第一步：&lt;strong&gt;设置 → 模型供应商&lt;/strong&gt;，添加你的 LLM。&lt;/p&gt;
&lt;p&gt;以 DeepSeek 为例：&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;点击「DeepSeek」→「设置」&lt;/li&gt;
&lt;li&gt;填入 API Key&lt;/li&gt;
&lt;li&gt;点击「保存」&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;以 OpenAI 为例：&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;点击「OpenAI」→「设置」&lt;/li&gt;
&lt;li&gt;填入 API Key&lt;/li&gt;
&lt;li&gt;可选：填入自定义 API 地址（如果你用中转服务）&lt;/li&gt;
&lt;li&gt;保存&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;同样方式添加 Embedding 模型。Dify 会自动使用与 LLM 同提供商的 Embedding 模型，也可以单独配置。&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;省钱技巧&lt;/strong&gt;：LLM 用 DeepSeek（便宜），Embedding 用智谱或 SiliconFlow 的免费额度。一个大模型回答 + 一个向量化模型，分开配置，成本极低。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;hr&gt;
&lt;h2 id=&#34;第五章：创建你的第一个知识库&#34;&gt;&lt;a href=&#34;#第五章：创建你的第一个知识库&#34; class=&#34;headerlink&#34; title=&#34;第五章：创建你的第一个知识库&#34;&gt;&lt;/a&gt;第五章：创建你的第一个知识库&lt;/h2&gt;&lt;h3 id=&#34;5-1-上传文档&#34;&gt;&lt;a href=&#34;#5-1-上传文档&#34; class=&#34;headerlink&#34; title=&#34;5.1 上传文档&#34;&gt;&lt;/a&gt;5.1 上传文档&lt;/h3&gt;&lt;ol&gt;
&lt;li&gt;顶部导航 → &lt;strong&gt;「知识库」&lt;/strong&gt; → &lt;strong&gt;「创建知识库」&lt;/strong&gt;&lt;/li&gt;
&lt;li&gt;填写名称（如”公司制度知识库”）&lt;/li&gt;
&lt;li&gt;点击创建&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;进入知识库后，你可以上传文档：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;支持格式&lt;/strong&gt;：PDF、TXT、Markdown、Word (.docx)、Excel (.xlsx)、HTML、CSV&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;上传方式&lt;/strong&gt;：拖拽文件 &amp;#x2F; 从 URL 导入 &amp;#x2F; 粘贴文本 &amp;#x2F; 对接 Notion&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;批量上传&lt;/strong&gt;：支持一次性上传多个文件&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;5-2-文档处理设置&#34;&gt;&lt;a href=&#34;#5-2-文档处理设置&#34; class=&#34;headerlink&#34; title=&#34;5.2 文档处理设置&#34;&gt;&lt;/a&gt;5.2 文档处理设置&lt;/h3&gt;&lt;p&gt;上传前可以调整关键参数：&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;参数&lt;/th&gt;
&lt;th&gt;说明&lt;/th&gt;
&lt;th&gt;建议值&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;分段最大长度&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;每个 chunk 的字符数上限&lt;/td&gt;
&lt;td&gt;500-800&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;分段重叠长度&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;相邻 chunk 的重叠字符数&lt;/td&gt;
&lt;td&gt;50-100&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;索引方式&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;高质量（推荐） &amp;#x2F; 经济 &amp;#x2F; 自定义&lt;/td&gt;
&lt;td&gt;高质量&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;检索方式&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;向量检索 &amp;#x2F; 全文检索 &amp;#x2F; 混合检索&lt;/td&gt;
&lt;td&gt;混合检索&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;p&gt;&lt;strong&gt;分段长度怎么选？&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;合同、法律文档：偏长（800-1000），一个条款不能断&lt;/li&gt;
&lt;li&gt;FAQ、问答对：偏短（300-500），问题答案各自独立&lt;/li&gt;
&lt;li&gt;技术文档：中等（500-800），一个知识点一块&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;5-3-等待处理&#34;&gt;&lt;a href=&#34;#5-3-等待处理&#34; class=&#34;headerlink&#34; title=&#34;5.3 等待处理&#34;&gt;&lt;/a&gt;5.3 等待处理&lt;/h3&gt;&lt;p&gt;上传后 Dify 自动执行：&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;文档解析（提取文字）&lt;/li&gt;
&lt;li&gt;文本分块（按设置切分）&lt;/li&gt;
&lt;li&gt;向量化（调用 Embedding 模型）&lt;/li&gt;
&lt;li&gt;存入向量数据库&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;处理速度取决于文档大小和 API 响应速度，一般几兆 PDF 几十秒就完成。&lt;/p&gt;
&lt;p&gt;处理完后你可以：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;查看分段结果（每个 chunk 的内容）&lt;/li&gt;
&lt;li&gt;手动编辑或删除某些分段&lt;/li&gt;
&lt;li&gt;在检索测试中直接搜索，看返回结果质量&lt;/li&gt;
&lt;/ul&gt;
&lt;hr&gt;
&lt;h2 id=&#34;第六章：创建知识库问答应用&#34;&gt;&lt;a href=&#34;#第六章：创建知识库问答应用&#34; class=&#34;headerlink&#34; title=&#34;第六章：创建知识库问答应用&#34;&gt;&lt;/a&gt;第六章：创建知识库问答应用&lt;/h2&gt;&lt;p&gt;知识库准备好后，把它变成一个可交互的聊天应用。&lt;/p&gt;
&lt;h3 id=&#34;6-1-创建应用&#34;&gt;&lt;a href=&#34;#6-1-创建应用&#34; class=&#34;headerlink&#34; title=&#34;6.1 创建应用&#34;&gt;&lt;/a&gt;6.1 创建应用&lt;/h3&gt;&lt;ol&gt;
&lt;li&gt;顶部导航 → &lt;strong&gt;「工作室」&lt;/strong&gt; → &lt;strong&gt;「创建空白应用」&lt;/strong&gt;&lt;/li&gt;
&lt;li&gt;选择 &lt;strong&gt;「聊天助手」&lt;/strong&gt; 类型&lt;/li&gt;
&lt;li&gt;命名（如”合同助手”）&lt;/li&gt;
&lt;li&gt;点击创建&lt;/li&gt;
&lt;/ol&gt;
&lt;h3 id=&#34;6-2-关联知识库&#34;&gt;&lt;a href=&#34;#6-2-关联知识库&#34; class=&#34;headerlink&#34; title=&#34;6.2 关联知识库&#34;&gt;&lt;/a&gt;6.2 关联知识库&lt;/h3&gt;&lt;p&gt;在应用编辑界面：&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;左侧 &lt;strong&gt;「上下文」&lt;/strong&gt; → 点击 &lt;strong&gt;「添加」&lt;/strong&gt;&lt;/li&gt;
&lt;li&gt;选择你刚创建的知识库&lt;/li&gt;
&lt;li&gt;设置参数：&lt;/li&gt;
&lt;/ol&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;参数&lt;/th&gt;
&lt;th&gt;说明&lt;/th&gt;
&lt;th&gt;建议&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;Top K&lt;/td&gt;
&lt;td&gt;每次检索返回多少个 chunk&lt;/td&gt;
&lt;td&gt;3-5&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;相似度阈值&lt;/td&gt;
&lt;td&gt;低于此分值的 chunk 不采用&lt;/td&gt;
&lt;td&gt;0.5-0.7&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;h3 id=&#34;6-3-编写系统提示词（Prompt）&#34;&gt;&lt;a href=&#34;#6-3-编写系统提示词（Prompt）&#34; class=&#34;headerlink&#34; title=&#34;6.3 编写系统提示词（Prompt）&#34;&gt;&lt;/a&gt;6.3 编写系统提示词（Prompt）&lt;/h3&gt;&lt;p&gt;在 &lt;strong&gt;「提示词」&lt;/strong&gt; 编辑框中，这是最关键的一步。一个模板：&lt;/p&gt;
&lt;figure class=&#34;highlight markdown&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;你是一个专业的知识库助手，专门回答关于[你的领域]的问题。&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;section&#34;&gt;## 规则&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;bullet&#34;&gt;1.&lt;/span&gt; 只根据「参考文档」中的内容回答问题&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;bullet&#34;&gt;2.&lt;/span&gt; 如果文档中没有相关信息，直接说&amp;quot;文档中未找到相关内容&amp;quot;，不要编造&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;bullet&#34;&gt;3.&lt;/span&gt; 回答时尽量引用文档原文，并注明来源&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;bullet&#34;&gt;4.&lt;/span&gt; 保持回答简洁专业，用中文回复&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;section&#34;&gt;## 参考文档&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;&amp;#123;context&amp;#125;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;其中 &lt;code&gt;&amp;#123;&amp;#123;context&amp;#125;&amp;#125;&lt;/code&gt; 是变量占位符，RAG 检索到的文档片段会自动填入。&lt;/p&gt;
&lt;h3 id=&#34;6-4-调试测试&#34;&gt;&lt;a href=&#34;#6-4-调试测试&#34; class=&#34;headerlink&#34; title=&#34;6.4 调试测试&#34;&gt;&lt;/a&gt;6.4 调试测试&lt;/h3&gt;&lt;p&gt;右侧有一个 &lt;strong&gt;「调试与预览」&lt;/strong&gt; 面板，可以直接测试。&lt;/p&gt;
&lt;p&gt;先确认右上角选择了正确的模型（比如 DeepSeek V3 或 GPT-4o），然后输入问题：&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;“合同中提前解约需要提前多少天通知？”&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;你会看到 Dify 先展示了检索到的文档片段（可以展开查看哪些 chunk 被命中），然后基于这些片段生成回答。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;如果回答质量不好？&lt;/strong&gt;&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;症状&lt;/th&gt;
&lt;th&gt;可能原因&lt;/th&gt;
&lt;th&gt;调整方向&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;答非所问&lt;/td&gt;
&lt;td&gt;检索不准&lt;/td&gt;
&lt;td&gt;调高 Top K、换混合检索&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;信息不全&lt;/td&gt;
&lt;td&gt;分段太碎&lt;/td&gt;
&lt;td&gt;增大 chunk 长度&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;答了无关内容&lt;/td&gt;
&lt;td&gt;阈值太低&lt;/td&gt;
&lt;td&gt;提高相似度阈值&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;回答太啰嗦&lt;/td&gt;
&lt;td&gt;Prompt 太弱&lt;/td&gt;
&lt;td&gt;优化系统提示词&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;幻觉严重&lt;/td&gt;
&lt;td&gt;文档覆盖不足&lt;/td&gt;
&lt;td&gt;补充文档、优化提示词&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;hr&gt;
&lt;h2 id=&#34;第七章：发布与使用&#34;&gt;&lt;a href=&#34;#第七章：发布与使用&#34; class=&#34;headerlink&#34; title=&#34;第七章：发布与使用&#34;&gt;&lt;/a&gt;第七章：发布与使用&lt;/h2&gt;&lt;h3 id=&#34;7-1-发布应用&#34;&gt;&lt;a href=&#34;#7-1-发布应用&#34; class=&#34;headerlink&#34; title=&#34;7.1 发布应用&#34;&gt;&lt;/a&gt;7.1 发布应用&lt;/h3&gt;&lt;p&gt;调试满意后，点击右上角 &lt;strong&gt;「发布」&lt;/strong&gt;。&lt;/p&gt;
&lt;p&gt;Dify 提供多种使用方式：&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;方式&lt;/th&gt;
&lt;th&gt;说明&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;网页链接&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;生成一个公开 URL，直接分享&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;嵌入网页&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;提供 iframe &amp;#x2F; script 代码，嵌入到你的网站&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;API 调用&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;提供 REST API，集成到自己的系统&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;企业微信&amp;#x2F;飞书&amp;#x2F;钉钉&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;对接办公 IM&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;h3 id=&#34;7-2-API-集成示例&#34;&gt;&lt;a href=&#34;#7-2-API-集成示例&#34; class=&#34;headerlink&#34; title=&#34;7.2 API 集成示例&#34;&gt;&lt;/a&gt;7.2 API 集成示例&lt;/h3&gt;&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; requests&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;url = &lt;span class=&#34;string&#34;&gt;&amp;quot;http://localhost/v1/chat-messages&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;headers = &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;Authorization&amp;quot;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;quot;Bearer app-YOUR_APP_API_KEY&amp;quot;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;Content-Type&amp;quot;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;quot;application/json&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;data = &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;inputs&amp;quot;&lt;/span&gt;: &amp;#123;&amp;#125;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;query&amp;quot;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;quot;员工年假有多少天？&amp;quot;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;response_mode&amp;quot;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;quot;blocking&amp;quot;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;conversation_id&amp;quot;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;quot;&amp;quot;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;user&amp;quot;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;quot;employee-001&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;response = requests.post(url, json=data, headers=headers)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(response.json()[&lt;span class=&#34;string&#34;&gt;&amp;quot;answer&amp;quot;&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h3 id=&#34;7-3-对话日志与分析&#34;&gt;&lt;a href=&#34;#7-3-对话日志与分析&#34; class=&#34;headerlink&#34; title=&#34;7.3 对话日志与分析&#34;&gt;&lt;/a&gt;7.3 对话日志与分析&lt;/h3&gt;&lt;p&gt;应用发布后，Dify 自动记录所有对话：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;「日志与标注」&lt;/strong&gt;：查看每条对话的问题、回答、检索到的文档&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;标注功能&lt;/strong&gt;：标记好的回答，用于后续优化&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;用量统计&lt;/strong&gt;：查看 API 调用次数、Token 消耗&lt;/li&gt;
&lt;/ul&gt;
&lt;hr&gt;
&lt;h2 id=&#34;第八章：进阶技巧&#34;&gt;&lt;a href=&#34;#第八章：进阶技巧&#34; class=&#34;headerlink&#34; title=&#34;第八章：进阶技巧&#34;&gt;&lt;/a&gt;第八章：进阶技巧&lt;/h2&gt;&lt;h3 id=&#34;8-1-多知识库联合检索&#34;&gt;&lt;a href=&#34;#8-1-多知识库联合检索&#34; class=&#34;headerlink&#34; title=&#34;8.1 多知识库联合检索&#34;&gt;&lt;/a&gt;8.1 多知识库联合检索&lt;/h3&gt;&lt;p&gt;一个应用可以关联多个知识库。比如：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;知识库 A：产品手册&lt;/li&gt;
&lt;li&gt;知识库 B：客服 FAQ&lt;/li&gt;
&lt;li&gt;知识库 C：内部流程文档&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;用户问一个问题，Dify 同时检索三个知识库，取最相关的 Top K 条。&lt;/p&gt;
&lt;h3 id=&#34;8-2-元数据过滤&#34;&gt;&lt;a href=&#34;#8-2-元数据过滤&#34; class=&#34;headerlink&#34; title=&#34;8.2 元数据过滤&#34;&gt;&lt;/a&gt;8.2 元数据过滤&lt;/h3&gt;&lt;p&gt;上传文档时可以加元数据标签（如 &lt;code&gt;category:财务&lt;/code&gt;、&lt;code&gt;year:2025&lt;/code&gt;），检索时按标签过滤：&lt;/p&gt;
&lt;figure class=&#34;highlight&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;只检索「2025年」的「财务类」文档 → 精确度和速度大幅提升&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h3 id=&#34;8-3-工作流编排（Workflow）&#34;&gt;&lt;a href=&#34;#8-3-工作流编排（Workflow）&#34; class=&#34;headerlink&#34; title=&#34;8.3 工作流编排（Workflow）&#34;&gt;&lt;/a&gt;8.3 工作流编排（Workflow）&lt;/h3&gt;&lt;p&gt;Dify 不只是问答。你可以用可视化的拖拽方式创建处理流程：&lt;/p&gt;
&lt;figure class=&#34;highlight mipsasm&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;用户输入 → 意图识别 → &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  ├─ 查资料 → 检索知识库 → &lt;span class=&#34;keyword&#34;&gt;LLM &lt;/span&gt;回答&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  ├─ 查数据 → 调用 API → 格式化返回&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  └─ 闲聊 → 直接 &lt;span class=&#34;keyword&#34;&gt;LLM &lt;/span&gt;回复&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h3 id=&#34;8-4-本地模型部署（省钱-隐私）&#34;&gt;&lt;a href=&#34;#8-4-本地模型部署（省钱-隐私）&#34; class=&#34;headerlink&#34; title=&#34;8.4 本地模型部署（省钱 + 隐私）&#34;&gt;&lt;/a&gt;8.4 本地模型部署（省钱 + 隐私）&lt;/h3&gt;&lt;p&gt;如果你有一定量的文档，不想每次调用都花 API 费用，或者文档涉密不能上云，可以本地部署开源模型。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Embedding 模型（向量化）：&lt;/strong&gt;&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 用 Ollama 部署&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;ollama pull nomic-embed-text&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;ollama pull bge-m3&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;&lt;strong&gt;LLM 模型（生成回答）：&lt;/strong&gt;&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# Qwen2.5 系列（中文友好）&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;ollama pull qwen2.5:7b&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;ollama pull qwen2.5:14b&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 或 DeepSeek&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;ollama pull deepseek-r1:8b&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;然后在 Dify 中配置模型供应商为「Ollama」，地址填 &lt;code&gt;http://localhost:11434&lt;/code&gt;。&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;7B 模型最低要求&lt;/strong&gt;：16GB 内存，无 GPU 也能跑（慢但能用）&lt;br&gt;&lt;strong&gt;14B 模型&lt;/strong&gt;：建议 32GB+ 内存或有 8GB+ 显存的 GPU&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h3 id=&#34;8-5-持续优化知识库&#34;&gt;&lt;a href=&#34;#8-5-持续优化知识库&#34; class=&#34;headerlink&#34; title=&#34;8.5 持续优化知识库&#34;&gt;&lt;/a&gt;8.5 持续优化知识库&lt;/h3&gt;&lt;p&gt;知识库不是建完就完事了：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;定期更新&lt;/strong&gt;：文档变了要重新上传新版本&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;分析失败案例&lt;/strong&gt;：看日志里哪些问题没回答好，补文档或调参数&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;用户反馈&lt;/strong&gt;：用标注功能收集好评&amp;#x2F;差评，针对性改进&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;A&amp;#x2F;B 测试&lt;/strong&gt;：同一问题用不同 chunk 大小或检索策略，对比效果&lt;/li&gt;
&lt;/ul&gt;
&lt;hr&gt;
&lt;h2 id=&#34;第九章：常见问题与排错&#34;&gt;&lt;a href=&#34;#第九章：常见问题与排错&#34; class=&#34;headerlink&#34; title=&#34;第九章：常见问题与排错&#34;&gt;&lt;/a&gt;第九章：常见问题与排错&lt;/h2&gt;&lt;h3 id=&#34;Q1：检索结果不准确怎么办？&#34;&gt;&lt;a href=&#34;#Q1：检索结果不准确怎么办？&#34; class=&#34;headerlink&#34; title=&#34;Q1：检索结果不准确怎么办？&#34;&gt;&lt;/a&gt;Q1：检索结果不准确怎么办？&lt;/h3&gt;&lt;ol&gt;
&lt;li&gt;先检查检索到的 chunk 是否包含答案（可能是 chunk 里有但没有被 LLM 用上 → 优化 Prompt）&lt;/li&gt;
&lt;li&gt;如果 chunk 里就没有答案 → 你的文档覆盖不足，或 chunk 切分有问题&lt;/li&gt;
&lt;li&gt;尝试切换检索方式：向量检索 → 混合检索 → 全文检索轮着试&lt;/li&gt;
&lt;li&gt;启用 Rerank 模型做二次精排&lt;/li&gt;
&lt;/ol&gt;
&lt;h3 id=&#34;Q2：Docker-启动失败？&#34;&gt;&lt;a href=&#34;#Q2：Docker-启动失败？&#34; class=&#34;headerlink&#34; title=&#34;Q2：Docker 启动失败？&#34;&gt;&lt;/a&gt;Q2：Docker 启动失败？&lt;/h3&gt;&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 查看日志&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;docker compose logs -f&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 常见问题：端口冲突&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 修改 .env 中的端口配置&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 重启&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;docker compose down&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;docker compose up -d&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h3 id=&#34;Q3：Embedding-处理很慢？&#34;&gt;&lt;a href=&#34;#Q3：Embedding-处理很慢？&#34; class=&#34;headerlink&#34; title=&#34;Q3：Embedding 处理很慢？&#34;&gt;&lt;/a&gt;Q3：Embedding 处理很慢？&lt;/h3&gt;&lt;ul&gt;
&lt;li&gt;检查 API 是否限速（免费额度通常有 RPM 限制）&lt;/li&gt;
&lt;li&gt;大批量文档分批上传&lt;/li&gt;
&lt;li&gt;换成更快的 Embedding 模型（如 &lt;code&gt;text-embedding-3-small&lt;/code&gt;）&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;Q4：中文效果不好？&#34;&gt;&lt;a href=&#34;#Q4：中文效果不好？&#34; class=&#34;headerlink&#34; title=&#34;Q4：中文效果不好？&#34;&gt;&lt;/a&gt;Q4：中文效果不好？&lt;/h3&gt;&lt;ul&gt;
&lt;li&gt;Embedding 模型选中文优化的（&lt;code&gt;bge-large-zh&lt;/code&gt;、&lt;code&gt;text-embedding-3&lt;/code&gt;、智谱 Embedding）&lt;/li&gt;
&lt;li&gt;LLM 选中文能力强的（DeepSeek、Qwen、GLM）&lt;/li&gt;
&lt;li&gt;分段时不要切断中文字符（Dify 默认会处理）&lt;/li&gt;
&lt;/ul&gt;
&lt;hr&gt;
&lt;h2 id=&#34;总结&#34;&gt;&lt;a href=&#34;#总结&#34; class=&#34;headerlink&#34; title=&#34;总结&#34;&gt;&lt;/a&gt;总结&lt;/h2&gt;&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;阶段&lt;/th&gt;
&lt;th&gt;你需要做什么&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;准备&lt;/td&gt;
&lt;td&gt;装 Docker、搞一个 LLM API Key&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;部署&lt;/td&gt;
&lt;td&gt;&lt;code&gt;docker compose up -d&lt;/code&gt; 一条命令&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;建知识库&lt;/td&gt;
&lt;td&gt;上传文档，调整分段参数&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;建应用&lt;/td&gt;
&lt;td&gt;关联知识库 + 写系统提示词&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;上线&lt;/td&gt;
&lt;td&gt;发布 → 生成链接&amp;#x2F;嵌入网页&amp;#x2F;API 调用&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;p&gt;整个流程从零到能用，新手一般 &lt;strong&gt;一个下午&lt;/strong&gt; 可以搞定。&lt;/p&gt;
&lt;p&gt;最后提醒一句：&lt;strong&gt;知识库的核心不是技术，是你的文档质量&lt;/strong&gt;。垃圾文档进 → 垃圾答案出。花时间整理好你的文档，比调任何参数都管用。&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Dify 官方文档：&lt;a href=&#34;https://docs.dify.ai/&#34;&gt;https://docs.dify.ai&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;Dify GitHub：&lt;a href=&#34;https://github.com/langgenius/dify&#34;&gt;https://github.com/langgenius/dify&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;Ollama（本地模型）：&lt;a href=&#34;https://ollama.com/&#34;&gt;https://ollama.com&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;

 &lt;h2 id=&#34;什么是-CC-Switch？&#34;&gt;&lt;a href=&#34;#什么是-CC-Switch？&#34; class=&#34;headerlink&#34; title=&#34;什么是 CC Switch？&#34;&gt;&lt;/a&gt;什么是 CC Switch？&lt;/h2&gt;&lt;p&gt;&lt;a href=&#34;https://github.com/farion1231/cc-switch&#34;&gt;CC Switch&lt;/a&gt; 是一款&lt;strong&gt;跨平台桌面应用&lt;/strong&gt;，一站式管理 Claude Code、Codex、Gemini CLI、OpenCode 和 OpenClaw 等多款 AI 编程助手。基于 Tauri 2 构建，支持 Windows &amp;#x2F; macOS &amp;#x2F; Linux，当前最新版本为 &lt;strong&gt;v3.14.1&lt;/strong&gt;。&lt;/p&gt;
&lt;p&gt;如果你同时使用多款 AI 编程工具——比如用 Claude Code 做架构设计、用 Codex 写代码、用 Gemini 做代码审查——CC Switch 能让你在一个统一的界面里切换、配置和管理它们，不用在多个终端窗口之间来回折腾。&lt;/p&gt;
&lt;h3 id=&#34;核心能力一览&#34;&gt;&lt;a href=&#34;#核心能力一览&#34; class=&#34;headerlink&#34; title=&#34;核心能力一览&#34;&gt;&lt;/a&gt;核心能力一览&lt;/h3&gt;&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;功能&lt;/th&gt;
&lt;th&gt;说明&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;🔄 多工具管理&lt;/td&gt;
&lt;td&gt;统一管理 Claude Code &amp;#x2F; Codex &amp;#x2F; Gemini CLI &amp;#x2F; OpenCode &amp;#x2F; OpenClaw&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;⚙️ 提供商切换&lt;/td&gt;
&lt;td&gt;支持 Anthropic 官方、AWS Bedrock、Google Vertex、Azure Foundry 及各类中转 API&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;📊 用量监控&lt;/td&gt;
&lt;td&gt;系统托盘实时显示各工具用量、订阅配额、颜色编码利用率&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;🔐 OAuth 反向代理&lt;/td&gt;
&lt;td&gt;内置 Codex OAuth 代理，支持 FAST 模式切换&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;🧩 Skills 管理&lt;/td&gt;
&lt;td&gt;导入、安装、更新各类 Agent Skills&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;📝 会话管理&lt;/td&gt;
&lt;td&gt;查看、恢复、切换各工具的历史会话&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;🌐 MCP 配置&lt;/td&gt;
&lt;td&gt;图形化管理 Model Context Protocol 服务器&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;🏠 Hermes 集成&lt;/td&gt;
&lt;td&gt;提供商管理、记忆编辑、Web UI 启动&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;hr&gt;
&lt;h2 id=&#34;安装指南&#34;&gt;&lt;a href=&#34;#安装指南&#34; class=&#34;headerlink&#34; title=&#34;安装指南&#34;&gt;&lt;/a&gt;安装指南&lt;/h2&gt;&lt;h3 id=&#34;下载安装包&#34;&gt;&lt;a href=&#34;#下载安装包&#34; class=&#34;headerlink&#34; title=&#34;下载安装包&#34;&gt;&lt;/a&gt;下载安装包&lt;/h3&gt;&lt;p&gt;访问 &lt;a href=&#34;https://github.com/farion1231/cc-switch/releases/latest&#34;&gt;Releases 页面&lt;/a&gt; 下载对应平台的安装包：&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;平台&lt;/th&gt;
&lt;th&gt;安装包格式&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;Windows&lt;/td&gt;
&lt;td&gt;&lt;code&gt;.msi&lt;/code&gt; 安装程序 &amp;#x2F; &lt;code&gt;.exe&lt;/code&gt; 便携版&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;macOS&lt;/td&gt;
&lt;td&gt;&lt;code&gt;.dmg&lt;/code&gt;（Apple Silicon &amp;#x2F; Intel）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Linux&lt;/td&gt;
&lt;td&gt;&lt;code&gt;.AppImage&lt;/code&gt; &amp;#x2F; &lt;code&gt;.deb&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;h3 id=&#34;Windows-安装&#34;&gt;&lt;a href=&#34;#Windows-安装&#34; class=&#34;headerlink&#34; title=&#34;Windows 安装&#34;&gt;&lt;/a&gt;Windows 安装&lt;/h3&gt;&lt;ol&gt;
&lt;li&gt;下载最新版 &lt;code&gt;.msi&lt;/code&gt; 安装包&lt;/li&gt;
&lt;li&gt;双击运行，按向导完成安装&lt;/li&gt;
&lt;li&gt;安装完成后，桌面和开始菜单会出现 CC Switch 图标&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;或者使用便携版（无需安装），直接运行 &lt;code&gt;.exe&lt;/code&gt;。&lt;/p&gt;
&lt;h3 id=&#34;macOS-安装&#34;&gt;&lt;a href=&#34;#macOS-安装&#34; class=&#34;headerlink&#34; title=&#34;macOS 安装&#34;&gt;&lt;/a&gt;macOS 安装&lt;/h3&gt;&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 下载 .dmg 后双击挂载，将 CC Switch 拖入 Applications&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 或通过 Homebrew（如有）&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;首次打开时，macOS 可能提示”无法验证开发者”，去&lt;strong&gt;系统设置 → 隐私与安全性&lt;/strong&gt;中点击”仍要打开”即可。&lt;/p&gt;
&lt;h3 id=&#34;Linux-安装&#34;&gt;&lt;a href=&#34;#Linux-安装&#34; class=&#34;headerlink&#34; title=&#34;Linux 安装&#34;&gt;&lt;/a&gt;Linux 安装&lt;/h3&gt;&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# AppImage（推荐）&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;chmod&lt;/span&gt; +x CC-Switch-*.AppImage&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;./CC-Switch-*.AppImage&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# deb 包&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;sudo dpkg -i cc-switch_*.deb&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;hr&gt;
&lt;h2 id=&#34;使用指南&#34;&gt;&lt;a href=&#34;#使用指南&#34; class=&#34;headerlink&#34; title=&#34;使用指南&#34;&gt;&lt;/a&gt;使用指南&lt;/h2&gt;&lt;h3 id=&#34;1-初始配置&#34;&gt;&lt;a href=&#34;#1-初始配置&#34; class=&#34;headerlink&#34; title=&#34;1. 初始配置&#34;&gt;&lt;/a&gt;1. 初始配置&lt;/h3&gt;&lt;p&gt;首次打开 CC Switch 后，你会看到主界面。左侧是工具列表（Claude Code &amp;#x2F; Codex &amp;#x2F; Gemini CLI 等），右侧是配置面板。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;第一步：添加 AI 工具&lt;/strong&gt;&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;点击左侧工具图标（如 Claude Code）&lt;/li&gt;
&lt;li&gt;在右侧面板中配置：&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;提供商&lt;/strong&gt;：选择 Anthropic（官方）&amp;#x2F; Bedrock &amp;#x2F; Vertex &amp;#x2F; 自定义 API 中转&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;API 地址&lt;/strong&gt;：如果用中转服务，填入对应的 &lt;code&gt;ANTHROPIC_BASE_URL&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;API Key&lt;/strong&gt;：填入你的密钥&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;模型&lt;/strong&gt;：选择默认使用的模型&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;点击「测试连接」确认配置正确&lt;/li&gt;
&lt;li&gt;点击「保存」&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;CC Switch 支持&lt;strong&gt;同时配置多个提供商&lt;/strong&gt;，你可以为 Claude Code 配一个 Anthropic 官方、一个 Bedrock、一个便宜的中转站，随时切换。&lt;/p&gt;
&lt;h3 id=&#34;2-切换工具和提供商&#34;&gt;&lt;a href=&#34;#2-切换工具和提供商&#34; class=&#34;headerlink&#34; title=&#34;2. 切换工具和提供商&#34;&gt;&lt;/a&gt;2. 切换工具和提供商&lt;/h3&gt;&lt;p&gt;在左侧工具栏点击对应图标即可切换不同的 AI 编程工具。&lt;/p&gt;
&lt;p&gt;对于同一工具的不同提供商，在主界面顶部或设置面板的提供商下拉菜单中一键切换。CC Switch 会自动更新对应的环境变量和配置文件。&lt;/p&gt;
&lt;h3 id=&#34;3-启动对话会话&#34;&gt;&lt;a href=&#34;#3-启动对话会话&#34; class=&#34;headerlink&#34; title=&#34;3. 启动对话会话&#34;&gt;&lt;/a&gt;3. 启动对话会话&lt;/h3&gt;&lt;p&gt;配置好工具后，可以：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;直接启动&lt;/strong&gt;：点击「启动」按钮，CC Switch 会在新终端窗口中打开对应工具&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;恢复历史会话&lt;/strong&gt;：在会话列表中双击之前的会话，自动恢复到上次的对话状态&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;继续最近会话&lt;/strong&gt;：点击工具旁边的「继续」图标&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;对于 Gemini CLI，CC Switch 会读取 &lt;code&gt;.project_root&lt;/code&gt; 元数据，确保恢复到正确的项目目录。&lt;/p&gt;
&lt;h3 id=&#34;4-用量监控（系统托盘）&#34;&gt;&lt;a href=&#34;#4-用量监控（系统托盘）&#34; class=&#34;headerlink&#34; title=&#34;4. 用量监控（系统托盘）&#34;&gt;&lt;/a&gt;4. 用量监控（系统托盘）&lt;/h3&gt;&lt;p&gt;CC Switch 最小化后会驻留在系统托盘中，右键托盘图标可以看到：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;当前工具的用量概览&lt;/strong&gt;：Claude &amp;#x2F; Codex &amp;#x2F; Gemini 各自的消耗情况&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;订阅配额摘要&lt;/strong&gt;：显示配额的百分比和颜色标记（🟢 正常 &amp;#x2F; 🟡 警告 &amp;#x2F; 🔴 耗尽）&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;用量脚本摘要&lt;/strong&gt;：基于自定义 usage_script 的详细统计&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;对于国内的 Kimi &amp;#x2F; 智谱 &amp;#x2F; MiniMax 等编码套餐，托盘还会显示 &lt;strong&gt;5 小时 + 周度&lt;/strong&gt;双窗口用量，格式类似 &lt;code&gt;🟢 h12% w80%&lt;/code&gt;。&lt;/p&gt;
&lt;h3 id=&#34;5-Skills（技能）管理&#34;&gt;&lt;a href=&#34;#5-Skills（技能）管理&#34; class=&#34;headerlink&#34; title=&#34;5. Skills（技能）管理&#34;&gt;&lt;/a&gt;5. Skills（技能）管理&lt;/h3&gt;&lt;p&gt;CC Switch 内置了 Skills 管理功能，可以导入和安装社区分享的 Agent Skills：&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;进入 Skills 管理页面&lt;/li&gt;
&lt;li&gt;点击「导入」→ 输入 Skills 的 GitHub URL&lt;/li&gt;
&lt;li&gt;CC Switch 自动下载并安装到对应工具的配置目录&lt;/li&gt;
&lt;li&gt;支持一键更新已安装的 Skills&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;导入过程中会自动去重，防止重复安装。&lt;/p&gt;
&lt;h3 id=&#34;6-MCP-服务器配置&#34;&gt;&lt;a href=&#34;#6-MCP-服务器配置&#34; class=&#34;headerlink&#34; title=&#34;6. MCP 服务器配置&#34;&gt;&lt;/a&gt;6. MCP 服务器配置&lt;/h3&gt;&lt;p&gt;在 MCP 配置页面，你可以图形化管理 Model Context Protocol 服务器：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;添加新的 MCP 服务器（本地或远程）&lt;/li&gt;
&lt;li&gt;配置环境变量和启动参数&lt;/li&gt;
&lt;li&gt;测试 MCP 连接状态&lt;/li&gt;
&lt;li&gt;一键启用&amp;#x2F;禁用特定服务器&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;7-Hermes-集成&#34;&gt;&lt;a href=&#34;#7-Hermes-集成&#34; class=&#34;headerlink&#34; title=&#34;7. Hermes 集成&#34;&gt;&lt;/a&gt;7. Hermes 集成&lt;/h3&gt;&lt;p&gt;Hermes 是 CC Switch 内置的配置管理中心：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;提供商展示&lt;/strong&gt;：查看所有已配置的 AI 提供商&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;默认切换&lt;/strong&gt;：设置默认使用的提供商&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;记忆编辑&lt;/strong&gt;：编辑 Agent 的持久化记忆&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Web UI 启动&lt;/strong&gt;：一键跳转到 Hermes Web 控制台，进行深度配置&lt;/li&gt;
&lt;/ul&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;注意&lt;/strong&gt;：v3.14.1 起移除了应用内的 Hermes 配置健康扫描功能，深度配置诊断请使用 Hermes Web UI。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;hr&gt;
&lt;h2 id=&#34;Codex-OAuth-反向代理&#34;&gt;&lt;a href=&#34;#Codex-OAuth-反向代理&#34; class=&#34;headerlink&#34; title=&#34;Codex OAuth 反向代理&#34;&gt;&lt;/a&gt;Codex OAuth 反向代理&lt;/h2&gt;&lt;p&gt;CC Switch 内置了 Codex OAuth 反向代理功能，主要特性：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;缓存路由&lt;/strong&gt;：使用客户端提供的会话 ID 作为缓存键，保持缓存一致性&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;FAST 模式&lt;/strong&gt;：可选择开启 &lt;code&gt;service_tier=&amp;quot;priority&amp;quot;&lt;/code&gt;，降低延迟（会消耗更多 ChatGPT 配额，默认关闭）&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Stream Check&lt;/strong&gt;：代理请求使用与实际请求相同的配置参数，确保连接测试结果与实际使用一致&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;SSE 聚合&lt;/strong&gt;：非流式请求也能正确处理上游的 SSE 响应&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;在 Codex 提供商的设置面板中，可以找到 OAuth 代理的开关和 FAST 模式选项。&lt;/p&gt;
&lt;hr&gt;
&lt;h2 id=&#34;常见问题&#34;&gt;&lt;a href=&#34;#常见问题&#34; class=&#34;headerlink&#34; title=&#34;常见问题&#34;&gt;&lt;/a&gt;常见问题&lt;/h2&gt;&lt;h3 id=&#34;Q-CC-Switch-收费吗？&#34;&gt;&lt;a href=&#34;#Q-CC-Switch-收费吗？&#34; class=&#34;headerlink&#34; title=&#34;Q: CC Switch 收费吗？&#34;&gt;&lt;/a&gt;Q: CC Switch 收费吗？&lt;/h3&gt;&lt;p&gt;完全免费开源（MIT 协议），从 &lt;a href=&#34;https://github.com/farion1231/cc-switch/releases&#34;&gt;GitHub Release&lt;/a&gt; 直接下载。&lt;/p&gt;
&lt;h3 id=&#34;Q-需要自己安装-Claude-Code-Codex-Gemini-CLI-吗？&#34;&gt;&lt;a href=&#34;#Q-需要自己安装-Claude-Code-Codex-Gemini-CLI-吗？&#34; class=&#34;headerlink&#34; title=&#34;Q: 需要自己安装 Claude Code &amp;#x2F; Codex &amp;#x2F; Gemini CLI 吗？&#34;&gt;&lt;/a&gt;Q: 需要自己安装 Claude Code &amp;#x2F; Codex &amp;#x2F; Gemini CLI 吗？&lt;/h3&gt;&lt;p&gt;需要。CC Switch 是管理工具，不是这些 AI 工具本身的安装器。请确保你要使用的工具已经安装在系统中。&lt;/p&gt;
&lt;h3 id=&#34;Q-支持哪些-API-中转服务？&#34;&gt;&lt;a href=&#34;#Q-支持哪些-API-中转服务？&#34; class=&#34;headerlink&#34; title=&#34;Q: 支持哪些 API 中转服务？&#34;&gt;&lt;/a&gt;Q: 支持哪些 API 中转服务？&lt;/h3&gt;&lt;p&gt;CC Switch 本身不限制中转服务。任何兼容 Anthropic &amp;#x2F; OpenAI 接口规范的中转 API 都可以配置使用。项目 README 中列出了一批赞助商（PackyCode、AIGoCode、Cubence、Crazyrouter 等），使用 CC Switch 专属优惠码充值有折扣。&lt;/p&gt;
&lt;h3 id=&#34;Q-数据安全吗？&#34;&gt;&lt;a href=&#34;#Q-数据安全吗？&#34; class=&#34;headerlink&#34; title=&#34;Q: 数据安全吗？&#34;&gt;&lt;/a&gt;Q: 数据安全吗？&lt;/h3&gt;&lt;p&gt;CC Switch 是本地桌面应用，所有配置和密钥保存在本地，不会上传到任何服务器。OAuth 代理也在本地运行。&lt;/p&gt;
&lt;hr&gt;
&lt;h2 id=&#34;总结&#34;&gt;&lt;a href=&#34;#总结&#34; class=&#34;headerlink&#34; title=&#34;总结&#34;&gt;&lt;/a&gt;总结&lt;/h2&gt;&lt;p&gt;CC Switch 解决了一个真实痛点：&lt;strong&gt;开发者同时使用多款 AI 编程工具时的管理混乱&lt;/strong&gt;。它把 Claude Code、Codex、Gemini CLI 等工具的配置、切换、监控、会话管理都整合到了一个桌面应用里，配合系统托盘用量监控和 Skills&amp;#x2F;MCP 管理，是目前这个细分领域最成熟的工具之一。&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;GitHub：&lt;a href=&#34;https://github.com/farion1231/cc-switch&#34;&gt;https://github.com/farion1231/cc-switch&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;最新版本：v3.14.1（2026-04-23）&lt;/li&gt;
&lt;li&gt;协议：MIT 开源&lt;/li&gt;
&lt;/ul&gt;

 &lt;h2 id=&#34;什么是-Claude-Code？&#34;&gt;&lt;a href=&#34;#什么是-Claude-Code？&#34; class=&#34;headerlink&#34; title=&#34;什么是 Claude Code？&#34;&gt;&lt;/a&gt;什么是 Claude Code？&lt;/h2&gt;&lt;p&gt;Claude Code 是 Anthropic 推出的&lt;strong&gt;智能编程助手&lt;/strong&gt;，以大语言模型为驱动，能够理解代码库、编辑文件、运行终端命令，并深度集成到你的开发流程中。它不仅仅是一个聊天窗口——它能直接在代码上下文里帮你分析问题、重构代码、调试错误，甚至自动化重复任务。&lt;/p&gt;
&lt;p&gt;目前 Claude Code 支持四种使用形态：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;终端 CLI&lt;/strong&gt;：在命令行中直接使用&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Desktop 桌面应用&lt;/strong&gt;：macOS &amp;#x2F; Windows 独立应用&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;VS Code 扩展&lt;/strong&gt;：在编辑器中侧栏对话&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;JetBrains 插件&lt;/strong&gt;：支持 IntelliJ、PyCharm、WebStorm 等&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;安装指南&#34;&gt;&lt;a href=&#34;#安装指南&#34; class=&#34;headerlink&#34; title=&#34;安装指南&#34;&gt;&lt;/a&gt;安装指南&lt;/h2&gt;&lt;h3 id=&#34;macOS-Linux-终端安装&#34;&gt;&lt;a href=&#34;#macOS-Linux-终端安装&#34; class=&#34;headerlink&#34; title=&#34;macOS &amp;#x2F; Linux 终端安装&#34;&gt;&lt;/a&gt;macOS &amp;#x2F; Linux 终端安装&lt;/h3&gt;&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 官方一键安装脚本&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;curl -fsSL https://claude.ai/install.sh | bash&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 或通过 Homebrew 安装&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;brew install --cask claude-code&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h3 id=&#34;Windows-终端安装&#34;&gt;&lt;a href=&#34;#Windows-终端安装&#34; class=&#34;headerlink&#34; title=&#34;Windows 终端安装&#34;&gt;&lt;/a&gt;Windows 终端安装&lt;/h3&gt;&lt;figure class=&#34;highlight powershell&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# PowerShell 中执行&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;irm&lt;/span&gt; https://claude.ai/install.ps1 | &lt;span class=&#34;built_in&#34;&gt;iex&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 或通过 WinGet 安装&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;winget install Anthropic.ClaudeCode&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;如果使用 CMD 命令行：&lt;/p&gt;
&lt;figure class=&#34;highlight cmd&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;curl -fsSL https://claude.ai/install.&lt;span class=&#34;built_in&#34;&gt;cmd&lt;/span&gt; -o install.&lt;span class=&#34;built_in&#34;&gt;cmd&lt;/span&gt; &amp;amp;&amp;amp; install.&lt;span class=&#34;built_in&#34;&gt;cmd&lt;/span&gt; &amp;amp;&amp;amp; &lt;span class=&#34;built_in&#34;&gt;del&lt;/span&gt; install.&lt;span class=&#34;built_in&#34;&gt;cmd&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h3 id=&#34;VS-Code-插件安装&#34;&gt;&lt;a href=&#34;#VS-Code-插件安装&#34; class=&#34;headerlink&#34; title=&#34;VS Code 插件安装&#34;&gt;&lt;/a&gt;VS Code 插件安装&lt;/h3&gt;&lt;p&gt;直接在 VS Code 扩展商店搜索 &lt;strong&gt;“Claude Code”&lt;/strong&gt;，或通过命令行安装：&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;code --install-extension anthropic.claude-code&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h3 id=&#34;JetBrains-IDE-安装&#34;&gt;&lt;a href=&#34;#JetBrains-IDE-安装&#34; class=&#34;headerlink&#34; title=&#34;JetBrains IDE 安装&#34;&gt;&lt;/a&gt;JetBrains IDE 安装&lt;/h3&gt;&lt;p&gt;在 JetBrains 插件市场搜索 &lt;strong&gt;“Claude Code”&lt;/strong&gt; 安装即可，支持 IntelliJ IDEA、PyCharm、WebStorm 等主流 IDE。&lt;/p&gt;
&lt;h2 id=&#34;初次配置&#34;&gt;&lt;a href=&#34;#初次配置&#34; class=&#34;headerlink&#34; title=&#34;初次配置&#34;&gt;&lt;/a&gt;初次配置&lt;/h2&gt;&lt;p&gt;安装完成后，第一次启动需要完成以下配置：&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;1. 认证&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Claude Code 使用 Anthropic API Key 进行身份认证。如果你已有账号，可通过如下方式设置：&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 设置环境变量&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;export&lt;/span&gt; ANTHROPIC_API_KEY=&lt;span class=&#34;string&#34;&gt;&amp;quot;your-api-key-here&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;也可以在首次运行 Claude Code 时，按照提示完成 OAuth 认证流程。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;2. 选择模型&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Claude Code 支持多种底层模型提供商：&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;提供商&lt;/th&gt;
&lt;th&gt;模型&lt;/th&gt;
&lt;th&gt;适用场景&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;Anthropic&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Claude Sonnet &amp;#x2F; Opus&lt;/td&gt;
&lt;td&gt;默认推荐，通用开发&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;Amazon Bedrock&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Claude 系列&lt;/td&gt;
&lt;td&gt;AWS 用户可管控数据&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;Google Vertex AI&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Claude 系列&lt;/td&gt;
&lt;td&gt;GCP 用户可管控数据&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;Microsoft Foundry&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Claude 系列&lt;/td&gt;
&lt;td&gt;Azure 用户可管控数据&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;p&gt;如果不做特殊配置，默认使用 Anthropic 直连。&lt;/p&gt;
&lt;h2 id=&#34;基本使用&#34;&gt;&lt;a href=&#34;#基本使用&#34; class=&#34;headerlink&#34; title=&#34;基本使用&#34;&gt;&lt;/a&gt;基本使用&lt;/h2&gt;&lt;h3 id=&#34;终端模式&#34;&gt;&lt;a href=&#34;#终端模式&#34; class=&#34;headerlink&#34; title=&#34;终端模式&#34;&gt;&lt;/a&gt;终端模式&lt;/h3&gt;&lt;p&gt;安装后在任何项目目录中运行：&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;claude&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;进入交互式会话后，你可以用自然语言描述需求，比如：&lt;/p&gt;
&lt;figure class=&#34;highlight node-repl&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;meta prompt_&#34;&gt;&amp;gt;&lt;/span&gt; &lt;span class=&#34;language-javascript&#34;&gt;帮我把这个函数的异常处理加上重试逻辑&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;meta prompt_&#34;&gt;&amp;gt;&lt;/span&gt; &lt;span class=&#34;language-javascript&#34;&gt;这段代码有 bug，帮我定位一下&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;meta prompt_&#34;&gt;&amp;gt;&lt;/span&gt; &lt;span class=&#34;language-javascript&#34;&gt;生成这个 &lt;span class=&#34;variable constant_&#34;&gt;API&lt;/span&gt; 的单元测试&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;Claude Code 会读取当前项目的文件，理解代码结构后给出修改建议或直接编辑文件。&lt;/p&gt;
&lt;h3 id=&#34;VS-Code-模式&#34;&gt;&lt;a href=&#34;#VS-Code-模式&#34; class=&#34;headerlink&#34; title=&#34;VS Code 模式&#34;&gt;&lt;/a&gt;VS Code 模式&lt;/h3&gt;&lt;p&gt;在 VS Code 中打开 Claude Code 侧栏（快捷键 &lt;code&gt;Ctrl+Shift+P&lt;/code&gt; → &lt;code&gt;Claude Code: Open&lt;/code&gt;），即可在编辑器中对话。VS Code 模式下，你还可以：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;直接 @ 引用文件&lt;/li&gt;
&lt;li&gt;用 &lt;code&gt;/&lt;/code&gt; 唤起快捷指令&lt;/li&gt;
&lt;li&gt;通过 diff 预览代码变更&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;常用指令速查&#34;&gt;&lt;a href=&#34;#常用指令速查&#34; class=&#34;headerlink&#34; title=&#34;常用指令速查&#34;&gt;&lt;/a&gt;常用指令速查&lt;/h3&gt;&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;指令&lt;/th&gt;
&lt;th&gt;说明&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;&lt;code&gt;claude&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;启动交互式会话&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;claude &amp;quot;你的问题&amp;quot;&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;一次性问答模式&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;claude --file path/to/file&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;针对特定文件分析&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;claude --print&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;非交互模式，输出到标准输出&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;claude commit&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;自动生成 commit message&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;h3 id=&#34;上下文管理&#34;&gt;&lt;a href=&#34;#上下文管理&#34; class=&#34;headerlink&#34; title=&#34;上下文管理&#34;&gt;&lt;/a&gt;上下文管理&lt;/h3&gt;&lt;p&gt;Claude Code 会自动分析你的项目结构。你也可以手动管理上下文：&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 添加文件到上下文&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;/extra *.ts src/&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 查看当前上下文&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;/context&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;&lt;strong&gt;提示&lt;/strong&gt;：上下文窗口有限，建议一次不要包含太多无关文件，保持问题和代码集中。&lt;/p&gt;
&lt;h2 id=&#34;核心功能&#34;&gt;&lt;a href=&#34;#核心功能&#34; class=&#34;headerlink&#34; title=&#34;核心功能&#34;&gt;&lt;/a&gt;核心功能&lt;/h2&gt;&lt;h3 id=&#34;1-代码生成与修改&#34;&gt;&lt;a href=&#34;#1-代码生成与修改&#34; class=&#34;headerlink&#34; title=&#34;1. 代码生成与修改&#34;&gt;&lt;/a&gt;1. 代码生成与修改&lt;/h3&gt;&lt;p&gt;Claude Code 不仅能生成新代码，还能深度理解现有代码并给出修改建议。它会：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;读取项目文件和目录结构&lt;/li&gt;
&lt;li&gt;理解代码的风格和惯例&lt;/li&gt;
&lt;li&gt;直接编辑文件并展示 diff&lt;/li&gt;
&lt;li&gt;按你的要求运行测试验证&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;2-代码审查（Code-Review）&#34;&gt;&lt;a href=&#34;#2-代码审查（Code-Review）&#34; class=&#34;headerlink&#34; title=&#34;2. 代码审查（Code Review）&#34;&gt;&lt;/a&gt;2. 代码审查（Code Review）&lt;/h3&gt;&lt;p&gt;你可以让 Claude Code 审查你的 PR 或某段代码：&lt;/p&gt;
&lt;figure class=&#34;highlight node-repl&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;meta prompt_&#34;&gt;&amp;gt;&lt;/span&gt; &lt;span class=&#34;language-javascript&#34;&gt;&lt;span class=&#34;title class_&#34;&gt;Review&lt;/span&gt; the changes &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; src/utils.&lt;span class=&#34;property&#34;&gt;ts&lt;/span&gt; and suggest improvements&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;它会给出具体的改进建议，涵盖逻辑、安全性、性能、代码风格等方面。&lt;/p&gt;
&lt;h3 id=&#34;3-调试辅助&#34;&gt;&lt;a href=&#34;#3-调试辅助&#34; class=&#34;headerlink&#34; title=&#34;3. 调试辅助&#34;&gt;&lt;/a&gt;3. 调试辅助&lt;/h3&gt;&lt;p&gt;粘贴错误信息，Claude Code 能帮你追踪根因：&lt;/p&gt;
&lt;figure class=&#34;highlight node-repl&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;meta prompt_&#34;&gt;&amp;gt;&lt;/span&gt; &lt;span class=&#34;language-javascript&#34;&gt;运行 npm test 时报了这个错：&lt;span class=&#34;title class_&#34;&gt;TypeError&lt;/span&gt;: &lt;span class=&#34;title class_&#34;&gt;Cannot&lt;/span&gt; read properties &lt;span class=&#34;keyword&#34;&gt;of&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;undefined&lt;/span&gt;...&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;meta prompt_&#34;&gt;&amp;gt;&lt;/span&gt; &lt;span class=&#34;language-javascript&#34;&gt;帮我看下是在哪里引入的&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;它会读取相关代码，定位问题并给出修复方案。&lt;/p&gt;
&lt;h3 id=&#34;4-Git-操作&#34;&gt;&lt;a href=&#34;#4-Git-操作&#34; class=&#34;headerlink&#34; title=&#34;4. Git 操作&#34;&gt;&lt;/a&gt;4. Git 操作&lt;/h3&gt;&lt;p&gt;Claude Code 与 Git 深度集成：&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 生成提交信息&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;claude commit&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 解释最近变更&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;gt; 帮我解释下最近 3 次 commit 做了什么&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h3 id=&#34;5-终端命令执行&#34;&gt;&lt;a href=&#34;#5-终端命令执行&#34; class=&#34;headerlink&#34; title=&#34;5. 终端命令执行&#34;&gt;&lt;/a&gt;5. 终端命令执行&lt;/h3&gt;&lt;p&gt;你可以让 Claude Code 代劳执行命令：&lt;/p&gt;
&lt;figure class=&#34;highlight node-repl&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;meta prompt_&#34;&gt;&amp;gt;&lt;/span&gt; &lt;span class=&#34;language-javascript&#34;&gt;帮我查下当前机器上哪个进程占了 &lt;span class=&#34;number&#34;&gt;8080&lt;/span&gt; 端口&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;meta prompt_&#34;&gt;&amp;gt;&lt;/span&gt; &lt;span class=&#34;language-javascript&#34;&gt;把这个项目跑起来&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;它会根据系统环境选择合适的命令并执行。&lt;/p&gt;
&lt;h2 id=&#34;实战示例&#34;&gt;&lt;a href=&#34;#实战示例&#34; class=&#34;headerlink&#34; title=&#34;实战示例&#34;&gt;&lt;/a&gt;实战示例&lt;/h2&gt;&lt;h3 id=&#34;场景一：为新功能写代码&#34;&gt;&lt;a href=&#34;#场景一：为新功能写代码&#34; class=&#34;headerlink&#34; title=&#34;场景一：为新功能写代码&#34;&gt;&lt;/a&gt;场景一：为新功能写代码&lt;/h3&gt;&lt;figure class=&#34;highlight text&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&amp;gt; 我现在要增加一个用户登录接口，使用 Express + JWT，按照项目现有风格来写。&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;Claude Code 会读取项目现有结构，按照一致的风格生成路由、中间件、错误处理。&lt;/p&gt;
&lt;h3 id=&#34;场景二：重构旧代码&#34;&gt;&lt;a href=&#34;#场景二：重构旧代码&#34; class=&#34;headerlink&#34; title=&#34;场景二：重构旧代码&#34;&gt;&lt;/a&gt;场景二：重构旧代码&lt;/h3&gt;&lt;figure class=&#34;highlight text&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&amp;gt; 帮我把这个回调地狱的代码改成 async/await 风格，别改逻辑。&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h3 id=&#34;场景三：写测试&#34;&gt;&lt;a href=&#34;#场景三：写测试&#34; class=&#34;headerlink&#34; title=&#34;场景三：写测试&#34;&gt;&lt;/a&gt;场景三：写测试&lt;/h3&gt;&lt;figure class=&#34;highlight text&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&amp;gt; 帮我把 src/service/order.ts 里的所有公开方法写一遍单元测试。&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h2 id=&#34;常见问题&#34;&gt;&lt;a href=&#34;#常见问题&#34; class=&#34;headerlink&#34; title=&#34;常见问题&#34;&gt;&lt;/a&gt;常见问题&lt;/h2&gt;&lt;p&gt;&lt;strong&gt;Q: Claude Code 免费吗？&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Claude Code 工具本身免费使用，但需要有效的 Anthropic API Key（付费）。API 费用取决于使用的模型和 token 量。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Q: 支持哪些语言？&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;几乎全部主流语言：JavaScript &amp;#x2F; TypeScript、Python、Java、Go、Rust、C&amp;#x2F;C++、SQL 等，前端后端通吃。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Q: 代码安全吗？&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;通过 Anthropic 直连时，代码会发送到 Anthropic 服务器处理。如果对数据安全有更高要求，可以使用 Amazon Bedrock 或 Google Vertex AI 等企业级部署方案，数据不离开你的云环境。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Q: 和 GitHub Copilot 有什么区别？&lt;/strong&gt;&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;对比维度&lt;/th&gt;
&lt;th&gt;Claude Code&lt;/th&gt;
&lt;th&gt;GitHub Copilot&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;工作方式&lt;/td&gt;
&lt;td&gt;对话式 Agent，可读整个项目&lt;/td&gt;
&lt;td&gt;以代码补全为主+聊天&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;上下文范围&lt;/td&gt;
&lt;td&gt;整个代码库&lt;/td&gt;
&lt;td&gt;当前文件 + 少量上下文&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;编辑方式&lt;/td&gt;
&lt;td&gt;直接修改文件&lt;/td&gt;
&lt;td&gt;建议片段&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;命令执行&lt;/td&gt;
&lt;td&gt;✅ 可执行终端命令&lt;/td&gt;
&lt;td&gt;❌ 不支持&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;p&gt;两者的定位不同：Copilot 更侧重于实时编码时的行级补全，Claude Code 更像一个能帮你完成整个任务的开发搭档。&lt;/p&gt;
&lt;h2 id=&#34;小结&#34;&gt;&lt;a href=&#34;#小结&#34; class=&#34;headerlink&#34; title=&#34;小结&#34;&gt;&lt;/a&gt;小结&lt;/h2&gt;&lt;p&gt;Claude Code 是目前 AI 编程工具中能力最为全面的一款，从代码生成、审查、调试到 Git 操作一应俱全。它真正的价值在于&lt;strong&gt;深度理解你的项目&lt;/strong&gt;，而不是简单拼接代码片段。&lt;/p&gt;
&lt;p&gt;如果你还没试过，不妨装一个，让它帮你处理那些重复又耗神的编码工作，把精力留给真正需要思考的事。&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;进一步阅读：&lt;/strong&gt; &lt;a href=&#34;https://code.claude.com/docs/en/overview&#34;&gt;Claude Code 官方文档&lt;/a&gt; | &lt;a href=&#34;https://marketplace.visualstudio.com/items?itemName=anthropic.claude-code&#34;&gt;VS Code 插件&lt;/a&gt;&lt;/p&gt;
&lt;/blockquote&gt;

 &lt;h2 id=&#34;异常层次结构&#34;&gt;&lt;a href=&#34;#异常层次结构&#34; class=&#34;headerlink&#34; title=&#34;异常层次结构&#34;&gt;&lt;/a&gt;异常层次结构&lt;/h2&gt;&lt;p&gt;Java 中所有异常都继承自 &lt;code&gt;Throwable&lt;/code&gt; 类，分为两大分支：&lt;strong&gt;Error&lt;/strong&gt; 和 &lt;strong&gt;Exception&lt;/strong&gt;。&lt;/p&gt;
&lt;figure class=&#34;highlight scss&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;Throwable&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── Error (系统级错误，不可处理)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── OutOfMemoryError&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── StackOverflowError&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   └── NoClassDefFoundError&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;└── Exception (程序级异常，可处理)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    ├── IOException (受检异常)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    ├── SQLException (受检异常)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    └── RuntimeException (非受检异常)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        ├── NullPointerException&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        ├── ArrayIndexOutOfBoundsException&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        ├── ClassCastException&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        └── IllegalArgumentException&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Error&lt;/strong&gt;：JVM 层面的错误，程序无法处理，也不应尝试捕获&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Exception&lt;/strong&gt;：程序可以捕获并处理的异常&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;受检异常-vs-非受检异常&#34;&gt;&lt;a href=&#34;#受检异常-vs-非受检异常&#34; class=&#34;headerlink&#34; title=&#34;受检异常 vs 非受检异常&#34;&gt;&lt;/a&gt;受检异常 vs 非受检异常&lt;/h2&gt;&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;类型&lt;/th&gt;
&lt;th&gt;父类&lt;/th&gt;
&lt;th&gt;编译器检查&lt;/th&gt;
&lt;th&gt;典型场景&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;受检异常 (Checked)&lt;/td&gt;
&lt;td&gt;Exception (非 RuntimeException)&lt;/td&gt;
&lt;td&gt;必须显式处理&lt;/td&gt;
&lt;td&gt;IO操作、数据库操作&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;非受检异常 (Unchecked)&lt;/td&gt;
&lt;td&gt;RuntimeException&lt;/td&gt;
&lt;td&gt;不强制处理&lt;/td&gt;
&lt;td&gt;空指针、数组越界&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;figure class=&#34;highlight java&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;// 受检异常：必须 try-catch 或 throws&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;public&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;void&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;readFile&lt;/span&gt;&lt;span class=&#34;params&#34;&gt;(String path)&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;throws&lt;/span&gt; IOException &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;type&#34;&gt;FileReader&lt;/span&gt; &lt;span class=&#34;variable&#34;&gt;reader&lt;/span&gt; &lt;span class=&#34;operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;new&lt;/span&gt; &lt;span class=&#34;title class_&#34;&gt;FileReader&lt;/span&gt;(path);&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;// 非受检异常：编译器不强制要求处理&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;public&lt;/span&gt; &lt;span class=&#34;type&#34;&gt;int&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;divide&lt;/span&gt;&lt;span class=&#34;params&#34;&gt;(&lt;span class=&#34;type&#34;&gt;int&lt;/span&gt; a, &lt;span class=&#34;type&#34;&gt;int&lt;/span&gt; b)&lt;/span&gt; &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; a / b; &lt;span class=&#34;comment&#34;&gt;// 如果 b=0 抛出 ArithmeticException&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h2 id=&#34;try-catch-finally&#34;&gt;&lt;a href=&#34;#try-catch-finally&#34; class=&#34;headerlink&#34; title=&#34;try-catch-finally&#34;&gt;&lt;/a&gt;try-catch-finally&lt;/h2&gt;&lt;p&gt;最基础的异常处理结构：&lt;/p&gt;
&lt;figure class=&#34;highlight java&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;public&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;void&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;demo&lt;/span&gt;&lt;span class=&#34;params&#34;&gt;()&lt;/span&gt; &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;try&lt;/span&gt; &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;type&#34;&gt;int&lt;/span&gt;[] arr = &lt;span class=&#34;keyword&#34;&gt;new&lt;/span&gt; &lt;span class=&#34;title class_&#34;&gt;int&lt;/span&gt;[&lt;span class=&#34;number&#34;&gt;5&lt;/span&gt;];&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        arr[&lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;] = &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;;                    &lt;span class=&#34;comment&#34;&gt;// 抛出异常&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &amp;#125; &lt;span class=&#34;keyword&#34;&gt;catch&lt;/span&gt; (ArrayIndexOutOfBoundsException e) &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        System.out.println(&lt;span class=&#34;string&#34;&gt;&amp;quot;数组越界：&amp;quot;&lt;/span&gt; + e.getMessage());&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &amp;#125; &lt;span class=&#34;keyword&#34;&gt;finally&lt;/span&gt; &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        System.out.println(&lt;span class=&#34;string&#34;&gt;&amp;quot;无论如何都会执行&amp;quot;&lt;/span&gt;);&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;&lt;strong&gt;多个 catch 块&lt;/strong&gt;的匹配规则：从上到下匹配，子类异常必须写在父类异常前面：&lt;/p&gt;
&lt;figure class=&#34;highlight java&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;try&lt;/span&gt; &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;// 业务代码&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125; &lt;span class=&#34;keyword&#34;&gt;catch&lt;/span&gt; (FileNotFoundException e) &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;// 子类异常在前&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125; &lt;span class=&#34;keyword&#34;&gt;catch&lt;/span&gt; (IOException e) &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;// 父类异常在后&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125; &lt;span class=&#34;keyword&#34;&gt;catch&lt;/span&gt; (Exception e) &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;// 兜底&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;&lt;strong&gt;finally 的执行时机&lt;/strong&gt;——即使在 try 或 catch 中执行了 return，finally 仍会执行：&lt;/p&gt;
&lt;figure class=&#34;highlight java&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;public&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;static&lt;/span&gt; &lt;span class=&#34;type&#34;&gt;int&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;test&lt;/span&gt;&lt;span class=&#34;params&#34;&gt;()&lt;/span&gt; &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;try&lt;/span&gt; &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &amp;#125; &lt;span class=&#34;keyword&#34;&gt;finally&lt;/span&gt; &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        System.out.println(&lt;span class=&#34;string&#34;&gt;&amp;quot;finally 执行了&amp;quot;&lt;/span&gt;);&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;// 输出：finally 执行了&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;// 返回值：1&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;唯一不执行 finally 的情况：调用了 &lt;code&gt;System.exit(0)&lt;/code&gt; 或 JVM 崩溃。&lt;/p&gt;
&lt;h2 id=&#34;try-with-resources-JDK-7&#34;&gt;&lt;a href=&#34;#try-with-resources-JDK-7&#34; class=&#34;headerlink&#34; title=&#34;try-with-resources (JDK 7+)&#34;&gt;&lt;/a&gt;try-with-resources (JDK 7+)&lt;/h2&gt;&lt;p&gt;自动关闭实现了 &lt;code&gt;AutoCloseable&lt;/code&gt; 接口的资源，无需手动写 finally：&lt;/p&gt;
&lt;figure class=&#34;highlight java&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;// 传统方式&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;type&#34;&gt;BufferedReader&lt;/span&gt; &lt;span class=&#34;variable&#34;&gt;br&lt;/span&gt; &lt;span class=&#34;operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;null&lt;/span&gt;;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;try&lt;/span&gt; &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    br = &lt;span class=&#34;keyword&#34;&gt;new&lt;/span&gt; &lt;span class=&#34;title class_&#34;&gt;BufferedReader&lt;/span&gt;(&lt;span class=&#34;keyword&#34;&gt;new&lt;/span&gt; &lt;span class=&#34;title class_&#34;&gt;FileReader&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&amp;quot;test.txt&amp;quot;&lt;/span&gt;));&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    System.out.println(br.readLine());&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125; &lt;span class=&#34;keyword&#34;&gt;catch&lt;/span&gt; (IOException e) &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    e.printStackTrace();&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125; &lt;span class=&#34;keyword&#34;&gt;finally&lt;/span&gt; &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (br != &lt;span class=&#34;literal&#34;&gt;null&lt;/span&gt;) &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;try&lt;/span&gt; &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            br.close();&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &amp;#125; &lt;span class=&#34;keyword&#34;&gt;catch&lt;/span&gt; (IOException e) &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            e.printStackTrace();&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;// try-with-resources 方式（简洁且安全）&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;try&lt;/span&gt; (&lt;span class=&#34;type&#34;&gt;BufferedReader&lt;/span&gt; &lt;span class=&#34;variable&#34;&gt;br&lt;/span&gt; &lt;span class=&#34;operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;new&lt;/span&gt; &lt;span class=&#34;title class_&#34;&gt;BufferedReader&lt;/span&gt;(&lt;span class=&#34;keyword&#34;&gt;new&lt;/span&gt; &lt;span class=&#34;title class_&#34;&gt;FileReader&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&amp;quot;test.txt&amp;quot;&lt;/span&gt;))) &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    System.out.println(br.readLine());&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125; &lt;span class=&#34;keyword&#34;&gt;catch&lt;/span&gt; (IOException e) &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    e.printStackTrace();&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;多个资源可以同时声明，用分号分隔：&lt;/p&gt;
&lt;figure class=&#34;highlight java&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;try&lt;/span&gt; (&lt;span class=&#34;type&#34;&gt;FileInputStream&lt;/span&gt; &lt;span class=&#34;variable&#34;&gt;fis&lt;/span&gt; &lt;span class=&#34;operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;new&lt;/span&gt; &lt;span class=&#34;title class_&#34;&gt;FileInputStream&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&amp;quot;in.txt&amp;quot;&lt;/span&gt;);&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;     &lt;span class=&#34;type&#34;&gt;FileOutputStream&lt;/span&gt; &lt;span class=&#34;variable&#34;&gt;fos&lt;/span&gt; &lt;span class=&#34;operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;new&lt;/span&gt; &lt;span class=&#34;title class_&#34;&gt;FileOutputStream&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&amp;quot;out.txt&amp;quot;&lt;/span&gt;)) &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;// 读写操作&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;// 两个流都会自动关闭（关闭顺序与声明顺序相反）&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h2 id=&#34;throw-vs-throws&#34;&gt;&lt;a href=&#34;#throw-vs-throws&#34; class=&#34;headerlink&#34; title=&#34;throw vs throws&#34;&gt;&lt;/a&gt;throw vs throws&lt;/h2&gt;&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;关键字&lt;/th&gt;
&lt;th&gt;位置&lt;/th&gt;
&lt;th&gt;作用&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;&lt;code&gt;throw&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;方法体内部&lt;/td&gt;
&lt;td&gt;抛出一个异常对象&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;throws&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;方法签名上&lt;/td&gt;
&lt;td&gt;声明方法可能抛出的异常类型&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;figure class=&#34;highlight java&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;// throws：声明可能抛出的异常&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;public&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;void&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;checkAge&lt;/span&gt;&lt;span class=&#34;params&#34;&gt;(&lt;span class=&#34;type&#34;&gt;int&lt;/span&gt; age)&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;throws&lt;/span&gt; IllegalArgumentException &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (age &amp;lt; &lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;) &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;// throw：实际抛出异常对象&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;throw&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;new&lt;/span&gt; &lt;span class=&#34;title class_&#34;&gt;IllegalArgumentException&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&amp;quot;年龄不能为负数：&amp;quot;&lt;/span&gt; + age);&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h2 id=&#34;自定义异常&#34;&gt;&lt;a href=&#34;#自定义异常&#34; class=&#34;headerlink&#34; title=&#34;自定义异常&#34;&gt;&lt;/a&gt;自定义异常&lt;/h2&gt;&lt;figure class=&#34;highlight java&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;// 自定义受检异常&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;public&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;class&lt;/span&gt; &lt;span class=&#34;title class_&#34;&gt;InsufficientBalanceException&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;extends&lt;/span&gt; &lt;span class=&#34;title class_&#34;&gt;Exception&lt;/span&gt; &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;public&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;InsufficientBalanceException&lt;/span&gt;&lt;span class=&#34;params&#34;&gt;(String message)&lt;/span&gt; &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;built_in&#34;&gt;super&lt;/span&gt;(message);&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;// 自定义非受检异常&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;public&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;class&lt;/span&gt; &lt;span class=&#34;title class_&#34;&gt;BusinessException&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;extends&lt;/span&gt; &lt;span class=&#34;title class_&#34;&gt;RuntimeException&lt;/span&gt; &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;private&lt;/span&gt; String errorCode;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;public&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;BusinessException&lt;/span&gt;&lt;span class=&#34;params&#34;&gt;(String errorCode, String message)&lt;/span&gt; &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;built_in&#34;&gt;super&lt;/span&gt;(message);&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;built_in&#34;&gt;this&lt;/span&gt;.errorCode = errorCode;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;public&lt;/span&gt; String &lt;span class=&#34;title function_&#34;&gt;getErrorCode&lt;/span&gt;&lt;span class=&#34;params&#34;&gt;()&lt;/span&gt; &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; errorCode;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h2 id=&#34;异常链&#34;&gt;&lt;a href=&#34;#异常链&#34; class=&#34;headerlink&#34; title=&#34;异常链&#34;&gt;&lt;/a&gt;异常链&lt;/h2&gt;&lt;p&gt;将一个异常作为另一个异常的原因，保留完整的调用栈：&lt;/p&gt;
&lt;figure class=&#34;highlight java&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;try&lt;/span&gt; &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;// 数据库操作&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125; &lt;span class=&#34;keyword&#34;&gt;catch&lt;/span&gt; (SQLException e) &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;// 包装为业务异常并保留原始异常&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;throw&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;new&lt;/span&gt; &lt;span class=&#34;title class_&#34;&gt;BusinessException&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&amp;quot;DB001&amp;quot;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;quot;数据查询失败&amp;quot;&lt;/span&gt;, e);&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h2 id=&#34;最佳实践&#34;&gt;&lt;a href=&#34;#最佳实践&#34; class=&#34;headerlink&#34; title=&#34;最佳实践&#34;&gt;&lt;/a&gt;最佳实践&lt;/h2&gt;&lt;ol&gt;
&lt;li&gt;&lt;strong&gt;不要吞掉异常&lt;/strong&gt;——永远不要写空的 catch 块：&lt;/li&gt;
&lt;/ol&gt;
&lt;figure class=&#34;highlight java&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;// 反例&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;try&lt;/span&gt; &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    doSomething();&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125; &lt;span class=&#34;keyword&#34;&gt;catch&lt;/span&gt; (Exception e) &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;// 什么都不做，问题被隐藏&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;// 正例：至少记录日志&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;try&lt;/span&gt; &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    doSomething();&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125; &lt;span class=&#34;keyword&#34;&gt;catch&lt;/span&gt; (Exception e) &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    log.error(&lt;span class=&#34;string&#34;&gt;&amp;quot;处理失败&amp;quot;&lt;/span&gt;, e);&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;throw&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;new&lt;/span&gt; &lt;span class=&#34;title class_&#34;&gt;ServiceException&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&amp;quot;操作失败&amp;quot;&lt;/span&gt;, e);&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;ol start=&#34;2&#34;&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;优先使用标准异常&lt;/strong&gt;——能用 JDK 自带的就别自定义（如 &lt;code&gt;IllegalArgumentException&lt;/code&gt;、&lt;code&gt;IllegalStateException&lt;/code&gt;）&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;异常信息要明确&lt;/strong&gt;——包含关键参数和上下文：&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;figure class=&#34;highlight java&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;throw&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;new&lt;/span&gt; &lt;span class=&#34;title class_&#34;&gt;IllegalArgumentException&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&amp;quot;用户ID无效: &amp;quot;&lt;/span&gt; + userId);&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;ol start=&#34;4&#34;&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;尽早抛出，延迟捕获&lt;/strong&gt;——底层发现问题立即抛出，在能处理的地方才捕获&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;不要在循环中使用 try-catch&lt;/strong&gt;——把 try-catch 放在循环外面，避免性能损耗&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;

 &lt;h2 id=&#34;Python面试题实录&#34;&gt;&lt;a href=&#34;#Python面试题实录&#34; class=&#34;headerlink&#34; title=&#34;Python面试题实录&#34;&gt;&lt;/a&gt;Python面试题实录&lt;/h2&gt;&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;温馨提示&lt;/strong&gt;：请访问我的另一个项目&lt;a href=&#34;https://github.com/jackfrued/Python-Interview-Bible&#34;&gt;“Python面试宝典”&lt;/a&gt;。&lt;/p&gt;
&lt;/blockquote&gt;

 &lt;h2 id=&#34;数据可视化-2&#34;&gt;&lt;a href=&#34;#数据可视化-2&#34; class=&#34;headerlink&#34; title=&#34;数据可视化-2&#34;&gt;&lt;/a&gt;数据可视化-2&lt;/h2&gt;&lt;p&gt;通过前面的学习，我们已经对数据可视化工具 matplotlib 有一个初步的认知。大家可能也会发现了，matplotlib 提供的函数虽然强大，但是参数太多，要想对图表进行深度的定制就需要修改一系列的参数，这一点对新手并不友好。另一方面，使用 matplotlib 定制的统计图是静态图表，可能在某些需要交互效果的场景下并不合适。为了解决这两个问题，我们为大家介绍两个新的可视化工具，一个是 seaborn，一个是 pyecharts。&lt;/p&gt;
&lt;h3 id=&#34;Seaborn&#34;&gt;&lt;a href=&#34;#Seaborn&#34; class=&#34;headerlink&#34; title=&#34;Seaborn&#34;&gt;&lt;/a&gt;Seaborn&lt;/h3&gt;&lt;p&gt;Seaborn 是建立在 matplotlib 之上的数据可视化工具，它相当于是对 matplotlib 进行了更高级的封装，而且 seaborn 也能跟 pandas 无缝整合，让我们可以用更少的代码构建出更好的统计图表，帮助我们探索和理解数据。Seaborn 包含但不局限于以下描述的功能：&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;面向数据集的 API，可用于检查多个变量之间的关系。&lt;/li&gt;
&lt;li&gt;支持使用分类变量来显示观察结果或汇总统计数据。&lt;/li&gt;
&lt;li&gt;能够可视化单变量或双变量分布以及在数据子集之间进行比较的选项&lt;/li&gt;
&lt;li&gt;各类因变量线性回归模型的自动估计与作图。&lt;/li&gt;
&lt;li&gt;集成调色板和主题，轻松定制统计图表的视觉效果。&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;可以使用 Python 的包管理工具 pip 来安装 seaborn。&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;pip install seaborn&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;在 Jupyter 中，可以直接使用魔法指令进行安装，如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;%pip install seaborn&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;下面，我们用 seaborn 自带的数据集为例，为大家简单的展示 seaborn 的用法和强大之处，想要深入研究 seaborn 的读者可以自行阅读官方&lt;a href=&#34;https://seaborn.pydata.org/tutorial.html&#34;&gt;文档&lt;/a&gt;和并查看官方作品集中的&lt;a href=&#34;https://seaborn.pydata.org/examples/index.html&#34;&gt;示例。&lt;/a&gt;根据官方示例来编写自己的代码是一个不错的选择，简单的说就是保留官方代码，将数据换成自己的数据即可。下图展示了 seaborn 绘制图表的函数，可以看出，seaborn 的这些函数主要支持我们通过绘制图表来探索数据的关系、分布和分类。&lt;/p&gt;
&lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20220502115005.png&#34; style=&#34;zoom:75%;&#34;&gt;

&lt;p&gt;使用 seaborn，首先需要导入该库并设置主题，代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; seaborn &lt;span class=&#34;keyword&#34;&gt;as&lt;/span&gt; sns&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;sns.set_theme()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;如果需要在图表上显示中文，还需要用之前讲过的方法修改 matplotlib 的配置参数，代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; matplotlib.pyplot &lt;span class=&#34;keyword&#34;&gt;as&lt;/span&gt; plt&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.rcParams[&lt;span class=&#34;string&#34;&gt;&amp;#x27;font.sans-serif&amp;#x27;&lt;/span&gt;] = [&lt;span class=&#34;string&#34;&gt;&amp;#x27;SimHei&amp;#x27;&lt;/span&gt;, ]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.rcParams[&lt;span class=&#34;string&#34;&gt;&amp;#x27;axes.unicode_minus&amp;#x27;&lt;/span&gt;] = &lt;span class=&#34;literal&#34;&gt;False&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;注意&lt;/strong&gt;：上面的代码必须放在调用 set_theme 函数之后，否则调用 set_theme 函数时又会重新修改 matplotlib 配置参数中的字体设置。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;加载官方的 Tips 数据集（就餐小费数据）。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;tips_df = sns.load_dataset(&lt;span class=&#34;string&#34;&gt;&amp;#x27;tips&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;tips_df.info()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;运行结果如下所示，其中 total_bill 表示账单总金额，tip 表示小费的金额，sex 是顾客的性别，smoker 表示顾客是否抽样，day 代表星期几，time 代表是午餐还是晚餐，size 是就餐人数。&lt;/p&gt;
&lt;figure class=&#34;highlight pgsql&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&amp;lt;&lt;span class=&#34;keyword&#34;&gt;class&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;#x27;pandas.core.frame.DataFrame&amp;#x27;&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;Range&lt;span class=&#34;keyword&#34;&gt;Index&lt;/span&gt;: &lt;span class=&#34;number&#34;&gt;244&lt;/span&gt; entries, &lt;span class=&#34;number&#34;&gt;0&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;to&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;243&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;Data &lt;span class=&#34;keyword&#34;&gt;columns&lt;/span&gt; (total &lt;span class=&#34;number&#34;&gt;7&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;columns&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt; #   &lt;span class=&#34;keyword&#34;&gt;Column&lt;/span&gt;      Non-&lt;span class=&#34;keyword&#34;&gt;Null&lt;/span&gt; Count  Dtype   &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;---  ------      --------------  -----   &lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt; &lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;   total_bill  &lt;span class=&#34;number&#34;&gt;244&lt;/span&gt; non-&lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt;    float64 &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt; &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;   tip         &lt;span class=&#34;number&#34;&gt;244&lt;/span&gt; non-&lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt;    float64 &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt; &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;   sex         &lt;span class=&#34;number&#34;&gt;244&lt;/span&gt; non-&lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt;    category&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt; &lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;   smoker      &lt;span class=&#34;number&#34;&gt;244&lt;/span&gt; non-&lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt;    category&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt; &lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;   day         &lt;span class=&#34;number&#34;&gt;244&lt;/span&gt; non-&lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt;    category&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt; &lt;span class=&#34;number&#34;&gt;5&lt;/span&gt;   &lt;span class=&#34;type&#34;&gt;time&lt;/span&gt;        &lt;span class=&#34;number&#34;&gt;244&lt;/span&gt; non-&lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt;    category&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt; &lt;span class=&#34;number&#34;&gt;6&lt;/span&gt;   size        &lt;span class=&#34;number&#34;&gt;244&lt;/span&gt; non-&lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt;    int64   &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;dtypes: category(&lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;), float64(&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;), int64(&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;memory &lt;span class=&#34;keyword&#34;&gt;usage&lt;/span&gt;: &lt;span class=&#34;number&#34;&gt;7.4&lt;/span&gt; KB&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;由于数据集是联网加载的，上述代码可能因为 SSL 的原因无法获取到数据，可以尝试先运行下面的代码，然后再加载数据集。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; ssl&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;ssl._create_default_https_context = ssl._create_unverified_context&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;如果我们希望了解账单金额的分布，可以使用下面的代码来绘制分布图。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;sns.histplot(data=tips_df, x=&lt;span class=&#34;string&#34;&gt;&amp;#x27;total_bill&amp;#x27;&lt;/span&gt;, kde=&lt;span class=&#34;literal&#34;&gt;True&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20220502115531.png&#34; style=&#34;zoom:50%;&#34;&gt;

&lt;p&gt;如果想了解变量之间的两两关系，我们可以绘制点对图，代码和效果如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;sns.pairplot(data=tips_df, hue=&lt;span class=&#34;string&#34;&gt;&amp;#x27;sex&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20220502120236.png&#34; style=&#34;zoom:50%;&#34;&gt;

&lt;p&gt;如果对上面图表的颜色不满意，还可以通过 palette 参数选择 seaborn 自带的“调色板”来修改颜色，这种方式相比于自行指定颜色或使用随机颜色方便和靠谱了很多，下图为大家展示了部分 seaborn 自带的“调色板”。&lt;/p&gt;
&lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20220502120749.png&#34; style=&#34;zoom:50%;&#34;&gt;

&lt;p&gt;我们可以将上面的代码稍作修改，看看运行结果有什么差别。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;sns.pairplot(data=tips_df, hue=&lt;span class=&#34;string&#34;&gt;&amp;#x27;sex&amp;#x27;&lt;/span&gt;, palette=&lt;span class=&#34;string&#34;&gt;&amp;#x27;Dark2&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;接下来，我们为 total_bill 和 tip 两组数据绘制联合分布图，代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;sns.jointplot(data=tips_df, x=&lt;span class=&#34;string&#34;&gt;&amp;#x27;total_bill&amp;#x27;&lt;/span&gt;, y=&lt;span class=&#34;string&#34;&gt;&amp;#x27;tip&amp;#x27;&lt;/span&gt;, hue=&lt;span class=&#34;string&#34;&gt;&amp;#x27;sex&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20220502121226.png&#34; style=&#34;zoom:50%;&#34;&gt;

&lt;p&gt;上面清晰的展示了，total_bill 和 tip 之间存在正相关关系，这一点我们也可以通过 DataFrame 对象的 corr 方法进行验证。接下来，我们可以建立回归模型来拟合这些数据点，而 seaborn 的线性回归模型图已经帮我们实现了这项功能，代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;sns.lmplot(data=tips_df, x=&lt;span class=&#34;string&#34;&gt;&amp;#x27;total_bill&amp;#x27;&lt;/span&gt;, y=&lt;span class=&#34;string&#34;&gt;&amp;#x27;tip&amp;#x27;&lt;/span&gt;, hue=&lt;span class=&#34;string&#34;&gt;&amp;#x27;sex&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20220502121656.png&#34; style=&#34;zoom:50%;&#34;&gt;

&lt;p&gt;如果我们希望了解账单金额的集中和离散趋势，可以绘制箱线图或小提琴图，代码如下所示，我们将数据按星期四、星期五、星期六和星期天分别进行展示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;sns.boxplot(data=tips_df, x=&lt;span class=&#34;string&#34;&gt;&amp;#x27;day&amp;#x27;&lt;/span&gt;, y=&lt;span class=&#34;string&#34;&gt;&amp;#x27;total_bill&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20220502122106.png&#34; style=&#34;zoom:50%;&#34;&gt;

&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;sns.violinplot(data=tips_df, x=&lt;span class=&#34;string&#34;&gt;&amp;#x27;day&amp;#x27;&lt;/span&gt;, y=&lt;span class=&#34;string&#34;&gt;&amp;#x27;total_bill&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20220502122144.png&#34; style=&#34;zoom:50%;&#34;&gt;

&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;说明&lt;/strong&gt;：相较于箱线图，小提琴图没有标注异常点而是显示了数据的整个范围，另一方面，小提琴图很好的展示了数据的分布（密度轨迹）。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h3 id=&#34;Pyecharts&#34;&gt;&lt;a href=&#34;#Pyecharts&#34; class=&#34;headerlink&#34; title=&#34;Pyecharts&#34;&gt;&lt;/a&gt;Pyecharts&lt;/h3&gt;&lt;p&gt;Echarts 原来是百度开发的一个前端图表库，2018年1月16日，ECharts 进入 Apache Incubator 进行孵化，目前已经是 Apache 软件基金会的顶级项目。凭借着良好的交互性和精巧的图表设计，ECharts 得到了众多开发者的认可，而 pyecharts 就是基于 Python 语言对 ECharts 进行了包装，让 Python 开发者也可以使用 ECharts 绘制外观精美且交互性强的统计图表。&lt;/p&gt;
&lt;p&gt;可以使用 Python 的包管理工具 pip 来安装 pyecharts。&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;pip install pyecharts&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;在 Jupyter 中，可以直接使用魔法指令进行安装，如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;%pip install pyecharts&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;接下来，我们通过来自于 pyecharts 官方网站新手教程中的一个例子，来认识 pyecharts。当然，我们对官网的例子进行一些调整，代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; pyecharts.charts &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; Bar&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; pyecharts &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; options&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; pyecharts.&lt;span class=&#34;built_in&#34;&gt;globals&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; ThemeType&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 创建柱状图对象并设置初始参数（宽度、高度、主题）&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;bar = Bar(init_opts=options.InitOpts(&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    width=&lt;span class=&#34;string&#34;&gt;&amp;#x27;600px&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    height=&lt;span class=&#34;string&#34;&gt;&amp;#x27;450px&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    theme=ThemeType.CHALK&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;))&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 设置横轴数据&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;bar.add_xaxis([&lt;span class=&#34;string&#34;&gt;&amp;quot;衬衫&amp;quot;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;quot;羊毛衫&amp;quot;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;quot;雪纺衫&amp;quot;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;quot;裤子&amp;quot;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;quot;高跟鞋&amp;quot;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;quot;袜子&amp;quot;&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 设置纵轴数据（第一组）&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;bar.add_yaxis(&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;商家A&amp;quot;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    [&lt;span class=&#34;number&#34;&gt;25&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;36&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;75&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;90&lt;/span&gt;],&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 设置纵轴数据（第二组）&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;bar.add_yaxis(&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;商家B&amp;quot;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    [&lt;span class=&#34;number&#34;&gt;15&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;12&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;30&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;45&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;60&lt;/span&gt;]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 设置纵轴数据（第三组）&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;bar.add_yaxis(&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;商家C&amp;quot;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    [&lt;span class=&#34;number&#34;&gt;12&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;32&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;40&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;52&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;35&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;26&lt;/span&gt;]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 添加全局配置参数&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;bar.set_global_opts(&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 横轴相关的参数&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    xaxis_opts=options.AxisOpts(&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        axislabel_opts=options.LabelOpts(&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            color=&lt;span class=&#34;string&#34;&gt;&amp;#x27;white&amp;#x27;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        )&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    ),&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 纵轴相关的参数（标签、最小值、最大值、间隔）&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    yaxis_opts=options.AxisOpts(&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        axislabel_opts=options.LabelOpts(&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            color=&lt;span class=&#34;string&#34;&gt;&amp;#x27;white&amp;#x27;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        ),&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        min_=&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        max_=&lt;span class=&#34;number&#34;&gt;100&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        interval=&lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    ),&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 标题相关的参数（内容、链接、位置、文本样式）&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    title_opts=options.TitleOpts(&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        title=&lt;span class=&#34;string&#34;&gt;&amp;#x27;2021年销售数据展示&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        title_link=&lt;span class=&#34;string&#34;&gt;&amp;#x27;http://www.qfedu.com&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        pos_left=&lt;span class=&#34;string&#34;&gt;&amp;#x27;2%&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        title_textstyle_opts=options.TextStyleOpts(&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            color=&lt;span class=&#34;string&#34;&gt;&amp;#x27;white&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            font_size=&lt;span class=&#34;number&#34;&gt;16&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            font_family=&lt;span class=&#34;string&#34;&gt;&amp;#x27;SimHei&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            font_weight=&lt;span class=&#34;string&#34;&gt;&amp;#x27;bold&amp;#x27;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        )&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    ),&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 工具箱相关的参数&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    toolbox_opts=options.ToolboxOpts(&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        orient=&lt;span class=&#34;string&#34;&gt;&amp;#x27;vertical&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        pos_left=&lt;span class=&#34;string&#34;&gt;&amp;#x27;right&amp;#x27;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    )&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 在Jupyter Notebook中渲染图表&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;bar.render_notebook()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;上面代码的运行效果如下图所示。值得一提的是，下图中的标题、图例、右侧的工具箱都是可以点击的，大家可以点击它们看看会有什么样的效果，ECharts 的魅力就在于它的交互效果，大家一定要试一试。如果要将下面的统计图表保存成一个网页，可以将上面最后一行代码修改为&lt;code&gt;bar.render(&amp;#39;index.html&amp;#39;)&lt;/code&gt;即可。&lt;/p&gt;
&lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20220502185650.png&#34; style=&#34;zoom:50%;&#34;&gt;

&lt;p&gt;接下来，我们也是通过一个官方示例，看看如何绘制饼图。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; pyecharts.options &lt;span class=&#34;keyword&#34;&gt;as&lt;/span&gt; opts&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; pyecharts.charts &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; Pie&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 准备饼图需要的数据&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;x_data = [&lt;span class=&#34;string&#34;&gt;&amp;quot;直接访问&amp;quot;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;quot;邮件营销&amp;quot;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;quot;联盟广告&amp;quot;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;quot;视频广告&amp;quot;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;quot;搜索引擎&amp;quot;&lt;/span&gt;]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;y_data = [&lt;span class=&#34;number&#34;&gt;335&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;310&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;234&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;135&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;1548&lt;/span&gt;]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;data = [(x, y) &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; x, y &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; &lt;span class=&#34;built_in&#34;&gt;zip&lt;/span&gt;(x_data, y_data)]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 创建饼图对象并设置初始化参数&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;pie = Pie(init_opts=opts.InitOpts(width=&lt;span class=&#34;string&#34;&gt;&amp;quot;800px&amp;quot;&lt;/span&gt;, height=&lt;span class=&#34;string&#34;&gt;&amp;quot;400px&amp;quot;&lt;/span&gt;))&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 向饼图添加数据&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;pie.add(&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;#x27;&amp;#x27;&lt;/span&gt;, &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    data_pair=data,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    radius=[&lt;span class=&#34;string&#34;&gt;&amp;quot;50%&amp;quot;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;quot;75%&amp;quot;&lt;/span&gt;],&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    label_opts=opts.LabelOpts(is_show=&lt;span class=&#34;literal&#34;&gt;False&lt;/span&gt;),&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 设置全局配置项&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;pie.set_global_opts(&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 配置图例相关的参数&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    legend_opts=opts.LegendOpts(&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        pos_left=&lt;span class=&#34;string&#34;&gt;&amp;quot;legft&amp;quot;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        orient=&lt;span class=&#34;string&#34;&gt;&amp;quot;vertical&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    )&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 设置数据系列配置参数&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;pie.set_series_opts(&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 设置不显示工具提示&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    tooltip_opts=opts.TooltipOpts(is_show=&lt;span class=&#34;literal&#34;&gt;False&lt;/span&gt;),&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 设置饼图标签的样式&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    label_opts=opts.LabelOpts(formatter=&lt;span class=&#34;string&#34;&gt;&amp;quot;&amp;#123;b&amp;#125;(&amp;#123;c&amp;#125;): &amp;#123;d&amp;#125;%&amp;quot;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;pie.render_notebook()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;运行上面的代码，效果如下图所示。&lt;/p&gt;
&lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20220502190558.png&#34; style=&#34;zoom:50%;&#34;&gt;

&lt;p&gt;需要提醒大家注意的是，pyecharts 并不能直接使用 NumPy 的 ndarray 和 Pandas 的 Series、DataFrame 为其提供数据，它需要的是 Python 原生的数据类型。可能大家也注意到了，上面的代码中，我们使用的都是列表、元组这样的数据类型。&lt;/p&gt;
&lt;p&gt;最后，我们来看看如何绘制地图，绘制地图首先需要安装额外的依赖库来获取地图相关信息，命令如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;pip install echarts-countries-pypkg echarts-china-provinces-pypkg echarts-china-cities-pypkg echarts-china-counties-pypkg&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;在 Jupyter 中，可以直接使用魔法指令进行安装，如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;%pip install echarts-countries-pypkg&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;%pip install echarts-china-provinces-pypkg&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;%pip install echarts-china-cities-pypkg&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;%pip install echarts-china-counties-pypkg&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;说明&lt;/strong&gt;：上面的四个库分别包含了世界各国、中国省级行政区域、中国市级行政区域、中国区&amp;#x2F;县级行政区域的数据。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;然后，我们将全国各省抖音大V的数据放在一个列表中，代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;data = [&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    (&lt;span class=&#34;string&#34;&gt;&amp;#x27;广东&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;594&lt;/span&gt;), (&lt;span class=&#34;string&#34;&gt;&amp;#x27;浙江&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;438&lt;/span&gt;), (&lt;span class=&#34;string&#34;&gt;&amp;#x27;四川&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;316&lt;/span&gt;), (&lt;span class=&#34;string&#34;&gt;&amp;#x27;北京&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;269&lt;/span&gt;), (&lt;span class=&#34;string&#34;&gt;&amp;#x27;山东&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;248&lt;/span&gt;),&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    (&lt;span class=&#34;string&#34;&gt;&amp;#x27;江苏&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;234&lt;/span&gt;), (&lt;span class=&#34;string&#34;&gt;&amp;#x27;湖南&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;196&lt;/span&gt;), (&lt;span class=&#34;string&#34;&gt;&amp;#x27;福建&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;166&lt;/span&gt;), (&lt;span class=&#34;string&#34;&gt;&amp;#x27;河南&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;153&lt;/span&gt;), (&lt;span class=&#34;string&#34;&gt;&amp;#x27;辽宁&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;152&lt;/span&gt;),&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    (&lt;span class=&#34;string&#34;&gt;&amp;#x27;上海&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;138&lt;/span&gt;), (&lt;span class=&#34;string&#34;&gt;&amp;#x27;河北&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;86&lt;/span&gt;), (&lt;span class=&#34;string&#34;&gt;&amp;#x27;安徽&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;79&lt;/span&gt;), (&lt;span class=&#34;string&#34;&gt;&amp;#x27;湖北&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;75&lt;/span&gt;), (&lt;span class=&#34;string&#34;&gt;&amp;#x27;黑龙江&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;70&lt;/span&gt;), &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    (&lt;span class=&#34;string&#34;&gt;&amp;#x27;陕西&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;63&lt;/span&gt;), (&lt;span class=&#34;string&#34;&gt;&amp;#x27;吉林&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;59&lt;/span&gt;), (&lt;span class=&#34;string&#34;&gt;&amp;#x27;江西&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;56&lt;/span&gt;), (&lt;span class=&#34;string&#34;&gt;&amp;#x27;重庆&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;46&lt;/span&gt;), (&lt;span class=&#34;string&#34;&gt;&amp;#x27;贵州&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;39&lt;/span&gt;),&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    (&lt;span class=&#34;string&#34;&gt;&amp;#x27;山西&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;37&lt;/span&gt;), (&lt;span class=&#34;string&#34;&gt;&amp;#x27;云南&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;33&lt;/span&gt;), (&lt;span class=&#34;string&#34;&gt;&amp;#x27;广西&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;24&lt;/span&gt;), (&lt;span class=&#34;string&#34;&gt;&amp;#x27;天津&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;22&lt;/span&gt;), (&lt;span class=&#34;string&#34;&gt;&amp;#x27;新疆&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;21&lt;/span&gt;),&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    (&lt;span class=&#34;string&#34;&gt;&amp;#x27;海南&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;18&lt;/span&gt;), (&lt;span class=&#34;string&#34;&gt;&amp;#x27;内蒙古&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;14&lt;/span&gt;), (&lt;span class=&#34;string&#34;&gt;&amp;#x27;台湾&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;11&lt;/span&gt;), (&lt;span class=&#34;string&#34;&gt;&amp;#x27;甘肃&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;7&lt;/span&gt;), (&lt;span class=&#34;string&#34;&gt;&amp;#x27;广西壮族自治区&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;),&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    (&lt;span class=&#34;string&#34;&gt;&amp;#x27;香港&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;), (&lt;span class=&#34;string&#34;&gt;&amp;#x27;青海&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;), (&lt;span class=&#34;string&#34;&gt;&amp;#x27;新疆维吾尔自治区&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;), (&lt;span class=&#34;string&#34;&gt;&amp;#x27;内蒙古自治区&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;), (&lt;span class=&#34;string&#34;&gt;&amp;#x27;宁夏&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;]&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;接下来，我们使用 pyecharts 在地图上标记各省抖音大V人数。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; pyecharts.charts &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; Map&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;map_chart = Map()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;map_chart.add(&lt;span class=&#34;string&#34;&gt;&amp;#x27;&amp;#x27;&lt;/span&gt;, data, &lt;span class=&#34;string&#34;&gt;&amp;#x27;china&amp;#x27;&lt;/span&gt;, is_roam=&lt;span class=&#34;literal&#34;&gt;False&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;map_chart.render_notebook()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;代码的运行效果如下图所示，将鼠标置于地图上时，会高亮对应的省并看到相关的信息。&lt;/p&gt;
&lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20220502192142.png&#34; style=&#34;zoom:50%;&#34;&gt;

&lt;p&gt;和 seaborn 一样，我们建议大家参考官方提供的示例来使用 pyecharts，我们可以在 pyecharts &lt;a href=&#34;https://pyecharts.org/#/zh-cn/&#34;&gt;官方网站&lt;/a&gt;的左侧导航栏中找到“图表类型”选项，下面每种类型的图表都有对应的官方示例，很多代码是可以直接使用的，我们需要做的就是将数据换成自己的数据。&lt;/p&gt;

 &lt;h2 id=&#34;数据可视化-1&#34;&gt;&lt;a href=&#34;#数据可视化-1&#34; class=&#34;headerlink&#34; title=&#34;数据可视化-1&#34;&gt;&lt;/a&gt;数据可视化-1&lt;/h2&gt;&lt;p&gt;在完成了对数据的透视之后，我们可以将数据透视的结果通过可视化的方式呈现出来，简单的说，就是将数据变成漂亮的统计图表，然后进一步发现和解读数据背后隐藏的商业价值。在之前的课程中，我们已经为大家展示过用使用&lt;code&gt;Series&lt;/code&gt;或&lt;code&gt;DataFrame&lt;/code&gt;对象的&lt;code&gt;plot&lt;/code&gt;方法生成可视化图表的操作，本章我们为大家讲解&lt;code&gt;plot&lt;/code&gt;方法的基石，它就是大名鼎鼎的&lt;code&gt;matplotlib&lt;/code&gt;库。&lt;/p&gt;
&lt;h3 id=&#34;常用的图表类型&#34;&gt;&lt;a href=&#34;#常用的图表类型&#34; class=&#34;headerlink&#34; title=&#34;常用的图表类型&#34;&gt;&lt;/a&gt;常用的图表类型&lt;/h3&gt;&lt;p&gt;常用的图表类型及其应用场景如下图所示。&lt;/p&gt;
&lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20220315193326.png&#34; style=&#34;zoom:65%&#34;&gt;

&lt;h3 id=&#34;Matplotlib-的安装和导入&#34;&gt;&lt;a href=&#34;#Matplotlib-的安装和导入&#34; class=&#34;headerlink&#34; title=&#34;Matplotlib 的安装和导入&#34;&gt;&lt;/a&gt;Matplotlib 的安装和导入&lt;/h3&gt;&lt;p&gt;如果还没有安装&lt;code&gt;matplotlib&lt;/code&gt;库，可以使用 Python 的包管理工具 pip 来安装，命令如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight shell&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;pip install matplotlib&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;在 Notebook 中，我们可以用下面的方式导入&lt;code&gt;matplotlib&lt;/code&gt;。为了解决图表中文显示的问题，我们可以通过&lt;code&gt;pyplot&lt;/code&gt;模块的&lt;code&gt;rcParams&lt;/code&gt;属性修改配置参数，具体的操作如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; matplotlib.pyplot &lt;span class=&#34;keyword&#34;&gt;as&lt;/span&gt; plt&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.rcParams[&lt;span class=&#34;string&#34;&gt;&amp;#x27;font.sans-serif&amp;#x27;&lt;/span&gt;] = [&lt;span class=&#34;string&#34;&gt;&amp;#x27;SimHei&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;Songti SC&amp;#x27;&lt;/span&gt;]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.rcParams[&lt;span class=&#34;string&#34;&gt;&amp;#x27;axes.unicode_minus&amp;#x27;&lt;/span&gt;] = &lt;span class=&#34;literal&#34;&gt;False&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;说明&lt;/strong&gt;：上面代码中的&lt;code&gt;SimHei&lt;/code&gt;是字体名称，大家可以通过百度云盘下载并安装该字体，链接地址：&lt;a href=&#34;https://pan.baidu.com/s/1rQujl5RQn9R7PadB2Z5g_g%EF%BC%8C%E6%8F%90%E5%8F%96%E7%A0%81:e7b4%EF%BC%9B%60Songti&#34;&gt;https://pan.baidu.com/s/1rQujl5RQn9R7PadB2Z5g_g，提取码:e7b4；`Songti&lt;/a&gt; SC&lt;code&gt;是我的 macOS 上自带的字体，对于 macOS 或 Windows 系统，字体的名字都可以在用户主目录下的&lt;/code&gt;.matplotlib&lt;code&gt;文件夹下的&lt;/code&gt;fontlist-v330.json&lt;code&gt;文件中找到。值得注意的是，使用中文字体后坐标轴上的负号会显示不出来，所以需要将&lt;/code&gt;axes.unicode_minus&lt;code&gt;参数设置为&lt;/code&gt;False&amp;#96;，这样才能让坐标轴上的负号正常显示。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;通过下面的魔法指令，我们可以在绘图时生成&lt;a href=&#34;https://zh.wikipedia.org/wiki/%E7%9F%A2%E9%87%8F%E5%9B%BE%E5%BD%A2&#34;&gt;矢量图&lt;/a&gt;（SVG - Scalable Vector Graphics）。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;%config InlineBackend.figure_format=&lt;span class=&#34;string&#34;&gt;&amp;#x27;svg&amp;#x27;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h3 id=&#34;绘图的流程&#34;&gt;&lt;a href=&#34;#绘图的流程&#34; class=&#34;headerlink&#34; title=&#34;绘图的流程&#34;&gt;&lt;/a&gt;绘图的流程&lt;/h3&gt;&lt;h4 id=&#34;创建画布&#34;&gt;&lt;a href=&#34;#创建画布&#34; class=&#34;headerlink&#34; title=&#34;创建画布&#34;&gt;&lt;/a&gt;创建画布&lt;/h4&gt;&lt;p&gt;&lt;code&gt;pyplot&lt;/code&gt;模块的&lt;code&gt;figure&lt;/code&gt;函数可以用来创建画布，创建画布时，可以通过&lt;code&gt;figsize&lt;/code&gt;参数指定画布的尺寸（默认值是&lt;code&gt;[6.4, 4.8]&lt;/code&gt;）；可以通过&lt;code&gt;dpi&lt;/code&gt;参数设置绘图的分辨率，因为&lt;code&gt;dpi&lt;/code&gt;代表了每英寸的像素点数量。除此之外，还可以通过&lt;code&gt;facecolor&lt;/code&gt;参数设置画布的背景色。&lt;code&gt;figure&lt;/code&gt;函数的返回值是一个&lt;code&gt;Figure&lt;/code&gt;对象，它代表了绘图使用的画布，我们可以基于画布来创建绘图使用的坐标系。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;plt.figure(figsize=(&lt;span class=&#34;number&#34;&gt;8&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;), dpi=&lt;span class=&#34;number&#34;&gt;120&lt;/span&gt;, facecolor=&lt;span class=&#34;string&#34;&gt;&amp;#x27;darkgray&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h4 id=&#34;创建坐标系&#34;&gt;&lt;a href=&#34;#创建坐标系&#34; class=&#34;headerlink&#34; title=&#34;创建坐标系&#34;&gt;&lt;/a&gt;创建坐标系&lt;/h4&gt;&lt;p&gt;可以直接使用&lt;code&gt;pyplot&lt;/code&gt;模块的&lt;code&gt;subplot&lt;/code&gt;函数来创建坐标系，该函数会返回&lt;code&gt;Axes&lt;/code&gt;对象。&lt;code&gt;subplot&lt;/code&gt;的前三个参数分别用来指定整个画布分成几行几列以及当前坐标系的索引，这三个参数的默认值都是&lt;code&gt;1&lt;/code&gt;。如果需要在画布上创建多个坐标系，就需要使用该函数，否则就直接使用默认的也是唯一的坐标系。当然，也可以通过上面创建的&lt;code&gt;Figure&lt;/code&gt;对象的&lt;code&gt;add_subplot&lt;/code&gt;方法或&lt;code&gt;add_axes&lt;/code&gt;方法来创建坐标系，前者跟&lt;code&gt;subplot&lt;/code&gt;函数的作用一致，后者会产生嵌套的坐标系。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;plt.subplot(&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h4 id=&#34;绘制图像&#34;&gt;&lt;a href=&#34;#绘制图像&#34; class=&#34;headerlink&#34; title=&#34;绘制图像&#34;&gt;&lt;/a&gt;绘制图像&lt;/h4&gt;&lt;h5 id=&#34;折线图&#34;&gt;&lt;a href=&#34;#折线图&#34; class=&#34;headerlink&#34; title=&#34;折线图&#34;&gt;&lt;/a&gt;折线图&lt;/h5&gt;&lt;p&gt;在绘图时，如果没有先调用&lt;code&gt;figure&lt;/code&gt;函数和&lt;code&gt;subplot&lt;/code&gt;函数，我们将使用默认的画布和坐标系，如果要绘制折线图，可以使用&lt;code&gt;pyplot&lt;/code&gt;模块的&lt;code&gt;plot&lt;/code&gt;函数，并指定横轴和纵轴的数据。折线图最适合用来观察数据的趋势，尤其是当横坐标代表时间的情况下。我们可以使用&lt;code&gt;plot&lt;/code&gt;函数的&lt;code&gt;color&lt;/code&gt;参数来定制折线的颜色，可以使用&lt;code&gt;marker&lt;/code&gt;参数来定制数据点的标记（例如：&lt;code&gt;*&lt;/code&gt;表示五角星，&lt;code&gt;^&lt;/code&gt;表示三角形，&lt;code&gt;o&lt;/code&gt;表示小圆圈等），可以使用&lt;code&gt;linestyle&lt;/code&gt;参数来定制折线的样式（例如：&lt;code&gt;-&lt;/code&gt;表示实线，&lt;code&gt;--&lt;/code&gt;表示虚线，&lt;code&gt;:&lt;/code&gt;表示点线等），可以使用&lt;code&gt;linewidth&lt;/code&gt;参数来定制折线的粗细。 下面的代码绘制了一条正弦曲线，其中&lt;code&gt;marker=&amp;#39;*&amp;#39;&lt;/code&gt;会将数据点的标记设置为五角星形状，而&lt;code&gt;color=&amp;#39;red&amp;#39;&lt;/code&gt;会将折线绘制为红色。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; numpy &lt;span class=&#34;keyword&#34;&gt;as&lt;/span&gt; np&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;x = np.linspace(-&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt; * np.pi, &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt; * np.pi, &lt;span class=&#34;number&#34;&gt;120&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;y = np.sin(x)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 创建画布&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.figure(figsize=(&lt;span class=&#34;number&#34;&gt;8&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;), dpi=&lt;span class=&#34;number&#34;&gt;120&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 绘制折线图&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.plot(x, y, linewidth=&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;, marker=&lt;span class=&#34;string&#34;&gt;&amp;#x27;*&amp;#x27;&lt;/span&gt;, color=&lt;span class=&#34;string&#34;&gt;&amp;#x27;red&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 显示绘图&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.show()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20220501173344.png&#34; style=&#34;zoom:50%;&#34;&gt;

&lt;p&gt;如果要在一个坐标系上同时绘制正弦和余弦曲线，可以对上面的代码稍作修改。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;x = np.linspace(-&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt; * np.pi, &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt; * np.pi, &lt;span class=&#34;number&#34;&gt;120&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;y1, y2 = np.sin(x), np.cos(x)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.figure(figsize=(&lt;span class=&#34;number&#34;&gt;8&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;), dpi=&lt;span class=&#34;number&#34;&gt;120&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.plot(x, y1, linewidth=&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;, marker=&lt;span class=&#34;string&#34;&gt;&amp;#x27;*&amp;#x27;&lt;/span&gt;, color=&lt;span class=&#34;string&#34;&gt;&amp;#x27;red&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.plot(x, y2, linewidth=&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;, marker=&lt;span class=&#34;string&#34;&gt;&amp;#x27;^&amp;#x27;&lt;/span&gt;, color=&lt;span class=&#34;string&#34;&gt;&amp;#x27;blue&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 定制图表的标注，其中的arrowprops是定制箭头样式的参数&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.annotate(&lt;span class=&#34;string&#34;&gt;&amp;#x27;sin(x)&amp;#x27;&lt;/span&gt;, xytext=(&lt;span class=&#34;number&#34;&gt;0.5&lt;/span&gt;, -&lt;span class=&#34;number&#34;&gt;0.75&lt;/span&gt;), xy=(&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;, -&lt;span class=&#34;number&#34;&gt;0.25&lt;/span&gt;), fontsize=&lt;span class=&#34;number&#34;&gt;12&lt;/span&gt;, arrowprops=&amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;#x27;arrowstyle&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;-&amp;gt;&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;color&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;darkgreen&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;connectionstyle&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;angle3, angleA=90, angleB=0&amp;#x27;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.annotate(&lt;span class=&#34;string&#34;&gt;&amp;#x27;cos(x)&amp;#x27;&lt;/span&gt;, xytext=(-&lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0.75&lt;/span&gt;), xy=(-&lt;span class=&#34;number&#34;&gt;1.25&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0.5&lt;/span&gt;), fontsize=&lt;span class=&#34;number&#34;&gt;12&lt;/span&gt;, arrowprops=&amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;#x27;arrowstyle&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;-&amp;gt;&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;color&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;darkgreen&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;connectionstyle&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;arc3, rad=0.35&amp;#x27;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.show()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20220502095949.png&#34; style=&#34;zoom:50%;&#34;&gt;

&lt;p&gt;如果要使用两个坐标系分别绘制正弦和余弦，可以用上面提到的&lt;code&gt;subplot&lt;/code&gt;函数来创建坐标系，然后再绘图。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;plt.figure(figsize=(&lt;span class=&#34;number&#34;&gt;8&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;), dpi=&lt;span class=&#34;number&#34;&gt;120&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 创建坐标系（第1个图）&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.subplot(&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.plot(x, y1, linewidth=&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;, marker=&lt;span class=&#34;string&#34;&gt;&amp;#x27;*&amp;#x27;&lt;/span&gt;, color=&lt;span class=&#34;string&#34;&gt;&amp;#x27;red&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 创建坐标系（第2个图）&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.subplot(&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.plot(x, y2, linewidth=&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;, marker=&lt;span class=&#34;string&#34;&gt;&amp;#x27;^&amp;#x27;&lt;/span&gt;, color=&lt;span class=&#34;string&#34;&gt;&amp;#x27;blue&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.show()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20220501173446.png&#34; style=&#34;zoom:50%;&#34;&gt;

&lt;p&gt;当然也可以像下面这么做，大家可以运行代码看看跟上面的图有什么区别。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;plt.figure(figsize=(&lt;span class=&#34;number&#34;&gt;8&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;), dpi=&lt;span class=&#34;number&#34;&gt;120&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.subplot(&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.plot(x, y1, linewidth=&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;, marker=&lt;span class=&#34;string&#34;&gt;&amp;#x27;*&amp;#x27;&lt;/span&gt;, color=&lt;span class=&#34;string&#34;&gt;&amp;#x27;red&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.subplot(&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.plot(x, y2, linewidth=&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;, marker=&lt;span class=&#34;string&#34;&gt;&amp;#x27;^&amp;#x27;&lt;/span&gt;, color=&lt;span class=&#34;string&#34;&gt;&amp;#x27;blue&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.show()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;然后，再试一试下面这个代码，看看运行效果如何。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;fig = plt.figure(figsize=(&lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;), dpi=&lt;span class=&#34;number&#34;&gt;120&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.plot(x, y1, linewidth=&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;, marker=&lt;span class=&#34;string&#34;&gt;&amp;#x27;*&amp;#x27;&lt;/span&gt;, color=&lt;span class=&#34;string&#34;&gt;&amp;#x27;red&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 用Figure对象的add_axes方法在现有坐标系中嵌套一个新的坐标系&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 该方法的参数是一个四元组，代表了新坐标系在原坐标系中的位置&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 前两个值是左下角的位置，后两个值是坐标系的宽度和高度&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;ax = fig.add_axes((&lt;span class=&#34;number&#34;&gt;0.595&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0.6&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0.3&lt;/span&gt;,&lt;span class=&#34;number&#34;&gt;0.25&lt;/span&gt;))&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;ax.plot(x, y2, marker=&lt;span class=&#34;string&#34;&gt;&amp;#x27;^&amp;#x27;&lt;/span&gt;, color=&lt;span class=&#34;string&#34;&gt;&amp;#x27;blue&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;ax = fig.add_axes((&lt;span class=&#34;number&#34;&gt;0.155&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0.2&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0.3&lt;/span&gt;,&lt;span class=&#34;number&#34;&gt;0.25&lt;/span&gt;))&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;ax.plot(x, y2, marker=&lt;span class=&#34;string&#34;&gt;&amp;#x27;^&amp;#x27;&lt;/span&gt;, color=&lt;span class=&#34;string&#34;&gt;&amp;#x27;green&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.show()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h5 id=&#34;散点图&#34;&gt;&lt;a href=&#34;#散点图&#34; class=&#34;headerlink&#34; title=&#34;散点图&#34;&gt;&lt;/a&gt;散点图&lt;/h5&gt;&lt;p&gt;散点图可以帮助我们了解两个变量的关系，如果需要了解三个变量的关系，可以将散点图升级为气泡图。下面的代码中，&lt;code&gt;x&lt;/code&gt;和&lt;code&gt;y&lt;/code&gt;两个数组分别表示每个月的收入和每个月网购的支出，如果我们想了解&lt;code&gt;x&lt;/code&gt;和&lt;code&gt;y&lt;/code&gt;是否存在相关关系，就可以绘制如下所示的散点图。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;x = np.array([&lt;span class=&#34;number&#34;&gt;5550&lt;/span&gt;,&lt;span class=&#34;number&#34;&gt;7500&lt;/span&gt;,&lt;span class=&#34;number&#34;&gt;10500&lt;/span&gt;,&lt;span class=&#34;number&#34;&gt;15000&lt;/span&gt;,&lt;span class=&#34;number&#34;&gt;20000&lt;/span&gt;,&lt;span class=&#34;number&#34;&gt;25000&lt;/span&gt;,&lt;span class=&#34;number&#34;&gt;30000&lt;/span&gt;,&lt;span class=&#34;number&#34;&gt;40000&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;y = np.array([&lt;span class=&#34;number&#34;&gt;800&lt;/span&gt;,&lt;span class=&#34;number&#34;&gt;1800&lt;/span&gt;,&lt;span class=&#34;number&#34;&gt;1250&lt;/span&gt;,&lt;span class=&#34;number&#34;&gt;2000&lt;/span&gt;,&lt;span class=&#34;number&#34;&gt;1800&lt;/span&gt;,&lt;span class=&#34;number&#34;&gt;2100&lt;/span&gt;,&lt;span class=&#34;number&#34;&gt;2500&lt;/span&gt;,&lt;span class=&#34;number&#34;&gt;3500&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.figure(figsize=(&lt;span class=&#34;number&#34;&gt;6&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;), dpi=&lt;span class=&#34;number&#34;&gt;120&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.scatter(x, y)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.show()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20220501173034.png&#34; style=&#34;zoom:50%;&#34;&gt;

&lt;h5 id=&#34;柱状图&#34;&gt;&lt;a href=&#34;#柱状图&#34; class=&#34;headerlink&#34; title=&#34;柱状图&#34;&gt;&lt;/a&gt;柱状图&lt;/h5&gt;&lt;p&gt;在对比数据的差异时，柱状图是非常棒的选择，我们可以使用&lt;code&gt;pyplot&lt;/code&gt;模块的&lt;code&gt;bar&lt;/code&gt;函数来生成柱状图，也可以使用&lt;code&gt;barh&lt;/code&gt;函数来生成水平柱状图。我们先为柱状图准备一些数据，代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;x = np.arange(&lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;y1 = np.random.randint(&lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;50&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;y2 = np.random.randint(&lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;60&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;绘制柱状图的代码。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;plt.figure(figsize=(&lt;span class=&#34;number&#34;&gt;6&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;), dpi=&lt;span class=&#34;number&#34;&gt;120&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 通过横坐标的偏移，让两组数据对应的柱子分开&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# width参数控制柱子的粗细，label参数为柱子添加标签&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.bar(x - &lt;span class=&#34;number&#34;&gt;0.1&lt;/span&gt;, y1, width=&lt;span class=&#34;number&#34;&gt;0.2&lt;/span&gt;, label=&lt;span class=&#34;string&#34;&gt;&amp;#x27;销售A组&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.bar(x + &lt;span class=&#34;number&#34;&gt;0.1&lt;/span&gt;, y2, width=&lt;span class=&#34;number&#34;&gt;0.2&lt;/span&gt;, label=&lt;span class=&#34;string&#34;&gt;&amp;#x27;销售B组&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 定制横轴的刻度&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.xticks(x, labels=[&lt;span class=&#34;string&#34;&gt;&amp;#x27;Q1&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;Q2&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;Q3&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;Q4&amp;#x27;&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 定制显示图例&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.legend()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.show()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20220501173557.png&#34; style=&#34;zoom:50%;&#34;&gt;

&lt;p&gt;如果想绘制堆叠柱状图，可以对上面的代码稍作修改，如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;labels = [&lt;span class=&#34;string&#34;&gt;&amp;#x27;Q1&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;Q2&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;Q3&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;Q4&amp;#x27;&lt;/span&gt;]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.figure(figsize=(&lt;span class=&#34;number&#34;&gt;6&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;), dpi=&lt;span class=&#34;number&#34;&gt;120&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.bar(labels, y1, width=&lt;span class=&#34;number&#34;&gt;0.4&lt;/span&gt;, label=&lt;span class=&#34;string&#34;&gt;&amp;#x27;销售A组&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 注意：堆叠柱状图的关键是将之前的柱子作为新柱子的底部&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 可以通过bottom参数指定底部数据，新柱子绘制在底部数据之上&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.bar(labels, y2, width=&lt;span class=&#34;number&#34;&gt;0.4&lt;/span&gt;, bottom=y1, label=&lt;span class=&#34;string&#34;&gt;&amp;#x27;销售B组&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.legend(loc=&lt;span class=&#34;string&#34;&gt;&amp;#x27;lower right&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.show()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20220501173645.png&#34; style=&#34;zoom:50%;&#34;&gt;

&lt;h5 id=&#34;饼状图&#34;&gt;&lt;a href=&#34;#饼状图&#34; class=&#34;headerlink&#34; title=&#34;饼状图&#34;&gt;&lt;/a&gt;饼状图&lt;/h5&gt;&lt;p&gt;饼状图通常简称为饼图，是一个将数据划分为几个扇形区域的统计图表，它主要用于描述数量、频率等之间的相对关系。在饼图中，每个扇形区域的大小就是其所表示的数量的比例，这些扇形区域合在一起刚好是一个完整的饼。在需要展示数据构成的场景下，饼状图、树状图和瀑布图是不错的选择，我们可以使用&lt;code&gt;pyplot&lt;/code&gt;模块的&lt;code&gt;pie&lt;/code&gt;函数来绘制饼图，代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;data = np.random.randint(&lt;span class=&#34;number&#34;&gt;100&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;500&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;7&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;labels = [&lt;span class=&#34;string&#34;&gt;&amp;#x27;苹果&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;香蕉&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;桃子&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;荔枝&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;石榴&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;山竹&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;榴莲&amp;#x27;&lt;/span&gt;]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.figure(figsize=(&lt;span class=&#34;number&#34;&gt;5&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;5&lt;/span&gt;), dpi=&lt;span class=&#34;number&#34;&gt;120&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.pie(&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    data,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 自动显示百分比&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    autopct=&lt;span class=&#34;string&#34;&gt;&amp;#x27;%.1f%%&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 饼图的半径&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    radius=&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 百分比到圆心的距离&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    pctdistance=&lt;span class=&#34;number&#34;&gt;0.8&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 颜色（随机生成）&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    colors=np.random.rand(&lt;span class=&#34;number&#34;&gt;7&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;),&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 分离距离&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# explode=[0.05, 0, 0.1, 0, 0, 0, 0],&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 阴影效果&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# shadow=True,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 字体属性&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    textprops=&lt;span class=&#34;built_in&#34;&gt;dict&lt;/span&gt;(fontsize=&lt;span class=&#34;number&#34;&gt;8&lt;/span&gt;, color=&lt;span class=&#34;string&#34;&gt;&amp;#x27;black&amp;#x27;&lt;/span&gt;),&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 楔子属性（生成环状饼图的关键）&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    wedgeprops=&lt;span class=&#34;built_in&#34;&gt;dict&lt;/span&gt;(linewidth=&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, width=&lt;span class=&#34;number&#34;&gt;0.35&lt;/span&gt;),&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 标签&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    labels=labels&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 定制图表的标题&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.title(&lt;span class=&#34;string&#34;&gt;&amp;#x27;水果销售额占比&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.show()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20220502094128.png&#34; style=&#34;zoom:50%;&#34;&gt;

&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;说明&lt;/strong&gt;：大家可以试一试将上面代码中被注释的部分恢复，看看有什么样的效果。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h5 id=&#34;直方图&#34;&gt;&lt;a href=&#34;#直方图&#34; class=&#34;headerlink&#34; title=&#34;直方图&#34;&gt;&lt;/a&gt;直方图&lt;/h5&gt;&lt;p&gt;在统计学中，直方图是一种展示数据分布情况的图形，是一种二维统计图表，它的两个坐标分别是统计样本和该样本对应的某个属性的度量。下面的数据是某学校100名男学生的身高，如果我们想知道数据的分布，就可以使用直方图。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;heights = np.array([&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;number&#34;&gt;170&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;163&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;174&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;164&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;159&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;168&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;165&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;171&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;171&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;167&lt;/span&gt;, &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;number&#34;&gt;165&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;161&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;175&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;170&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;174&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;170&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;174&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;170&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;173&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;173&lt;/span&gt;, &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;number&#34;&gt;167&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;169&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;173&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;153&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;165&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;169&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;158&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;166&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;164&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;173&lt;/span&gt;, &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;number&#34;&gt;162&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;171&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;173&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;171&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;165&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;152&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;163&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;170&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;171&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;163&lt;/span&gt;, &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;number&#34;&gt;165&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;166&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;155&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;155&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;171&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;161&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;167&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;172&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;164&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;155&lt;/span&gt;, &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;number&#34;&gt;168&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;171&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;173&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;169&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;165&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;162&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;168&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;177&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;174&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;178&lt;/span&gt;, &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;number&#34;&gt;161&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;180&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;155&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;155&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;166&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;175&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;159&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;169&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;165&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;174&lt;/span&gt;, &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;number&#34;&gt;175&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;160&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;152&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;168&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;164&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;175&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;168&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;183&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;166&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;166&lt;/span&gt;, &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;number&#34;&gt;182&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;174&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;167&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;168&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;176&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;170&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;169&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;173&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;177&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;168&lt;/span&gt;, &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;number&#34;&gt;172&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;159&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;173&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;185&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;161&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;170&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;170&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;184&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;171&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;172&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;])&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;可以使用&lt;code&gt;pyplot&lt;/code&gt;模块的&lt;code&gt;hist&lt;/code&gt;函数来绘制直方图，代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 将身高数据分到以下8个组中&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;bins = np.array([&lt;span class=&#34;number&#34;&gt;150&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;155&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;160&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;165&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;170&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;175&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;180&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;185&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;190&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.figure(figsize=(&lt;span class=&#34;number&#34;&gt;6&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;), dpi=&lt;span class=&#34;number&#34;&gt;120&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# density参数默认值为False，表示纵轴显示频数&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 将density参数设置为True，纵轴会显示概率密度&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.hist(heights, bins, density=&lt;span class=&#34;literal&#34;&gt;True&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 定制横轴标签&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.xlabel(&lt;span class=&#34;string&#34;&gt;&amp;#x27;身高&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 定制纵轴标签&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.ylabel(&lt;span class=&#34;string&#34;&gt;&amp;#x27;概率密度&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.show()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20220502093924.png&#34; style=&#34;zoom:50%;&#34;&gt;

&lt;h5 id=&#34;箱线图&#34;&gt;&lt;a href=&#34;#箱线图&#34; class=&#34;headerlink&#34; title=&#34;箱线图&#34;&gt;&lt;/a&gt;箱线图&lt;/h5&gt;&lt;p&gt;箱线图又叫箱型图或盒须图，是一种用于展示一组数据分散情况的统计图表，如下所示。因图形如箱子，而且在上下四分位数之外有线条像胡须延伸出去而得名。在箱线图中，箱子的上边界是上四分位数（$Q_3$）的位置，箱子的下边界是下四分位数（$Q_1$）的位置，箱子中间的线条是中位数（$Q_2$）的位置，而箱子的长度就是四分位距离（IQR）。除此之外，箱子上方线条的边界是最大值，箱子下方线条的边界是最小值，这两条线之外的点就是离群值（outlier）。所谓离群值，是指数据小于$Q_1 - 1.5 \times IQR$或数据大于$Q_3 + 1.5 \times IQR$的值，公式中的&lt;code&gt;1.5&lt;/code&gt;还可以替换为&lt;code&gt;3&lt;/code&gt;来发现极端离群值（extreme outlier），而介于&lt;code&gt;1.5&lt;/code&gt;到&lt;code&gt;3&lt;/code&gt;之间的离群值通常称之为适度离群值（mild outlier）。&lt;/p&gt;
&lt;p&gt;可以使用&lt;code&gt;pyplot&lt;/code&gt;模块的&lt;code&gt;boxplot&lt;/code&gt;函数来绘制箱线图，代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 数组中有47个[0, 100)范围的随机数&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;data = np.random.randint(&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;100&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;47&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 向数组中添加三个可能是离群点的数据&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;data = np.append(data, &lt;span class=&#34;number&#34;&gt;160&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;data = np.append(data, &lt;span class=&#34;number&#34;&gt;200&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;data = np.append(data, -&lt;span class=&#34;number&#34;&gt;50&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.figure(figsize=(&lt;span class=&#34;number&#34;&gt;6&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;), dpi=&lt;span class=&#34;number&#34;&gt;120&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# whis参数的默认值是1.5，将其设置为3可以检测极端离群值&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# showmeans=True表示在图中标记均值的位置&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.boxplot(data, whis=&lt;span class=&#34;number&#34;&gt;1.5&lt;/span&gt;, showmeans=&lt;span class=&#34;literal&#34;&gt;True&lt;/span&gt;, notch=&lt;span class=&#34;literal&#34;&gt;True&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 定制纵轴的取值范围&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.ylim([-&lt;span class=&#34;number&#34;&gt;100&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;250&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 定制横轴的刻度&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.xticks([&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;], labels=[&lt;span class=&#34;string&#34;&gt;&amp;#x27;data&amp;#x27;&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.show()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20220501172802.png&#34; style=&#34;zoom:50%;&#34; /&gt;

&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;说明&lt;/strong&gt;：由于数据是随机生成的，所以大家运行上面的代码生成的图可能跟我这里并不相同。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h4 id=&#34;显示或保存图像&#34;&gt;&lt;a href=&#34;#显示或保存图像&#34; class=&#34;headerlink&#34; title=&#34;显示或保存图像&#34;&gt;&lt;/a&gt;显示或保存图像&lt;/h4&gt;&lt;p&gt;可以使用&lt;code&gt;pyplot&lt;/code&gt;模块的&lt;code&gt;show&lt;/code&gt;函数来显示绘制的图表，我们在上面的代码中使用过这个函数。如果希望保存图表，可以使用&lt;code&gt;savefig&lt;/code&gt;函数。需要注意的是，如果要同时显示和保存图表，应该先执行&lt;code&gt;savefig&lt;/code&gt;函数，再执行&lt;code&gt;show&lt;/code&gt;函数，因为在调用&lt;code&gt;show&lt;/code&gt;函数时，图表已经被释放，位于&lt;code&gt;show&lt;/code&gt;函数之后的&lt;code&gt;savefig&lt;/code&gt;保存的只是一个空白的区域。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;plt.savefig(&lt;span class=&#34;string&#34;&gt;&amp;#x27;chart.png&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.show()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h3 id=&#34;其他图表&#34;&gt;&lt;a href=&#34;#其他图表&#34; class=&#34;headerlink&#34; title=&#34;其他图表&#34;&gt;&lt;/a&gt;其他图表&lt;/h3&gt;&lt;p&gt;使用 matplotlib，我们还可以绘制出其他的统计图表（如：雷达图、玫瑰图、热力图等），但实际工作中，使用频率最高的几类图表我们在上面已经为大家完整的展示出来了。此外，matplotlib 还有很多对统计图表进行定制的细节，例如定制坐标轴、定制图表上的文字和标签等。如果想了解如何用 matplotlib 绘制和定制更多的统计图表，可以直接查看 matplotlib 官方网站上的&lt;a href=&#34;https://matplotlib.org/stable/tutorials/index.html&#34;&gt;文档&lt;/a&gt;和&lt;a href=&#34;https://matplotlib.org/stable/gallery/index.html&#34;&gt;示例&lt;/a&gt;。&lt;/p&gt;

 &lt;h2 id=&#34;Pandas的应用-5&#34;&gt;&lt;a href=&#34;#Pandas的应用-5&#34; class=&#34;headerlink&#34; title=&#34;Pandas的应用-5&#34;&gt;&lt;/a&gt;Pandas的应用-5&lt;/h2&gt;&lt;h3 id=&#34;DataFrame的应用&#34;&gt;&lt;a href=&#34;#DataFrame的应用&#34; class=&#34;headerlink&#34; title=&#34;DataFrame的应用&#34;&gt;&lt;/a&gt;DataFrame的应用&lt;/h3&gt;&lt;h4 id=&#34;窗口计算&#34;&gt;&lt;a href=&#34;#窗口计算&#34; class=&#34;headerlink&#34; title=&#34;窗口计算&#34;&gt;&lt;/a&gt;窗口计算&lt;/h4&gt;&lt;p&gt;&lt;code&gt;DataFrame&lt;/code&gt;对象的&lt;code&gt;rolling&lt;/code&gt;方法允许我们将数据置于窗口中，然后就可以使用函数对窗口中的数据进行运算和处理。例如，我们获取了某只股票近期的数据，想制作5日均线和10日均线，那么就需要先设置窗口再进行运算。我们可以使用三方库&lt;code&gt;pandas-datareader&lt;/code&gt;来获取指定的股票在某个时间段内的数据，具体的操作如下所示。&lt;/p&gt;
&lt;p&gt;安装&lt;code&gt;pandas-datareader&lt;/code&gt;三方库。&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;pip install pandas-datareader&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;通过&lt;code&gt;pandas-datareader&lt;/code&gt; 提供的&lt;code&gt;get_data_stooq&lt;/code&gt;从 Stooq 网站获取百度（股票代码：BIDU）近期股票数据。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; pandas_datareader &lt;span class=&#34;keyword&#34;&gt;as&lt;/span&gt; pdr&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;baidu_df = pdr.get_data_stooq(&lt;span class=&#34;string&#34;&gt;&amp;#x27;BIDU&amp;#x27;&lt;/span&gt;, start=&lt;span class=&#34;string&#34;&gt;&amp;#x27;2021-11-22&amp;#x27;&lt;/span&gt;, end=&lt;span class=&#34;string&#34;&gt;&amp;#x27;2021-12-7&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;baidu_df.sort_index(inplace=&lt;span class=&#34;literal&#34;&gt;True&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;baidu_df&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20211208205710.png&#34; style=&#34;zoom:38%;&#34;&gt;

&lt;p&gt;上面的&lt;code&gt;DataFrame&lt;/code&gt;有&lt;code&gt;Open&lt;/code&gt;、&lt;code&gt;High&lt;/code&gt;、&lt;code&gt;Low&lt;/code&gt;、&lt;code&gt;Close&lt;/code&gt;、&lt;code&gt;Volume&lt;/code&gt;五个列，分别代码股票的开盘价、最高价、最低价、收盘价和成交量，接下来我们对百度的股票数据进行窗口计算。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;baidu_df.rolling(&lt;span class=&#34;number&#34;&gt;5&lt;/span&gt;).mean()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20211208205932.png&#34; style=&#34;zoom:38%;&#34;&gt;

&lt;p&gt;上面的&lt;code&gt;Close&lt;/code&gt; 列的数据就是我们需要的5日均线，当然，我们也可以用下面的方法，直接在&lt;code&gt;Close&lt;/code&gt;列对应的&lt;code&gt;Series&lt;/code&gt;对象上计算5日均线。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;baidu_df.Close.rolling(&lt;span class=&#34;number&#34;&gt;5&lt;/span&gt;).mean()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight apache&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;Date&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;2021&lt;/span&gt;-&lt;span class=&#34;number&#34;&gt;11&lt;/span&gt;-&lt;span class=&#34;number&#34;&gt;22&lt;/span&gt;        NaN&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;2021&lt;/span&gt;-&lt;span class=&#34;number&#34;&gt;11&lt;/span&gt;-&lt;span class=&#34;number&#34;&gt;23&lt;/span&gt;        NaN&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;2021&lt;/span&gt;-&lt;span class=&#34;number&#34;&gt;11&lt;/span&gt;-&lt;span class=&#34;number&#34;&gt;24&lt;/span&gt;        NaN&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;2021&lt;/span&gt;-&lt;span class=&#34;number&#34;&gt;11&lt;/span&gt;-&lt;span class=&#34;number&#34;&gt;26&lt;/span&gt;        NaN&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;2021&lt;/span&gt;-&lt;span class=&#34;number&#34;&gt;11&lt;/span&gt;-&lt;span class=&#34;number&#34;&gt;29&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;150&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;608&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;2021&lt;/span&gt;-&lt;span class=&#34;number&#34;&gt;11&lt;/span&gt;-&lt;span class=&#34;number&#34;&gt;30&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;151&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;014&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;2021&lt;/span&gt;-&lt;span class=&#34;number&#34;&gt;12&lt;/span&gt;-&lt;span class=&#34;number&#34;&gt;01&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;150&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;682&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;2021&lt;/span&gt;-&lt;span class=&#34;number&#34;&gt;12&lt;/span&gt;-&lt;span class=&#34;number&#34;&gt;02&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;150&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;196&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;2021&lt;/span&gt;-&lt;span class=&#34;number&#34;&gt;12&lt;/span&gt;-&lt;span class=&#34;number&#34;&gt;03&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;147&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;062&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;2021&lt;/span&gt;-&lt;span class=&#34;number&#34;&gt;12&lt;/span&gt;-&lt;span class=&#34;number&#34;&gt;06&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;146&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;534&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;2021&lt;/span&gt;-&lt;span class=&#34;number&#34;&gt;12&lt;/span&gt;-&lt;span class=&#34;number&#34;&gt;07&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;146&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;544&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;Name&lt;/span&gt;: Close, dtype: float64&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h4 id=&#34;相关性判定&#34;&gt;&lt;a href=&#34;#相关性判定&#34; class=&#34;headerlink&#34; title=&#34;相关性判定&#34;&gt;&lt;/a&gt;相关性判定&lt;/h4&gt;&lt;p&gt;在统计学中，我们通常使用协方差（covariance）来衡量两个随机变量的联合变化程度。如果变量 $X$ 的较大值主要与另一个变量 $Y$ 的较大值相对应，而两者较小值也相对应，那么两个变量倾向于表现出相似的行为，协方差为正。如果一个变量的较大值主要对应于另一个变量的较小值，则两个变量倾向于表现出相反的行为，协方差为负。简单的说，协方差的正负号显示着两个变量的相关性。方差是协方差的一种特殊情况，即变量与自身的协方差。&lt;/p&gt;
&lt;p&gt;$$&lt;br&gt;cov(X,Y) &amp;#x3D; E((X - \mu)(Y - \upsilon)) &amp;#x3D; E(X \cdot Y) - \mu\upsilon&lt;br&gt;$$&lt;/p&gt;
&lt;p&gt;如果 $X$ 和 $Y$ 是统计独立的，那么二者的协方差为0，这是因为在 $X$ 和 $Y$ 独立的情况下：&lt;/p&gt;
&lt;p&gt;$$&lt;br&gt;E(X \cdot Y) &amp;#x3D; E(X) \cdot E(Y) &amp;#x3D; \mu\upsilon&lt;br&gt;$$&lt;/p&gt;
&lt;p&gt;协方差的数值大小取决于变量的大小，通常是不容易解释的，但是正态形式的协方差大小可以显示两变量线性关系的强弱。在统计学中，皮尔逊积矩相关系数就是正态形式的协方差，它用于度量两个变量 $X$ 和 $Y$ 之间的相关程度（线性相关），其值介于&lt;code&gt;-1&lt;/code&gt;到&lt;code&gt;1&lt;/code&gt;之间。&lt;/p&gt;
&lt;p&gt;$$&lt;br&gt;\rho{X,Y} &amp;#x3D; \frac {cov(X, Y)} {\sigma_{X}\sigma_{Y}}&lt;br&gt;$$&lt;/p&gt;
&lt;p&gt;估算样本的协方差和标准差，可以得到样本皮尔逊系数，通常用希腊字母 $\rho$ 表示。&lt;/p&gt;
&lt;p&gt;$$&lt;br&gt;\rho &amp;#x3D; \frac {\sum_{i&amp;#x3D;1}^{n}(X_i - \bar{X})(Y_i - \bar{Y})} {\sqrt{\sum_{i&amp;#x3D;1}^{n}(X_i - \bar{X})^2} \sqrt{\sum_{i&amp;#x3D;1}^{n}(Y_i - \bar{Y})^2}}&lt;br&gt;$$&lt;/p&gt;
&lt;p&gt;我们用 $\rho$ 值判断指标的相关性时遵循以下两个步骤。&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;判断指标间是正相关、负相关，还是不相关。&lt;ul&gt;
&lt;li&gt;当 $ \rho \gt 0 $，认为变量之间是正相关，也就是两者的趋势一致。&lt;/li&gt;
&lt;li&gt;当 $ \rho \lt 0 $，认为变量之间是负相关，也就是两者的趋势相反。&lt;/li&gt;
&lt;li&gt;当 $ \rho &amp;#x3D; 0 $，认为变量之间是不相关的，但并不代表两个指标是统计独立的。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;判断指标间的相关程度。&lt;ul&gt;
&lt;li&gt;当 $ \rho $ 的绝对值在 $ [0.6,1] $ 之间，认为变量之间是强相关的。&lt;/li&gt;
&lt;li&gt;当 $ \rho $ 的绝对值在 $ [0.1,0.6) $ 之间，认为变量之间是弱相关的。&lt;/li&gt;
&lt;li&gt;当 $ \rho $ 的绝对值在 $ [0,0.1) $ 之间，认为变量之间没有相关性。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;皮尔逊相关系数适用于：&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;两个变量之间是线性关系，都是连续数据。&lt;/li&gt;
&lt;li&gt;两个变量的总体是正态分布，或接近正态的单峰分布。&lt;/li&gt;
&lt;li&gt;两个变量的观测值是成对的，每对观测值之间相互独立。&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;&lt;code&gt;DataFrame&lt;/code&gt;对象的&lt;code&gt;cov&lt;/code&gt;方法和&lt;code&gt;corr&lt;/code&gt;方法分别用于计算协方差和相关系数，&lt;code&gt;corr&lt;/code&gt;方法的第一个参数&lt;code&gt;method&lt;/code&gt;的默认值是&lt;code&gt;pearson&lt;/code&gt;，表示计算皮尔逊相关系数；除此之外，还可以指定&lt;code&gt;kendall&lt;/code&gt;或&lt;code&gt;spearman&lt;/code&gt;来获得肯德尔系数或斯皮尔曼等级相关系数。&lt;/p&gt;
&lt;p&gt;接下来，我们从名为&lt;code&gt;boston_house_price.csv&lt;/code&gt;的文件中获取著名的&lt;a href=&#34;https://www.heywhale.com/mw/dataset/590bd595812ede32b73f55f2&#34;&gt;波士顿房价数据集&lt;/a&gt;来创建一个&lt;code&gt;DataFrame&lt;/code&gt;，我们通过&lt;code&gt;corr&lt;/code&gt;方法计算可能影响房价的&lt;code&gt;13&lt;/code&gt;个因素中，哪些跟房价是正相关或负相关的，代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;boston_df = pd.read_csv(&lt;span class=&#34;string&#34;&gt;&amp;#x27;data/csv/boston_house_price.csv&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;boston_df.corr()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;说明&lt;/strong&gt;：如果需要上面例子中的 CSV 文件，可以通过下面的百度云盘地址进行获取，数据在《从零开始学数据分析》目录中。链接：&lt;a href=&#34;https://pan.baidu.com/s/1rQujl5RQn9R7PadB2Z5g_g&#34;&gt;https://pan.baidu.com/s/1rQujl5RQn9R7PadB2Z5g_g&lt;/a&gt;，提取码：e7b4。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;输出：&lt;/p&gt;
&lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20211208213325.png&#34;&gt;

&lt;p&gt;斯皮尔曼相关系数对数据条件的要求没有皮尔逊相关系数严格，只要两个变量的观测值是成对的等级评定资料，或者是由连续变量观测资料转化得到的等级资料，不论两个变量的总体分布形态、样本容量的大小如何，都可以用斯皮尔曼等级相关系数来进行研究。我们通过下面的方式来计算斯皮尔曼相关系数。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;boston_df.corr(&lt;span class=&#34;string&#34;&gt;&amp;#x27;spearman&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; 输出：&lt;/p&gt;
&lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20211208213518.png&#34;&gt;

&lt;p&gt;在 Notebook 或 JupyterLab 中，我们可以为&lt;code&gt;PRICE&lt;/code&gt;列添加渐变色，用颜色直观的展示出跟房价负相关、正相关、不相关的列，&lt;code&gt;DataFrame&lt;/code&gt;对象&lt;code&gt;style&lt;/code&gt;属性的&lt;code&gt;background_gradient&lt;/code&gt;方法可以完成这个操作，代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;boston_df.corr(&lt;span class=&#34;string&#34;&gt;&amp;#x27;spearman&amp;#x27;&lt;/span&gt;).style.background_gradient(&lt;span class=&#34;string&#34;&gt;&amp;#x27;RdYlBu&amp;#x27;&lt;/span&gt;, subset=[&lt;span class=&#34;string&#34;&gt;&amp;#x27;PRICE&amp;#x27;&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20211208215228.png&#34;&gt;

&lt;p&gt;上面代码中的&lt;code&gt;RdYlBu&lt;/code&gt;代表的颜色如下所示，相关系数的数据值越接近&lt;code&gt;1&lt;/code&gt;，颜色越接近红色；数据值越接近&lt;code&gt;1&lt;/code&gt;，颜色越接近蓝色；数据值在&lt;code&gt;0&lt;/code&gt;附件则是黄色。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;plt.get_cmap(&lt;span class=&#34;string&#34;&gt;&amp;#x27;RdYlBu&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20211208215057.png&#34;&gt;

&lt;h3 id=&#34;Index的应用&#34;&gt;&lt;a href=&#34;#Index的应用&#34; class=&#34;headerlink&#34; title=&#34;Index的应用&#34;&gt;&lt;/a&gt;Index的应用&lt;/h3&gt;&lt;p&gt;我们再来看看&lt;code&gt;Index&lt;/code&gt;类型，它为&lt;code&gt;Series&lt;/code&gt;和&lt;code&gt;DataFrame&lt;/code&gt;对象提供了索引服务，常用的&lt;code&gt;Index&lt;/code&gt;有以下几种。&lt;/p&gt;
&lt;h4 id=&#34;范围索引（RangeIndex）&#34;&gt;&lt;a href=&#34;#范围索引（RangeIndex）&#34; class=&#34;headerlink&#34; title=&#34;范围索引（RangeIndex）&#34;&gt;&lt;/a&gt;范围索引（RangeIndex）&lt;/h4&gt;&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;sales_data = np.random.randint(&lt;span class=&#34;number&#34;&gt;400&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;1000&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;12&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;month_index = pd.RangeIndex(&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;13&lt;/span&gt;, name=&lt;span class=&#34;string&#34;&gt;&amp;#x27;月份&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;ser = pd.Series(data=sales_data, index=month_index)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;ser&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight angelscript&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;月份&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;     &lt;span class=&#34;number&#34;&gt;703&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;     &lt;span class=&#34;number&#34;&gt;705&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;     &lt;span class=&#34;number&#34;&gt;557&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;     &lt;span class=&#34;number&#34;&gt;943&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;5&lt;/span&gt;     &lt;span class=&#34;number&#34;&gt;961&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;6&lt;/span&gt;     &lt;span class=&#34;number&#34;&gt;615&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;7&lt;/span&gt;     &lt;span class=&#34;number&#34;&gt;788&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;8&lt;/span&gt;     &lt;span class=&#34;number&#34;&gt;985&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;9&lt;/span&gt;     &lt;span class=&#34;number&#34;&gt;921&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;951&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;11&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;874&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;12&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;609&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;dtype: &lt;span class=&#34;built_in&#34;&gt;int64&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h4 id=&#34;分类索引（CategoricalIndex）&#34;&gt;&lt;a href=&#34;#分类索引（CategoricalIndex）&#34; class=&#34;headerlink&#34; title=&#34;分类索引（CategoricalIndex）&#34;&gt;&lt;/a&gt;分类索引（CategoricalIndex）&lt;/h4&gt;&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;cate_index = pd.CategoricalIndex(&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    [&lt;span class=&#34;string&#34;&gt;&amp;#x27;苹果&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;香蕉&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;苹果&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;苹果&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;桃子&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;香蕉&amp;#x27;&lt;/span&gt;],&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    ordered=&lt;span class=&#34;literal&#34;&gt;True&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    categories=[&lt;span class=&#34;string&#34;&gt;&amp;#x27;苹果&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;香蕉&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;桃子&amp;#x27;&lt;/span&gt;]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;ser = pd.Series(data=amount, index=cate_index)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;ser&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight angelscript&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;苹果    &lt;span class=&#34;number&#34;&gt;6&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;香蕉    &lt;span class=&#34;number&#34;&gt;6&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;苹果    &lt;span class=&#34;number&#34;&gt;7&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;苹果    &lt;span class=&#34;number&#34;&gt;6&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;桃子    &lt;span class=&#34;number&#34;&gt;8&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;香蕉    &lt;span class=&#34;number&#34;&gt;6&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;dtype: &lt;span class=&#34;built_in&#34;&gt;int64&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;ser.groupby(level=&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;).&lt;span class=&#34;built_in&#34;&gt;sum&lt;/span&gt;()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight angelscript&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;苹果    &lt;span class=&#34;number&#34;&gt;19&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;香蕉    &lt;span class=&#34;number&#34;&gt;12&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;桃子     &lt;span class=&#34;number&#34;&gt;8&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;dtype: &lt;span class=&#34;built_in&#34;&gt;int64&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h4 id=&#34;多级索引（MultiIndex）&#34;&gt;&lt;a href=&#34;#多级索引（MultiIndex）&#34; class=&#34;headerlink&#34; title=&#34;多级索引（MultiIndex）&#34;&gt;&lt;/a&gt;多级索引（MultiIndex）&lt;/h4&gt;&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;ids = np.arange(&lt;span class=&#34;number&#34;&gt;1001&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;1006&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;sms = [&lt;span class=&#34;string&#34;&gt;&amp;#x27;期中&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;期末&amp;#x27;&lt;/span&gt;]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;index = pd.MultiIndex.from_product((ids, sms), names=[&lt;span class=&#34;string&#34;&gt;&amp;#x27;学号&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;学期&amp;#x27;&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;courses = [&lt;span class=&#34;string&#34;&gt;&amp;#x27;语文&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;数学&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;英语&amp;#x27;&lt;/span&gt;]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;scores = np.random.randint(&lt;span class=&#34;number&#34;&gt;60&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;101&lt;/span&gt;, (&lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;))&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;df = pd.DataFrame(data=scores, columns=courses, index=index)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;df&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;说明&lt;/strong&gt;：上面的代码使用了&lt;code&gt;MultiIndex&lt;/code&gt;的类方法&lt;code&gt;from_product&lt;/code&gt;，该方法通过&lt;code&gt;ids&lt;/code&gt;和&lt;code&gt;sms&lt;/code&gt;两组数据的笛卡尔积构造了多级索引。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight yaml&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;             &lt;span class=&#34;string&#34;&gt;语文&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;数学&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;英语&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;学号&lt;/span&gt;	&lt;span class=&#34;string&#34;&gt;学期&lt;/span&gt;			&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;1001&lt;/span&gt;  &lt;span class=&#34;string&#34;&gt;期中&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;93&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;77&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;60&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;span class=&#34;string&#34;&gt;期末&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;93&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;98&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;84&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;1002&lt;/span&gt;  &lt;span class=&#34;string&#34;&gt;期中&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;64&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;78&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;71&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;span class=&#34;string&#34;&gt;期末&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;70&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;71&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;97&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;1003&lt;/span&gt;  &lt;span class=&#34;string&#34;&gt;期中&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;72&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;88&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;97&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;span class=&#34;string&#34;&gt;期末&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;99&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;100&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;63&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;1004&lt;/span&gt;  &lt;span class=&#34;string&#34;&gt;期中&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;80&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;71&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;61&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;span class=&#34;string&#34;&gt;期末&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;91&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;62&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;72&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;1005&lt;/span&gt;  &lt;span class=&#34;string&#34;&gt;期中&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;82&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;95&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;67&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;span class=&#34;string&#34;&gt;期末&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;84&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;78&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;86&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 计算每个学生的成绩，期中占25%，期末占75%&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;df.groupby(level=&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;).agg(&lt;span class=&#34;keyword&#34;&gt;lambda&lt;/span&gt; x: x.values[&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;] * &lt;span class=&#34;number&#34;&gt;0.25&lt;/span&gt; + x.values[&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;] * &lt;span class=&#34;number&#34;&gt;0.75&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight dns&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;        语文    数学    英语&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;学号			&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;1001	93.00&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;92.75	78.00&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;1002	68.50&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;72.75	90.50&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;1003	92.25&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;97.00	71.50&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;1004	88.25&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;64.25	69.25&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;1005	83.50&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;82.25	81.25&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h4 id=&#34;日期时间索引（DatetimeIndex）&#34;&gt;&lt;a href=&#34;#日期时间索引（DatetimeIndex）&#34; class=&#34;headerlink&#34; title=&#34;日期时间索引（DatetimeIndex）&#34;&gt;&lt;/a&gt;日期时间索引（DatetimeIndex）&lt;/h4&gt;&lt;ol&gt;
&lt;li&gt;&lt;p&gt;通过&lt;code&gt;date_range()&lt;/code&gt;函数，我们可以创建日期时间索引，代码如下所示。&lt;/p&gt;
&lt;p&gt; 代码：&lt;/p&gt;
 &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;pd.date_range(&lt;span class=&#34;string&#34;&gt;&amp;#x27;2021-1-1&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;2021-6-1&amp;#x27;&lt;/span&gt;, periods=&lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; 输出：&lt;/p&gt;
 &lt;figure class=&#34;highlight 1c&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;DatetimeIndex([&amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-01-01&lt;/span&gt; 00:00:00&amp;#x27;, &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-01-17&lt;/span&gt; 18:40:00&amp;#x27;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;               &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-02-03&lt;/span&gt; 13:20:00&amp;#x27;, &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-02-20&lt;/span&gt; 08:00:00&amp;#x27;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;               &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-03-09&lt;/span&gt; 02:40:00&amp;#x27;, &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-03-25&lt;/span&gt; 21:20:00&amp;#x27;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;               &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-04-11&lt;/span&gt; 16:00:00&amp;#x27;, &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-04-28&lt;/span&gt; 10:40:00&amp;#x27;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;               &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-05-15&lt;/span&gt; 05:20:00&amp;#x27;, &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-06-01&lt;/span&gt; 00:00:00&amp;#x27;],&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;              dtype=&amp;#x27;datetime64[ns]&amp;#x27;, freq=None)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; 代码：&lt;/p&gt;
 &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;pd.date_range(&lt;span class=&#34;string&#34;&gt;&amp;#x27;2021-1-1&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;2021-6-1&amp;#x27;&lt;/span&gt;, freq=&lt;span class=&#34;string&#34;&gt;&amp;#x27;W&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; 输出：&lt;/p&gt;
 &lt;figure class=&#34;highlight 1c&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;DatetimeIndex([&amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-01-03&lt;/span&gt;&amp;#x27;, &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-01-10&lt;/span&gt;&amp;#x27;, &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-01-17&lt;/span&gt;&amp;#x27;, &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-01-24&lt;/span&gt;&amp;#x27;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;               &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-01-31&lt;/span&gt;&amp;#x27;, &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-02-07&lt;/span&gt;&amp;#x27;, &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-02-14&lt;/span&gt;&amp;#x27;, &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-02-21&lt;/span&gt;&amp;#x27;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;               &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-02-28&lt;/span&gt;&amp;#x27;, &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-03-07&lt;/span&gt;&amp;#x27;, &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-03-14&lt;/span&gt;&amp;#x27;, &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-03-21&lt;/span&gt;&amp;#x27;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;               &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-03-28&lt;/span&gt;&amp;#x27;, &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-04-04&lt;/span&gt;&amp;#x27;, &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-04-11&lt;/span&gt;&amp;#x27;, &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-04-18&lt;/span&gt;&amp;#x27;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;               &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-04-25&lt;/span&gt;&amp;#x27;, &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-05-02&lt;/span&gt;&amp;#x27;, &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-05-09&lt;/span&gt;&amp;#x27;, &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-05-16&lt;/span&gt;&amp;#x27;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;               &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-05-23&lt;/span&gt;&amp;#x27;, &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-05-30&lt;/span&gt;&amp;#x27;],&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;              dtype=&amp;#x27;datetime64[ns]&amp;#x27;, freq=&amp;#x27;W-SUN&amp;#x27;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;通过&lt;code&gt;DateOffset&lt;/code&gt;类型，我们可以设置时间差并和&lt;code&gt;DatetimeIndex&lt;/code&gt;进行运算，具体的操作如下所示。&lt;/p&gt;
&lt;p&gt; 代码：&lt;/p&gt;
 &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;index = pd.date_range(&lt;span class=&#34;string&#34;&gt;&amp;#x27;2021-1-1&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;2021-6-1&amp;#x27;&lt;/span&gt;, freq=&lt;span class=&#34;string&#34;&gt;&amp;#x27;W&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;index - pd.DateOffset(days=&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; 输出：&lt;/p&gt;
 &lt;figure class=&#34;highlight 1c&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;DatetimeIndex([&amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-01-01&lt;/span&gt;&amp;#x27;, &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-01-08&lt;/span&gt;&amp;#x27;, &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-01-15&lt;/span&gt;&amp;#x27;, &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-01-22&lt;/span&gt;&amp;#x27;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;               &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-01-29&lt;/span&gt;&amp;#x27;, &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-02-05&lt;/span&gt;&amp;#x27;, &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-02-12&lt;/span&gt;&amp;#x27;, &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-02-19&lt;/span&gt;&amp;#x27;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;               &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-02-26&lt;/span&gt;&amp;#x27;, &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-03-05&lt;/span&gt;&amp;#x27;, &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-03-12&lt;/span&gt;&amp;#x27;, &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-03-19&lt;/span&gt;&amp;#x27;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;               &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-03-26&lt;/span&gt;&amp;#x27;, &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-04-02&lt;/span&gt;&amp;#x27;, &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-04-09&lt;/span&gt;&amp;#x27;, &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-04-16&lt;/span&gt;&amp;#x27;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;               &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-04-23&lt;/span&gt;&amp;#x27;, &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-04-30&lt;/span&gt;&amp;#x27;, &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-05-07&lt;/span&gt;&amp;#x27;, &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-05-14&lt;/span&gt;&amp;#x27;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;               &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-05-21&lt;/span&gt;&amp;#x27;, &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-05-28&lt;/span&gt;&amp;#x27;],&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;              dtype=&amp;#x27;datetime64[ns]&amp;#x27;, freq=None)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; 代码：&lt;/p&gt;
 &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;index + pd.DateOffset(days=&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; 输出：&lt;/p&gt;
 &lt;figure class=&#34;highlight 1c&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;DatetimeIndex([&amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-01-05&lt;/span&gt;&amp;#x27;, &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-01-12&lt;/span&gt;&amp;#x27;, &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-01-19&lt;/span&gt;&amp;#x27;, &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-01-26&lt;/span&gt;&amp;#x27;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;               &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-02-02&lt;/span&gt;&amp;#x27;, &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-02-09&lt;/span&gt;&amp;#x27;, &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-02-16&lt;/span&gt;&amp;#x27;, &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-02-23&lt;/span&gt;&amp;#x27;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;               &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-03-02&lt;/span&gt;&amp;#x27;, &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-03-09&lt;/span&gt;&amp;#x27;, &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-03-16&lt;/span&gt;&amp;#x27;, &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-03-23&lt;/span&gt;&amp;#x27;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;               &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-03-30&lt;/span&gt;&amp;#x27;, &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-04-06&lt;/span&gt;&amp;#x27;, &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-04-13&lt;/span&gt;&amp;#x27;, &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-04-20&lt;/span&gt;&amp;#x27;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;               &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-04-27&lt;/span&gt;&amp;#x27;, &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-05-04&lt;/span&gt;&amp;#x27;, &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-05-11&lt;/span&gt;&amp;#x27;, &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-05-18&lt;/span&gt;&amp;#x27;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;               &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-05-25&lt;/span&gt;&amp;#x27;, &amp;#x27;&lt;span class=&#34;number&#34;&gt;2021-06-01&lt;/span&gt;&amp;#x27;],&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;              dtype=&amp;#x27;datetime64[ns]&amp;#x27;, freq=None)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;可以使用&lt;code&gt;DatatimeIndex&lt;/code&gt;类型的相关方法来处理数据，具体包括：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;p&gt;&lt;code&gt;shift()&lt;/code&gt;方法：通过时间前移或后移数据，我们仍然以上面百度股票数据为例，代码如下所示。&lt;/p&gt;
&lt;p&gt;  代码：&lt;/p&gt;
  &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;baidu_df.shift(&lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;, fill_value=&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;  输出：&lt;/p&gt;
  &lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20211208220551.png&#34; style=&#34;zoom:150%;&#34;&gt;

&lt;p&gt;  代码：&lt;/p&gt;
  &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;baidu_df.shift(-&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, fill_value=&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;  输出：&lt;/p&gt;
  &lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20211208220713.png&#34; style=&#34;zoom:150%;&#34;&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;code&gt;asfreq()&lt;/code&gt;方法：指定一个时间频率抽取对应的数据，代码如下所示。&lt;/p&gt;
&lt;p&gt;  代码：&lt;/p&gt;
  &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;baidu_df.asfreq(&lt;span class=&#34;string&#34;&gt;&amp;#x27;5D&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;  输出：&lt;/p&gt;
  &lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20211208221202.png&#34;&gt;

&lt;p&gt;  代码：&lt;/p&gt;
  &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;baidu_df.asfreq(&lt;span class=&#34;string&#34;&gt;&amp;#x27;5D&amp;#x27;&lt;/span&gt;, method=&lt;span class=&#34;string&#34;&gt;&amp;#x27;ffill&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;  输出：&lt;/p&gt;
  &lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20211208221249.png&#34; style=&#34;zoom:150%;&#34;&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;code&gt;resample()&lt;/code&gt;方法：基于时间对数据进行重采样，相当于根据时间周期对数据进行了分组操作，代码如下所示。&lt;/p&gt;
&lt;p&gt;  代码：&lt;/p&gt;
  &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;baidu_df.resample(&lt;span class=&#34;string&#34;&gt;&amp;#x27;1M&amp;#x27;&lt;/span&gt;).mean()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;  输出：&lt;/p&gt;
  &lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20211208221429.png&#34;&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;说明&lt;/strong&gt;：上面的代码中，&lt;code&gt;W&lt;/code&gt;表示一周，&lt;code&gt;5D&lt;/code&gt;表示&lt;code&gt;5&lt;/code&gt;天，&lt;code&gt;1M&lt;/code&gt;表示&lt;code&gt;1&lt;/code&gt;个月。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;时区转换&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;p&gt;获取时区信息。&lt;/p&gt;
  &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; pytz&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;pytz.common_timezones&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;code&gt;tz_localize()&lt;/code&gt;方法：将日期时间本地化。&lt;/p&gt;
&lt;p&gt;  代码：&lt;/p&gt;
  &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;baidu_df = baidu_df.tz_localize(&lt;span class=&#34;string&#34;&gt;&amp;#x27;Asia/Chongqing&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;baidu_df&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;  输出：&lt;/p&gt;
  &lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20211208221947.png&#34;&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;code&gt;tz_convert()&lt;/code&gt;方法：转换时区。&lt;/p&gt;
&lt;p&gt;  代码：&lt;/p&gt;
  &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;baidu_df.tz_convert(&lt;span class=&#34;string&#34;&gt;&amp;#x27;America/New_York&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;  输出：&lt;/p&gt;
  &lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20211208222404.png&#34;&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ol&gt;

 &lt;h2 id=&#34;Pandas的应用-4&#34;&gt;&lt;a href=&#34;#Pandas的应用-4&#34; class=&#34;headerlink&#34; title=&#34;Pandas的应用-4&#34;&gt;&lt;/a&gt;Pandas的应用-4&lt;/h2&gt;&lt;h3 id=&#34;DataFrame的应用&#34;&gt;&lt;a href=&#34;#DataFrame的应用&#34; class=&#34;headerlink&#34; title=&#34;DataFrame的应用&#34;&gt;&lt;/a&gt;DataFrame的应用&lt;/h3&gt;&lt;h4 id=&#34;数据分析&#34;&gt;&lt;a href=&#34;#数据分析&#34; class=&#34;headerlink&#34; title=&#34;数据分析&#34;&gt;&lt;/a&gt;数据分析&lt;/h4&gt;&lt;p&gt;经过前面的学习，我们已经将数据准备就绪而且变成了我们想要的样子，接下来就是最为重要的数据分析阶段了。当我们拿到一大堆数据的时候，如何从数据中迅速的解读出有价值的信息，这就是数据分析要解决的问题。首先，我们可以获取数据的描述性统计信息，通过描述性统计信息，我们可以了解数据的集中趋势和离散趋势。&lt;/p&gt;
&lt;p&gt;例如，我们有如下所示的学生成绩表。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; numpy &lt;span class=&#34;keyword&#34;&gt;as&lt;/span&gt; np&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; pandas &lt;span class=&#34;keyword&#34;&gt;as&lt;/span&gt; pd&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;scores = np.random.randint(&lt;span class=&#34;number&#34;&gt;50&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;101&lt;/span&gt;, (&lt;span class=&#34;number&#34;&gt;5&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;))&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;names = (&lt;span class=&#34;string&#34;&gt;&amp;#x27;关羽&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;张飞&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;赵云&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;马超&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;黄忠&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;courses = (&lt;span class=&#34;string&#34;&gt;&amp;#x27;语文&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;数学&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;英语&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;df = pd.DataFrame(data=scores, columns=courses, index=names)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;df&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight tap&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;     语文   数学   英语&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;关羽 &lt;span class=&#34;number&#34;&gt; 96 &lt;/span&gt;  &lt;span class=&#34;number&#34;&gt; 72 &lt;/span&gt;   73&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;张飞 &lt;span class=&#34;number&#34;&gt; 72 &lt;/span&gt;   70	97&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;赵云 &lt;span class=&#34;number&#34;&gt; 74 &lt;/span&gt;   51	79&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;马超 &lt;span class=&#34;number&#34;&gt; 100 &lt;/span&gt;  54	54&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;黄忠 &lt;span class=&#34;number&#34;&gt; 89 &lt;/span&gt;   100	88&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;我们可以通过&lt;code&gt;DataFrame&lt;/code&gt;对象的方法&lt;code&gt;mean&lt;/code&gt;、&lt;code&gt;max&lt;/code&gt;、&lt;code&gt;min&lt;/code&gt;、&lt;code&gt;std&lt;/code&gt;、&lt;code&gt;var&lt;/code&gt;等方法分别获取每个学生或每门课程的平均分、最高分、最低分、标准差、方差等信息，也可以直接通过&lt;code&gt;describe&lt;/code&gt;方法直接获取描述性统计信息，代码如下所示。&lt;/p&gt;
&lt;p&gt;计算每门课程成绩的平均分。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;df.mean()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight angelscript&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;语文    &lt;span class=&#34;number&#34;&gt;86.2&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;数学    &lt;span class=&#34;number&#34;&gt;69.4&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;英语    &lt;span class=&#34;number&#34;&gt;78.2&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;dtype: &lt;span class=&#34;built_in&#34;&gt;float&lt;/span&gt;64&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;计算每个学生成绩的平均分。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;df.mean(axis=&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight dns&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;关羽    &lt;span class=&#34;number&#34;&gt;80.333333&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;张飞    &lt;span class=&#34;number&#34;&gt;79.666667&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;赵云    &lt;span class=&#34;number&#34;&gt;68.000000&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;马超    &lt;span class=&#34;number&#34;&gt;69.333333&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;黄忠    &lt;span class=&#34;number&#34;&gt;92.333333&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;dtype: float64&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;计算每门课程成绩的方差。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;df.var()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight angelscript&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;语文    &lt;span class=&#34;number&#34;&gt;161.2&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;数学    &lt;span class=&#34;number&#34;&gt;379.8&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;英语    &lt;span class=&#34;number&#34;&gt;265.7&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;dtype: &lt;span class=&#34;built_in&#34;&gt;float&lt;/span&gt;64&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;说明&lt;/strong&gt;：通过方差可以看出，数学成绩波动最大，最不稳定。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;获取每门课程的描述性统计信息。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;df.describe()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight dns&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;        语文        数学         英语&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;count   &lt;span class=&#34;number&#34;&gt;5.000000&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;5.000000&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;5.000000&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;mean    &lt;span class=&#34;number&#34;&gt;86.200000	69&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;400000	78&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;200000&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;std     &lt;span class=&#34;number&#34;&gt;12.696456&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;19.488458&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;16.300307&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;min     &lt;span class=&#34;number&#34;&gt;72.000000&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;51.000000&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;54.000000&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;25&lt;/span&gt;%     &lt;span class=&#34;number&#34;&gt;74.000000&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;54.000000&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;73.000000&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;50&lt;/span&gt;%     &lt;span class=&#34;number&#34;&gt;89.000000&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;70.000000&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;79.000000&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;75&lt;/span&gt;%     &lt;span class=&#34;number&#34;&gt;96.000000&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;72.000000&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;88.000000&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;max     &lt;span class=&#34;number&#34;&gt;100.000000&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;100.000000&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;97.000000&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h5 id=&#34;排序和Top-N&#34;&gt;&lt;a href=&#34;#排序和Top-N&#34; class=&#34;headerlink&#34; title=&#34;排序和Top-N&#34;&gt;&lt;/a&gt;排序和Top-N&lt;/h5&gt;&lt;p&gt;如果需要对数据进行排序，可以使用&lt;code&gt;DataFrame&lt;/code&gt;对象的&lt;code&gt;sort_values&lt;/code&gt;方法，该方法的&lt;code&gt;by&lt;/code&gt;参数可以指定根据哪个列或哪些列进行排序，而&lt;code&gt;ascending&lt;/code&gt;参数可以指定升序或是降序。例如，下面的代码展示了如何将学生表按语文成绩排降序。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;df.sort_values(by=&lt;span class=&#34;string&#34;&gt;&amp;#x27;语文&amp;#x27;&lt;/span&gt;, ascending=&lt;span class=&#34;literal&#34;&gt;False&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight tap&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;      语文   数学   英语&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;马超	100    54	  54&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;关羽	96    &lt;span class=&#34;number&#34;&gt; 72 &lt;/span&gt;    73&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;黄忠	89    &lt;span class=&#34;number&#34;&gt; 100 &lt;/span&gt;   88&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;赵云	74    &lt;span class=&#34;number&#34;&gt; 51 &lt;/span&gt;    79&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;张飞	72    &lt;span class=&#34;number&#34;&gt; 70 &lt;/span&gt;    97&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;如果&lt;code&gt;DataFrame&lt;/code&gt;数据量很大，排序将是一个非常耗费时间的操作。有的时候我们只需要获得排前N名或后N名的数据，这个时候其实没有必要对整个数据进行排序，而是直接利用堆结构找出Top-N的数据。&lt;code&gt;DataFrame&lt;/code&gt;的&lt;code&gt;nlargest&lt;/code&gt;和&lt;code&gt;nsmallest&lt;/code&gt;方法就提供对Top-N操作的支持，代码如下所示。&lt;/p&gt;
&lt;p&gt;找出语文成绩前3名的学生信息。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;df.nlargest(&lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;语文&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight tap&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;      语文   数学   英语&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;马超	100    54	  54&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;关羽	96    &lt;span class=&#34;number&#34;&gt; 72 &lt;/span&gt;    73&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;黄忠	89    &lt;span class=&#34;number&#34;&gt; 100 &lt;/span&gt;   88&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;找出数学成绩最低的3名学生的信息。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;df.nsmallest(&lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;数学&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight tap&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;      语文  数学  英语&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;赵云 &lt;span class=&#34;number&#34;&gt; 74 &lt;/span&gt;   51	79&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;马超 &lt;span class=&#34;number&#34;&gt; 100 &lt;/span&gt;  54	54&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;张飞 &lt;span class=&#34;number&#34;&gt; 72 &lt;/span&gt;   70	97&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h5 id=&#34;分组聚合操作&#34;&gt;&lt;a href=&#34;#分组聚合操作&#34; class=&#34;headerlink&#34; title=&#34;分组聚合操作&#34;&gt;&lt;/a&gt;分组聚合操作&lt;/h5&gt;&lt;p&gt;我们先从 Excel 文件中读取一组销售数据，然后再为大家演示如何进行分组聚合操作。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;df = pd.read_excel(&lt;span class=&#34;string&#34;&gt;&amp;#x27;2020年销售数据.xlsx&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;df.head()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;说明&lt;/strong&gt;：如果需要上面例子中的 Excel 文件，可以通过百度云盘进行获取。链接：&lt;a href=&#34;https://pan.baidu.com/s/1NhWtYcpFzF72cxcsoDoXjQ?pwd=swg1%EF%BC%8C%E6%8F%90%E5%8F%96%E7%A0%81%EF%BC%9Aswg1%E3%80%82&#34;&gt;https://pan.baidu.com/s/1NhWtYcpFzF72cxcsoDoXjQ?pwd=swg1，提取码：swg1。&lt;/a&gt;&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight subunit&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;    销售日期	 销售区域   销售渠道  销售订单     品牌    售价  销售数量&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;0   2020&lt;span class=&#34;string&#34;&gt;-01&lt;/span&gt;&lt;span class=&#34;string&#34;&gt;-01&lt;/span&gt;  上海       拼多多    182894&lt;span class=&#34;string&#34;&gt;-455&lt;/span&gt;  八匹马  99    83&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;1   2020&lt;span class=&#34;string&#34;&gt;-01&lt;/span&gt;&lt;span class=&#34;string&#34;&gt;-01&lt;/span&gt;  上海       抖音      205635&lt;span class=&#34;string&#34;&gt;-402&lt;/span&gt;  八匹马  219   29&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2   2020&lt;span class=&#34;string&#34;&gt;-01&lt;/span&gt;&lt;span class=&#34;string&#34;&gt;-01&lt;/span&gt;  上海       天猫      205654&lt;span class=&#34;string&#34;&gt;-021&lt;/span&gt;  八匹马  169   85&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3   2020&lt;span class=&#34;string&#34;&gt;-01&lt;/span&gt;&lt;span class=&#34;string&#34;&gt;-01&lt;/span&gt;  上海       天猫      205654&lt;span class=&#34;string&#34;&gt;-519&lt;/span&gt;  八匹马  169   14&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4   2020&lt;span class=&#34;string&#34;&gt;-01&lt;/span&gt;&lt;span class=&#34;string&#34;&gt;-01&lt;/span&gt;  上海       天猫      377781&lt;span class=&#34;string&#34;&gt;-010&lt;/span&gt;  皮皮虾  249   61&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;如果我们要统计每个销售区域的销售总额，可以先通过“售价”和“销售数量”计算出销售额，为&lt;code&gt;DataFrame&lt;/code&gt;添加一个列，代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;df[&lt;span class=&#34;string&#34;&gt;&amp;#x27;销售额&amp;#x27;&lt;/span&gt;] = df[&lt;span class=&#34;string&#34;&gt;&amp;#x27;售价&amp;#x27;&lt;/span&gt;] * df[&lt;span class=&#34;string&#34;&gt;&amp;#x27;销售数量&amp;#x27;&lt;/span&gt;]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;df.head()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight subunit&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;    销售日期	 销售区域   销售渠道  销售订单     品牌    售价  销售数量  销售额&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;0   2020&lt;span class=&#34;string&#34;&gt;-01&lt;/span&gt;&lt;span class=&#34;string&#34;&gt;-01&lt;/span&gt;  上海       拼多多    182894&lt;span class=&#34;string&#34;&gt;-455&lt;/span&gt;  八匹马  99    83        8217&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;1   2020&lt;span class=&#34;string&#34;&gt;-01&lt;/span&gt;&lt;span class=&#34;string&#34;&gt;-01&lt;/span&gt;  上海       抖音      205635&lt;span class=&#34;string&#34;&gt;-402&lt;/span&gt;  八匹马  219   29        6351&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2   2020&lt;span class=&#34;string&#34;&gt;-01&lt;/span&gt;&lt;span class=&#34;string&#34;&gt;-01&lt;/span&gt;  上海       天猫      205654&lt;span class=&#34;string&#34;&gt;-021&lt;/span&gt;  八匹马  169   85        14365&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3   2020&lt;span class=&#34;string&#34;&gt;-01&lt;/span&gt;&lt;span class=&#34;string&#34;&gt;-01&lt;/span&gt;  上海       天猫      205654&lt;span class=&#34;string&#34;&gt;-519&lt;/span&gt;  八匹马  169   14        2366&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4   2020&lt;span class=&#34;string&#34;&gt;-01&lt;/span&gt;&lt;span class=&#34;string&#34;&gt;-01&lt;/span&gt;  上海       天猫      377781&lt;span class=&#34;string&#34;&gt;-010&lt;/span&gt;  皮皮虾  249   61        15189&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;然后再根据“销售区域”列对数据进行分组，这里我们使用的是&lt;code&gt;DataFrame&lt;/code&gt;对象的&lt;code&gt;groupby&lt;/code&gt;方法。分组之后，我们取“销售额”这个列在分组内进行求和处理，代码和结果如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;df.groupby(&lt;span class=&#34;string&#34;&gt;&amp;#x27;销售区域&amp;#x27;&lt;/span&gt;).销售额.&lt;span class=&#34;built_in&#34;&gt;sum&lt;/span&gt;()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight dns&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;销售区域&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;上海    &lt;span class=&#34;number&#34;&gt;11610489&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;北京    &lt;span class=&#34;number&#34;&gt;12477717&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;南京     &lt;span class=&#34;number&#34;&gt;1767301&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;安徽      &lt;span class=&#34;number&#34;&gt;895463&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;广东     &lt;span class=&#34;number&#34;&gt;1617949&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;江苏      &lt;span class=&#34;number&#34;&gt;537079&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;浙江      &lt;span class=&#34;number&#34;&gt;687862&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;福建    &lt;span class=&#34;number&#34;&gt;10178227&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;Name: 销售额, dtype: int64&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;如果我们要统计每个月的销售总额，我们可以将“销售日期”作为groupby&amp;#96;方法的参数，当然这里需要先将“销售日期”处理成月，代码和结果如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;df.groupby(df[&lt;span class=&#34;string&#34;&gt;&amp;#x27;销售日期&amp;#x27;&lt;/span&gt;].dt.month).销售额.&lt;span class=&#34;built_in&#34;&gt;sum&lt;/span&gt;()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight dns&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;销售日期&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;     &lt;span class=&#34;number&#34;&gt;5409855&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;     &lt;span class=&#34;number&#34;&gt;4608455&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;     &lt;span class=&#34;number&#34;&gt;4164972&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;     &lt;span class=&#34;number&#34;&gt;3996770&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;5&lt;/span&gt;     &lt;span class=&#34;number&#34;&gt;3239005&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;6&lt;/span&gt;     &lt;span class=&#34;number&#34;&gt;2817936&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;7&lt;/span&gt;     &lt;span class=&#34;number&#34;&gt;3501304&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;8&lt;/span&gt;     &lt;span class=&#34;number&#34;&gt;2948189&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;9&lt;/span&gt;     &lt;span class=&#34;number&#34;&gt;2632960&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;2375385&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;11&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;2385283&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;12&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;1691973&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;Name: 销售额, dtype: int64&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;接下来我们将难度升级，统计每个销售区域每个月的销售总额，这又该如何处理呢？事实上，&lt;code&gt;groupby&lt;/code&gt;方法的第一个参数可以是一个列表，列表中可以指定多个分组的依据，大家看看下面的代码和输出结果就明白了。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;df.groupby([&lt;span class=&#34;string&#34;&gt;&amp;#x27;销售区域&amp;#x27;&lt;/span&gt;, df[&lt;span class=&#34;string&#34;&gt;&amp;#x27;销售日期&amp;#x27;&lt;/span&gt;].dt.month]).销售额.&lt;span class=&#34;built_in&#34;&gt;sum&lt;/span&gt;()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight tap&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;销售区域  销售日期&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;上海     &lt;span class=&#34;number&#34;&gt; 1 &lt;/span&gt;      1679125&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;         &lt;span class=&#34;number&#34;&gt; 2 &lt;/span&gt;      1689527&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;         &lt;span class=&#34;number&#34;&gt; 3 &lt;/span&gt;      1061193&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;         &lt;span class=&#34;number&#34;&gt; 4 &lt;/span&gt;      1082187&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;         &lt;span class=&#34;number&#34;&gt; 5 &lt;/span&gt;       841199&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;         &lt;span class=&#34;number&#34;&gt; 6 &lt;/span&gt;       785404&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;         &lt;span class=&#34;number&#34;&gt; 7 &lt;/span&gt;       863906&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;         &lt;span class=&#34;number&#34;&gt; 8 &lt;/span&gt;       734937&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;         &lt;span class=&#34;number&#34;&gt; 9 &lt;/span&gt;      1107693&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;number&#34;&gt; 10 &lt;/span&gt;      412108&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;number&#34;&gt; 11 &lt;/span&gt;      825169&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;number&#34;&gt; 12 &lt;/span&gt;      528041&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;北京    &lt;span class=&#34;number&#34;&gt; 1 &lt;/span&gt;      1878234&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;number&#34;&gt; 2 &lt;/span&gt;      1807787&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;number&#34;&gt; 3 &lt;/span&gt;      1360666&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;number&#34;&gt; 4 &lt;/span&gt;      1205989&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;number&#34;&gt; 5 &lt;/span&gt;       807300&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;number&#34;&gt; 6 &lt;/span&gt;      1216432&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;number&#34;&gt; 7 &lt;/span&gt;      1219083&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;number&#34;&gt; 8 &lt;/span&gt;       645727&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;number&#34;&gt; 9 &lt;/span&gt;       390077&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;       &lt;span class=&#34;number&#34;&gt; 10 &lt;/span&gt;      671608&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;       &lt;span class=&#34;number&#34;&gt; 11 &lt;/span&gt;      678668&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;       &lt;span class=&#34;number&#34;&gt; 12 &lt;/span&gt;      596146&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;南京    &lt;span class=&#34;number&#34;&gt; 7 &lt;/span&gt;       841032&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;       &lt;span class=&#34;number&#34;&gt; 10 &lt;/span&gt;      710962&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;       &lt;span class=&#34;number&#34;&gt; 12 &lt;/span&gt;      215307&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;安徽    &lt;span class=&#34;number&#34;&gt; 4 &lt;/span&gt;       341308&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;number&#34;&gt; 5 &lt;/span&gt;       554155&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;广东    &lt;span class=&#34;number&#34;&gt; 3 &lt;/span&gt;       388180&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;number&#34;&gt; 8 &lt;/span&gt;       469390&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;number&#34;&gt; 9 &lt;/span&gt;       365191&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;       &lt;span class=&#34;number&#34;&gt; 11 &lt;/span&gt;      395188&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;江苏    &lt;span class=&#34;number&#34;&gt; 4 &lt;/span&gt;       537079&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;浙江    &lt;span class=&#34;number&#34;&gt; 3 &lt;/span&gt;       248354&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;number&#34;&gt; 8 &lt;/span&gt;       439508&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;福建    &lt;span class=&#34;number&#34;&gt; 1 &lt;/span&gt;      1852496&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;number&#34;&gt; 2 &lt;/span&gt;      1111141&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;number&#34;&gt; 3 &lt;/span&gt;      1106579&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;number&#34;&gt; 4 &lt;/span&gt;       830207&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;number&#34;&gt; 5 &lt;/span&gt;      1036351&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;number&#34;&gt; 6 &lt;/span&gt;       816100&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;number&#34;&gt; 7 &lt;/span&gt;       577283&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;number&#34;&gt; 8 &lt;/span&gt;       658627&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;number&#34;&gt; 9 &lt;/span&gt;       769999&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;       &lt;span class=&#34;number&#34;&gt; 10 &lt;/span&gt;      580707&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;       &lt;span class=&#34;number&#34;&gt; 11 &lt;/span&gt;      486258&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;       &lt;span class=&#34;number&#34;&gt; 12 &lt;/span&gt;      352479&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;Name: 销售额, dtype: int64&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;如果希望统计出每个区域的销售总额以及每个区域单笔金额的最高和最低，我们可以在&lt;code&gt;DataFrame&lt;/code&gt;或&lt;code&gt;Series&lt;/code&gt;对象上使用&lt;code&gt;agg&lt;/code&gt;方法并指定多个聚合函数，代码和结果如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;df.groupby(&lt;span class=&#34;string&#34;&gt;&amp;#x27;销售区域&amp;#x27;&lt;/span&gt;).销售额.agg([&lt;span class=&#34;string&#34;&gt;&amp;#x27;sum&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;max&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;min&amp;#x27;&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight tap&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;          sum        max        min&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;销售区域			&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;上海     &lt;span class=&#34;number&#34;&gt; 11610489 &lt;/span&gt; &lt;span class=&#34;number&#34;&gt; 116303 &lt;/span&gt;    948&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;北京     &lt;span class=&#34;number&#34;&gt; 12477717 &lt;/span&gt; &lt;span class=&#34;number&#34;&gt; 133411 &lt;/span&gt;    690&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;南京     &lt;span class=&#34;number&#34;&gt; 1767301 &lt;/span&gt;  &lt;span class=&#34;number&#34;&gt; 87527 &lt;/span&gt;     1089&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;安徽     &lt;span class=&#34;number&#34;&gt; 895463 &lt;/span&gt;   &lt;span class=&#34;number&#34;&gt; 68502 &lt;/span&gt;     1683&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;广东     &lt;span class=&#34;number&#34;&gt; 1617949 &lt;/span&gt;  &lt;span class=&#34;number&#34;&gt; 120807 &lt;/span&gt;    990&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;江苏     &lt;span class=&#34;number&#34;&gt; 537079 &lt;/span&gt;   &lt;span class=&#34;number&#34;&gt; 114312 &lt;/span&gt;    3383&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;浙江     &lt;span class=&#34;number&#34;&gt; 687862 &lt;/span&gt;   &lt;span class=&#34;number&#34;&gt; 90909 &lt;/span&gt;     3927&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;福建     &lt;span class=&#34;number&#34;&gt; 10178227 &lt;/span&gt; &lt;span class=&#34;number&#34;&gt; 87527 &lt;/span&gt;     897&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;如果希望自定义聚合后的列的名字，可以使用如下所示的方法。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;df.groupby(&lt;span class=&#34;string&#34;&gt;&amp;#x27;销售区域&amp;#x27;&lt;/span&gt;).销售额.agg(销售总额=&lt;span class=&#34;string&#34;&gt;&amp;#x27;sum&amp;#x27;&lt;/span&gt;, 单笔最高=&lt;span class=&#34;string&#34;&gt;&amp;#x27;max&amp;#x27;&lt;/span&gt;, 单笔最低=&lt;span class=&#34;string&#34;&gt;&amp;#x27;min&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight tap&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;          销售总额   单笔最高    单笔最低&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;销售区域			&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;上海     &lt;span class=&#34;number&#34;&gt; 11610489 &lt;/span&gt; &lt;span class=&#34;number&#34;&gt; 116303 &lt;/span&gt;    948&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;北京     &lt;span class=&#34;number&#34;&gt; 12477717 &lt;/span&gt; &lt;span class=&#34;number&#34;&gt; 133411 &lt;/span&gt;    690&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;南京     &lt;span class=&#34;number&#34;&gt; 1767301 &lt;/span&gt;  &lt;span class=&#34;number&#34;&gt; 87527 &lt;/span&gt;     1089&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;安徽     &lt;span class=&#34;number&#34;&gt; 895463 &lt;/span&gt;   &lt;span class=&#34;number&#34;&gt; 68502 &lt;/span&gt;     1683&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;广东     &lt;span class=&#34;number&#34;&gt; 1617949 &lt;/span&gt;  &lt;span class=&#34;number&#34;&gt; 120807 &lt;/span&gt;    990&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;江苏     &lt;span class=&#34;number&#34;&gt; 537079 &lt;/span&gt;   &lt;span class=&#34;number&#34;&gt; 114312 &lt;/span&gt;    3383&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;浙江     &lt;span class=&#34;number&#34;&gt; 687862 &lt;/span&gt;   &lt;span class=&#34;number&#34;&gt; 90909 &lt;/span&gt;     3927&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;福建     &lt;span class=&#34;number&#34;&gt; 10178227 &lt;/span&gt; &lt;span class=&#34;number&#34;&gt; 87527 &lt;/span&gt;     897&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;如果需要对多个列使用不同的聚合函数，例如“统计每个销售区域销售额的平均值以及销售数量的最低值和最高值”，我们可以按照下面的方式来操作。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;df.groupby(&lt;span class=&#34;string&#34;&gt;&amp;#x27;销售区域&amp;#x27;&lt;/span&gt;)[[&lt;span class=&#34;string&#34;&gt;&amp;#x27;销售额&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;销售数量&amp;#x27;&lt;/span&gt;]].agg(&amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;#x27;销售额&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;mean&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;销售数量&amp;#x27;&lt;/span&gt;: [&lt;span class=&#34;string&#34;&gt;&amp;#x27;max&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;min&amp;#x27;&lt;/span&gt;]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight tap&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;         销售额        销售数量&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;         mean          max    min&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;销售区域			&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;上海     20622.538188 &lt;span class=&#34;number&#34;&gt; 100 &lt;/span&gt;   10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;北京     20125.350000 &lt;span class=&#34;number&#34;&gt; 100 &lt;/span&gt;   10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;南京     22370.898734 &lt;span class=&#34;number&#34;&gt; 100 &lt;/span&gt;   11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;安徽     26337.147059 &lt;span class=&#34;number&#34;&gt; 98 &lt;/span&gt;    16&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;广东     32358.980000 &lt;span class=&#34;number&#34;&gt; 98 &lt;/span&gt;    10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;江苏     29837.722222 &lt;span class=&#34;number&#34;&gt; 98 &lt;/span&gt;    15&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;浙江     27514.480000 &lt;span class=&#34;number&#34;&gt; 95 &lt;/span&gt;    20&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;福建     18306.163669 &lt;span class=&#34;number&#34;&gt; 100 &lt;/span&gt;   10&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h5 id=&#34;透视表和交叉表&#34;&gt;&lt;a href=&#34;#透视表和交叉表&#34; class=&#34;headerlink&#34; title=&#34;透视表和交叉表&#34;&gt;&lt;/a&gt;透视表和交叉表&lt;/h5&gt;&lt;p&gt;上面的例子中，“统计每个销售区域每个月的销售总额”会产生一个看起来很长的结果，在实际工作中我们通常把那些行很多列很少的表成为“窄表”，如果我们不想得到这样的一个“窄表”，可以使用&lt;code&gt;DataFrame&lt;/code&gt;的&lt;code&gt;pivot_table&lt;/code&gt;方法或者是&lt;code&gt;pivot_table&lt;/code&gt;函数来生成透视表。透视表的本质就是对数据进行分组聚合操作，&lt;strong&gt;根据 A 列对 B 列进行统计&lt;/strong&gt;，如果大家有使用 Excel 的经验，相信对透视表这个概念一定不会陌生。例如，我们要“统计每个销售区域的销售总额”，那么“销售区域”就是我们的 A 列，而“销售额”就是我们的 B 列，在&lt;code&gt;pivot_table&lt;/code&gt;函数中分别对应&lt;code&gt;index&lt;/code&gt;和&lt;code&gt;values&lt;/code&gt;参数，这两个参数都可以是单个列或者多个列。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;pd.pivot_table(df, index=&lt;span class=&#34;string&#34;&gt;&amp;#x27;销售区域&amp;#x27;&lt;/span&gt;, values=&lt;span class=&#34;string&#34;&gt;&amp;#x27;销售额&amp;#x27;&lt;/span&gt;, aggfunc=&lt;span class=&#34;string&#34;&gt;&amp;#x27;sum&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20211106180912.png&#34; style=&#34;zoom:50%&#34;&gt;

&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;注意&lt;/strong&gt;：上面的结果操作跟之前用&lt;code&gt;groupby&lt;/code&gt;的方式得到的结果有一些区别，&lt;code&gt;groupby&lt;/code&gt;操作后，如果对单个列进行聚合，得到的结果是一个&lt;code&gt;Series&lt;/code&gt;对象，而上面的结果是一个&lt;code&gt;DataFrame&lt;/code&gt; 对象。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;如果要统计每个销售区域每个月的销售总额，也可以使用&lt;code&gt;pivot_table&lt;/code&gt;函数，代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;pd.pivot_table(df, index=[&lt;span class=&#34;string&#34;&gt;&amp;#x27;销售区域&amp;#x27;&lt;/span&gt;, df[&lt;span class=&#34;string&#34;&gt;&amp;#x27;销售日期&amp;#x27;&lt;/span&gt;].dt.month], values=&lt;span class=&#34;string&#34;&gt;&amp;#x27;销售额&amp;#x27;&lt;/span&gt;, aggfunc=&lt;span class=&#34;string&#34;&gt;&amp;#x27;sum&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;上面的操作结果是一个&lt;code&gt;DataFrame&lt;/code&gt;，但也是一个长长的“窄表”，如果希望做成一个行比较少列比较多的“宽表”，可以将&lt;code&gt;index&lt;/code&gt;参数中的列放到&lt;code&gt;columns&lt;/code&gt;参数中，代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;pd.pivot_table(&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    df, index=&lt;span class=&#34;string&#34;&gt;&amp;#x27;销售区域&amp;#x27;&lt;/span&gt;, columns=df[&lt;span class=&#34;string&#34;&gt;&amp;#x27;销售日期&amp;#x27;&lt;/span&gt;].dt.month, &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    values=&lt;span class=&#34;string&#34;&gt;&amp;#x27;销售额&amp;#x27;&lt;/span&gt;, aggfunc=&lt;span class=&#34;string&#34;&gt;&amp;#x27;sum&amp;#x27;&lt;/span&gt;, fill_value=&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;说明&lt;/strong&gt;：&lt;code&gt;pivot_table&lt;/code&gt;函数的&lt;code&gt;fill_value=0&lt;/code&gt;会将空值处理为&lt;code&gt;0&lt;/code&gt;。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;输出：&lt;/p&gt;
&lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20211106104551.png&#34; style=&#34;zoom:50%&#34;&gt;

&lt;p&gt;使用&lt;code&gt;pivot_table&lt;/code&gt;函数时，还可以通过添加&lt;code&gt;margins&lt;/code&gt;和&lt;code&gt;margins_name&lt;/code&gt;参数对分组聚合的结果做一个汇总，具体的操作和效果如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;df[&lt;span class=&#34;string&#34;&gt;&amp;#x27;月份&amp;#x27;&lt;/span&gt;] = df[&lt;span class=&#34;string&#34;&gt;&amp;#x27;销售日期&amp;#x27;&lt;/span&gt;].dt.month&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;pd.pivot_table(&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    df, index=&lt;span class=&#34;string&#34;&gt;&amp;#x27;销售区域&amp;#x27;&lt;/span&gt;, columns=&lt;span class=&#34;string&#34;&gt;&amp;#x27;月份&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    values=&lt;span class=&#34;string&#34;&gt;&amp;#x27;销售额&amp;#x27;&lt;/span&gt;, aggfunc=&lt;span class=&#34;string&#34;&gt;&amp;#x27;sum&amp;#x27;&lt;/span&gt;, fill_value=&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;, &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    margins=&lt;span class=&#34;literal&#34;&gt;True&lt;/span&gt;, margins_name=&lt;span class=&#34;string&#34;&gt;&amp;#x27;总计&amp;#x27;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;p&gt;&lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20211106181707.png&#34; alt=&#34;image-20211106181707655&#34;&gt;&lt;/p&gt;
&lt;p&gt;交叉表就是一种特殊的透视表，它不需要先构造一个&lt;code&gt;DataFrame&lt;/code&gt;对象，而是直接通过数组或&lt;code&gt;Series&lt;/code&gt;对象指定两个或多个因素进行运算得到统计结果。例如，我们要统计每个销售区域的销售总额，也可以按照如下所示的方式来完成，我们先准备三组数据。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;sales_area, sales_month, sales_amount = df[&lt;span class=&#34;string&#34;&gt;&amp;#x27;销售区域&amp;#x27;&lt;/span&gt;], df[&lt;span class=&#34;string&#34;&gt;&amp;#x27;月份&amp;#x27;&lt;/span&gt;], df[&lt;span class=&#34;string&#34;&gt;&amp;#x27;销售额&amp;#x27;&lt;/span&gt;]&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;使用&lt;code&gt;crosstab&lt;/code&gt;函数生成交叉表。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;pd.crosstab(&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    index=sales_area, columns=sales_month, values=sales_amount, aggfunc=&lt;span class=&#34;string&#34;&gt;&amp;#x27;sum&amp;#x27;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;).fillna(&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;).applymap(&lt;span class=&#34;built_in&#34;&gt;int&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;说明&lt;/strong&gt;：上面的代码使用了&lt;code&gt;DataFrame&lt;/code&gt;对象的&lt;code&gt;fillna&lt;/code&gt;方法将空值处理为0，再使用&lt;code&gt;applymap&lt;/code&gt;方法将数据类型处理成整数。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h4 id=&#34;数据可视化&#34;&gt;&lt;a href=&#34;#数据可视化&#34; class=&#34;headerlink&#34; title=&#34;数据可视化&#34;&gt;&lt;/a&gt;数据可视化&lt;/h4&gt;&lt;p&gt;一图胜千言，我们对数据进行透视的结果，最终要通过图表的方式呈现出来，因为图表具有极强的表现力，能够让我们迅速的解读数据中隐藏的价值。和&lt;code&gt;Series&lt;/code&gt;一样，&lt;code&gt;DataFrame&lt;/code&gt;对象提供了&lt;code&gt;plot&lt;/code&gt;方法来支持绘图，底层仍然是通过&lt;code&gt;matplotlib&lt;/code&gt;库实现图表的渲染。关于&lt;code&gt;matplotlib&lt;/code&gt;的内容，我们在下一个章节进行详细的探讨，这里我们只简单的讲解&lt;code&gt;plot&lt;/code&gt;方法的用法。 &lt;/p&gt;
&lt;p&gt;例如，我们想通过一张柱状图来比较“每个销售区域的销售总额”，可以直接在透视表上使用&lt;code&gt;plot&lt;/code&gt;方法生成柱状图。我们先导入&lt;code&gt;matplotlib.pyplot&lt;/code&gt;模块，通过修改绘图的参数使其支持中文显示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; matplotlib.pyplot &lt;span class=&#34;keyword&#34;&gt;as&lt;/span&gt; plt&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.rcParams[&lt;span class=&#34;string&#34;&gt;&amp;#x27;font.sans-serif&amp;#x27;&lt;/span&gt;] = &lt;span class=&#34;string&#34;&gt;&amp;#x27;FZJKai-Z03S&amp;#x27;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;说明&lt;/strong&gt;：上面的&lt;code&gt;FZJKai-Z03S&lt;/code&gt;是我电脑上已经安装的一种支持中文的字体的名称，字体的名称可以通过查看用户主目录下&lt;code&gt;.matplotlib&lt;/code&gt;文件夹下名为&lt;code&gt;fontlist-v330.json&lt;/code&gt;的文件来获得，而这个文件在执行上面的命令后就会生成。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;使用魔法指令配置生成矢量图。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;%config InlineBackend.figure_format = &lt;span class=&#34;string&#34;&gt;&amp;#x27;svg&amp;#x27;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;绘制“每个销售区域销售总额”的柱状图。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;temp = pd.pivot_table(df, index=&lt;span class=&#34;string&#34;&gt;&amp;#x27;销售区域&amp;#x27;&lt;/span&gt;, values=&lt;span class=&#34;string&#34;&gt;&amp;#x27;销售额&amp;#x27;&lt;/span&gt;, aggfunc=&lt;span class=&#34;string&#34;&gt;&amp;#x27;sum&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;temp.plot(figsize=(&lt;span class=&#34;number&#34;&gt;8&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;), kind=&lt;span class=&#34;string&#34;&gt;&amp;#x27;bar&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.xticks(rotation=&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.show()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;说明&lt;/strong&gt;：上面的第3行代码会将横轴刻度上的文字旋转到0度，第4行代码会显示图像。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;输出：&lt;/p&gt;
&lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20211106195040.png&#34; style=&#34;zoom:50%&#34;&gt;

&lt;p&gt;如果要绘制饼图，可以修改&lt;code&gt;plot&lt;/code&gt;方法的&lt;code&gt;kind&lt;/code&gt;参数为&lt;code&gt;pie&lt;/code&gt;，然后使用定制饼图的参数对图表加以定制，代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;temp.sort_values(by=&lt;span class=&#34;string&#34;&gt;&amp;#x27;销售额&amp;#x27;&lt;/span&gt;, ascending=&lt;span class=&#34;literal&#34;&gt;False&lt;/span&gt;).plot(&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    figsize=(&lt;span class=&#34;number&#34;&gt;6&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;6&lt;/span&gt;), kind=&lt;span class=&#34;string&#34;&gt;&amp;#x27;pie&amp;#x27;&lt;/span&gt;, y=&lt;span class=&#34;string&#34;&gt;&amp;#x27;销售额&amp;#x27;&lt;/span&gt;, &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    autopct=&lt;span class=&#34;string&#34;&gt;&amp;#x27;%.2f%%&amp;#x27;&lt;/span&gt;, pctdistance=&lt;span class=&#34;number&#34;&gt;0.8&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    wedgeprops=&lt;span class=&#34;built_in&#34;&gt;dict&lt;/span&gt;(linewidth=&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, width=&lt;span class=&#34;number&#34;&gt;0.35&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.legend(loc=&lt;span class=&#34;string&#34;&gt;&amp;#x27;center&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.show()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20211106201550.png&#34; style=&#34;zoom:50%&#34;&gt;

 &lt;h2 id=&#34;Pandas的应用-3&#34;&gt;&lt;a href=&#34;#Pandas的应用-3&#34; class=&#34;headerlink&#34; title=&#34;Pandas的应用-3&#34;&gt;&lt;/a&gt;Pandas的应用-3&lt;/h2&gt;&lt;h3 id=&#34;DataFrame的应用&#34;&gt;&lt;a href=&#34;#DataFrame的应用&#34; class=&#34;headerlink&#34; title=&#34;DataFrame的应用&#34;&gt;&lt;/a&gt;DataFrame的应用&lt;/h3&gt;&lt;h4 id=&#34;数据清洗&#34;&gt;&lt;a href=&#34;#数据清洗&#34; class=&#34;headerlink&#34; title=&#34;数据清洗&#34;&gt;&lt;/a&gt;数据清洗&lt;/h4&gt;&lt;p&gt;通常，我们从 Excel、CSV 或数据库中获取到的数据并不是非常完美的，里面可能因为系统或人为的原因混入了重复值或异常值，也可能在某些字段上存在缺失值；再者，&lt;code&gt;DataFrame&lt;/code&gt;中的数据也可能存在格式不统一、量纲不统一等各种问题。因此，在开始数据分析之前，对数据进行清洗就显得特别重要。&lt;/p&gt;
&lt;h5 id=&#34;缺失值&#34;&gt;&lt;a href=&#34;#缺失值&#34; class=&#34;headerlink&#34; title=&#34;缺失值&#34;&gt;&lt;/a&gt;缺失值&lt;/h5&gt;&lt;p&gt;可以使用&lt;code&gt;DataFrame&lt;/code&gt;对象的&lt;code&gt;isnull&lt;/code&gt;或&lt;code&gt;isna&lt;/code&gt;方法来找出数据表中的缺失值，如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;emp_df.isnull()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;或者&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;emp_df.isna()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight mathematica&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;variable&#34;&gt;ename&lt;/span&gt;   &lt;span class=&#34;variable&#34;&gt;job&lt;/span&gt;	    &lt;span class=&#34;variable&#34;&gt;mgr&lt;/span&gt;     &lt;span class=&#34;variable&#34;&gt;sal&lt;/span&gt;     &lt;span class=&#34;variable&#34;&gt;comm&lt;/span&gt;    &lt;span class=&#34;variable&#34;&gt;dno&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;variable&#34;&gt;eno&lt;/span&gt;						&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;1359&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;2056&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;3088&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;3211&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;True&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;3233&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;True&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;3244&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;True&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;3251&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;True&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;3344&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;3577&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;True&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;3588&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;True&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;4466&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;True&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;5234&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;True&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;5566&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;7800&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;True&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;	&lt;span class=&#34;built_in&#34;&gt;False&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;相对应的，&lt;code&gt;notnull&lt;/code&gt;和&lt;code&gt;notna&lt;/code&gt;方法可以将非空的值标记为&lt;code&gt;True&lt;/code&gt;。如果想删除这些缺失值，可以使用&lt;code&gt;DataFrame&lt;/code&gt;对象的&lt;code&gt;dropna&lt;/code&gt;方法，该方法的&lt;code&gt;axis&lt;/code&gt;参数可以指定沿着0轴还是1轴删除，也就是说当遇到空值时，是删除整行还是删除整列，默认是沿0轴进行删除的，代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;emp_df.dropna()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight apache&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;attribute&#34;&gt;ename&lt;/span&gt;   job      mgr	 sal    comm     dno&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;eno&lt;/span&gt;						&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;1359&lt;/span&gt;	胡一刀  销售员	&lt;span class=&#34;number&#34;&gt;3344&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;1800&lt;/span&gt;   &lt;span class=&#34;number&#34;&gt;200&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;30&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;2056&lt;/span&gt;	乔峰    架构师	 &lt;span class=&#34;number&#34;&gt;7800&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;5000&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;1500&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3088&lt;/span&gt;	李莫愁  设计师	&lt;span class=&#34;number&#34;&gt;2056&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;3500&lt;/span&gt;   &lt;span class=&#34;number&#34;&gt;800&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3344&lt;/span&gt;	黄蓉    销售主管	&lt;span class=&#34;number&#34;&gt;7800&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;3000&lt;/span&gt;   &lt;span class=&#34;number&#34;&gt;800&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;30&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;5566&lt;/span&gt;	宋远桥  会计师	&lt;span class=&#34;number&#34;&gt;7800&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;4000&lt;/span&gt;   &lt;span class=&#34;number&#34;&gt;1000&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;如果要沿着1轴进行删除，可以使用下面的代码。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;emp_df.dropna(axis=&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight apache&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;attribute&#34;&gt;ename&lt;/span&gt;    job      sal    dno&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;eno&lt;/span&gt;				&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;1359&lt;/span&gt;	胡一刀   销售员    &lt;span class=&#34;number&#34;&gt;1800&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;30&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;2056&lt;/span&gt;	乔峰     架构师	  &lt;span class=&#34;number&#34;&gt;5000&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3088&lt;/span&gt;	李莫愁   设计师    &lt;span class=&#34;number&#34;&gt;3500&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3211&lt;/span&gt;	张无忌   程序员    &lt;span class=&#34;number&#34;&gt;3200&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3233&lt;/span&gt;	丘处机   程序员    &lt;span class=&#34;number&#34;&gt;3400&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3244&lt;/span&gt;	欧阳锋   程序员    &lt;span class=&#34;number&#34;&gt;3200&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3251&lt;/span&gt;	张翠山   程序员    &lt;span class=&#34;number&#34;&gt;4000&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3344&lt;/span&gt;	黄蓉     销售主管  &lt;span class=&#34;number&#34;&gt;3000&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;30&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3577&lt;/span&gt;	杨过     会计	   &lt;span class=&#34;number&#34;&gt;2200&lt;/span&gt;	  &lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3588&lt;/span&gt;	朱九真   会计	  &lt;span class=&#34;number&#34;&gt;2500&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;4466&lt;/span&gt;	苗人凤   销售员	 &lt;span class=&#34;number&#34;&gt;2500&lt;/span&gt;   &lt;span class=&#34;number&#34;&gt;30&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;5234&lt;/span&gt;	郭靖     出纳      &lt;span class=&#34;number&#34;&gt;2000&lt;/span&gt;   &lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;5566&lt;/span&gt;	宋远桥   会计师    &lt;span class=&#34;number&#34;&gt;4000&lt;/span&gt;   &lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;7800&lt;/span&gt;	张三丰   总裁      &lt;span class=&#34;number&#34;&gt;9000&lt;/span&gt;   &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;注意&lt;/strong&gt;：&lt;code&gt;DataFrame&lt;/code&gt;对象的很多方法都有一个名为&lt;code&gt;inplace&lt;/code&gt;的参数，该参数的默认值为&lt;code&gt;False&lt;/code&gt;，表示我们的操作不会修改原来的&lt;code&gt;DataFrame&lt;/code&gt;对象，而是将处理后的结果通过一个新的&lt;code&gt;DataFrame&lt;/code&gt;对象返回。如果将该参数的值设置为&lt;code&gt;True&lt;/code&gt;，那么我们的操作就会在原来的&lt;code&gt;DataFrame&lt;/code&gt;上面直接修改，方法的返回值为&lt;code&gt;None&lt;/code&gt;。简单的说，上面的操作并没有修改&lt;code&gt;emp_df&lt;/code&gt;，而是返回了一个新的&lt;code&gt;DataFrame&lt;/code&gt;对象。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;在某些特定的场景下，我们可以对空值进行填充，对应的方法是&lt;code&gt;fillna&lt;/code&gt;，填充空值时可以使用指定的值（通过&lt;code&gt;value&lt;/code&gt;参数进行指定），也可以用表格中前一个单元格（通过设置参数&lt;code&gt;method=ffill&lt;/code&gt;）或后一个单元格（通过设置参数&lt;code&gt;method=bfill&lt;/code&gt;）的值进行填充，当代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;emp_df.fillna(value=&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;注意&lt;/strong&gt;：填充的值如何选择也是一个值得探讨的话题，实际工作中，可能会使用某种统计量（如：均值、众数等）进行填充，或者使用某种插值法（如：随机插值法、拉格朗日插值法等）进行填充，甚至有可能通过回归模型、贝叶斯模型等对缺失数据进行填充。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight apache&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;attribute&#34;&gt;ename&lt;/span&gt;    job        mgr      sal     comm    dno&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;eno&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;1359&lt;/span&gt;	胡一刀    销售员	   &lt;span class=&#34;number&#34;&gt;3344&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;1800&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;200&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;30&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;2056&lt;/span&gt;	乔峰	    分析师	    &lt;span class=&#34;number&#34;&gt;7800&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;5000&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;1500&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3088&lt;/span&gt;	李莫愁	   设计师	   &lt;span class=&#34;number&#34;&gt;2056&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;3500&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;800&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3211&lt;/span&gt;	张无忌	   程序员	   &lt;span class=&#34;number&#34;&gt;2056&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;3200&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;     &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3233&lt;/span&gt;	丘处机	   程序员	   &lt;span class=&#34;number&#34;&gt;2056&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;3400&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	    &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3244&lt;/span&gt;	欧阳锋	   程序员	   &lt;span class=&#34;number&#34;&gt;3088&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;3200&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;     &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3251&lt;/span&gt;	张翠山	   程序员	   &lt;span class=&#34;number&#34;&gt;2056&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;4000&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	    &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3344&lt;/span&gt;	黄蓉	    销售主管   &lt;span class=&#34;number&#34;&gt;7800&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;3000&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;800&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;30&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3577&lt;/span&gt;	杨过	    会计	     &lt;span class=&#34;number&#34;&gt;5566&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	  &lt;span class=&#34;number&#34;&gt;2200&lt;/span&gt;	  &lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	  &lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3588&lt;/span&gt;	朱九真	   会计	    &lt;span class=&#34;number&#34;&gt;5566&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;2500&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;4466&lt;/span&gt;	苗人凤	   销售员	   &lt;span class=&#34;number&#34;&gt;3344&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;2500&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	    &lt;span class=&#34;number&#34;&gt;30&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;5234&lt;/span&gt;	郭靖	    出纳	     &lt;span class=&#34;number&#34;&gt;5566&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	  &lt;span class=&#34;number&#34;&gt;2000&lt;/span&gt;	  &lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	  &lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;5566&lt;/span&gt;	宋远桥	   会计师	   &lt;span class=&#34;number&#34;&gt;7800&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;4000&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;1000&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;7800&lt;/span&gt;	张三丰	   总裁	    &lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;      &lt;span class=&#34;number&#34;&gt;9000&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;1200&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h5 id=&#34;重复值&#34;&gt;&lt;a href=&#34;#重复值&#34; class=&#34;headerlink&#34; title=&#34;重复值&#34;&gt;&lt;/a&gt;重复值&lt;/h5&gt;&lt;p&gt;接下来，我们先给之前的部门表添加两行数据，让部门表中名为“研发部”和“销售部”的部门各有两个。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;dept_df.loc[&lt;span class=&#34;number&#34;&gt;50&lt;/span&gt;] = &amp;#123;&lt;span class=&#34;string&#34;&gt;&amp;#x27;dname&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;研发部&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;dloc&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;上海&amp;#x27;&lt;/span&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;dept_df.loc[&lt;span class=&#34;number&#34;&gt;60&lt;/span&gt;] = &amp;#123;&lt;span class=&#34;string&#34;&gt;&amp;#x27;dname&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;销售部&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;dloc&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;长沙&amp;#x27;&lt;/span&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;dept_df&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出:&lt;/p&gt;
&lt;figure class=&#34;highlight nginx&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attribute&#34;&gt;dname&lt;/span&gt;  dloc&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;dno		&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;	会计部	北京&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;	研发部	成都&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;30&lt;/span&gt;	销售部	重庆&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;40&lt;/span&gt;	运维部	天津&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;50&lt;/span&gt;	研发部	上海&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;60&lt;/span&gt;	销售部	长沙&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;现在，我们的数据表中有重复数据了，我们可以通过&lt;code&gt;DataFrame&lt;/code&gt;对象的&lt;code&gt;duplicated&lt;/code&gt;方法判断是否存在重复值，该方法在不指定参数时默认判断行索引是否重复，我们也可以指定根据部门名称&lt;code&gt;dname&lt;/code&gt;判断部门是否重复，代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;dept_df.duplicated(&lt;span class=&#34;string&#34;&gt;&amp;#x27;dname&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight pgsql&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;dno&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;    &lt;span class=&#34;keyword&#34;&gt;False&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;    &lt;span class=&#34;keyword&#34;&gt;False&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;30&lt;/span&gt;    &lt;span class=&#34;keyword&#34;&gt;False&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;40&lt;/span&gt;    &lt;span class=&#34;keyword&#34;&gt;False&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;50&lt;/span&gt;     &lt;span class=&#34;keyword&#34;&gt;True&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;60&lt;/span&gt;     &lt;span class=&#34;keyword&#34;&gt;True&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;dtype: &lt;span class=&#34;type&#34;&gt;bool&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;从上面的输出可以看到，&lt;code&gt;50&lt;/code&gt;和&lt;code&gt;60&lt;/code&gt;两个部门从部门名称上来看是重复的，如果要删除重复值，可以使用&lt;code&gt;drop_duplicates&lt;/code&gt;方法，该方法的&lt;code&gt;keep&lt;/code&gt;参数可以控制在遇到重复值时，保留第一项还是保留最后一项，或者多个重复项一个都不用保留，全部删除掉。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;dept_df.drop_duplicates(&lt;span class=&#34;string&#34;&gt;&amp;#x27;dname&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight nginx&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;	&lt;span class=&#34;attribute&#34;&gt;dname&lt;/span&gt;	dloc&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;dno		&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;	会计部	北京&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;	研发部	成都&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;30&lt;/span&gt;	销售部	重庆&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;40&lt;/span&gt;	运维部	天津&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;将&lt;code&gt;keep&lt;/code&gt;参数的值修改为&lt;code&gt;last&lt;/code&gt;。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;dept_df.drop_duplicates(&lt;span class=&#34;string&#34;&gt;&amp;#x27;dname&amp;#x27;&lt;/span&gt;, keep=&lt;span class=&#34;string&#34;&gt;&amp;#x27;last&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight nginx&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;	&lt;span class=&#34;attribute&#34;&gt;dname&lt;/span&gt;	dloc&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;dno		&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;	会计部	北京&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;40&lt;/span&gt;	运维部	天津&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;50&lt;/span&gt;	研发部	上海&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;60&lt;/span&gt;	销售部	长沙&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h5 id=&#34;异常值&#34;&gt;&lt;a href=&#34;#异常值&#34; class=&#34;headerlink&#34; title=&#34;异常值&#34;&gt;&lt;/a&gt;异常值&lt;/h5&gt;&lt;p&gt;异常值在统计学上的全称是疑似异常值，也称作离群点（outlier），异常值的分析也称作离群点分析。异常值是指样本中出现的“极端值”，数据值看起来异常大或异常小，其分布明显偏离其余的观测值。实际工作中，有些异常值可能是由系统或人为原因造成的，但有些异常值却不是，它们能够重复且稳定的出现，属于正常的极端值，例如很多游戏产品中头部玩家的数据往往都是离群的极端值。所以，我们既不能忽视异常值的存在，也不能简单地把异常值从数据分析中剔除。重视异常值的出现，分析其产生的原因，常常成为发现问题进而改进决策的契机。&lt;/p&gt;
&lt;p&gt;异常值的检测有Z-score 方法、IQR 方法、DBScan 聚类、孤立森林等，这里我们对前两种方法做一个简单的介绍。&lt;/p&gt;
&lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20211004192858.png&#34; style=&#34;zoom:50%;&#34;&gt;

&lt;p&gt;如果数据服从正态分布，依据3σ法则，异常值被定义与平均值的偏差超过三倍标准差的值。在正态分布下，距离平均值3σ之外的值出现的概率为$ P(|x-\mu|&amp;gt;3\sigma)&amp;lt;0.003 $，属于小概率事件。如果数据不服从正态分布，那么可以用远离平均值的多少倍的标准差来描述，这里的倍数就是Z-score。Z-score以标准差为单位去度量某一原始分数偏离平均值的距离，公式如下所示。&lt;br&gt;$$&lt;br&gt;z &amp;#x3D; \frac {X - \mu} {\sigma}&lt;br&gt;$$&lt;br&gt;Z-score需要根据经验和实际情况来决定，通常把远离标准差&lt;code&gt;3&lt;/code&gt;倍距离以上的数据点视为离群点，下面的代给出了如何通过Z-score方法检测异常值。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; numpy &lt;span class=&#34;keyword&#34;&gt;as&lt;/span&gt; np&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;detect_outliers_zscore&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;data, threshold=&lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    avg_value = np.mean(data)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    std_value = np.std(data)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    z_score = np.&lt;span class=&#34;built_in&#34;&gt;abs&lt;/span&gt;((data - avg_value) / std_value)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; data[z_score &amp;gt; threshold]&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;IQR 方法中的IQR（Inter-Quartile Range）代表四分位距离，即上四分位数（Q3）和下四分位数（Q1）的差值。通常情况下，可以认为小于 $ Q1 - 1.5 \times IQR $ 或大于 $ Q3 + 1.5 \times IQR $ 的就是异常值，而这种检测异常值的方法也是箱线图（后面会讲到）默认使用的方法。下面的代给出了如何通过 IQR 方法检测异常值。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; numpy &lt;span class=&#34;keyword&#34;&gt;as&lt;/span&gt; np&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;detect_outliers_iqr&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;data, whis=&lt;span class=&#34;number&#34;&gt;1.5&lt;/span&gt;&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    q1, q3 = np.quantile(data, [&lt;span class=&#34;number&#34;&gt;0.25&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0.75&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    iqr = q3 - q1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    lower, upper = q1 - whis * iqr, q3 + whis * iqr&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; data[(data &amp;lt; lower) | (data &amp;gt; upper)]&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;如果要删除异常值，可以使用&lt;code&gt;DataFrame&lt;/code&gt;对象的&lt;code&gt;drop&lt;/code&gt;方法，该方法可以根据行索引或列索引删除指定的行或列。例如我们认为月薪低于&lt;code&gt;2000&lt;/code&gt;或高于&lt;code&gt;8000&lt;/code&gt;的是员工表中的异常值，可以用下面的代码删除对应的记录。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;emp_df.drop(emp_df[(emp_df.sal &amp;gt; &lt;span class=&#34;number&#34;&gt;8000&lt;/span&gt;) | (emp_df.sal &amp;lt; &lt;span class=&#34;number&#34;&gt;2000&lt;/span&gt;)].index)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;如果要替换掉异常值，可以通过给单元格赋值的方式来实现，也可以使用&lt;code&gt;replace&lt;/code&gt;方法将指定的值替换掉。例如我们要将月薪为&lt;code&gt;1800&lt;/code&gt;和&lt;code&gt;9000&lt;/code&gt;的替换为月薪的平均值，补贴为&lt;code&gt;800&lt;/code&gt;的替换为&lt;code&gt;1000&lt;/code&gt;，代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;avg_sal = np.mean(emp_df.sal).astype(&lt;span class=&#34;built_in&#34;&gt;int&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;emp_df.replace(&amp;#123;&lt;span class=&#34;string&#34;&gt;&amp;#x27;sal&amp;#x27;&lt;/span&gt;: [&lt;span class=&#34;number&#34;&gt;1800&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;9000&lt;/span&gt;], &lt;span class=&#34;string&#34;&gt;&amp;#x27;comm&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;number&#34;&gt;800&lt;/span&gt;&amp;#125;, &amp;#123;&lt;span class=&#34;string&#34;&gt;&amp;#x27;sal&amp;#x27;&lt;/span&gt;: avg_sal, &lt;span class=&#34;string&#34;&gt;&amp;#x27;comm&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;number&#34;&gt;1000&lt;/span&gt;&amp;#125;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h5 id=&#34;预处理&#34;&gt;&lt;a href=&#34;#预处理&#34; class=&#34;headerlink&#34; title=&#34;预处理&#34;&gt;&lt;/a&gt;预处理&lt;/h5&gt;&lt;p&gt;对数据进行预处理也是一个很大的话题，它包含了对数据的拆解、变换、归约、离散化等操作。我们先来看看数据的拆解。如果数据表中的数据是一个时间日期，我们通常都需要从年、季度、月、日、星期、小时、分钟等维度对其进行拆解，如果时间日期是用字符串表示的，可以先通过&lt;code&gt;pandas&lt;/code&gt;的&lt;code&gt;to_datetime&lt;/code&gt;函数将其处理成时间日期。&lt;/p&gt;
&lt;p&gt;在下面的例子中，我们先读取 Excel 文件，获取到一组销售数据，其中第一列就是销售日期，我们将其拆解为“月份”、“季度”和“星期”，代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;sales_df = pd.read_excel(&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;#x27;2020年销售数据.xlsx&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    usecols=[&lt;span class=&#34;string&#34;&gt;&amp;#x27;销售日期&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;销售区域&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;销售渠道&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;品牌&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;销售额&amp;#x27;&lt;/span&gt;]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;sales_df.info()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;说明&lt;/strong&gt;：如果需要上面例子中的 Excel 文件，可以通过下面的百度云盘地址进行获取，数据在《从零开始学数据分析》目录中。链接：&lt;a href=&#34;https://pan.baidu.com/s/1rQujl5RQn9R7PadB2Z5g_g%EF%BC%8C%E6%8F%90%E5%8F%96%E7%A0%81%EF%BC%9Ae7b4%E3%80%82&#34;&gt;https://pan.baidu.com/s/1rQujl5RQn9R7PadB2Z5g_g，提取码：e7b4。&lt;/a&gt;&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight pgsql&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&amp;lt;&lt;span class=&#34;keyword&#34;&gt;class&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;#x27;pandas.core.frame.DataFrame&amp;#x27;&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;Range&lt;span class=&#34;keyword&#34;&gt;Index&lt;/span&gt;: &lt;span class=&#34;number&#34;&gt;1945&lt;/span&gt; entries, &lt;span class=&#34;number&#34;&gt;0&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;to&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;1944&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;Data &lt;span class=&#34;keyword&#34;&gt;columns&lt;/span&gt; (total &lt;span class=&#34;number&#34;&gt;5&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;columns&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt; #   &lt;span class=&#34;keyword&#34;&gt;Column&lt;/span&gt;  Non-&lt;span class=&#34;keyword&#34;&gt;Null&lt;/span&gt; Count  Dtype         &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;---  ------  --------------  -----         &lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt; &lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;   销售日期    &lt;span class=&#34;number&#34;&gt;1945&lt;/span&gt; non-&lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt;   datetime64[ns]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt; &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;   销售区域    &lt;span class=&#34;number&#34;&gt;1945&lt;/span&gt; non-&lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt;   &lt;span class=&#34;keyword&#34;&gt;object&lt;/span&gt;        &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt; &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;   销售渠道    &lt;span class=&#34;number&#34;&gt;1945&lt;/span&gt; non-&lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt;   &lt;span class=&#34;keyword&#34;&gt;object&lt;/span&gt;        &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt; &lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;   品牌        &lt;span class=&#34;number&#34;&gt;1945&lt;/span&gt; non-&lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt;   &lt;span class=&#34;keyword&#34;&gt;object&lt;/span&gt;        &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt; &lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;   销售额      &lt;span class=&#34;number&#34;&gt;1945&lt;/span&gt; non-&lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt;   int64         &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;dtypes: datetime64[ns](&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;), int64(&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;), &lt;span class=&#34;keyword&#34;&gt;object&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;memory &lt;span class=&#34;keyword&#34;&gt;usage&lt;/span&gt;: &lt;span class=&#34;number&#34;&gt;76.1&lt;/span&gt;+ KB&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;sales_df[&lt;span class=&#34;string&#34;&gt;&amp;#x27;月份&amp;#x27;&lt;/span&gt;] = sales_df[&lt;span class=&#34;string&#34;&gt;&amp;#x27;销售日期&amp;#x27;&lt;/span&gt;].dt.month&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;sales_df[&lt;span class=&#34;string&#34;&gt;&amp;#x27;季度&amp;#x27;&lt;/span&gt;] = sales_df[&lt;span class=&#34;string&#34;&gt;&amp;#x27;销售日期&amp;#x27;&lt;/span&gt;].dt.quarter&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;sales_df[&lt;span class=&#34;string&#34;&gt;&amp;#x27;星期&amp;#x27;&lt;/span&gt;] = sales_df[&lt;span class=&#34;string&#34;&gt;&amp;#x27;销售日期&amp;#x27;&lt;/span&gt;].dt.weekday&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;sales_df&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight yaml&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;	    &lt;span class=&#34;string&#34;&gt;销售日期&lt;/span&gt;	 &lt;span class=&#34;string&#34;&gt;销售区域&lt;/span&gt;	&lt;span class=&#34;string&#34;&gt;销售渠道&lt;/span&gt;	&lt;span class=&#34;string&#34;&gt;品牌&lt;/span&gt;	  &lt;span class=&#34;string&#34;&gt;销售额&lt;/span&gt;	&lt;span class=&#34;string&#34;&gt;月份&lt;/span&gt;	&lt;span class=&#34;string&#34;&gt;季度&lt;/span&gt;	&lt;span class=&#34;string&#34;&gt;星期&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	    &lt;span class=&#34;number&#34;&gt;2020-01-01&lt;/span&gt;	&lt;span class=&#34;string&#34;&gt;上海&lt;/span&gt;	     &lt;span class=&#34;string&#34;&gt;拼多多&lt;/span&gt;	 &lt;span class=&#34;string&#34;&gt;八匹马&lt;/span&gt;   &lt;span class=&#34;number&#34;&gt;8217	    &lt;/span&gt;&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;	   &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;	    &lt;span class=&#34;number&#34;&gt;2020-01-01&lt;/span&gt;	&lt;span class=&#34;string&#34;&gt;上海&lt;/span&gt;	     &lt;span class=&#34;string&#34;&gt;抖音&lt;/span&gt;	      &lt;span class=&#34;string&#34;&gt;八匹马&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;6351	 &lt;/span&gt;&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;	  &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;	    &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;	    &lt;span class=&#34;number&#34;&gt;2020-01-01&lt;/span&gt;	&lt;span class=&#34;string&#34;&gt;上海&lt;/span&gt;	     &lt;span class=&#34;string&#34;&gt;天猫&lt;/span&gt;	      &lt;span class=&#34;string&#34;&gt;八匹马&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;14365&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;	  &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;	    &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;	    &lt;span class=&#34;number&#34;&gt;2020-01-01&lt;/span&gt;	&lt;span class=&#34;string&#34;&gt;上海&lt;/span&gt;	     &lt;span class=&#34;string&#34;&gt;天猫&lt;/span&gt;       &lt;span class=&#34;string&#34;&gt;八匹马&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;2366	 &lt;/span&gt;&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;	  &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;     &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;	    &lt;span class=&#34;number&#34;&gt;2020-01-01&lt;/span&gt;	&lt;span class=&#34;string&#34;&gt;上海&lt;/span&gt;	     &lt;span class=&#34;string&#34;&gt;天猫&lt;/span&gt; 	  &lt;span class=&#34;string&#34;&gt;皮皮虾&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;15189&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;	  &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;     &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;...&lt;/span&gt;     &lt;span class=&#34;string&#34;&gt;...&lt;/span&gt;         &lt;span class=&#34;string&#34;&gt;...&lt;/span&gt;        &lt;span class=&#34;string&#34;&gt;...&lt;/span&gt;       &lt;span class=&#34;string&#34;&gt;...&lt;/span&gt;      &lt;span class=&#34;string&#34;&gt;...&lt;/span&gt;     &lt;span class=&#34;string&#34;&gt;...&lt;/span&gt;  &lt;span class=&#34;string&#34;&gt;...&lt;/span&gt;   &lt;span class=&#34;string&#34;&gt;...&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;1940    &lt;/span&gt;&lt;span class=&#34;number&#34;&gt;2020-12-30&lt;/span&gt;	&lt;span class=&#34;string&#34;&gt;北京&lt;/span&gt;	     &lt;span class=&#34;string&#34;&gt;京东&lt;/span&gt;	      &lt;span class=&#34;string&#34;&gt;花花姑娘&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;6994     &lt;/span&gt;&lt;span class=&#34;number&#34;&gt;12&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;	   &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;1941    &lt;/span&gt;&lt;span class=&#34;number&#34;&gt;2020-12-30&lt;/span&gt;	&lt;span class=&#34;string&#34;&gt;福建&lt;/span&gt;	     &lt;span class=&#34;string&#34;&gt;实体&lt;/span&gt;	      &lt;span class=&#34;string&#34;&gt;八匹马&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;7663	 &lt;/span&gt;&lt;span class=&#34;number&#34;&gt;12&lt;/span&gt;	  &lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;	    &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;1942    &lt;/span&gt;&lt;span class=&#34;number&#34;&gt;2020-12-31&lt;/span&gt;	&lt;span class=&#34;string&#34;&gt;福建&lt;/span&gt;	     &lt;span class=&#34;string&#34;&gt;实体&lt;/span&gt;	      &lt;span class=&#34;string&#34;&gt;花花姑娘&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;14795&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;12&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;	   &lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;1943    &lt;/span&gt;&lt;span class=&#34;number&#34;&gt;2020-12-31&lt;/span&gt;	&lt;span class=&#34;string&#34;&gt;福建&lt;/span&gt;	     &lt;span class=&#34;string&#34;&gt;抖音&lt;/span&gt;	      &lt;span class=&#34;string&#34;&gt;八匹马&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;3481	 &lt;/span&gt;&lt;span class=&#34;number&#34;&gt;12&lt;/span&gt;	  &lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;	    &lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;1944    &lt;/span&gt;&lt;span class=&#34;number&#34;&gt;2020-12-31&lt;/span&gt;	&lt;span class=&#34;string&#34;&gt;福建&lt;/span&gt;	     &lt;span class=&#34;string&#34;&gt;天猫&lt;/span&gt;	      &lt;span class=&#34;string&#34;&gt;八匹马&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;2673	 &lt;/span&gt;&lt;span class=&#34;number&#34;&gt;12&lt;/span&gt;	  &lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;	    &lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;在上面的代码中，通过日期时间类型的&lt;code&gt;Series&lt;/code&gt;对象的&lt;code&gt;dt&lt;/code&gt; 属性，获得一个访问日期时间的对象，通过该对象的&lt;code&gt;year&lt;/code&gt;、&lt;code&gt;month&lt;/code&gt;、&lt;code&gt;quarter&lt;/code&gt;、&lt;code&gt;hour&lt;/code&gt;等属性，就可以获取到年、月、季度、小时等时间信息，获取到的仍然是一个&lt;code&gt;Series&lt;/code&gt;对象，它包含了一组时间信息，所以我们通常也将这个&lt;code&gt;dt&lt;/code&gt;属性称为“日期时间向量”。&lt;/p&gt;
&lt;p&gt;我们再来说一说字符串类型的数据的处理，我们先从指定的 Excel 文件中读取某招聘网站的招聘数据。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;jobs_df = pd.read_csv(&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;#x27;某招聘网站招聘数据.csv&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    usecols=[&lt;span class=&#34;string&#34;&gt;&amp;#x27;city&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;companyFullName&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;positionName&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;salary&amp;#x27;&lt;/span&gt;]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;jobs_df.info()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;说明&lt;/strong&gt;：如果需要上面例子中的 Excel 文件，可以通过下面的百度云盘地址进行获取，数据在《从零开始学数据分析》目录中。链接：&lt;a href=&#34;https://pan.baidu.com/s/1rQujl5RQn9R7PadB2Z5g_g%EF%BC%8C%E6%8F%90%E5%8F%96%E7%A0%81%EF%BC%9Ae7b4%E3%80%82&#34;&gt;https://pan.baidu.com/s/1rQujl5RQn9R7PadB2Z5g_g，提取码：e7b4。&lt;/a&gt;&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight pgsql&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&amp;lt;&lt;span class=&#34;keyword&#34;&gt;class&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;#x27;pandas.core.frame.DataFrame&amp;#x27;&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;Range&lt;span class=&#34;keyword&#34;&gt;Index&lt;/span&gt;: &lt;span class=&#34;number&#34;&gt;3140&lt;/span&gt; entries, &lt;span class=&#34;number&#34;&gt;0&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;to&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;3139&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;Data &lt;span class=&#34;keyword&#34;&gt;columns&lt;/span&gt; (total &lt;span class=&#34;number&#34;&gt;4&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;columns&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt; #   &lt;span class=&#34;keyword&#34;&gt;Column&lt;/span&gt;           Non-&lt;span class=&#34;keyword&#34;&gt;Null&lt;/span&gt; Count  Dtype &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;---  ------           --------------  ----- &lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt; &lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;   city             &lt;span class=&#34;number&#34;&gt;3140&lt;/span&gt; non-&lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt;   &lt;span class=&#34;keyword&#34;&gt;object&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt; &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;   companyFullName  &lt;span class=&#34;number&#34;&gt;3140&lt;/span&gt; non-&lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt;   &lt;span class=&#34;keyword&#34;&gt;object&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt; &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;   positionName     &lt;span class=&#34;number&#34;&gt;3140&lt;/span&gt; non-&lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt;   &lt;span class=&#34;keyword&#34;&gt;object&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt; &lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;   salary           &lt;span class=&#34;number&#34;&gt;3140&lt;/span&gt; non-&lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt;   &lt;span class=&#34;keyword&#34;&gt;object&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;dtypes: &lt;span class=&#34;keyword&#34;&gt;object&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;memory &lt;span class=&#34;keyword&#34;&gt;usage&lt;/span&gt;: &lt;span class=&#34;number&#34;&gt;98.2&lt;/span&gt;+ KB&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;查看前&lt;code&gt;5&lt;/code&gt;条数据。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;jobs_df.head()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight apache&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attribute&#34;&gt;city&lt;/span&gt;    companyFullName              positionName    salary&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;0&lt;/span&gt;   北京	  达疆网络科技（上海）有限公司    数据分析岗       &lt;span class=&#34;number&#34;&gt;15&lt;/span&gt;k-&lt;span class=&#34;number&#34;&gt;30&lt;/span&gt;k&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;1&lt;/span&gt;   北京	  北京音娱时光科技有限公司        数据分析        &lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;k-&lt;span class=&#34;number&#34;&gt;18&lt;/span&gt;k&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;2&lt;/span&gt;   北京	  北京千喜鹤餐饮管理有限公司	     数据分析        &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;k-&lt;span class=&#34;number&#34;&gt;30&lt;/span&gt;k&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3&lt;/span&gt;   北京	  吉林省海生电子商务有限公司	     数据分析        &lt;span class=&#34;number&#34;&gt;33&lt;/span&gt;k-&lt;span class=&#34;number&#34;&gt;50&lt;/span&gt;k&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;4&lt;/span&gt;   北京	  韦博网讯科技（北京）有限公司	数据分析        &lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;k-&lt;span class=&#34;number&#34;&gt;15&lt;/span&gt;k&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;上面的数据表一共有&lt;code&gt;3140&lt;/code&gt;条数据，但并非所有的职位都是“数据分析”的岗位，如果要筛选出数据分析的岗位，可以通过检查&lt;code&gt;positionName&lt;/code&gt;字段是否包含“数据分析”这个关键词，这里需要模糊匹配，应该如何实现呢？我们可以先获取&lt;code&gt;positionName&lt;/code&gt;列，因为这个&lt;code&gt;Series&lt;/code&gt;对象的&lt;code&gt;dtype&lt;/code&gt;是字符串，所以可以通过&lt;code&gt;str&lt;/code&gt;属性获取对应的字符串向量，然后就可以利用我们熟悉的字符串的方法来对其进行操作，代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;jobs_df = jobs_df[jobs_df.positionName.&lt;span class=&#34;built_in&#34;&gt;str&lt;/span&gt;.contains(&lt;span class=&#34;string&#34;&gt;&amp;#x27;数据分析&amp;#x27;&lt;/span&gt;)]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;jobs_df.shape&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight clojure&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;(&lt;span class=&#34;number&#34;&gt;1515&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;可以看出，筛选后的数据还有&lt;code&gt;1515&lt;/code&gt;条。接下来，我们还需要对&lt;code&gt;salary&lt;/code&gt;字段进行处理，如果我们希望统计所有岗位的平均工资或每个城市的平均工资，首先需要将用范围表示的工资处理成其中间值，代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;jobs_df.salary.&lt;span class=&#34;built_in&#34;&gt;str&lt;/span&gt;.extract(&lt;span class=&#34;string&#34;&gt;r&amp;#x27;(\d+)[kK]?-(\d+)[kK]?&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;说明&lt;/strong&gt;：上面的代码通过正则表达式捕获组从字符串中抽取出两组数字，分别对应工资的下限和上限，对正则表达式不熟悉的读者，可以阅读我的知乎专栏“从零开始学Python”中的&lt;a href=&#34;https://zhuanlan.zhihu.com/p/158929767&#34;&gt;《正则表达式的应用》&lt;/a&gt;一文。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight tap&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;       &lt;span class=&#34;number&#34;&gt; 0 &lt;/span&gt;    1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;0	   &lt;span class=&#34;number&#34;&gt; 15 &lt;/span&gt;   30&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;1	    10	  18&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2      &lt;span class=&#34;number&#34;&gt; 20 &lt;/span&gt;   30&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3      &lt;span class=&#34;number&#34;&gt; 33 &lt;/span&gt;   50&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4      &lt;span class=&#34;number&#34;&gt; 10 &lt;/span&gt;   15&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;...     ...   ...&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3065   &lt;span class=&#34;number&#34;&gt; 8 &lt;/span&gt;    10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3069   &lt;span class=&#34;number&#34;&gt; 6 &lt;/span&gt;    10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3070   &lt;span class=&#34;number&#34;&gt; 2 &lt;/span&gt;    4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3071   &lt;span class=&#34;number&#34;&gt; 6 &lt;/span&gt;    12&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3088   &lt;span class=&#34;number&#34;&gt; 8 &lt;/span&gt;    12&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;需要提醒大家的是，抽取出来的两列数据都是字符串类型的值，我们需要将其转换成&lt;code&gt;int&lt;/code&gt;类型，才能计算平均值，对应的方法是&lt;code&gt;DataFrame&lt;/code&gt;对象的&lt;code&gt;applymap&lt;/code&gt;方法，该方法的参数是一个函数，而该函数会作用于&lt;code&gt;DataFrame&lt;/code&gt;中的每个元素。完成这一步之后，我们就可以使用&lt;code&gt;apply&lt;/code&gt;方法将上面的&lt;code&gt;DataFrame&lt;/code&gt;处理成中间值，&lt;code&gt;apply&lt;/code&gt;方法的参数也是一个函数，可以通过指定&lt;code&gt;axis&lt;/code&gt;参数使其作用于&lt;code&gt;DataFrame&lt;/code&gt; 对象的行或列，代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;temp_df = jobs_df.salary.&lt;span class=&#34;built_in&#34;&gt;str&lt;/span&gt;.extract(&lt;span class=&#34;string&#34;&gt;r&amp;#x27;(\d+)[kK]?-(\d+)[kK]?&amp;#x27;&lt;/span&gt;).applymap(&lt;span class=&#34;built_in&#34;&gt;int&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;temp_df.apply(np.mean, axis=&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; 输出：&lt;/p&gt;
&lt;figure class=&#34;highlight yaml&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;       &lt;span class=&#34;number&#34;&gt;22.5&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;       &lt;span class=&#34;number&#34;&gt;14.0&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;       &lt;span class=&#34;number&#34;&gt;25.0&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;       &lt;span class=&#34;number&#34;&gt;41.5&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;       &lt;span class=&#34;number&#34;&gt;12.5&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;string&#34;&gt;...&lt;/span&gt; &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;3065    &lt;/span&gt;&lt;span class=&#34;number&#34;&gt;9.0&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;3069    &lt;/span&gt;&lt;span class=&#34;number&#34;&gt;8.0&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;3070    &lt;/span&gt;&lt;span class=&#34;number&#34;&gt;3.0&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;3071    &lt;/span&gt;&lt;span class=&#34;number&#34;&gt;9.0&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;3088    &lt;/span&gt;&lt;span class=&#34;number&#34;&gt;10.0&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attr&#34;&gt;Length:&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;1515&lt;/span&gt;&lt;span class=&#34;string&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;dtype:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;float64&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;接下来，我们可以用上面的结果替换掉原来的&lt;code&gt;salary&lt;/code&gt;列或者增加一个新的列来表示职位对应的工资，完整的代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;temp_df = jobs_df.salary.&lt;span class=&#34;built_in&#34;&gt;str&lt;/span&gt;.extract(&lt;span class=&#34;string&#34;&gt;r&amp;#x27;(\d+)[kK]?-(\d+)[kK]?&amp;#x27;&lt;/span&gt;).applymap(&lt;span class=&#34;built_in&#34;&gt;int&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;jobs_df[&lt;span class=&#34;string&#34;&gt;&amp;#x27;salary&amp;#x27;&lt;/span&gt;] = temp_df.apply(np.mean, axis=&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;jobs_df.head()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight apache&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attribute&#34;&gt;city&lt;/span&gt;    companyFullName              positionName    salary&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;0&lt;/span&gt;   北京	  达疆网络科技（上海）有限公司    数据分析岗       &lt;span class=&#34;number&#34;&gt;22&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;5&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;1&lt;/span&gt;   北京	  北京音娱时光科技有限公司        数据分析        &lt;span class=&#34;number&#34;&gt;14&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;2&lt;/span&gt;   北京	  北京千喜鹤餐饮管理有限公司	     数据分析        &lt;span class=&#34;number&#34;&gt;25&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3&lt;/span&gt;   北京	  吉林省海生电子商务有限公司	     数据分析        &lt;span class=&#34;number&#34;&gt;41&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;5&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;4&lt;/span&gt;   北京	  韦博网讯科技（北京）有限公司	数据分析        &lt;span class=&#34;number&#34;&gt;12&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;5&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;&lt;code&gt;applymap&lt;/code&gt;和&lt;code&gt;apply&lt;/code&gt;两个方法在数据预处理的时候经常用到，&lt;code&gt;Series&lt;/code&gt;对象也有&lt;code&gt;apply&lt;/code&gt;方法，也是用于数据的预处理，但是&lt;code&gt;DataFrame&lt;/code&gt;对象还有一个名为&lt;code&gt;transform&lt;/code&gt; 的方法，也是通过传入的函数对数据进行变换，类似&lt;code&gt;Series&lt;/code&gt;对象的&lt;code&gt;map&lt;/code&gt;方法。需要强调的是，&lt;code&gt;apply&lt;/code&gt;方法具有归约效果的，简单的说就是能将较多的数据处理成较少的数据或一条数据；而&lt;code&gt;transform&lt;/code&gt;方法没有归约效果，只能对数据进行变换，原来有多少条数据，处理后还是有多少条数据。&lt;/p&gt;
&lt;p&gt;如果要对数据进行深度的分析和挖掘，字符串、日期时间这样的非数值类型都需要处理成数值，因为非数值类型没有办法计算相关性，也没有办法进行$\chi^2$检验等操作。对于字符串类型，通常可以其分为以下三类，再进行对应的处理。&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;有序变量（Ordinal Variable）：字符串表示的数据有顺序关系，那么可以对字符串进行序号化处理。&lt;/li&gt;
&lt;li&gt;分类变量（Categorical Variable）&amp;#x2F; 名义变量（Nominal Variable）：字符串表示的数据没有大小关系和等级之分，那么就可以使用独热编码的方式处理成哑变量（虚拟变量）矩阵。&lt;/li&gt;
&lt;li&gt;定距变量（Scale Variable）：字符串本质上对应到一个有大小高低之分的数据，而且可以进行加减运算，那么只需要将字符串处理成对应的数值即可。&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;对于第1类和第3类，我们可以用上面提到的&lt;code&gt;apply&lt;/code&gt;或&lt;code&gt;transform&lt;/code&gt;方法来处理，也可以利用&lt;code&gt;scikit-learn&lt;/code&gt;中的&lt;code&gt;OrdinalEncoder&lt;/code&gt;处理第1类字符串，这个我们在后续的课程中会讲到。对于第2类字符串，可以使用&lt;code&gt;pandas&lt;/code&gt;的&lt;code&gt;get_dummies()&lt;/code&gt;函数来生成哑变量（虚拟变量）矩阵，代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;persons_df = pd.DataFrame(&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    data=&amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;string&#34;&gt;&amp;#x27;姓名&amp;#x27;&lt;/span&gt;: [&lt;span class=&#34;string&#34;&gt;&amp;#x27;关羽&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;张飞&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;赵云&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;马超&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;黄忠&amp;#x27;&lt;/span&gt;],&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;string&#34;&gt;&amp;#x27;职业&amp;#x27;&lt;/span&gt;: [&lt;span class=&#34;string&#34;&gt;&amp;#x27;医生&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;医生&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;程序员&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;画家&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;教师&amp;#x27;&lt;/span&gt;],&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;string&#34;&gt;&amp;#x27;学历&amp;#x27;&lt;/span&gt;: [&lt;span class=&#34;string&#34;&gt;&amp;#x27;研究生&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;大专&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;研究生&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;高中&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;本科&amp;#x27;&lt;/span&gt;]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;persons_df&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;	姓名	职业	学历&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;0	关羽	医生	研究生&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;1	张飞	医生	大专&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2	赵云	程序员	研究生&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3	马超	画家	高中&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4	黄忠	教师	本科&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;将职业处理成哑变量矩阵。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;pd.get_dummies(persons_df[&lt;span class=&#34;string&#34;&gt;&amp;#x27;职业&amp;#x27;&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight tap&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;    医生 教师  画家  程序员&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;0	1   &lt;span class=&#34;number&#34;&gt; 0 &lt;/span&gt;  &lt;span class=&#34;number&#34;&gt; 0 &lt;/span&gt;   0&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;1	1   &lt;span class=&#34;number&#34;&gt; 0 &lt;/span&gt;  &lt;span class=&#34;number&#34;&gt; 0 &lt;/span&gt;   0&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2	0   &lt;span class=&#34;number&#34;&gt; 0 &lt;/span&gt;  &lt;span class=&#34;number&#34;&gt; 0 &lt;/span&gt;   1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3	0   &lt;span class=&#34;number&#34;&gt; 0 &lt;/span&gt;  &lt;span class=&#34;number&#34;&gt; 1 &lt;/span&gt;   0&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4	0   &lt;span class=&#34;number&#34;&gt; 1 &lt;/span&gt;  &lt;span class=&#34;number&#34;&gt; 0 &lt;/span&gt;   0&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;将学历处理成大小不同的值。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;handle_education&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;x&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    edu_dict = &amp;#123;&lt;span class=&#34;string&#34;&gt;&amp;#x27;高中&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;大专&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;本科&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;number&#34;&gt;5&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;研究生&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; edu_dict.get(x, &lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;persons_df[&lt;span class=&#34;string&#34;&gt;&amp;#x27;学历&amp;#x27;&lt;/span&gt;].apply(handle_education)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight apache&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;0&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;1&lt;/span&gt;     &lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;2&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3&lt;/span&gt;     &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;4&lt;/span&gt;     &lt;span class=&#34;number&#34;&gt;5&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;Name&lt;/span&gt;: 学历, dtype: int64&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;我们再来说说数据离散化。离散化也叫分箱，如果变量的取值是连续值，那么它的取值有无数种可能，在进行数据分组的时候就会非常的不方便，这个时候将连续变量离散化就显得非常重要。之所以把离散化叫做分箱，是因为我们可以预先设置一些箱子，每个箱子代表了数据取值的范围，这样就可以将连续的值分配到不同的箱子中，从而实现离散化。下面的例子读取了2018年北京积分落户数据，我们可以根据落户积分对数据进行分组，具体的做法如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;luohu_df = pd.read_csv(&lt;span class=&#34;string&#34;&gt;&amp;#x27;data/2018年北京积分落户数据.csv&amp;#x27;&lt;/span&gt;, index_col=&lt;span class=&#34;string&#34;&gt;&amp;#x27;id&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;luohu_df.score.describe()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight apache&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;count&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;6019&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;000000&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;mean&lt;/span&gt;       &lt;span class=&#34;number&#34;&gt;95&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;654552&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;std&lt;/span&gt;         &lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;354445&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;min&lt;/span&gt;        &lt;span class=&#34;number&#34;&gt;90&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;750000&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;25&lt;/span&gt;%        &lt;span class=&#34;number&#34;&gt;92&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;330000&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;50&lt;/span&gt;%        &lt;span class=&#34;number&#34;&gt;94&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;460000&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;75&lt;/span&gt;%        &lt;span class=&#34;number&#34;&gt;97&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;750000&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;max&lt;/span&gt;       &lt;span class=&#34;number&#34;&gt;122&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;590000&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;Name&lt;/span&gt;: score, dtype: float64&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;可以看出，落户积分的最大值是&lt;code&gt;122.59&lt;/code&gt;，最小值是&lt;code&gt;90.75&lt;/code&gt;，那么我们可以构造一个从&lt;code&gt;90&lt;/code&gt;分到&lt;code&gt;125&lt;/code&gt;分，每&lt;code&gt;5&lt;/code&gt;分一组的&lt;code&gt;7&lt;/code&gt;个箱子，&lt;code&gt;pandas&lt;/code&gt;的&lt;code&gt;cut&lt;/code&gt;函数可以帮助我们首先数据分箱，代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;bins = np.arange(&lt;span class=&#34;number&#34;&gt;90&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;126&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;5&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;pd.cut(luohu_df.score, bins, right=&lt;span class=&#34;literal&#34;&gt;False&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;说明&lt;/strong&gt;：&lt;code&gt;cut&lt;/code&gt;函数的&lt;code&gt;right&lt;/code&gt;参数默认值为&lt;code&gt;True&lt;/code&gt;，表示箱子左开右闭；修改为&lt;code&gt;False&lt;/code&gt;可以让箱子的右边界为开区间，左边界为闭区间，大家看看下面的输出就明白了。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight yaml&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;id&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;       [&lt;span class=&#34;number&#34;&gt;120&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;125&lt;/span&gt;&lt;span class=&#34;string&#34;&gt;)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;       [&lt;span class=&#34;number&#34;&gt;120&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;125&lt;/span&gt;&lt;span class=&#34;string&#34;&gt;)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;       [&lt;span class=&#34;number&#34;&gt;115&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;120&lt;/span&gt;&lt;span class=&#34;string&#34;&gt;)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;       [&lt;span class=&#34;number&#34;&gt;115&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;120&lt;/span&gt;&lt;span class=&#34;string&#34;&gt;)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;5&lt;/span&gt;       [&lt;span class=&#34;number&#34;&gt;115&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;120&lt;/span&gt;&lt;span class=&#34;string&#34;&gt;)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;           &lt;span class=&#34;string&#34;&gt;...&lt;/span&gt;    &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;6015&lt;/span&gt;      [&lt;span class=&#34;number&#34;&gt;90&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;95&lt;/span&gt;&lt;span class=&#34;string&#34;&gt;)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;6016&lt;/span&gt;      [&lt;span class=&#34;number&#34;&gt;90&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;95&lt;/span&gt;&lt;span class=&#34;string&#34;&gt;)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;6017&lt;/span&gt;      [&lt;span class=&#34;number&#34;&gt;90&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;95&lt;/span&gt;&lt;span class=&#34;string&#34;&gt;)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;6018&lt;/span&gt;      [&lt;span class=&#34;number&#34;&gt;90&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;95&lt;/span&gt;&lt;span class=&#34;string&#34;&gt;)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;6019&lt;/span&gt;      [&lt;span class=&#34;number&#34;&gt;90&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;95&lt;/span&gt;&lt;span class=&#34;string&#34;&gt;)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attr&#34;&gt;Name:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;score&lt;/span&gt;, &lt;span class=&#34;attr&#34;&gt;Length:&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;6019&lt;/span&gt;, &lt;span class=&#34;attr&#34;&gt;dtype:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;category&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;Categories&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;(7&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;interval&lt;/span&gt;[&lt;span class=&#34;string&#34;&gt;int64&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;left&lt;/span&gt;]&lt;span class=&#34;string&#34;&gt;):&lt;/span&gt; [[&lt;span class=&#34;number&#34;&gt;90&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;95&lt;/span&gt;&lt;span class=&#34;string&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;lt;&lt;/span&gt; [&lt;span class=&#34;number&#34;&gt;95&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;100&lt;/span&gt;&lt;span class=&#34;string&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;lt;&lt;/span&gt; [&lt;span class=&#34;number&#34;&gt;100&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;105&lt;/span&gt;&lt;span class=&#34;string&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;lt;&lt;/span&gt; [&lt;span class=&#34;number&#34;&gt;105&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;110&lt;/span&gt;&lt;span class=&#34;string&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;lt;&lt;/span&gt; [&lt;span class=&#34;number&#34;&gt;110&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;115&lt;/span&gt;&lt;span class=&#34;string&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;lt;&lt;/span&gt; [&lt;span class=&#34;number&#34;&gt;115&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;120&lt;/span&gt;&lt;span class=&#34;string&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;lt;&lt;/span&gt; [&lt;span class=&#34;number&#34;&gt;120&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;125&lt;/span&gt;&lt;span class=&#34;string&#34;&gt;)&lt;/span&gt;]&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;我们可以根据分箱的结果对数据进行分组，然后使用聚合函数对每个组进行统计，这是数据分析中经常用到的操作，下一个章节会为大家介绍。除此之外，&lt;code&gt;pandas&lt;/code&gt;还提供了一个名为&lt;code&gt;qcut&lt;/code&gt;的函数，可以指定分位数对数据进行分箱，有兴趣的读者可以自行研究。&lt;/p&gt;

 &lt;h2 id=&#34;Pandas的应用-2&#34;&gt;&lt;a href=&#34;#Pandas的应用-2&#34; class=&#34;headerlink&#34; title=&#34;Pandas的应用-2&#34;&gt;&lt;/a&gt;Pandas的应用-2&lt;/h2&gt;&lt;h3 id=&#34;DataFrame的应用&#34;&gt;&lt;a href=&#34;#DataFrame的应用&#34; class=&#34;headerlink&#34; title=&#34;DataFrame的应用&#34;&gt;&lt;/a&gt;DataFrame的应用&lt;/h3&gt;&lt;h4 id=&#34;创建DataFrame对象&#34;&gt;&lt;a href=&#34;#创建DataFrame对象&#34; class=&#34;headerlink&#34; title=&#34;创建DataFrame对象&#34;&gt;&lt;/a&gt;创建DataFrame对象&lt;/h4&gt;&lt;h5 id=&#34;通过二维数组创建DataFrame对象&#34;&gt;&lt;a href=&#34;#通过二维数组创建DataFrame对象&#34; class=&#34;headerlink&#34; title=&#34;通过二维数组创建DataFrame对象&#34;&gt;&lt;/a&gt;通过二维数组创建&lt;code&gt;DataFrame&lt;/code&gt;对象&lt;/h5&gt;&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;scores = np.random.randint(&lt;span class=&#34;number&#34;&gt;60&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;101&lt;/span&gt;, (&lt;span class=&#34;number&#34;&gt;5&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;))&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;courses = [&lt;span class=&#34;string&#34;&gt;&amp;#x27;语文&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;数学&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;英语&amp;#x27;&lt;/span&gt;]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;ids = [&lt;span class=&#34;number&#34;&gt;1001&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;1002&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;1003&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;1004&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;1005&lt;/span&gt;]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;df1 = pd.DataFrame(data=scores, columns=courses, index=ids)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;df1&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight yaml&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;		&lt;span class=&#34;string&#34;&gt;语文&lt;/span&gt;	&lt;span class=&#34;string&#34;&gt;数学&lt;/span&gt;	&lt;span class=&#34;string&#34;&gt;英语&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;1001    &lt;/span&gt;&lt;span class=&#34;number&#34;&gt;69&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;80&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;79&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;1002    &lt;/span&gt;&lt;span class=&#34;number&#34;&gt;71&lt;/span&gt;	  &lt;span class=&#34;number&#34;&gt;60&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;100&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;1003    &lt;/span&gt;&lt;span class=&#34;number&#34;&gt;94&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;81&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;93&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;1004    &lt;/span&gt;&lt;span class=&#34;number&#34;&gt;88&lt;/span&gt;	  &lt;span class=&#34;number&#34;&gt;88&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;67&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;1005    &lt;/span&gt;&lt;span class=&#34;number&#34;&gt;82&lt;/span&gt;	  &lt;span class=&#34;number&#34;&gt;66&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;60&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h5 id=&#34;通过字典创建DataFrame对象&#34;&gt;&lt;a href=&#34;#通过字典创建DataFrame对象&#34; class=&#34;headerlink&#34; title=&#34;通过字典创建DataFrame对象&#34;&gt;&lt;/a&gt;通过字典创建&lt;code&gt;DataFrame&lt;/code&gt;对象&lt;/h5&gt;&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;scores = &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;#x27;语文&amp;#x27;&lt;/span&gt;: [&lt;span class=&#34;number&#34;&gt;62&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;72&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;93&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;88&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;93&lt;/span&gt;],&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;#x27;数学&amp;#x27;&lt;/span&gt;: [&lt;span class=&#34;number&#34;&gt;95&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;65&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;86&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;66&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;87&lt;/span&gt;],&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;#x27;英语&amp;#x27;&lt;/span&gt;: [&lt;span class=&#34;number&#34;&gt;66&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;75&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;82&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;69&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;82&lt;/span&gt;],&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;ids = [&lt;span class=&#34;number&#34;&gt;1001&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;1002&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;1003&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;1004&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;1005&lt;/span&gt;]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;df2 = pd.DataFrame(data=scores, index=ids)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;df2&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight yaml&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;		&lt;span class=&#34;string&#34;&gt;语文&lt;/span&gt;	&lt;span class=&#34;string&#34;&gt;数学&lt;/span&gt;	&lt;span class=&#34;string&#34;&gt;英语&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;1001    &lt;/span&gt;&lt;span class=&#34;number&#34;&gt;69&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;80&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;79&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;1002    &lt;/span&gt;&lt;span class=&#34;number&#34;&gt;71&lt;/span&gt;	  &lt;span class=&#34;number&#34;&gt;60&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;100&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;1003    &lt;/span&gt;&lt;span class=&#34;number&#34;&gt;94&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;81&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;93&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;1004    &lt;/span&gt;&lt;span class=&#34;number&#34;&gt;88&lt;/span&gt;	  &lt;span class=&#34;number&#34;&gt;88&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;67&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;1005    &lt;/span&gt;&lt;span class=&#34;number&#34;&gt;82&lt;/span&gt;	  &lt;span class=&#34;number&#34;&gt;66&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;60&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h5 id=&#34;读取-CSV-文件创建DataFrame对象&#34;&gt;&lt;a href=&#34;#读取-CSV-文件创建DataFrame对象&#34; class=&#34;headerlink&#34; title=&#34;读取 CSV 文件创建DataFrame对象&#34;&gt;&lt;/a&gt;读取 CSV 文件创建&lt;code&gt;DataFrame&lt;/code&gt;对象&lt;/h5&gt;&lt;p&gt;可以通过&lt;code&gt;pandas&lt;/code&gt; 模块的&lt;code&gt;read_csv&lt;/code&gt;函数来读取 CSV 文件，&lt;code&gt;read_csv&lt;/code&gt;函数的参数非常多，下面接受几个比较重要的参数。&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;sep&lt;/code&gt; &amp;#x2F; &lt;code&gt;delimiter&lt;/code&gt;：分隔符，默认是&lt;code&gt;,&lt;/code&gt;。&lt;/li&gt;
&lt;li&gt;&lt;code&gt;header&lt;/code&gt;：表头（列索引）的位置，默认值是&lt;code&gt;infer&lt;/code&gt;，用第一行的内容作为表头（列索引）。&lt;/li&gt;
&lt;li&gt;&lt;code&gt;index_col&lt;/code&gt;：用作行索引（标签）的列。&lt;/li&gt;
&lt;li&gt;&lt;code&gt;usecols&lt;/code&gt;：需要加载的列，可以使用序号或者列名。&lt;/li&gt;
&lt;li&gt;&lt;code&gt;true_values&lt;/code&gt; &amp;#x2F; &lt;code&gt;false_values&lt;/code&gt;：哪些值被视为布尔值&lt;code&gt;True&lt;/code&gt; &amp;#x2F; &lt;code&gt;False&lt;/code&gt;。&lt;/li&gt;
&lt;li&gt;&lt;code&gt;skiprows&lt;/code&gt;：通过行号、索引或函数指定需要跳过的行。&lt;/li&gt;
&lt;li&gt;&lt;code&gt;skipfooter&lt;/code&gt;：要跳过的末尾行数。&lt;/li&gt;
&lt;li&gt;&lt;code&gt;nrows&lt;/code&gt;：需要读取的行数。&lt;/li&gt;
&lt;li&gt;&lt;code&gt;na_values&lt;/code&gt;：哪些值被视为空值。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;df3 = pd.read_csv(&lt;span class=&#34;string&#34;&gt;&amp;#x27;2018年北京积分落户数据.csv&amp;#x27;&lt;/span&gt;, index_col=&lt;span class=&#34;string&#34;&gt;&amp;#x27;id&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;df3&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight yaml&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;     &lt;span class=&#34;string&#34;&gt;name&lt;/span&gt;   &lt;span class=&#34;string&#34;&gt;birthday&lt;/span&gt;    &lt;span class=&#34;string&#34;&gt;company&lt;/span&gt;       &lt;span class=&#34;string&#34;&gt;score&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;id&lt;/span&gt;				&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;    &lt;span class=&#34;string&#34;&gt;杨x&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;1972-12&lt;/span&gt;    &lt;span class=&#34;string&#34;&gt;北京利德xxxx&lt;/span&gt;	  &lt;span class=&#34;number&#34;&gt;122.59&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;    &lt;span class=&#34;string&#34;&gt;纪x&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;1974-12&lt;/span&gt;    &lt;span class=&#34;string&#34;&gt;北京航天xxxx&lt;/span&gt;	  &lt;span class=&#34;number&#34;&gt;121.25&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;    &lt;span class=&#34;string&#34;&gt;王x&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;1974-05&lt;/span&gt;	  &lt;span class=&#34;string&#34;&gt;品牌联盟xxxx&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;118.96&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;    &lt;span class=&#34;string&#34;&gt;杨x&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;1975-07&lt;/span&gt;	  &lt;span class=&#34;string&#34;&gt;中科专利xxxx&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;118.21&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;5&lt;/span&gt;    &lt;span class=&#34;string&#34;&gt;张x&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;1974-11&lt;/span&gt;	  &lt;span class=&#34;string&#34;&gt;北京阿里xxxx&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;117.79&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;...&lt;/span&gt;  &lt;span class=&#34;string&#34;&gt;...&lt;/span&gt;    &lt;span class=&#34;string&#34;&gt;...&lt;/span&gt;        &lt;span class=&#34;string&#34;&gt;...&lt;/span&gt;            &lt;span class=&#34;string&#34;&gt;...&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;6015&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;孙x&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;1978-08&lt;/span&gt;	  &lt;span class=&#34;string&#34;&gt;华为海洋xxxx&lt;/span&gt;	  &lt;span class=&#34;number&#34;&gt;90.75&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;6016&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;刘x&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;1976-11&lt;/span&gt;	  &lt;span class=&#34;string&#34;&gt;福斯流体xxxx&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;90.75&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;6017&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;周x&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;1977-10&lt;/span&gt;	  &lt;span class=&#34;string&#34;&gt;赢创德固xxxx&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;90.75&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;6018&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;赵x&lt;/span&gt;	   &lt;span class=&#34;number&#34;&gt;1979-07&lt;/span&gt;	  &lt;span class=&#34;string&#34;&gt;澳科利耳xxxx&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;90.75&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;6019&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;贺x&lt;/span&gt;	   &lt;span class=&#34;number&#34;&gt;1981-06&lt;/span&gt;	  &lt;span class=&#34;string&#34;&gt;北京宝洁xxxx&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;90.75&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;6019 &lt;/span&gt;&lt;span class=&#34;string&#34;&gt;rows&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;×&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;4&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;columns&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;说明&lt;/strong&gt;：如果需要上面例子中的 CSV 文件，可以通过下面的百度云盘地址进行获取，数据在《从零开始学数据分析》目录中。链接：&lt;a href=&#34;https://pan.baidu.com/s/1rQujl5RQn9R7PadB2Z5g_g%EF%BC%8C%E6%8F%90%E5%8F%96%E7%A0%81%EF%BC%9Ae7b4%E3%80%82&#34;&gt;https://pan.baidu.com/s/1rQujl5RQn9R7PadB2Z5g_g，提取码：e7b4。&lt;/a&gt;&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h5 id=&#34;读取Excel文件创建DataFrame对象&#34;&gt;&lt;a href=&#34;#读取Excel文件创建DataFrame对象&#34; class=&#34;headerlink&#34; title=&#34;读取Excel文件创建DataFrame对象&#34;&gt;&lt;/a&gt;读取Excel文件创建&lt;code&gt;DataFrame&lt;/code&gt;对象&lt;/h5&gt;&lt;p&gt;可以通过&lt;code&gt;pandas&lt;/code&gt; 模块的&lt;code&gt;read_excel&lt;/code&gt;函数来读取 Exce l文件，该函数与上面的&lt;code&gt;read_csv&lt;/code&gt;非常相近，多了一个&lt;code&gt;sheet_name&lt;/code&gt;参数来指定数据表的名称，但是不同于 CSV 文件，没有&lt;code&gt;sep&lt;/code&gt;或&lt;code&gt;delimiter&lt;/code&gt;这样的参数。下面的代码中，&lt;code&gt;read_excel&lt;/code&gt;函数的&lt;code&gt;skiprows&lt;/code&gt;参数是一个 Lambda 函数，通过该 Lambda 函数指定只读取 Excel 文件的表头和其中10%的数据，跳过其他的数据。&lt;/p&gt;
&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; random&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;df4 = pd.read_excel(&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    io=&lt;span class=&#34;string&#34;&gt;&amp;#x27;小宝剑大药房2018年销售数据.xlsx&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    usecols=[&lt;span class=&#34;string&#34;&gt;&amp;#x27;购药时间&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;社保卡号&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;商品名称&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;销售数量&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;应收金额&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;实收金额&amp;#x27;&lt;/span&gt;],&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    skiprows=&lt;span class=&#34;keyword&#34;&gt;lambda&lt;/span&gt; x: x &amp;gt; &lt;span class=&#34;number&#34;&gt;0&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;and&lt;/span&gt; random.random() &amp;gt; &lt;span class=&#34;number&#34;&gt;0.1&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;df4&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;说明&lt;/strong&gt;：如果需要上面例子中的 Excel 文件，可以通过下面的百度云盘地址进行获取，数据在《从零开始学数据分析》目录中。链接：&lt;a href=&#34;https://pan.baidu.com/s/1rQujl5RQn9R7PadB2Z5g_g%EF%BC%8C%E6%8F%90%E5%8F%96%E7%A0%81%EF%BC%9Ae7b4%E3%80%82&#34;&gt;https://pan.baidu.com/s/1rQujl5RQn9R7PadB2Z5g_g，提取码：e7b4。&lt;/a&gt;&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight dns&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;    购药时间			社保卡号	    商品名称    销售数量	应收金额	实收金额&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;0	2018-03&lt;/span&gt;-&lt;span class=&#34;number&#34;&gt;23&lt;/span&gt; 星期三	&lt;span class=&#34;number&#34;&gt;10012157328&lt;/span&gt;		强力xx片	 &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;			&lt;span class=&#34;number&#34;&gt;13&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;8&lt;/span&gt;		&lt;span class=&#34;number&#34;&gt;13&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;80&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;1	2018-07&lt;/span&gt;-&lt;span class=&#34;number&#34;&gt;12&lt;/span&gt; 星期二	&lt;span class=&#34;number&#34;&gt;108207828&lt;/span&gt;	    强力xx片	 &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;	        &lt;span class=&#34;number&#34;&gt;13&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;8&lt;/span&gt;		&lt;span class=&#34;number&#34;&gt;13&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;80&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;2	2018-01&lt;/span&gt;-&lt;span class=&#34;number&#34;&gt;17&lt;/span&gt; 星期日	&lt;span class=&#34;number&#34;&gt;13358228&lt;/span&gt;	    清热xx液	 &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;		    &lt;span class=&#34;number&#34;&gt;28&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;		&lt;span class=&#34;number&#34;&gt;28&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;00&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;3	2018-07&lt;/span&gt;-&lt;span class=&#34;number&#34;&gt;11&lt;/span&gt; 星期一	&lt;span class=&#34;number&#34;&gt;10031402228&lt;/span&gt;		三九xx灵	 &lt;span class=&#34;number&#34;&gt;5&lt;/span&gt;			&lt;span class=&#34;number&#34;&gt;149&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;		&lt;span class=&#34;number&#34;&gt;130&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;00&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;4	2018-01&lt;/span&gt;-&lt;span class=&#34;number&#34;&gt;20&lt;/span&gt; 星期三	&lt;span class=&#34;number&#34;&gt;10013340328&lt;/span&gt;		三九xx灵	 &lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;			&lt;span class=&#34;number&#34;&gt;84&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;		&lt;span class=&#34;number&#34;&gt;73&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;92&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;...	...					...				...		...			...			...&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;618	2018&lt;/span&gt;-&lt;span class=&#34;number&#34;&gt;03&lt;/span&gt;-&lt;span class=&#34;number&#34;&gt;05&lt;/span&gt; 星期六	&lt;span class=&#34;number&#34;&gt;10066059228&lt;/span&gt;		开博xx通	 &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;			&lt;span class=&#34;number&#34;&gt;56&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;		&lt;span class=&#34;number&#34;&gt;49&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;28&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;619	2018&lt;/span&gt;-&lt;span class=&#34;number&#34;&gt;03&lt;/span&gt;-&lt;span class=&#34;number&#34;&gt;22&lt;/span&gt; 星期二	&lt;span class=&#34;number&#34;&gt;10035514928&lt;/span&gt;		开博xx通	 &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;			&lt;span class=&#34;number&#34;&gt;28&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;		&lt;span class=&#34;number&#34;&gt;25&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;00&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;620	2018&lt;/span&gt;-&lt;span class=&#34;number&#34;&gt;04&lt;/span&gt;-&lt;span class=&#34;number&#34;&gt;15&lt;/span&gt; 星期五	&lt;span class=&#34;number&#34;&gt;1006668328&lt;/span&gt;	    开博xx通	 &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;			&lt;span class=&#34;number&#34;&gt;56&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;		&lt;span class=&#34;number&#34;&gt;50&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;00&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;621	2018&lt;/span&gt;-&lt;span class=&#34;number&#34;&gt;04&lt;/span&gt;-&lt;span class=&#34;number&#34;&gt;24&lt;/span&gt; 星期日	&lt;span class=&#34;number&#34;&gt;10073294128&lt;/span&gt;		高特xx灵	 &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;			&lt;span class=&#34;number&#34;&gt;5&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;6&lt;/span&gt;			&lt;span class=&#34;number&#34;&gt;5&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;60&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;622	2018&lt;/span&gt;-&lt;span class=&#34;number&#34;&gt;04&lt;/span&gt;-&lt;span class=&#34;number&#34;&gt;24&lt;/span&gt; 星期日	&lt;span class=&#34;number&#34;&gt;10073294128&lt;/span&gt;		高特xx灵	 &lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;			&lt;span class=&#34;number&#34;&gt;56&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;		&lt;span class=&#34;number&#34;&gt;56&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;623&lt;/span&gt; rows × &lt;span class=&#34;number&#34;&gt;6&lt;/span&gt; columns&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h5 id=&#34;通过SQL从数据库读取数据创建DataFrame对象&#34;&gt;&lt;a href=&#34;#通过SQL从数据库读取数据创建DataFrame对象&#34; class=&#34;headerlink&#34; title=&#34;通过SQL从数据库读取数据创建DataFrame对象&#34;&gt;&lt;/a&gt;通过SQL从数据库读取数据创建&lt;code&gt;DataFrame&lt;/code&gt;对象&lt;/h5&gt;&lt;p&gt;&lt;code&gt;pandas&lt;/code&gt;模块的&lt;code&gt;read_sql&lt;/code&gt;函数可以通过 SQL 语句从数据库中读取数据创建&lt;code&gt;DataFrame&lt;/code&gt;对象，该函数的第二个参数代表了需要连接的数据库。对于 MySQL 数据库，我们可以通过&lt;code&gt;pymysql&lt;/code&gt;或&lt;code&gt;mysqlclient&lt;/code&gt;来创建数据库连接，得到一个&lt;code&gt;Connection&lt;/code&gt; 对象，而这个对象就是&lt;code&gt;read_sql&lt;/code&gt;函数需要的第二个参数，代码如下所示。&lt;/p&gt;
&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; pymysql&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 创建一个MySQL数据库的连接对象&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;conn = pymysql.connect(&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    host=&lt;span class=&#34;string&#34;&gt;&amp;#x27;47.104.31.138&amp;#x27;&lt;/span&gt;, port=&lt;span class=&#34;number&#34;&gt;3306&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    user=&lt;span class=&#34;string&#34;&gt;&amp;#x27;guest&amp;#x27;&lt;/span&gt;, password=&lt;span class=&#34;string&#34;&gt;&amp;#x27;Guest.618&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    database=&lt;span class=&#34;string&#34;&gt;&amp;#x27;hrs&amp;#x27;&lt;/span&gt;, charset=&lt;span class=&#34;string&#34;&gt;&amp;#x27;utf8mb4&amp;#x27;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 通过SQL从数据库读取数据创建DataFrame&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;df5 = pd.read_sql(&lt;span class=&#34;string&#34;&gt;&amp;#x27;select * from tb_emp&amp;#x27;&lt;/span&gt;, conn, index_col=&lt;span class=&#34;string&#34;&gt;&amp;#x27;eno&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;df5&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;提示&lt;/strong&gt;：执行上面的代码需要先安装&lt;code&gt;pymysql&lt;/code&gt;库，如果尚未安装，可以先在 Notebook 的单元格中先执行&lt;code&gt;!pip install pymysql&lt;/code&gt;，然后再运行上面的代码。上面的代码连接的是我部署在阿里云上的 MySQL 数据库，公网 IP 地址：&lt;code&gt;47.104.31.138&lt;/code&gt;，用户名：&lt;code&gt;guest&lt;/code&gt;，密码：&lt;code&gt;Guest.618&lt;/code&gt;，数据库：&lt;code&gt;hrs&lt;/code&gt;，表名：&lt;code&gt;tb_emp&lt;/code&gt;，字符集：&lt;code&gt;utf8mb4&lt;/code&gt;，大家可以使用这个数据库，但是不要进行恶意的访问。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight apache&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;attribute&#34;&gt;ename&lt;/span&gt;    job     mgr      sal    comm    dno&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;eno&lt;/span&gt;						&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;1359&lt;/span&gt;	胡一刀   销售员	&lt;span class=&#34;number&#34;&gt;3344&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;   &lt;span class=&#34;number&#34;&gt;1800&lt;/span&gt;   &lt;span class=&#34;number&#34;&gt;200&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;   &lt;span class=&#34;number&#34;&gt;30&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;2056&lt;/span&gt;	乔峰	   分析师	 &lt;span class=&#34;number&#34;&gt;7800&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;   &lt;span class=&#34;number&#34;&gt;5000&lt;/span&gt;   &lt;span class=&#34;number&#34;&gt;1500&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3088&lt;/span&gt;	李莫愁	  设计师	&lt;span class=&#34;number&#34;&gt;2056&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;   &lt;span class=&#34;number&#34;&gt;3500&lt;/span&gt;   &lt;span class=&#34;number&#34;&gt;800&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;   &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3211&lt;/span&gt;	张无忌	  程序员	&lt;span class=&#34;number&#34;&gt;2056&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;   &lt;span class=&#34;number&#34;&gt;3200&lt;/span&gt;   NaN     &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3233&lt;/span&gt;	丘处机	  程序员	&lt;span class=&#34;number&#34;&gt;2056&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;   &lt;span class=&#34;number&#34;&gt;3400&lt;/span&gt;	NaN     &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3244&lt;/span&gt;	欧阳锋	  程序员	&lt;span class=&#34;number&#34;&gt;3088&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;   &lt;span class=&#34;number&#34;&gt;3200&lt;/span&gt;	NaN     &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3251&lt;/span&gt;	张翠山	  程序员	&lt;span class=&#34;number&#34;&gt;2056&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;   &lt;span class=&#34;number&#34;&gt;4000&lt;/span&gt;	NaN     &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3344&lt;/span&gt;	黄蓉	   销售主管	&lt;span class=&#34;number&#34;&gt;7800&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;   &lt;span class=&#34;number&#34;&gt;3000&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;800&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;   &lt;span class=&#34;number&#34;&gt;30&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3577&lt;/span&gt;	杨过	   会计	  &lt;span class=&#34;number&#34;&gt;5566&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;   &lt;span class=&#34;number&#34;&gt;2200&lt;/span&gt;   NaN	  &lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3588&lt;/span&gt;	朱九真	  会计	 &lt;span class=&#34;number&#34;&gt;5566&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;   &lt;span class=&#34;number&#34;&gt;2500&lt;/span&gt;   NaN	 &lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;4466&lt;/span&gt;	苗人凤	  销售员	&lt;span class=&#34;number&#34;&gt;3344&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;   &lt;span class=&#34;number&#34;&gt;2500&lt;/span&gt;	NaN     &lt;span class=&#34;number&#34;&gt;30&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;5234&lt;/span&gt;	郭靖	   出纳	  &lt;span class=&#34;number&#34;&gt;5566&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;   &lt;span class=&#34;number&#34;&gt;2000&lt;/span&gt;   NaN	  &lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;5566&lt;/span&gt;	宋远桥	  会计师	&lt;span class=&#34;number&#34;&gt;7800&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;   &lt;span class=&#34;number&#34;&gt;4000&lt;/span&gt;   &lt;span class=&#34;number&#34;&gt;1000&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;  &lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;7800&lt;/span&gt;	张三丰	  总裁	 NaN      &lt;span class=&#34;number&#34;&gt;9000&lt;/span&gt;   &lt;span class=&#34;number&#34;&gt;1200&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;  &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h4 id=&#34;基本属性和方法&#34;&gt;&lt;a href=&#34;#基本属性和方法&#34; class=&#34;headerlink&#34; title=&#34;基本属性和方法&#34;&gt;&lt;/a&gt;基本属性和方法&lt;/h4&gt;&lt;p&gt;在开始讲解&lt;code&gt;DataFrame&lt;/code&gt;的属性和方法前，我们先从之前提到的&lt;code&gt;hrs&lt;/code&gt;数据库中读取三张表的数据，创建出三个&lt;code&gt;DataFrame&lt;/code&gt;对象，代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; pymysql&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;conn = pymysql.connect(&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    host=&lt;span class=&#34;string&#34;&gt;&amp;#x27;47.104.31.138&amp;#x27;&lt;/span&gt;, port=&lt;span class=&#34;number&#34;&gt;3306&lt;/span&gt;, &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    user=&lt;span class=&#34;string&#34;&gt;&amp;#x27;guest&amp;#x27;&lt;/span&gt;, password=&lt;span class=&#34;string&#34;&gt;&amp;#x27;Guest.618&amp;#x27;&lt;/span&gt;, &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    database=&lt;span class=&#34;string&#34;&gt;&amp;#x27;hrs&amp;#x27;&lt;/span&gt;, charset=&lt;span class=&#34;string&#34;&gt;&amp;#x27;utf8mb4&amp;#x27;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;dept_df = pd.read_sql(&lt;span class=&#34;string&#34;&gt;&amp;#x27;select * from tb_dept&amp;#x27;&lt;/span&gt;, conn, index_col=&lt;span class=&#34;string&#34;&gt;&amp;#x27;dno&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;emp_df = pd.read_sql(&lt;span class=&#34;string&#34;&gt;&amp;#x27;select * from tb_emp&amp;#x27;&lt;/span&gt;, conn, index_col=&lt;span class=&#34;string&#34;&gt;&amp;#x27;eno&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;emp2_df = pd.read_sql(&lt;span class=&#34;string&#34;&gt;&amp;#x27;select * from tb_emp2&amp;#x27;&lt;/span&gt;, conn, index_col=&lt;span class=&#34;string&#34;&gt;&amp;#x27;eno&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;得到的三个&lt;code&gt;DataFrame&lt;/code&gt;对象如下所示。&lt;/p&gt;
&lt;p&gt;部门表（&lt;code&gt;dept_df&lt;/code&gt;），其中&lt;code&gt;dno&lt;/code&gt;是部门的编号，&lt;code&gt;dname&lt;/code&gt;和&lt;code&gt;dloc&lt;/code&gt;分别是部门的名称和所在地。&lt;/p&gt;
&lt;figure class=&#34;highlight nginx&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attribute&#34;&gt;dname&lt;/span&gt;  dloc&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;dno&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;	会计部	北京&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;	研发部	成都&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;30&lt;/span&gt;	销售部	重庆&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;40&lt;/span&gt;	运维部	天津&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;员工表（&lt;code&gt;emp_df&lt;/code&gt;），其中&lt;code&gt;eno&lt;/code&gt;是员工编号，&lt;code&gt;ename&lt;/code&gt;、&lt;code&gt;job&lt;/code&gt;、&lt;code&gt;mgr&lt;/code&gt;、&lt;code&gt;sal&lt;/code&gt;、&lt;code&gt;comm&lt;/code&gt;和&lt;code&gt;dno&lt;/code&gt;分别代表员工的姓名、职位、主管编号、月薪、补贴和部门编号。&lt;/p&gt;
&lt;figure class=&#34;highlight apache&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;attribute&#34;&gt;ename&lt;/span&gt;    job        mgr      sal     comm    dno&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;eno&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;1359&lt;/span&gt;	胡一刀    销售员	   &lt;span class=&#34;number&#34;&gt;3344&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;1800&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;200&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;30&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;2056&lt;/span&gt;	乔峰	    分析师	    &lt;span class=&#34;number&#34;&gt;7800&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;5000&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;1500&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3088&lt;/span&gt;	李莫愁	   设计师	   &lt;span class=&#34;number&#34;&gt;2056&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;3500&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;800&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3211&lt;/span&gt;	张无忌	   程序员	   &lt;span class=&#34;number&#34;&gt;2056&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;3200&lt;/span&gt;	NaN     &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3233&lt;/span&gt;	丘处机	   程序员	   &lt;span class=&#34;number&#34;&gt;2056&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;3400&lt;/span&gt;	NaN	    &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3244&lt;/span&gt;	欧阳锋	   程序员	   &lt;span class=&#34;number&#34;&gt;3088&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;3200&lt;/span&gt;	NaN     &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3251&lt;/span&gt;	张翠山	   程序员	   &lt;span class=&#34;number&#34;&gt;2056&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;4000&lt;/span&gt;	NaN	    &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3344&lt;/span&gt;	黄蓉	    销售主管   &lt;span class=&#34;number&#34;&gt;7800&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;3000&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;800&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;30&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3577&lt;/span&gt;	杨过	    会计	     &lt;span class=&#34;number&#34;&gt;5566&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	  &lt;span class=&#34;number&#34;&gt;2200&lt;/span&gt;	  NaN	  &lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3588&lt;/span&gt;	朱九真	   会计	    &lt;span class=&#34;number&#34;&gt;5566&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;2500&lt;/span&gt;	 NaN	 &lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;4466&lt;/span&gt;	苗人凤	   销售员	   &lt;span class=&#34;number&#34;&gt;3344&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;2500&lt;/span&gt;	NaN	    &lt;span class=&#34;number&#34;&gt;30&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;5234&lt;/span&gt;	郭靖	    出纳	     &lt;span class=&#34;number&#34;&gt;5566&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	  &lt;span class=&#34;number&#34;&gt;2000&lt;/span&gt;	  NaN	  &lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;5566&lt;/span&gt;	宋远桥	   会计师	   &lt;span class=&#34;number&#34;&gt;7800&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;4000&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;1000&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;7800&lt;/span&gt;	张三丰	   总裁	    NaN      &lt;span class=&#34;number&#34;&gt;9000&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;1200&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;说明&lt;/strong&gt;：在数据库中&lt;code&gt;mgr&lt;/code&gt;和&lt;code&gt;comm&lt;/code&gt;两个列的数据类型是&lt;code&gt;int&lt;/code&gt;，但是因为有缺失值（空值），读取到&lt;code&gt;DataFrame&lt;/code&gt;之后，列的数据类型变成了&lt;code&gt;float&lt;/code&gt;，因为我们通常会用&lt;code&gt;float&lt;/code&gt;类型的&lt;code&gt;NaN&lt;/code&gt;来表示空值。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;员工表（&lt;code&gt;emp2_df&lt;/code&gt;），跟上面的员工表结构相同，但是保存了不同的员工数据。&lt;/p&gt;
&lt;figure class=&#34;highlight apache&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;attribute&#34;&gt;ename&lt;/span&gt;    job    mgr     sal      comm    dno&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;eno&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;9800&lt;/span&gt;	骆昊	   架构师	&lt;span class=&#34;number&#34;&gt;7800&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;30000&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;5000&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;9900&lt;/span&gt;	王小刀	  程序员  &lt;span class=&#34;number&#34;&gt;9800&lt;/span&gt;	   &lt;span class=&#34;number&#34;&gt;10000&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;1200&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;9700&lt;/span&gt;	王大锤	  程序员  &lt;span class=&#34;number&#34;&gt;9800&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;8000&lt;/span&gt; 	&lt;span class=&#34;number&#34;&gt;600&lt;/span&gt;	    &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;&lt;code&gt;DataFrame&lt;/code&gt;对象的属性如下表所示。&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;属性名&lt;/th&gt;
&lt;th&gt;说明&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;&lt;code&gt;at&lt;/code&gt; &amp;#x2F; &lt;code&gt;iat&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;通过标签获取&lt;code&gt;DataFrame&lt;/code&gt;中的单个值。&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;columns&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;DataFrame&lt;/code&gt;对象列的索引&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;dtypes&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;DataFrame&lt;/code&gt;对象每一列的数据类型&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;empty&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;DataFrame&lt;/code&gt;对象是否为空&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;loc&lt;/code&gt; &amp;#x2F; &lt;code&gt;iloc&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;通过标签获取&lt;code&gt;DataFrame&lt;/code&gt;中的一组值。&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;ndim&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;DataFrame&lt;/code&gt;对象的维度&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;shape&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;DataFrame&lt;/code&gt;对象的形状（行数和列数）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;size&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;DataFrame&lt;/code&gt;对象中元素的个数&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;values&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;DataFrame&lt;/code&gt;对象的数据对应的二维数组&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;p&gt;关于&lt;code&gt;DataFrame&lt;/code&gt;的方法，首先需要了解的是&lt;code&gt;info()&lt;/code&gt;方法，它可以帮助我们了解&lt;code&gt;DataFrame&lt;/code&gt;的相关信息，如下所示。&lt;/p&gt;
&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;emp_df.info()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight pgsql&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&amp;lt;&lt;span class=&#34;keyword&#34;&gt;class&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;#x27;pandas.core.frame.DataFrame&amp;#x27;&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;Int64Index: &lt;span class=&#34;number&#34;&gt;14&lt;/span&gt; entries, &lt;span class=&#34;number&#34;&gt;1359&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;to&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;7800&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;Data &lt;span class=&#34;keyword&#34;&gt;columns&lt;/span&gt; (total &lt;span class=&#34;number&#34;&gt;6&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;columns&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt; #   &lt;span class=&#34;keyword&#34;&gt;Column&lt;/span&gt;  Non-&lt;span class=&#34;keyword&#34;&gt;Null&lt;/span&gt; Count  Dtype  &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;---  ------  --------------  -----  &lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt; &lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;   ename   &lt;span class=&#34;number&#34;&gt;14&lt;/span&gt; non-&lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt;     &lt;span class=&#34;keyword&#34;&gt;object&lt;/span&gt; &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt; &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;   job     &lt;span class=&#34;number&#34;&gt;14&lt;/span&gt; non-&lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt;     &lt;span class=&#34;keyword&#34;&gt;object&lt;/span&gt; &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt; &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;   mgr     &lt;span class=&#34;number&#34;&gt;13&lt;/span&gt; non-&lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt;     float64&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt; &lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;   sal     &lt;span class=&#34;number&#34;&gt;14&lt;/span&gt; non-&lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt;     int64  &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt; &lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;   comm    &lt;span class=&#34;number&#34;&gt;6&lt;/span&gt; non-&lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt;      float64&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt; &lt;span class=&#34;number&#34;&gt;5&lt;/span&gt;   dno     &lt;span class=&#34;number&#34;&gt;14&lt;/span&gt; non-&lt;span class=&#34;keyword&#34;&gt;null&lt;/span&gt;     int64  &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;dtypes: float64(&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;), int64(&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;), &lt;span class=&#34;keyword&#34;&gt;object&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;memory &lt;span class=&#34;keyword&#34;&gt;usage&lt;/span&gt;: &lt;span class=&#34;number&#34;&gt;1.3&lt;/span&gt;+ KB&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;如果需要查看&lt;code&gt;DataFrame&lt;/code&gt;的头部或尾部的数据，可以使用&lt;code&gt;head()&lt;/code&gt;或&lt;code&gt;tail()&lt;/code&gt;方法，这两个方法的默认参数是&lt;code&gt;5&lt;/code&gt;，表示获取&lt;code&gt;DataFrame&lt;/code&gt;最前面5行或最后面5行的数据，如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;emp_df.head()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight apache&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;attribute&#34;&gt;ename&lt;/span&gt;    job    mgr    sal    comm  dno&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;eno&lt;/span&gt;						&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;1359&lt;/span&gt;	胡一刀   销售员	&lt;span class=&#34;number&#34;&gt;3344&lt;/span&gt;   &lt;span class=&#34;number&#34;&gt;1800&lt;/span&gt;  &lt;span class=&#34;number&#34;&gt;200&lt;/span&gt;   &lt;span class=&#34;number&#34;&gt;30&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;2056&lt;/span&gt;	乔峰	   分析师	 &lt;span class=&#34;number&#34;&gt;7800&lt;/span&gt;   &lt;span class=&#34;number&#34;&gt;5000&lt;/span&gt;  &lt;span class=&#34;number&#34;&gt;1500&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3088&lt;/span&gt;	李莫愁	  设计师	&lt;span class=&#34;number&#34;&gt;2056&lt;/span&gt;   &lt;span class=&#34;number&#34;&gt;3500&lt;/span&gt;  &lt;span class=&#34;number&#34;&gt;800&lt;/span&gt;   &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3211&lt;/span&gt;	张无忌	  程序员	&lt;span class=&#34;number&#34;&gt;2056&lt;/span&gt;   &lt;span class=&#34;number&#34;&gt;3200&lt;/span&gt;  NaN   &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3233&lt;/span&gt;	丘处机	  程序员	&lt;span class=&#34;number&#34;&gt;2056&lt;/span&gt;   &lt;span class=&#34;number&#34;&gt;3400&lt;/span&gt;	 NaN   &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h4 id=&#34;获取数据&#34;&gt;&lt;a href=&#34;#获取数据&#34; class=&#34;headerlink&#34; title=&#34;获取数据&#34;&gt;&lt;/a&gt;获取数据&lt;/h4&gt;&lt;h5 id=&#34;索引和切片&#34;&gt;&lt;a href=&#34;#索引和切片&#34; class=&#34;headerlink&#34; title=&#34;索引和切片&#34;&gt;&lt;/a&gt;索引和切片&lt;/h5&gt;&lt;p&gt;如果要获取&lt;code&gt;DataFrame&lt;/code&gt;的某一列，例如取出上面&lt;code&gt;emp_df&lt;/code&gt;的&lt;code&gt;ename&lt;/code&gt;列，可以使用下面的两种方式。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;emp_df.ename&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;或者&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;emp_df[&lt;span class=&#34;string&#34;&gt;&amp;#x27;ename&amp;#x27;&lt;/span&gt;]&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;执行上面的代码可以发现，我们获得的是一个&lt;code&gt;Series&lt;/code&gt;对象。事实上，&lt;code&gt;DataFrame&lt;/code&gt;对象就是将多个&lt;code&gt;Series&lt;/code&gt;对象组合到一起的结果。&lt;/p&gt;
&lt;p&gt;如果要获取&lt;code&gt;DataFrame&lt;/code&gt;的某一行，可以使用整数索引或我们设置的索引，例如取出员工编号为&lt;code&gt;2056&lt;/code&gt;的员工数据，代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;emp_df.iloc[&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;]&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;或者&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;emp_df.loc[&lt;span class=&#34;number&#34;&gt;2056&lt;/span&gt;]&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;通过执行上面的代码我们发现，单独取&lt;code&gt;DataFrame&lt;/code&gt; 的某一行或某一列得到的都是&lt;code&gt;Series&lt;/code&gt;对象。我们当然也可以通过花式索引来获取多个行或多个列的数据，花式索引的结果仍然是一个&lt;code&gt;DataFrame&lt;/code&gt;对象。&lt;/p&gt;
&lt;p&gt;获取多个列：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;emp_df[[&lt;span class=&#34;string&#34;&gt;&amp;#x27;ename&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;job&amp;#x27;&lt;/span&gt;]]&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;获取多个行：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;emp_df.loc[[&lt;span class=&#34;number&#34;&gt;2056&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;7800&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;3344&lt;/span&gt;]]&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;如果要获取或修改&lt;code&gt;DataFrame&lt;/code&gt; 对象某个单元格的数据，需要同时指定行和列的索引，例如要获取员工编号为&lt;code&gt;2056&lt;/code&gt;的员工的职位信息，代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;emp_df[&lt;span class=&#34;string&#34;&gt;&amp;#x27;job&amp;#x27;&lt;/span&gt;][&lt;span class=&#34;number&#34;&gt;2056&lt;/span&gt;]&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;或者&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;emp_df.loc[&lt;span class=&#34;number&#34;&gt;2056&lt;/span&gt;][&lt;span class=&#34;string&#34;&gt;&amp;#x27;job&amp;#x27;&lt;/span&gt;]&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;或者&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;emp_df.loc[&lt;span class=&#34;number&#34;&gt;2056&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;job&amp;#x27;&lt;/span&gt;]&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;我们推荐大家使用第三种做法，因为它只做了一次索引运算。如果要将该员工的职位修改为“架构师”，可以使用下面的代码。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;emp_df.loc[&lt;span class=&#34;number&#34;&gt;2056&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;job&amp;#x27;&lt;/span&gt;] = &lt;span class=&#34;string&#34;&gt;&amp;#x27;架构师&amp;#x27;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;当然，我们也可以通过切片操作来获取多行多列，相信大家一定已经想到了这一点。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;emp_df.loc[&lt;span class=&#34;number&#34;&gt;2056&lt;/span&gt;:&lt;span class=&#34;number&#34;&gt;3344&lt;/span&gt;]&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight apache&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;attribute&#34;&gt;ename&lt;/span&gt;    job        mgr      sal     comm    dno&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;eno&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;2056&lt;/span&gt;	乔峰	    分析师	    &lt;span class=&#34;number&#34;&gt;7800&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;5000&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;1500&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3088&lt;/span&gt;	李莫愁	   设计师	   &lt;span class=&#34;number&#34;&gt;2056&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;3500&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;800&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3211&lt;/span&gt;	张无忌	   程序员	   &lt;span class=&#34;number&#34;&gt;2056&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;3200&lt;/span&gt;	NaN     &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3233&lt;/span&gt;	丘处机	   程序员	   &lt;span class=&#34;number&#34;&gt;2056&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;3400&lt;/span&gt;	NaN	    &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3244&lt;/span&gt;	欧阳锋	   程序员	   &lt;span class=&#34;number&#34;&gt;3088&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;3200&lt;/span&gt;	NaN     &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3251&lt;/span&gt;	张翠山	   程序员	   &lt;span class=&#34;number&#34;&gt;2056&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;4000&lt;/span&gt;	NaN	    &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3344&lt;/span&gt;	黄蓉	    销售主管   &lt;span class=&#34;number&#34;&gt;7800&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;3000&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;800&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;30&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h5 id=&#34;数据筛选&#34;&gt;&lt;a href=&#34;#数据筛选&#34; class=&#34;headerlink&#34; title=&#34;数据筛选&#34;&gt;&lt;/a&gt;数据筛选&lt;/h5&gt;&lt;p&gt;上面我们提到了花式索引，相信大家已经联想到了布尔索引。跟&lt;code&gt;ndarray&lt;/code&gt;和&lt;code&gt;Series&lt;/code&gt;一样，我们可以通过布尔索引对&lt;code&gt;DataFrame&lt;/code&gt;对象进行数据筛选，例如我们要从&lt;code&gt;emp_df&lt;/code&gt;中筛选出月薪超过&lt;code&gt;3500&lt;/code&gt;的员工，代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;emp_df[emp_df.sal &amp;gt; &lt;span class=&#34;number&#34;&gt;3500&lt;/span&gt;]&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight apache&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;attribute&#34;&gt;ename&lt;/span&gt;    job        mgr      sal     comm    dno&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;eno&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;2056&lt;/span&gt;	乔峰	    分析师	    &lt;span class=&#34;number&#34;&gt;7800&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;5000&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;1500&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3251&lt;/span&gt;	张翠山	   程序员	   &lt;span class=&#34;number&#34;&gt;2056&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;4000&lt;/span&gt;	NaN	    &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;5566&lt;/span&gt;	宋远桥	   会计师	   &lt;span class=&#34;number&#34;&gt;7800&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;4000&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;1000&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;7800&lt;/span&gt;	张三丰	   总裁	    NaN      &lt;span class=&#34;number&#34;&gt;9000&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;1200&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;当然，我们也可以组合多个条件来进行数据筛选，例如从&lt;code&gt;emp_df&lt;/code&gt;中筛选出月薪超过&lt;code&gt;3500&lt;/code&gt;且部门编号为&lt;code&gt;20&lt;/code&gt;的员工，代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;emp_df[(emp_df.sal &amp;gt; &lt;span class=&#34;number&#34;&gt;3500&lt;/span&gt;) &amp;amp; (emp_df.dno == &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;)]&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight apache&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;attribute&#34;&gt;ename&lt;/span&gt;    job        mgr      sal     comm    dno&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;eno&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;2056&lt;/span&gt;	乔峰	    分析师	    &lt;span class=&#34;number&#34;&gt;7800&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;5000&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;1500&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3251&lt;/span&gt;	张翠山	   程序员	   &lt;span class=&#34;number&#34;&gt;2056&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;4000&lt;/span&gt;	NaN	    &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;7800&lt;/span&gt;	张三丰	   总裁	    NaN      &lt;span class=&#34;number&#34;&gt;9000&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;1200&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;除了使用布尔索引，&lt;code&gt;DataFrame&lt;/code&gt;对象的&lt;code&gt;query&lt;/code&gt;方法也可以实现数据筛选，&lt;code&gt;query&lt;/code&gt;方法的参数是一个字符串，它代表了筛选数据使用的表达式，而且更符合 Python 程序员的使用习惯。下面我们使用&lt;code&gt;query&lt;/code&gt;方法将上面的效果重新实现一遍，代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;emp_df.query(&lt;span class=&#34;string&#34;&gt;&amp;#x27;sal &amp;gt; 3500 and dno == 20&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h4 id=&#34;重塑数据&#34;&gt;&lt;a href=&#34;#重塑数据&#34; class=&#34;headerlink&#34; title=&#34;重塑数据&#34;&gt;&lt;/a&gt;重塑数据&lt;/h4&gt;&lt;p&gt;有的时候，我们做数据分析需要的原始数据可能并不是来自一个地方，就像上面的例子中，我们从关系型数据库中读取了三张表，得到了三个&lt;code&gt;DataFrame&lt;/code&gt;对象，但实际工作可能需要我们把他们的数据整合到一起。例如：&lt;code&gt;emp_df&lt;/code&gt;和&lt;code&gt;emp2_df&lt;/code&gt;其实都是员工的数据，而且数据结构完全一致，我们可以使用&lt;code&gt;pandas&lt;/code&gt;提供的&lt;code&gt;concat&lt;/code&gt;函数实现两个或多个&lt;code&gt;DataFrame&lt;/code&gt;的数据拼接，代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;all_emp_df = pd.concat([emp_df, emp2_df])&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight apache&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;attribute&#34;&gt;ename&lt;/span&gt;    job        mgr      sal     comm    dno&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;eno&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;1359&lt;/span&gt;    胡一刀    销售员	   &lt;span class=&#34;number&#34;&gt;3344&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;1800&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;200&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;30&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;2056&lt;/span&gt;    乔峰	    分析师	    &lt;span class=&#34;number&#34;&gt;7800&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;5000&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;1500&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3088&lt;/span&gt;    李莫愁	   设计师	   &lt;span class=&#34;number&#34;&gt;2056&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;3500&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;800&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3211&lt;/span&gt;    张无忌	   程序员	   &lt;span class=&#34;number&#34;&gt;2056&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;3200&lt;/span&gt;	NaN     &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3233&lt;/span&gt;    丘处机	   程序员	   &lt;span class=&#34;number&#34;&gt;2056&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;3400&lt;/span&gt;	NaN	    &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3244&lt;/span&gt;    欧阳锋	   程序员	   &lt;span class=&#34;number&#34;&gt;3088&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;3200&lt;/span&gt;	NaN     &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3251&lt;/span&gt;    张翠山	   程序员	   &lt;span class=&#34;number&#34;&gt;2056&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;4000&lt;/span&gt;	NaN	    &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3344&lt;/span&gt;    黄蓉	    销售主管   &lt;span class=&#34;number&#34;&gt;7800&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;3000&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;800&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;30&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3577&lt;/span&gt;    杨过	    会计	     &lt;span class=&#34;number&#34;&gt;5566&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	  &lt;span class=&#34;number&#34;&gt;2200&lt;/span&gt;	  NaN	  &lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3588&lt;/span&gt;    朱九真	   会计	    &lt;span class=&#34;number&#34;&gt;5566&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;2500&lt;/span&gt;	 NaN	 &lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;4466&lt;/span&gt;    苗人凤	   销售员	   &lt;span class=&#34;number&#34;&gt;3344&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;2500&lt;/span&gt;	NaN	    &lt;span class=&#34;number&#34;&gt;30&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;5234&lt;/span&gt;    郭靖	    出纳	     &lt;span class=&#34;number&#34;&gt;5566&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	  &lt;span class=&#34;number&#34;&gt;2000&lt;/span&gt;	  NaN	  &lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;5566&lt;/span&gt;    宋远桥	   会计师	   &lt;span class=&#34;number&#34;&gt;7800&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;4000&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;1000&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;7800&lt;/span&gt;    张三丰	   总裁	    NaN      &lt;span class=&#34;number&#34;&gt;9000&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;1200&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;9800&lt;/span&gt;    骆昊	    架构师     &lt;span class=&#34;number&#34;&gt;7800&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;30000&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;5000&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;9900&lt;/span&gt;    王小刀	   程序员     &lt;span class=&#34;number&#34;&gt;9800&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;10000&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;1200&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;9700&lt;/span&gt;    王大锤	   程序员     &lt;span class=&#34;number&#34;&gt;9800&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;8000&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;600&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	&lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;上面的代码将两个代表员工数据的&lt;code&gt;DataFrame&lt;/code&gt;拼接到了一起，接下来我们使用&lt;code&gt;merge&lt;/code&gt;函数将员工表和部门表的数据合并到一张表中，代码如下所示。&lt;/p&gt;
&lt;p&gt;先使用&lt;code&gt;reset_index&lt;/code&gt;方法重新设置&lt;code&gt;all_emp_df&lt;/code&gt;的索引，这样&lt;code&gt;eno&lt;/code&gt; 不再是索引而是一个普通列，&lt;code&gt;reset_index&lt;/code&gt;方法的&lt;code&gt;inplace&lt;/code&gt;参数设置为&lt;code&gt;True&lt;/code&gt;表示，重置索引的操作直接在&lt;code&gt;all_emp_df&lt;/code&gt;上执行，而不是返回修改后的新对象。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;all_emp_df.reset_index(inplace=&lt;span class=&#34;literal&#34;&gt;True&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;通过&lt;code&gt;merge&lt;/code&gt;函数合并数据，当然，也可以调用&lt;code&gt;DataFrame&lt;/code&gt;对象的&lt;code&gt;merge&lt;/code&gt;方法来达到同样的效果。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;pd.merge(dept_df, all_emp_df, how=&lt;span class=&#34;string&#34;&gt;&amp;#x27;inner&amp;#x27;&lt;/span&gt;, on=&lt;span class=&#34;string&#34;&gt;&amp;#x27;dno&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight apache&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attribute&#34;&gt;dno&lt;/span&gt; dname  dloc eno   ename  job      mgr     sal    comm&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;0&lt;/span&gt;   &lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;	会计部	北京	&lt;span class=&#34;number&#34;&gt;3577&lt;/span&gt;  杨过	会计	   &lt;span class=&#34;number&#34;&gt;5566&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;  &lt;span class=&#34;number&#34;&gt;2200&lt;/span&gt;   NaN&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;1&lt;/span&gt;   &lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;	会计部	北京	&lt;span class=&#34;number&#34;&gt;3588&lt;/span&gt;  朱九真  会计     &lt;span class=&#34;number&#34;&gt;5566&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;  &lt;span class=&#34;number&#34;&gt;2500&lt;/span&gt;   NaN&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;2&lt;/span&gt;   &lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;	会计部	北京	&lt;span class=&#34;number&#34;&gt;5234&lt;/span&gt;  郭靖	出纳	   &lt;span class=&#34;number&#34;&gt;5566&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;  &lt;span class=&#34;number&#34;&gt;2000&lt;/span&gt;   NaN&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3&lt;/span&gt;   &lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;	会计部	北京	&lt;span class=&#34;number&#34;&gt;5566&lt;/span&gt;  宋远桥  会计师   &lt;span class=&#34;number&#34;&gt;7800&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;4000&lt;/span&gt;   &lt;span class=&#34;number&#34;&gt;1000&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;4&lt;/span&gt;   &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;	研发部	成都	&lt;span class=&#34;number&#34;&gt;2056&lt;/span&gt;  乔峰	架构师   &lt;span class=&#34;number&#34;&gt;7800&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;  &lt;span class=&#34;number&#34;&gt;5000&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;1500&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;5&lt;/span&gt;   &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;	研发部	成都	&lt;span class=&#34;number&#34;&gt;3088&lt;/span&gt;  李莫愁  设计师   &lt;span class=&#34;number&#34;&gt;2056&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;3500&lt;/span&gt;   &lt;span class=&#34;number&#34;&gt;800&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;6&lt;/span&gt;   &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;	研发部	成都	&lt;span class=&#34;number&#34;&gt;3211&lt;/span&gt;  张无忌  程序员   &lt;span class=&#34;number&#34;&gt;2056&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;3200&lt;/span&gt;   NaN&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;7&lt;/span&gt;   &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;	研发部	成都	&lt;span class=&#34;number&#34;&gt;3233&lt;/span&gt;  丘处机  程序员   &lt;span class=&#34;number&#34;&gt;2056&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;3400&lt;/span&gt;   NaN&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;8&lt;/span&gt;   &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;	研发部	成都	&lt;span class=&#34;number&#34;&gt;3244&lt;/span&gt;  欧阳锋  程序员   &lt;span class=&#34;number&#34;&gt;3088&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;3200&lt;/span&gt;   NaN&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;9&lt;/span&gt;   &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;	研发部	成都	&lt;span class=&#34;number&#34;&gt;3251&lt;/span&gt;  张翠山  程序员   &lt;span class=&#34;number&#34;&gt;2056&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;4000&lt;/span&gt;   NaN&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;10&lt;/span&gt;  &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;	研发部	成都	&lt;span class=&#34;number&#34;&gt;7800&lt;/span&gt;  张三丰  总裁     NaN     &lt;span class=&#34;number&#34;&gt;9000&lt;/span&gt;   &lt;span class=&#34;number&#34;&gt;1200&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;11&lt;/span&gt;  &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;	研发部	成都	&lt;span class=&#34;number&#34;&gt;9800&lt;/span&gt;  骆昊    架构师   &lt;span class=&#34;number&#34;&gt;7800&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;  &lt;span class=&#34;number&#34;&gt;30000&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;5000&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;12&lt;/span&gt;  &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;	研发部	成都	&lt;span class=&#34;number&#34;&gt;9900&lt;/span&gt;  王小刀  程序员	 &lt;span class=&#34;number&#34;&gt;9800&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;10000&lt;/span&gt;  &lt;span class=&#34;number&#34;&gt;1200&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;13&lt;/span&gt;  &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;	研发部	成都	&lt;span class=&#34;number&#34;&gt;9700&lt;/span&gt;  王大锤  程序员	 &lt;span class=&#34;number&#34;&gt;9800&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;8000&lt;/span&gt;   &lt;span class=&#34;number&#34;&gt;600&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;14&lt;/span&gt;  &lt;span class=&#34;number&#34;&gt;30&lt;/span&gt;	销售部	重庆	&lt;span class=&#34;number&#34;&gt;1359&lt;/span&gt;  胡一刀  销售员	 &lt;span class=&#34;number&#34;&gt;3344&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;1800&lt;/span&gt;   &lt;span class=&#34;number&#34;&gt;200&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;15&lt;/span&gt;  &lt;span class=&#34;number&#34;&gt;30&lt;/span&gt;	销售部	重庆	&lt;span class=&#34;number&#34;&gt;3344&lt;/span&gt;  黄蓉    销售主管 &lt;span class=&#34;number&#34;&gt;7800&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;3000&lt;/span&gt;   &lt;span class=&#34;number&#34;&gt;800&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;16&lt;/span&gt;  &lt;span class=&#34;number&#34;&gt;30&lt;/span&gt;	销售部	重庆	&lt;span class=&#34;number&#34;&gt;4466&lt;/span&gt;  苗人凤  销售员   &lt;span class=&#34;number&#34;&gt;3344&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;	 &lt;span class=&#34;number&#34;&gt;2500&lt;/span&gt;   NaN&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;&lt;code&gt;merge&lt;/code&gt;函数的一个参数代表合并的左表、第二个参数代表合并的右表，有SQL编程经验的同学对这两个词是不是感觉到非常亲切。正如大家猜想的那样，&lt;code&gt;DataFrame&lt;/code&gt;对象的合并跟数据库中的表连接非常类似，所以上面代码中的&lt;code&gt;how&lt;/code&gt;代表了合并两张表的方式，有&lt;code&gt;left&lt;/code&gt;、&lt;code&gt;right&lt;/code&gt;、&lt;code&gt;inner&lt;/code&gt;、&lt;code&gt;outer&lt;/code&gt;四个选项；而&lt;code&gt;on&lt;/code&gt;则代表了基于哪个列实现表的合并，相当于 SQL 表连接中的连表条件，如果左右两表对应的列列名不同，可以用&lt;code&gt;left_on&lt;/code&gt;和&lt;code&gt;right_on&lt;/code&gt;参数取代&lt;code&gt;on&lt;/code&gt;参数分别进行指定。&lt;/p&gt;
&lt;p&gt;如果对上面的代码稍作修改，将&lt;code&gt;how&lt;/code&gt;参数修改为&lt;code&gt;left&lt;/code&gt;，大家可以思考一下代码执行的结果。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;pd.merge(dept_df, all_emp_df, how=&lt;span class=&#34;string&#34;&gt;&amp;#x27;left&amp;#x27;&lt;/span&gt;, on=&lt;span class=&#34;string&#34;&gt;&amp;#x27;dno&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;运行结果比之前的输出多出了如下所示的一行，这是因为&lt;code&gt;left&lt;/code&gt;代表左外连接，也就意味着左表&lt;code&gt;dept_df&lt;/code&gt;中的数据会被完整的查出来，但是在&lt;code&gt;all_emp_df&lt;/code&gt;中又没有编号为&lt;code&gt;40&lt;/code&gt; 部门的员工，所以对应的位置都被填入了空值。&lt;/p&gt;
&lt;figure class=&#34;highlight basic&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;symbol&#34;&gt;17 &lt;/span&gt; &lt;span class=&#34;number&#34;&gt;40&lt;/span&gt;  运维部  天津  NaN  NaN  NaN  NaN  NaN  NaN&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

 &lt;h2 id=&#34;Pandas的应用-1&#34;&gt;&lt;a href=&#34;#Pandas的应用-1&#34; class=&#34;headerlink&#34; title=&#34;Pandas的应用-1&#34;&gt;&lt;/a&gt;Pandas的应用-1&lt;/h2&gt;&lt;p&gt;Pandas是Wes McKinney在2008年开发的一个强大的&lt;strong&gt;分析结构化数据&lt;/strong&gt;的工具集。Pandas以NumPy为基础（数据表示和运算），提供了用于数据处理的函数和方法，对数据分析和数据挖掘提供了很好的支持；同时Pandas还可以跟数据可视化工具Matplotlib很好的整合在一起，非常轻松愉快的实现数据的可视化展示。&lt;/p&gt;
&lt;p&gt;Pandas核心的数据类型是&lt;code&gt;Series&lt;/code&gt;（数据系列）、&lt;code&gt;DataFrame&lt;/code&gt;（数据表&amp;#x2F;数据框），分别用于处理一维和二维的数据，除此之外还有一个名为&lt;code&gt;Index&lt;/code&gt;的类型及其子类型，它为&lt;code&gt;Series&lt;/code&gt;和&lt;code&gt;DataFrame&lt;/code&gt;提供了索引功能。日常工作中以&lt;code&gt;DataFrame&lt;/code&gt;使用最为广泛，因为二维的数据本质就是一个有行有列的表格（想一想Excel电子表格和关系型数据库中的二维表）。上述这些类型都提供了大量的处理数据的方法，数据分析师可以以此为基础实现对数据的各种常规处理。&lt;/p&gt;
&lt;h3 id=&#34;Series的应用&#34;&gt;&lt;a href=&#34;#Series的应用&#34; class=&#34;headerlink&#34; title=&#34;Series的应用&#34;&gt;&lt;/a&gt;Series的应用&lt;/h3&gt;&lt;p&gt;Pandas库中的&lt;code&gt;Series&lt;/code&gt;对象可以用来表示一维数据结构，跟数组非常类似，但是多了一些额外的功能。&lt;code&gt;Series&lt;/code&gt;的内部结构包含了两个数组，其中一个用来保存数据，另一个用来保存数据的索引。&lt;/p&gt;
&lt;h4 id=&#34;创建Series对象&#34;&gt;&lt;a href=&#34;#创建Series对象&#34; class=&#34;headerlink&#34; title=&#34;创建Series对象&#34;&gt;&lt;/a&gt;创建Series对象&lt;/h4&gt;&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;提示&lt;/strong&gt;：在执行下面的代码之前，请先导入&lt;code&gt;pandas&lt;/code&gt;以及相关的库文件，具体的做法可以参考上一章。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h5 id=&#34;方法1：通过列表或数组创建Series对象&#34;&gt;&lt;a href=&#34;#方法1：通过列表或数组创建Series对象&#34; class=&#34;headerlink&#34; title=&#34;方法1：通过列表或数组创建Series对象&#34;&gt;&lt;/a&gt;方法1：通过列表或数组创建Series对象&lt;/h5&gt;&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# data参数表示数据，index参数表示数据的索引（标签）&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 如果没有指定index属性，默认使用数字索引&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;ser1 = pd.Series(data=[&lt;span class=&#34;number&#34;&gt;320&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;180&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;300&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;405&lt;/span&gt;], index=[&lt;span class=&#34;string&#34;&gt;&amp;#x27;一季度&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;二季度&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;三季度&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;四季度&amp;#x27;&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;ser1&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight angelscript&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;一季度    &lt;span class=&#34;number&#34;&gt;320&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;二季度    &lt;span class=&#34;number&#34;&gt;180&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;三季度    &lt;span class=&#34;number&#34;&gt;300&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;四季度    &lt;span class=&#34;number&#34;&gt;405&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;dtype: &lt;span class=&#34;built_in&#34;&gt;int64&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h5 id=&#34;方法2：通过字典创建Series对象。&#34;&gt;&lt;a href=&#34;#方法2：通过字典创建Series对象。&#34; class=&#34;headerlink&#34; title=&#34;方法2：通过字典创建Series对象。&#34;&gt;&lt;/a&gt;方法2：通过字典创建Series对象。&lt;/h5&gt;&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 字典中的键就是数据的索引（标签），字典中的值就是数据&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;ser2 = pd.Series(&amp;#123;&lt;span class=&#34;string&#34;&gt;&amp;#x27;一季度&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;number&#34;&gt;320&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;二季度&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;number&#34;&gt;180&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;三季度&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;number&#34;&gt;300&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;四季度&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;number&#34;&gt;405&lt;/span&gt;&amp;#125;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;ser2&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight angelscript&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;一季度    &lt;span class=&#34;number&#34;&gt;320&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;二季度    &lt;span class=&#34;number&#34;&gt;180&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;三季度    &lt;span class=&#34;number&#34;&gt;300&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;四季度    &lt;span class=&#34;number&#34;&gt;405&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;dtype: &lt;span class=&#34;built_in&#34;&gt;int64&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h4 id=&#34;索引和切片&#34;&gt;&lt;a href=&#34;#索引和切片&#34; class=&#34;headerlink&#34; title=&#34;索引和切片&#34;&gt;&lt;/a&gt;索引和切片&lt;/h4&gt;&lt;p&gt;跟数组一样，Series对象也可以进行索引和切片操作，不同的是Series对象因为内部维护了一个保存索引的数组，所以除了可以使用整数索引通过位置检索数据外，还可以通过自己设置的索引标签获取对应的数据。&lt;/p&gt;
&lt;h5 id=&#34;使用整数索引&#34;&gt;&lt;a href=&#34;#使用整数索引&#34; class=&#34;headerlink&#34; title=&#34;使用整数索引&#34;&gt;&lt;/a&gt;使用整数索引&lt;/h5&gt;&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(ser2[&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;], ser[&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;], ser[&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;], ser[&lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;ser2[&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;], ser2[&lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;] = &lt;span class=&#34;number&#34;&gt;350&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;360&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(ser2)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight dns&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;320 180&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;300 405&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;一季度    &lt;span class=&#34;number&#34;&gt;350&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;二季度    &lt;span class=&#34;number&#34;&gt;180&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;三季度    &lt;span class=&#34;number&#34;&gt;300&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;四季度    &lt;span class=&#34;number&#34;&gt;360&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;dtype: int64&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;提示&lt;/strong&gt;：如果要使用负向索引，必须在创建&lt;code&gt;Series&lt;/code&gt;对象时通过&lt;code&gt;index&lt;/code&gt;属性指定非数值类型的标签。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h5 id=&#34;使用自定义的标签索引&#34;&gt;&lt;a href=&#34;#使用自定义的标签索引&#34; class=&#34;headerlink&#34; title=&#34;使用自定义的标签索引&#34;&gt;&lt;/a&gt;使用自定义的标签索引&lt;/h5&gt;&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(ser2[&lt;span class=&#34;string&#34;&gt;&amp;#x27;一季度&amp;#x27;&lt;/span&gt;], ser2[&lt;span class=&#34;string&#34;&gt;&amp;#x27;三季度&amp;#x27;&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;ser2[&lt;span class=&#34;string&#34;&gt;&amp;#x27;一季度&amp;#x27;&lt;/span&gt;] = &lt;span class=&#34;number&#34;&gt;380&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(ser2)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight angelscript&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;350&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;300&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;一季度    &lt;span class=&#34;number&#34;&gt;380&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;二季度    &lt;span class=&#34;number&#34;&gt;180&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;三季度    &lt;span class=&#34;number&#34;&gt;300&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;四季度    &lt;span class=&#34;number&#34;&gt;360&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;dtype: &lt;span class=&#34;built_in&#34;&gt;int64&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h5 id=&#34;切片操作&#34;&gt;&lt;a href=&#34;#切片操作&#34; class=&#34;headerlink&#34; title=&#34;切片操作&#34;&gt;&lt;/a&gt;切片操作&lt;/h5&gt;&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(ser2[&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;:&lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(ser2[&lt;span class=&#34;string&#34;&gt;&amp;#x27;二季度&amp;#x27;&lt;/span&gt;:&lt;span class=&#34;string&#34;&gt;&amp;#x27;四季度&amp;#x27;&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight angelscript&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;二季度    &lt;span class=&#34;number&#34;&gt;180&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;三季度    &lt;span class=&#34;number&#34;&gt;300&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;dtype: &lt;span class=&#34;built_in&#34;&gt;int64&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;二季度    &lt;span class=&#34;number&#34;&gt;500&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;三季度    &lt;span class=&#34;number&#34;&gt;500&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;四季度    &lt;span class=&#34;number&#34;&gt;520&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;dtype: &lt;span class=&#34;built_in&#34;&gt;int64&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;ser2[&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;:&lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;] = &lt;span class=&#34;number&#34;&gt;400&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;500&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;ser2&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight angelscript&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;一季度    &lt;span class=&#34;number&#34;&gt;380&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;二季度    &lt;span class=&#34;number&#34;&gt;400&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;三季度    &lt;span class=&#34;number&#34;&gt;500&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;四季度    &lt;span class=&#34;number&#34;&gt;360&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;dtype: &lt;span class=&#34;built_in&#34;&gt;int64&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h5 id=&#34;花式索引&#34;&gt;&lt;a href=&#34;#花式索引&#34; class=&#34;headerlink&#34; title=&#34;花式索引&#34;&gt;&lt;/a&gt;花式索引&lt;/h5&gt;&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(ser2[[&lt;span class=&#34;string&#34;&gt;&amp;#x27;二季度&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;四季度&amp;#x27;&lt;/span&gt;]])&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;ser2[[&lt;span class=&#34;string&#34;&gt;&amp;#x27;二季度&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;四季度&amp;#x27;&lt;/span&gt;]] = &lt;span class=&#34;number&#34;&gt;500&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;520&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(ser2)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight angelscript&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;二季度    &lt;span class=&#34;number&#34;&gt;400&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;四季度    &lt;span class=&#34;number&#34;&gt;360&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;dtype: &lt;span class=&#34;built_in&#34;&gt;int64&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;一季度    &lt;span class=&#34;number&#34;&gt;380&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;二季度    &lt;span class=&#34;number&#34;&gt;500&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;三季度    &lt;span class=&#34;number&#34;&gt;500&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;四季度    &lt;span class=&#34;number&#34;&gt;520&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;dtype: &lt;span class=&#34;built_in&#34;&gt;int64&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h5 id=&#34;布尔索引&#34;&gt;&lt;a href=&#34;#布尔索引&#34; class=&#34;headerlink&#34; title=&#34;布尔索引&#34;&gt;&lt;/a&gt;布尔索引&lt;/h5&gt;&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;ser2[ser2 &amp;gt;= &lt;span class=&#34;number&#34;&gt;500&lt;/span&gt;]&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight angelscript&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;二季度    &lt;span class=&#34;number&#34;&gt;500&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;三季度    &lt;span class=&#34;number&#34;&gt;500&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;四季度    &lt;span class=&#34;number&#34;&gt;520&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;dtype: &lt;span class=&#34;built_in&#34;&gt;int64&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;####属性和方法&lt;/p&gt;
&lt;p&gt;Series对象的常用属性如下表所示。&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;属性&lt;/th&gt;
&lt;th&gt;说明&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;&lt;code&gt;dtype&lt;/code&gt; &amp;#x2F; &lt;code&gt;dtypes&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;返回&lt;code&gt;Series&lt;/code&gt;对象的数据类型&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;hasnans&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;判断&lt;code&gt;Series&lt;/code&gt;对象中有没有空值&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;at&lt;/code&gt; &amp;#x2F; &lt;code&gt;iat&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;通过索引访问&lt;code&gt;Series&lt;/code&gt;对象中的单个值&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;loc&lt;/code&gt; &amp;#x2F; &lt;code&gt;iloc&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;通过一组索引访问&lt;code&gt;Series&lt;/code&gt;对象中的一组值&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;index&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;返回&lt;code&gt;Series&lt;/code&gt;对象的索引&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;is_monotonic&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;判断&lt;code&gt;Series&lt;/code&gt;对象中的数据是否单调&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;is_monotonic_increasing&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;判断&lt;code&gt;Series&lt;/code&gt;对象中的数据是否单调递增&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;is_monotonic_decreasing&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;判断&lt;code&gt;Series&lt;/code&gt;对象中的数据是否单调递减&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;is_unique&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;判断&lt;code&gt;Series&lt;/code&gt;对象中的数据是否独一无二&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;size&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;返回&lt;code&gt;Series&lt;/code&gt;对象中元素的个数&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;values&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;以&lt;code&gt;ndarray&lt;/code&gt;的方式返回&lt;code&gt;Series&lt;/code&gt;对象中的值&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;p&gt;&lt;code&gt;Series&lt;/code&gt;对象的方法很多，我们通过下面的代码为大家介绍一些常用的方法。&lt;/p&gt;
&lt;h5 id=&#34;统计相关的方法&#34;&gt;&lt;a href=&#34;#统计相关的方法&#34; class=&#34;headerlink&#34; title=&#34;统计相关的方法&#34;&gt;&lt;/a&gt;统计相关的方法&lt;/h5&gt;&lt;p&gt;&lt;code&gt;Series&lt;/code&gt;对象支持各种获取描述性统计信息的方法。&lt;/p&gt;
&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 求和&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(ser2.&lt;span class=&#34;built_in&#34;&gt;sum&lt;/span&gt;())&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 求均值&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(ser2.mean())&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 求最大&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(ser2.&lt;span class=&#34;built_in&#34;&gt;max&lt;/span&gt;())&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 求最小&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(ser2.&lt;span class=&#34;built_in&#34;&gt;min&lt;/span&gt;())&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 计数&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(ser2.count())&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 求标准差&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(ser2.std())&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 求方差&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(ser2.var())&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 求中位数&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(ser2.median())&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;&lt;code&gt;Series&lt;/code&gt;对象还有一个名为&lt;code&gt;describe()&lt;/code&gt;的方法，可以获得上述所有的描述性统计信息，如下所示。&lt;/p&gt;
&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;ser2.describe()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight apache&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;count&lt;/span&gt;      &lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;000000&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;mean&lt;/span&gt;     &lt;span class=&#34;number&#34;&gt;475&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;000000&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;std&lt;/span&gt;       &lt;span class=&#34;number&#34;&gt;64&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;031242&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;min&lt;/span&gt;      &lt;span class=&#34;number&#34;&gt;380&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;000000&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;25&lt;/span&gt;%      &lt;span class=&#34;number&#34;&gt;470&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;000000&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;50&lt;/span&gt;%      &lt;span class=&#34;number&#34;&gt;500&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;000000&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;75&lt;/span&gt;%      &lt;span class=&#34;number&#34;&gt;505&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;000000&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;max&lt;/span&gt;      &lt;span class=&#34;number&#34;&gt;520&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;000000&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;dtype&lt;/span&gt;: float64&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;提示&lt;/strong&gt;：因为&lt;code&gt;describe()&lt;/code&gt;返回的也是一个&lt;code&gt;Series&lt;/code&gt;对象，所以也可以用&lt;code&gt;ser2.describe()[&amp;#39;mean&amp;#39;]&lt;/code&gt;来获取平均值。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;如果&lt;code&gt;Series&lt;/code&gt;对象有重复的值，我们可以使用&lt;code&gt;unique()&lt;/code&gt;方法获得去重之后的&lt;code&gt;Series&lt;/code&gt;对象；可以使用&lt;code&gt;nunique()&lt;/code&gt;方法统计不重复值的数量；如果想要统计每个值重复的次数，可以使用&lt;code&gt;value_counts()&lt;/code&gt;方法，这个方法会返回一个&lt;code&gt;Series&lt;/code&gt;对象，它的索引就是原来的&lt;code&gt;Series&lt;/code&gt;对象中的值，而每个值出现的次数就是返回的&lt;code&gt;Series&lt;/code&gt;对象中的数据，在默认情况下会按照出现次数做降序排列。&lt;/p&gt;
&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;ser3 = pd.Series(data=[&lt;span class=&#34;string&#34;&gt;&amp;#x27;apple&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;banana&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;apple&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;pitaya&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;apple&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;pitaya&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;durian&amp;#x27;&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;ser3.value_counts()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight apache&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;apple&lt;/span&gt;     &lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;pitaya&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;durian&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;banana&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;dtype&lt;/span&gt;: int64&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;ser3.nunique()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h5 id=&#34;数据处理的方法&#34;&gt;&lt;a href=&#34;#数据处理的方法&#34; class=&#34;headerlink&#34; title=&#34;数据处理的方法&#34;&gt;&lt;/a&gt;数据处理的方法&lt;/h5&gt;&lt;p&gt;&lt;code&gt;Series&lt;/code&gt;对象的&lt;code&gt;isnull()&lt;/code&gt;和&lt;code&gt;notnull()&lt;/code&gt;方法可以用于空值的判断，代码如下所示。&lt;/p&gt;
&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;ser4 = pd.Series(data=[&lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;, np.NaN, &lt;span class=&#34;number&#34;&gt;30&lt;/span&gt;, np.NaN])&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;ser4.isnull()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight pgsql&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;    &lt;span class=&#34;keyword&#34;&gt;False&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;    &lt;span class=&#34;keyword&#34;&gt;False&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;     &lt;span class=&#34;keyword&#34;&gt;True&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;    &lt;span class=&#34;keyword&#34;&gt;False&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;     &lt;span class=&#34;keyword&#34;&gt;True&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;dtype: &lt;span class=&#34;type&#34;&gt;bool&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;ser4.notnull()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight pgsql&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;     &lt;span class=&#34;keyword&#34;&gt;True&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;     &lt;span class=&#34;keyword&#34;&gt;True&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;    &lt;span class=&#34;keyword&#34;&gt;False&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;     &lt;span class=&#34;keyword&#34;&gt;True&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;    &lt;span class=&#34;keyword&#34;&gt;False&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;dtype: &lt;span class=&#34;type&#34;&gt;bool&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;&lt;code&gt;Series&lt;/code&gt;对象的&lt;code&gt;dropna()&lt;/code&gt;和&lt;code&gt;fillna()&lt;/code&gt;方法分别用来删除空值和填充空值，具体的用法如下所示。&lt;/p&gt;
&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;ser4.dropna()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight apache&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;0&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;1&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;30&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;dtype&lt;/span&gt;: float64&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 将空值填充为40&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;ser4.fillna(value=&lt;span class=&#34;number&#34;&gt;40&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight apache&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;0&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;1&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;2&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;40&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;30&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;4&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;40&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;dtype&lt;/span&gt;: float64&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# backfill或bfill表示用后一个元素的值填充空值&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# ffill或pad表示用前一个元素的值填充空值&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;ser4.fillna(method=&lt;span class=&#34;string&#34;&gt;&amp;#x27;ffill&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight apache&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;0&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;1&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;2&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;30&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;4&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;30&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;dtype&lt;/span&gt;: float64&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;需要提醒大家注意的是，&lt;code&gt;dropna()&lt;/code&gt;和&lt;code&gt;fillna()&lt;/code&gt;方法都有一个名为&lt;code&gt;inplace&lt;/code&gt;的参数，它的默认值是&lt;code&gt;False&lt;/code&gt;，表示删除空值或填充空值不会修改原来的&lt;code&gt;Series&lt;/code&gt;对象，而是返回一个新的&lt;code&gt;Series&lt;/code&gt;对象来表示删除或填充空值后的数据系列，如果将&lt;code&gt;inplace&lt;/code&gt;参数的值修改为&lt;code&gt;True&lt;/code&gt;，那么删除或填充空值会就地操作，直接修改原来的&lt;code&gt;Series&lt;/code&gt;对象，那么方法的返回值是&lt;code&gt;None&lt;/code&gt;。后面我们会接触到的很多方法，包括&lt;code&gt;DataFrame&lt;/code&gt;对象的很多方法都会有这个参数，它们的意义跟这里是一样的。&lt;/p&gt;
&lt;p&gt;&lt;code&gt;Series&lt;/code&gt;对象的&lt;code&gt;mask()&lt;/code&gt;和&lt;code&gt;where()&lt;/code&gt;方法可以将满足或不满足条件的值进行替换，如下所示。&lt;/p&gt;
&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;ser5 = pd.Series(&lt;span class=&#34;built_in&#34;&gt;range&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;5&lt;/span&gt;))&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;ser5.where(ser5 &amp;gt; &lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight apache&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;0&lt;/span&gt;    NaN&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;1&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;2&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;4&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;dtype&lt;/span&gt;: float64&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;ser5.where(ser5 &amp;gt; &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight apache&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;0&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;1&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;2&lt;/span&gt;     &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3&lt;/span&gt;     &lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;4&lt;/span&gt;     &lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;dtype&lt;/span&gt;: int64&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;ser5.mask(ser5 &amp;gt; &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight apache&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;0&lt;/span&gt;     &lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;1&lt;/span&gt;     &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;2&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;3&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;4&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;dtype&lt;/span&gt;: int64&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;&lt;code&gt;Series&lt;/code&gt;对象的&lt;code&gt;duplicated()&lt;/code&gt;方法可以帮助我们找出重复的数据，而&lt;code&gt;drop_duplicates()&lt;/code&gt;方法可以帮我们删除重复数据。&lt;/p&gt;
&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;ser3.duplicated()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight pgsql&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;    &lt;span class=&#34;keyword&#34;&gt;False&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;    &lt;span class=&#34;keyword&#34;&gt;False&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;     &lt;span class=&#34;keyword&#34;&gt;True&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;    &lt;span class=&#34;keyword&#34;&gt;False&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;     &lt;span class=&#34;keyword&#34;&gt;True&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;5&lt;/span&gt;     &lt;span class=&#34;keyword&#34;&gt;True&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;6&lt;/span&gt;    &lt;span class=&#34;keyword&#34;&gt;False&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;dtype: &lt;span class=&#34;type&#34;&gt;bool&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;ser3.drop_duplicates()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight vbnet&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;     apple&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;    banana&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;    pitaya&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;6&lt;/span&gt;    durian&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;symbol&#34;&gt;dtype:&lt;/span&gt; &lt;span class=&#34;type&#34;&gt;object&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;&lt;code&gt;Series&lt;/code&gt;对象的&lt;code&gt;apply()&lt;/code&gt;和&lt;code&gt;map()&lt;/code&gt;方法非常重要，它们可以用于数据处理，把数据映射或转换成我们期望的样子，这个操作在数据分析的数据准备阶段非常重要。&lt;/p&gt;
&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;ser6 = pd.Series([&lt;span class=&#34;string&#34;&gt;&amp;#x27;cat&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;dog&amp;#x27;&lt;/span&gt;, np.nan, &lt;span class=&#34;string&#34;&gt;&amp;#x27;rabbit&amp;#x27;&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;ser6&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight pgsql&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;       cat&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;       dog&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;       &lt;span class=&#34;keyword&#34;&gt;NaN&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;    rabbit&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;dtype: &lt;span class=&#34;keyword&#34;&gt;object&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;ser6.&lt;span class=&#34;built_in&#34;&gt;map&lt;/span&gt;(&amp;#123;&lt;span class=&#34;string&#34;&gt;&amp;#x27;cat&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;kitten&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;dog&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;puppy&amp;#x27;&lt;/span&gt;&amp;#125;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight pgsql&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;    kitten&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;     puppy&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;       &lt;span class=&#34;keyword&#34;&gt;NaN&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;       &lt;span class=&#34;keyword&#34;&gt;NaN&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;dtype: &lt;span class=&#34;keyword&#34;&gt;object&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;ser6.&lt;span class=&#34;built_in&#34;&gt;map&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&amp;#x27;I am a &amp;#123;&amp;#125;&amp;#x27;&lt;/span&gt;.&lt;span class=&#34;built_in&#34;&gt;format&lt;/span&gt;, na_action=&lt;span class=&#34;string&#34;&gt;&amp;#x27;ignore&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight less&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;       &lt;span class=&#34;selector-tag&#34;&gt;I&lt;/span&gt; &lt;span class=&#34;selector-tag&#34;&gt;am&lt;/span&gt; &lt;span class=&#34;selector-tag&#34;&gt;a&lt;/span&gt; &lt;span class=&#34;selector-tag&#34;&gt;cat&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;       &lt;span class=&#34;selector-tag&#34;&gt;I&lt;/span&gt; &lt;span class=&#34;selector-tag&#34;&gt;am&lt;/span&gt; &lt;span class=&#34;selector-tag&#34;&gt;a&lt;/span&gt; &lt;span class=&#34;selector-tag&#34;&gt;dog&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;              &lt;span class=&#34;selector-tag&#34;&gt;NaN&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;    &lt;span class=&#34;selector-tag&#34;&gt;I&lt;/span&gt; &lt;span class=&#34;selector-tag&#34;&gt;am&lt;/span&gt; &lt;span class=&#34;selector-tag&#34;&gt;a&lt;/span&gt; &lt;span class=&#34;selector-tag&#34;&gt;rabbit&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;selector-tag&#34;&gt;dtype&lt;/span&gt;: &lt;span class=&#34;selector-tag&#34;&gt;object&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;ser7 = pd.Series([&lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;21&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;12&lt;/span&gt;],  index=[&lt;span class=&#34;string&#34;&gt;&amp;#x27;London&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;New York&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;Helsinki&amp;#x27;&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;ser7&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight apache&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;London&lt;/span&gt;      &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;New&lt;/span&gt; York    &lt;span class=&#34;number&#34;&gt;21&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;Helsinki&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;12&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;dtype&lt;/span&gt;: int64&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;ser7.apply(np.square)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight apache&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;London&lt;/span&gt;      &lt;span class=&#34;number&#34;&gt;400&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;New&lt;/span&gt; York    &lt;span class=&#34;number&#34;&gt;441&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;Helsinki&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;144&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;dtype&lt;/span&gt;: int64&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;ser7.apply(&lt;span class=&#34;keyword&#34;&gt;lambda&lt;/span&gt; x, value: x - value, args=(&lt;span class=&#34;number&#34;&gt;5&lt;/span&gt;, ))&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight apache&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;London&lt;/span&gt;      &lt;span class=&#34;number&#34;&gt;15&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;New&lt;/span&gt; York    &lt;span class=&#34;number&#34;&gt;16&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;Helsinki&lt;/span&gt;     &lt;span class=&#34;number&#34;&gt;7&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;dtype&lt;/span&gt;: int64&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h5 id=&#34;排序和取头部值的方法&#34;&gt;&lt;a href=&#34;#排序和取头部值的方法&#34; class=&#34;headerlink&#34; title=&#34;排序和取头部值的方法&#34;&gt;&lt;/a&gt;排序和取头部值的方法&lt;/h5&gt;&lt;p&gt;&lt;code&gt;Series&lt;/code&gt;对象的&lt;code&gt;sort_index()&lt;/code&gt;和&lt;code&gt;sort_values()&lt;/code&gt;方法可以用于对索引和数据的排序，排序方法有一个名为&lt;code&gt;ascending&lt;/code&gt;的布尔类型参数，该参数用于控制排序的结果是升序还是降序；而名为&lt;code&gt;kind&lt;/code&gt;的参数则用来控制排序使用的算法，默认使用了&lt;code&gt;quicksort&lt;/code&gt;，也可以选择&lt;code&gt;mergesort&lt;/code&gt;或&lt;code&gt;heapsort&lt;/code&gt;；如果存在空值，那么可以用&lt;code&gt;na_position&lt;/code&gt;参数空值放在最前还是最后，默认是&lt;code&gt;last&lt;/code&gt;，代码如下所示。&lt;/p&gt;
&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;ser8 = pd.Series(&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    data=[&lt;span class=&#34;number&#34;&gt;35&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;96&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;12&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;57&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;25&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;89&lt;/span&gt;], &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;index=[&lt;span class=&#34;string&#34;&gt;&amp;#x27;grape&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;banana&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;pitaya&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;apple&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;peach&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;orange&amp;#x27;&lt;/span&gt;]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 按值从小到大排序&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;ser8.sort_values()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight apache&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;pitaya&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;12&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;peach&lt;/span&gt;     &lt;span class=&#34;number&#34;&gt;25&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;grape&lt;/span&gt;     &lt;span class=&#34;number&#34;&gt;35&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;apple&lt;/span&gt;     &lt;span class=&#34;number&#34;&gt;57&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;orange&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;89&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;banana&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;96&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;dtype&lt;/span&gt;: int64&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 按索引从大到小排序&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;ser8.sort_index(ascending=&lt;span class=&#34;literal&#34;&gt;False&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight apache&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;pitaya&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;12&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;peach&lt;/span&gt;     &lt;span class=&#34;number&#34;&gt;25&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;orange&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;89&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;grape&lt;/span&gt;     &lt;span class=&#34;number&#34;&gt;35&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;banana&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;96&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;apple&lt;/span&gt;     &lt;span class=&#34;number&#34;&gt;57&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;dtype&lt;/span&gt;: int64&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;如果要从&lt;code&gt;Series&lt;/code&gt;对象中找出元素中最大或最小的“Top-N”，实际上是不需要对所有的值进行排序的，可以使用&lt;code&gt;nlargest()&lt;/code&gt;和&lt;code&gt;nsmallest()&lt;/code&gt;方法来完成，如下所示。&lt;/p&gt;
&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 值最大的3个&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;ser8.nlargest(&lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight apache&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;banana&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;96&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;orange&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;89&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;apple&lt;/span&gt;     &lt;span class=&#34;number&#34;&gt;57&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;dtype&lt;/span&gt;: int64&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 值最小的2个&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;ser8.nsmallest(&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight apache&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;pitaya&lt;/span&gt;    &lt;span class=&#34;number&#34;&gt;12&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;peach&lt;/span&gt;     &lt;span class=&#34;number&#34;&gt;25&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;dtype&lt;/span&gt;: int64&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h4 id=&#34;绘制图表&#34;&gt;&lt;a href=&#34;#绘制图表&#34; class=&#34;headerlink&#34; title=&#34;绘制图表&#34;&gt;&lt;/a&gt;绘制图表&lt;/h4&gt;&lt;p&gt;Series对象有一个名为&lt;code&gt;plot&lt;/code&gt;的方法可以用来生成图表，如果选择生成折线图、饼图、柱状图等，默认会使用Series对象的索引作为横坐标，使用Series对象的数据作为纵坐标。&lt;/p&gt;
&lt;p&gt;首先导入&lt;code&gt;matplotlib&lt;/code&gt;中&lt;code&gt;pyplot&lt;/code&gt;模块并进行必要的配置。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; matplotlib.pyplot &lt;span class=&#34;keyword&#34;&gt;as&lt;/span&gt; plt&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 配置支持中文的非衬线字体（默认的字体无法显示中文）&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.rcParams[&lt;span class=&#34;string&#34;&gt;&amp;#x27;font.sans-serif&amp;#x27;&lt;/span&gt;] = [&lt;span class=&#34;string&#34;&gt;&amp;#x27;SimHei&amp;#x27;&lt;/span&gt;, ]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 使用指定的中文字体时需要下面的配置来避免负号无法显示&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.rcParams[&lt;span class=&#34;string&#34;&gt;&amp;#x27;axes.unicode_minus&amp;#x27;&lt;/span&gt;] = &lt;span class=&#34;literal&#34;&gt;False&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;创建&lt;code&gt;Series&lt;/code&gt;对象并绘制对应的柱状图。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;ser9 = pd.Series(&amp;#123;&lt;span class=&#34;string&#34;&gt;&amp;#x27;一季度&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;number&#34;&gt;400&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;二季度&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;number&#34;&gt;520&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;三季度&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;number&#34;&gt;180&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;四季度&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;number&#34;&gt;380&lt;/span&gt;&amp;#125;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 通过Series对象的plot方法绘图（kind=&amp;#x27;bar&amp;#x27;表示绘制柱状图）&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;ser9.plot(kind=&lt;span class=&#34;string&#34;&gt;&amp;#x27;bar&amp;#x27;&lt;/span&gt;, color=[&lt;span class=&#34;string&#34;&gt;&amp;#x27;r&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;g&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;b&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;y&amp;#x27;&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# x轴的坐标旋转到0度（中文水平显示）&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.xticks(rotation=&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 在柱状图的柱子上绘制数字&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; i &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; &lt;span class=&#34;built_in&#34;&gt;range&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    plt.text(i, ser9[i] + &lt;span class=&#34;number&#34;&gt;5&lt;/span&gt;, ser9[i], ha=&lt;span class=&#34;string&#34;&gt;&amp;#x27;center&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 显示图像&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.show()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;&lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20220619171513.png&#34;&gt;&lt;/p&gt;
&lt;p&gt;绘制反映每个季度占比的饼图。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# autopct参数可以配置在饼图上显示每块饼的占比&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;ser9.plot(kind=&lt;span class=&#34;string&#34;&gt;&amp;#x27;pie&amp;#x27;&lt;/span&gt;, autopct=&lt;span class=&#34;string&#34;&gt;&amp;#x27;%.1f%%&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 设置y轴的标签（显示在饼图左侧的文字）&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.ylabel(&lt;span class=&#34;string&#34;&gt;&amp;#x27;各季度占比&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.show()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;&lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20220619171503.png&#34;&gt;&lt;/p&gt;

 &lt;h2 id=&#34;NumPy的应用-2&#34;&gt;&lt;a href=&#34;#NumPy的应用-2&#34; class=&#34;headerlink&#34; title=&#34;NumPy的应用-2&#34;&gt;&lt;/a&gt;NumPy的应用-2&lt;/h2&gt;&lt;h3 id=&#34;数组的运算&#34;&gt;&lt;a href=&#34;#数组的运算&#34; class=&#34;headerlink&#34; title=&#34;数组的运算&#34;&gt;&lt;/a&gt;数组的运算&lt;/h3&gt;&lt;p&gt;使用 NumPy 最为方便的是当需要对数组元素进行运算时，不用编写循环代码遍历每个元素，所有的运算都会自动的&lt;strong&gt;矢量化&lt;/strong&gt;（使用高效的、提前编译的底层代码来对数据序列进行数学操作）。简单的说就是，NumPy 中的数学运算和数学函数会自动作用于数组中的每个成员。&lt;/p&gt;
&lt;h4 id=&#34;数组跟标量的运算&#34;&gt;&lt;a href=&#34;#数组跟标量的运算&#34; class=&#34;headerlink&#34; title=&#34;数组跟标量的运算&#34;&gt;&lt;/a&gt;数组跟标量的运算&lt;/h4&gt;&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array35 = np.arange(&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(array35 + &lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(array35 * &lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight tap&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;[11&lt;span class=&#34;number&#34;&gt; 12 &lt;/span&gt;13&lt;span class=&#34;number&#34;&gt; 14 &lt;/span&gt;15&lt;span class=&#34;number&#34;&gt; 16 &lt;/span&gt;17&lt;span class=&#34;number&#34;&gt; 18 &lt;/span&gt;19]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;[10&lt;span class=&#34;number&#34;&gt; 20 &lt;/span&gt;30&lt;span class=&#34;number&#34;&gt; 40 &lt;/span&gt;50&lt;span class=&#34;number&#34;&gt; 60 &lt;/span&gt;70&lt;span class=&#34;number&#34;&gt; 80 &lt;/span&gt;90]&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h4 id=&#34;数组跟数组的运算&#34;&gt;&lt;a href=&#34;#数组跟数组的运算&#34; class=&#34;headerlink&#34; title=&#34;数组跟数组的运算&#34;&gt;&lt;/a&gt;数组跟数组的运算&lt;/h4&gt;&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array36 = np.array([&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(array35 + array36)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(array35 * array36)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(array35 ** array36)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight tap&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;[&lt;span class=&#34;number&#34;&gt; 2 &lt;/span&gt;&lt;span class=&#34;number&#34;&gt; 3 &lt;/span&gt;&lt;span class=&#34;number&#34;&gt; 4 &lt;/span&gt;&lt;span class=&#34;number&#34;&gt; 6 &lt;/span&gt;&lt;span class=&#34;number&#34;&gt; 7 &lt;/span&gt;&lt;span class=&#34;number&#34;&gt; 8 &lt;/span&gt;10&lt;span class=&#34;number&#34;&gt; 11 &lt;/span&gt;12]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;[&lt;span class=&#34;number&#34;&gt; 1 &lt;/span&gt;&lt;span class=&#34;number&#34;&gt; 2 &lt;/span&gt;&lt;span class=&#34;number&#34;&gt; 3 &lt;/span&gt;&lt;span class=&#34;number&#34;&gt; 8 &lt;/span&gt;10&lt;span class=&#34;number&#34;&gt; 12 &lt;/span&gt;21&lt;span class=&#34;number&#34;&gt; 24 &lt;/span&gt;27]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;[ &lt;span class=&#34;number&#34;&gt; 1 &lt;/span&gt; &lt;span class=&#34;number&#34;&gt; 2 &lt;/span&gt; &lt;span class=&#34;number&#34;&gt; 3 &lt;/span&gt;&lt;span class=&#34;number&#34;&gt; 16 &lt;/span&gt;&lt;span class=&#34;number&#34;&gt; 25 &lt;/span&gt;&lt;span class=&#34;number&#34;&gt; 36 &lt;/span&gt;343&lt;span class=&#34;number&#34;&gt; 512 &lt;/span&gt;729]&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h4 id=&#34;通用一元函数&#34;&gt;&lt;a href=&#34;#通用一元函数&#34; class=&#34;headerlink&#34; title=&#34;通用一元函数&#34;&gt;&lt;/a&gt;通用一元函数&lt;/h4&gt;&lt;p&gt;通用函数是对&lt;code&gt;ndarray&lt;/code&gt;中的数据执行元素级运算的函数。你可以将其看做普通函数（接收一个标量值作为参数，返回一个标量值）的矢量化包装器，如下所示。&lt;/p&gt;
&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(np.sqrt(array35))&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(np.log2(array35))&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight dns&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;[&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;.         &lt;span class=&#34;number&#34;&gt;1.41421356&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;1.73205081&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;.         &lt;span class=&#34;number&#34;&gt;2.23606798&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;2.44948974&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt; &lt;span class=&#34;number&#34;&gt;2.64575131&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;2.82842712&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;.        ]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;[&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;.         &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;.         &lt;span class=&#34;number&#34;&gt;1.5849625&lt;/span&gt;  &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;.         &lt;span class=&#34;number&#34;&gt;2.32192809&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;2.5849625&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt; &lt;span class=&#34;number&#34;&gt;2.80735492&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;.         &lt;span class=&#34;number&#34;&gt;3.169925&lt;/span&gt;  ]&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;&lt;strong&gt;表1：通用一元函数&lt;/strong&gt;&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;函数&lt;/th&gt;
&lt;th&gt;说明&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;&lt;code&gt;abs&lt;/code&gt; &amp;#x2F; &lt;code&gt;fabs&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;求绝对值的函数&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;sqrt&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;求平方根的函数，相当于&lt;code&gt;array ** 0.5 &lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;square&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;求平方的函数，相当于&lt;code&gt;array ** 2&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;exp&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;计算$e^x$的函数&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;log&lt;/code&gt; &amp;#x2F; &lt;code&gt;log10&lt;/code&gt; &amp;#x2F; &lt;code&gt;log2&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;对数函数（&lt;code&gt;e&lt;/code&gt;为底 &amp;#x2F; &lt;code&gt;10&lt;/code&gt;为底 &amp;#x2F; &lt;code&gt;2&lt;/code&gt;为底）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;sign&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;符号函数（&lt;code&gt;1&lt;/code&gt; - 正数；&lt;code&gt;0&lt;/code&gt; - 零；&lt;code&gt;-1&lt;/code&gt; - 负数）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;ceil&lt;/code&gt; &amp;#x2F; &lt;code&gt;floor&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;上取整 &amp;#x2F;  下取整&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;isnan&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;返回布尔数组，NaN对应&lt;code&gt;True&lt;/code&gt;，非NaN对应&lt;code&gt;False&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;isfinite&lt;/code&gt; &amp;#x2F; &lt;code&gt;isinf&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;判断数值是否为无穷大的函数&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;cos&lt;/code&gt; &amp;#x2F; &lt;code&gt;cosh&lt;/code&gt; &amp;#x2F; &lt;code&gt;sin&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;三角函数&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;sinh&lt;/code&gt; &amp;#x2F; &lt;code&gt;tan&lt;/code&gt; &amp;#x2F; &lt;code&gt;tanh&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;三角函数&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;arccos&lt;/code&gt; &amp;#x2F; &lt;code&gt;arccosh&lt;/code&gt; &amp;#x2F; &lt;code&gt;arcsin&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;反三角函数&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;arcsinh&lt;/code&gt; &amp;#x2F; &lt;code&gt;arctan&lt;/code&gt; &amp;#x2F; &lt;code&gt;arctanh&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;反三角函数&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;rint&lt;/code&gt; &amp;#x2F; &lt;code&gt;round&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;四舍五入函数&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;h4 id=&#34;通用二元函数&#34;&gt;&lt;a href=&#34;#通用二元函数&#34; class=&#34;headerlink&#34; title=&#34;通用二元函数&#34;&gt;&lt;/a&gt;通用二元函数&lt;/h4&gt;&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array37 = np.array([[&lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;5&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;6&lt;/span&gt;], [&lt;span class=&#34;number&#34;&gt;7&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;8&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;9&lt;/span&gt;]])&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;array38 = np.array([[&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;], [&lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;]])&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(array37 ** array38)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(np.power(array37, array38))&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight lua&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;[[  4  25 216]&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt; [343  64   9]]&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;[[  4  25 216]&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt; [343  64   9]]&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;&lt;strong&gt;表2：通用二元函数&lt;/strong&gt;&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;函数&lt;/th&gt;
&lt;th&gt;说明&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;&lt;code&gt;add(x, y)&lt;/code&gt; &amp;#x2F; &lt;code&gt;substract(x, y)&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;加法函数 &amp;#x2F; 减法函数&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;multiply(x, y)&lt;/code&gt; &amp;#x2F; &lt;code&gt;divide(x, y)&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;乘法函数 &amp;#x2F; 除法函数&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;floor_divide(x, y)&lt;/code&gt; &amp;#x2F; &lt;code&gt;mod(x, y)&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;整除函数 &amp;#x2F; 求模函数&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;allclose(x, y)&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;检查数组&lt;code&gt;x&lt;/code&gt;和&lt;code&gt;y&lt;/code&gt;元素是否几乎相等&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;power(x, y)&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;数组$x$的元素$x_i$和数组$y$的元素$y_i$，计算$x_i^{y_i}$&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;maximum(x, y)&lt;/code&gt; &amp;#x2F; &lt;code&gt;fmax(x, y)&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;两两比较元素获取最大值 &amp;#x2F; 获取最大值（忽略NaN）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;minimum(x, y)&lt;/code&gt; &amp;#x2F; &lt;code&gt;fmin(x, y)&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;两两比较元素获取最小值 &amp;#x2F; 获取最小值（忽略NaN）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;dot(x, y)&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;点积运算（数量积，通常记为$\cdots$，用于欧几里得空间（Euclidean space））&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;inner(x, y)&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;内积运算（内积的含义要高于点积，点积相当于是内积在欧几里得空间$$的特例，而内积可以推广到&lt;strong&gt;赋范向量空间&lt;/strong&gt;，只要它满足平行四边形法则即可）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;cross(x, y) &lt;/code&gt;&lt;/td&gt;
&lt;td&gt;叉积运算（向量积，通常记为$\times$，运算结果是一个向量）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;outer(x, y)&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;外积运算（张量积，通常记为$\bigotimes$，运算结果通常是一个矩阵）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;intersect1d(x, y)&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;计算&lt;code&gt;x&lt;/code&gt;和&lt;code&gt;y&lt;/code&gt;的交集，返回这些元素构成的有序数组&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;union1d(x, y)&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;计算&lt;code&gt;x&lt;/code&gt;和&lt;code&gt;y&lt;/code&gt;的并集，返回这些元素构成的有序数组&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;in1d(x, y)&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;返回由判断&lt;code&gt;x&lt;/code&gt; 的元素是否在&lt;code&gt;y&lt;/code&gt;中得到的布尔值构成的数组&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;setdiff1d(x, y)&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;计算&lt;code&gt;x&lt;/code&gt;和&lt;code&gt;y&lt;/code&gt;的差集，返回这些元素构成的数组&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;setxor1d(x, y)&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;计算&lt;code&gt;x&lt;/code&gt;和&lt;code&gt;y&lt;/code&gt;的对称差，返回这些元素构成的数组&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;补充说明&lt;/strong&gt;：在二维空间内，两个向量$\boldsymbol{A}&amp;#x3D;\begin{bmatrix} a_1 \ a_2 \end{bmatrix}$和$\boldsymbol{B}&amp;#x3D;\begin{bmatrix} b_1 \ b_2 \end{bmatrix}$的叉积是这样定义的：$\boldsymbol{A}\times \boldsymbol{B}&amp;#x3D;\begin{vmatrix} a_1 \quad a_2 \ b_1 \quad b_2 \end{vmatrix}&amp;#x3D;a_1b_2 - a_2b_1$，其中$\begin{vmatrix} a_1 \quad a_2 \ b_1 \quad b_2 \end{vmatrix}$称为行列式。但是一定要注意，叉积并不等同于行列式，行列式的运算结果是一个标量，而叉积运算的结果是一个向量。如果不明白，我们可以看看三维空间两个向量，$\boldsymbol{A}&amp;#x3D;\begin{bmatrix} a_1 \ a_2 \ a_3 \end{bmatrix}$和$\boldsymbol{B}&amp;#x3D;\begin{bmatrix} b_1 \ b_2 \ b_3 \end{bmatrix}$的叉积是$\left&amp;lt; \hat{i} \begin{vmatrix} a_2 \quad a_3 \ b_2 \quad b_3 \end{vmatrix}, -\hat{j} \begin{vmatrix} a_1 \quad a_3 \ b_1 \quad b_3 \end{vmatrix}, \hat{k} \begin{vmatrix} a_1 \quad a_2 \ b_1 \quad b_2 \end{vmatrix} \right&amp;gt;$，其中$\hat{i}, \hat{j}, \hat{k}$代表每个维度的单位向量。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h4 id=&#34;广播机制&#34;&gt;&lt;a href=&#34;#广播机制&#34; class=&#34;headerlink&#34; title=&#34;广播机制&#34;&gt;&lt;/a&gt;广播机制&lt;/h4&gt;&lt;p&gt;上面的例子中，两个二元运算的数组形状是完全相同的，我们再来研究一下，两个形状不同的数组是否可以直接做二元运算或使用二元函数进行运算，请看下面的例子。&lt;/p&gt;
&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array39 = np.array([[&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;], [&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;], [&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;], [&lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;]])&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;array40 = np.array([&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;array39 + array40&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight inform7&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array(&lt;span class=&#34;comment&#34;&gt;[&lt;span class=&#34;comment&#34;&gt;[1, 2, 3]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;       &lt;span class=&#34;comment&#34;&gt;[2, 3, 4]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;       &lt;span class=&#34;comment&#34;&gt;[3, 4, 5]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;       &lt;span class=&#34;comment&#34;&gt;[4, 5, 6]&lt;/span&gt;]&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array41 = np.array([[&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;], [&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;], [&lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;], [&lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;]])&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;array39 + array41&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight inform7&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array(&lt;span class=&#34;comment&#34;&gt;[&lt;span class=&#34;comment&#34;&gt;[1, 1, 1]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;       &lt;span class=&#34;comment&#34;&gt;[3, 3, 3]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;       &lt;span class=&#34;comment&#34;&gt;[5, 5, 5]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;       &lt;span class=&#34;comment&#34;&gt;[7, 7, 7]&lt;/span&gt;]&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;通过上面的例子，我们发现形状不同的数组仍然有机会进行二元运算，但也绝对不是任意的数组都可以进行二元运算。简单的说，只有两个数组后缘维度相同或者其中一个数组后缘维度为1时，广播机制会被触发，而通过广播机制如果能够使两个数组的形状一致，才能进行二元运算。所谓后缘维度，指的是数组&lt;code&gt;shape&lt;/code&gt;属性对应的元组中最后一个元素的值（从后往前数最后一个维度的值），例如，我们之前打开的图像对应的数组后缘维度为3，3行4列的二维数组后缘维度为4，而有5个元素的一维数组后缘维度为5。简单的说就是，后缘维度相同或者其中一个数组的后缘维度为1，就可以应用广播机制；而广播机制如果能够使得数组的形状一致，就满足了两个数组对应元素做运算的需求，如下图所示。&lt;/p&gt;
&lt;p&gt;&lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20211005115640.png&#34;&gt;&lt;/p&gt;
&lt;p&gt;&lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20211005115658.png&#34;&gt;&lt;/p&gt;
&lt;p&gt;&lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20211005115800.png&#34;&gt;&lt;/p&gt;
&lt;h3 id=&#34;其他常用函数&#34;&gt;&lt;a href=&#34;#其他常用函数&#34; class=&#34;headerlink&#34; title=&#34;其他常用函数&#34;&gt;&lt;/a&gt;其他常用函数&lt;/h3&gt;&lt;p&gt;除了上面讲到的函数外，NumPy 中还提供了很多用于处理数组的函数，&lt;code&gt;ndarray&lt;/code&gt;对象的很多方法也可以通过直接调用函数来实现，下表给出了一些常用的函数。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;表3：NumPy其他常用函数&lt;/strong&gt;&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;函数&lt;/th&gt;
&lt;th&gt;说明&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;&lt;code&gt;unique&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;去除数组重复元素，返回唯一元素构成的有序数组&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;copy&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;返回拷贝数组得到的数组&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;sort&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;返回数组元素排序后的拷贝&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;split&lt;/code&gt; &amp;#x2F; &lt;code&gt;hsplit&lt;/code&gt; &amp;#x2F; &lt;code&gt;vsplit&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;将数组拆成若干个子数组&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;stack&lt;/code&gt; &amp;#x2F; &lt;code&gt;hstack&lt;/code&gt; &amp;#x2F; &lt;code&gt;vstack&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;将多个数组堆叠成新数组&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;concatenate&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;沿着指定的轴连接多个数组构成新数组&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;append&lt;/code&gt; &amp;#x2F; &lt;code&gt;insert&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;向数组末尾追加元素 &amp;#x2F; 在数组指定位置插入元素&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;argwhere&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;找出数组中非0元素的位置&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;extract&lt;/code&gt; &amp;#x2F; &lt;code&gt;select&lt;/code&gt; &amp;#x2F; &lt;code&gt;where&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;按照指定的条件从数组中抽取或处理数组元素&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;flip&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;沿指定的轴翻转数组中的元素&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;fromiter&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;通过迭代器创建数组对象&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;fromregex&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;通过读取文件和正则表达式解析获取数据创建数组对象&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;repeat&lt;/code&gt; &amp;#x2F; &lt;code&gt;tile&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;通过对元素的重复来创建新数组&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;roll&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;沿指定轴对数组元素进行移位&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;resize&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;重新调整数组的大小&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;place&lt;/code&gt; &amp;#x2F; &lt;code&gt;put&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;将数组中满足条件的元素&amp;#x2F;指定的元素替换为指定的值&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;partition&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;用选定的元素对数组进行一次划分并返回划分后的数组&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;提示&lt;/strong&gt;：上面的&lt;code&gt;resize&lt;/code&gt;函数和&lt;code&gt;ndarray&lt;/code&gt;对象的&lt;code&gt;resize&lt;/code&gt;方法是有区别的，&lt;code&gt;resize&lt;/code&gt;函数在调整数组大小时会重复数组中的元素作为填补多出来的元素的值，而&lt;code&gt;ndarry&lt;/code&gt;对象的&lt;code&gt;resize&lt;/code&gt;方法是用0来填补多出来的元素。这些小细节不清楚暂时也不要紧，但是如果用到对应的功能了就要引起注意。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array42 = np.array([[&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;], [&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;], [&lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;]])&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;array43 = np.array([[&lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;], [&lt;span class=&#34;number&#34;&gt;5&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;5&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;5&lt;/span&gt;], [&lt;span class=&#34;number&#34;&gt;6&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;6&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;6&lt;/span&gt;]])&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;np.hstack((array42, array43))&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight lua&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array(&lt;span class=&#34;string&#34;&gt;[[1, 1, 1, 4, 4, 4],&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;       [2, 2, 2, 5, 5, 5],&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;       [3, 3, 3, 6, 6, 6]]&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;np.vstack((array42, array43))&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight inform7&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array(&lt;span class=&#34;comment&#34;&gt;[&lt;span class=&#34;comment&#34;&gt;[1, 1, 1]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;       &lt;span class=&#34;comment&#34;&gt;[2, 2, 2]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;       &lt;span class=&#34;comment&#34;&gt;[3, 3, 3]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;       &lt;span class=&#34;comment&#34;&gt;[4, 4, 4]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;       &lt;span class=&#34;comment&#34;&gt;[5, 5, 5]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;       &lt;span class=&#34;comment&#34;&gt;[6, 6, 6]&lt;/span&gt;]&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;np.concatenate((array42, array43))&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight inform7&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array(&lt;span class=&#34;comment&#34;&gt;[&lt;span class=&#34;comment&#34;&gt;[1, 1, 1]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;       &lt;span class=&#34;comment&#34;&gt;[2, 2, 2]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;       &lt;span class=&#34;comment&#34;&gt;[3, 3, 3]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;       &lt;span class=&#34;comment&#34;&gt;[4, 4, 4]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;       &lt;span class=&#34;comment&#34;&gt;[5, 5, 5]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;       &lt;span class=&#34;comment&#34;&gt;[6, 6, 6]&lt;/span&gt;]&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;np.concatenate((array42, array43), axis=&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight lua&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array(&lt;span class=&#34;string&#34;&gt;[[1, 1, 1, 4, 4, 4],&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;       [2, 2, 2, 5, 5, 5],&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;       [3, 3, 3, 6, 6, 6]]&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h3 id=&#34;矩阵运算&#34;&gt;&lt;a href=&#34;#矩阵运算&#34; class=&#34;headerlink&#34; title=&#34;矩阵运算&#34;&gt;&lt;/a&gt;矩阵运算&lt;/h3&gt;&lt;p&gt;NumPy 中提供了专门用于线性代数（linear algebra）的模块和表示矩阵的类型&lt;code&gt;matrix&lt;/code&gt;，当然我们通过二维数组也可以表示一个矩阵，官方并不推荐使用&lt;code&gt;matrix&lt;/code&gt;类而是建议使用二维数组，而且有可能在将来的版本中会移除&lt;code&gt;matrix&lt;/code&gt;类。无论如何，利用这些已经封装好的类和函数，我们可以轻松愉快的实现线性代数中很多的操作。&lt;/p&gt;
&lt;h4 id=&#34;线性代数快速回顾&#34;&gt;&lt;a href=&#34;#线性代数快速回顾&#34; class=&#34;headerlink&#34; title=&#34;线性代数快速回顾&#34;&gt;&lt;/a&gt;线性代数快速回顾&lt;/h4&gt;&lt;ol&gt;
&lt;li&gt;&lt;strong&gt;向量&lt;/strong&gt;也叫&lt;strong&gt;矢量&lt;/strong&gt;，是一个同时具有大小和方向，且满足平行四边形法则的几何对象。与向量相对的概念叫&lt;strong&gt;标量&lt;/strong&gt;或&lt;strong&gt;数量&lt;/strong&gt;，标量只有大小、绝大多数情况下没有方向。&lt;/li&gt;
&lt;li&gt;向量可以进行&lt;strong&gt;加&lt;/strong&gt;、&lt;strong&gt;减&lt;/strong&gt;、&lt;strong&gt;数乘&lt;/strong&gt;、&lt;strong&gt;点积&lt;/strong&gt;、&lt;strong&gt;叉积&lt;/strong&gt;等运算。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;行列式&lt;/strong&gt;由向量组成，它的性质可以由向量解释。&lt;/li&gt;
&lt;li&gt;行列式可以使用&lt;strong&gt;行列式公式&lt;/strong&gt;计算：$det(\boldsymbol{A})&amp;#x3D;\sum_{n!} \pm {a_{1\alpha}a_{2\beta} \cdots a_{n\omega}}$。&lt;/li&gt;
&lt;li&gt;高阶行列式可以用&lt;strong&gt;代数余子式&lt;/strong&gt;展开成多个低阶行列式，如：$det(\boldsymbol{A})&amp;#x3D;a_{11}C_{11}+a_{12}C_{12}+ \cdots +a_{1n}C_{1n}$。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;矩阵&lt;/strong&gt;是由一系列元素排成的矩形阵列，矩阵里的元素可以是数字、符号或数学公式。&lt;/li&gt;
&lt;li&gt;矩阵可以进行&lt;strong&gt;加法&lt;/strong&gt;、&lt;strong&gt;减法&lt;/strong&gt;、&lt;strong&gt;数乘&lt;/strong&gt;、&lt;strong&gt;乘法&lt;/strong&gt;、&lt;strong&gt;转置&lt;/strong&gt;等运算。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;逆矩阵&lt;/strong&gt;用$\boldsymbol{A^{-1}}$表示，$\boldsymbol{A}\boldsymbol{A^{-1}}&amp;#x3D;\boldsymbol{A^{-1}}\boldsymbol{A}&amp;#x3D;\boldsymbol{I}$；没有逆矩阵的方阵是&lt;strong&gt;奇异矩阵&lt;/strong&gt;。&lt;/li&gt;
&lt;li&gt;如果一个方阵是&lt;strong&gt;满秩矩阵&lt;/strong&gt;(矩阵的秩等于矩阵的阶数)，该方阵对应的线性方程有唯一解。&lt;/li&gt;
&lt;/ol&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;说明&lt;/strong&gt;：&lt;strong&gt;矩阵的秩&lt;/strong&gt;是指矩阵中线性无关的行&amp;#x2F;列向量的最大个数，同时也是矩阵对应的线性变换的像空间的维度。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h4 id=&#34;NumPy中矩阵相关函数&#34;&gt;&lt;a href=&#34;#NumPy中矩阵相关函数&#34; class=&#34;headerlink&#34; title=&#34;NumPy中矩阵相关函数&#34;&gt;&lt;/a&gt;NumPy中矩阵相关函数&lt;/h4&gt;&lt;ol&gt;
&lt;li&gt;&lt;p&gt;创建矩阵对象。&lt;/p&gt;
&lt;p&gt; 代码：&lt;/p&gt;
 &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# matrix构造函数可以传入类数组对象也可以传入字符串&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;m1 = np.matrix(&lt;span class=&#34;string&#34;&gt;&amp;#x27;1 2 3; 4 5 6&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;m1&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; 输出：&lt;/p&gt;
 &lt;figure class=&#34;highlight lua&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;matrix(&lt;span class=&#34;string&#34;&gt;[[1, 2, 3],&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;        [4, 5, 6]]&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; 代码：&lt;/p&gt;
 &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# asmatrix函数也可以写成mat函数，它们其实是同一个函数&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;m2 = np.asmatrix(np.array([[&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;], [&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;], [&lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;]]))&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;m2&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; 输出：&lt;/p&gt;
 &lt;figure class=&#34;highlight lua&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;matrix(&lt;span class=&#34;string&#34;&gt;[[1, 1],&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;        [2, 2],&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;        [3, 3]]&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; 代码：&lt;/p&gt;
 &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;m1 * m2&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; 输出：&lt;/p&gt;
 &lt;figure class=&#34;highlight lua&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;matrix(&lt;span class=&#34;string&#34;&gt;[[14, 14],&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;        [32, 32]]&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;说明&lt;/strong&gt;：注意&lt;code&gt;matrix&lt;/code&gt;对象和&lt;code&gt;ndarray&lt;/code&gt;对象乘法运算的差别，如果两个二维数组要做矩阵乘法运算，应该使用&lt;code&gt;@&lt;/code&gt;运算符或&lt;code&gt;matmul&lt;/code&gt;函数，而不是&lt;code&gt;*&lt;/code&gt;运算符。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;矩阵对象的属性。&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;属性&lt;/th&gt;
&lt;th&gt;说明&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;&lt;code&gt;A&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;获取矩阵对象对应的&lt;code&gt;ndarray&lt;/code&gt;对象&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;A1&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;获取矩阵对象对应的扁平化后的&lt;code&gt;ndarray&lt;/code&gt;对象&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;I&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;可逆矩阵的逆矩阵&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;T&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;矩阵的转置&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;H&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;矩阵的共轭转置&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;shape&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;矩阵的形状&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;size&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;矩阵元素的个数&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;矩阵对象的方法。&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;  矩阵对象的方法跟之前讲过的&lt;code&gt;ndarray&lt;/code&gt;数组对象的方法基本差不多，此处不再进行赘述。&lt;/p&gt;
&lt;h4 id=&#34;NumPy的线性代数模块&#34;&gt;&lt;a href=&#34;#NumPy的线性代数模块&#34; class=&#34;headerlink&#34; title=&#34;NumPy的线性代数模块&#34;&gt;&lt;/a&gt;NumPy的线性代数模块&lt;/h4&gt;&lt;p&gt;NumPy 的&lt;code&gt;linalg&lt;/code&gt;模块中有一组标准的矩阵分解运算以及诸如求逆和行列式之类的函数，它们跟 MATLAB 和 R 等语言所使用的是相同的行业标准线性代数库，下面的表格列出了&lt;code&gt;numpy&lt;/code&gt;以及&lt;code&gt;linalg&lt;/code&gt;模块中常用的跟线性代数相关的函数。&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;函数&lt;/th&gt;
&lt;th&gt;说明&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;&lt;code&gt;diag&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;以一维数组的形式返回方阵的对角线元素或将一维数组转换为方阵（非对角元素元素为0）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;vdot&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;向量的点积&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;dot&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;数组的点积&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;inner&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;数组的内积&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;outer&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;数组的叉积&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;trace&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;计算对角线元素的和&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;norm&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;求模（范数）运算&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;det&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;计算行列式的值（在方阵上计算会得到一个标量）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;matrix_rank&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;计算矩阵的秩&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;eig&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;计算矩阵的特征值（eigenvalue）和特征向量（eigenvector）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;inv&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;计算非奇异矩阵（$n$阶方阵）的逆矩阵&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;pinv&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;计算矩阵的摩尔-彭若斯（Moore-Penrose）广义逆&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;qr&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;QR分解（把矩阵分解成一个正交矩阵与一个上三角矩阵的积）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;svd&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;计算奇异值分解（singular value decomposition）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;solve&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;解线性方程组$\boldsymbol{A}\boldsymbol{x}&amp;#x3D;\boldsymbol{b}$，其中$\boldsymbol{A}$是一个方阵&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;lstsq&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;计算$\boldsymbol{A}\boldsymbol{x}&amp;#x3D;\boldsymbol{b}$的最小二乘解&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;p&gt;大家如果有兴趣可以用下面的代码验证上面的函数。&lt;/p&gt;
&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;m3 = np.array([[&lt;span class=&#34;number&#34;&gt;1.&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;2.&lt;/span&gt;], [&lt;span class=&#34;number&#34;&gt;3.&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;4.&lt;/span&gt;]])&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;np.linalg.inv(m3)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight lua&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array(&lt;span class=&#34;string&#34;&gt;[[-2. ,  1. ],&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;       [ 1.5, -0.5]]&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;m4 = np.array([[&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;5&lt;/span&gt;], [&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;6&lt;/span&gt;], [&lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;7&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;9&lt;/span&gt;]])&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;np.linalg.det(m4)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 解线性方程组ax=b&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 3*x1 + x2= 9，x1 + 2*x2 = 8&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;a = np.array([[&lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;,&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;], [&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;,&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;]])&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;b = np.array([&lt;span class=&#34;number&#34;&gt;9&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;8&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;np.linalg.solve(a, b)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight stylus&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;function&#34;&gt;&lt;span class=&#34;title&#34;&gt;array&lt;/span&gt;&lt;span class=&#34;params&#34;&gt;([&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;., &lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;.])&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

 &lt;h2 id=&#34;NumPy的应用-1&#34;&gt;&lt;a href=&#34;#NumPy的应用-1&#34; class=&#34;headerlink&#34; title=&#34;NumPy的应用-1&#34;&gt;&lt;/a&gt;NumPy的应用-1&lt;/h2&gt;&lt;p&gt;Numpy 是一个开源的 Python 科学计算库，&lt;strong&gt;用于快速处理任意维度的数组&lt;/strong&gt;。Numpy &lt;strong&gt;支持常见的数组和矩阵操作&lt;/strong&gt;，对于同样的数值计算任务，使用 NumPy 不仅代码要简洁的多，而且 NumPy 的性能远远优于原生 Python，基本是一个到两个数量级的差距，而且数据量越大，NumPy 的优势就越明显。&lt;/p&gt;
&lt;p&gt;Numpy 最为核心的数据类型是&lt;code&gt;ndarray&lt;/code&gt;，使用&lt;code&gt;ndarray&lt;/code&gt;可以处理一维、二维和多维数组，该对象相当于是一个快速而灵活的大数据容器。NumPy 底层代码使用 C 语言编写，解决了 GIL 的限制，&lt;code&gt;ndarray&lt;/code&gt;在存取数据的时候，数据与数据的地址都是连续的，这确保了可以进行高效率的批量操作，远远优于 Python 中的&lt;code&gt;list&lt;/code&gt;；另一方面&lt;code&gt;ndarray&lt;/code&gt;对象提供了更多的方法来处理数据，尤其是和统计相关的方法，这些方法也是 Python 原生的&lt;code&gt;list&lt;/code&gt;没有的。&lt;/p&gt;
&lt;h3 id=&#34;准备工作&#34;&gt;&lt;a href=&#34;#准备工作&#34; class=&#34;headerlink&#34; title=&#34;准备工作&#34;&gt;&lt;/a&gt;准备工作&lt;/h3&gt;&lt;ol&gt;
&lt;li&gt;&lt;p&gt;启动Notebook&lt;/p&gt;
 &lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;jupyter notebook&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;提示&lt;/strong&gt;：在启动Notebook之前，建议先安装好数据分析相关依赖项，包括之前提到的三大神器以及相关依赖项，包括：&lt;code&gt;numpy&lt;/code&gt;、&lt;code&gt;pandas&lt;/code&gt;、&lt;code&gt;matplotlib&lt;/code&gt;、&lt;code&gt;openpyxl&lt;/code&gt;等。如果使用Anaconda，则无需单独安装。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;导入&lt;/p&gt;
 &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; numpy &lt;span class=&#34;keyword&#34;&gt;as&lt;/span&gt; np&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; pandas &lt;span class=&#34;keyword&#34;&gt;as&lt;/span&gt; pd&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; matplotlib.pyplot &lt;span class=&#34;keyword&#34;&gt;as&lt;/span&gt; plt&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;说明&lt;/strong&gt;：如果已经启动了 Notebook 但尚未安装相关依赖库，例如尚未安装&lt;code&gt;numpy&lt;/code&gt;，可以在 Notebook 的单元格中输入&lt;code&gt;!pip install numpy&lt;/code&gt;并运行该单元格来安装 NumPy，也可以一次性安装多个三方库，需要在单元格中输入&lt;code&gt;%pip install numpy pandas matplotlib&lt;/code&gt;。注意上面的代码，我们不仅导入了NumPy，还将 pandas 和 matplotlib 库一并导入了。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;h3 id=&#34;创建数组对象&#34;&gt;&lt;a href=&#34;#创建数组对象&#34; class=&#34;headerlink&#34; title=&#34;创建数组对象&#34;&gt;&lt;/a&gt;创建数组对象&lt;/h3&gt;&lt;p&gt;创建&lt;code&gt;ndarray&lt;/code&gt;对象有很多种方法，下面就如何创建一维数组、二维数组和多维数组进行说明。&lt;/p&gt;
&lt;h4 id=&#34;一维数组&#34;&gt;&lt;a href=&#34;#一维数组&#34; class=&#34;headerlink&#34; title=&#34;一维数组&#34;&gt;&lt;/a&gt;一维数组&lt;/h4&gt;&lt;ul&gt;
&lt;li&gt;&lt;p&gt;方法一：使用&lt;code&gt;array&lt;/code&gt;函数，通过&lt;code&gt;list&lt;/code&gt;创建数组对象&lt;/p&gt;
&lt;p&gt;  代码：&lt;/p&gt;
  &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array1 = np.array([&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;5&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;array1&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;  输出：&lt;/p&gt;
  &lt;figure class=&#34;highlight apache&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;array&lt;/span&gt;([&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;5&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;方法二：使用&lt;code&gt;arange&lt;/code&gt;函数，指定取值范围创建数组对象&lt;/p&gt;
&lt;p&gt;  代码：&lt;/p&gt;
  &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array2 = np.arange(&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;array2&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;  输出：&lt;/p&gt;
  &lt;figure class=&#34;highlight apache&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;array&lt;/span&gt;([ &lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;,  &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;,  &lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;,  &lt;span class=&#34;number&#34;&gt;6&lt;/span&gt;,  &lt;span class=&#34;number&#34;&gt;8&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;12&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;14&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;16&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;18&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;方法三：使用&lt;code&gt;linspace&lt;/code&gt;函数，用指定范围均匀间隔的数字创建数组对象&lt;/p&gt;
&lt;p&gt;  代码：&lt;/p&gt;
  &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array3 = np.linspace(-&lt;span class=&#34;number&#34;&gt;5&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;5&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;101&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;array3&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;  输出：&lt;/p&gt;
  &lt;figure class=&#34;highlight subunit&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array([&lt;span class=&#34;string&#34;&gt;-5&lt;/span&gt;. , &lt;span class=&#34;string&#34;&gt;-4&lt;/span&gt;.9, &lt;span class=&#34;string&#34;&gt;-4&lt;/span&gt;.8, &lt;span class=&#34;string&#34;&gt;-4&lt;/span&gt;.7, &lt;span class=&#34;string&#34;&gt;-4&lt;/span&gt;.6, &lt;span class=&#34;string&#34;&gt;-4&lt;/span&gt;.5, &lt;span class=&#34;string&#34;&gt;-4&lt;/span&gt;.4, &lt;span class=&#34;string&#34;&gt;-4&lt;/span&gt;.3, &lt;span class=&#34;string&#34;&gt;-4&lt;/span&gt;.2, &lt;span class=&#34;string&#34;&gt;-4&lt;/span&gt;.1, &lt;span class=&#34;string&#34;&gt;-4&lt;/span&gt;. ,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;       &lt;span class=&#34;string&#34;&gt;-3&lt;/span&gt;.9, &lt;span class=&#34;string&#34;&gt;-3&lt;/span&gt;.8, &lt;span class=&#34;string&#34;&gt;-3&lt;/span&gt;.7, &lt;span class=&#34;string&#34;&gt;-3&lt;/span&gt;.6, &lt;span class=&#34;string&#34;&gt;-3&lt;/span&gt;.5, &lt;span class=&#34;string&#34;&gt;-3&lt;/span&gt;.4, &lt;span class=&#34;string&#34;&gt;-3&lt;/span&gt;.3, &lt;span class=&#34;string&#34;&gt;-3&lt;/span&gt;.2, &lt;span class=&#34;string&#34;&gt;-3&lt;/span&gt;.1, &lt;span class=&#34;string&#34;&gt;-3&lt;/span&gt;. , &lt;span class=&#34;string&#34;&gt;-2&lt;/span&gt;.9,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;       &lt;span class=&#34;string&#34;&gt;-2&lt;/span&gt;.8, &lt;span class=&#34;string&#34;&gt;-2&lt;/span&gt;.7, &lt;span class=&#34;string&#34;&gt;-2&lt;/span&gt;.6, &lt;span class=&#34;string&#34;&gt;-2&lt;/span&gt;.5, &lt;span class=&#34;string&#34;&gt;-2&lt;/span&gt;.4, &lt;span class=&#34;string&#34;&gt;-2&lt;/span&gt;.3, &lt;span class=&#34;string&#34;&gt;-2&lt;/span&gt;.2, &lt;span class=&#34;string&#34;&gt;-2&lt;/span&gt;.1, &lt;span class=&#34;string&#34;&gt;-2&lt;/span&gt;. , &lt;span class=&#34;string&#34;&gt;-1&lt;/span&gt;.9, &lt;span class=&#34;string&#34;&gt;-1&lt;/span&gt;.8,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;       &lt;span class=&#34;string&#34;&gt;-1&lt;/span&gt;.7, &lt;span class=&#34;string&#34;&gt;-1&lt;/span&gt;.6, &lt;span class=&#34;string&#34;&gt;-1&lt;/span&gt;.5, &lt;span class=&#34;string&#34;&gt;-1&lt;/span&gt;.4, &lt;span class=&#34;string&#34;&gt;-1&lt;/span&gt;.3, &lt;span class=&#34;string&#34;&gt;-1&lt;/span&gt;.2, &lt;span class=&#34;string&#34;&gt;-1&lt;/span&gt;.1, &lt;span class=&#34;string&#34;&gt;-1&lt;/span&gt;. , &lt;span class=&#34;string&#34;&gt;-0&lt;/span&gt;.9, &lt;span class=&#34;string&#34;&gt;-0&lt;/span&gt;.8, &lt;span class=&#34;string&#34;&gt;-0&lt;/span&gt;.7,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;       &lt;span class=&#34;string&#34;&gt;-0&lt;/span&gt;.6, &lt;span class=&#34;string&#34;&gt;-0&lt;/span&gt;.5, &lt;span class=&#34;string&#34;&gt;-0&lt;/span&gt;.4, &lt;span class=&#34;string&#34;&gt;-0&lt;/span&gt;.3, &lt;span class=&#34;string&#34;&gt;-0&lt;/span&gt;.2, &lt;span class=&#34;string&#34;&gt;-0&lt;/span&gt;.1,  0. ,  0.1,  0.2,  0.3,  0.4,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        0.5,  0.6,  0.7,  0.8,  0.9,  1. ,  1.1,  1.2,  1.3,  1.4,  1.5,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        1.6,  1.7,  1.8,  1.9,  2. ,  2.1,  2.2,  2.3,  2.4,  2.5,  2.6,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        2.7,  2.8,  2.9,  3. ,  3.1,  3.2,  3.3,  3.4,  3.5,  3.6,  3.7,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        3.8,  3.9,  4. ,  4.1,  4.2,  4.3,  4.4,  4.5,  4.6,  4.7,  4.8,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        4.9,  5. ])&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;方法四：使用&lt;code&gt;numpy.random&lt;/code&gt;模块的函数生成随机数创建数组对象&lt;/p&gt;
&lt;p&gt;  产生10个$[0, 1)$范围的随机小数，代码：&lt;/p&gt;
  &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array4 = np.random.rand(&lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;array4&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;  输出：&lt;/p&gt;
  &lt;figure class=&#34;highlight apache&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;array&lt;/span&gt;([&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;45556132&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;67871326&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;4552213&lt;/span&gt; , &lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;96671509&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;44086463&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;       &lt;span class=&#34;attribute&#34;&gt;0&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;72650875&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;79877188&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;12153022&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;24762739&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;6669852&lt;/span&gt; ])&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;  产生10个$[1, 100)$范围的随机整数，代码：&lt;/p&gt;
  &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array5 = np.random.randint(&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;100&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;array5&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;  输出：&lt;/p&gt;
  &lt;figure class=&#34;highlight apache&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;array&lt;/span&gt;([&lt;span class=&#34;number&#34;&gt;29&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;97&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;87&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;47&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;39&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;19&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;71&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;32&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;79&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;34&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;  产生20个$\mu&amp;#x3D;50$，$\sigma&amp;#x3D;10$的正态分布随机数，代码：&lt;/p&gt;
  &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array6 = np.random.normal(&lt;span class=&#34;number&#34;&gt;50&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;array6&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;  输出：&lt;/p&gt;
  &lt;figure class=&#34;highlight apache&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;array&lt;/span&gt;([&lt;span class=&#34;number&#34;&gt;55&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;04155586&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;46&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;43510797&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;28371158&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;62&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;67884053&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;61&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;23185964&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;       &lt;span class=&#34;attribute&#34;&gt;38&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;22682148&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;53&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;17126151&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;43&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;54741592&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;36&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;11268017&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;40&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;94086676&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;       &lt;span class=&#34;attribute&#34;&gt;63&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;27911699&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;46&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;92688903&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;37&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;1593374&lt;/span&gt; , &lt;span class=&#34;number&#34;&gt;67&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;06525656&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;67&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;47269463&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;       &lt;span class=&#34;attribute&#34;&gt;23&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;37925889&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;31&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;45312239&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;48&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;34532466&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;55&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;09180924&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;47&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;95702787&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;说明&lt;/strong&gt;：创建一维数组还有很多其他的方式，比如通过读取字符串、读取文件、解析正则表达式等方式，这里我们暂不讨论这些方式，有兴趣的读者可以自行研究。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h4 id=&#34;二维数组&#34;&gt;&lt;a href=&#34;#二维数组&#34; class=&#34;headerlink&#34; title=&#34;二维数组&#34;&gt;&lt;/a&gt;二维数组&lt;/h4&gt;&lt;ul&gt;
&lt;li&gt;&lt;p&gt;方法一：使用&lt;code&gt;array&lt;/code&gt;函数，通过嵌套的&lt;code&gt;list&lt;/code&gt;创建数组对象&lt;/p&gt;
&lt;p&gt;  代码：&lt;/p&gt;
  &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array7 = np.array([[&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;], [&lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;5&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;6&lt;/span&gt;]])&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;array7&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;  输出：&lt;/p&gt;
  &lt;figure class=&#34;highlight lua&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array(&lt;span class=&#34;string&#34;&gt;[[1, 2, 3],&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;       [4, 5, 6]]&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;方法二：使用&lt;code&gt;zeros&lt;/code&gt;、&lt;code&gt;ones&lt;/code&gt;、&lt;code&gt;full&lt;/code&gt;函数指定数组的形状创建数组对象&lt;/p&gt;
&lt;p&gt;  使用&lt;code&gt;zeros&lt;/code&gt;函数，代码：&lt;/p&gt;
  &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array8 = np.zeros((&lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;))&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;array8&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;  输出：&lt;/p&gt;
  &lt;figure class=&#34;highlight lua&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array(&lt;span class=&#34;string&#34;&gt;[[0., 0., 0., 0.],&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;       [0., 0., 0., 0.],&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;       [0., 0., 0., 0.]]&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;  使用&lt;code&gt;ones&lt;/code&gt;函数，代码：&lt;/p&gt;
  &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array9 = np.ones((&lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;))&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;array9&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;  输出：&lt;/p&gt;
  &lt;figure class=&#34;highlight lua&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array(&lt;span class=&#34;string&#34;&gt;[[1., 1., 1., 1.],&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;       [1., 1., 1., 1.],&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;       [1., 1., 1., 1.]]&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;  使用&lt;code&gt;full&lt;/code&gt;函数，代码：&lt;/p&gt;
  &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array10 = np.full((&lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;), &lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;array10&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;  输出：&lt;/p&gt;
  &lt;figure class=&#34;highlight lua&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array(&lt;span class=&#34;string&#34;&gt;[[10, 10, 10, 10],&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;       [10, 10, 10, 10],&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;       [10, 10, 10, 10]]&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;方法三：使用eye函数创建单位矩阵&lt;/p&gt;
&lt;p&gt;  代码：&lt;/p&gt;
  &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array11 = np.eye(&lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;array11&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;  输出：&lt;/p&gt;
  &lt;figure class=&#34;highlight inform7&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array(&lt;span class=&#34;comment&#34;&gt;[&lt;span class=&#34;comment&#34;&gt;[1., 0., 0., 0.]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;       &lt;span class=&#34;comment&#34;&gt;[0., 1., 0., 0.]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;       &lt;span class=&#34;comment&#34;&gt;[0., 0., 1., 0.]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;       &lt;span class=&#34;comment&#34;&gt;[0., 0., 0., 1.]&lt;/span&gt;]&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;方法四：通过&lt;code&gt;reshape&lt;/code&gt;将一维数组变成二维数组&lt;/p&gt;
&lt;p&gt;  代码：&lt;/p&gt;
  &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array12 = np.array([&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;5&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;6&lt;/span&gt;]).reshape(&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;array12&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;  输出：&lt;/p&gt;
  &lt;figure class=&#34;highlight lua&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array(&lt;span class=&#34;string&#34;&gt;[[1, 2, 3],&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;       [4, 5, 6]]&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;提示&lt;/strong&gt;：&lt;code&gt;reshape&lt;/code&gt;是&lt;code&gt;ndarray&lt;/code&gt;对象的一个方法，使用&lt;code&gt;reshape&lt;/code&gt;方法时需要确保调形后的数组元素个数与调形前数组元素个数保持一致，否则将会产生异常。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;方法五：通过&lt;code&gt;numpy.random&lt;/code&gt;模块的函数生成随机数创建数组对象&lt;/p&gt;
&lt;p&gt;  产生$[0, 1)$范围的随机小数构成的3行4列的二维数组，代码：&lt;/p&gt;
  &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array13 = np.random.rand(&lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;array13&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;  输出：&lt;/p&gt;
  &lt;figure class=&#34;highlight dns&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array([[&lt;span class=&#34;number&#34;&gt;0.54017809&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0.46797771&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0.78291445&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0.79501326&lt;/span&gt;],&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;       [&lt;span class=&#34;number&#34;&gt;0.93973783&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0.21434806&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0.03592874&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0.88838892&lt;/span&gt;],&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;       [&lt;span class=&#34;number&#34;&gt;0.84130479&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0.3566601&lt;/span&gt; , &lt;span class=&#34;number&#34;&gt;0.99935473&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0.26353598&lt;/span&gt;]])&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;  产生$[1, 100)$范围的随机整数构成的3行4列的二维数组，代码：&lt;/p&gt;
  &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array14 = np.random.randint(&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;100&lt;/span&gt;, (&lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;))&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;array14&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;  输出：&lt;/p&gt;
  &lt;figure class=&#34;highlight lua&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array(&lt;span class=&#34;string&#34;&gt;[[83, 30, 64, 53],&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;       [39, 92, 53, 43],&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;       [43, 48, 91, 72]]&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h4 id=&#34;多维数组&#34;&gt;&lt;a href=&#34;#多维数组&#34; class=&#34;headerlink&#34; title=&#34;多维数组&#34;&gt;&lt;/a&gt;多维数组&lt;/h4&gt;&lt;ul&gt;
&lt;li&gt;&lt;p&gt;使用随机的方式创建多维数组&lt;/p&gt;
&lt;p&gt;  代码：&lt;/p&gt;
  &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array15 = np.random.randint(&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;100&lt;/span&gt;, (&lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;5&lt;/span&gt;))&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;array15&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;  输出：&lt;/p&gt;
  &lt;figure class=&#34;highlight inform7&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array(&lt;span class=&#34;comment&#34;&gt;[&lt;span class=&#34;comment&#34;&gt;[&lt;span class=&#34;comment&#34;&gt;[94, 26, 49, 24, 43]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;&lt;span class=&#34;comment&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;[27, 27, 33, 98, 33]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;&lt;span class=&#34;comment&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;[13, 73,  6,  1, 77]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;&lt;span class=&#34;comment&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;[54, 32, 51, 86, 59]&lt;/span&gt;]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;       &lt;span class=&#34;comment&#34;&gt;[&lt;span class=&#34;comment&#34;&gt;[62, 75, 62, 29, 87]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;&lt;span class=&#34;comment&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;[90, 26,  6, 79, 41]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;&lt;span class=&#34;comment&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;[31, 15, 32, 56, 64]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;&lt;span class=&#34;comment&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;[37, 84, 61, 71, 71]&lt;/span&gt;]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;       &lt;span class=&#34;comment&#34;&gt;[&lt;span class=&#34;comment&#34;&gt;[45, 24, 78, 77, 41]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;&lt;span class=&#34;comment&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;[75, 37,  4, 74, 93]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;&lt;span class=&#34;comment&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;[ 1, 36, 36, 60, 43]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;&lt;span class=&#34;comment&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;[23, 84, 44, 89, 79]&lt;/span&gt;]&lt;/span&gt;]&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;将一维二维的数组调形为多维数组&lt;/p&gt;
&lt;p&gt;  一维数组调形为多维数组，代码：&lt;/p&gt;
  &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array16 = np.arange(&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;25&lt;/span&gt;).reshape((&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;))&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;array16&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;  输出：&lt;/p&gt;
  &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array([[[ &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;,  &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;,  &lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;,  &lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;],&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        [ &lt;span class=&#34;number&#34;&gt;5&lt;/span&gt;,  &lt;span class=&#34;number&#34;&gt;6&lt;/span&gt;,  &lt;span class=&#34;number&#34;&gt;7&lt;/span&gt;,  &lt;span class=&#34;number&#34;&gt;8&lt;/span&gt;],&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        [ &lt;span class=&#34;number&#34;&gt;9&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;11&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;12&lt;/span&gt;]],&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;       [[&lt;span class=&#34;number&#34;&gt;13&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;14&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;15&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;16&lt;/span&gt;],&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        [&lt;span class=&#34;number&#34;&gt;17&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;18&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;19&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;],&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        [&lt;span class=&#34;number&#34;&gt;21&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;22&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;23&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;24&lt;/span&gt;]]])&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;  二维数组调形为多维数组，代码：&lt;/p&gt;
  &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array17 = np.random.randint(&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;100&lt;/span&gt;, (&lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;6&lt;/span&gt;)).reshape((&lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;))&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;array17&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;  输出：&lt;/p&gt;
  &lt;figure class=&#34;highlight lua&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array(&lt;span class=&#34;string&#34;&gt;[[[60, 59],&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;        [31, 80],&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;        [54, 91]]&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;       &lt;span class=&#34;string&#34;&gt;[[67,  4],&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;        [ 4, 59],&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;        [47, 49]]&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;       &lt;span class=&#34;string&#34;&gt;[[16,  4],&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;        [ 5, 71],&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;        [80, 53]]&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;       &lt;span class=&#34;string&#34;&gt;[[38, 49],&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;        [70,  5],&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;        [76, 80]]&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;读取图片获得对应的三维数组&lt;/p&gt;
&lt;p&gt;  代码：&lt;/p&gt;
  &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array18 = plt.imread(&lt;span class=&#34;string&#34;&gt;&amp;#x27;guido.jpg&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;array18&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;  输出：&lt;/p&gt;
  &lt;figure class=&#34;highlight inform7&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array(&lt;span class=&#34;comment&#34;&gt;[&lt;span class=&#34;comment&#34;&gt;[&lt;span class=&#34;comment&#34;&gt;[ 36,  33,  28]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;&lt;span class=&#34;comment&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;[ 36,  33,  28]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;&lt;span class=&#34;comment&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;[ 36,  33,  28]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;&lt;span class=&#34;comment&#34;&gt;        ...,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;&lt;span class=&#34;comment&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;[ 32,  31,  29]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;&lt;span class=&#34;comment&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;[ 32,  31,  27]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;&lt;span class=&#34;comment&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;[ 31,  32,  26]&lt;/span&gt;]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;       &lt;span class=&#34;comment&#34;&gt;[&lt;span class=&#34;comment&#34;&gt;[ 37,  34,  29]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;&lt;span class=&#34;comment&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;[ 38,  35,  30]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;&lt;span class=&#34;comment&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;[ 38,  35,  30]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;&lt;span class=&#34;comment&#34;&gt;        ...,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;&lt;span class=&#34;comment&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;[ 31,  30,  28]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;&lt;span class=&#34;comment&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;[ 31,  30,  26]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;&lt;span class=&#34;comment&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;[ 30,  31,  25]&lt;/span&gt;]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;       &lt;span class=&#34;comment&#34;&gt;[&lt;span class=&#34;comment&#34;&gt;[ 38,  35,  30]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;&lt;span class=&#34;comment&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;[ 38,  35,  30]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;&lt;span class=&#34;comment&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;[ 38,  35,  30]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;&lt;span class=&#34;comment&#34;&gt;        ...,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;&lt;span class=&#34;comment&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;[ 30,  29,  27]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;&lt;span class=&#34;comment&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;[ 30,  29,  25]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;&lt;span class=&#34;comment&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;[ 29,  30,  25]&lt;/span&gt;]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;       ...,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;       &lt;span class=&#34;comment&#34;&gt;[&lt;span class=&#34;comment&#34;&gt;[239, 178, 123]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;&lt;span class=&#34;comment&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;[237, 176, 121]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;&lt;span class=&#34;comment&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;[235, 174, 119]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;&lt;span class=&#34;comment&#34;&gt;        ...,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;&lt;span class=&#34;comment&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;[ 78,  68,  56]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;&lt;span class=&#34;comment&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;[ 75,  67,  54]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;&lt;span class=&#34;comment&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;[ 73,  65,  52]&lt;/span&gt;]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;       &lt;span class=&#34;comment&#34;&gt;[&lt;span class=&#34;comment&#34;&gt;[238, 177, 120]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;&lt;span class=&#34;comment&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;[236, 175, 118]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;&lt;span class=&#34;comment&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;[234, 173, 116]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;&lt;span class=&#34;comment&#34;&gt;        ...,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;&lt;span class=&#34;comment&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;[ 82,  70,  58]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;&lt;span class=&#34;comment&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;[ 78,  68,  56]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;&lt;span class=&#34;comment&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;[ 75,  66,  51]&lt;/span&gt;]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;       &lt;span class=&#34;comment&#34;&gt;[&lt;span class=&#34;comment&#34;&gt;[238, 176, 119]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;&lt;span class=&#34;comment&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;[236, 175, 118]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;&lt;span class=&#34;comment&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;[234, 173, 116]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;&lt;span class=&#34;comment&#34;&gt;        ...,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;&lt;span class=&#34;comment&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;[ 84,  70,  61]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;&lt;span class=&#34;comment&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;[ 81,  69,  57]&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;&lt;span class=&#34;comment&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;[ 79,  67,  53]&lt;/span&gt;]&lt;/span&gt;]&lt;/span&gt;, dtype=uint8)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;说明&lt;/strong&gt;：上面的代码读取了当前路径下名为&lt;code&gt;guido.jpg&lt;/code&gt; 的图片文件，计算机系统中的图片通常由若干行若干列的像素点构成，而每个像素点又是由红绿蓝三原色构成的，所以能够用三维数组来表示。读取图片用到了&lt;code&gt;matplotlib&lt;/code&gt;库的&lt;code&gt;imread&lt;/code&gt;函数。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;数组对象的属性&#34;&gt;&lt;a href=&#34;#数组对象的属性&#34; class=&#34;headerlink&#34; title=&#34;数组对象的属性&#34;&gt;&lt;/a&gt;数组对象的属性&lt;/h3&gt;&lt;ol&gt;
&lt;li&gt;&lt;p&gt;&lt;code&gt;size&lt;/code&gt;属性：数组元素个数&lt;/p&gt;
&lt;p&gt; 代码：&lt;/p&gt;
 &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array19 = np.arange(&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;100&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;array20 = np.random.rand(&lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(array19.size, array20.size)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; 输出：&lt;/p&gt;
 &lt;figure class=&#34;highlight basic&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;symbol&#34;&gt;50 &lt;/span&gt;&lt;span class=&#34;number&#34;&gt;12&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;code&gt;shape&lt;/code&gt;属性：数组的形状&lt;/p&gt;
&lt;p&gt; 代码：&lt;/p&gt;
 &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(array19.shape, array20.shape)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; 输出：&lt;/p&gt;
 &lt;figure class=&#34;highlight clojure&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;(&lt;span class=&#34;number&#34;&gt;50&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;,&lt;/span&gt;) (&lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;code&gt;dtype&lt;/code&gt;属性：数组元素的数据类型&lt;/p&gt;
&lt;p&gt; 代码：&lt;/p&gt;
 &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(array19.dtype, array20.dtype)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; 输出：&lt;/p&gt;
 &lt;figure class=&#34;highlight angelscript&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;int64&lt;/span&gt; &lt;span class=&#34;built_in&#34;&gt;float&lt;/span&gt;64&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; &lt;code&gt;ndarray&lt;/code&gt;对象元素的数据类型可以参考如下所示的表格。&lt;/p&gt;
 &lt;img src=&#34;https://github.com/mypic/20211005114813.png&#34; width=&#34;85%&#34;&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;code&gt;ndim&lt;/code&gt;属性：数组的维度&lt;/p&gt;
&lt;p&gt; 代码：&lt;/p&gt;
 &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(array19.ndim, array20.ndim)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; 输出：&lt;/p&gt;
 &lt;figure class=&#34;highlight basic&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;symbol&#34;&gt;1 &lt;/span&gt;&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;code&gt;itemsize&lt;/code&gt;属性：数组单个元素占用内存空间的字节数&lt;/p&gt;
&lt;p&gt; 代码：&lt;/p&gt;
 &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array21 = np.arange(&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;100&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;, dtype=np.int8)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(array19.itemsize, array20.itemsize, array21.itemsize)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; 输出：&lt;/p&gt;
 &lt;figure class=&#34;highlight basic&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;symbol&#34;&gt;8 &lt;/span&gt;&lt;span class=&#34;number&#34;&gt;8&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;说明&lt;/strong&gt;：在使用&lt;code&gt;arange&lt;/code&gt;创建数组对象时，通过&lt;code&gt;dtype&lt;/code&gt;参数指定元素的数据类型。可以看出，&lt;code&gt;np.int8&lt;/code&gt;代表的是8位有符号整数，只占用1个字节的内存空间，取值范围是$[-128,127]$。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;code&gt;nbytes&lt;/code&gt;属性：数组所有元素占用内存空间的字节数&lt;/p&gt;
&lt;p&gt; 代码：&lt;/p&gt;
 &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(array19.nbytes, array20.nbytes, array21.nbytes)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; 输出：&lt;/p&gt;
 &lt;figure class=&#34;highlight basic&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;symbol&#34;&gt;400 &lt;/span&gt;&lt;span class=&#34;number&#34;&gt;96&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;50&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;code&gt;flat&lt;/code&gt;属性：数组（一维化之后）元素的迭代器&lt;/p&gt;
&lt;p&gt; 代码：&lt;/p&gt;
 &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; typing &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; Iterable&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(&lt;span class=&#34;built_in&#34;&gt;isinstance&lt;/span&gt;(array20.flat, np.ndarray), &lt;span class=&#34;built_in&#34;&gt;isinstance&lt;/span&gt;(array20.flat, Iterable))&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; 输出：&lt;/p&gt;
 &lt;figure class=&#34;highlight ada&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;literal&#34;&gt;False&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;True&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;code&gt;base&lt;/code&gt;属性：数组的基对象（如果数组共享了其他数组的内存空间）&lt;/p&gt;
&lt;p&gt; 代码：&lt;/p&gt;
 &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array22 = array19[:]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(array22.base &lt;span class=&#34;keyword&#34;&gt;is&lt;/span&gt; array19, array22.base &lt;span class=&#34;keyword&#34;&gt;is&lt;/span&gt; array21)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; 输出：&lt;/p&gt;
 &lt;figure class=&#34;highlight ada&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;literal&#34;&gt;True&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;False&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;说明&lt;/strong&gt;：上面的代码用到了数组的切片操作，它类似于 Python 中&lt;code&gt;list&lt;/code&gt;类型的切片，但在细节上又不完全相同，下面会专门讲解这个知识点。通过上面的代码可以发现，&lt;code&gt;ndarray&lt;/code&gt;切片后得到的新的数组对象跟原来的数组对象共享了内存中的数据，因此&lt;code&gt;array22&lt;/code&gt;的&lt;code&gt;base&lt;/code&gt;属性就是&lt;code&gt;array19&lt;/code&gt;对应的数组对象。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;h3 id=&#34;数组的索引和切片&#34;&gt;&lt;a href=&#34;#数组的索引和切片&#34; class=&#34;headerlink&#34; title=&#34;数组的索引和切片&#34;&gt;&lt;/a&gt;数组的索引和切片&lt;/h3&gt;&lt;p&gt;和 Python 中的列表类似，NumPy 的&lt;code&gt;ndarray&lt;/code&gt;对象可以进行索引和切片操作，通过索引可以获取或修改数组中的元素，通过切片可以取出数组的一部分。&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;&lt;p&gt;索引运算（普通索引）&lt;/p&gt;
&lt;p&gt; 一维数组，代码：&lt;/p&gt;
 &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array23 = np.array([&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;5&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;6&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;7&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;8&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;9&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(array23[&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;], array23[array23.size - &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(array23[-array23.size], array23[-&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; 输出：&lt;/p&gt;
 &lt;figure class=&#34;highlight basic&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;symbol&#34;&gt;1 &lt;/span&gt;&lt;span class=&#34;number&#34;&gt;9&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;symbol&#34;&gt;1 &lt;/span&gt;&lt;span class=&#34;number&#34;&gt;9&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; 二维数组，代码：&lt;/p&gt;
 &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array24 = np.array([[&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;], [&lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;5&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;6&lt;/span&gt;], [&lt;span class=&#34;number&#34;&gt;7&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;8&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;9&lt;/span&gt;]])&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(array24[&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(array24[&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;][&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;], array24[-&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;][-&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(array24[&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;][&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;], array24[&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; 输出：&lt;/p&gt;
 &lt;figure class=&#34;highlight tap&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;[7&lt;span class=&#34;number&#34;&gt; 8 &lt;/span&gt;9]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;1 9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5 5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;[[&lt;span class=&#34;number&#34;&gt; 1 &lt;/span&gt;&lt;span class=&#34;number&#34;&gt; 2 &lt;/span&gt; 3]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt; [&lt;span class=&#34;number&#34;&gt; 4 &lt;/span&gt;10  6]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt; [&lt;span class=&#34;number&#34;&gt; 7 &lt;/span&gt;&lt;span class=&#34;number&#34;&gt; 8 &lt;/span&gt; 9]]&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; 代码：&lt;/p&gt;
 &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array24[&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;][&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;] = &lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(array24)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;array24[&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;] = [&lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;11&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;12&lt;/span&gt;]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(array24)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; 输出：&lt;/p&gt;
 &lt;figure class=&#34;highlight lua&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;[[ 1  2  3]&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt; [ 4 10  6]&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt; [ 7  8  9]]&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;[[ 1  2  3]&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt; [10 11 12]&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt; [ 7  8  9]]&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;切片运算（切片索引）&lt;/p&gt;
&lt;p&gt; 切片是形如&lt;code&gt;[开始索引:结束索引:步长]&lt;/code&gt;的语法，通过指定&lt;strong&gt;开始索引&lt;/strong&gt;（默认值无穷小）、&lt;strong&gt;结束索引&lt;/strong&gt;（默认值无穷大）和&lt;strong&gt;步长&lt;/strong&gt;（默认值1），从数组中取出指定部分的元素并构成新的数组。因为开始索引、结束索引和步长都有默认值，所以它们都可以省略，如果不指定步长，第二个冒号也可以省略。一维数组的切片运算跟 Python 中的&lt;code&gt;list&lt;/code&gt;类型的切片非常类似，此处不再赘述，二维数组的切片可以参考下面的代码，相信非常容易理解。&lt;/p&gt;
&lt;p&gt; 代码：&lt;/p&gt;
 &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(array24[:&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;:])&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; 输出：&lt;/p&gt;
 &lt;figure class=&#34;highlight lua&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;[[2 3]&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt; [5 6]]&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; 代码：&lt;/p&gt;
 &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(array24[&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(array24[&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;, :])&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; 输出：&lt;/p&gt;
 &lt;figure class=&#34;highlight angelscript&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;[7 8 9]&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;[7 8 9]&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; 代码：&lt;/p&gt;
 &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(array24[&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;:, :])&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; 输出：&lt;/p&gt;
 &lt;figure class=&#34;highlight lua&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;[[7 8 9]]&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; 代码：&lt;/p&gt;
 &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(array24[:, :&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; 输出：&lt;/p&gt;
 &lt;figure class=&#34;highlight lua&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;[[1 2]&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt; [4 5]&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt; [7 8]]&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; 代码：&lt;/p&gt;
 &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(array24[&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, :&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(array24[&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;:&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;, :&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; 输出：&lt;/p&gt;
 &lt;figure class=&#34;highlight lua&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;[&lt;span class=&#34;number&#34;&gt;4&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;5&lt;/span&gt;]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;[[4 5]]&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; 代码：&lt;/p&gt;
 &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(array24[::&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;, ::&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; 输出：&lt;/p&gt;
 &lt;figure class=&#34;highlight lua&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;[[1 3]&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt; [7 9]]&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; 代码：&lt;/p&gt;
 &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(array24[::-&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;, ::-&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; 输出：&lt;/p&gt;
 &lt;figure class=&#34;highlight lua&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;[[9 7]&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt; [3 1]]&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; 关于数组的索引和切片运算，大家可以通过下面的两张图来增强印象，这两张图来自&lt;a href=&#34;https://item.jd.com/12398725.html&#34;&gt;《利用Python进行数据分析》&lt;/a&gt;一书，它是&lt;code&gt;pandas&lt;/code&gt;库的作者 Wes McKinney 撰写的 Python 数据分析领域的经典教科书，有兴趣的读者可以购买和阅读原书。&lt;/p&gt;
 &lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20211005115005.png&#34; style=&#34;zoom: 65%&#34;&gt;

 &lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20211005115041.png&#34; style=&#34;zoom:65%&#34;&gt;  
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;花式索引（fancy index）&lt;/p&gt;
&lt;p&gt; 花式索引（Fancy indexing）是指利用整数数组进行索引，这里所说的整数数组可以是 NumPy 的&lt;code&gt;ndarray&lt;/code&gt;，也可以是 Python 中&lt;code&gt;list&lt;/code&gt;、&lt;code&gt;tuple&lt;/code&gt;等可迭代类型，可以使用正向或负向索引。&lt;/p&gt;
&lt;p&gt; 一维数组的花式索引，代码：&lt;/p&gt;
 &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array25 = np.array([&lt;span class=&#34;number&#34;&gt;50&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;30&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;15&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;40&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;array25[[&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, -&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;]]&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; 输出：&lt;/p&gt;
 &lt;figure class=&#34;highlight apache&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;array&lt;/span&gt;([&lt;span class=&#34;number&#34;&gt;50&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;30&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;40&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; 二维数组的花式索引，代码：&lt;/p&gt;
 &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array26 = np.array([[&lt;span class=&#34;number&#34;&gt;30&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;], [&lt;span class=&#34;number&#34;&gt;40&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;60&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;50&lt;/span&gt;], [&lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;90&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;80&lt;/span&gt;]])&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 取二维数组的第1行和第3行&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;array26[[&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;]]&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; 输出：&lt;/p&gt;
 &lt;figure class=&#34;highlight lua&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array(&lt;span class=&#34;string&#34;&gt;[[30, 20, 10],&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;       [10, 90, 80]]&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; 代码：&lt;/p&gt;
 &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 取二维数组第1行第2列，第3行第3列的两个元素&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;array26[[&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;], [&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;]]&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; 输出：&lt;/p&gt;
 &lt;figure class=&#34;highlight stylus&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;function&#34;&gt;&lt;span class=&#34;title&#34;&gt;array&lt;/span&gt;&lt;span class=&#34;params&#34;&gt;([&lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;80&lt;/span&gt;])&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; 代码：&lt;/p&gt;
 &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 取二维数组第1行第2列，第3行第2列的两个元素&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;array26[[&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;], &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;]&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; 输出：&lt;/p&gt;
 &lt;figure class=&#34;highlight stylus&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;function&#34;&gt;&lt;span class=&#34;title&#34;&gt;array&lt;/span&gt;&lt;span class=&#34;params&#34;&gt;([&lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;90&lt;/span&gt;])&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;布尔索引&lt;/p&gt;
&lt;p&gt; 布尔索引就是通过布尔类型的数组对数组元素进行索引，布尔类型的数组可以手动构造，也可以通过关系运算来产生布尔类型的数组。&lt;/p&gt;
&lt;p&gt; 代码：&lt;/p&gt;
 &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array27 = np.arange(&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;array27[[&lt;span class=&#34;literal&#34;&gt;True&lt;/span&gt;, &lt;span class=&#34;literal&#34;&gt;False&lt;/span&gt;, &lt;span class=&#34;literal&#34;&gt;True&lt;/span&gt;, &lt;span class=&#34;literal&#34;&gt;True&lt;/span&gt;, &lt;span class=&#34;literal&#34;&gt;False&lt;/span&gt;, &lt;span class=&#34;literal&#34;&gt;False&lt;/span&gt;, &lt;span class=&#34;literal&#34;&gt;False&lt;/span&gt;, &lt;span class=&#34;literal&#34;&gt;False&lt;/span&gt;, &lt;span class=&#34;literal&#34;&gt;True&lt;/span&gt;]]&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; 输出：&lt;/p&gt;
 &lt;figure class=&#34;highlight apache&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;array&lt;/span&gt;([&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;9&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; 代码：&lt;/p&gt;
 &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array27 &amp;gt;= &lt;span class=&#34;number&#34;&gt;5&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; 输出：&lt;/p&gt;
 &lt;figure class=&#34;highlight ada&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;array&lt;/span&gt;([&lt;span class=&#34;literal&#34;&gt;False&lt;/span&gt;, &lt;span class=&#34;literal&#34;&gt;False&lt;/span&gt;, &lt;span class=&#34;literal&#34;&gt;False&lt;/span&gt;, &lt;span class=&#34;literal&#34;&gt;False&lt;/span&gt;,  &lt;span class=&#34;literal&#34;&gt;True&lt;/span&gt;,  &lt;span class=&#34;literal&#34;&gt;True&lt;/span&gt;,  &lt;span class=&#34;literal&#34;&gt;True&lt;/span&gt;,  &lt;span class=&#34;literal&#34;&gt;True&lt;/span&gt;,  &lt;span class=&#34;literal&#34;&gt;True&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; 代码：&lt;/p&gt;
 &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# ~运算符可以实现逻辑变反，看看运行结果跟上面有什么不同&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;~(array27 &amp;gt;= &lt;span class=&#34;number&#34;&gt;5&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;p&gt; 输出：&lt;/p&gt;
 &lt;figure class=&#34;highlight ada&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;array&lt;/span&gt;([ &lt;span class=&#34;literal&#34;&gt;True&lt;/span&gt;,  &lt;span class=&#34;literal&#34;&gt;True&lt;/span&gt;,  &lt;span class=&#34;literal&#34;&gt;True&lt;/span&gt;,  &lt;span class=&#34;literal&#34;&gt;True&lt;/span&gt;, &lt;span class=&#34;literal&#34;&gt;False&lt;/span&gt;, &lt;span class=&#34;literal&#34;&gt;False&lt;/span&gt;, &lt;span class=&#34;literal&#34;&gt;False&lt;/span&gt;, &lt;span class=&#34;literal&#34;&gt;False&lt;/span&gt;, &lt;span class=&#34;literal&#34;&gt;False&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;p&gt; 代码：&lt;/p&gt;
 &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array27[array27 &amp;gt;= &lt;span class=&#34;number&#34;&gt;5&lt;/span&gt;]&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;p&gt; 输出：&lt;/p&gt;
 &lt;figure class=&#34;highlight apache&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;array&lt;/span&gt;([&lt;span class=&#34;number&#34;&gt;5&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;6&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;7&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;8&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;9&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;/li&gt;
&lt;/ol&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;提示&lt;/strong&gt;：切片操作虽然创建了新的数组对象，但是新数组和原数组共享了数组中的数据，简单的说，如果通过新数组对象或原数组对象修改数组中的数据，其实修改的是同一块数据。花式索引和布尔索引也会创建新的数组对象，而且新数组复制了原数组的元素，新数组和原数组并不是共享数据的关系，这一点通过前面讲的数组的&lt;code&gt;base&lt;/code&gt;属性也可以了解到，在使用的时候要引起注意。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h4 id=&#34;案例：通过数组切片处理图像&#34;&gt;&lt;a href=&#34;#案例：通过数组切片处理图像&#34; class=&#34;headerlink&#34; title=&#34;案例：通过数组切片处理图像&#34;&gt;&lt;/a&gt;案例：通过数组切片处理图像&lt;/h4&gt;&lt;p&gt;学习基础知识总是比较枯燥且没有成就感的，所以我们还是来个案例为大家演示下上面学习的数组索引和切片操作到底有什么用。前面我们说到过，可以用三维数组来表示图像，那么通过图像对应的三维数组进行操作，就可以实现对图像的处理，如下所示。&lt;/p&gt;
&lt;p&gt;读入图片创建三维数组对象。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;guido_image = plt.imread(&lt;span class=&#34;string&#34;&gt;&amp;#x27;guido.jpg&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;plt.imshow(guido_image)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;对数组的0轴进行反向切片，实现图像的垂直翻转。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;plt.imshow(guido_image[::-&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;&lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20211005115228.png&#34;&gt;&lt;/p&gt;
&lt;p&gt;对数组的1轴进行反向切片，实现图像的水平翻转。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;plt.imshow(guido_image[:,::-&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;&lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20211005115242.png&#34;&gt;&lt;/p&gt;
&lt;p&gt;将 Guido 的头切出来。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;plt.imshow(guido_image[&lt;span class=&#34;number&#34;&gt;30&lt;/span&gt;:&lt;span class=&#34;number&#34;&gt;350&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;90&lt;/span&gt;:&lt;span class=&#34;number&#34;&gt;300&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;&lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20211005115305.png&#34;&gt;&lt;/p&gt;
&lt;h3 id=&#34;数组对象的方法&#34;&gt;&lt;a href=&#34;#数组对象的方法&#34; class=&#34;headerlink&#34; title=&#34;数组对象的方法&#34;&gt;&lt;/a&gt;数组对象的方法&lt;/h3&gt;&lt;h4 id=&#34;统计方法&#34;&gt;&lt;a href=&#34;#统计方法&#34; class=&#34;headerlink&#34; title=&#34;统计方法&#34;&gt;&lt;/a&gt;统计方法&lt;/h4&gt;&lt;p&gt;统计方法主要包括：&lt;code&gt;sum()&lt;/code&gt;、&lt;code&gt;mean()&lt;/code&gt;、&lt;code&gt;std()&lt;/code&gt;、&lt;code&gt;var()&lt;/code&gt;、&lt;code&gt;min()&lt;/code&gt;、&lt;code&gt;max()&lt;/code&gt;、&lt;code&gt;argmin()&lt;/code&gt;、&lt;code&gt;argmax()&lt;/code&gt;、&lt;code&gt;cumsum()&lt;/code&gt;等，分别用于对数组中的元素求和、求平均、求标准差、求方差、找最大、找最小、求累积和等，请参考下面的代码。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array28 = np.array([&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;5&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;5&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(array28.&lt;span class=&#34;built_in&#34;&gt;sum&lt;/span&gt;())&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(array28.mean())&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(array28.&lt;span class=&#34;built_in&#34;&gt;max&lt;/span&gt;())&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(array28.&lt;span class=&#34;built_in&#34;&gt;min&lt;/span&gt;())&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(array28.std())&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(array28.var())&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(array28.cumsum())&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight tap&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;30&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3.0&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;1.4142135623730951&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2.0&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;[&lt;span class=&#34;number&#34;&gt; 1 &lt;/span&gt;&lt;span class=&#34;number&#34;&gt; 3 &lt;/span&gt;&lt;span class=&#34;number&#34;&gt; 6 &lt;/span&gt;10&lt;span class=&#34;number&#34;&gt; 15 &lt;/span&gt;20&lt;span class=&#34;number&#34;&gt; 24 &lt;/span&gt;27&lt;span class=&#34;number&#34;&gt; 29 &lt;/span&gt;30]&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h4 id=&#34;其他方法&#34;&gt;&lt;a href=&#34;#其他方法&#34; class=&#34;headerlink&#34; title=&#34;其他方法&#34;&gt;&lt;/a&gt;其他方法&lt;/h4&gt;&lt;ol&gt;
&lt;li&gt;&lt;p&gt;&lt;code&gt;all()&lt;/code&gt; &amp;#x2F; &lt;code&gt;any()&lt;/code&gt;方法：判断数组是否所有元素都是&lt;code&gt;True&lt;/code&gt; &amp;#x2F; 判断数组是否有为&lt;code&gt;True&lt;/code&gt;的元素。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;code&gt;astype()&lt;/code&gt;方法：拷贝数组，并将数组中的元素转换为指定的类型。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;code&gt;dump()&lt;/code&gt;方法：保存数组到文件中，可以通过 NumPy 中的&lt;code&gt;load()&lt;/code&gt;函数从保存的文件中加载数据创建数组。&lt;/p&gt;
&lt;p&gt; 代码：&lt;/p&gt;
 &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array31.dump(&lt;span class=&#34;string&#34;&gt;&amp;#x27;array31-data&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;array32 = np.load(&lt;span class=&#34;string&#34;&gt;&amp;#x27;array31-data&amp;#x27;&lt;/span&gt;, allow_pickle=&lt;span class=&#34;literal&#34;&gt;True&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;array32&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; 输出：&lt;/p&gt;
 &lt;figure class=&#34;highlight lua&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array(&lt;span class=&#34;string&#34;&gt;[[1, 2],&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;       [3, 4],&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;       [5, 6]]&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;code&gt;fill()&lt;/code&gt;方法：向数组中填充指定的元素。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;code&gt;flatten()&lt;/code&gt;方法：将多维数组扁平化为一维数组。&lt;/p&gt;
&lt;p&gt; 代码：&lt;/p&gt;
 &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array32.flatten()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; 输出：&lt;/p&gt;
 &lt;figure class=&#34;highlight apache&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;array&lt;/span&gt;([&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;5&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;6&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;code&gt;nonzero()&lt;/code&gt;方法：返回非0元素的索引。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;code&gt;round()&lt;/code&gt;方法：对数组中的元素做四舍五入操作。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;code&gt;sort()&lt;/code&gt;方法：对数组进行就地排序。&lt;/p&gt;
&lt;p&gt; 代码：&lt;/p&gt;
 &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array33 = np.array([&lt;span class=&#34;number&#34;&gt;35&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;96&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;12&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;78&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;66&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;54&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;40&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;82&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;array33.sort()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;array33&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; 输出：&lt;/p&gt;
 &lt;figure class=&#34;highlight apache&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;array&lt;/span&gt;([&lt;span class=&#34;number&#34;&gt;12&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;35&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;40&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;54&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;66&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;78&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;82&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;96&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;code&gt;swapaxes()&lt;/code&gt;和&lt;code&gt;transpose()&lt;/code&gt;方法：交换数组指定的轴。&lt;/p&gt;
&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 指定需要交换的两个轴，顺序无所谓&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;array32.swapaxes(&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight lua&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array(&lt;span class=&#34;string&#34;&gt;[[1, 3, 5],&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;      [2, 4, 6]]&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 对于二维数组，transpose相当于实现了矩阵的转置&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;array32.transpose()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight lua&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;array(&lt;span class=&#34;string&#34;&gt;[[1, 3, 5],&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;      [2, 4, 6]]&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;code&gt;tolist()&lt;/code&gt;方法：将数组转成Python中的&lt;code&gt;list&lt;/code&gt;。&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;

 &lt;h2 id=&#34;环境准备&#34;&gt;&lt;a href=&#34;#环境准备&#34; class=&#34;headerlink&#34; title=&#34;环境准备&#34;&gt;&lt;/a&gt;环境准备&lt;/h2&gt;&lt;p&gt;如果希望快速开始使用 Python 处理数据科学相关的工作，建议大家直接安装 Anaconda，然后使用 Anaconda 中集成的 Notebook 或 JupyterLab 工具来编写代码。因为对于新手来说，先安装官方的 Python 解释器，再逐个安装工作中会使用到的三方库文件会比较麻烦，尤其是在 Windows 环境下，经常会因为构建工具或 DLL 文件的缺失导致安装失败，而一般新手也很难根据错误提示信息采取正确的解决措施，容易产生严重的挫败感。如果计算机上已经有 Python 解释器环境了，也可以直接使用 Python 的包管理工具 pip 安装 Jupyter，再根据实际工作的需要安装三方库，这种方式适合有一定经验的用户。&lt;/p&gt;
&lt;h3 id=&#34;安装和使用-Anaconda&#34;&gt;&lt;a href=&#34;#安装和使用-Anaconda&#34; class=&#34;headerlink&#34; title=&#34;安装和使用 Anaconda&#34;&gt;&lt;/a&gt;安装和使用 Anaconda&lt;/h3&gt;&lt;p&gt;对于个人用户来说，可以从 Anaconda 的&lt;a href=&#34;https://www.anaconda.com/&#34;&gt;官方网站&lt;/a&gt;下载它的“个人版（Individual Edition）”安装程序，安装完成后，你的计算机上不仅拥有了 Python 环境和 Spyder（类似于PyCharm的集成开发工具），还拥有了与数据科学工作相关的近200个工具包，包括我们上面提到 Python 数据分析三大神器。除此之外，Anaconda 还提供了一个名为 conda 的包管理工具，通过这个工具不仅可以管理 Python 的工具包，还可以用于创建运行 Python 程序的虚拟环境。&lt;/p&gt;
&lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20211005111417.png&#34;&gt;

&lt;p&gt;如上图所示，可以通过 Anaconda 官网提供的下载链接选择适合自己操作系统的安装程序，建议大家选择图形化的安装程序，下载完成后双击安装程序开始安装。安装过程基本使用默认设置即可，完成安装后，macOS 用户可以在“应用程序”或“Launchpad”中找到名为“Anaconda-Navigator”的应用程序，运行该程序可以看到如下所示的界面，我们可以在这里选择需要执行的操作。&lt;/p&gt;
&lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20211005111729.png&#34;&gt;

&lt;p&gt;对于 Windows 用户，建议按照安装向导的提示和推荐的选项来安装 Anaconda（除了安装路径，基本也没有什么需要选择的），安装完成后可以在“开始菜单”中找到“Anaconda3”。&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;温馨提示&lt;/strong&gt;：可以选择 Miniconda 作为 Anaconda 的替代品，Miniconda 只会安装 Python 解释器环境和一些必要的工具，其他的三方库由用户自行选择安装。其实我个人并不喜欢 Anaconda，因为它是给小白用户使用的，我们有了 Python 以后完全可以按照自己的意愿来安装需要的三方库。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h4 id=&#34;conda命令&#34;&gt;&lt;a href=&#34;#conda命令&#34; class=&#34;headerlink&#34; title=&#34;conda命令&#34;&gt;&lt;/a&gt;conda命令&lt;/h4&gt;&lt;p&gt;如果希望使用 conda 工具来管理依赖项或者创建项目的虚拟环境，可以在终端或命令行提示符中使用 conda 命令。Windows 用户可以在“开始菜单”中找到“Anaconda3”，然后点击“Anaconda Prompt”来启动支持 conda 的命令行提示符。macOS 用户建议直接使用“Anaconda-Navigator”中的“Environments”，通过可视化的方式对虚拟环境和依赖项进行管理。&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;&lt;p&gt;版本和帮助信息。&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;查看版本：&lt;code&gt;conda -V&lt;/code&gt;或&lt;code&gt;conda --version&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;获取帮助：&lt;code&gt;conda -h&lt;/code&gt;或&lt;code&gt;conda --help&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;相关信息：&lt;code&gt;conda list&lt;/code&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;虚拟环境相关。&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;显示所有虚拟环境：&lt;code&gt;conda env list&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;创建虚拟环境：&lt;code&gt;conda create --name venv&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;指定 Python 版本创建虚拟环境：&lt;code&gt;conda create --name venv python=3.7&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;指定 Python 版本创建虚拟环境并安装指定依赖项：&lt;code&gt;conda create --name venv python=3.7 numpy pandas&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;通过克隆现有虚拟环境的方式创建虚拟环境：&lt;code&gt;conda create --name venv2 --clone venv&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;分享虚拟环境并重定向到指定的文件中：&lt;code&gt;conda env export &amp;gt; environment.yml&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;通过分享的虚拟环境文件创建虚拟环境：&lt;code&gt;conda env create -f environment.yml&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;激活虚拟环境：&lt;code&gt;conda activate venv&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;退出虚拟环境：&lt;code&gt;conda deactivate&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;删除虚拟环境：&lt;code&gt;conda remove --name venv --all&lt;/code&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;说明&lt;/strong&gt;：上面的命令中，&lt;code&gt;venv&lt;/code&gt;和&lt;code&gt;venv2&lt;/code&gt;是虚拟环境文件夹的名字，可以将其替换为自己喜欢的名字，但是&lt;strong&gt;强烈建议&lt;/strong&gt;使用英文且不要出现空格或其他特殊字符。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;包（三方库或工具）管理。&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;查看已经安装的包：&lt;code&gt;conda list&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;搜索指定的包：&lt;code&gt;conda search matplotlib&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;安装指定的包：&lt;code&gt;conda install matplotlib&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;更新指定的包：&lt;code&gt;conda update matplotlib&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;移除指定的包：&lt;code&gt;conda remove matplotlib&lt;/code&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;说明&lt;/strong&gt;：在搜索、安装和更新软件包时，默认会连接到官方网站进行操作，如果觉得速度不给力，可以将默认的官方网站替换为国内的镜像网站，推荐使用清华大学的开源镜像网站。将默认源更换为国内镜像的命令是：&lt;code&gt;conda config --add channels https://mirrors.tuna.tsinghua.edu.cn/anaconda/pkgs/free/&lt;/code&gt;和&lt;code&gt;conda config --add channels https://mirrors.tuna.tsinghua.edu.cn/anaconda/pkgs/main&lt;/code&gt;。如果需要换回默认源，可以使用命令&lt;code&gt;conda config --remove-key channels&lt;/code&gt;。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;h3 id=&#34;使用Notebook&#34;&gt;&lt;a href=&#34;#使用Notebook&#34; class=&#34;headerlink&#34; title=&#34;使用Notebook&#34;&gt;&lt;/a&gt;使用Notebook&lt;/h3&gt;&lt;h4 id=&#34;安装和启动Notebook&#34;&gt;&lt;a href=&#34;#安装和启动Notebook&#34; class=&#34;headerlink&#34; title=&#34;安装和启动Notebook&#34;&gt;&lt;/a&gt;安装和启动Notebook&lt;/h4&gt;&lt;p&gt;如果已经安装了 Anaconda，macOS 用户可以按照上面所说的方式在“Anaconda-Navigator”中直接启动“Jupyter Notebook”（以下统一简称为 Notebook）。Windows 用户可以在“开始菜单”中找到 Anaconda 文件夹，接下来选择运行文件夹中的“Jupyter Notebook”就可以开始数据科学的探索之旅。&lt;/p&gt;
&lt;p&gt;对于安装了 Python 环境但是没有安装 Anaconda 的用户，可以用 Python 的包管理工具&lt;code&gt;pip&lt;/code&gt;来安装&lt;code&gt;jupyter&lt;/code&gt;，然后在终端（Windows 系统为命令行提示符）中运行&lt;code&gt;jupyter notebook&lt;/code&gt;命令来启动 Notebook，如下所示。&lt;/p&gt;
&lt;p&gt;安装 Notebook：&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;pip install jupyter&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;安装三大神器：&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;pip install numpy pandas matplotlib&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;运行 Notebook：&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;jupyter notebook&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;Notebook 是基于网页的用于交互计算的应用程序，可以用于代码开发、文档撰写、代码运行和结果展示。简单的说，你可以在网页中直接&lt;strong&gt;编写代码&lt;/strong&gt;和&lt;strong&gt;运行代码&lt;/strong&gt;，代码的运行结果也会直接在代码块下方进行展示。如在编写代码的过程中需要编写说明文档，可在同一个页面中使用 Markdown 格式进行编写，而且可以直接看到渲染后的效果。此外，Notebook 的设计初衷是提供一个能够支持多种编程语言的工作环境，目前它能够支持超过40种编程语言，包括 Python、R、Julia、Scala 等。&lt;/p&gt;
&lt;p&gt;首先，我们可以创建一个用于书写 Python 代码的 Notebook，如下图所示。&lt;/p&gt;
&lt;p&gt;&lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20211129131353.png&#34;&gt;&lt;/p&gt;
&lt;p&gt;接下来，我们就可以编写代码、撰写文档和运行程序啦，如下图所示。&lt;/p&gt;
&lt;p&gt;&lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20211005113900.png&#34;&gt;&lt;/p&gt;
&lt;h4 id=&#34;Notebook使用技巧&#34;&gt;&lt;a href=&#34;#Notebook使用技巧&#34; class=&#34;headerlink&#34; title=&#34;Notebook使用技巧&#34;&gt;&lt;/a&gt;Notebook使用技巧&lt;/h4&gt;&lt;p&gt;如果使用 Python 做工程化的项目开发，PyCharm 肯定是最好的选择，它提供了一个集成开发环境应该具有的所有功能，尤其是智能提示、代码补全、自动纠错这类功能会让开发人员感到非常舒服。如果使用 Python 做数据科学相关的工作，Notebook 并不比 PyCharm 逊色，在数据和图表展示方面 Notebook 更加优秀。这个工具的使用非常简单，大家可以看看 Notebook 菜单栏，相信理解起来不会有太多困难，在知乎上有一篇名为&lt;a href=&#34;https://zhuanlan.zhihu.com/p/32320214&#34;&gt;《最详尽使用指南：超快上手Jupyter Notebook》&lt;/a&gt;的文章，也可以帮助大家快速认识 Notebook。&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;说明&lt;/strong&gt;：&lt;a href=&#34;https://jupyter.org/&#34;&gt;Jupyter 官网&lt;/a&gt;上还有一个名为 JupyterLab 的工具，被称之为“Next-Generation Notebook”，用户界面较之 Notebook 更加友好，有兴趣的读者可以使用&lt;code&gt;pip install jupyterlab&lt;/code&gt;命令来安装这个工具，然后通过&lt;code&gt;jupyter lab&lt;/code&gt;来启动它。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;下面我为大家介绍一些 Notebook 的使用技巧，希望能够帮助大家提升工作效率。&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;&lt;p&gt;自动补全。在使用 Notebook 编写代码时，按&lt;code&gt;Tab&lt;/code&gt;键会获得代码提示。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;获得帮助。在使用 Notebook 时，如果希望了解一个对象（如变量、类、函数等）的相关信息或使用方式，可以在对象后面使用&lt;code&gt;?&lt;/code&gt;并运行代码， 窗口下方会显示出对应的信息，帮助我们了解该对象，如下所示。&lt;/p&gt;
&lt;p&gt; &lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20211005113848.png&#34;&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;搜索命名。如果只记得一个类或一个函数名字的一部分，可以使用通配符&lt;code&gt;*&lt;/code&gt;并配合&lt;code&gt;?&lt;/code&gt;进行搜索，如下所示。&lt;/p&gt;
&lt;p&gt; &lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20211005113836.png&#34;&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;调用命令。可以在 Notebook 中使用&lt;code&gt;!&lt;/code&gt;后面跟系统命令的方式来执行系统命令。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;魔法指令。Notebook 中有很多非常有趣且有用的魔法指令，例如可以使用&lt;code&gt;%timeit&lt;/code&gt;测试语句的执行时间，可以使用&lt;code&gt;%pwd&lt;/code&gt;查看当前工作目录等。如果想查看所有的魔法指令，可以使用&lt;code&gt;%lsmagic&lt;/code&gt;，如果了解魔法指令的用法，可以使用&lt;code&gt;%magic&lt;/code&gt;来查看，如下图所示。&lt;/p&gt;
&lt;p&gt; &lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20211005113825.png&#34;&gt;&lt;/p&gt;
&lt;p&gt; 常用的魔法指令有：&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;魔法指令&lt;/th&gt;
&lt;th&gt;功能说明&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;&lt;code&gt;%pwd&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;查看当前工作目录&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;%ls&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;列出当前或指定文件夹下的内容&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;%cat&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;查看指定文件的内容&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;%hist&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;查看输入历史&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;%matplotlib inline&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;设置在页面中嵌入matplotlib输出的统计图表&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;%config Inlinebackend.figure_format=&amp;#39;svg&amp;#39;&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;设置统计图表使用SVG格式（矢量图）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;%run&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;运行指定的程序&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;%load&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;加载指定的文件到单元格中&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;%quickref&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;显示IPython的快速参考&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;%timeit&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;多次运行代码并统计代码执行时间&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;%prun&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;用&lt;code&gt;cProfile.run&lt;/code&gt;运行代码并显示分析器的输出&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;%who&lt;/code&gt; &amp;#x2F; &lt;code&gt;%whos&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;显示命名空间中的变量&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;%xdel&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;删除一个对象并清理所有对它的引用&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;快捷键。Notebook 中的很多操作可以通过快捷键来实现，使用快捷键可以提升工作效率。Notebook 的快捷键又可以分为命令模式下的快捷键和编辑模式下的快捷键，所谓编辑模式就是处于输入代码或撰写文档状态的模式，在编辑模式下按&lt;code&gt;Esc&lt;/code&gt;可以回到命令模式，在命令模式下按&lt;code&gt;Enter&lt;/code&gt;可以进入编辑模式。&lt;/p&gt;
&lt;p&gt; 命令模式下的快捷键：&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;快捷键&lt;/th&gt;
&lt;th&gt;功能说明&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;&lt;code&gt;Alt&lt;/code&gt; + &lt;code&gt;Enter&lt;/code&gt;（&lt;code&gt;Option&lt;/code&gt; + &lt;code&gt;Enter&lt;/code&gt;）&lt;/td&gt;
&lt;td&gt;运行当前单元格并在下面插入新的单元格&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;Shift&lt;/code&gt; + &lt;code&gt;Enter&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;运行当前单元格并选中下方的单元格&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;Ctrl&lt;/code&gt; + &lt;code&gt;Enter&lt;/code&gt;（&lt;code&gt;Command&lt;/code&gt; + &lt;code&gt;Enter&lt;/code&gt;）&lt;/td&gt;
&lt;td&gt;运行当前单元格&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;j&lt;/code&gt; &amp;#x2F; &lt;code&gt;k&lt;/code&gt;、&lt;code&gt;Shift&lt;/code&gt; + &lt;code&gt;j&lt;/code&gt; &amp;#x2F; &lt;code&gt;Shift&lt;/code&gt; + &lt;code&gt;k&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;选中下方&amp;#x2F;上方单元格、连续选中下方&amp;#x2F;上方单元格&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;a&lt;/code&gt; &amp;#x2F; &lt;code&gt;b&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;在下方&amp;#x2F;上方插入新的单元格&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;c&lt;/code&gt; &amp;#x2F; &lt;code&gt;x&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;复制单元格 &amp;#x2F; 剪切单元格&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;v&lt;/code&gt; &amp;#x2F; &lt;code&gt;Shift&lt;/code&gt; + &lt;code&gt;v&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;在下方&amp;#x2F;上方粘贴单元格&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;dd&lt;/code&gt; &amp;#x2F; &lt;code&gt;z&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;删除单元格 &amp;#x2F; 恢复删除的单元格&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;l&lt;/code&gt; &amp;#x2F; &lt;code&gt;Shift&lt;/code&gt; + &lt;code&gt;l&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;显示或隐藏当前&amp;#x2F;所有单元格行号&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;ii&lt;/code&gt; &amp;#x2F; &lt;code&gt;00&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;中断&amp;#x2F;重启Notebook内核&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;Space&lt;/code&gt; &amp;#x2F; &lt;code&gt;Shift&lt;/code&gt; + &lt;code&gt;Space&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;向下&amp;#x2F;向上滚动页面&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;p&gt; 编辑模式下的快捷键：&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;快捷键&lt;/th&gt;
&lt;th&gt;功能说明&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;&lt;code&gt;Shift&lt;/code&gt; + &lt;code&gt;Tab&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;获得提示信息&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;Ctrl&lt;/code&gt; + &lt;code&gt;]&lt;/code&gt;（&lt;code&gt;Command&lt;/code&gt; + &lt;code&gt;]&lt;/code&gt;）&amp;#x2F; &lt;code&gt;Ctrl&lt;/code&gt; + &lt;code&gt;[&lt;/code&gt;（&lt;code&gt;Command&lt;/code&gt; + &lt;code&gt;[&lt;/code&gt;）&lt;/td&gt;
&lt;td&gt;增加&amp;#x2F;减少缩进&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;Alt&lt;/code&gt; + &lt;code&gt;Enter&lt;/code&gt;（&lt;code&gt;Option&lt;/code&gt; + &lt;code&gt;Enter&lt;/code&gt;）&lt;/td&gt;
&lt;td&gt;运行当前单元格并在下面插入新的单元格&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;Shift&lt;/code&gt; + &lt;code&gt;Enter&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;运行当前单元格并选中下方的单元格&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;Ctrl&lt;/code&gt; + &lt;code&gt;Enter&lt;/code&gt;（&lt;code&gt;Command&lt;/code&gt; + &lt;code&gt;Enter&lt;/code&gt;）&lt;/td&gt;
&lt;td&gt;运行当前单元格&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;Ctrl&lt;/code&gt; + &lt;code&gt;Left&lt;/code&gt; &amp;#x2F; &lt;code&gt;Right&lt;/code&gt;（&lt;code&gt;Command&lt;/code&gt; + &lt;code&gt;Left&lt;/code&gt; &amp;#x2F; &lt;code&gt;Right&lt;/code&gt;）&lt;/td&gt;
&lt;td&gt;光标移到行首&amp;#x2F;行尾&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;Ctrl&lt;/code&gt; + &lt;code&gt;Up&lt;/code&gt; &amp;#x2F; &lt;code&gt;Down&lt;/code&gt;（&lt;code&gt;Command&lt;/code&gt; + &lt;code&gt;Up&lt;/code&gt; &amp;#x2F; &lt;code&gt;Down&lt;/code&gt;）&lt;/td&gt;
&lt;td&gt;光标移动代码开头&amp;#x2F;结尾处&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;Up&lt;/code&gt; &amp;#x2F; &lt;code&gt;Down&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;光标上移&amp;#x2F;下移一行或移到上&amp;#x2F;下一个单元格&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;温馨提示&lt;/strong&gt;：如果记不住这些快捷键也没有关系，在命令模式下按&lt;code&gt;h&lt;/code&gt;键可以打开 Notebook 的帮助系统，马上就可以看到快捷键的设置，而且可以根据实际的需要重新编辑快捷键，如下图所示。&lt;/p&gt;
&lt;p&gt;&lt;img src=&#34;https://github.com/jackfrued/mypic/raw/master/20211005113812.png&#34;&gt;&lt;/p&gt;
&lt;/blockquote&gt;
&lt;/li&gt;
&lt;/ol&gt;

 &lt;h2 id=&#34;数据分析概述&#34;&gt;&lt;a href=&#34;#数据分析概述&#34; class=&#34;headerlink&#34; title=&#34;数据分析概述&#34;&gt;&lt;/a&gt;数据分析概述&lt;/h2&gt;&lt;p&gt;当今世界对信息技术的依赖程度在不断加深，每天都会有大量的数据产生，我们经常会感到数据越来越多，但是要从中发现有价值的信息却越来越难。这里所说的信息，可以理解为对数据集处理之后的结果，是从数据集中提炼出的可用于其他场合的结论性的东西，而&lt;strong&gt;从原始数据中抽取出有价值的信息&lt;/strong&gt;的这个过程我们就称之为&lt;strong&gt;数据分析&lt;/strong&gt;，它是数据科学工作的一部分。&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;定义：&lt;strong&gt;数据分析是有针对性的收集、加工、整理数据并采用统计、挖掘等技术对数据进行分析和解释的科学和艺术&lt;/strong&gt;。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h3 id=&#34;数据分析师的职责和技能栈&#34;&gt;&lt;a href=&#34;#数据分析师的职责和技能栈&#34; class=&#34;headerlink&#34; title=&#34;数据分析师的职责和技能栈&#34;&gt;&lt;/a&gt;数据分析师的职责和技能栈&lt;/h3&gt;&lt;p&gt;HR在发布招聘需求时，通常将数据工程、数据分析、数据挖掘等岗位都统称为数据分析岗位，但是根据工作性质的不同，又可以分为偏工程的&lt;strong&gt;数据治理方向&lt;/strong&gt;、偏业务的&lt;strong&gt;数据分析方向&lt;/strong&gt;、偏算法的&lt;strong&gt;数据挖掘方向&lt;/strong&gt;、偏开发的&lt;strong&gt;数据开发方向&lt;/strong&gt;、偏产品的&lt;strong&gt;数据产品经理&lt;/strong&gt;。我们通常所说的数据分析师主要是指&lt;strong&gt;业务数据分析师&lt;/strong&gt;，很多数据分析师的职业生涯都是从这个岗位开始的，而且这个岗位也是招聘数量最多的岗位。业务数据分析师在公司通常不属于研发部门而属于运营部门，所以这个岗位也称为&lt;strong&gt;数据运营&lt;/strong&gt;或&lt;strong&gt;商业分析&lt;/strong&gt;，这类人员通常也被称为“BI工程师”。通常招聘信息对这个岗位的描述（JD）是：&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;负责相关报表的输出。&lt;/li&gt;
&lt;li&gt;建立和优化指标体系。&lt;/li&gt;
&lt;li&gt;监控数据波动和异常，找出问题。&lt;/li&gt;
&lt;li&gt;优化和驱动业务，推动数字化运营。&lt;/li&gt;
&lt;li&gt;找出潜在的市场和产品的上升空间。&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;根据上面的描述，作为业务数据分析师，我们的工作不是给领导一个简单浅显的结论，而是结合公司的业务，完成&lt;strong&gt;监控数据&lt;/strong&gt;、&lt;strong&gt;揪出异常&lt;/strong&gt;、&lt;strong&gt;找到原因&lt;/strong&gt;、&lt;strong&gt;探索趋势&lt;/strong&gt;等工作。作为数据分析师，不管是用 Python 语言、Excel、SPSS或其他的商业智能工具，工具只是达成目标的手段，&lt;strong&gt;数据思维是核心技能&lt;/strong&gt;，从实际业务问题出发到最终&lt;strong&gt;发现数据中的商业价值&lt;/strong&gt;是终极目标。数据分析师在很多公司只是一个基础岗位，精于业务的数据分析师可以向&lt;strong&gt;数据分析经理&lt;/strong&gt;或&lt;strong&gt;数据运营总监&lt;/strong&gt;等管理岗位发展；对于熟悉机器学习算法的数据分析师来说，可以向&lt;strong&gt;数据挖掘工程师&lt;/strong&gt;或&lt;strong&gt;算法专家&lt;/strong&gt;方向发展，而这些岗位除了需要相应的数学和统计学知识，在编程能力方面也比数据分析师有更高的要求，可能还需要有大数据存储和处理的相关经验。数据治理岗位主要是帮助公司建设数据仓库或数据湖，实现数据从业务系统、埋点系统、日志系统到分析库的转移，为后续的数据分析和挖掘提供基础设施。数据治理岗位对 SQL 和 HiveSQL 有着较高的要求，要求能够熟练的使用 ETL 工具，此外可能还需要对 Hadoop 生态圈有一个很好的认知。作为数据产品经理，除了传统产品经理的技能栈之外，也需要较强的技术能力，例如要了解常用的推荐算法、机器学习模型，能够为算法的改进提供依据，能够制定相关埋点的规范和口径，虽然不需要精通各种算法，但是要站在产品的角度去考虑数据模型、指标、算法等的落地&lt;/p&gt;
&lt;p&gt;以下是我总结的数据分析师的技能栈，仅供参考。&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;计算机科学（数据分析工具、编程语言、数据库）&lt;/li&gt;
&lt;li&gt;数学和统计学（数据思维、统计思维）&lt;/li&gt;
&lt;li&gt;人工智能（机器学习中的数据挖掘算法）&lt;/li&gt;
&lt;li&gt;业务理解能力（沟通、表达、经验）&lt;/li&gt;
&lt;li&gt;总结和表述能力（商业PPT、文字总结）&lt;/li&gt;
&lt;/ol&gt;
&lt;h3 id=&#34;数据分析的流程&#34;&gt;&lt;a href=&#34;#数据分析的流程&#34; class=&#34;headerlink&#34; title=&#34;数据分析的流程&#34;&gt;&lt;/a&gt;数据分析的流程&lt;/h3&gt;&lt;p&gt;我们提到数分析这个词很多时候可能指的都是&lt;strong&gt;狭义的数据分析&lt;/strong&gt;，这类数据分析主要目标就是生成可视化报表并通过这些报表来洞察业务中的问题。&lt;strong&gt;广义的数据分析&lt;/strong&gt;还包含了数据挖掘的部分，不仅要通过数据实现对业务的监控和分析，还要利用机器学习算法，找出隐藏在数据背后的知识，并利用这些知识为将来的决策提供支撑。简单的说，&lt;strong&gt;一个完整的数据分析应该包括基本的数据分析和深入的数据挖掘两个部分&lt;/strong&gt;。&lt;/p&gt;
&lt;p&gt;基本的数据分析工作一般包含以下几个方面的内容，当然因为行业和工作内容的不同会略有差异。&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;确定目标（输入）：理解业务，确定指标口径&lt;/li&gt;
&lt;li&gt;获取数据：数据仓库、电子表格、三方接口、网络爬虫、开放数据集等&lt;/li&gt;
&lt;li&gt;清洗数据：缺失值&amp;#x2F;重复值&amp;#x2F;异常值处理、数据变换（格式化、规范化）、离散化等&lt;/li&gt;
&lt;li&gt;数据透视：运算、统计、分组、聚合、可视化&lt;/li&gt;
&lt;li&gt;数据报告（输出）：数据发布，工作成果总结汇报&lt;/li&gt;
&lt;li&gt;分析洞察（后续）：解释数据的变化，提出对应的方案&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;深入的数据挖掘工作通常包含以下几个方面的内容，当然因为行业和工作内容的不同会略有差异。&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;确定目标（输入）：理解业务，明确挖掘目标&lt;/li&gt;
&lt;li&gt;数据准备：数据采集、数据描述、数据探索、质量判定等&lt;/li&gt;
&lt;li&gt;数据加工：提取数据、清洗数据、数据变换、特殊编码、降维、特征选择等&lt;/li&gt;
&lt;li&gt;数据建模：模型比较、模型选择、算法应用&lt;/li&gt;
&lt;li&gt;模型评估：交叉检验、参数调优、结果评价&lt;/li&gt;
&lt;li&gt;模型部署（输出）：模型落地、业务改进、运营监控、报告撰写&lt;/li&gt;
&lt;/ol&gt;
&lt;h3 id=&#34;数据分析相关库&#34;&gt;&lt;a href=&#34;#数据分析相关库&#34; class=&#34;headerlink&#34; title=&#34;数据分析相关库&#34;&gt;&lt;/a&gt;数据分析相关库&lt;/h3&gt;&lt;p&gt;使用 Python 从事数据科学相关的工作是一个非常棒的选择，因为 Python 整个生态圈中，有大量的成熟的用于数据科学的软件包（工具库）。而且不同于其他的用于数据科学的编程语言（如：Julia、R），Python 除了可以用于数据科学，能做的事情还很多，可以说 Python 语言几乎是无所不能的。&lt;/p&gt;
&lt;h4 id=&#34;三大神器&#34;&gt;&lt;a href=&#34;#三大神器&#34; class=&#34;headerlink&#34; title=&#34;三大神器&#34;&gt;&lt;/a&gt;三大神器&lt;/h4&gt;&lt;ol&gt;
&lt;li&gt;&lt;a href=&#34;https://numpy.org/&#34;&gt;NumPy&lt;/a&gt;：支持常见的数组和矩阵操作，通过&lt;code&gt;ndarray&lt;/code&gt;类实现了对多维数组的封装，提供了操作这些数组的方法和函数集。由于 NumPy 内置了并行运算功能，当使用多核 CPU 时，Numpy会自动做并行计算。&lt;/li&gt;
&lt;li&gt;&lt;a href=&#34;https://pandas.pydata.org/&#34;&gt;Pandas&lt;/a&gt;：pandas 的核心是其特有的数据结构&lt;code&gt;DataFrame&lt;/code&gt;和&lt;code&gt;Series&lt;/code&gt;，这使得 pandas 可以处理包含不同类型的数据的负责表格和时间序列，这一点是NumPy的&lt;code&gt;ndarray&lt;/code&gt;做不到的。使用 pandas，可以轻松顺利的加载各种形式的数据，然后对数据进行切片、切块、处理缺失值、聚合、重塑和可视化等操作。&lt;/li&gt;
&lt;li&gt;&lt;a href=&#34;https://matplotlib.org/&#34;&gt;Matplotlib&lt;/a&gt;：matplotlib 是一个包含各种绘图模块的库，能够根据我们提供的数据创建高质量的图形。此外，matplotlib 还提供了 pylab 模块，这个模块包含了很多像 &lt;a href=&#34;https://www.mathworks.com/products/matlab.html&#34;&gt;MATLAB&lt;/a&gt; 一样的绘图组件。&lt;/li&gt;
&lt;/ol&gt;
&lt;h4 id=&#34;其他相关库&#34;&gt;&lt;a href=&#34;#其他相关库&#34; class=&#34;headerlink&#34; title=&#34;其他相关库&#34;&gt;&lt;/a&gt;其他相关库&lt;/h4&gt;&lt;ol&gt;
&lt;li&gt;&lt;a href=&#34;https://scipy.org/&#34;&gt;SciPy&lt;/a&gt;：完善了 NumPy 的功能，封装了大量科学计算的算法，包括线性代数、稀疏矩阵、信号和图像处理、最优化问题、快速傅里叶变换等。&lt;/li&gt;
&lt;li&gt;&lt;a href=&#34;https://seaborn.pydata.org/&#34;&gt;Seaborn&lt;/a&gt;：seaborn 是基于 matplotlib 的图形可视化工具，直接使用 matplotlib 虽然可以定制出漂亮的统计图表，但是总体来说还不够简单方便，seaborn 相当于是对 matplotlib 做了封装，让用户能够以更简洁有效的方式做出各种有吸引力的统计图表。&lt;/li&gt;
&lt;li&gt;&lt;a href=&#34;https://scikit-learn.org/&#34;&gt;Scikit-learn&lt;/a&gt;：scikit-learn 最初是 SciPy 的一部分，它是 Python 数据科学运算的核心，提供了大量机器学习可能用到的工具，包括：数据预处理、监督学习（分类、回归）、无监督学习（聚类）、模式选择、交叉检验等。&lt;/li&gt;
&lt;li&gt;&lt;a href=&#34;https://www.statsmodels.org/stable/index.html&#34;&gt;Statsmodels&lt;/a&gt;：包含了经典统计学和经济计量学算法的库。&lt;/li&gt;
&lt;/ol&gt;

 &lt;h2 id=&#34;爬虫框架Scrapy简介&#34;&gt;&lt;a href=&#34;#爬虫框架Scrapy简介&#34; class=&#34;headerlink&#34; title=&#34;爬虫框架Scrapy简介&#34;&gt;&lt;/a&gt;爬虫框架Scrapy简介&lt;/h2&gt;&lt;p&gt;当你写了很多个爬虫程序之后，你会发现每次写爬虫程序时，都需要将页面获取、页面解析、爬虫调度、异常处理、反爬应对这些代码从头至尾实现一遍，这里面有很多工作其实都是简单乏味的重复劳动。那么，有没有什么办法可以提升我们编写爬虫代码的效率呢？答案是肯定的，那就是利用爬虫框架，而在所有的爬虫框架中，Scrapy 应该是最流行、最强大的框架。&lt;/p&gt;
&lt;h3 id=&#34;Scrapy-概述&#34;&gt;&lt;a href=&#34;#Scrapy-概述&#34; class=&#34;headerlink&#34; title=&#34;Scrapy 概述&#34;&gt;&lt;/a&gt;Scrapy 概述&lt;/h3&gt;&lt;p&gt;Scrapy 是基于 Python 的一个非常流行的网络爬虫框架，可以用来抓取 Web 站点并从页面中提取结构化的数据。下图展示了 Scrapy 的基本架构，其中包含了主要组件和系统的数据处理流程（图中带数字的红色箭头）。&lt;/p&gt;
&lt;p&gt;&lt;img src=&#34;https://gitee.com/jackfrued/mypic/raw/master/20210824003638.png&#34;&gt;&lt;/p&gt;
&lt;h4 id=&#34;Scrapy的组件&#34;&gt;&lt;a href=&#34;#Scrapy的组件&#34; class=&#34;headerlink&#34; title=&#34;Scrapy的组件&#34;&gt;&lt;/a&gt;Scrapy的组件&lt;/h4&gt;&lt;p&gt;我们先来说说 Scrapy 中的组件。&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;Scrapy 引擎（Engine）：用来控制整个系统的数据处理流程。&lt;/li&gt;
&lt;li&gt;调度器（Scheduler）：调度器从引擎接受请求并排序列入队列，并在引擎发出请求后返还给它们。&lt;/li&gt;
&lt;li&gt;下载器（Downloader）：下载器的主要职责是抓取网页并将网页内容返还给蜘蛛（Spiders）。&lt;/li&gt;
&lt;li&gt;蜘蛛程序（Spiders）：蜘蛛是用户自定义的用来解析网页并抓取特定URL的类，每个蜘蛛都能处理一个域名或一组域名，简单的说就是用来定义特定网站的抓取和解析规则的模块。&lt;/li&gt;
&lt;li&gt;数据管道（Item Pipeline）：管道的主要责任是负责处理有蜘蛛从网页中抽取的数据条目，它的主要任务是清理、验证和存储数据。当页面被蜘蛛解析后，将被发送到数据管道，并经过几个特定的次序处理数据。每个数据管道组件都是一个 Python 类，它们获取了数据条目并执行对数据条目进行处理的方法，同时还需要确定是否需要在数据管道中继续执行下一步或是直接丢弃掉不处理。数据管道通常执行的任务有：清理 HTML 数据、验证解析到的数据（检查条目是否包含必要的字段）、检查是不是重复数据（如果重复就丢弃）、将解析到的数据存储到数据库（关系型数据库或 NoSQL 数据库）中。&lt;/li&gt;
&lt;li&gt;中间件（Middlewares）：中间件是介于引擎和其他组件之间的一个钩子框架，主要是为了提供自定义的代码来拓展 Scrapy 的功能，包括下载器中间件和蜘蛛中间件。&lt;/li&gt;
&lt;/ol&gt;
&lt;h4 id=&#34;数据处理流程&#34;&gt;&lt;a href=&#34;#数据处理流程&#34; class=&#34;headerlink&#34; title=&#34;数据处理流程&#34;&gt;&lt;/a&gt;数据处理流程&lt;/h4&gt;&lt;p&gt;Scrapy 的整个数据处理流程由引擎进行控制，通常的运转流程包括以下的步骤：&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;&lt;p&gt;引擎询问蜘蛛需要处理哪个网站，并让蜘蛛将第一个需要处理的 URL 交给它。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;引擎让调度器将需要处理的 URL 放在队列中。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;引擎从调度那获取接下来进行爬取的页面。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;调度将下一个爬取的 URL 返回给引擎，引擎将它通过下载中间件发送到下载器。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;当网页被下载器下载完成以后，响应内容通过下载中间件被发送到引擎；如果下载失败了，引擎会通知调度器记录这个 URL，待会再重新下载。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;引擎收到下载器的响应并将它通过蜘蛛中间件发送到蜘蛛进行处理。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;蜘蛛处理响应并返回爬取到的数据条目，此外还要将需要跟进的新的 URL 发送给引擎。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;引擎将抓取到的数据条目送入数据管道，把新的 URL 发送给调度器放入队列中。&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;上述操作中的第2步到第8步会一直重复直到调度器中没有需要请求的 URL，爬虫就停止工作。&lt;/p&gt;
&lt;h3 id=&#34;安装和使用Scrapy&#34;&gt;&lt;a href=&#34;#安装和使用Scrapy&#34; class=&#34;headerlink&#34; title=&#34;安装和使用Scrapy&#34;&gt;&lt;/a&gt;安装和使用Scrapy&lt;/h3&gt;&lt;p&gt;可以使用 Python 的包管理工具&lt;code&gt;pip&lt;/code&gt;来安装 Scrapy。&lt;/p&gt;
&lt;figure class=&#34;highlight shell&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;pip install scrapy&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;在命令行中使用&lt;code&gt;scrapy&lt;/code&gt;命令创建名为&lt;code&gt;demo&lt;/code&gt;的项目。&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;scrapy startproject demo&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;项目的目录结构如下图所示。&lt;/p&gt;
&lt;figure class=&#34;highlight shell&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;demo&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;|____ demo&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;|________ spiders&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;|____________ __init__.py&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;|________ __init__.py&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;|________ items.py&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;|________ middlewares.py&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;|________ pipelines.py&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;|________ settings.py&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;|____ scrapy.cfg&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;切换到&lt;code&gt;demo&lt;/code&gt; 目录，用下面的命令创建名为&lt;code&gt;douban&lt;/code&gt;的蜘蛛程序。&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;scrapy genspider douban movie.douban.com&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h4 id=&#34;一个简单的例子&#34;&gt;&lt;a href=&#34;#一个简单的例子&#34; class=&#34;headerlink&#34; title=&#34;一个简单的例子&#34;&gt;&lt;/a&gt;一个简单的例子&lt;/h4&gt;&lt;p&gt;接下来，我们实现一个爬取豆瓣电影 Top250 电影标题、评分和金句的爬虫。&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;&lt;p&gt;在&lt;code&gt;items.py&lt;/code&gt;的&lt;code&gt;Item&lt;/code&gt;类中定义字段，这些字段用来保存数据，方便后续的操作。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; scrapy&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;class&lt;/span&gt; &lt;span class=&#34;title class_&#34;&gt;DoubanItem&lt;/span&gt;(scrapy.Item):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    title = scrapy.Field()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    score = scrapy.Field()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    motto = scrapy.Field()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;修改&lt;code&gt;spiders&lt;/code&gt;文件夹中名为&lt;code&gt;douban.py&lt;/code&gt; 的文件，它是蜘蛛程序的核心，需要我们添加解析页面的代码。在这里，我们可以通过对&lt;code&gt;Response&lt;/code&gt;对象的解析，获取电影的信息，代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; scrapy&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; scrapy &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; Selector, Request&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; scrapy.http &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; HtmlResponse&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; demo.items &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; MovieItem&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;class&lt;/span&gt; &lt;span class=&#34;title class_&#34;&gt;DoubanSpider&lt;/span&gt;(scrapy.Spider):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    name = &lt;span class=&#34;string&#34;&gt;&amp;#x27;douban&amp;#x27;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    allowed_domains = [&lt;span class=&#34;string&#34;&gt;&amp;#x27;movie.douban.com&amp;#x27;&lt;/span&gt;]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    start_urls = [&lt;span class=&#34;string&#34;&gt;&amp;#x27;https://movie.douban.com/top250?start=0&amp;amp;filter=&amp;#x27;&lt;/span&gt;]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;parse&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;self, response: HtmlResponse&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        sel = Selector(response)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        movie_items = sel.css(&lt;span class=&#34;string&#34;&gt;&amp;#x27;#content &amp;gt; div &amp;gt; div.article &amp;gt; ol &amp;gt; li&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; movie_sel &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; movie_items:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            item = MovieItem()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            item[&lt;span class=&#34;string&#34;&gt;&amp;#x27;title&amp;#x27;&lt;/span&gt;] = movie_sel.css(&lt;span class=&#34;string&#34;&gt;&amp;#x27;.title::text&amp;#x27;&lt;/span&gt;).extract_first()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            item[&lt;span class=&#34;string&#34;&gt;&amp;#x27;score&amp;#x27;&lt;/span&gt;] = movie_sel.css(&lt;span class=&#34;string&#34;&gt;&amp;#x27;.rating_num::text&amp;#x27;&lt;/span&gt;).extract_first()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            item[&lt;span class=&#34;string&#34;&gt;&amp;#x27;motto&amp;#x27;&lt;/span&gt;] = movie_sel.css(&lt;span class=&#34;string&#34;&gt;&amp;#x27;.inq::text&amp;#x27;&lt;/span&gt;).extract_first()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;keyword&#34;&gt;yield&lt;/span&gt; item&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;p&gt;通过上面的代码不难看出，我们可以使用 CSS 选择器进行页面解析。当然，如果你愿意也可以使用 XPath 或正则表达式进行页面解析，对应的方法分别是&lt;code&gt;xpath&lt;/code&gt;和&lt;code&gt;re&lt;/code&gt;。&lt;/p&gt;
&lt;p&gt;如果还要生成后续爬取的请求，我们可以用&lt;code&gt;yield&lt;/code&gt;产出&lt;code&gt;Request&lt;/code&gt;对象。&lt;code&gt;Request&lt;/code&gt;对象有两个非常重要的属性，一个是&lt;code&gt;url&lt;/code&gt;，它代表了要请求的地址；一个是&lt;code&gt;callback&lt;/code&gt;，它代表了获得响应之后要执行的回调函数。我们可以将上面的代码稍作修改。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; scrapy&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; scrapy &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; Selector, Request&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; scrapy.http &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; HtmlResponse&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; demo.items &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; MovieItem&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;class&lt;/span&gt; &lt;span class=&#34;title class_&#34;&gt;DoubanSpider&lt;/span&gt;(scrapy.Spider):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    name = &lt;span class=&#34;string&#34;&gt;&amp;#x27;douban&amp;#x27;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    allowed_domains = [&lt;span class=&#34;string&#34;&gt;&amp;#x27;movie.douban.com&amp;#x27;&lt;/span&gt;]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    start_urls = [&lt;span class=&#34;string&#34;&gt;&amp;#x27;https://movie.douban.com/top250?start=0&amp;amp;filter=&amp;#x27;&lt;/span&gt;]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;parse&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;self, response: HtmlResponse&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        sel = Selector(response)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        movie_items = sel.css(&lt;span class=&#34;string&#34;&gt;&amp;#x27;#content &amp;gt; div &amp;gt; div.article &amp;gt; ol &amp;gt; li&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; movie_sel &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; movie_items:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            item = MovieItem()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            item[&lt;span class=&#34;string&#34;&gt;&amp;#x27;title&amp;#x27;&lt;/span&gt;] = movie_sel.css(&lt;span class=&#34;string&#34;&gt;&amp;#x27;.title::text&amp;#x27;&lt;/span&gt;).extract_first()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            item[&lt;span class=&#34;string&#34;&gt;&amp;#x27;score&amp;#x27;&lt;/span&gt;] = movie_sel.css(&lt;span class=&#34;string&#34;&gt;&amp;#x27;.rating_num::text&amp;#x27;&lt;/span&gt;).extract_first()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            item[&lt;span class=&#34;string&#34;&gt;&amp;#x27;motto&amp;#x27;&lt;/span&gt;] = movie_sel.css(&lt;span class=&#34;string&#34;&gt;&amp;#x27;.inq::text&amp;#x27;&lt;/span&gt;).extract_first()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;keyword&#34;&gt;yield&lt;/span&gt; item&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        hrefs = sel.css(&lt;span class=&#34;string&#34;&gt;&amp;#x27;#content &amp;gt; div &amp;gt; div.article &amp;gt; div.paginator &amp;gt; a::attr(&amp;quot;href&amp;quot;)&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; href &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; hrefs:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            full_url = response.urljoin(href.extract())&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;keyword&#34;&gt;yield&lt;/span&gt; Request(url=full_url)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;到这里，我们已经可以通过下面的命令让爬虫运转起来。&lt;/p&gt;
&lt;figure class=&#34;highlight shell&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;scrapy crawl movie&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;可以在控制台看到爬取到的数据，如果想将这些数据保存到文件中，可以通过&lt;code&gt;-o&lt;/code&gt;参数来指定文件名，Scrapy 支持我们将爬取到的数据导出成 JSON、CSV、XML 等格式。&lt;/p&gt;
&lt;figure class=&#34;highlight shell&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;scrapy crawl moive -o result.json&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;不知大家是否注意到，通过运行爬虫获得的 JSON 文件中有&lt;code&gt;275&lt;/code&gt;条数据，那是因为首页被重复爬取了。要解决这个问题，可以对上面的代码稍作调整，不在&lt;code&gt;parse&lt;/code&gt;方法中解析获取新页面的 URL，而是通过&lt;code&gt;start_requests&lt;/code&gt;方法提前准备好待爬取页面的 URL，调整后的代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; scrapy&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; scrapy &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; Selector, Request&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; scrapy.http &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; HtmlResponse&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; demo.items &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; MovieItem&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;class&lt;/span&gt; &lt;span class=&#34;title class_&#34;&gt;DoubanSpider&lt;/span&gt;(scrapy.Spider):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    name = &lt;span class=&#34;string&#34;&gt;&amp;#x27;douban&amp;#x27;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    allowed_domains = [&lt;span class=&#34;string&#34;&gt;&amp;#x27;movie.douban.com&amp;#x27;&lt;/span&gt;]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;start_requests&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;self&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; page &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; &lt;span class=&#34;built_in&#34;&gt;range&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;keyword&#34;&gt;yield&lt;/span&gt; Request(url=&lt;span class=&#34;string&#34;&gt;f&amp;#x27;https://movie.douban.com/top250?start=&lt;span class=&#34;subst&#34;&gt;&amp;#123;page * &lt;span class=&#34;number&#34;&gt;25&lt;/span&gt;&amp;#125;&lt;/span&gt;&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;parse&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;self, response: HtmlResponse&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        sel = Selector(response)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        movie_items = sel.css(&lt;span class=&#34;string&#34;&gt;&amp;#x27;#content &amp;gt; div &amp;gt; div.article &amp;gt; ol &amp;gt; li&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; movie_sel &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; movie_items:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            item = MovieItem()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            item[&lt;span class=&#34;string&#34;&gt;&amp;#x27;title&amp;#x27;&lt;/span&gt;] = movie_sel.css(&lt;span class=&#34;string&#34;&gt;&amp;#x27;.title::text&amp;#x27;&lt;/span&gt;).extract_first()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            item[&lt;span class=&#34;string&#34;&gt;&amp;#x27;score&amp;#x27;&lt;/span&gt;] = movie_sel.css(&lt;span class=&#34;string&#34;&gt;&amp;#x27;.rating_num::text&amp;#x27;&lt;/span&gt;).extract_first()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            item[&lt;span class=&#34;string&#34;&gt;&amp;#x27;motto&amp;#x27;&lt;/span&gt;] = movie_sel.css(&lt;span class=&#34;string&#34;&gt;&amp;#x27;.inq::text&amp;#x27;&lt;/span&gt;).extract_first()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;keyword&#34;&gt;yield&lt;/span&gt; item&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;如果希望完成爬虫数据的持久化，可以在数据管道中处理蜘蛛程序产生的&lt;code&gt;Item&lt;/code&gt;对象。例如，我们可以通过前面讲到的&lt;code&gt;openpyxl&lt;/code&gt;操作 Excel 文件，将数据写入 Excel 文件中，代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; openpyxl&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; demo.items &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; MovieItem&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;class&lt;/span&gt; &lt;span class=&#34;title class_&#34;&gt;MovieItemPipeline&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;__init__&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;self&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        self.wb = openpyxl.Workbook()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        self.sheet = self.wb.active&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        self.sheet.title = &lt;span class=&#34;string&#34;&gt;&amp;#x27;Top250&amp;#x27;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        self.sheet.append((&lt;span class=&#34;string&#34;&gt;&amp;#x27;名称&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;评分&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;名言&amp;#x27;&lt;/span&gt;))&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;process_item&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;self, item: MovieItem, spider&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        self.sheet.append((item[&lt;span class=&#34;string&#34;&gt;&amp;#x27;title&amp;#x27;&lt;/span&gt;], item[&lt;span class=&#34;string&#34;&gt;&amp;#x27;score&amp;#x27;&lt;/span&gt;], item[&lt;span class=&#34;string&#34;&gt;&amp;#x27;motto&amp;#x27;&lt;/span&gt;]))&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; item&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;close_spider&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;self, spider&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        self.wb.save(&lt;span class=&#34;string&#34;&gt;&amp;#x27;豆瓣电影数据.xlsx&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;上面的&lt;code&gt;process_item&lt;/code&gt;和&lt;code&gt;close_spider&lt;/code&gt;都是回调方法（钩子函数）， 简单的说就是 Scrapy 框架会自动去调用的方法。当蜘蛛程序产生一个&lt;code&gt;Item&lt;/code&gt;对象交给引擎时，引擎会将该&lt;code&gt;Item&lt;/code&gt;对象交给数据管道，这时我们配置好的数据管道的&lt;code&gt;parse_item&lt;/code&gt;方法就会被执行，所以我们可以在该方法中获取数据并完成数据的持久化操作。另一个方法&lt;code&gt;close_spider&lt;/code&gt;是在爬虫结束运行前会自动执行的方法，在上面的代码中，我们在这个地方进行了保存 Excel 文件的操作，相信这段代码大家是很容易读懂的。&lt;/p&gt;
&lt;p&gt;总而言之，数据管道可以帮助我们完成以下操作：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;清理 HTML 数据，验证爬取的数据。&lt;/li&gt;
&lt;li&gt;丢弃重复的不必要的内容。&lt;/li&gt;
&lt;li&gt;将爬取的结果进行持久化操作。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;修改&lt;code&gt;settings.py&lt;/code&gt;文件对项目进行配置，主要需要修改以下几个配置。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 用户浏览器&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;USER_AGENT = &lt;span class=&#34;string&#34;&gt;&amp;#x27;Mozilla/5.0 (Macintosh; Intel Mac OS X 10_14_6) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/92.0.4515.159 Safari/537.36&amp;#x27;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 并发请求数量 &lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;CONCURRENT_REQUESTS = &lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 下载延迟&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;DOWNLOAD_DELAY = &lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 随机化下载延迟&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;RANDOMIZE_DOWNLOAD_DELAY = &lt;span class=&#34;literal&#34;&gt;True&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 是否遵守爬虫协议&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;ROBOTSTXT_OBEY = &lt;span class=&#34;literal&#34;&gt;True&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 配置数据管道&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;ITEM_PIPELINES = &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;   &lt;span class=&#34;string&#34;&gt;&amp;#x27;demo.pipelines.MovieItemPipeline&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;number&#34;&gt;300&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;说明&lt;/strong&gt;：上面配置文件中的&lt;code&gt;ITEM_PIPELINES&lt;/code&gt;选项是一个字典，可以配置多个处理数据的管道，后面的数字代表了执行的优先级，数字小的先执行。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;/li&gt;
&lt;/ol&gt;

 &lt;h2 id=&#34;使用Selenium抓取网页动态内容&#34;&gt;&lt;a href=&#34;#使用Selenium抓取网页动态内容&#34; class=&#34;headerlink&#34; title=&#34;使用Selenium抓取网页动态内容&#34;&gt;&lt;/a&gt;使用Selenium抓取网页动态内容&lt;/h2&gt;&lt;p&gt;根据权威机构发布的全球互联网可访问性审计报告，全球约有四分之三的网站其内容或部分内容是通过JavaScript动态生成的，这就意味着在浏览器窗口中“查看网页源代码”时无法在HTML代码中找到这些内容，也就是说我们之前用的抓取数据的方式无法正常运转了。解决这样的问题基本上有两种方案，一是获取提供动态内容的数据接口，这种方式也适用于抓取手机 App 的数据；另一种是通过自动化测试工具 Selenium 运行浏览器获取渲染后的动态内容。对于第一种方案，我们可以使用浏览器的“开发者工具”或者更为专业的抓包工具（如：Charles、Fiddler、Wireshark等）来获取到数据接口，后续的操作跟上一个章节中讲解的获取“360图片”网站的数据是一样的，这里我们不再进行赘述。这一章我们重点讲解如何使用自动化测试工具 Selenium 来获取网站的动态内容。&lt;/p&gt;
&lt;h3 id=&#34;Selenium-介绍&#34;&gt;&lt;a href=&#34;#Selenium-介绍&#34; class=&#34;headerlink&#34; title=&#34;Selenium 介绍&#34;&gt;&lt;/a&gt;Selenium 介绍&lt;/h3&gt;&lt;p&gt;Selenium 是一个自动化测试工具，利用它可以驱动浏览器执行特定的行为，最终帮助爬虫开发者获取到网页的动态内容。简单的说，只要我们在浏览器窗口中能够看到的内容，都可以使用 Selenium 获取到，对于那些使用了 JavaScript 动态渲染技术的网站，Selenium 会是一个重要的选择。下面，我们还是以 Chrome 浏览器为例，来讲解 Selenium 的用法，大家需要先安装 Chrome 浏览器并下载它的驱动。Chrome 浏览器的驱动程序可以在&lt;a href=&#34;https://chromedriver.chromium.org/downloads&#34;&gt;ChromeDriver官网&lt;/a&gt;进行下载，驱动的版本要跟浏览器的版本对应，如果没有完全对应的版本，就选择版本代号最为接近的版本。&lt;/p&gt;
&lt;img src=&#34;https://gitee.com/jackfrued/mypic/raw/master/20220310134558.png&#34; style=&#34;zoom: 35%&#34;&gt;

&lt;h3 id=&#34;使用Selenium&#34;&gt;&lt;a href=&#34;#使用Selenium&#34; class=&#34;headerlink&#34; title=&#34;使用Selenium&#34;&gt;&lt;/a&gt;使用Selenium&lt;/h3&gt;&lt;p&gt;我们可以先通过&lt;code&gt;pip&lt;/code&gt;来安装 Selenium，命令如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight shell&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;pip install selenium&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h4 id=&#34;加载页面&#34;&gt;&lt;a href=&#34;#加载页面&#34; class=&#34;headerlink&#34; title=&#34;加载页面&#34;&gt;&lt;/a&gt;加载页面&lt;/h4&gt;&lt;p&gt;接下来，我们通过下面的代码驱动 Chrome 浏览器打开百度。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; selenium &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; webdriver&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 创建Chrome浏览器对象&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;browser = webdriver.Chrome()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 加载指定的页面&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;browser.get(&lt;span class=&#34;string&#34;&gt;&amp;#x27;https://www.baidu.com/&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;如果不愿意使用 Chrome 浏览器，也可以修改上面的代码操控其他浏览器，只需创建对应的浏览器对象（如 Firefox、Safari 等）即可。运行上面的程序，如果看到如下所示的错误提示，那是说明我们还没有将 Chrome 浏览器的驱动添加到 PATH 环境变量中，也没有在程序中指定 Chrome 浏览器驱动所在的位置。&lt;/p&gt;
&lt;figure class=&#34;highlight shell&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;selenium.common.exceptions.WebDriverException: Message: &amp;#x27;chromedriver&amp;#x27; executable needs to be in PATH. Please see https://sites.google.com/a/chromium.org/chromedriver/home&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;解决这个问题的办法有三种：&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;&lt;p&gt;将下载的 ChromeDriver 放到已有的 PATH 环境变量下，建议直接跟 Python 解释器放在同一个目录，因为之前安装 Python 的时候我们已经将 Python 解释器的路径放到 PATH 环境变量中了。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;将 ChromeDriver 放到项目虚拟环境下的 &lt;code&gt;bin&lt;/code&gt; 文件夹中（Windows 系统对应的目录是 &lt;code&gt;Scripts&lt;/code&gt;），这样 ChromeDriver 就跟虚拟环境下的 Python 解释器在同一个位置，肯定是能够找到的。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;修改上面的代码，在创建 Chrome 对象时，通过&lt;code&gt;service&lt;/code&gt;参数配置&lt;code&gt;Service&lt;/code&gt;对象，并通过创建&lt;code&gt;Service&lt;/code&gt;对象的&lt;code&gt;executable_path&lt;/code&gt;参数指定 ChromeDriver 所在的位置，如下所示：&lt;/p&gt;
 &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; selenium &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; webdriver&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; selenium.webdriver.chrome.service &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; Service&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;browser = webdriver.Chrome(service=Service(executable_path=&lt;span class=&#34;string&#34;&gt;&amp;#x27;venv/bin/chromedriver&amp;#x27;&lt;/span&gt;))&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;browser.get(&lt;span class=&#34;string&#34;&gt;&amp;#x27;https://www.baidu.com/&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;/li&gt;
&lt;/ol&gt;
&lt;h4 id=&#34;查找元素和模拟用户行为&#34;&gt;&lt;a href=&#34;#查找元素和模拟用户行为&#34; class=&#34;headerlink&#34; title=&#34;查找元素和模拟用户行为&#34;&gt;&lt;/a&gt;查找元素和模拟用户行为&lt;/h4&gt;&lt;p&gt;接下来，我们可以尝试模拟用户在百度首页的文本框输入搜索关键字并点击“百度一下”按钮。在完成页面加载后，可以通过&lt;code&gt;Chrome&lt;/code&gt;对象的&lt;code&gt;find_element&lt;/code&gt;和&lt;code&gt;find_elements&lt;/code&gt;方法来获取页面元素，Selenium 支持多种获取元素的方式，包括：CSS 选择器、XPath、元素名字（标签名）、元素 ID、类名等，前者可以获取单个页面元素（&lt;code&gt;WebElement&lt;/code&gt;对象），后者可以获取多个页面元素构成的列表。获取到&lt;code&gt;WebElement&lt;/code&gt;对象以后，可以通过&lt;code&gt;send_keys&lt;/code&gt;来模拟用户输入行为，可以通过&lt;code&gt;click&lt;/code&gt;来模拟用户点击操作，代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; selenium &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; webdriver&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; selenium.webdriver.common.by &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; By&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;browser = webdriver.Chrome()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;browser.get(&lt;span class=&#34;string&#34;&gt;&amp;#x27;https://www.baidu.com/&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 通过元素ID获取元素&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;kw_input = browser.find_element(By.ID, &lt;span class=&#34;string&#34;&gt;&amp;#x27;kw&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 模拟用户输入行为&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;kw_input.send_keys(&lt;span class=&#34;string&#34;&gt;&amp;#x27;Python&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 通过CSS选择器获取元素&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;su_button = browser.find_element(By.CSS_SELECTOR, &lt;span class=&#34;string&#34;&gt;&amp;#x27;#su&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 模拟用户点击行为&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;su_button.click()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;如果要执行一个系列动作，例如模拟拖拽操作，可以创建&lt;code&gt;ActionChains&lt;/code&gt;对象，有兴趣的读者可以自行研究。&lt;/p&gt;
&lt;h4 id=&#34;隐式等待和显式等待&#34;&gt;&lt;a href=&#34;#隐式等待和显式等待&#34; class=&#34;headerlink&#34; title=&#34;隐式等待和显式等待&#34;&gt;&lt;/a&gt;隐式等待和显式等待&lt;/h4&gt;&lt;p&gt;这里还有一个细节需要大家知道，网页上的元素可能是动态生成的，在我们使用&lt;code&gt;find_element&lt;/code&gt;或&lt;code&gt;find_elements&lt;/code&gt;方法获取的时候，可能还没有完成渲染，这时会引发&lt;code&gt;NoSuchElementException&lt;/code&gt;错误。为了解决这个问题，我们可以使用隐式等待的方式，通过设置等待时间让浏览器完成对页面元素的渲染。除此之外，我们还可以使用显示等待，通过创建&lt;code&gt;WebDriverWait&lt;/code&gt;对象，并设置等待时间和条件，当条件没有满足时，我们可以先等待再尝试进行后续的操作，具体的代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; selenium &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; webdriver&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; selenium.webdriver.common.by &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; By&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; selenium.webdriver.support &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; expected_conditions&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; selenium.webdriver.support.wait &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; WebDriverWait&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;browser = webdriver.Chrome()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 设置浏览器窗口大小&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;browser.set_window_size(&lt;span class=&#34;number&#34;&gt;1200&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;800&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;browser.get(&lt;span class=&#34;string&#34;&gt;&amp;#x27;https://www.baidu.com/&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 设置隐式等待时间为10秒&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;browser.implicitly_wait(&lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;kw_input = browser.find_element(By.ID, &lt;span class=&#34;string&#34;&gt;&amp;#x27;kw&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;kw_input.send_keys(&lt;span class=&#34;string&#34;&gt;&amp;#x27;Python&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;su_button = browser.find_element(By.CSS_SELECTOR, &lt;span class=&#34;string&#34;&gt;&amp;#x27;#su&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;su_button.click()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 创建显示等待对象&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;wait_obj = WebDriverWait(browser, &lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 设置等待条件（等搜索结果的div出现）&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;wait_obj.until(&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    expected_conditions.presence_of_element_located(&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        (By.CSS_SELECTOR, &lt;span class=&#34;string&#34;&gt;&amp;#x27;#content_left&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    )&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 截屏&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;browser.get_screenshot_as_file(&lt;span class=&#34;string&#34;&gt;&amp;#x27;python_result.png&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;上面设置的等待条件&lt;code&gt;presence_of_element_located&lt;/code&gt;表示等待指定元素出现，下面的表格列出了常用的等待条件及其含义。&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;等待条件&lt;/th&gt;
&lt;th&gt;具体含义&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;&lt;code&gt;title_is / title_contains&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;标题是指定的内容 &amp;#x2F; 标题包含指定的内容&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;visibility_of&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;元素可见&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;presence_of_element_located&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;定位的元素加载完成&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;visibility_of_element_located&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;定位的元素变得可见&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;invisibility_of_element_located&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;定位的元素变得不可见&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;presence_of_all_elements_located&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;定位的所有元素加载完成&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;text_to_be_present_in_element&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;元素包含指定的内容&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;text_to_be_present_in_element_value&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;元素的&lt;code&gt;value&lt;/code&gt;属性包含指定的内容&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;frame_to_be_available_and_switch_to_it&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;载入并切换到指定的内部窗口&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;element_to_be_clickable&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;元素可点击&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;element_to_be_selected&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;元素被选中&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;element_located_to_be_selected&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;定位的元素被选中&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;alert_is_present&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;出现 Alert 弹窗&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;h4 id=&#34;执行JavaScript代码&#34;&gt;&lt;a href=&#34;#执行JavaScript代码&#34; class=&#34;headerlink&#34; title=&#34;执行JavaScript代码&#34;&gt;&lt;/a&gt;执行JavaScript代码&lt;/h4&gt;&lt;p&gt;对于使用瀑布式加载的页面，如果希望在浏览器窗口中加载更多的内容，可以通过浏览器对象的&lt;code&gt;execute_scripts&lt;/code&gt;方法执行 JavaScript 代码来实现。对于一些高级的爬取操作，也很有可能会用到类似的操作，如果你的爬虫代码需要 JavaScript 的支持，建议先对 JavaScript 进行适当的了解，尤其是 JavaScript 中的 BOM 和 DOM 操作。我们在上面的代码中截屏之前加入下面的代码，这样就可以利用 JavaScript 将网页滚到最下方。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 执行JavaScript代码&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;browser.execute_script(&lt;span class=&#34;string&#34;&gt;&amp;#x27;document.documentElement.scrollTop = document.documentElement.scrollHeight&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h4 id=&#34;Selenium反爬的破解&#34;&gt;&lt;a href=&#34;#Selenium反爬的破解&#34; class=&#34;headerlink&#34; title=&#34;Selenium反爬的破解&#34;&gt;&lt;/a&gt;Selenium反爬的破解&lt;/h4&gt;&lt;p&gt;有一些网站专门针对 Selenium 设置了反爬措施，因为使用 Selenium 驱动的浏览器，在控制台中可以看到如下所示的&lt;code&gt;webdriver&lt;/code&gt;属性值为&lt;code&gt;true&lt;/code&gt;，如果要绕过这项检查，可以在加载页面之前，先通过执行 JavaScript 代码将其修改为&lt;code&gt;undefined&lt;/code&gt;。&lt;/p&gt;
&lt;img src=&#34;https://gitee.com/jackfrued/mypic/raw/master/20220310154246.png&#34; style=&#34;zoom:50%&#34;&gt;

&lt;p&gt;另一方面，我们还可以将浏览器窗口上的“Chrome正受到自动测试软件的控制”隐藏掉，完整的代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 创建Chrome参数对象&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;options = webdriver.ChromeOptions()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 添加试验性参数&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;options.add_experimental_option(&lt;span class=&#34;string&#34;&gt;&amp;#x27;excludeSwitches&amp;#x27;&lt;/span&gt;, [&lt;span class=&#34;string&#34;&gt;&amp;#x27;enable-automation&amp;#x27;&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;options.add_experimental_option(&lt;span class=&#34;string&#34;&gt;&amp;#x27;useAutomationExtension&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;literal&#34;&gt;False&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 创建Chrome浏览器对象并传入参数&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;browser = webdriver.Chrome(options=options)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 执行Chrome开发者协议命令（在加载页面时执行指定的JavaScript代码）&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;browser.execute_cdp_cmd(&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;#x27;Page.addScriptToEvaluateOnNewDocument&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &amp;#123;&lt;span class=&#34;string&#34;&gt;&amp;#x27;source&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;Object.defineProperty(navigator, &amp;quot;webdriver&amp;quot;, &amp;#123;get: () =&amp;gt; undefined&amp;#125;)&amp;#x27;&lt;/span&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;browser.set_window_size(&lt;span class=&#34;number&#34;&gt;1200&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;800&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;browser.get(&lt;span class=&#34;string&#34;&gt;&amp;#x27;https://www.baidu.com/&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h4 id=&#34;无头浏览器&#34;&gt;&lt;a href=&#34;#无头浏览器&#34; class=&#34;headerlink&#34; title=&#34;无头浏览器&#34;&gt;&lt;/a&gt;无头浏览器&lt;/h4&gt;&lt;p&gt;很多时候，我们在爬取数据时并不需要看到浏览器窗口，只要有 Chrome 浏览器以及对应的驱动程序，我们的爬虫就能够运转起来。如果不想看到浏览器窗口，我们可以通过下面的方式设置使用无头浏览器。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;options = webdriver.ChromeOptions()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;options.add_argument(&lt;span class=&#34;string&#34;&gt;&amp;#x27;--headless&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;browser = webdriver.Chrome(options=options)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h3 id=&#34;API参考&#34;&gt;&lt;a href=&#34;#API参考&#34; class=&#34;headerlink&#34; title=&#34;API参考&#34;&gt;&lt;/a&gt;API参考&lt;/h3&gt;&lt;p&gt;Selenium 相关的知识还有很多，我们在此就不一一赘述了，下面为大家罗列一些浏览器对象和&lt;code&gt;WebElement&lt;/code&gt;对象常用的属性和方法。具体的内容大家还可以参考 Selenium &lt;a href=&#34;https://selenium-python-zh.readthedocs.io/en/latest/index.html&#34;&gt;官方文档的中文翻译&lt;/a&gt;。&lt;/p&gt;
&lt;h4 id=&#34;浏览器对象&#34;&gt;&lt;a href=&#34;#浏览器对象&#34; class=&#34;headerlink&#34; title=&#34;浏览器对象&#34;&gt;&lt;/a&gt;浏览器对象&lt;/h4&gt;&lt;p&gt;表1. 常用属性&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;属性名&lt;/th&gt;
&lt;th&gt;描述&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;&lt;code&gt;current_url&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;当前页面的URL&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;current_window_handle&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;当前窗口的句柄（引用）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;name&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;浏览器的名称&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;orientation&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;当前设备的方向（横屏、竖屏）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;page_source&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;当前页面的源代码（包括动态内容）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;title&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;当前页面的标题&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;window_handles&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;浏览器打开的所有窗口的句柄&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;p&gt;表2. 常用方法&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;方法名&lt;/th&gt;
&lt;th&gt;描述&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;&lt;code&gt;back&lt;/code&gt; &amp;#x2F; &lt;code&gt;forward&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;在浏览历史记录中后退&amp;#x2F;前进&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;close&lt;/code&gt; &amp;#x2F; &lt;code&gt;quit&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;关闭当前浏览器窗口 &amp;#x2F; 退出浏览器实例&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;get&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;加载指定 URL 的页面到浏览器中&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;maximize_window&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;将浏览器窗口最大化&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;refresh&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;刷新当前页面&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;set_page_load_timeout&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;设置页面加载超时时间&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;set_script_timeout&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;设置 JavaScript 执行超时时间&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;implicit_wait&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;设置等待元素被找到或目标指令完成&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;get_cookie&lt;/code&gt; &amp;#x2F; &lt;code&gt;get_cookies&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;获取指定的Cookie &amp;#x2F; 获取所有Cookie&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;add_cookie&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;添加 Cookie 信息&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;delete_cookie&lt;/code&gt; &amp;#x2F; &lt;code&gt;delete_all_cookies&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;删除指定的 Cookie &amp;#x2F; 删除所有 Cookie&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;find_element&lt;/code&gt; &amp;#x2F; &lt;code&gt;find_elements&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;查找单个元素 &amp;#x2F; 查找一系列元素&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;h4 id=&#34;WebElement对象&#34;&gt;&lt;a href=&#34;#WebElement对象&#34; class=&#34;headerlink&#34; title=&#34;WebElement对象&#34;&gt;&lt;/a&gt;WebElement对象&lt;/h4&gt;&lt;p&gt;表1. WebElement常用属性&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;属性名&lt;/th&gt;
&lt;th&gt;描述&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;&lt;code&gt;location&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;元素的位置&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;size&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;元素的尺寸&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;text&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;元素的文本内容&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;id&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;元素的 ID&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;tag_name&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;元素的标签名&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;p&gt;表2. 常用方法&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;方法名&lt;/th&gt;
&lt;th&gt;描述&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;&lt;code&gt;clear&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;清空文本框或文本域中的内容&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;click&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;点击元素&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;get_attribute&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;获取元素的属性值&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;is_displayed&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;判断元素对于用户是否可见&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;is_enabled&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;判断元素是否处于可用状态&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;is_selected&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;判断元素（单选框和复选框）是否被选中&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;send_keys&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;模拟输入文本&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;submit&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;提交表单&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;value_of_css_property&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;获取指定的CSS属性值&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;find_element&lt;/code&gt; &amp;#x2F; &lt;code&gt;find_elements&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;获取单个子元素 &amp;#x2F; 获取一系列子元素&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;screenshot&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;为元素生成快照&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;h3 id=&#34;简单案例&#34;&gt;&lt;a href=&#34;#简单案例&#34; class=&#34;headerlink&#34; title=&#34;简单案例&#34;&gt;&lt;/a&gt;简单案例&lt;/h3&gt;&lt;p&gt;下面的例子演示了如何使用 Selenium 从“360图片”网站搜索和下载图片。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; os&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; time&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; concurrent.futures &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; ThreadPoolExecutor&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; requests&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; selenium &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; webdriver&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; selenium.webdriver.common.by &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; By&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; selenium.webdriver.common.keys &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; Keys&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;DOWNLOAD_PATH = &lt;span class=&#34;string&#34;&gt;&amp;#x27;images/&amp;#x27;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;download_picture&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;picture_url: &lt;span class=&#34;built_in&#34;&gt;str&lt;/span&gt;&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;&amp;quot;&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;    下载保存图片&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;    :param picture_url: 图片的URL&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;    &amp;quot;&amp;quot;&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    filename = picture_url[picture_url.rfind(&lt;span class=&#34;string&#34;&gt;&amp;#x27;/&amp;#x27;&lt;/span&gt;) + &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;:]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    resp = requests.get(picture_url)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;with&lt;/span&gt; &lt;span class=&#34;built_in&#34;&gt;open&lt;/span&gt;(os.path.join(DOWNLOAD_PATH, filename), &lt;span class=&#34;string&#34;&gt;&amp;#x27;wb&amp;#x27;&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;as&lt;/span&gt; file:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        file.write(resp.content)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;not&lt;/span&gt; os.path.exists(DOWNLOAD_PATH):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    os.makedirs(DOWNLOAD_PATH)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;browser = webdriver.Chrome()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;browser.get(&lt;span class=&#34;string&#34;&gt;&amp;#x27;https://image.so.com/z?ch=beauty&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;browser.implicitly_wait(&lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;kw_input = browser.find_element(By.CSS_SELECTOR, &lt;span class=&#34;string&#34;&gt;&amp;#x27;input[name=q]&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;kw_input.send_keys(&lt;span class=&#34;string&#34;&gt;&amp;#x27;苍老师&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;kw_input.send_keys(Keys.ENTER)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; _ &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; &lt;span class=&#34;built_in&#34;&gt;range&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    browser.execute_script(&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;string&#34;&gt;&amp;#x27;document.documentElement.scrollTop = document.documentElement.scrollHeight&amp;#x27;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    )&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    time.sleep(&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;imgs = browser.find_elements(By.CSS_SELECTOR, &lt;span class=&#34;string&#34;&gt;&amp;#x27;div.waterfall img&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;with&lt;/span&gt; ThreadPoolExecutor(max_workers=&lt;span class=&#34;number&#34;&gt;32&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;as&lt;/span&gt; pool:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; img &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; imgs:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        pic_url = img.get_attribute(&lt;span class=&#34;string&#34;&gt;&amp;#x27;src&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        pool.submit(download_picture, pic_url)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;运行上面的代码，检查指定的目录下是否下载了根据关键词搜索到的图片。&lt;/p&gt;

 &lt;h2 id=&#34;Python中的并发编程-3&#34;&gt;&lt;a href=&#34;#Python中的并发编程-3&#34; class=&#34;headerlink&#34; title=&#34;Python中的并发编程-3&#34;&gt;&lt;/a&gt;Python中的并发编程-3&lt;/h2&gt;&lt;p&gt;爬虫是典型的 I&amp;#x2F;O 密集型任务，I&amp;#x2F;O 密集型任务的特点就是程序会经常性的因为 I&amp;#x2F;O 操作而进入阻塞状态，比如我们之前使用&lt;code&gt;requests&lt;/code&gt;获取页面代码或二进制内容，发出一个请求之后，程序必须要等待网站返回响应之后才能继续运行，如果目标网站不是很给力或者网络状况不是很理想，那么等待响应的时间可能会很久，而在这个过程中整个程序是一直阻塞在那里，没有做任何的事情。通过前面的课程，我们已经知道了可以通过多线程的方式为爬虫提速，使用多线程的本质就是，当一个线程阻塞的时候，程序还有其他的线程可以继续运转，因此整个程序就不会在阻塞和等待中浪费了大量的时间。&lt;/p&gt;
&lt;p&gt;事实上，还有一种非常适合 I&amp;#x2F;O 密集型任务的并发编程方式，我们称之为异步编程，你也可以将它称为异步 I&amp;#x2F;O。这种方式并不需要启动多个线程或多个进程来实现并发，它是通过多个子程序相互协作的方式来提升 CPU 的利用率，解决了 I&amp;#x2F;O 密集型任务 CPU  利用率很低的问题，我一般将这种方式称为“协作式并发”。这里，我不打算探讨操作系统的各种 I&amp;#x2F;O 模式，因为这对很多读者来说都太过抽象；但是我们得先抛出两组概念给大家，一组叫做“阻塞”和“非阻塞”，一组叫做“同步”和“异步”。&lt;/p&gt;
&lt;h3 id=&#34;基本概念&#34;&gt;&lt;a href=&#34;#基本概念&#34; class=&#34;headerlink&#34; title=&#34;基本概念&#34;&gt;&lt;/a&gt;基本概念&lt;/h3&gt;&lt;h4 id=&#34;阻塞&#34;&gt;&lt;a href=&#34;#阻塞&#34; class=&#34;headerlink&#34; title=&#34;阻塞&#34;&gt;&lt;/a&gt;阻塞&lt;/h4&gt;&lt;p&gt;阻塞状态指程序未得到所需计算资源时被挂起的状态。程序在等待某个操作完成期间，自身无法继续处理其他的事情，则称该程序在该操作上是阻塞的。阻塞随时都可能发生，最典型的就是 I&amp;#x2F;O 中断（包括网络 I&amp;#x2F;O 、磁盘 I&amp;#x2F;O 、用户输入等）、休眠操作、等待某个线程执行结束，甚至包括在 CPU 切换上下文时，程序都无法真正的执行，这就是所谓的阻塞。&lt;/p&gt;
&lt;h4 id=&#34;非阻塞&#34;&gt;&lt;a href=&#34;#非阻塞&#34; class=&#34;headerlink&#34; title=&#34;非阻塞&#34;&gt;&lt;/a&gt;非阻塞&lt;/h4&gt;&lt;p&gt;程序在等待某操作过程中，自身不被阻塞，可以继续处理其他的事情，则称该程序在该操作上是非阻塞的。非阻塞并不是在任何程序级别、任何情况下都可以存在的。仅当程序封装的级别可以囊括独立的子程序单元时，它才可能存在非阻塞状态。显然，某个操作的阻塞可能会导程序耗时以及效率低下，所以我们会希望把它变成非阻塞的。&lt;/p&gt;
&lt;h4 id=&#34;同步&#34;&gt;&lt;a href=&#34;#同步&#34; class=&#34;headerlink&#34; title=&#34;同步&#34;&gt;&lt;/a&gt;同步&lt;/h4&gt;&lt;p&gt;不同程序单元为了完成某个任务，在执行过程中需靠某种通信方式以协调一致，我们称这些程序单元是同步执行的。例如前面讲过的给银行账户存钱的操作，我们在代码中使用了“锁”作为通信信号，让多个存钱操作强制排队顺序执行，这就是所谓的同步。&lt;/p&gt;
&lt;h4 id=&#34;异步&#34;&gt;&lt;a href=&#34;#异步&#34; class=&#34;headerlink&#34; title=&#34;异步&#34;&gt;&lt;/a&gt;异步&lt;/h4&gt;&lt;p&gt;不同程序单元在执行过程中无需通信协调，也能够完成一个任务，这种方式我们就称之为异步。例如，使用爬虫下载页面时，调度程序调用下载程序后，即可调度其他任务，而无需与该下载任务保持通信以协调行为。不同网页的下载、保存等操作都是不相关的，也无需相互通知协调。很显然，异步操作的完成时刻和先后顺序并不能确定。&lt;/p&gt;
&lt;p&gt;很多人都不太能准确的把握这几个概念，这里我们简单的总结一下，同步与异步的关注点是&lt;strong&gt;消息通信机制&lt;/strong&gt;，最终表现出来的是“有序”和“无序”的区别；阻塞和非阻塞的关注点是&lt;strong&gt;程序在等待消息时状态&lt;/strong&gt;，最终表现出来的是程序在等待时能不能做点别的。如果想深入理解这些内容，推荐大家阅读经典著作&lt;a href=&#34;https://item.jd.com/11880047.html&#34;&gt;《UNIX网络编程》&lt;/a&gt;，这本书非常的赞。&lt;/p&gt;
&lt;h3 id=&#34;生成器和协程&#34;&gt;&lt;a href=&#34;#生成器和协程&#34; class=&#34;headerlink&#34; title=&#34;生成器和协程&#34;&gt;&lt;/a&gt;生成器和协程&lt;/h3&gt;&lt;p&gt;前面我们说过，异步编程是一种“协作式并发”，即通过多个子程序相互协作的方式提升 CPU 的利用率，从而减少程序在阻塞和等待中浪费的时间，最终达到并发的效果。我们可以将多个相互协作的子程序称为“协程”，它是实现异步编程的关键。在介绍协程之前，我们先通过下面的代码，看看什么是生成器。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;fib&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;max_count&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    a, b = &lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; _ &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; &lt;span class=&#34;built_in&#34;&gt;range&lt;/span&gt;(max_count):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        a, b = b, a + b&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;yield&lt;/span&gt; a&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;上面我们编写了一个生成斐波那契数列的生成器，调用上面的&lt;code&gt;fib&lt;/code&gt;函数并不是执行该函数获得返回值，因为&lt;code&gt;fib&lt;/code&gt;函数中有一个特殊的关键字&lt;code&gt;yield&lt;/code&gt;。这个关键字使得&lt;code&gt;fib&lt;/code&gt;函数跟普通的函数有些区别，调用该函数会得到一个生成器对象，我们可以通过下面的代码来验证这一点。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;gen_obj = fib(&lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(gen_obj)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight maxima&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&amp;lt;generator object &lt;span class=&#34;built_in&#34;&gt;fib&lt;/span&gt; &lt;span class=&#34;built_in&#34;&gt;at&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;0x106daee40&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;我们可以使用内置函数&lt;code&gt;next&lt;/code&gt;从生成器对象中获取斐波那契数列的值，也可以通过&lt;code&gt;for-in&lt;/code&gt;循环对生成器能够提供的值进行遍历，代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; value &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; gen_obj:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(value)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;生成器经过预激活，就是一个协程，它可以跟其他子程序协作。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;calc_average&lt;/span&gt;():&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    total, counter = &lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    avg_value = &lt;span class=&#34;literal&#34;&gt;None&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;while&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;True&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        curr_value = &lt;span class=&#34;keyword&#34;&gt;yield&lt;/span&gt; avg_value&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        total += curr_value&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        counter += &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        avg_value = total / counter&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;main&lt;/span&gt;():&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    obj = calc_average()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 生成器预激活&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    obj.send(&lt;span class=&#34;literal&#34;&gt;None&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; _ &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; &lt;span class=&#34;built_in&#34;&gt;range&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;5&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(obj.send(&lt;span class=&#34;built_in&#34;&gt;float&lt;/span&gt;(&lt;span class=&#34;built_in&#34;&gt;input&lt;/span&gt;())))&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; __name__ == &lt;span class=&#34;string&#34;&gt;&amp;#x27;__main__&amp;#x27;&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    main()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;上面的&lt;code&gt;main&lt;/code&gt;函数首先通过生成器对象的&lt;code&gt;send&lt;/code&gt;方法发送一个&lt;code&gt;None&lt;/code&gt;值来将其激活为协程，也可以通过&lt;code&gt;next(obj)&lt;/code&gt;达到同样的效果。接下来，协程对象会接收&lt;code&gt;main&lt;/code&gt;函数发送的数据并产出（&lt;code&gt;yield&lt;/code&gt;）数据的平均值。通过上面的例子，不知道大家是否看出两段子程序是怎么“协作”的。&lt;/p&gt;
&lt;h3 id=&#34;异步函数&#34;&gt;&lt;a href=&#34;#异步函数&#34; class=&#34;headerlink&#34; title=&#34;异步函数&#34;&gt;&lt;/a&gt;异步函数&lt;/h3&gt;&lt;p&gt;Python 3.5版本中，引入了两个非常有意思的元素，一个叫&lt;code&gt;async&lt;/code&gt;，一个叫&lt;code&gt;await&lt;/code&gt;，它们在Python 3.7版本中成为了正式的关键字。通过这两个关键字，可以简化协程代码的编写，可以用更为简单的方式让多个子程序很好的协作起来。我们通过一个例子来加以说明，请大家先看看下面的代码。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; time&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;display&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;num&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    time.sleep(&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(num)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;main&lt;/span&gt;():&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    start = time.time()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; i &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; &lt;span class=&#34;built_in&#34;&gt;range&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        display(i)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    end = time.time()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;f&amp;#x27;&lt;span class=&#34;subst&#34;&gt;&amp;#123;end - start:&lt;span class=&#34;number&#34;&gt;.3&lt;/span&gt;f&amp;#125;&lt;/span&gt;秒&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; __name__ == &lt;span class=&#34;string&#34;&gt;&amp;#x27;__main__&amp;#x27;&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    main()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;上面的代码每次执行都会依次输出&lt;code&gt;1&lt;/code&gt;到&lt;code&gt;9&lt;/code&gt;的数字，每个间隔&lt;code&gt;1&lt;/code&gt;秒钟，整个代码需要执行大概需要&lt;code&gt;9&lt;/code&gt;秒多的时间，这一点我相信大家都能看懂。不知道大家是否意识到，这段代码就是以同步和阻塞的方式执行的，同步可以从代码的输出看出来，而阻塞是指在调用&lt;code&gt;display&lt;/code&gt;函数发生休眠时，整个代码的其他部分都不能继续执行，必须等待休眠结束。&lt;/p&gt;
&lt;p&gt;接下来，我们尝试用异步的方式改写上面的代码，让&lt;code&gt;display&lt;/code&gt;函数以异步的方式运转。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; asyncio&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; time&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;async&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;display&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;num&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;await&lt;/span&gt; asyncio.sleep(&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(num)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;main&lt;/span&gt;():&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    start = time.time()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    objs = [display(i) &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; i &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; &lt;span class=&#34;built_in&#34;&gt;range&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;)]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    loop = asyncio.get_event_loop()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    loop.run_until_complete(asyncio.wait(objs))&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    loop.close()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    end = time.time()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;f&amp;#x27;&lt;span class=&#34;subst&#34;&gt;&amp;#123;end - start:&lt;span class=&#34;number&#34;&gt;.3&lt;/span&gt;f&amp;#125;&lt;/span&gt;秒&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; __name__ == &lt;span class=&#34;string&#34;&gt;&amp;#x27;__main__&amp;#x27;&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    main()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;Python 中的&lt;code&gt;asyncio&lt;/code&gt;模块提供了对异步 I&amp;#x2F;O 的支持。上面的代码中，我们首先在&lt;code&gt;display&lt;/code&gt;函数前面加上了&lt;code&gt;async&lt;/code&gt;关键字使其变成一个异步函数，调用异步函数不会执行函数体而是获得一个协程对象。我们将&lt;code&gt;display&lt;/code&gt;函数中的&lt;code&gt;time.sleep(1)&lt;/code&gt;修改为&lt;code&gt;await asyncio.sleep(1)&lt;/code&gt;，二者的区别在于，后者不会让整个代码陷入阻塞，因为&lt;code&gt;await&lt;/code&gt;操作会让其他协作的子程序有获得 CPU 资源而得以运转的机会。为了让这些子程序可以协作起来，我们需要将他们放到一个事件循环（实现消息分派传递的系统）上，因为&lt;strong&gt;当协程遭遇 I&amp;#x2F;O 操作阻塞时，就会到事件循环中监听 I&amp;#x2F;O 操作是否完成，并注册自身的上下文以及自身的唤醒函数（以便恢复执行），之后该协程就变为阻塞状态&lt;/strong&gt;。上面的第12行代码创建了&lt;code&gt;9&lt;/code&gt;个协程对象并放到一个列表中，第13行代码通过&lt;code&gt;asyncio&lt;/code&gt;模块的&lt;code&gt;get_event_loop&lt;/code&gt;函数获得了系统的事件循环，第14行通过&lt;code&gt;asyncio&lt;/code&gt;模块的&lt;code&gt;run_until_complete&lt;/code&gt;函数将协程对象挂载到事件循环上。执行上面的代码会发现，&lt;code&gt;9&lt;/code&gt;个分别会阻塞&lt;code&gt;1&lt;/code&gt;秒钟的协程总共只阻塞了约&lt;code&gt;1&lt;/code&gt;秒种的时间，因为&lt;strong&gt;阻塞的协程对象会放弃对 CPU 的占有而不是让 CPU 处于闲置状态，这种方式大大的提升了 CPU 的利用率&lt;/strong&gt;。而且我们还会注意到，数字并不是按照从&lt;code&gt;1&lt;/code&gt;到&lt;code&gt;9&lt;/code&gt;的顺序打印输出的，这正是我们想要的结果，说明它们是&lt;strong&gt;异步执行&lt;/strong&gt;的。对于爬虫这样的 I&amp;#x2F;O 密集型任务来说，这种协作式并发在很多场景下是比使用多线程更好的选择，因为这种做法减少了管理和维护多个线程以及多个线程切换所带来的开销。&lt;/p&gt;
&lt;h3 id=&#34;aiohttp库&#34;&gt;&lt;a href=&#34;#aiohttp库&#34; class=&#34;headerlink&#34; title=&#34;aiohttp库&#34;&gt;&lt;/a&gt;aiohttp库&lt;/h3&gt;&lt;p&gt;我们之前使用的&lt;code&gt;requests&lt;/code&gt;三方库并不支持异步 I&amp;#x2F;O，如果希望使用异步 I&amp;#x2F;O 的方式来加速爬虫代码的执行，我们可以安装和使用名为&lt;code&gt;aiohttp&lt;/code&gt;的三方库。&lt;/p&gt;
&lt;p&gt;安装&lt;code&gt;aiohttp&lt;/code&gt;。&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;pip install aiohttp&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;下面的代码使用&lt;code&gt;aiohttp&lt;/code&gt;抓取了&lt;code&gt;10&lt;/code&gt;个网站的首页并解析出它们的标题。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; asyncio&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; re&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; aiohttp&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; aiohttp &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; ClientSession&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;TITLE_PATTERN = re.&lt;span class=&#34;built_in&#34;&gt;compile&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;r&amp;#x27;&amp;lt;title.*?&amp;gt;(.*?)&amp;lt;/title&amp;gt;&amp;#x27;&lt;/span&gt;, re.DOTALL)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;async&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;fetch_page_title&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;url&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;async&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;with&lt;/span&gt; aiohttp.ClientSession(headers=&amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;string&#34;&gt;&amp;#x27;User-Agent&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;Mozilla/5.0 (Macintosh; Intel Mac OS X 10_14_6) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/95.0.4638.69 Safari/537.36&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &amp;#125;) &lt;span class=&#34;keyword&#34;&gt;as&lt;/span&gt; session:  &lt;span class=&#34;comment&#34;&gt;# type: ClientSession&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;async&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;with&lt;/span&gt; session.get(url, ssl=&lt;span class=&#34;literal&#34;&gt;False&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;as&lt;/span&gt; resp:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; resp.status == &lt;span class=&#34;number&#34;&gt;200&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                html_code = &lt;span class=&#34;keyword&#34;&gt;await&lt;/span&gt; resp.text()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                matcher = TITLE_PATTERN.search(html_code)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                title = matcher.group(&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;).strip()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                &lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(title)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;main&lt;/span&gt;():&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    urls = [&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;string&#34;&gt;&amp;#x27;https://www.python.org/&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;string&#34;&gt;&amp;#x27;https://www.jd.com/&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;string&#34;&gt;&amp;#x27;https://www.baidu.com/&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;string&#34;&gt;&amp;#x27;https://www.taobao.com/&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;string&#34;&gt;&amp;#x27;https://git-scm.com/&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;string&#34;&gt;&amp;#x27;https://www.sohu.com/&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;string&#34;&gt;&amp;#x27;https://gitee.com/&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;string&#34;&gt;&amp;#x27;https://www.amazon.com/&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;string&#34;&gt;&amp;#x27;https://www.usa.gov/&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;string&#34;&gt;&amp;#x27;https://www.nasa.gov/&amp;#x27;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    ]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    objs = [fetch_page_title(url) &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; url &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; urls]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    loop = asyncio.get_event_loop()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    loop.run_until_complete(asyncio.wait(objs))&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    loop.close()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; __name__ == &lt;span class=&#34;string&#34;&gt;&amp;#x27;__main__&amp;#x27;&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    main()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;输出：&lt;/p&gt;
&lt;figure class=&#34;highlight llvm&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;京东(JD.COM)-正品低价、品质保障、配送及时、轻松购物！&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;搜狐&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;淘宝网 - 淘！我喜欢&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;百度一下，你就知道&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;Gitee - 基于 Git 的代码托管和研发协作平台&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;Git&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;NASA&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;Official Guide &lt;span class=&#34;keyword&#34;&gt;to&lt;/span&gt; Government Information &lt;span class=&#34;keyword&#34;&gt;and&lt;/span&gt; Services   &amp;amp;&lt;span class=&#34;variable&#34;&gt;#124&lt;/span&gt;&lt;span class=&#34;comment&#34;&gt;; USAGov&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;Amazon.com. Spend less. Smile more.&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;Welcome &lt;span class=&#34;keyword&#34;&gt;to&lt;/span&gt; Python.org&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;从上面的输出可以看出，网站首页标题的输出顺序跟它们的 URL 在列表中的顺序没有关系。代码的第11行到第13行创建了&lt;code&gt;ClientSession&lt;/code&gt;对象，通过它的&lt;code&gt;get&lt;/code&gt;方法可以向指定的 URL 发起请求，如第14行所示，跟&lt;code&gt;requests&lt;/code&gt;中的&lt;code&gt;Session&lt;/code&gt;对象并没有本质区别，唯一的区别是这里使用了异步上下文。代码第16行的&lt;code&gt;await&lt;/code&gt;会让因为 I&amp;#x2F;O 操作阻塞的子程序放弃对 CPU 的占用，这使得其他的子程序可以运转起来去抓取页面。代码的第17行和第18行使用了正则表达式捕获组操作解析网页标题。&lt;code&gt;fetch_page_title&lt;/code&gt;是一个被&lt;code&gt;async&lt;/code&gt;关键字修饰的异步函数，调用该函数会获得协程对象，如代码第35行所示。后面的代码跟之前的例子没有什么区别，相信大家能够理解。&lt;/p&gt;
&lt;p&gt;大家可以尝试将&lt;code&gt;aiohttp&lt;/code&gt;换回到&lt;code&gt;requests&lt;/code&gt;，看看不使用异步 I&amp;#x2F;O 也不使用多线程，到底和上面的代码有什么区别，相信通过这样的对比，大家能够更深刻的理解我们之前强调的几个概念：同步和异步，阻塞和非阻塞。&lt;/p&gt;

 &lt;h2 id=&#34;Python中的并发编程-2&#34;&gt;&lt;a href=&#34;#Python中的并发编程-2&#34; class=&#34;headerlink&#34; title=&#34;Python中的并发编程-2&#34;&gt;&lt;/a&gt;Python中的并发编程-2&lt;/h2&gt;&lt;p&gt;在上一课中我们说过，由于 GIL 的存在，CPython 中的多线程并不能发挥 CPU 的多核优势，如果希望突破 GIL 的限制，可以考虑使用多进程。对于多进程的程序，每个进程都有一个属于自己的 GIL，所以多进程不会受到 GIL 的影响。那么，我们应该如何在 Python 程序中创建和使用多进程呢？&lt;/p&gt;
&lt;p&gt;###创建进程&lt;/p&gt;
&lt;p&gt;在 Python 中可以基于&lt;code&gt;Process&lt;/code&gt;类来创建进程，虽然进程和线程有着本质的差别，但是&lt;code&gt;Process&lt;/code&gt;类和&lt;code&gt;Thread&lt;/code&gt;类的用法却非常类似。在使用&lt;code&gt;Process&lt;/code&gt;类的构造器创建对象时，也是通过&lt;code&gt;target&lt;/code&gt;参数传入一个函数来指定进程要执行的代码，而&lt;code&gt;args&lt;/code&gt;和&lt;code&gt;kwargs&lt;/code&gt;参数可以指定该函数使用的参数值。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; multiprocessing &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; Process, current_process&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; time &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; sleep&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;sub_task&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;content, nums&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 通过current_process函数获取当前进程对象&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 通过进程对象的pid和name属性获取进程的ID号和名字&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;f&amp;#x27;PID: &lt;span class=&#34;subst&#34;&gt;&amp;#123;current_process().pid&amp;#125;&lt;/span&gt;&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;f&amp;#x27;Name: &lt;span class=&#34;subst&#34;&gt;&amp;#123;current_process().name&amp;#125;&lt;/span&gt;&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 通过下面的输出不难发现，每个进程都有自己的nums列表，进程之间本就不共享内存&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 在创建子进程时复制了父进程的数据结构，三个进程从列表中pop(0)得到的值都是20&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    counter, total = &lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;, nums.pop(&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;f&amp;#x27;Loop count: &lt;span class=&#34;subst&#34;&gt;&amp;#123;total&amp;#125;&lt;/span&gt;&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    sleep(&lt;span class=&#34;number&#34;&gt;0.5&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;while&lt;/span&gt; counter &amp;lt; total:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        counter += &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;f&amp;#x27;&lt;span class=&#34;subst&#34;&gt;&amp;#123;counter&amp;#125;&lt;/span&gt;: &lt;span class=&#34;subst&#34;&gt;&amp;#123;content&amp;#125;&lt;/span&gt;&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        sleep(&lt;span class=&#34;number&#34;&gt;0.01&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;main&lt;/span&gt;():&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    nums = [&lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;30&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;40&lt;/span&gt;]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 创建并启动进程来执行指定的函数&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    Process(target=sub_task, args=(&lt;span class=&#34;string&#34;&gt;&amp;#x27;Ping&amp;#x27;&lt;/span&gt;, nums)).start()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    Process(target=sub_task, args=(&lt;span class=&#34;string&#34;&gt;&amp;#x27;Pong&amp;#x27;&lt;/span&gt;, nums)).start()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 在主进程中执行sub_task函数&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    sub_task(&lt;span class=&#34;string&#34;&gt;&amp;#x27;Good&amp;#x27;&lt;/span&gt;, nums)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; __name__ == &lt;span class=&#34;string&#34;&gt;&amp;#x27;__main__&amp;#x27;&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    main()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;说明&lt;/strong&gt;：上面的代码通过&lt;code&gt;current_process&lt;/code&gt;函数获取当前进程对象，再通过进程对象的&lt;code&gt;pid&lt;/code&gt;属性获取进程ID。在 Python 中，使用&lt;code&gt;os&lt;/code&gt;模块的&lt;code&gt;getpid&lt;/code&gt;函数也可以达到同样的效果。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;如果愿意，也可以使用&lt;code&gt;os&lt;/code&gt;模块的&lt;code&gt;fork&lt;/code&gt;函数来创建进程，调用该函数时，操作系统自动把当前进程（父进程）复制一份（子进程），父进程的&lt;code&gt;fork&lt;/code&gt;函数会返回子进程的ID，而子进程中的&lt;code&gt;fork&lt;/code&gt;函数会返回&lt;code&gt;0&lt;/code&gt;，也就是说这个函数调用一次会在父进程和子进程中得到两个不同的返回值。需要注意的是，Windows 系统并不支持&lt;code&gt;fork&lt;/code&gt;函数，如果你使用的是 Linux 或 macOS 系统，可以试试下面的代码。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; os&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;f&amp;#x27;PID: &lt;span class=&#34;subst&#34;&gt;&amp;#123;os.getpid()&amp;#125;&lt;/span&gt;&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;pid = os.fork()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; pid == &lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;f&amp;#x27;子进程 - PID: &lt;span class=&#34;subst&#34;&gt;&amp;#123;os.getpid()&amp;#125;&lt;/span&gt;&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&amp;#x27;Todo: 在子进程中执行的代码&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;else&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;f&amp;#x27;父进程 - PID: &lt;span class=&#34;subst&#34;&gt;&amp;#123;os.getpid()&amp;#125;&lt;/span&gt;&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&amp;#x27;Todo: 在父进程中执行的代码&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;简而言之，我们还是推荐大家通过直接使用&lt;code&gt;Process&lt;/code&gt;类、继承&lt;code&gt;Process&lt;/code&gt;类和使用进程池（&lt;code&gt;ProcessPoolExecutor&lt;/code&gt;）这三种方式来创建和使用多进程，这三种方式不同于上面的&lt;code&gt;fork&lt;/code&gt;函数，能够保证代码的兼容性和可移植性。具体的做法跟之前讲过的创建和使用多线程的方式比较接近，此处不再进行赘述。&lt;/p&gt;
&lt;h3 id=&#34;多进程和多线程的比较&#34;&gt;&lt;a href=&#34;#多进程和多线程的比较&#34; class=&#34;headerlink&#34; title=&#34;多进程和多线程的比较&#34;&gt;&lt;/a&gt;多进程和多线程的比较&lt;/h3&gt;&lt;p&gt;对于爬虫这类 I&amp;#x2F;O 密集型任务来说，使用多进程并没有什么优势；但是对于计算密集型任务来说，多进程相比多线程，在效率上会有显著的提升，我们可以通过下面的代码来加以证明。下面的代码会通过多线程和多进程两种方式来判断一组大整数是不是质数，很显然这是一个计算密集型任务，我们将任务分别放到多个线程和多个进程中来加速代码的执行，让我们看看多线程和多进程的代码具体表现有何不同。&lt;/p&gt;
&lt;p&gt;我们先实现一个多线程的版本，代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; concurrent.futures&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;PRIMES = [&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;number&#34;&gt;1116281&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;number&#34;&gt;1297337&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;number&#34;&gt;104395303&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;number&#34;&gt;472882027&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;number&#34;&gt;533000389&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;number&#34;&gt;817504243&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;number&#34;&gt;982451653&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;number&#34;&gt;112272535095293&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;number&#34;&gt;112582705942171&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;number&#34;&gt;112272535095293&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;number&#34;&gt;115280095190773&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;number&#34;&gt;115797848077099&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;number&#34;&gt;1099726899285419&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;] * &lt;span class=&#34;number&#34;&gt;5&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;is_prime&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;n&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;&amp;quot;&amp;quot;判断素数&amp;quot;&amp;quot;&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; i &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; &lt;span class=&#34;built_in&#34;&gt;range&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;, &lt;span class=&#34;built_in&#34;&gt;int&lt;/span&gt;(n ** &lt;span class=&#34;number&#34;&gt;0.5&lt;/span&gt;) + &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; n % i == &lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;False&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; n != &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;main&lt;/span&gt;():&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;&amp;quot;&amp;quot;主函数&amp;quot;&amp;quot;&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;with&lt;/span&gt; concurrent.futures.ThreadPoolExecutor(max_workers=&lt;span class=&#34;number&#34;&gt;16&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;as&lt;/span&gt; executor:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; number, prime &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; &lt;span class=&#34;built_in&#34;&gt;zip&lt;/span&gt;(PRIMES, executor.&lt;span class=&#34;built_in&#34;&gt;map&lt;/span&gt;(is_prime, PRIMES)):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&amp;#x27;%d is prime: %s&amp;#x27;&lt;/span&gt; % (number, prime))&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; __name__ == &lt;span class=&#34;string&#34;&gt;&amp;#x27;__main__&amp;#x27;&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    main()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;假设上面的代码保存在名为&lt;code&gt;example.py&lt;/code&gt;的文件中，在 Linux 或 macOS 系统上，可以使用&lt;code&gt;time python example.py&lt;/code&gt;命令执行程序并获得操作系统关于执行时间的统计，在我的 macOS 上，某次的运行结果的最后一行输出如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight apache&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;python&lt;/span&gt; example09.py  &lt;span class=&#34;number&#34;&gt;38&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;69&lt;/span&gt;s user &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;01&lt;/span&gt;s system &lt;span class=&#34;number&#34;&gt;101&lt;/span&gt;% cpu &lt;span class=&#34;number&#34;&gt;39&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;213&lt;/span&gt; total&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;从运行结果可以看出，多线程的代码只能让 CPU 利用率达到100%，这其实已经证明了多线程的代码无法利用 CPU 多核特性来加速代码的执行，我们再看看多进程的版本，我们将上面代码中的线程池（&lt;code&gt;ThreadPoolExecutor&lt;/code&gt;）更换为进程池（&lt;code&gt;ProcessPoolExecutor&lt;/code&gt;）。&lt;/p&gt;
&lt;p&gt;多进程的版本。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; concurrent.futures&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;PRIMES = [&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;number&#34;&gt;1116281&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;number&#34;&gt;1297337&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;number&#34;&gt;104395303&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;number&#34;&gt;472882027&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;number&#34;&gt;533000389&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;number&#34;&gt;817504243&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;number&#34;&gt;982451653&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;number&#34;&gt;112272535095293&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;number&#34;&gt;112582705942171&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;number&#34;&gt;112272535095293&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;number&#34;&gt;115280095190773&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;number&#34;&gt;115797848077099&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;number&#34;&gt;1099726899285419&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;] * &lt;span class=&#34;number&#34;&gt;5&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;is_prime&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;n&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;&amp;quot;&amp;quot;判断素数&amp;quot;&amp;quot;&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; i &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; &lt;span class=&#34;built_in&#34;&gt;range&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;, &lt;span class=&#34;built_in&#34;&gt;int&lt;/span&gt;(n ** &lt;span class=&#34;number&#34;&gt;0.5&lt;/span&gt;) + &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; n % i == &lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;False&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; n != &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;main&lt;/span&gt;():&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;&amp;quot;&amp;quot;主函数&amp;quot;&amp;quot;&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;with&lt;/span&gt; concurrent.futures.ProcessPoolExecutor(max_workers=&lt;span class=&#34;number&#34;&gt;16&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;as&lt;/span&gt; executor:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; number, prime &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; &lt;span class=&#34;built_in&#34;&gt;zip&lt;/span&gt;(PRIMES, executor.&lt;span class=&#34;built_in&#34;&gt;map&lt;/span&gt;(is_prime, PRIMES)):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&amp;#x27;%d is prime: %s&amp;#x27;&lt;/span&gt; % (number, prime))&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; __name__ == &lt;span class=&#34;string&#34;&gt;&amp;#x27;__main__&amp;#x27;&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    main()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;提示&lt;/strong&gt;：运行上面的代码时，可以通过操作系统的任务管理器（资源监视器）来查看是否启动了多个 Python  解释器进程。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;我们仍然通过&lt;code&gt;time python example.py&lt;/code&gt;的方式来执行上述代码，运行结果的最后一行如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight apache&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;python&lt;/span&gt; example09.py &lt;span class=&#34;number&#34;&gt;106&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;63&lt;/span&gt;s user &lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;57&lt;/span&gt;s system &lt;span class=&#34;number&#34;&gt;389&lt;/span&gt;% cpu &lt;span class=&#34;number&#34;&gt;27&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;497&lt;/span&gt; total&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;可以看出，多进程的版本在我使用的这台电脑上，让 CPU 的利用率达到了将近400%，而运行代码时用户态耗费的 CPU 的时间（106.63秒）几乎是代码运行总时间（27.497秒）的4倍，从这两点都可以看出，我的电脑使用了一款4核的 CPU。当然，要知道自己的电脑有几个 CPU 或几个核，可以直接使用下面的代码。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; os&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(os.cpu_count())&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;综上所述，多进程可以突破 GIL 的限制，充分利用 CPU 多核特性，对于计算密集型任务，这一点是相当重要的。常见的计算密集型任务包括科学计算、图像处理、音视频编解码等，如果这些计算密集型任务本身是可以并行的，那么使用多进程应该是更好的选择。&lt;/p&gt;
&lt;h3 id=&#34;进程间通信&#34;&gt;&lt;a href=&#34;#进程间通信&#34; class=&#34;headerlink&#34; title=&#34;进程间通信&#34;&gt;&lt;/a&gt;进程间通信&lt;/h3&gt;&lt;p&gt;在讲解进程间通信之前，先给大家一个任务：启动两个进程，一个输出“Ping”，一个输出“Pong”，两个进程输出的“Ping”和“Pong”加起来一共有50个时，就结束程序。听起来是不是非常简单，但是实际编写代码时，由于多个进程之间不能够像多个线程之间直接通过共享内存的方式交换数据，所以下面的代码是达不到我们想要的结果的。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; multiprocessing &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; Process&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; time &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; sleep&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;counter = &lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;sub_task&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;string&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;global&lt;/span&gt; counter&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;while&lt;/span&gt; counter &amp;lt; &lt;span class=&#34;number&#34;&gt;50&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(string, end=&lt;span class=&#34;string&#34;&gt;&amp;#x27;&amp;#x27;&lt;/span&gt;, flush=&lt;span class=&#34;literal&#34;&gt;True&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        counter += &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        sleep(&lt;span class=&#34;number&#34;&gt;0.01&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;main&lt;/span&gt;():&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    Process(target=sub_task, args=(&lt;span class=&#34;string&#34;&gt;&amp;#x27;Ping&amp;#x27;&lt;/span&gt;, )).start()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    Process(target=sub_task, args=(&lt;span class=&#34;string&#34;&gt;&amp;#x27;Pong&amp;#x27;&lt;/span&gt;, )).start()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; __name__ == &lt;span class=&#34;string&#34;&gt;&amp;#x27;__main__&amp;#x27;&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    main()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;上面的代码看起来没毛病，但是最后的结果是“Ping”和“Pong”各输出了50个。再次提醒大家，当我们在程序中创建进程的时候，子进程会复制父进程及其所有的数据结构，每个子进程有自己独立的内存空间，这也就意味着两个子进程中各有一个&lt;code&gt;counter&lt;/code&gt;变量，它们都会从&lt;code&gt;0&lt;/code&gt;加到&lt;code&gt;50&lt;/code&gt;，所以结果就可想而知了。要解决这个问题比较简单的办法是使用&lt;code&gt;multiprocessing&lt;/code&gt;模块中的&lt;code&gt;Queue&lt;/code&gt;类，它是可以被多个进程共享的队列，底层是通过操作系统底层的管道和信号量（semaphore）机制来实现的，代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; time&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; multiprocessing &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; Process, Queue&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;sub_task&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;content, queue&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    counter = queue.get()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;while&lt;/span&gt; counter &amp;lt; &lt;span class=&#34;number&#34;&gt;50&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(content, end=&lt;span class=&#34;string&#34;&gt;&amp;#x27;&amp;#x27;&lt;/span&gt;, flush=&lt;span class=&#34;literal&#34;&gt;True&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        counter += &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        queue.put(counter)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        time.sleep(&lt;span class=&#34;number&#34;&gt;0.01&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        counter = queue.get()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;main&lt;/span&gt;():&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    queue = Queue()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    queue.put(&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    p1 = Process(target=sub_task, args=(&lt;span class=&#34;string&#34;&gt;&amp;#x27;Ping&amp;#x27;&lt;/span&gt;, queue))&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    p1.start()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    p2 = Process(target=sub_task, args=(&lt;span class=&#34;string&#34;&gt;&amp;#x27;Pong&amp;#x27;&lt;/span&gt;, queue))&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    p2.start()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;while&lt;/span&gt; p1.is_alive() &lt;span class=&#34;keyword&#34;&gt;and&lt;/span&gt; p2.is_alive():&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;pass&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    queue.put(&lt;span class=&#34;number&#34;&gt;50&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; __name__ == &lt;span class=&#34;string&#34;&gt;&amp;#x27;__main__&amp;#x27;&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    main()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;提示&lt;/strong&gt;：&lt;code&gt;multiprocessing.Queue&lt;/code&gt;对象的&lt;code&gt;get&lt;/code&gt;方法默认在队列为空时是会阻塞的，直到获取到数据才会返回。如果不希望该方法阻塞以及需要指定阻塞的超时时间，可以通过指定&lt;code&gt;block&lt;/code&gt;和&lt;code&gt;timeout&lt;/code&gt;参数进行设定。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;上面的代码通过&lt;code&gt;Queue&lt;/code&gt;类的&lt;code&gt;get&lt;/code&gt;和&lt;code&gt;put&lt;/code&gt;方法让三个进程（&lt;code&gt;p1&lt;/code&gt;、&lt;code&gt;p2&lt;/code&gt;和主进程）实现了数据的共享，这就是所谓的进程间的通信，通过这种方式，当&lt;code&gt;Queue&lt;/code&gt;中取出的值已经大于等于&lt;code&gt;50&lt;/code&gt;时，&lt;code&gt;p1&lt;/code&gt;和&lt;code&gt;p2&lt;/code&gt;就会跳出&lt;code&gt;while&lt;/code&gt;循环，从而终止进程的执行。代码第22行的循环是为了等待&lt;code&gt;p1&lt;/code&gt;和&lt;code&gt;p2&lt;/code&gt;两个进程中的一个结束，这时候主进程还需要向&lt;code&gt;Queue&lt;/code&gt;中放置一个大于等于&lt;code&gt;50&lt;/code&gt;的值，这样另一个尚未结束的进程也会因为读到这个大于等于&lt;code&gt;50&lt;/code&gt;的值而终止。&lt;/p&gt;
&lt;p&gt;进程间通信的方式还有很多，比如使用套接字也可以实现两个进程的通信，甚至于这两个进程并不在同一台主机上，有兴趣的读者可以自行了解。&lt;/p&gt;
&lt;h3 id=&#34;简单的总结&#34;&gt;&lt;a href=&#34;#简单的总结&#34; class=&#34;headerlink&#34; title=&#34;简单的总结&#34;&gt;&lt;/a&gt;简单的总结&lt;/h3&gt;&lt;p&gt;在 Python 中，我们还可以通过&lt;code&gt;subprocess&lt;/code&gt;模块的&lt;code&gt;call&lt;/code&gt;函数执行其他的命令来创建子进程，相当于就是在我们的程序中调用其他程序，这里我们暂不探讨这些知识，有兴趣的读者可以自行研究。&lt;/p&gt;
&lt;p&gt;对于Python开发者来说，以下情况需要考虑使用多线程：&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;程序需要维护许多共享的状态（尤其是可变状态），Python 中的列表、字典、集合都是线程安全的（多个线程同时操作同一个列表、字典或集合，不会引发错误和数据问题），所以使用线程而不是进程维护共享状态的代价相对较小。&lt;/li&gt;
&lt;li&gt;程序会花费大量时间在 I&amp;#x2F;O 操作上，没有太多并行计算的需求且不需占用太多的内存。&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;那么在遇到下列情况时，应该考虑使用多进程：&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;程序执行计算密集型任务（如：音视频编解码、数据压缩、科学计算等）。&lt;/li&gt;
&lt;li&gt;程序的输入可以并行的分成块，并且可以将运算结果合并。&lt;/li&gt;
&lt;li&gt;程序在内存使用方面没有任何限制且不强依赖于 I&amp;#x2F;O 操作（如读写文件、套接字等）。&lt;/li&gt;
&lt;/ol&gt;

 &lt;h2 id=&#34;Python中的并发编程-1&#34;&gt;&lt;a href=&#34;#Python中的并发编程-1&#34; class=&#34;headerlink&#34; title=&#34;Python中的并发编程-1&#34;&gt;&lt;/a&gt;Python中的并发编程-1&lt;/h2&gt;&lt;p&gt;现如今，我们使用的计算机早已是多 CPU 或多核的计算机，而我们使用的操作系统基本都支持“多任务”，这使得我们可以同时运行多个程序，也可以将一个程序分解为若干个相对独立的子任务，让多个子任务“并行”或“并发”的执行，从而缩短程序的执行时间，同时也让用户获得更好的体验。因此当下，不管用什么编程语言进行开发，实现“并行”或“并发”编程已经成为了程序员的标配技能。为了讲述如何在 Python 程序中实现“并行”或“并发”，我们需要先了解两个重要的概念：进程和线程。&lt;/p&gt;
&lt;h3 id=&#34;线程和进程&#34;&gt;&lt;a href=&#34;#线程和进程&#34; class=&#34;headerlink&#34; title=&#34;线程和进程&#34;&gt;&lt;/a&gt;线程和进程&lt;/h3&gt;&lt;p&gt;我们通过操作系统运行一个程序会创建出一个或多个进程，进程是具有一定独立功能的程序关于某个数据集合上的一次运行活动。简单的说，进程是操作系统分配存储空间的基本单位，每个进程都有自己的地址空间、数据栈以及其他用于跟踪进程执行的辅助数据；操作系统管理所有进程的执行，为它们合理的分配资源。一个进程可以通过 fork 或 spawn 的方式创建新的进程来执行其他的任务，不过新的进程也有自己独立的内存空间，因此两个进程如果要共享数据，必须通过进程间通信机制来实现，具体的方式包括管道、信号、套接字等。&lt;/p&gt;
&lt;p&gt;一个进程还可以拥有多个执行线索，简单的说就是拥有多个可以获得 CPU 调度的执行单元，这就是所谓的线程。由于线程在同一个进程下，它们可以共享相同的上下文，因此相对于进程而言，线程间的信息共享和通信更加容易。当然在单核 CPU 系统中，多个线程不可能同时执行，因为在某个时刻只有一个线程能够获得 CPU，多个线程通过共享 CPU 执行时间的方式来达到并发的效果。&lt;/p&gt;
&lt;p&gt;在程序中使用多线程技术通常都会带来不言而喻的好处，最主要的体现在提升程序的性能和改善用户体验，今天我们使用的软件几乎都用到了多线程技术，这一点可以利用系统自带的进程监控工具（如 macOS 中的“活动监视器”、Windows 中的“任务管理器”）来证实，如下图所示。&lt;/p&gt;
&lt;img src=&#34;https://gitee.com/jackfrued/mypic/raw/master/20210822094243.png&#34; width=&#34;80%&#34;&gt;

&lt;p&gt;这里，我们还需要跟大家再次强调两个概念：&lt;strong&gt;并发&lt;/strong&gt;（concurrency）和&lt;strong&gt;并行&lt;/strong&gt;（parallel）。&lt;strong&gt;并发&lt;/strong&gt;通常是指同一时刻只能有一条指令执行，但是多个线程对应的指令被快速轮换地执行。比如一个处理器，它先执行线程 A 的指令一段时间，再执行线程 B 的指令一段时间，再切回到线程 A 执行一段时间。由于处理器执行指令的速度和切换的速度极快，人们完全感知不到计算机在这个过程中有多个线程切换上下文执行的操作，这就使得宏观上看起来多个线程在同时运行，但微观上其实只有一个线程在执行。&lt;strong&gt;并行&lt;/strong&gt;是指同一时刻，有多条指令在多个处理器上同时执行，并行必须要依赖于多个处理器，不论是从宏观上还是微观上，多个线程可以在同一时刻一起执行的。很多时候，我们并不用严格区分并发和并行两个词，所以我们有时候也把 Python 中的多线程、多进程以及异步 I&amp;#x2F;O 都视为实现并发编程的手段，但实际上前面两者也可以实现并行编程，当然这里还有一个全局解释器锁（GIL）的问题，我们稍后讨论。&lt;/p&gt;
&lt;h3 id=&#34;多线程编程&#34;&gt;&lt;a href=&#34;#多线程编程&#34; class=&#34;headerlink&#34; title=&#34;多线程编程&#34;&gt;&lt;/a&gt;多线程编程&lt;/h3&gt;&lt;p&gt;Python 标准库中&lt;code&gt;threading&lt;/code&gt;模块的&lt;code&gt;Thread&lt;/code&gt;类可以帮助我们非常轻松的实现多线程编程。我们用一个联网下载文件的例子来对比使用多线程和不使用多线程到底有什么区别，代码如下所示。&lt;/p&gt;
&lt;p&gt;不使用多线程的下载。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; random&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; time&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;download&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;*, filename&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    start = time.time()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;f&amp;#x27;开始下载 &lt;span class=&#34;subst&#34;&gt;&amp;#123;filename&amp;#125;&lt;/span&gt;.&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    time.sleep(random.randint(&lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;6&lt;/span&gt;))&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;f&amp;#x27;&lt;span class=&#34;subst&#34;&gt;&amp;#123;filename&amp;#125;&lt;/span&gt; 下载完成.&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    end = time.time()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;f&amp;#x27;下载耗时: &lt;span class=&#34;subst&#34;&gt;&amp;#123;end - start:&lt;span class=&#34;number&#34;&gt;.3&lt;/span&gt;f&amp;#125;&lt;/span&gt;秒.&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;main&lt;/span&gt;():&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    start = time.time()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    download(filename=&lt;span class=&#34;string&#34;&gt;&amp;#x27;Python从入门到住院.pdf&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    download(filename=&lt;span class=&#34;string&#34;&gt;&amp;#x27;MySQL从删库到跑路.avi&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    download(filename=&lt;span class=&#34;string&#34;&gt;&amp;#x27;Linux从精通到放弃.mp4&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    end = time.time()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;f&amp;#x27;总耗时: &lt;span class=&#34;subst&#34;&gt;&amp;#123;end - start:&lt;span class=&#34;number&#34;&gt;.3&lt;/span&gt;f&amp;#125;&lt;/span&gt;秒.&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; __name__ == &lt;span class=&#34;string&#34;&gt;&amp;#x27;__main__&amp;#x27;&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    main()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;说明&lt;/strong&gt;：上面的代码并没有真正实现联网下载的功能，而是通过&lt;code&gt;time.sleep()&lt;/code&gt;休眠一段时间来模拟下载文件需要一些时间上的开销，跟实际下载的状况比较类似。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;运行上面的代码，可以得到如下所示的运行结果。可以看出，当我们的程序只有一个工作线程时，每个下载任务都需要等待上一个下载任务执行结束才能开始，所以程序执行的总耗时是三个下载任务各自执行时间的总和。&lt;/p&gt;
&lt;figure class=&#34;highlight erlang&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;开始下载Python从入门到住院.pdf.&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;Python从入门到住院.pdf下载完成.&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;下载耗时: &lt;span class=&#34;number&#34;&gt;3.005&lt;/span&gt;秒.&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;开始下载MySQL从删库到跑路.avi.&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;MySQL从删库到跑路.avi下载完成.&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;下载耗时: &lt;span class=&#34;number&#34;&gt;5.006&lt;/span&gt;秒.&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;开始下载Linux从精通到放弃.mp4.&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;Linux从精通到放弃.mp3下载完成.&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;下载耗时: &lt;span class=&#34;number&#34;&gt;6.007&lt;/span&gt;秒.&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;总耗时: &lt;span class=&#34;number&#34;&gt;14.018&lt;/span&gt;秒.&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;事实上，上面的三个下载任务之间并没有逻辑上的因果关系，三者是可以“并发”的，下一个下载任务没有必要等待上一个下载任务结束，为此，我们可以使用多线程编程来改写上面的代码。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; random&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; time&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; threading &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; Thread&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;download&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;*, filename&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    start = time.time()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;f&amp;#x27;开始下载 &lt;span class=&#34;subst&#34;&gt;&amp;#123;filename&amp;#125;&lt;/span&gt;.&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    time.sleep(random.randint(&lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;6&lt;/span&gt;))&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;f&amp;#x27;&lt;span class=&#34;subst&#34;&gt;&amp;#123;filename&amp;#125;&lt;/span&gt; 下载完成.&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    end = time.time()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;f&amp;#x27;下载耗时: &lt;span class=&#34;subst&#34;&gt;&amp;#123;end - start:&lt;span class=&#34;number&#34;&gt;.3&lt;/span&gt;f&amp;#125;&lt;/span&gt;秒.&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;main&lt;/span&gt;():&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    threads = [&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        Thread(target=download, kwargs=&amp;#123;&lt;span class=&#34;string&#34;&gt;&amp;#x27;filename&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;Python从入门到住院.pdf&amp;#x27;&lt;/span&gt;&amp;#125;),&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        Thread(target=download, kwargs=&amp;#123;&lt;span class=&#34;string&#34;&gt;&amp;#x27;filename&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;MySQL从删库到跑路.avi&amp;#x27;&lt;/span&gt;&amp;#125;),&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        Thread(target=download, kwargs=&amp;#123;&lt;span class=&#34;string&#34;&gt;&amp;#x27;filename&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;Linux从精通到放弃.mp4&amp;#x27;&lt;/span&gt;&amp;#125;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    ]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    start = time.time()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 启动三个线程&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; thread &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; threads:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        thread.start()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 等待线程结束&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; thread &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; threads:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        thread.join()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    end = time.time()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;f&amp;#x27;总耗时: &lt;span class=&#34;subst&#34;&gt;&amp;#123;end - start:&lt;span class=&#34;number&#34;&gt;.3&lt;/span&gt;f&amp;#125;&lt;/span&gt;秒.&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; __name__ == &lt;span class=&#34;string&#34;&gt;&amp;#x27;__main__&amp;#x27;&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    main()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;某次的运行结果如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight erlang&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;开始下载 Python从入门到住院.pdf.&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;开始下载 MySQL从删库到跑路.avi.&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;开始下载 Linux从精通到放弃.mp4.&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;MySQL从删库到跑路.avi 下载完成.&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;下载耗时: &lt;span class=&#34;number&#34;&gt;3.005&lt;/span&gt;秒.&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;Python从入门到住院.pdf 下载完成.&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;下载耗时: &lt;span class=&#34;number&#34;&gt;5.006&lt;/span&gt;秒.&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;Linux从精通到放弃.mp4 下载完成.&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;下载耗时: &lt;span class=&#34;number&#34;&gt;6.003&lt;/span&gt;秒.&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;总耗时: &lt;span class=&#34;number&#34;&gt;6.004&lt;/span&gt;秒.&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;通过上面的运行结果可以发现，整个程序的执行时间几乎等于耗时最长的一个下载任务的执行时间，这也就意味着，三个下载任务是并发执行的，不存在一个等待另一个的情况，这样做很显然提高了程序的执行效率。简单的说，如果程序中有非常耗时的执行单元，而这些耗时的执行单元之间又没有逻辑上的因果关系，即 B 单元的执行不依赖于 A 单元的执行结果，那么 A 和 B 两个单元就可以放到两个不同的线程中，让他们并发的执行。这样做的好处除了减少程序执行的等待时间，还可以带来更好的用户体验，因为一个单元的阻塞不会造成程序的“假死”，因为程序中还有其他的单元是可以运转的。&lt;/p&gt;
&lt;h4 id=&#34;使用-Thread-类创建线程对象&#34;&gt;&lt;a href=&#34;#使用-Thread-类创建线程对象&#34; class=&#34;headerlink&#34; title=&#34;使用 Thread 类创建线程对象&#34;&gt;&lt;/a&gt;使用 Thread 类创建线程对象&lt;/h4&gt;&lt;p&gt;通过上面的代码可以看出，直接使用&lt;code&gt;Thread&lt;/code&gt;类的构造器就可以创建线程对象，而线程对象的&lt;code&gt;start()&lt;/code&gt;方法可以启动一个线程。线程启动后会执行&lt;code&gt;target&lt;/code&gt;参数指定的函数，当然前提是获得 CPU 的调度；如果&lt;code&gt;target&lt;/code&gt;指定的线程要执行的目标函数有参数，需要通过&lt;code&gt;args&lt;/code&gt;参数为其进行指定，对于关键字参数，可以通过&lt;code&gt;kwargs&lt;/code&gt;参数进行传入。&lt;code&gt;Thread&lt;/code&gt;类的构造器还有很多其他的参数，我们遇到的时候再为大家进行讲解，目前需要大家掌握的，就是&lt;code&gt;target&lt;/code&gt;、&lt;code&gt;args&lt;/code&gt;和&lt;code&gt;kwargs&lt;/code&gt;。&lt;/p&gt;
&lt;h4 id=&#34;继承-Thread-类自定义线程&#34;&gt;&lt;a href=&#34;#继承-Thread-类自定义线程&#34; class=&#34;headerlink&#34; title=&#34;继承 Thread 类自定义线程&#34;&gt;&lt;/a&gt;继承 Thread 类自定义线程&lt;/h4&gt;&lt;p&gt;除了上面的代码展示的创建线程的方式外，还可以通过继承&lt;code&gt;Thread&lt;/code&gt;类并重写&lt;code&gt;run()&lt;/code&gt;方法的方式来自定义线程，具体的代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; random&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; time&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; threading &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; Thread&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;class&lt;/span&gt; &lt;span class=&#34;title class_&#34;&gt;DownloadThread&lt;/span&gt;(&lt;span class=&#34;title class_ inherited__&#34;&gt;Thread&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;__init__&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;self, filename&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        self.filename = filename&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;built_in&#34;&gt;super&lt;/span&gt;().__init__()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;run&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;self&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        start = time.time()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;f&amp;#x27;开始下载 &lt;span class=&#34;subst&#34;&gt;&amp;#123;self.filename&amp;#125;&lt;/span&gt;.&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        time.sleep(random.randint(&lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;6&lt;/span&gt;))&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;f&amp;#x27;&lt;span class=&#34;subst&#34;&gt;&amp;#123;self.filename&amp;#125;&lt;/span&gt; 下载完成.&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        end = time.time()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;f&amp;#x27;下载耗时: &lt;span class=&#34;subst&#34;&gt;&amp;#123;end - start:&lt;span class=&#34;number&#34;&gt;.3&lt;/span&gt;f&amp;#125;&lt;/span&gt;秒.&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;main&lt;/span&gt;():&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    threads = [&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        DownloadThread(&lt;span class=&#34;string&#34;&gt;&amp;#x27;Python从入门到住院.pdf&amp;#x27;&lt;/span&gt;),&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        DownloadThread(&lt;span class=&#34;string&#34;&gt;&amp;#x27;MySQL从删库到跑路.avi&amp;#x27;&lt;/span&gt;),&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        DownloadThread(&lt;span class=&#34;string&#34;&gt;&amp;#x27;Linux从精通到放弃.mp4&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    ]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    start = time.time()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 启动三个线程&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; thread &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; threads:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        thread.start()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 等待线程结束&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; thread &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; threads:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        thread.join()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    end = time.time()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;f&amp;#x27;总耗时: &lt;span class=&#34;subst&#34;&gt;&amp;#123;end - start:&lt;span class=&#34;number&#34;&gt;.3&lt;/span&gt;f&amp;#125;&lt;/span&gt;秒.&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; __name__ == &lt;span class=&#34;string&#34;&gt;&amp;#x27;__main__&amp;#x27;&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    main()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h4 id=&#34;使用线程池&#34;&gt;&lt;a href=&#34;#使用线程池&#34; class=&#34;headerlink&#34; title=&#34;使用线程池&#34;&gt;&lt;/a&gt;使用线程池&lt;/h4&gt;&lt;p&gt;我们还可以通过线程池的方式将任务放到多个线程中去执行，通过线程池来使用线程应该是多线程编程最理想的选择。事实上，线程的创建和释放都会带来较大的开销，频繁的创建和释放线程通常都不是很好的选择。利用线程池，可以提前准备好若干个线程，在使用的过程中不需要再通过自定义的代码创建和释放线程，而是直接复用线程池中的线程。Python 内置的&lt;code&gt;concurrent.futures&lt;/code&gt;模块提供了对线程池的支持，代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; random&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; time&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; concurrent.futures &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; ThreadPoolExecutor&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; threading &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; Thread&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;download&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;*, filename&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    start = time.time()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;f&amp;#x27;开始下载 &lt;span class=&#34;subst&#34;&gt;&amp;#123;filename&amp;#125;&lt;/span&gt;.&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    time.sleep(random.randint(&lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;6&lt;/span&gt;))&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;f&amp;#x27;&lt;span class=&#34;subst&#34;&gt;&amp;#123;filename&amp;#125;&lt;/span&gt; 下载完成.&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    end = time.time()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;f&amp;#x27;下载耗时: &lt;span class=&#34;subst&#34;&gt;&amp;#123;end - start:&lt;span class=&#34;number&#34;&gt;.3&lt;/span&gt;f&amp;#125;&lt;/span&gt;秒.&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;main&lt;/span&gt;():&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;with&lt;/span&gt; ThreadPoolExecutor(max_workers=&lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;as&lt;/span&gt; pool:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        filenames = [&lt;span class=&#34;string&#34;&gt;&amp;#x27;Python从入门到住院.pdf&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;MySQL从删库到跑路.avi&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;Linux从精通到放弃.mp4&amp;#x27;&lt;/span&gt;]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        start = time.time()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; filename &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; filenames:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            pool.submit(download, filename=filename)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    end = time.time()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;f&amp;#x27;总耗时: &lt;span class=&#34;subst&#34;&gt;&amp;#123;end - start:&lt;span class=&#34;number&#34;&gt;.3&lt;/span&gt;f&amp;#125;&lt;/span&gt;秒.&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; __name__ == &lt;span class=&#34;string&#34;&gt;&amp;#x27;__main__&amp;#x27;&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    main()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h3 id=&#34;守护线程&#34;&gt;&lt;a href=&#34;#守护线程&#34; class=&#34;headerlink&#34; title=&#34;守护线程&#34;&gt;&lt;/a&gt;守护线程&lt;/h3&gt;&lt;p&gt;所谓“守护线程”就是在主线程结束的时候，不值得再保留的执行线程。这里的不值得保留指的是守护线程会在其他非守护线程全部运行结束之后被销毁，它守护的是当前进程内所有的非守护线程。简单的说，守护线程会跟随主线程一起挂掉，而主线程的生命周期就是一个进程的生命周期。如果不理解，我们可以看一段简单的代码。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; time&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; threading &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; Thread&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;display&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;content&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;while&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;True&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(content, end=&lt;span class=&#34;string&#34;&gt;&amp;#x27;&amp;#x27;&lt;/span&gt;, flush=&lt;span class=&#34;literal&#34;&gt;True&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        time.sleep(&lt;span class=&#34;number&#34;&gt;0.1&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;main&lt;/span&gt;():&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    Thread(target=display, args=(&lt;span class=&#34;string&#34;&gt;&amp;#x27;Ping&amp;#x27;&lt;/span&gt;, )).start()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    Thread(target=display, args=(&lt;span class=&#34;string&#34;&gt;&amp;#x27;Pong&amp;#x27;&lt;/span&gt;, )).start()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; __name__ == &lt;span class=&#34;string&#34;&gt;&amp;#x27;__main__&amp;#x27;&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    main()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;说明&lt;/strong&gt;：上面的代码中，我们将&lt;code&gt;print&lt;/code&gt;函数的参数&lt;code&gt;flush&lt;/code&gt;设置为&lt;code&gt;True&lt;/code&gt;，这是因为&lt;code&gt;flush&lt;/code&gt;参数的值如果为&lt;code&gt;False&lt;/code&gt;，而&lt;code&gt;print&lt;/code&gt;又没有做换行处理，就会导致每次&lt;code&gt;print&lt;/code&gt;输出的内容被放到操作系统的输出缓冲区，直到缓冲区被输出的内容塞满，才会清空缓冲区产生一次输出。上述现象是操作系统为了减少 I&amp;#x2F;O 中断，提升 CPU 利用率做出的设定，为了让代码产生直观交互，我们才将&lt;code&gt;flush&lt;/code&gt;参数设置为&lt;code&gt;True&lt;/code&gt;，强制每次输出都清空输出缓冲区。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;上面的代码运行起来之后是不会停止的，因为两个子线程中都有死循环，除非你手动中断代码的执行。但是，如果在创建线程对象时，将名为&lt;code&gt;daemon&lt;/code&gt;的参数设置为&lt;code&gt;True&lt;/code&gt;，这两个线程就会变成守护线程，那么在其他线程结束时，即便有死循环，两个守护线程也会挂掉，不会再继续执行下去，代码如下所示。&lt;/p&gt;
 &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; time&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; threading &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; Thread&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;display&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;content&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;while&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;True&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(content, end=&lt;span class=&#34;string&#34;&gt;&amp;#x27;&amp;#x27;&lt;/span&gt;, flush=&lt;span class=&#34;literal&#34;&gt;True&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        time.sleep(&lt;span class=&#34;number&#34;&gt;0.1&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;main&lt;/span&gt;():&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    Thread(target=display, args=(&lt;span class=&#34;string&#34;&gt;&amp;#x27;Ping&amp;#x27;&lt;/span&gt;, ), daemon=&lt;span class=&#34;literal&#34;&gt;True&lt;/span&gt;).start()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    Thread(target=display, args=(&lt;span class=&#34;string&#34;&gt;&amp;#x27;Pong&amp;#x27;&lt;/span&gt;, ), daemon=&lt;span class=&#34;literal&#34;&gt;True&lt;/span&gt;).start()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    time.sleep(&lt;span class=&#34;number&#34;&gt;5&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; __name__ == &lt;span class=&#34;string&#34;&gt;&amp;#x27;__main__&amp;#x27;&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    main()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;上面的代码，我们在主线程中添加了一行&lt;code&gt;time.sleep(5)&lt;/code&gt;让主线程休眠5秒，在这个过程中，输出&lt;code&gt;Ping&lt;/code&gt;和&lt;code&gt;Pong&lt;/code&gt;的守护线程会持续运转，直到主线程在5秒后结束，这两个守护线程也被销毁，不再继续运行。&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;思考&lt;/strong&gt;：如果将上面代码第12行的&lt;code&gt;daemon=True&lt;/code&gt;去掉，代码会怎样执行？有兴趣的读者可以尝试一下，并看看实际执行的结果跟你想象的是否一致。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h3 id=&#34;资源竞争&#34;&gt;&lt;a href=&#34;#资源竞争&#34; class=&#34;headerlink&#34; title=&#34;资源竞争&#34;&gt;&lt;/a&gt;资源竞争&lt;/h3&gt;&lt;p&gt;在编写多线程代码时，不可避免的会遇到多个线程竞争同一个资源（对象）的情况。在这种情况下，如果没有合理的机制来保护被竞争的资源，那么就有可能出现非预期的状况。下面的代码创建了&lt;code&gt;100&lt;/code&gt;个线程向同一个银行账户（初始余额为&lt;code&gt;0&lt;/code&gt;元）转账，每个线程转账金额为&lt;code&gt;1&lt;/code&gt;元。在正常的情况下，我们的银行账户最终的余额应该是&lt;code&gt;100&lt;/code&gt;元，但是运行下面的代码我们并不能得到&lt;code&gt;100&lt;/code&gt;元这个结果。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; time&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; concurrent.futures &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; ThreadPoolExecutor&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;class&lt;/span&gt; &lt;span class=&#34;title class_&#34;&gt;Account&lt;/span&gt;(&lt;span class=&#34;title class_ inherited__&#34;&gt;object&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;&amp;quot;&amp;quot;银行账户&amp;quot;&amp;quot;&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;__init__&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;self&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        self.balance = &lt;span class=&#34;number&#34;&gt;0.0&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;deposit&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;self, money&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;string&#34;&gt;&amp;quot;&amp;quot;&amp;quot;存钱&amp;quot;&amp;quot;&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        new_balance = self.balance + money&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        time.sleep(&lt;span class=&#34;number&#34;&gt;0.01&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        self.balance = new_balance&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;main&lt;/span&gt;():&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;&amp;quot;&amp;quot;主函数&amp;quot;&amp;quot;&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    account = Account()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;with&lt;/span&gt; ThreadPoolExecutor(max_workers=&lt;span class=&#34;number&#34;&gt;16&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;as&lt;/span&gt; pool:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; _ &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; &lt;span class=&#34;built_in&#34;&gt;range&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;100&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            pool.submit(account.deposit, &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(account.balance)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; __name__ == &lt;span class=&#34;string&#34;&gt;&amp;#x27;__main__&amp;#x27;&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    main()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;上面代码中的&lt;code&gt;Account&lt;/code&gt;类代表了银行账户，它的&lt;code&gt;deposit&lt;/code&gt;方法代表存款行为，参数&lt;code&gt;money&lt;/code&gt;代表存入的金额，该方法通过&lt;code&gt;time.sleep&lt;/code&gt;函数模拟受理存款需要一段时间。我们通过线程池的方式启动了&lt;code&gt;100&lt;/code&gt;个线程向一个账户转账，但是上面的代码并不能运行出&lt;code&gt;100&lt;/code&gt;这个我们期望的结果，这就是在多个线程竞争一个资源的时候，可能会遇到的数据不一致的问题。注意上面代码的第&lt;code&gt;14&lt;/code&gt;行，当多个线程都执行到这行代码时，它们会在相同的余额上执行加上存入金额的操作，这就会造成“丢失更新”现象，即之前修改数据的成果被后续的修改给覆盖掉了，所以才得不到正确的结果。&lt;/p&gt;
&lt;p&gt;要解决上面的问题，可以使用锁机制，通过锁对操作数据的关键代码加以保护。Python 标准库的&lt;code&gt;threading&lt;/code&gt;模块提供了&lt;code&gt;Lock&lt;/code&gt;和&lt;code&gt;RLock&lt;/code&gt;类来支持锁机制，这里我们不去深究二者的区别，建议大家直接使用&lt;code&gt;RLock&lt;/code&gt;。接下来，我们给银行账户添加一个锁对象，通过锁对象来解决刚才存款时发生“丢失更新”的问题，代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; time&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; concurrent.futures &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; ThreadPoolExecutor&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; threading &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; RLock&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;class&lt;/span&gt; &lt;span class=&#34;title class_&#34;&gt;Account&lt;/span&gt;(&lt;span class=&#34;title class_ inherited__&#34;&gt;object&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;&amp;quot;&amp;quot;银行账户&amp;quot;&amp;quot;&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;__init__&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;self&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        self.balance = &lt;span class=&#34;number&#34;&gt;0.0&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        self.lock = RLock()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;deposit&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;self, money&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;# 获得锁&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        self.lock.acquire()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;try&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            new_balance = self.balance + money&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            time.sleep(&lt;span class=&#34;number&#34;&gt;0.01&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            self.balance = new_balance&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;finally&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;comment&#34;&gt;# 释放锁&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            self.lock.release()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;main&lt;/span&gt;():&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;&amp;quot;&amp;quot;主函数&amp;quot;&amp;quot;&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    account = Account()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;with&lt;/span&gt; ThreadPoolExecutor(max_workers=&lt;span class=&#34;number&#34;&gt;16&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;as&lt;/span&gt; pool:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; _ &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; &lt;span class=&#34;built_in&#34;&gt;range&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;100&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            pool.submit(account.deposit, &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(account.balance)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; __name__ == &lt;span class=&#34;string&#34;&gt;&amp;#x27;__main__&amp;#x27;&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    main()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;上面代码中，获得锁和释放锁的操作也可以通过上下文语法来实现，使用上下文语法会让代码更加简单优雅，这也是我们推荐大家使用的方式。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; time&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; concurrent.futures &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; ThreadPoolExecutor&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; threading &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; RLock&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;class&lt;/span&gt; &lt;span class=&#34;title class_&#34;&gt;Account&lt;/span&gt;(&lt;span class=&#34;title class_ inherited__&#34;&gt;object&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;&amp;quot;&amp;quot;银行账户&amp;quot;&amp;quot;&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;__init__&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;self&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        self.balance = &lt;span class=&#34;number&#34;&gt;0.0&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        self.lock = RLock()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;deposit&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;self, money&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;# 通过上下文语法获得锁和释放锁&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;with&lt;/span&gt; self.lock:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            new_balance = self.balance + money&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            time.sleep(&lt;span class=&#34;number&#34;&gt;0.01&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            self.balance = new_balance&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;main&lt;/span&gt;():&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;&amp;quot;&amp;quot;主函数&amp;quot;&amp;quot;&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    account = Account()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;with&lt;/span&gt; ThreadPoolExecutor(max_workers=&lt;span class=&#34;number&#34;&gt;16&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;as&lt;/span&gt; pool:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; _ &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; &lt;span class=&#34;built_in&#34;&gt;range&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;100&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            pool.submit(account.deposit, &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(account.balance)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; __name__ == &lt;span class=&#34;string&#34;&gt;&amp;#x27;__main__&amp;#x27;&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    main()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;思考&lt;/strong&gt;：将上面的代码修改为5个线程向银行账户存钱，5个线程从银行账户取钱，取钱的线程在银行账户余额不足时，需要停下来等待存钱的线程将钱存入后再尝试取钱。这里需要用到线程调度的知识，大家可以自行研究下&lt;code&gt;threading&lt;/code&gt;模块中的&lt;code&gt;Condition&lt;/code&gt;类，看看是否能够完成这个任务。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h3 id=&#34;GIL问题&#34;&gt;&lt;a href=&#34;#GIL问题&#34; class=&#34;headerlink&#34; title=&#34;GIL问题&#34;&gt;&lt;/a&gt;GIL问题&lt;/h3&gt;&lt;p&gt;如果使用官方的 Python 解释器（通常称之为 CPython）运行 Python 程序，我们并不能通过使用多线程的方式将 CPU 的利用率提升到逼近400%（对于4核 CPU）或逼近800%（对于8核 CPU）这样的水平，因为 CPython 在执行代码时，会受到 GIL（全局解释器锁）的限制。具体的说，CPython 在执行任何代码时，都需要对应的线程先获得 GIL，然后每执行100条（字节码）指令，CPython 就会让获得 GIL 的线程主动释放 GIL，这样别的线程才有机会执行。因为 GIL 的存在，无论你的 CPU 有多少个核，我们编写的 Python 代码也没有机会真正并行的执行。&lt;/p&gt;
&lt;p&gt;GIL 是官方 Python 解释器在设计上的历史遗留问题，要解决这个问题，让多线程能够发挥 CPU 的多核优势，需要重新实现一个不带 GIL 的 Python 解释器。这个问题按照官方的说法，在 Python 发布4.0版本时会得到解决，就让我们拭目以待吧。当下，对于 CPython 而言，如果希望充分发挥 CPU 的多核优势，可以考虑使用多进程，因为每个进程都对应一个 Python 解释器，因此每个进程都有自己独立的 GIL，这样就可以突破 GIL 的限制。在下一个章节中，我们会为大家介绍关于多进程的相关知识，并对多线程和多进程的代码及其执行效果进行比较。&lt;/p&gt;

 &lt;h2 id=&#34;并发编程在爬虫中的应用&#34;&gt;&lt;a href=&#34;#并发编程在爬虫中的应用&#34; class=&#34;headerlink&#34; title=&#34;并发编程在爬虫中的应用&#34;&gt;&lt;/a&gt;并发编程在爬虫中的应用&lt;/h2&gt;&lt;p&gt;之前的课程，我们已经为大家介绍了 Python 中的多线程、多进程和异步编程，通过这三种手段，我们可以实现并发或并行编程，这一方面可以加速代码的执行，另一方面也可以带来更好的用户体验。爬虫程序是典型的 I&amp;#x2F;O 密集型任务，对于 I&amp;#x2F;O 密集型任务来说，多线程和异步 I&amp;#x2F;O 都是很好的选择，因为当程序的某个部分因 I&amp;#x2F;O 操作阻塞时，程序的其他部分仍然可以运转，这样我们不用在等待和阻塞中浪费大量的时间。下面我们以爬取“&lt;a href=&#34;https://image.so.com/&#34;&gt;360图片&lt;/a&gt;”网站的图片并保存到本地为例，为大家分别展示使用单线程、多线程和异步 I&amp;#x2F;O 编程的爬虫程序有什么区别，同时也对它们的执行效率进行简单的对比。&lt;/p&gt;
&lt;p&gt;“360图片”网站的页面使用了 &lt;a href=&#34;https://developer.mozilla.org/zh-CN/docs/Web/Guide/AJAX&#34;&gt;Ajax&lt;/a&gt; 技术，这是很多网站都会使用的一种异步加载数据和局部刷新页面的技术。简单的说，页面上的图片都是通过 JavaScript 代码异步获取 JSON 数据并动态渲染生成的，而且整个页面还使用了瀑布式加载（一边向下滚动，一边加载更多的图片）。我们在浏览器的“开发者工具”中可以找到提供动态内容的数据接口，如下图所示，我们需要的图片信息就在服务器返回的 JSON 数据中。&lt;/p&gt;
&lt;img src=&#34;https://gitee.com/jackfrued/mypic/raw/master/20211205221352.png&#34; style=&#34;zoom:50%;&#34;&gt;

&lt;p&gt;例如，要获取“美女”频道的图片，我们可以请求如下所示的URL，其中参数&lt;code&gt;ch&lt;/code&gt;表示请求的频道，&lt;code&gt;=&lt;/code&gt;后面的参数值&lt;code&gt;beauty&lt;/code&gt;就代表了“美女”频道，参数&lt;code&gt;sn&lt;/code&gt;相当于是页码，&lt;code&gt;0&lt;/code&gt;表示第一页（共&lt;code&gt;30&lt;/code&gt;张图片），&lt;code&gt;30&lt;/code&gt;表示第二页，&lt;code&gt;60&lt;/code&gt;表示第三页，以此类推。&lt;/p&gt;
&lt;figure class=&#34;highlight vim&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;https://image.&lt;span class=&#34;keyword&#34;&gt;so&lt;/span&gt;.&lt;span class=&#34;keyword&#34;&gt;com&lt;/span&gt;/zjl?ch=beauty&amp;amp;&lt;span class=&#34;keyword&#34;&gt;sn&lt;/span&gt;=&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h3 id=&#34;单线程版本&#34;&gt;&lt;a href=&#34;#单线程版本&#34; class=&#34;headerlink&#34; title=&#34;单线程版本&#34;&gt;&lt;/a&gt;单线程版本&lt;/h3&gt;&lt;p&gt;通过上面的 URL 下载“美女”频道共&lt;code&gt;90&lt;/code&gt;张图片。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;&amp;quot;&amp;quot;&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;example04.py - 单线程版本爬虫&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;&amp;quot;&amp;quot;&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; os&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; requests&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;download_picture&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;url&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    filename = url[url.rfind(&lt;span class=&#34;string&#34;&gt;&amp;#x27;/&amp;#x27;&lt;/span&gt;) + &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;:]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    resp = requests.get(url)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; resp.status_code == &lt;span class=&#34;number&#34;&gt;200&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;with&lt;/span&gt; &lt;span class=&#34;built_in&#34;&gt;open&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;f&amp;#x27;images/beauty/&lt;span class=&#34;subst&#34;&gt;&amp;#123;filename&amp;#125;&lt;/span&gt;&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;wb&amp;#x27;&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;as&lt;/span&gt; file:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            file.write(resp.content)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;main&lt;/span&gt;():&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;not&lt;/span&gt; os.path.exists(&lt;span class=&#34;string&#34;&gt;&amp;#x27;images/beauty&amp;#x27;&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        os.makedirs(&lt;span class=&#34;string&#34;&gt;&amp;#x27;images/beauty&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; page &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; &lt;span class=&#34;built_in&#34;&gt;range&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        resp = requests.get(&lt;span class=&#34;string&#34;&gt;f&amp;#x27;https://image.so.com/zjl?ch=beauty&amp;amp;sn=&lt;span class=&#34;subst&#34;&gt;&amp;#123;page * &lt;span class=&#34;number&#34;&gt;30&lt;/span&gt;&amp;#125;&lt;/span&gt;&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; resp.status_code == &lt;span class=&#34;number&#34;&gt;200&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            pic_dict_list = resp.json()[&lt;span class=&#34;string&#34;&gt;&amp;#x27;list&amp;#x27;&lt;/span&gt;]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; pic_dict &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; pic_dict_list:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                download_picture(pic_dict[&lt;span class=&#34;string&#34;&gt;&amp;#x27;qhimg_url&amp;#x27;&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; __name__ == &lt;span class=&#34;string&#34;&gt;&amp;#x27;__main__&amp;#x27;&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    main()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;在 macOS 或 Linux 系统上，我们可以使用&lt;code&gt;time&lt;/code&gt;命令来了解上面代码的执行时间以及 CPU 的利用率，如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;time python3 example04.py &lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;下面是单线程爬虫代码在我的电脑上执行的结果。&lt;/p&gt;
&lt;figure class=&#34;highlight apache&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;python3&lt;/span&gt; example04.py  &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;36&lt;/span&gt;s user &lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;39&lt;/span&gt;s system &lt;span class=&#34;number&#34;&gt;12&lt;/span&gt;% cpu &lt;span class=&#34;number&#34;&gt;21&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;578&lt;/span&gt; total&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;这里我们只需要关注代码的总耗时为&lt;code&gt;21.578&lt;/code&gt;秒，CPU 利用率为&lt;code&gt;12%&lt;/code&gt;。&lt;/p&gt;
&lt;h3 id=&#34;多线程版本&#34;&gt;&lt;a href=&#34;#多线程版本&#34; class=&#34;headerlink&#34; title=&#34;多线程版本&#34;&gt;&lt;/a&gt;多线程版本&lt;/h3&gt;&lt;p&gt;我们使用之前讲到过的线程池技术，将上面的代码修改为多线程版本。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;&amp;quot;&amp;quot;&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;example05.py - 多线程版本爬虫&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;&amp;quot;&amp;quot;&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; os&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; concurrent.futures &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; ThreadPoolExecutor&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; requests&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;download_picture&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;url&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    filename = url[url.rfind(&lt;span class=&#34;string&#34;&gt;&amp;#x27;/&amp;#x27;&lt;/span&gt;) + &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;:]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    resp = requests.get(url)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; resp.status_code == &lt;span class=&#34;number&#34;&gt;200&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;with&lt;/span&gt; &lt;span class=&#34;built_in&#34;&gt;open&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;f&amp;#x27;images/beauty/&lt;span class=&#34;subst&#34;&gt;&amp;#123;filename&amp;#125;&lt;/span&gt;&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;wb&amp;#x27;&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;as&lt;/span&gt; file:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            file.write(resp.content)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;main&lt;/span&gt;():&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;not&lt;/span&gt; os.path.exists(&lt;span class=&#34;string&#34;&gt;&amp;#x27;images/beauty&amp;#x27;&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        os.makedirs(&lt;span class=&#34;string&#34;&gt;&amp;#x27;images/beauty&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;with&lt;/span&gt; ThreadPoolExecutor(max_workers=&lt;span class=&#34;number&#34;&gt;16&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;as&lt;/span&gt; pool:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; page &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; &lt;span class=&#34;built_in&#34;&gt;range&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            resp = requests.get(&lt;span class=&#34;string&#34;&gt;f&amp;#x27;https://image.so.com/zjl?ch=beauty&amp;amp;sn=&lt;span class=&#34;subst&#34;&gt;&amp;#123;page * &lt;span class=&#34;number&#34;&gt;30&lt;/span&gt;&amp;#125;&lt;/span&gt;&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; resp.status_code == &lt;span class=&#34;number&#34;&gt;200&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                pic_dict_list = resp.json()[&lt;span class=&#34;string&#34;&gt;&amp;#x27;list&amp;#x27;&lt;/span&gt;]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; pic_dict &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; pic_dict_list:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                    pool.submit(download_picture, pic_dict[&lt;span class=&#34;string&#34;&gt;&amp;#x27;qhimg_url&amp;#x27;&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; __name__ == &lt;span class=&#34;string&#34;&gt;&amp;#x27;__main__&amp;#x27;&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    main()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;执行如下所示的命令。&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;time python3 example05.py&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;代码的执行结果如下所示：&lt;/p&gt;
&lt;figure class=&#34;highlight apache&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;python3&lt;/span&gt; example05.py  &lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;65&lt;/span&gt;s user &lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;40&lt;/span&gt;s system &lt;span class=&#34;number&#34;&gt;95&lt;/span&gt;% cpu &lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;193&lt;/span&gt; total&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h3 id=&#34;异步I-O版本&#34;&gt;&lt;a href=&#34;#异步I-O版本&#34; class=&#34;headerlink&#34; title=&#34;异步I&amp;#x2F;O版本&#34;&gt;&lt;/a&gt;异步I&amp;#x2F;O版本&lt;/h3&gt;&lt;p&gt;我们使用&lt;code&gt;aiohttp&lt;/code&gt;将上面的代码修改为异步 I&amp;#x2F;O 的版本。为了以异步 I&amp;#x2F;O 的方式实现网络资源的获取和写文件操作，我们首先得安装三方库&lt;code&gt;aiohttp&lt;/code&gt;和&lt;code&gt;aiofile&lt;/code&gt;，命令如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;pip install aiohttp aiofile&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;&lt;code&gt;aiohttp&lt;/code&gt; 的用法在之前的课程中已经做过简要介绍，&lt;code&gt;aiofile&lt;/code&gt;模块中的&lt;code&gt;async_open&lt;/code&gt;函数跟 Python 内置函数&lt;code&gt;open&lt;/code&gt;的用法大致相同，只不过它支持异步操作。下面是异步 I&amp;#x2F;O 版本的爬虫代码。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;&amp;quot;&amp;quot;&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;example06.py - 异步I/O版本爬虫&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;&amp;quot;&amp;quot;&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; asyncio&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; json&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; os&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; aiofile&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; aiohttp&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;async&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;download_picture&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;session, url&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    filename = url[url.rfind(&lt;span class=&#34;string&#34;&gt;&amp;#x27;/&amp;#x27;&lt;/span&gt;) + &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;:]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;async&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;with&lt;/span&gt; session.get(url, ssl=&lt;span class=&#34;literal&#34;&gt;False&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;as&lt;/span&gt; resp:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; resp.status == &lt;span class=&#34;number&#34;&gt;200&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            data = &lt;span class=&#34;keyword&#34;&gt;await&lt;/span&gt; resp.read()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;keyword&#34;&gt;async&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;with&lt;/span&gt; aiofile.async_open(&lt;span class=&#34;string&#34;&gt;f&amp;#x27;images/beauty/&lt;span class=&#34;subst&#34;&gt;&amp;#123;filename&amp;#125;&lt;/span&gt;&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;wb&amp;#x27;&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;as&lt;/span&gt; file:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                &lt;span class=&#34;keyword&#34;&gt;await&lt;/span&gt; file.write(data)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;async&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;fetch_json&lt;/span&gt;():&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;async&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;with&lt;/span&gt; aiohttp.ClientSession() &lt;span class=&#34;keyword&#34;&gt;as&lt;/span&gt; session:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; page &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; &lt;span class=&#34;built_in&#34;&gt;range&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;keyword&#34;&gt;async&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;with&lt;/span&gt; session.get(&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                url=&lt;span class=&#34;string&#34;&gt;f&amp;#x27;https://image.so.com/zjl?ch=beauty&amp;amp;sn=&lt;span class=&#34;subst&#34;&gt;&amp;#123;page * &lt;span class=&#34;number&#34;&gt;30&lt;/span&gt;&amp;#125;&lt;/span&gt;&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                ssl=&lt;span class=&#34;literal&#34;&gt;False&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            ) &lt;span class=&#34;keyword&#34;&gt;as&lt;/span&gt; resp:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; resp.status == &lt;span class=&#34;number&#34;&gt;200&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                    json_str = &lt;span class=&#34;keyword&#34;&gt;await&lt;/span&gt; resp.text()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                    result = json.loads(json_str)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                    &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; pic_dict &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; result[&lt;span class=&#34;string&#34;&gt;&amp;#x27;list&amp;#x27;&lt;/span&gt;]:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                        &lt;span class=&#34;keyword&#34;&gt;await&lt;/span&gt; download_picture(session, pic_dict[&lt;span class=&#34;string&#34;&gt;&amp;#x27;qhimg_url&amp;#x27;&lt;/span&gt;])&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;main&lt;/span&gt;():&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;not&lt;/span&gt; os.path.exists(&lt;span class=&#34;string&#34;&gt;&amp;#x27;images/beauty&amp;#x27;&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        os.makedirs(&lt;span class=&#34;string&#34;&gt;&amp;#x27;images/beauty&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    loop = asyncio.get_event_loop()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    loop.run_until_complete(fetch_json())&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    loop.close()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; __name__ == &lt;span class=&#34;string&#34;&gt;&amp;#x27;__main__&amp;#x27;&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    main()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;执行如下所示的命令。&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;time python3 example06.py&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;代码的执行结果如下所示：&lt;/p&gt;
&lt;figure class=&#34;highlight apache&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;python3&lt;/span&gt; example06.py  &lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;82&lt;/span&gt;s user &lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;21&lt;/span&gt;s system &lt;span class=&#34;number&#34;&gt;27&lt;/span&gt;% cpu &lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;.&lt;span class=&#34;number&#34;&gt;782&lt;/span&gt; total&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h3 id=&#34;总结&#34;&gt;&lt;a href=&#34;#总结&#34; class=&#34;headerlink&#34; title=&#34;总结&#34;&gt;&lt;/a&gt;总结&lt;/h3&gt;&lt;p&gt;通过上面三段代码执行结果的比较，我们可以得出一个结论，使用多线程和异步 I&amp;#x2F;O 都可以改善爬虫程序的性能，因为我们不用将时间浪费在因 I&amp;#x2F;O 操作造成的等待和阻塞上，而&lt;code&gt;time&lt;/code&gt;命令的执行结果也告诉我们，单线程的代码 CPU 利用率仅仅只有&lt;code&gt;12%&lt;/code&gt;，而多线程版本的 CPU 利用率则高达&lt;code&gt;95%&lt;/code&gt;；单线程版本的爬虫执行时间约&lt;code&gt;21&lt;/code&gt;秒，而多线程和异步 I&amp;#x2F;O 的版本仅执行了&lt;code&gt;3&lt;/code&gt;秒钟。另外，在运行时间差别不大的情况下，多线程的代码比异步 I&amp;#x2F;O 的代码耗费了更多的 CPU 资源，这是因为多线程的调度和切换也需要花费 CPU 时间。至此，三种方式在 I&amp;#x2F;O 密集型任务上的优劣已经一目了然，当然这只是在我的电脑上跑出来的结果。如果网络状况不是很理想或者目标网站响应很慢，那么使用多线程和异步 I&amp;#x2F;O 的优势将更为明显，有兴趣的读者可以自行试验。&lt;/p&gt;

 &lt;h2 id=&#34;用Python解析HTML页面&#34;&gt;&lt;a href=&#34;#用Python解析HTML页面&#34; class=&#34;headerlink&#34; title=&#34;用Python解析HTML页面&#34;&gt;&lt;/a&gt;用Python解析HTML页面&lt;/h2&gt;&lt;p&gt;在前面的课程中，我们讲到了使用&lt;code&gt;request&lt;/code&gt;三方库获取网络资源，还介绍了一些前端的基础知识。接下来，我们继续探索如何解析 HTML 代码，从页面中提取出有用的信息。之前，我们尝试过用正则表达式的捕获组操作提取页面内容，但是写出一个正确的正则表达式也是一件让人头疼的事情。为了解决这个问题，我们得先深入的了解一下 HTML 页面的结构，并在此基础上研究另外的解析页面的方法。&lt;/p&gt;
&lt;h3 id=&#34;HTML-页面的结构&#34;&gt;&lt;a href=&#34;#HTML-页面的结构&#34; class=&#34;headerlink&#34; title=&#34;HTML 页面的结构&#34;&gt;&lt;/a&gt;HTML 页面的结构&lt;/h3&gt;&lt;p&gt;我们在浏览器中打开任意一个网站，然后通过鼠标右键菜单，选择“显示网页源代码”菜单项，就可以看到网页对应的 HTML 代码。&lt;/p&gt;
&lt;p&gt;&lt;img src=&#34;https://gitee.com/jackfrued/mypic/raw/master/20210822094218.png&#34; alt=&#34;image-20210822094218269&#34;&gt;&lt;/p&gt;
&lt;p&gt;代码的第&lt;code&gt;1&lt;/code&gt;行是文档类型声明，第&lt;code&gt;2&lt;/code&gt;行的&lt;code&gt;&amp;lt;html&amp;gt;&lt;/code&gt;标签是整个页面根标签的开始标签，最后一行是根标签的结束标签&lt;code&gt;&amp;lt;/html&amp;gt;&lt;/code&gt;。&lt;code&gt;&amp;lt;html&amp;gt;&lt;/code&gt;标签下面有两个子标签&lt;code&gt;&amp;lt;head&amp;gt;&lt;/code&gt;和&lt;code&gt;&amp;lt;body&amp;gt;&lt;/code&gt;，放在&lt;code&gt;&amp;lt;body&amp;gt;&lt;/code&gt;标签下的内容会显示在浏览器窗口中，这部分内容是网页的主体；放在&lt;code&gt;&amp;lt;head&amp;gt;&lt;/code&gt;标签下的内容不会显示在浏览器窗口中，但是却包含了页面重要的元信息，通常称之为网页的头部。HTML 页面大致的代码结构如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight html&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;meta&#34;&gt;&amp;lt;!doctype &lt;span class=&#34;keyword&#34;&gt;html&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;html&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;head&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;&amp;lt;!-- 页面的元信息，如字符编码、标题、关键字、媒体查询等 --&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;head&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;body&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;&amp;lt;!-- 页面的主体，显示在浏览器窗口中的内容 --&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;body&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;html&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;标签、层叠样式表（CSS）、JavaScript 是构成 HTML 页面的三要素，其中标签用来承载页面要显示的内容，CSS 负责对页面的渲染，而 JavaScript 用来控制页面的交互式行为。要实现 HTML 页面的解析，可以使用 XPath 的语法，它原本是 XML 的一种查询语法，可以根据 HTML 标签的层次结构提取标签中的内容或标签属性；此外，也可以使用 CSS 选择器来定位页面元素，就跟用 CSS 渲染页面元素是同样的道理。&lt;/p&gt;
&lt;h3 id=&#34;XPath-解析&#34;&gt;&lt;a href=&#34;#XPath-解析&#34; class=&#34;headerlink&#34; title=&#34;XPath 解析&#34;&gt;&lt;/a&gt;XPath 解析&lt;/h3&gt;&lt;p&gt;XPath 是在 XML（eXtensible Markup Language）文档中查找信息的一种语法，XML 跟 HTML 类似也是一种用标签承载数据的标签语言，不同之处在于 XML 的标签是可扩展的，可以自定义的，而且 XML 对语法有更严格的要求。XPath 使用路径表达式来选取 XML 文档中的节点或者节点集，这里所说的节点包括元素、属性、文本、命名空间、处理指令、注释、根节点等。下面我们通过一个例子来说明如何使用 XPath 对页面进行解析。&lt;/p&gt;
&lt;figure class=&#34;highlight xml&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;meta&#34;&gt;&amp;lt;?xml version=&lt;span class=&#34;string&#34;&gt;&amp;quot;1.0&amp;quot;&lt;/span&gt; encoding=&lt;span class=&#34;string&#34;&gt;&amp;quot;UTF-8&amp;quot;&lt;/span&gt;?&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;bookstore&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;book&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;title&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;lang&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;eng&amp;quot;&lt;/span&gt;&amp;gt;&lt;/span&gt;Harry Potter&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;title&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;price&lt;/span&gt;&amp;gt;&lt;/span&gt;29.99&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;price&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;book&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;book&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;title&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;lang&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;zh&amp;quot;&lt;/span&gt;&amp;gt;&lt;/span&gt;Learning XML&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;title&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;price&lt;/span&gt;&amp;gt;&lt;/span&gt;39.95&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;price&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;book&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;bookstore&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;对于上面的 XML 文件，我们可以用如下所示的 XPath 语法获取文档中的节点。&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;路径表达式&lt;/th&gt;
&lt;th&gt;结果&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;&lt;code&gt;/bookstore&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;选取根元素 bookstore。&lt;strong&gt;注意&lt;/strong&gt;：假如路径起始于正斜杠( &amp;#x2F; )，则此路径始终代表到某元素的绝对路径！&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;//book&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;选取所有 book 子元素，而不管它们在文档中的位置。&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;//@lang&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;选取名为 lang 的所有属性。&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;/bookstore/book[1]&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;选取属于 bookstore 子元素的第一个 book 元素。&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;/bookstore/book[last()]&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;选取属于 bookstore 子元素的最后一个 book 元素。&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;/bookstore/book[last()-1]&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;选取属于 bookstore 子元素的倒数第二个 book 元素。&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;/bookstore/book[position()&amp;lt;3]&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;选取最前面的两个属于 bookstore 元素的子元素的 book 元素。&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;//title[@lang]&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;选取所有拥有名为 lang 的属性的 title 元素。&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;//title[@lang=&amp;#39;eng&amp;#39;]&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;选取所有 title 元素，且这些元素拥有值为 eng 的 lang 属性。&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;/bookstore/book[price&amp;gt;35.00]&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;选取 bookstore 元素的所有 book 元素，且其中的 price 元素的值须大于 35.00。&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;/bookstore/book[price&amp;gt;35.00]/title&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;选取 bookstore 元素中的 book 元素的所有 title 元素，且其中的 price 元素的值须大于 35.00。&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;p&gt;XPath还支持通配符用法，如下所示。&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;路径表达式&lt;/th&gt;
&lt;th&gt;结果&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;&lt;code&gt;/bookstore/*&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;选取 bookstore 元素的所有子元素。&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;//*&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;选取文档中的所有元素。&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;//title[@*]&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;选取所有带有属性的 title 元素。&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;p&gt;如果要选取多个节点，可以使用如下所示的方法。&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;路径表达式&lt;/th&gt;
&lt;th&gt;结果&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;&lt;code&gt;//book/title | //book/price&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;选取 book 元素的所有 title 和 price 元素。&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;//title | //price&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;选取文档中的所有 title 和 price 元素。&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;/bookstore/book/title | //price&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;选取属于 bookstore 元素的 book 元素的所有 title 元素，以及文档中所有的 price 元素。&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;说明&lt;/strong&gt;：上面的例子来自于“菜鸟教程”网站上的 &lt;a href=&#34;https://www.runoob.com/xpath/xpath-tutorial.html&#34;&gt;XPath 教程&lt;/a&gt;，有兴趣的读者可以自行阅读原文。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;当然，如果不理解或不熟悉 XPath 语法，可以在浏览器的开发者工具中按照如下所示的方法查看元素的 XPath 语法，下图是在 Chrome 浏览器的开发者工具中查看豆瓣网电影详情信息中影片标题的 XPath 语法。&lt;/p&gt;
&lt;p&gt;&lt;img src=&#34;https://gitee.com/jackfrued/mypic/raw/master/20210822093707.png&#34;&gt;&lt;/p&gt;
&lt;p&gt;实现 XPath 解析需要三方库&lt;code&gt;lxml&lt;/code&gt; 的支持，可以使用下面的命令安装&lt;code&gt;lxml&lt;/code&gt;。&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;pip install lxml&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;下面我们用 XPath 解析方式改写之前获取豆瓣电影 Top250的代码，如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; lxml &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; etree&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; requests&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; page &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; &lt;span class=&#34;built_in&#34;&gt;range&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;11&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    resp = requests.get(&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        url=&lt;span class=&#34;string&#34;&gt;f&amp;#x27;https://movie.douban.com/top250?start=&lt;span class=&#34;subst&#34;&gt;&amp;#123;(page - &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;) * &lt;span class=&#34;number&#34;&gt;25&lt;/span&gt;&amp;#125;&lt;/span&gt;&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        headers=&amp;#123;&lt;span class=&#34;string&#34;&gt;&amp;#x27;User-Agent&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;BaiduSpider&amp;#x27;&lt;/span&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    )&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    tree = etree.HTML(resp.text)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 通过XPath语法从页面中提取电影标题&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    title_spans = tree.xpath(&lt;span class=&#34;string&#34;&gt;&amp;#x27;//*[@id=&amp;quot;content&amp;quot;]/div/div[1]/ol/li/div/div[2]/div[1]/a/span[1]&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 通过XPath语法从页面中提取电影评分&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    rank_spans = tree.xpath(&lt;span class=&#34;string&#34;&gt;&amp;#x27;//*[@id=&amp;quot;content&amp;quot;]/div/div[1]/ol/li[1]/div/div[2]/div[2]/div/span[2]&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; title_span, rank_span &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; &lt;span class=&#34;built_in&#34;&gt;zip&lt;/span&gt;(title_spans, rank_spans):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(title_span.text, rank_span.text)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h3 id=&#34;CSS-选择器解析&#34;&gt;&lt;a href=&#34;#CSS-选择器解析&#34; class=&#34;headerlink&#34; title=&#34;CSS 选择器解析&#34;&gt;&lt;/a&gt;CSS 选择器解析&lt;/h3&gt;&lt;p&gt;对于熟悉 CSS 选择器和 JavaScript 的开发者来说，通过 CSS 选择器获取页面元素可能是更为简单的选择，因为浏览器中运行的 JavaScript 本身就可以&lt;code&gt;document&lt;/code&gt;对象的&lt;code&gt;querySelector()&lt;/code&gt;和&lt;code&gt;querySelectorAll()&lt;/code&gt;方法基于 CSS 选择器获取页面元素。在 Python 中，我们可以利用三方库&lt;code&gt;beautifulsoup4&lt;/code&gt;或&lt;code&gt;pyquery&lt;/code&gt;来做同样的事情。Beautiful Soup 可以用来解析 HTML 和 XML 文档，修复含有未闭合标签等错误的文档，通过为待解析的页面在内存中创建一棵树结构，实现对从页面中提取数据操作的封装。可以用下面的命令来安装 Beautiful Soup。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;pip install beautifulsoup4&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;下面是使用&lt;code&gt;bs4&lt;/code&gt;改写的获取豆瓣电影Top250电影名称的代码。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; bs4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; requests&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; page &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; &lt;span class=&#34;built_in&#34;&gt;range&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;11&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    resp = requests.get(&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        url=&lt;span class=&#34;string&#34;&gt;f&amp;#x27;https://movie.douban.com/top250?start=&lt;span class=&#34;subst&#34;&gt;&amp;#123;(page - &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;) * &lt;span class=&#34;number&#34;&gt;25&lt;/span&gt;&amp;#125;&lt;/span&gt;&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        headers=&amp;#123;&lt;span class=&#34;string&#34;&gt;&amp;#x27;User-Agent&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;BaiduSpider&amp;#x27;&lt;/span&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    )&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 创建BeautifulSoup对象&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    soup = bs4.BeautifulSoup(resp.text, &lt;span class=&#34;string&#34;&gt;&amp;#x27;lxml&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 通过CSS选择器从页面中提取包含电影标题的span标签&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    title_spans = soup.select(&lt;span class=&#34;string&#34;&gt;&amp;#x27;div.info &amp;gt; div.hd &amp;gt; a &amp;gt; span:nth-child(1)&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 通过CSS选择器从页面中提取包含电影评分的span标签&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    rank_spans = soup.select(&lt;span class=&#34;string&#34;&gt;&amp;#x27;div.info &amp;gt; div.bd &amp;gt; div &amp;gt; span.rating_num&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; title_span, rank_span &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; &lt;span class=&#34;built_in&#34;&gt;zip&lt;/span&gt;(title_spans, rank_spans):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(title_span.text, rank_span.text)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;关于 BeautifulSoup 更多的知识，可以参考它的&lt;a href=&#34;https://www.crummy.com/software/BeautifulSoup/bs4/doc.zh/&#34;&gt;官方文档&lt;/a&gt;。&lt;/p&gt;
&lt;h3 id=&#34;简单的总结&#34;&gt;&lt;a href=&#34;#简单的总结&#34; class=&#34;headerlink&#34; title=&#34;简单的总结&#34;&gt;&lt;/a&gt;简单的总结&lt;/h3&gt;&lt;p&gt;下面我们对三种解析方式做一个简单比较。&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;解析方式&lt;/th&gt;
&lt;th&gt;对应的模块&lt;/th&gt;
&lt;th&gt;速度&lt;/th&gt;
&lt;th&gt;使用难度&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;正则表达式解析&lt;/td&gt;
&lt;td&gt;&lt;code&gt;re&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;快&lt;/td&gt;
&lt;td&gt;困难&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;XPath 解析&lt;/td&gt;
&lt;td&gt;&lt;code&gt;lxml&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;快&lt;/td&gt;
&lt;td&gt;一般&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;CSS 选择器解析&lt;/td&gt;
&lt;td&gt;&lt;code&gt;bs4&lt;/code&gt;或&lt;code&gt;pyquery&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;不确定&lt;/td&gt;
&lt;td&gt;简单&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;

 &lt;h2 id=&#34;用Python获取网络数据&#34;&gt;&lt;a href=&#34;#用Python获取网络数据&#34; class=&#34;headerlink&#34; title=&#34;用Python获取网络数据&#34;&gt;&lt;/a&gt;用Python获取网络数据&lt;/h2&gt;&lt;p&gt;网络数据采集是 Python 语言非常擅长的领域，上节课我们讲到，实现网络数据采集的程序通常称之为网络爬虫或蜘蛛程序。即便是在大数据时代，数据对于中小企业来说仍然是硬伤和短板，有些数据需要通过开放或付费的数据接口来获得，其他的行业数据和竞对数据则必须要通过网络数据采集的方式来获得。不管使用哪种方式获取网络数据资源，Python 语言都是非常好的选择，因为 Python 的标准库和三方库都对网络数据采集提供了良好的支持。&lt;/p&gt;
&lt;h3 id=&#34;requests库&#34;&gt;&lt;a href=&#34;#requests库&#34; class=&#34;headerlink&#34; title=&#34;requests库&#34;&gt;&lt;/a&gt;requests库&lt;/h3&gt;&lt;p&gt;要使用 Python 获取网络数据，我们推荐大家使用名为&lt;code&gt;requests&lt;/code&gt; 的三方库，这个库我们在之前的课程中其实已经使用过了。按照官方网站的解释，&lt;code&gt;requests&lt;/code&gt;是基于 Python 标准库进行了封装，简化了通过 HTTP 或 HTTPS 访问网络资源的操作。上课我们提到过，HTTP 是一个请求响应式的协议，当我们在浏览器中输入正确的 &lt;a href=&#34;https://developer.mozilla.org/zh-CN/docs/Learn/Common_questions/What_is_a_URL&#34;&gt;URL&lt;/a&gt;（通常也称为网址）并按下 Enter 键时，我们就向网络上的 &lt;a href=&#34;https://developer.mozilla.org/zh-CN/docs/Learn/Common_questions/What_is_a_web_server&#34;&gt;Web 服务器&lt;/a&gt;发送了一个 HTTP 请求，服务器在收到请求后会给我们一个 HTTP 响应。在 Chrome 浏览器中的菜单中打开“开发者工具”切换到“Network”选项卡就能够查看 HTTP 请求和响应到底是什么样子的，如下图所示。&lt;/p&gt;
&lt;p&gt;&lt;img src=&#34;https://gitee.com/jackfrued/mypic/raw/master/20210822093434.png&#34;&gt;&lt;/p&gt;
&lt;p&gt;通过&lt;code&gt;requests&lt;/code&gt;库，我们可以让 Python 程序向浏览器一样向 Web 服务器发起请求，并接收服务器返回的响应，从响应中我们就可以提取出想要的数据。浏览器呈现给我们的网页是用 &lt;a href=&#34;https://developer.mozilla.org/zh-CN/docs/Web/HTML&#34;&gt;HTML&lt;/a&gt; 编写的，浏览器相当于是 HTML 的解释器环境，我们看到的网页中的内容都包含在 HTML 的标签中。在获取到 HTML 代码后，就可以从标签的属性或标签体中提取内容。下面例子演示了如何获取网页 HTML 代码，我们通过&lt;code&gt;requests&lt;/code&gt;库的&lt;code&gt;get&lt;/code&gt;函数，获取了搜狐首页的代码。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; requests&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;resp = requests.get(&lt;span class=&#34;string&#34;&gt;&amp;#x27;https://www.sohu.com/&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; resp.status_code == &lt;span class=&#34;number&#34;&gt;200&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(resp.text)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;说明&lt;/strong&gt;：上面代码中的变量&lt;code&gt;resp&lt;/code&gt;是一个&lt;code&gt;Response&lt;/code&gt;对象（&lt;code&gt;requests&lt;/code&gt;库封装的类型），通过该对象的&lt;code&gt;status_code&lt;/code&gt;属性可以获取响应状态码，而该对象的&lt;code&gt;text&lt;/code&gt;属性可以帮我们获取到页面的 HTML 代码。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;由于&lt;code&gt;Response&lt;/code&gt;对象的&lt;code&gt;text&lt;/code&gt;是一个字符串，所以我们可以利用之前讲过的正则表达式的知识，从页面的 HTML 代码中提取新闻的标题和链接，代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; re&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; requests&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;pattern = re.&lt;span class=&#34;built_in&#34;&gt;compile&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;r&amp;#x27;&amp;lt;a.*?href=&amp;quot;(.*?)&amp;quot;.*?title=&amp;quot;(.*?)&amp;quot;.*?&amp;gt;&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;resp = requests.get(&lt;span class=&#34;string&#34;&gt;&amp;#x27;https://www.sohu.com/&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; resp.status_code == &lt;span class=&#34;number&#34;&gt;200&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    all_matches = pattern.findall(resp.text)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; href, title &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; all_matches:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(href)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(title)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;除了文本内容，我们也可以使用&lt;code&gt;requests&lt;/code&gt;库通过 URL 获取二进制资源。下面的例子演示了如何获取百度 Logo 并保存到名为&lt;code&gt;baidu.png&lt;/code&gt;的本地文件中。可以在百度的首页上右键点击百度Logo，并通过“复制图片地址”菜单项获取图片的 URL。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; requests&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;resp = requests.get(&lt;span class=&#34;string&#34;&gt;&amp;#x27;https://www.baidu.com/img/PCtm_d9c8750bed0b3c7d089fa7d55720d6cf.png&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;with&lt;/span&gt; &lt;span class=&#34;built_in&#34;&gt;open&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&amp;#x27;baidu.png&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;wb&amp;#x27;&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;as&lt;/span&gt; file:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    file.write(resp.content)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;说明&lt;/strong&gt;：&lt;code&gt;Response&lt;/code&gt;对象的&lt;code&gt;content&lt;/code&gt;属性可以获得服务器响应的二进制数据。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;&lt;code&gt;requests&lt;/code&gt;库非常好用而且功能上也比较强大和完整，具体的内容我们在使用的过程中为大家一点点剖析。想解锁关于&lt;code&gt;requests&lt;/code&gt;库更多的知识，可以阅读它的&lt;a href=&#34;https://docs.python-requests.org/zh_CN/latest/&#34;&gt;官方文档&lt;/a&gt;。&lt;/p&gt;
&lt;h3 id=&#34;编写爬虫代码&#34;&gt;&lt;a href=&#34;#编写爬虫代码&#34; class=&#34;headerlink&#34; title=&#34;编写爬虫代码&#34;&gt;&lt;/a&gt;编写爬虫代码&lt;/h3&gt;&lt;p&gt;接下来，我们以“豆瓣电影”为例，为大家讲解如何编写爬虫代码。按照上面提供的方法，我们先使用&lt;code&gt;requests&lt;/code&gt;获取到网页的HTML代码，然后将整个代码看成一个长字符串，这样我们就可以使用正则表达式的捕获组从字符串提取我们需要的内容。下面的代码演示了如何从&lt;a href=&#34;https://movie.douban.com/&#34;&gt;豆瓣电影&lt;/a&gt;获取排前250名的电影的名称。&lt;a href=&#34;https://movie.douban.com/top250&#34;&gt;豆瓣电影Top250&lt;/a&gt;的页面结构和对应代码如下图所示，可以看出，每页共展示了25部电影，如果要获取到 Top250 数据，我们共需要访问10个页面，对应的地址是&lt;a href=&#34;https://movie.douban.com/top250?start=xxx&#34;&gt;https://movie.douban.com/top250?start=xxx&lt;/a&gt;，这里的&lt;code&gt;xxx&lt;/code&gt;如果为&lt;code&gt;0&lt;/code&gt;就是第一页，如果&lt;code&gt;xxx&lt;/code&gt;的值是&lt;code&gt;100&lt;/code&gt;，那么我们可以访问到第五页。为了代码简单易读，我们只获取电影的标题和评分。&lt;/p&gt;
&lt;p&gt;&lt;img src=&#34;https://gitee.com/jackfrued/mypic/raw/master/20210822093447.png&#34;&gt;&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; random&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; re&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; time&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; requests&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; page &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; &lt;span class=&#34;built_in&#34;&gt;range&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;11&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    resp = requests.get(&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        url=&lt;span class=&#34;string&#34;&gt;f&amp;#x27;https://movie.douban.com/top250?start=&lt;span class=&#34;subst&#34;&gt;&amp;#123;(page - &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;) * &lt;span class=&#34;number&#34;&gt;25&lt;/span&gt;&amp;#125;&lt;/span&gt;&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;# 如果不设置HTTP请求头中的User-Agent，豆瓣会检测出不是浏览器而阻止我们的请求。&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;# 通过get函数的headers参数设置User-Agent的值，具体的值可以在浏览器的开发者工具查看到。&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;# 用爬虫访问大部分网站时，将爬虫伪装成来自浏览器的请求都是非常重要的一步。&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        headers=&amp;#123;&lt;span class=&#34;string&#34;&gt;&amp;#x27;User-Agent&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;Mozilla/5.0 (Macintosh; Intel Mac OS X 10_14_6) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/92.0.4515.159 Safari/537.36&amp;#x27;&lt;/span&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    )&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 通过正则表达式获取class属性为title且标签体不以&amp;amp;开头的span标签并用捕获组提取标签内容&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    pattern1 = re.&lt;span class=&#34;built_in&#34;&gt;compile&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;r&amp;#x27;&amp;lt;span class=&amp;quot;title&amp;quot;&amp;gt;([^&amp;amp;]*?)&amp;lt;/span&amp;gt;&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    titles = pattern1.findall(resp.text)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 通过正则表达式获取class属性为rating_num的span标签并用捕获组提取标签内容&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    pattern2 = re.&lt;span class=&#34;built_in&#34;&gt;compile&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;r&amp;#x27;&amp;lt;span class=&amp;quot;rating_num&amp;quot;.*?&amp;gt;(.*?)&amp;lt;/span&amp;gt;&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    ranks = pattern2.findall(resp.text)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 使用zip压缩两个列表，循环遍历所有的电影标题和评分&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; title, rank &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; &lt;span class=&#34;built_in&#34;&gt;zip&lt;/span&gt;(titles, ranks):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(title, rank)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 随机休眠1-5秒，避免爬取页面过于频繁&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    time.sleep(random.random() * &lt;span class=&#34;number&#34;&gt;4&lt;/span&gt; + &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;说明&lt;/strong&gt;：通过分析豆瓣网的robots协议，我们发现豆瓣网并不拒绝百度爬虫获取它的数据，因此我们也可以将爬虫伪装成百度的爬虫，将&lt;code&gt;get&lt;/code&gt;函数的&lt;code&gt;headers&lt;/code&gt;参数修改为：&lt;code&gt;headers=&amp;#123;&amp;#39;User-Agent&amp;#39;: &amp;#39;BaiduSpider&amp;#39;&amp;#125;&lt;/code&gt;。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h3 id=&#34;使用-IP-代理&#34;&gt;&lt;a href=&#34;#使用-IP-代理&#34; class=&#34;headerlink&#34; title=&#34;使用 IP 代理&#34;&gt;&lt;/a&gt;使用 IP 代理&lt;/h3&gt;&lt;p&gt;让爬虫程序隐匿自己的身份对编写爬虫程序来说是比较重要的，很多网站对爬虫都比较反感的，因为爬虫会耗费掉它们很多的网络带宽并制造很多无效的流量。要隐匿身份通常需要使用&lt;strong&gt;商业 IP 代理&lt;/strong&gt;（如蘑菇代理、芝麻代理、快代理等），让被爬取的网站无法获取爬虫程序来源的真实 IP 地址，也就无法简单的通过 IP 地址对爬虫程序进行封禁。&lt;/p&gt;
&lt;p&gt;下面以&lt;a href=&#34;http://www.moguproxy.com/&#34;&gt;蘑菇代理&lt;/a&gt;为例，为大家讲解商业 IP 代理的使用方法。首先需要在该网站注册一个账号，注册账号后就可以&lt;a href=&#34;http://www.moguproxy.com/buy&#34;&gt;购买&lt;/a&gt;相应的套餐来获得商业 IP 代理。作为商业用途，建议大家购买不限量套餐，这样可以根据实际需要获取足够多的代理 IP 地址；作为学习用途，可以购买包时套餐或根据自己的需求来决定。蘑菇代理提供了两种接入代理的方式，分别是 API 私密代理和 HTTP 隧道代理，前者是通过请求蘑菇代理的 API 接口获取代理服务器地址，后者是直接使用统一的入口（蘑菇代理提供的域名）进行接入。&lt;/p&gt;
&lt;img src=&#34;https://gitee.com/jackfrued/mypic/raw/master/20210829080647.png&#34; width=&#34;75%&#34;&gt;

&lt;p&gt;下面，我们以HTTP隧道代理为例，为大家讲解接入 IP 代理的方式，大家也可以直接参考蘑菇代理官网提供的代码来为爬虫设置代理。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; requests&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;APP_KEY = &lt;span class=&#34;string&#34;&gt;&amp;#x27;Wnp******************************XFx&amp;#x27;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;PROXY_HOST = &lt;span class=&#34;string&#34;&gt;&amp;#x27;secondtransfer.moguproxy.com:9001&amp;#x27;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; page &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; &lt;span class=&#34;built_in&#34;&gt;range&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;11&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    resp = requests.get(&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        url=&lt;span class=&#34;string&#34;&gt;f&amp;#x27;https://movie.douban.com/top250?start=&lt;span class=&#34;subst&#34;&gt;&amp;#123;(page - &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;) * &lt;span class=&#34;number&#34;&gt;25&lt;/span&gt;&amp;#125;&lt;/span&gt;&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;# 需要在HTTP请求头设置代理的身份认证方式&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        headers=&amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;string&#34;&gt;&amp;#x27;Proxy-Authorization&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;f&amp;#x27;Basic &lt;span class=&#34;subst&#34;&gt;&amp;#123;APP_KEY&amp;#125;&lt;/span&gt;&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;string&#34;&gt;&amp;#x27;User-Agent&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;Mozilla/5.0 (Macintosh; Intel Mac OS X 10_14_6) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/92.0.4515.159 Safari/537.36&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;string&#34;&gt;&amp;#x27;Accept-Language&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;zh-CN,zh;q=0.8,en-US;q=0.6,en;q=0.4&amp;#x27;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &amp;#125;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;# 设置代理服务器&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        proxies=&amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;string&#34;&gt;&amp;#x27;http&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;f&amp;#x27;http://&lt;span class=&#34;subst&#34;&gt;&amp;#123;PROXY_HOST&amp;#125;&lt;/span&gt;&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;string&#34;&gt;&amp;#x27;https&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;f&amp;#x27;https://&lt;span class=&#34;subst&#34;&gt;&amp;#123;PROXY_HOST&amp;#125;&lt;/span&gt;&amp;#x27;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &amp;#125;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        verify=&lt;span class=&#34;literal&#34;&gt;False&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    )&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    pattern1 = re.&lt;span class=&#34;built_in&#34;&gt;compile&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;r&amp;#x27;&amp;lt;span class=&amp;quot;title&amp;quot;&amp;gt;([^&amp;amp;]*?)&amp;lt;/span&amp;gt;&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    titles = pattern1.findall(resp.text)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    pattern2 = re.&lt;span class=&#34;built_in&#34;&gt;compile&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;r&amp;#x27;&amp;lt;span class=&amp;quot;rating_num&amp;quot;.*?&amp;gt;(.*?)&amp;lt;/span&amp;gt;&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    ranks = pattern2.findall(resp.text)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; title, rank &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; &lt;span class=&#34;built_in&#34;&gt;zip&lt;/span&gt;(titles, ranks):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(title, rank)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;说明&lt;/strong&gt;：上面的代码需要修改&lt;code&gt;APP_KEY&lt;/code&gt;为自己创建的订单对应的&lt;code&gt;Appkey&lt;/code&gt;值，这个值可以在用户中心用户订单中查看到。蘑菇代理提供了免费的 API 代理和 HTTP 隧道代理试用，但是试用的代理接通率不能保证，建议大家还是直接购买一个在自己支付能力范围内的代理服务来体验。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h3 id=&#34;简单的总结&#34;&gt;&lt;a href=&#34;#简单的总结&#34; class=&#34;headerlink&#34; title=&#34;简单的总结&#34;&gt;&lt;/a&gt;简单的总结&lt;/h3&gt;&lt;p&gt;Python 语言能做的事情真的很多，就网络数据采集这一项而言，Python 几乎是一枝独秀的，大量的企业和个人都在使用 Python 从网络上获取自己需要的数据，这可能也是你将来日常工作的一部分。另外，用编写正则表达式的方式从网页中提取内容虽然可行，但是写出一个能够满足需求的正则表达式本身也不是件容易的事情，这一点对于新手来说尤为明显。在下一节课中，我们将会为大家介绍另外两种从页面中提取数据的方法，虽然从性能上来讲，它们可能不如正则表达式，但是却降低了编码的复杂性，相信大家会喜欢上它们的。&lt;/p&gt;

 &lt;h2 id=&#34;网络数据采集概述&#34;&gt;&lt;a href=&#34;#网络数据采集概述&#34; class=&#34;headerlink&#34; title=&#34;网络数据采集概述&#34;&gt;&lt;/a&gt;网络数据采集概述&lt;/h2&gt;&lt;p&gt;爬虫（crawler）也经常被称为网络蜘蛛（spider），是按照一定的规则自动浏览网站并获取所需信息的机器人程序（自动化脚本代码），被广泛的应用于互联网搜索引擎和数据采集。使用过互联网和浏览器的人都知道，网页中除了供用户阅读的文字信息之外，还包含一些超链接，网络爬虫正是通过网页中的超链接信息，不断获得网络上其它页面的地址，然后持续的进行数据采集。正因如此，网络数据采集的过程就像一个爬虫或者蜘蛛在网络上漫游，所以才被形象的称为爬虫或者网络蜘蛛。&lt;/p&gt;
&lt;h3 id=&#34;爬虫的应用领域&#34;&gt;&lt;a href=&#34;#爬虫的应用领域&#34; class=&#34;headerlink&#34; title=&#34;爬虫的应用领域&#34;&gt;&lt;/a&gt;爬虫的应用领域&lt;/h3&gt;&lt;p&gt;在理想的状态下，所有 ICP（Internet Content Provider）都应该为自己的网站提供 API 接口来共享它们允许其他程序获取的数据，在这种情况下就根本不需要爬虫程序。国内比较有名的电商平台（如淘宝、京东等）、社交平台（如微博、微信等）等都提供了自己的 API 接口，但是这类 API 接口通常会对可以抓取的数据以及抓取数据的频率进行限制。对于大多数的公司而言，及时的获取行业数据和竞对数据是企业生存的重要环节之一，然而对大部分企业来说，数据都是其与生俱来的短板。在这种情况下，合理的利用爬虫来获取数据并从中提取出有商业价值的信息对这些企业来说就显得至关重要的。&lt;/p&gt;
&lt;p&gt;爬虫的应用领域其实非常广泛，下面我们列举了其中的一部分，有兴趣的读者可以自行探索相关内容。&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;搜索引擎&lt;/li&gt;
&lt;li&gt;新闻聚合&lt;/li&gt;
&lt;li&gt;社交应用&lt;/li&gt;
&lt;li&gt;舆情监控&lt;/li&gt;
&lt;li&gt;行业数据&lt;/li&gt;
&lt;/ol&gt;
&lt;h3 id=&#34;爬虫合法性探讨&#34;&gt;&lt;a href=&#34;#爬虫合法性探讨&#34; class=&#34;headerlink&#34; title=&#34;爬虫合法性探讨&#34;&gt;&lt;/a&gt;爬虫合法性探讨&lt;/h3&gt;&lt;p&gt;经常听人说起“爬虫写得好，牢饭吃到饱”，那么编程爬虫程序是否违法呢？关于这个问题，我们可以从以下几个角度进行解读。&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;网络爬虫这个领域目前还属于拓荒阶段，虽然互联网世界已经通过自己的游戏规则建立起了一定的道德规范，即 Robots 协议（全称是“网络爬虫排除标准”），但法律部分还在建立和完善中，也就是说，现在这个领域暂时还是灰色地带。&lt;/li&gt;
&lt;li&gt;“法不禁止即为许可”，如果爬虫就像浏览器一样获取的是前端显示的数据（网页上的公开信息）而不是网站后台的私密敏感信息，就不太担心法律法规的约束，因为目前大数据产业链的发展速度远远超过了法律的完善程度。&lt;/li&gt;
&lt;li&gt;在爬取网站的时候，需要限制自己的爬虫遵守 Robots 协议，同时控制网络爬虫程序的抓取数据的速度；在使用数据的时候，必须要尊重网站的知识产权（从Web 2.0时代开始，虽然Web上的数据很多都是由用户提供的，但是网站平台是投入了运营成本的，当用户在注册和发布内容时，平台通常就已经获得了对数据的所有权、使用权和分发权）。如果违反了这些规定，在打官司的时候败诉几率相当高。&lt;/li&gt;
&lt;li&gt;适当的隐匿自己的身份在编写爬虫程序时必要的，而且最好不要被对方举证你的爬虫有破坏别人动产（例如服务器）的行为。&lt;/li&gt;
&lt;li&gt;不要在公网（如代码托管平台）上去开源或者展示你的爬虫代码，这些行为通常会给自己带来不必要的麻烦。&lt;/li&gt;
&lt;/ol&gt;
&lt;h4 id=&#34;Robots协议&#34;&gt;&lt;a href=&#34;#Robots协议&#34; class=&#34;headerlink&#34; title=&#34;Robots协议&#34;&gt;&lt;/a&gt;Robots协议&lt;/h4&gt;&lt;p&gt;大多数网站都会定义&lt;code&gt;robots.txt&lt;/code&gt;文件，这是一个君子协议，并不是所有爬虫都必须遵守的游戏规则。下面以淘宝的&lt;a href=&#34;http://www.taobao.com/robots.txt&#34;&gt;&lt;code&gt;robots.txt&lt;/code&gt;&lt;/a&gt;文件为例，看看淘宝网对爬虫有哪些限制。&lt;/p&gt;
&lt;figure class=&#34;highlight http&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;User-agent&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;: &lt;/span&gt;Baiduspider&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;Disallow&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;: &lt;/span&gt;/&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;User-agent&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;: &lt;/span&gt;baiduspider&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;Disallow&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;: &lt;/span&gt;/&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;通过上面的文件可以看出，淘宝禁止百度爬虫爬取它任何资源，因此当你在百度搜索“淘宝”的时候，搜索结果下方会出现：“由于该网站的&lt;code&gt;robots.txt&lt;/code&gt;文件存在限制指令（限制搜索引擎抓取），系统无法提供该页面的内容描述”。百度作为一个搜索引擎，至少在表面上遵守了淘宝网的&lt;code&gt;robots.txt&lt;/code&gt;协议，所以用户不能从百度上搜索到淘宝内部的产品信息。&lt;/p&gt;
&lt;p&gt;图1. 百度搜索淘宝的结果&lt;/p&gt;
&lt;p&gt;&lt;img src=&#34;https://gitee.com/jackfrued/mypic/raw/master/20210824004320.png&#34;&gt;&lt;/p&gt;
&lt;p&gt;下面是豆瓣网的&lt;a href=&#34;https://www.douban.com/robots.txt&#34;&gt;&lt;code&gt;robots.txt&lt;/code&gt;&lt;/a&gt;文件，大家可以自行解读，看看它做出了什么样的限制。&lt;/p&gt;
&lt;figure class=&#34;highlight dts&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;User-agent: *&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;symbol&#34;&gt;Disallow:&lt;/span&gt; /subject_search&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;symbol&#34;&gt;Disallow:&lt;/span&gt; /amazon_search&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;symbol&#34;&gt;Disallow:&lt;/span&gt; /search&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;symbol&#34;&gt;Disallow:&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;/group/&lt;/span&gt;search&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;symbol&#34;&gt;Disallow:&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;/event/&lt;/span&gt;search&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;symbol&#34;&gt;Disallow:&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;/celebrities/&lt;/span&gt;search&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;symbol&#34;&gt;Disallow:&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;/location/&lt;/span&gt;drama/search&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;symbol&#34;&gt;Disallow:&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;/forum/&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;symbol&#34;&gt;Disallow:&lt;/span&gt; /new_subject&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;symbol&#34;&gt;Disallow:&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;/service/&lt;/span&gt;iframe&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;symbol&#34;&gt;Disallow:&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;/j/&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;symbol&#34;&gt;Disallow:&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;/link2/&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;symbol&#34;&gt;Disallow:&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;/recommend/&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;symbol&#34;&gt;Disallow:&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;/doubanapp/&lt;/span&gt;card&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;symbol&#34;&gt;Disallow:&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;/update/&lt;/span&gt;topic/&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;symbol&#34;&gt;Disallow:&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;/share/&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;symbol&#34;&gt;Allow:&lt;/span&gt; /ads.txt&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;symbol&#34;&gt;Sitemap:&lt;/span&gt; https:&lt;span class=&#34;comment&#34;&gt;//www.douban.com/sitemap_index.xml&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;symbol&#34;&gt;Sitemap:&lt;/span&gt; https:&lt;span class=&#34;comment&#34;&gt;//www.douban.com/sitemap_updated_index.xml&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;meta&#34;&gt;# Crawl-delay: 5&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;User-agent: Wandoujia Spider&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;symbol&#34;&gt;Disallow:&lt;/span&gt; /&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;User-agent: Mediapartners-Google&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;symbol&#34;&gt;Disallow:&lt;/span&gt; /subject_search&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;symbol&#34;&gt;Disallow:&lt;/span&gt; /amazon_search&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;symbol&#34;&gt;Disallow:&lt;/span&gt; /search&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;symbol&#34;&gt;Disallow:&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;/group/&lt;/span&gt;search&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;symbol&#34;&gt;Disallow:&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;/event/&lt;/span&gt;search&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;symbol&#34;&gt;Disallow:&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;/celebrities/&lt;/span&gt;search&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;symbol&#34;&gt;Disallow:&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;/location/&lt;/span&gt;drama/search&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;symbol&#34;&gt;Disallow:&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;/j/&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h3 id=&#34;超文本传输协议（HTTP）&#34;&gt;&lt;a href=&#34;#超文本传输协议（HTTP）&#34; class=&#34;headerlink&#34; title=&#34;超文本传输协议（HTTP）&#34;&gt;&lt;/a&gt;超文本传输协议（HTTP）&lt;/h3&gt;&lt;p&gt;在开始讲解爬虫之前，我们稍微对超文本传输协议（HTTP）做一些回顾，因为我们在网页上看到的内容通常是浏览器执行 HTML （超文本标记语言）得到的结果，而 HTTP 就是传输 HTML 数据的协议。HTTP 和其他很多应用级协议一样是构建在 TCP（传输控制协议）之上的，它利用了 TCP 提供的可靠的传输服务实现了 Web 应用中的数据交换。按照维基百科上的介绍，设计 HTTP 最初的目的是为了提供一种发布和接收 &lt;a href=&#34;https://zh.wikipedia.org/wiki/HTML&#34;&gt;HTML&lt;/a&gt; 页面的方法，也就是说，这个协议是浏览器和 Web 服务器之间传输的数据的载体。关于 HTTP 的详细信息以及目前的发展状况，大家可以阅读&lt;a href=&#34;http://www.ruanyifeng.com/blog/2016/08/http.html&#34;&gt;《HTTP 协议入门》&lt;/a&gt;、&lt;a href=&#34;http://www.ruanyifeng.com/blog/2012/05/internet_protocol_suite_part_i.html&#34;&gt;《互联网协议入门》&lt;/a&gt;、&lt;a href=&#34;http://www.ruanyifeng.com/blog/2014/09/illustration-ssl.html&#34;&gt;《图解 HTTPS 协议》&lt;/a&gt;等文章进行了解。&lt;/p&gt;
&lt;p&gt;下图是我在四川省网络通信技术重点实验室工作期间用开源协议分析工具 Ethereal（WireShark 的前身）截取的访问百度首页时的 HTTP 请求和响应的报文（协议数据），由于 Ethereal 截取的是经过网络适配器的数据，因此可以清晰的看到从物理链路层到应用层的协议数据。&lt;/p&gt;
&lt;p&gt;图2. HTTP请求&lt;/p&gt;
&lt;p&gt;&lt;img src=&#34;https://gitee.com/jackfrued/mypic/raw/master/20210824003915.png&#34; alt=&#34;http-request&#34;&gt;&lt;/p&gt;
&lt;p&gt;HTTP 请求通常是由请求行、请求头、空行、消息体四个部分构成，如果没有数据发给服务器，消息体就不是必须的部分。请求行中包含了请求方法（GET、POST 等，如下表所示）、资源路径和协议版本；请求头由若干键值对构成，包含了浏览器、编码方式、首选语言、缓存策略等信息；请求头的后面是空行和消息体。&lt;/p&gt;
&lt;img src=&#34;https://gitee.com/jackfrued/mypic/raw/master/20210825002720.PNG&#34; width=&#34;65%&#34;&gt;

&lt;p&gt;图3. HTTP响应&lt;/p&gt;
&lt;p&gt;&lt;img src=&#34;https://gitee.com/jackfrued/mypic/raw/master/20210824234158.png&#34; alt=&#34;http-response&#34;&gt;&lt;/p&gt;
&lt;p&gt;HTTP 响应通常是由响应行、响应头、空行、消息体四个部分构成，其中消息体是服务响应的数据，可能是 HTML 页面，也有可能是JSON或二进制数据等。响应行中包含了协议版本和响应状态码，响应状态码有很多种，常见的如下表所示。&lt;/p&gt;
&lt;img src=&#34;https://gitee.com/jackfrued/mypic/raw/master/20210825002802.PNG&#34; width=&#34;65%&#34;&gt;

&lt;h4 id=&#34;相关工具&#34;&gt;&lt;a href=&#34;#相关工具&#34; class=&#34;headerlink&#34; title=&#34;相关工具&#34;&gt;&lt;/a&gt;相关工具&lt;/h4&gt;&lt;p&gt;下面我们先介绍一些开发爬虫程序的辅助工具，这些工具相信能帮助你事半功倍。&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;&lt;p&gt;Chrome Developer Tools：谷歌浏览器内置的开发者工具。该工具最常用的几个功能模块是：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;元素（ELements）：用于查看或修改 HTML 元素的属性、CSS 属性、监听事件等。CSS 可以即时修改，即时显示，大大方便了开发者调试页面。&lt;/li&gt;
&lt;li&gt;控制台（Console）：用于执行一次性代码，查看 JavaScript 对象，查看调试日志信息或异常信息。控制台其实就是一个执行 JavaScript 代码的交互式环境。&lt;/li&gt;
&lt;li&gt;源代码（Sources）：用于查看页面的 HTML 文件源代码、JavaScript 源代码、CSS 源代码，此外最重要的是可以调试 JavaScript 源代码，可以给代码添加断点和单步执行。&lt;/li&gt;
&lt;li&gt;网络（Network）：用于 HTTP 请求、HTTP 响应以及与网络连接相关的信息。&lt;/li&gt;
&lt;li&gt;应用（Application）：用于查看浏览器本地存储、后台任务等内容，本地存储主要包括Cookie、Local Storage、Session Storage等。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;img src=&#34;https://gitee.com/jackfrued/mypic/raw/master/20210824004034.png&#34; alt=&#34;chrome-developer-tools&#34;&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;Postman：功能强大的网页调试与 RESTful 请求工具。Postman可以帮助我们模拟请求，非常方便的定制我们的请求以及查看服务器的响应。&lt;/p&gt;
&lt;p&gt;&lt;img src=&#34;https://gitee.com/jackfrued/mypic/raw/master/20210824004048.png&#34; alt=&#34;postman&#34;&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;HTTPie：命令行HTTP客户端。&lt;/p&gt;
&lt;p&gt;安装。&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;pip install httpie&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;使用。&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;http --header http --header https://movie.douban.com/&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;HTTP/1.1 200 OK&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;Connection: keep-alive&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;Content-Encoding: gzip&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;Content-Type: text/html; charset=utf-8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;Date: Tue, 24 Aug 2021 16:48:00 GMT&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;Keep-Alive: &lt;span class=&#34;built_in&#34;&gt;timeout&lt;/span&gt;=30&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;Server: dae&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;Set-Cookie: bid=58h4BdKC9lM; Expires=Wed, 24-Aug-22 16:48:00 GMT; Domain=.douban.com; Path=/&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;Strict-Transport-Security: max-age=15552000&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;Transfer-Encoding: chunked&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;X-Content-Type-Options: nosniff&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;X-DOUBAN-NEWBID: 58h4BdKC9lM&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;code&gt;builtwith&lt;/code&gt;库：识别网站所用技术的工具。&lt;/p&gt;
&lt;p&gt;安装。&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;pip install builtwith&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;使用。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; ssl&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; builtwith&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;ssl._create_default_https_context = ssl._create_unverified_context&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(builtwith.parse(&lt;span class=&#34;string&#34;&gt;&amp;#x27;http://www.bootcss.com/&amp;#x27;&lt;/span&gt;))&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;code&gt;python-whois&lt;/code&gt;库：查询网站所有者的工具。&lt;/p&gt;
&lt;p&gt;安装。&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;pip3 install python-whois&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;使用。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; whois&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;print&lt;/span&gt;(whois.whois(&lt;span class=&#34;string&#34;&gt;&amp;#x27;https://www.bootcss.com&amp;#x27;&lt;/span&gt;))&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;/li&gt;
&lt;/ol&gt;
&lt;h3 id=&#34;爬虫的基本工作流程&#34;&gt;&lt;a href=&#34;#爬虫的基本工作流程&#34; class=&#34;headerlink&#34; title=&#34;爬虫的基本工作流程&#34;&gt;&lt;/a&gt;爬虫的基本工作流程&lt;/h3&gt;&lt;p&gt;一个基本的爬虫通常分为数据采集（网页下载）、数据处理（网页解析）和数据存储（将有用的信息持久化）三个部分的内容，当然更为高级的爬虫在数据采集和处理时会使用并发编程或分布式技术，这就需要有调度器（安排线程或进程执行对应的任务）、后台管理程序（监控爬虫的工作状态以及检查数据抓取的结果）等的参与。&lt;/p&gt;
&lt;p&gt;&lt;img src=&#34;https://gitee.com/jackfrued/mypic/raw/master/20210824004107.png&#34; alt=&#34;crawler-workflow&#34;&gt;&lt;/p&gt;
&lt;p&gt;一般来说，爬虫的工作流程包括以下几个步骤：&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;设定抓取目标（种子页面&amp;#x2F;起始页面）并获取网页。&lt;/li&gt;
&lt;li&gt;当服务器无法访问时，按照指定的重试次数尝试重新下载页面。&lt;/li&gt;
&lt;li&gt;在需要的时候设置用户代理或隐藏真实IP，否则可能无法访问页面。&lt;/li&gt;
&lt;li&gt;对获取的页面进行必要的解码操作然后抓取出需要的信息。&lt;/li&gt;
&lt;li&gt;在获取的页面中通过某种方式（如正则表达式）抽取出页面中的链接信息。&lt;/li&gt;
&lt;li&gt;对链接进行进一步的处理（获取页面并重复上面的动作）。&lt;/li&gt;
&lt;li&gt;将有用的信息进行持久化以备后续的处理。&lt;/li&gt;
&lt;/ol&gt;

 &lt;h2 id=&#34;用FastAPI开发网络数据接口&#34;&gt;&lt;a href=&#34;#用FastAPI开发网络数据接口&#34; class=&#34;headerlink&#34; title=&#34;用FastAPI开发网络数据接口&#34;&gt;&lt;/a&gt;用FastAPI开发网络数据接口&lt;/h2&gt;&lt;p&gt;FastAPI 是一个用于构建API（网络数据接口）的现代、高性能的Web框架，基于Python 3.6+，使用了Python中的类型提示进行类型检查，非常符合工程化开发的需求，在业界有非常好的口碑。下面，我们先用代码告诉大家FastAPI到底能做什么，然后再来讲解它的方方面面。&lt;/p&gt;
&lt;h3 id=&#34;FastAPI五分钟上手&#34;&gt;&lt;a href=&#34;#FastAPI五分钟上手&#34; class=&#34;headerlink&#34; title=&#34;FastAPI五分钟上手&#34;&gt;&lt;/a&gt;FastAPI五分钟上手&lt;/h3&gt;&lt;ol&gt;
&lt;li&gt;&lt;p&gt;安装依赖库和ASGI服务器（支持异步I&amp;#x2F;O的Python服务器）。&lt;/p&gt;
 &lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;pip install fastapi&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;pip install uvicorn&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;编写代码&lt;code&gt;main.py&lt;/code&gt;。&lt;/p&gt;
 &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; fastapi &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; FastAPI&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;app = FastAPI()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;meta&#34;&gt;@app.get(&lt;span class=&#34;params&#34;&gt;&lt;span class=&#34;string&#34;&gt;&amp;#x27;/&amp;#x27;&lt;/span&gt;&lt;/span&gt;)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;say_hello&lt;/span&gt;():&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; &amp;#123;&lt;span class=&#34;string&#34;&gt;&amp;#x27;code&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;number&#34;&gt;200&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;message&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;hello, world!&amp;#x27;&lt;/span&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;运行服务。&lt;/p&gt;
 &lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;uvicorn main:app --reload&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;说明&lt;/strong&gt;：上面运行uvicorn时使用的&lt;code&gt;--reload&lt;/code&gt;参数会在代码发生变更时自动重新加载新的内容，这个参数在开发阶段非常的有用。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;访问服务。&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;  &lt;img src=&#34;/res/run-first-demo.png&#34;&gt;&lt;/p&gt;
&lt;ol start=&#34;5&#34;&gt;
&lt;li&gt;&lt;p&gt;查看文档。&lt;/p&gt;
&lt;p&gt; &lt;img src=&#34;/res/first-demo-docs.png&#34;&gt;&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;注意&lt;/strong&gt;：FastAPI会基于&lt;a href=&#34;https://swagger.io/tools/swagger-ui/&#34;&gt;Swagger UI&lt;/a&gt;自动为数据接口生成对应的文档。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;h3 id=&#34;请求和响应&#34;&gt;&lt;a href=&#34;#请求和响应&#34; class=&#34;headerlink&#34; title=&#34;请求和响应&#34;&gt;&lt;/a&gt;请求和响应&lt;/h3&gt;&lt;h3 id=&#34;接入关系型数据库&#34;&gt;&lt;a href=&#34;#接入关系型数据库&#34; class=&#34;headerlink&#34; title=&#34;接入关系型数据库&#34;&gt;&lt;/a&gt;接入关系型数据库&lt;/h3&gt;&lt;p&gt;我们可以使用SQLAlchemy三方库来实现对关系型数据库的接入。SQLAlchemy是一个ORM（对象关系映射）框架，ORM框架可以解决Python程序的面向对象模型和关系型数据库的关系模型并不匹配的问题，使得我们可以用面向对象的方式实现数据的CRUD操作。&lt;/p&gt;
&lt;h3 id=&#34;依赖注入&#34;&gt;&lt;a href=&#34;#依赖注入&#34; class=&#34;headerlink&#34; title=&#34;依赖注入&#34;&gt;&lt;/a&gt;依赖注入&lt;/h3&gt;&lt;h3 id=&#34;中间件&#34;&gt;&lt;a href=&#34;#中间件&#34; class=&#34;headerlink&#34; title=&#34;中间件&#34;&gt;&lt;/a&gt;中间件&lt;/h3&gt;&lt;h3 id=&#34;异步化&#34;&gt;&lt;a href=&#34;#异步化&#34; class=&#34;headerlink&#34; title=&#34;异步化&#34;&gt;&lt;/a&gt;异步化&lt;/h3&gt;&lt;h3 id=&#34;虚拟化部署（Docker）&#34;&gt;&lt;a href=&#34;#虚拟化部署（Docker）&#34; class=&#34;headerlink&#34; title=&#34;虚拟化部署（Docker）&#34;&gt;&lt;/a&gt;虚拟化部署（Docker）&lt;/h3&gt;&lt;h3 id=&#34;项目实战：车辆违章查询&#34;&gt;&lt;a href=&#34;#项目实战：车辆违章查询&#34; class=&#34;headerlink&#34; title=&#34;项目实战：车辆违章查询&#34;&gt;&lt;/a&gt;项目实战：车辆违章查询&lt;/h3&gt;

 &lt;h2 id=&#34;异步任务和定时任务&#34;&gt;&lt;a href=&#34;#异步任务和定时任务&#34; class=&#34;headerlink&#34; title=&#34;异步任务和定时任务&#34;&gt;&lt;/a&gt;异步任务和定时任务&lt;/h2&gt;&lt;p&gt;在Web应用中，如果一个请求执行了耗时间的操作或者该请求的执行时间无法确定，而且对于用户来说只需要知道服务器接收了他的请求，并不需要马上得到请求的执行结果，这样的操作我们就应该对其进行异步化处理。如果说&lt;strong&gt;使用缓存是优化网站性能的第一要义&lt;/strong&gt;，那么将耗时间或执行时间不确定的任务&lt;strong&gt;异步化则是网站性能优化的第二要义&lt;/strong&gt;，简单的说就是&lt;strong&gt;能推迟做的事情都不要马上做&lt;/strong&gt;。&lt;/p&gt;
&lt;p&gt;上一章节中讲到的发短信和上传文件到云存储为例，这两个操作前者属于时间不确定的操作（因为作为调用者，我们不能确定三方平台响应的时间），后者属于耗时间的操作（如果文件较大或者三方平台不稳定，都可能导致上传的时间较长），很显然，这两个操作都可以做异步化处理。&lt;/p&gt;
&lt;p&gt;在Python项目中实现异步化处理可以使用多线程或借助三方库Celery来完成。&lt;/p&gt;
&lt;h3 id=&#34;使用Celery实现异步化&#34;&gt;&lt;a href=&#34;#使用Celery实现异步化&#34; class=&#34;headerlink&#34; title=&#34;使用Celery实现异步化&#34;&gt;&lt;/a&gt;使用Celery实现异步化&lt;/h3&gt;&lt;h3 id=&#34;使用多线程实现异步化&#34;&gt;&lt;a href=&#34;#使用多线程实现异步化&#34; class=&#34;headerlink&#34; title=&#34;使用多线程实现异步化&#34;&gt;&lt;/a&gt;使用多线程实现异步化&lt;/h3&gt;

 &lt;h2 id=&#34;接入三方平台&#34;&gt;&lt;a href=&#34;#接入三方平台&#34; class=&#34;headerlink&#34; title=&#34;接入三方平台&#34;&gt;&lt;/a&gt;接入三方平台&lt;/h2&gt;&lt;p&gt;在Web应用的开发过程中，有一些任务并不是我们自己能够完成的。例如，我们的Web项目中需要做个人或企业的实名认证，很显然我们并没有能力判断用户提供的认证信息的真实性，这个时候我们就要借助三方平台提供的服务来完成该项操作。再比如说，我们的项目中需要提供在线支付功能，这类业务通常也是借助支付网关来完成而不是自己去实现，我们只需要接入像微信、支付宝、银联这样的三方平台即可。&lt;/p&gt;
&lt;p&gt;在项目中接入三方平台基本上就两种方式：API接入和SDK接入。&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;API接入指的是通过访问三方提供的URL来完成操作或获取数据。国内有很多这样的平台提供了大量常用的服务，例如&lt;a href=&#34;https://www.juhe.cn/&#34;&gt;聚合数据&lt;/a&gt;上提供了生活服务类、金融科技类、交通地理类、充值缴费类等各种类型的API。我们可以通过Python程序发起网络请求，通过访问URL获取数据，这些API接口跟我们项目中提供的数据接口是一样的，只不过我们项目中的API是供自己使用的，而这类三方平台提供的API是开放的。当然开放并不代表免费，大多数能够提供有商业价值的数据的API都是需要付费才能使用的。&lt;/li&gt;
&lt;li&gt;SDK接入指的是通过安装三方库并使用三方库封装的类、函数来使用三方平台提供的服务的方式。例如我们刚才说到的接入支付宝，就需要先安装支付宝的SDK，然后通过支付宝封装的类和方法完成对支付服务的调用。&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;下面我们通过具体的例子来讲解如何接入三方平台。&lt;/p&gt;
&lt;h3 id=&#34;接入短信网关&#34;&gt;&lt;a href=&#34;#接入短信网关&#34; class=&#34;headerlink&#34; title=&#34;接入短信网关&#34;&gt;&lt;/a&gt;接入短信网关&lt;/h3&gt;&lt;p&gt;一个Web项目有很多地方都可以用到短信服务，例如：手机验证码登录、重要消息提醒、产品营销短信等。要实现发送短信的功能，可以通过接入短信网关来实现，国内比较有名的短信网关包括：云片短信、网易云信、螺丝帽、SendCloud等，这些短信网关一般都提供了免费试用功能。下面我们以&lt;a href=&#34;https://luosimao.com/&#34;&gt;螺丝帽&lt;/a&gt;平台为例，讲解如何在项目中接入短信网关，其他平台操作基本类似。&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;&lt;p&gt;注册账号，新用户可以免费试用。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;登录到管理后台，进入短信版块。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;点击“触发发送”可以找到自己专属的API Key（身份标识）。&lt;/p&gt;
&lt;p&gt; &lt;img src=&#34;/res/luosimao-sms-apikey.png&#34;&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;点击“签名管理”可以添加短信签名，短信都必须携带签名，免费试用的短信要在短信中添加“【铁壳测试】”这个签名，否则短信无法发送。&lt;/p&gt;
&lt;p&gt; &lt;img src=&#34;/res/luosimao-sms-signature.png&#34;&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;点击“IP白名单”将运行Django项目的服务器地址（公网IP地址，本地运行可以打开&lt;a href=&#34;&#34;&gt;xxx&lt;/a&gt;网站查看自己本机的公网IP地址）填写到白名单中，否则短信无法发送。&lt;/p&gt;
&lt;p&gt; &lt;img src=&#34;/res/luosimao-sms-whitelist.png&#34;&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;如果没有剩余的短信条数，可以到“充值”页面选择“短信服务”进行充值。&lt;/p&gt;
&lt;p&gt; &lt;img src=&#34;/res/luosimao-pay-onlinebuy.png&#34;&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;接下来，我们可以通过调用螺丝帽短信网关实现发送短信验证码的功能，代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;send_mobile_code&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;tel, code&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;&amp;quot;&amp;quot;发送短信验证码&amp;quot;&amp;quot;&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    resp = requests.post(&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        url=&lt;span class=&#34;string&#34;&gt;&amp;#x27;http://sms-api.luosimao.com/v1/send.json&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        auth=(&lt;span class=&#34;string&#34;&gt;&amp;#x27;api&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;key-自己的APIKey&amp;#x27;&lt;/span&gt;),&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        data=&amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;string&#34;&gt;&amp;#x27;mobile&amp;#x27;&lt;/span&gt;: tel,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;string&#34;&gt;&amp;#x27;message&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;f&amp;#x27;您的短信验证码是&lt;span class=&#34;subst&#34;&gt;&amp;#123;code&amp;#125;&lt;/span&gt;，打死也不能告诉别人哟。【Python小课】&amp;#x27;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &amp;#125;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        verify=&lt;span class=&#34;literal&#34;&gt;False&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    )&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; resp.json()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;运行上面的代码需要先安装&lt;code&gt;requests&lt;/code&gt;三方库，这个三方库封装了HTTP网络请求的相关功能，使用起来非常的简单，我们在之前的内容中也讲到过这个三方库。&lt;code&gt;send_mobile_code&lt;/code&gt;函数有两个参数，第一个参数是手机号，第二个参数是短信验证码的内容，第5行代码需要提供自己的API Key，就是上面第2步中查看到的自己的API Key。请求螺丝帽的短信网关会返回JSON格式的数据，对于上面的代码如果返回&lt;code&gt;&amp;#123;&amp;#39;err&amp;#39;: 0, &amp;#39;msg&amp;#39;: &amp;#39;ok&amp;#39;&amp;#125;&lt;/code&gt;，则表示短信发送成功，如果&lt;code&gt;err&lt;/code&gt;字段的值不为&lt;code&gt;0&lt;/code&gt;而是其他值，则表示短信发送失败，可以在螺丝帽官方的&lt;a href=&#34;https://luosimao.com/docs/api/&#34;&gt;开发文档&lt;/a&gt;页面上查看到不同的数值代表的含义，例如：&lt;code&gt;-20&lt;/code&gt;表示余额不足，&lt;code&gt;-32&lt;/code&gt;表示缺少短信签名。&lt;/p&gt;
&lt;p&gt;可以在视图函数中调用上面的函数来完成发送短信验证码的功能，稍后我们可以把这个功能跟用户注册结合起来。&lt;/p&gt;
&lt;p&gt;生成随机验证码和验证手机号的函数。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; random&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; re&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;TEL_PATTERN = re.&lt;span class=&#34;built_in&#34;&gt;compile&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;r&amp;#x27;1[3-9]\d&amp;#123;9&amp;#125;&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;check_tel&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;tel&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;&amp;quot;&amp;quot;检查手机号&amp;quot;&amp;quot;&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; TEL_PATTERN.fullmatch(tel) &lt;span class=&#34;keyword&#34;&gt;is&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;not&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;None&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;random_code&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;length=&lt;span class=&#34;number&#34;&gt;6&lt;/span&gt;&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;&amp;quot;&amp;quot;生成随机短信验证码&amp;quot;&amp;quot;&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;#x27;&amp;#x27;&lt;/span&gt;.join(random.choices(&lt;span class=&#34;string&#34;&gt;&amp;#x27;0123456789&amp;#x27;&lt;/span&gt;, k=length))&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;发送短信验证码的视图函数。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;meta&#34;&gt;@api_view(&lt;span class=&#34;params&#34;&gt;(&lt;span class=&#34;params&#34;&gt;&lt;span class=&#34;string&#34;&gt;&amp;#x27;GET&amp;#x27;&lt;/span&gt;, &lt;/span&gt;)&lt;/span&gt;)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;get_mobilecode&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;request, tel&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;&amp;quot;&amp;quot;获取短信验证码&amp;quot;&amp;quot;&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; check_tel(tel):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        redis_cli = get_redis_connection()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; redis_cli.exists(&lt;span class=&#34;string&#34;&gt;f&amp;#x27;vote:block-mobile:&lt;span class=&#34;subst&#34;&gt;&amp;#123;tel&amp;#125;&lt;/span&gt;&amp;#x27;&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            data = &amp;#123;&lt;span class=&#34;string&#34;&gt;&amp;#x27;code&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;number&#34;&gt;30001&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;message&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;请不要在60秒内重复发送短信验证码&amp;#x27;&lt;/span&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;else&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            code = random_code()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            send_mobile_code(tel, code)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;comment&#34;&gt;# 通过Redis阻止60秒内容重复发送短信验证码&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            redis_cli.&lt;span class=&#34;built_in&#34;&gt;set&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;f&amp;#x27;vote:block-mobile:&lt;span class=&#34;subst&#34;&gt;&amp;#123;tel&amp;#125;&lt;/span&gt;&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;x&amp;#x27;&lt;/span&gt;, ex=&lt;span class=&#34;number&#34;&gt;60&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;comment&#34;&gt;# 将验证码在Redis中保留10分钟（有效期10分钟）&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            redis_cli.&lt;span class=&#34;built_in&#34;&gt;set&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;f&amp;#x27;vote2:valid-mobile:&lt;span class=&#34;subst&#34;&gt;&amp;#123;tel&amp;#125;&lt;/span&gt;&amp;#x27;&lt;/span&gt;, code, ex=&lt;span class=&#34;number&#34;&gt;600&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            data = &amp;#123;&lt;span class=&#34;string&#34;&gt;&amp;#x27;code&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;number&#34;&gt;30000&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;message&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;短信验证码已发送，请注意查收&amp;#x27;&lt;/span&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;else&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        data = &amp;#123;&lt;span class=&#34;string&#34;&gt;&amp;#x27;code&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;number&#34;&gt;30002&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;message&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;请输入有效的手机号&amp;#x27;&lt;/span&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; Response(data)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;说明&lt;/strong&gt;：上面的代码利用Redis实现了两个额外的功能，一个是阻止用户60秒内重复发送短信验证码，一个是将用户的短信验证码保留10分钟，也就是说这个短信验证码的有效期只有10分钟，我们可以要求用户在注册时提供该验证码来验证用户手机号的真实性。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h3 id=&#34;接入云存储服务&#34;&gt;&lt;a href=&#34;#接入云存储服务&#34; class=&#34;headerlink&#34; title=&#34;接入云存储服务&#34;&gt;&lt;/a&gt;接入云存储服务&lt;/h3&gt;&lt;p&gt;当我们提到&lt;strong&gt;云存储&lt;/strong&gt;这个词的时候，通常是指把数据存放在由第三方提供的虚拟服务器环境下，简单的说就是将某些数据或资源通过第三平台托管。一般情况下，提供云存储服务的公司都运营着大型的数据中心，需要云存储服务的个人或组织通过向其购买或租赁存储空间来满足数据存储的需求。在开发Web应用时，可以将静态资源，尤其是用户上传的静态资源直接置于云存储服务中，云存储通常会提供对应的URL使得用户可以访问该静态资源。国内外比较有名的云存储服务（如：亚马逊的S3、阿里的OSS2等）一般都物美价廉，相比自己架设静态资源服务器，云存储的代价更小，而且一般的云存储平台都提供了CDN服务，用于加速对静态资源的访问，所以不管从哪个角度出发，使用云存储的方式管理Web应用的数据和静态资源都是非常好的选择，除非这些资源涉及到个人或商业隐私，否则就可以托管到云存储中。&lt;/p&gt;
&lt;p&gt;下面我们以接入&lt;a href=&#34;https://www.qiniu.com/&#34;&gt;七牛云&lt;/a&gt;为例，讲解如何实现将用户上传的文件保存到七牛云存储。七牛云是国内知名的云计算及数据服务提供商，七牛云在海量文件存储、CDN、视频点播、互动直播以及大规模异构数据的智能分析与处理等领域都有自己的产品，而且非付费用户也可以免费接入，使用其提供的服务。下面是接入七牛云的流程：&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;&lt;p&gt;注册账号，登录管理控制台。&lt;/p&gt;
&lt;p&gt; &lt;img src=&#34;/res/qiniu-manage-console.png&#34;&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;选择左侧菜单中的对象存储。&lt;/p&gt;
&lt;p&gt; &lt;img src=&#34;/res/qiniu-storage-service.png&#34;&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;在空间管理中选择新建空间（例如：myvote），如果提示空间名称已被占用，更换一个再尝试即可。注意，创建空间后会提示绑定自定义域名，如果暂时还没有自己的域名，可以使用七牛云提供的临时域名，但是临时域名会在30天后被回收，所以最好准备自己的域名（域名需要备案，不清楚如何操作的请自行查阅相关资料）。&lt;/p&gt;
&lt;p&gt; &lt;img src=&#34;/res/qiniu-storage-create.png&#34;&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;在网页的右上角点击个人头像中的“密钥管理”，查看自己的密钥，稍后在代码中需要使用AK（AccessKey）和SK（SecretKey）两个密钥来认证用户身份。&lt;/p&gt;
&lt;p&gt; &lt;img src=&#34;/res/qiniu-secretkey-management.png&#34;&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;点击网页上方菜单中的“文档”，进入到&lt;a href=&#34;https://developer.qiniu.com/&#34;&gt;七牛开发者中心&lt;/a&gt;，选择导航菜单中的“SDK&amp;amp;工具”并点击“官方SDK”子菜单，找到Python（服务端）并点击“文档”查看官方文档。&lt;/p&gt;
&lt;p&gt; &lt;img src=&#34;/res/qiniu-document-python.png&#34;&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;接下来，只要安装官方文档提供的示例，就可以接入七牛云，使用七牛云提供的云存储以及其他服务。首先可以通过下面的命令安装七牛云的三方库。&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;pip install qiniu&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;接下来可以通过&lt;code&gt;qiniu&lt;/code&gt;模块中的&lt;code&gt;put_file&lt;/code&gt;和&lt;code&gt;put_stream&lt;/code&gt;两个函数实现文件上传，前者可以上传指定路径的文件，后者可以将内存中的二进制数据上传至七牛云，具体的代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; qiniu&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;AUTH = qiniu.Auth(&lt;span class=&#34;string&#34;&gt;&amp;#x27;密钥管理中的AccessKey&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;密钥管理中的SecretKey&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;BUCKET_NAME = &lt;span class=&#34;string&#34;&gt;&amp;#x27;myvote&amp;#x27;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;upload_file_to_qiniu&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;key, file_path&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;&amp;quot;&amp;quot;上传指定路径的文件到七牛云&amp;quot;&amp;quot;&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    token = AUTH.upload_token(BUCKET_NAME, key)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; qiniu.put_file(token, key, file_path)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;upload_stream_to_qiniu&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;key, stream, size&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;&amp;quot;&amp;quot;上传二进制数据流到七牛云&amp;quot;&amp;quot;&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    token = AUTH.upload_token(BUCKET_NAME, key)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; qiniu.put_stream(token, key, stream, &lt;span class=&#34;literal&#34;&gt;None&lt;/span&gt;, size)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;下面是一个文件上传的简单前端页。&lt;/p&gt;
&lt;figure class=&#34;highlight html&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;meta&#34;&gt;&amp;lt;!DOCTYPE &lt;span class=&#34;keyword&#34;&gt;html&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;html&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;lang&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;en&amp;quot;&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;head&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;meta&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;charset&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;UTF-8&amp;quot;&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;title&lt;/span&gt;&amp;gt;&lt;/span&gt;上传文件&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;title&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;head&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;body&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;form&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;action&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;/upload/&amp;quot;&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;method&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;post&amp;quot;&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;enctype&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;multipart/form-data&amp;quot;&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;div&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;input&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;type&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;file&amp;quot;&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;name&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;photo&amp;quot;&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;input&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;type&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;submit&amp;quot;&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;value&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;上传&amp;quot;&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;div&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;form&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;body&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;html&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;说明&lt;/strong&gt;：前端如果使用表单实现文件上传，表单的method属性必须设置为post，enctype属性需要设置为multipart&amp;#x2F;form-data，表单中type属性为file的input标签，就是上传文件的文件选择器。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;实现上传功能的视图函数如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; django.views.decorators.csrf &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; csrf_exempt&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;meta&#34;&gt;@csrf_exempt&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;upload&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;request&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 如果上传的文件小于2.5M，则photo对象的类型为InMemoryUploadedFile，文件在内存中&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 如果上传的文件超过2.5M，则photo对象的类型为TemporaryUploadedFile，文件在临时路径下&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    photo = request.FILES.get(&lt;span class=&#34;string&#34;&gt;&amp;#x27;photo&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    _, ext = os.path.splitext(photo.name)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 通过UUID和原来文件的扩展名生成独一无二的新的文件名&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    filename = &lt;span class=&#34;string&#34;&gt;f&amp;#x27;&lt;span class=&#34;subst&#34;&gt;&amp;#123;uuid.uuid1().&lt;span class=&#34;built_in&#34;&gt;hex&lt;/span&gt;&amp;#125;&lt;/span&gt;&lt;span class=&#34;subst&#34;&gt;&amp;#123;ext&amp;#125;&lt;/span&gt;&amp;#x27;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 对于内存中的文件，可以使用上面封装好的函数upload_stream_to_qiniu上传文件到七牛云&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 如果文件保存在临时路径下，可以使用upload_file_to_qiniu实现文件上传&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    upload_stream_to_qiniu(filename, photo.file, photo.size)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; redirect(&lt;span class=&#34;string&#34;&gt;&amp;#x27;/static/html/upload.html&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;注意&lt;/strong&gt;：上面的视图函数使用了&lt;code&gt;csrf_exempt&lt;/code&gt;装饰器，该装饰器能够让表单免除必须提供CSRF令牌的要求。此外，代码第11行使用了&lt;code&gt;uuid&lt;/code&gt;模块的&lt;code&gt;uuid1&lt;/code&gt;函数来生成全局唯一标识符。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;运行项目尝试文件上传的功能，文件上传成功后，可以在七牛云“空间管理”中点击自己空间并进入“文件管理”界面，在这里可以看到我们刚才上传成功的文件，而且可以通过七牛云提供的域名获取该文件。&lt;/p&gt;
&lt;p&gt;&lt;img src=&#34;/res/qiniu-file-management.png&#34;&gt;&lt;/p&gt;

 &lt;h2 id=&#34;使用缓存&#34;&gt;&lt;a href=&#34;#使用缓存&#34; class=&#34;headerlink&#34; title=&#34;使用缓存&#34;&gt;&lt;/a&gt;使用缓存&lt;/h2&gt;&lt;p&gt;通常情况下，Web应用的性能瓶颈都会出现在关系型数据库上，当并发访问量较大时，如果所有的请求都需要通过关系型数据库完成数据持久化操作，那么数据库一定会不堪重负。优化Web应用性能最为重要的一点就是使用缓存，把那些数据体量不大但访问频率非常高的数据提前加载到缓存服务器中，这又是典型的空间换时间的方法。通常缓存服务器都是直接将数据置于内存中而且使用了非常高效的数据存取策略（哈希存储、键值对方式等），在读写性能上远远优于关系型数据库的，因此我们可以让Web应用接入缓存服务器来优化其性能，其中一个非常好的选择就是使用Redis。&lt;/p&gt;
&lt;p&gt;Web应用的缓存架构大致如下图所示。&lt;/p&gt;
&lt;p&gt;&lt;img src=&#34;/res/redis-cache-service.png&#34;&gt;&lt;/p&gt;
&lt;h3 id=&#34;Django项目接入Redis&#34;&gt;&lt;a href=&#34;#Django项目接入Redis&#34; class=&#34;headerlink&#34; title=&#34;Django项目接入Redis&#34;&gt;&lt;/a&gt;Django项目接入Redis&lt;/h3&gt;&lt;p&gt;在此前的课程中，我们介绍过Redis的安装和使用，此处不再进行赘述。如果需要在Django项目中接入Redis，可以使用三方库&lt;code&gt;django-redis&lt;/code&gt;，这个三方库又依赖了一个名为&lt;code&gt;redis&lt;/code&gt; 的三方库，它封装了对Redis的各种操作。&lt;/p&gt;
&lt;p&gt;安装&lt;code&gt;django-redis&lt;/code&gt;。&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;pip install django-redis&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;修改Django配置文件中关于缓存的配置。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;CACHES = &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;#x27;default&amp;#x27;&lt;/span&gt;: &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;# 指定通过django-redis接入Redis服务&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;string&#34;&gt;&amp;#x27;BACKEND&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;django_redis.cache.RedisCache&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;# Redis服务器的URL&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;string&#34;&gt;&amp;#x27;LOCATION&amp;#x27;&lt;/span&gt;: [&lt;span class=&#34;string&#34;&gt;&amp;#x27;redis://1.2.3.4:6379/0&amp;#x27;&lt;/span&gt;, ],&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;# Redis中键的前缀（解决命名冲突）&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;string&#34;&gt;&amp;#x27;KEY_PREFIX&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;vote&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;# 其他的配置选项&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;string&#34;&gt;&amp;#x27;OPTIONS&amp;#x27;&lt;/span&gt;: &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;string&#34;&gt;&amp;#x27;CLIENT_CLASS&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;django_redis.client.DefaultClient&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;comment&#34;&gt;# 连接池（预置若干备用的Redis连接）参数&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;string&#34;&gt;&amp;#x27;CONNECTION_POOL_KWARGS&amp;#x27;&lt;/span&gt;: &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                &lt;span class=&#34;comment&#34;&gt;# 最大连接数&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                &lt;span class=&#34;string&#34;&gt;&amp;#x27;max_connections&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;number&#34;&gt;512&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &amp;#125;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;comment&#34;&gt;# 连接Redis的用户口令&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;string&#34;&gt;&amp;#x27;PASSWORD&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;foobared&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &amp;#125;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;至此，我们的Django项目已经可以接入Redis，接下来我们修改项目代码，用Redis为之写的获取学科数据的接口提供缓存服务。&lt;/p&gt;
&lt;h3 id=&#34;为视图提供缓存服务&#34;&gt;&lt;a href=&#34;#为视图提供缓存服务&#34; class=&#34;headerlink&#34; title=&#34;为视图提供缓存服务&#34;&gt;&lt;/a&gt;为视图提供缓存服务&lt;/h3&gt;&lt;h4 id=&#34;声明式缓存&#34;&gt;&lt;a href=&#34;#声明式缓存&#34; class=&#34;headerlink&#34; title=&#34;声明式缓存&#34;&gt;&lt;/a&gt;声明式缓存&lt;/h4&gt;&lt;p&gt;所谓声明式缓存是指不修改原来的代码，通过Python中的装饰器（代理）为原有的代码增加缓存功能。对于FBV，代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; django.views.decorators.cache &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; cache_page&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;meta&#34;&gt;@api_view(&lt;span class=&#34;params&#34;&gt;(&lt;span class=&#34;params&#34;&gt;&lt;span class=&#34;string&#34;&gt;&amp;#x27;GET&amp;#x27;&lt;/span&gt;, &lt;/span&gt;)&lt;/span&gt;)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;meta&#34;&gt;@cache_page(&lt;span class=&#34;params&#34;&gt;timeout=&lt;span class=&#34;number&#34;&gt;86400&lt;/span&gt;, cache=&lt;span class=&#34;string&#34;&gt;&amp;#x27;default&amp;#x27;&lt;/span&gt;&lt;/span&gt;)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;show_subjects&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;request&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;&amp;quot;&amp;quot;获取学科数据&amp;quot;&amp;quot;&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    queryset = Subject.objects.&lt;span class=&#34;built_in&#34;&gt;all&lt;/span&gt;()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    data = SubjectSerializer(queryset, many=&lt;span class=&#34;literal&#34;&gt;True&lt;/span&gt;).data&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; Response(&amp;#123;&lt;span class=&#34;string&#34;&gt;&amp;#x27;code&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;number&#34;&gt;20000&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;subjects&amp;#x27;&lt;/span&gt;: data&amp;#125;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;上面的代码通过Django封装的&lt;code&gt;cache_page&lt;/code&gt;装饰器缓存了视图函数的返回值（响应对象），&lt;code&gt;cache_page&lt;/code&gt;的本意是缓存视图函数渲染的页面，对于返回JSON数据的视图函数，相当于是缓存了JSON数据。在使用&lt;code&gt;cache_page&lt;/code&gt;装饰器时，可以传入&lt;code&gt;timeout&lt;/code&gt;参数来指定缓存过期时间，还可以使用&lt;code&gt;cache&lt;/code&gt;参数来指定需要使用哪一组缓存服务来缓存数据。Django项目允许在配置文件中配置多组缓存服务，上面的&lt;code&gt;cache=&amp;#39;default&amp;#39;&lt;/code&gt;指定了使用默认的缓存服务（因为之前的配置文件中我们也只配置了名为&lt;code&gt;default&lt;/code&gt;的缓存服务）。视图函数的返回值会被序列化成字节串放到Redis中（Redis中的str类型可以接收字节串），缓存数据的序列化和反序列化也不需要我们自己处理，因为&lt;code&gt;cache_page&lt;/code&gt;装饰器会调用&lt;code&gt;django-redis&lt;/code&gt;库中的&lt;code&gt;RedisCache&lt;/code&gt;来对接Redis，该类使用了&lt;code&gt;DefaultClient&lt;/code&gt;来连接Redis并使用了&lt;a href=&#34;https://python3-cookbook.readthedocs.io/zh_CN/latest/c05/p21_serializing_python_objects.html&#34;&gt;pickle序列化&lt;/a&gt;，&lt;code&gt;django_redis.serializers.pickle.PickleSerializer&lt;/code&gt;是默认的序列化类。&lt;/p&gt;
&lt;p&gt;如果缓存中没有学科的数据，那么通过接口访问学科数据时，我们的视图函数会通过执行&lt;code&gt;Subject.objects.all()&lt;/code&gt;向数据库发出SQL语句来获得数据，视图函数的返回值会被缓存，因此下次请求该视图函数如果缓存没有过期，可以直接从缓存中获取视图函数的返回值，无需再次查询数据库。如果想了解缓存的使用情况，可以配置数据库日志或者使用Django-Debug-Toolbar来查看，第一次访问学科数据接口时会看到查询学科数据的SQL语句，再次获取学科数据时，不会再向数据库发出SQL语句，因为可以直接从缓存中获取数据。&lt;/p&gt;
&lt;p&gt;对于CBV，可以利用Django中名为&lt;code&gt;method_decorator&lt;/code&gt;的装饰器将&lt;code&gt;cache_page&lt;/code&gt;这个装饰函数的装饰器放到类中的方法上，效果跟上面的代码是一样的。需要提醒大家注意的是，&lt;code&gt;cache_page&lt;/code&gt;装饰器不能直接放在类上，因为它是装饰函数的装饰器，所以Django框架才提供了&lt;code&gt;method_decorator&lt;/code&gt;来解决这个问题，很显然，&lt;code&gt;method_decorator&lt;/code&gt;是一个装饰类的装饰器。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; django.utils.decorators &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; method_decorator&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; django.views.decorators.cache &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; cache_page&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;meta&#34;&gt;@method_decorator(&lt;span class=&#34;params&#34;&gt;decorator=cache_page(&lt;span class=&#34;params&#34;&gt;timeout=&lt;span class=&#34;number&#34;&gt;86400&lt;/span&gt;, cache=&lt;span class=&#34;string&#34;&gt;&amp;#x27;default&amp;#x27;&lt;/span&gt;&lt;/span&gt;), name=&lt;span class=&#34;string&#34;&gt;&amp;#x27;get&amp;#x27;&lt;/span&gt;&lt;/span&gt;)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;class&lt;/span&gt; &lt;span class=&#34;title class_&#34;&gt;SubjectView&lt;/span&gt;(&lt;span class=&#34;title class_ inherited__&#34;&gt;ListAPIView&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;&amp;quot;&amp;quot;获取学科数据的视图类&amp;quot;&amp;quot;&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    queryset = Subject.objects.&lt;span class=&#34;built_in&#34;&gt;all&lt;/span&gt;()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    serializer_class = SubjectSerializer&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h4 id=&#34;编程式缓存&#34;&gt;&lt;a href=&#34;#编程式缓存&#34; class=&#34;headerlink&#34; title=&#34;编程式缓存&#34;&gt;&lt;/a&gt;编程式缓存&lt;/h4&gt;&lt;p&gt;所谓编程式缓存是指通过自己编写的代码来使用缓存服务，这种方式虽然代码量会稍微大一些，但是相较于声明式缓存，它对缓存的操作和使用更加灵活，在实际开发中使用得更多。下面的代码去掉了之前使用的&lt;code&gt;cache_page&lt;/code&gt;装饰器，通过&lt;code&gt;django-redis&lt;/code&gt;提供的&lt;code&gt;get_redis_connection&lt;/code&gt;函数直接获取Redis连接来操作Redis。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;show_subjects&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;request&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;&amp;quot;&amp;quot;获取学科数据&amp;quot;&amp;quot;&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    redis_cli = get_redis_connection()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 先尝试从缓存中获取学科数据&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    data = redis_cli.get(&lt;span class=&#34;string&#34;&gt;&amp;#x27;vote:polls:subjects&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; data:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;# 如果获取到学科数据就进行反序列化操作&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        data = json.loads(data)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;else&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;# 如果缓存中没有获取到学科数据就查询数据库&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        queryset = Subject.objects.&lt;span class=&#34;built_in&#34;&gt;all&lt;/span&gt;()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        data = SubjectSerializer(queryset, many=&lt;span class=&#34;literal&#34;&gt;True&lt;/span&gt;).data&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;# 将查到的学科数据序列化后放到缓存中&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        redis_cli.&lt;span class=&#34;built_in&#34;&gt;set&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&amp;#x27;vote:polls:subjects&amp;#x27;&lt;/span&gt;, json.dumps(data), ex=&lt;span class=&#34;number&#34;&gt;86400&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; Response(&amp;#123;&lt;span class=&#34;string&#34;&gt;&amp;#x27;code&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;number&#34;&gt;20000&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;subjects&amp;#x27;&lt;/span&gt;: data&amp;#125;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;需要说明的是，Django框架提供了&lt;code&gt;cache&lt;/code&gt;和&lt;code&gt;caches&lt;/code&gt;两个现成的变量来支持缓存操作，前者访问的是默认的缓存（名为&lt;code&gt;default&lt;/code&gt;的缓存），后者可以通过索引运算获取指定的缓存服务（例如：&lt;code&gt;caches[&amp;#39;default&amp;#39;]&lt;/code&gt;）。向&lt;code&gt;cache&lt;/code&gt;对象发送&lt;code&gt;get&lt;/code&gt;和&lt;code&gt;set&lt;/code&gt;消息就可以实现对缓存的读和写操作，但是这种方式能做的操作有限，不如上面代码中使用的方式灵活。还有一个值得注意的地方，由于可以通过&lt;code&gt;get_redis_connection&lt;/code&gt;函数获得的Redis连接对象向Redis发起各种操作，包括&lt;code&gt;FLUSHDB&lt;/code&gt;、&lt;code&gt;SHUTDOWN&lt;/code&gt;等危险的操作，所以在实际商业项目开发中，一般都会对&lt;code&gt;django-redis&lt;/code&gt;再做一次封装，例如封装一个工具类，其中只提供了项目需要用到的缓存操作的方法，从而避免了直接使用&lt;code&gt;get_redis_connection&lt;/code&gt;的潜在风险。当然，自己封装对缓存的操作还可以使用“Read Through”和“Write Through”的方式实现对缓存的更新，这个在下面会介绍到。&lt;/p&gt;
&lt;h3 id=&#34;缓存相关问题&#34;&gt;&lt;a href=&#34;#缓存相关问题&#34; class=&#34;headerlink&#34; title=&#34;缓存相关问题&#34;&gt;&lt;/a&gt;缓存相关问题&lt;/h3&gt;&lt;h4 id=&#34;缓存数据的更新&#34;&gt;&lt;a href=&#34;#缓存数据的更新&#34; class=&#34;headerlink&#34; title=&#34;缓存数据的更新&#34;&gt;&lt;/a&gt;缓存数据的更新&lt;/h4&gt;&lt;p&gt;在使用缓存时，一个必须搞清楚的问题就是，当数据改变时，如何更新缓存中的数据。通常更新缓存有如下几种套路，分别是：&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;Cache Aside Pattern&lt;/li&gt;
&lt;li&gt;Read&amp;#x2F;Write Through Pattern&lt;/li&gt;
&lt;li&gt;Write Behind Caching Pattern&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;第1种方式的具体做法就是，当数据更新时，先更新数据库，再删除缓存。注意，不能够使用先更新数据库再更新缓存的方式，也不能够使用先删除缓存再更新数据库的方式，大家可以自己想一想为什么（考虑一下有并发的读操作和写操作的场景）。当然，先更新数据库再删除缓存的做法在理论上也存在风险，但是发生问题的概率是极低的，所以不少的项目都使用了这种方式。&lt;/p&gt;
&lt;p&gt;第1种方式相当于编写业务代码的开发者要自己负责对两套存储系统（缓存和关系型数据库）的操作，代码写起来非常的繁琐。第2种方式的主旨是将后端的存储系统变成一套代码，对缓存的维护封装在这套代码中。其中，Read Through指在查询操作中更新缓存，也就是说，当缓存失效的时候，由缓存服务自己负责对数据的加载，从而对应用方是透明的；而Write Through是指在更新数据时，如果没有命中缓存，直接更新数据库，然后返回。如果命中了缓存，则更新缓存，然后再由缓存服务自己更新数据库（同步更新）。刚才我们说过，如果自己对项目中的Redis操作再做一次封装，就可以实现“Read Through”和“Write Through”模式，这样做虽然会增加工作量，但无疑是一件“一劳永逸”且“功在千秋”的事情。&lt;/p&gt;
&lt;p&gt;第3种方式是在更新数据的时候，只更新缓存，不更新数据库，而缓存服务这边会&lt;strong&gt;异步的批量更新&lt;/strong&gt;数据库。这种做法会大幅度提升性能，但代价是牺牲数据的&lt;strong&gt;强一致性&lt;/strong&gt;。第3种方式的实现逻辑比较复杂，因为他需要追踪有哪数据是被更新了的，然后再批量的刷新到持久层上。&lt;/p&gt;
&lt;h4 id=&#34;缓存穿透&#34;&gt;&lt;a href=&#34;#缓存穿透&#34; class=&#34;headerlink&#34; title=&#34;缓存穿透&#34;&gt;&lt;/a&gt;缓存穿透&lt;/h4&gt;&lt;p&gt;缓存是为了缓解数据库压力而添加的一个中间层，如果恶意的访问者频繁的访问缓存中没有的数据，那么缓存就失去了存在的意义，瞬间所有请求的压力都落在了数据库上，这样会导致数据库承载着巨大的压力甚至连接异常，类似于分布式拒绝服务攻击（DDoS）的做法。解决缓存穿透的一个办法是约定如果查询返回为空值，把这个空值也缓存起来，但是需要为这个空值的缓存设置一个较短的超时时间，毕竟缓存这样的值就是对缓存空间的浪费。另一个解决缓存穿透的办法是使用布隆过滤器，具体的做法大家可以自行了解。&lt;/p&gt;
&lt;h4 id=&#34;缓存击穿&#34;&gt;&lt;a href=&#34;#缓存击穿&#34; class=&#34;headerlink&#34; title=&#34;缓存击穿&#34;&gt;&lt;/a&gt;缓存击穿&lt;/h4&gt;&lt;p&gt;在实际的项目中，可能存在某个缓存的key某个时间点过期，但恰好在这个时间点对有对该key的大量的并发请求过来，这些请求没有从缓存中找到key对应的数据，就会直接从数据库中获取数据并写回到缓存，这个时候大并发的请求可能会瞬间把数据库压垮，这种现象称为缓存击穿。比较常见的解决缓存击穿的办法是使用互斥锁，简单的说就是在缓存失效的时候，不是立即去数据库加载数据，而是先设置互斥锁（例如：Redis中的setnx），只有设置互斥锁的操作成功的请求，才能执行查询从数据库中加载数据并写入缓存，其他设置互斥锁失败的请求，可以先执行一个短暂的休眠，然后尝试重新从缓存中获取数据，如果缓存还没有数据，则重复刚才的设置互斥锁的操作，大致的参考代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;data = redis_cli.get(key)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;while&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;not&lt;/span&gt; data:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; redis_cli.setnx(&lt;span class=&#34;string&#34;&gt;&amp;#x27;mutex&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;x&amp;#x27;&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        redis.expire(&lt;span class=&#34;string&#34;&gt;&amp;#x27;mutex&amp;#x27;&lt;/span&gt;, timeout)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        data = db.query(...)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        redis.&lt;span class=&#34;built_in&#34;&gt;set&lt;/span&gt;(key, data)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        redis.delete(&lt;span class=&#34;string&#34;&gt;&amp;#x27;mutex&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;else&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        time.sleep(&lt;span class=&#34;number&#34;&gt;0.1&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        data = redis_cli.get(key)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h4 id=&#34;缓存雪崩&#34;&gt;&lt;a href=&#34;#缓存雪崩&#34; class=&#34;headerlink&#34; title=&#34;缓存雪崩&#34;&gt;&lt;/a&gt;缓存雪崩&lt;/h4&gt;&lt;p&gt;缓存雪崩是指在将数据放入缓存时采用了相同的过期时间，这样就导致缓存在某一时刻同时失效，请求全部转发到数据库，导致数据库瞬时压力过大而崩溃。解决缓存雪崩问题的方法也比较简单，可以在既定的缓存过期时间上加一个随机时间，这样可以从一定程度上避免不同的key在同一时间集体失效。还有一种办法就是使用多级缓存，每一级缓存的过期时间都不一样，这样的话即便某个级别的缓存集体失效，但是其他级别的缓存还能够提供数据，避免所有的请求都落到数据库上。&lt;/p&gt;

 &lt;h2 id=&#34;RESTful架构和DRF进阶&#34;&gt;&lt;a href=&#34;#RESTful架构和DRF进阶&#34; class=&#34;headerlink&#34; title=&#34;RESTful架构和DRF进阶&#34;&gt;&lt;/a&gt;RESTful架构和DRF进阶&lt;/h2&gt;&lt;p&gt;除了上一节讲到的方法，使用DRF创建REST风格的数据接口也可以通过CBV（基于类的视图）的方式。使用CBV创建数据接口的特点是代码简单，开发效率高，但是没有FBV（基于函数的视图）灵活，因为使用FBV的方式，数据接口对应的视图函数执行什么样的代码以及返回什么的数据是高度可定制的。下面我们以定制学科的数据接口为例，讲解通过CBV方式定制数据接口的具体做法。&lt;/p&gt;
&lt;h3 id=&#34;使用CBV&#34;&gt;&lt;a href=&#34;#使用CBV&#34; class=&#34;headerlink&#34; title=&#34;使用CBV&#34;&gt;&lt;/a&gt;使用CBV&lt;/h3&gt;&lt;h4 id=&#34;继承APIView的子类&#34;&gt;&lt;a href=&#34;#继承APIView的子类&#34; class=&#34;headerlink&#34; title=&#34;继承APIView的子类&#34;&gt;&lt;/a&gt;继承APIView的子类&lt;/h4&gt;&lt;p&gt;修改之前项目中的&lt;code&gt;polls/views.py&lt;/code&gt;，去掉&lt;code&gt;show_subjects&lt;/code&gt;视图函数，添加一个名为&lt;code&gt;SubjectView&lt;/code&gt;的类，该类继承自&lt;code&gt;ListAPIView&lt;/code&gt;，&lt;code&gt;ListAPIView&lt;/code&gt;能接收GET请求，它封装了获取数据列表并返回JSON数据的&lt;code&gt;get&lt;/code&gt;方法。&lt;code&gt;ListAPIView&lt;/code&gt;是&lt;code&gt;APIView&lt;/code&gt; 的子类，&lt;code&gt;APIView&lt;/code&gt;还有很多的子类，例如&lt;code&gt;CreateAPIView&lt;/code&gt;可以支持POST请求，&lt;code&gt;UpdateAPIView&lt;/code&gt;可以支持PUT和PATCH请求，&lt;code&gt;DestoryAPIView&lt;/code&gt;可以支持DELETE请求。&lt;code&gt;SubjectView&lt;/code&gt; 的代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; rest_framework.generics &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; ListAPIView&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;class&lt;/span&gt; &lt;span class=&#34;title class_&#34;&gt;SubjectView&lt;/span&gt;(&lt;span class=&#34;title class_ inherited__&#34;&gt;ListAPIView&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 通过queryset指定如何获取学科数据&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    queryset = Subject.objects.&lt;span class=&#34;built_in&#34;&gt;all&lt;/span&gt;()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 通过serializer_class指定如何序列化学科数据&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    serializer_class = SubjectSerializer&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;刚才说过，由于&lt;code&gt;SubjectView&lt;/code&gt;的父类&lt;code&gt;ListAPIView&lt;/code&gt;已经实现了&lt;code&gt;get&lt;/code&gt;方法来处理获取学科列表的GET请求，所以我们只需要声明如何获取学科数据以及如何序列化学科数据，前者用&lt;code&gt;queryset&lt;/code&gt;属性指定，后者用&lt;code&gt;serializer_class&lt;/code&gt;属性指定。要使用上面的&lt;code&gt;SubjectView&lt;/code&gt;，需要修改&lt;code&gt;urls.py&lt;/code&gt;文件，如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;urlpatterns = [&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    path(&lt;span class=&#34;string&#34;&gt;&amp;#x27;api/subjects/&amp;#x27;&lt;/span&gt;, SubjectView.as_view()),   &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;]&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;很显然，上面的做法较之之前讲到的FBV要简单很多。&lt;/p&gt;
&lt;h4 id=&#34;继承ModelViewSet&#34;&gt;&lt;a href=&#34;#继承ModelViewSet&#34; class=&#34;headerlink&#34; title=&#34;继承ModelViewSet&#34;&gt;&lt;/a&gt;继承ModelViewSet&lt;/h4&gt;&lt;p&gt;如果学科对应的数据接口需要支持GET、POST、PUT、PATCH、DELETE请求来支持对学科资源的获取、新增、更新、删除操作，更为简单的做法是继承&lt;code&gt;ModelViewSet&lt;/code&gt;来编写学科视图类。再次修改&lt;code&gt;polls/views.py&lt;/code&gt;文件，去掉&lt;code&gt;SubjectView&lt;/code&gt;类，添加一个名为&lt;code&gt;SubjectViewSet&lt;/code&gt;的类，代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; rest_framework.viewsets &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; ModelViewSet&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;class&lt;/span&gt; &lt;span class=&#34;title class_&#34;&gt;SubjectViewSet&lt;/span&gt;(&lt;span class=&#34;title class_ inherited__&#34;&gt;ModelViewSet&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    queryset = Subject.objects.&lt;span class=&#34;built_in&#34;&gt;all&lt;/span&gt;()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    serializer_class = SubjectSerializer&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;通过查看&lt;code&gt;ModelViewSet&lt;/code&gt;类的源代码可以发现，该类共有6个父类，其中前5个父类分别实现对POST（新增学科）、GET（获取指定学科）、PUT&amp;#x2F;PATCH（更新学科）、DELETE（删除学科）和GET（获取学科列表）操作的支持，对应的方法分别是&lt;code&gt;create&lt;/code&gt;、&lt;code&gt;retrieve&lt;/code&gt;、&lt;code&gt;update&lt;/code&gt;、&lt;code&gt;destroy&lt;/code&gt;和&lt;code&gt;list&lt;/code&gt;。由于&lt;code&gt;ModelViewSet&lt;/code&gt;的父类中已经实现了这些方法，所以我们几乎没有编写任何代码就完成了学科数据全套接口的开发，我们要做的仅仅是指出如何获取到数据（通过&lt;code&gt;queryset&lt;/code&gt;属性指定）以及如何序列化数据（通过&lt;code&gt;serializer_class&lt;/code&gt;属性指定），这一点跟上面继承&lt;code&gt;APIView&lt;/code&gt;的子类做法是一致的。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;class&lt;/span&gt; &lt;span class=&#34;title class_&#34;&gt;ModelViewSet&lt;/span&gt;(mixins.CreateModelMixin,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                   mixins.RetrieveModelMixin,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                   mixins.UpdateModelMixin,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                   mixins.DestroyModelMixin,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                   mixins.ListModelMixin,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                   GenericViewSet):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;&amp;quot;&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;    A viewset that provides default `create()`, `retrieve()`, `update()`,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;    `partial_update()`, `destroy()` and `list()` actions.&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;    &amp;quot;&amp;quot;&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;pass&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;要使用上面的&lt;code&gt;SubjectViewSet&lt;/code&gt;，需要在&lt;code&gt;urls.py&lt;/code&gt;文件中进行URL映射。由于&lt;code&gt;ModelViewSet&lt;/code&gt;相当于是多个视图函数的汇总，所以不同于之前映射URL的方式，我们需要先创建一个路由器并通过它注册&lt;code&gt;SubjectViewSet&lt;/code&gt;，然后将注册成功后生成的URL一并添加到&lt;code&gt;urlspattern&lt;/code&gt;列表中，代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; rest_framework.routers &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; DefaultRouter&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;router = DefaultRouter()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;router.register(&lt;span class=&#34;string&#34;&gt;&amp;#x27;api/subjects&amp;#x27;&lt;/span&gt;, SubjectViewSet)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;urlpatterns += router.urls&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;除了&lt;code&gt;ModelViewSet&lt;/code&gt;类外，DRF还提供了一个名为&lt;code&gt;ReadOnlyModelViewSet&lt;/code&gt; 的类，从名字上就可以看出，该类是只读视图的集合，也就意味着，继承该类定制的数据接口只能支持GET请求，也就是获取单个资源和资源列表的请求。&lt;/p&gt;
&lt;h3 id=&#34;数据分页&#34;&gt;&lt;a href=&#34;#数据分页&#34; class=&#34;headerlink&#34; title=&#34;数据分页&#34;&gt;&lt;/a&gt;数据分页&lt;/h3&gt;&lt;p&gt;在使用GET请求获取资源列表时，我们通常不会一次性的加载所有的数据，除非数据量真的很小。大多数获取资源列表的操作都支持数据分页展示，也就说我们可以通过指定页码（或类似于页码的标识）和页面大小（一次加载多少条数据）来获取不同的数据。我们可以通过对&lt;code&gt;QuerySet&lt;/code&gt;对象的切片操作来实现分页，也可以利用Django框架封装的&lt;code&gt;Paginator&lt;/code&gt;和&lt;code&gt;Page&lt;/code&gt;对象来实现分页。使用DRF时，可以在Django配置文件中修改&lt;code&gt;REST_FRAMEWORK&lt;/code&gt;并配置默认的分页类和页面大小来实现分页，如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;REST_FRAMEWORK = &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;#x27;PAGE_SIZE&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;#x27;DEFAULT_PAGINATION_CLASS&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;rest_framework.pagination.PageNumberPagination&amp;#x27;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;除了上面配置的&lt;code&gt;PageNumberPagination&lt;/code&gt;分页器之外，DRF还提供了&lt;code&gt;LimitOffsetPagination&lt;/code&gt;和&lt;code&gt;CursorPagination&lt;/code&gt;分页器，值得一提的是&lt;code&gt;CursorPagination&lt;/code&gt;，它可以避免使用页码分页时暴露网站的数据体量，有兴趣的读者可以自行了解。如果不希望使用配置文件中默认的分页设定，可以在视图类中添加一个&lt;code&gt;pagination_class&lt;/code&gt;属性来重新指定分页器，通常可以将该属性指定为自定义的分页器，如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; rest_framework.pagination &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; PageNumberPagination&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;class&lt;/span&gt; &lt;span class=&#34;title class_&#34;&gt;CustomizedPagination&lt;/span&gt;(&lt;span class=&#34;title class_ inherited__&#34;&gt;PageNumberPagination&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 默认页面大小&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    page_size = &lt;span class=&#34;number&#34;&gt;5&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 页面大小对应的查询参数&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    page_size_query_param = &lt;span class=&#34;string&#34;&gt;&amp;#x27;size&amp;#x27;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 页面大小的最大值&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    max_page_size = &lt;span class=&#34;number&#34;&gt;50&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;class&lt;/span&gt; &lt;span class=&#34;title class_&#34;&gt;SubjectView&lt;/span&gt;(&lt;span class=&#34;title class_ inherited__&#34;&gt;ListAPIView&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 指定如何获取数据&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    queryset = Subject.objects.&lt;span class=&#34;built_in&#34;&gt;all&lt;/span&gt;()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 指定如何序列化数据&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    serializer_class = SubjectSerializer&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 指定如何分页&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    pagination_class = CustomizedPagination&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;如果不希望数据分页，可以将&lt;code&gt;pagination_class&lt;/code&gt;属性设置为&lt;code&gt;None&lt;/code&gt;来取消默认的分页器。&lt;/p&gt;
&lt;h3 id=&#34;数据筛选&#34;&gt;&lt;a href=&#34;#数据筛选&#34; class=&#34;headerlink&#34; title=&#34;数据筛选&#34;&gt;&lt;/a&gt;数据筛选&lt;/h3&gt;&lt;p&gt;如果希望使用CBV定制获取老师信息的数据接口，也可以通过继承&lt;code&gt;ListAPIView&lt;/code&gt;来实现。但是因为要通过指定的学科来获取对应的老师信息，因此需要对老师数据进行筛选而不是直接获取所有老师的数据。如果想从请求中获取学科编号并通过学科编号对老师进行筛选，可以通过重写&lt;code&gt;get_queryset&lt;/code&gt;方法来做到，代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;class&lt;/span&gt; &lt;span class=&#34;title class_&#34;&gt;TeacherView&lt;/span&gt;(&lt;span class=&#34;title class_ inherited__&#34;&gt;ListAPIView&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    serializer_class = TeacherSerializer&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;get_queryset&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;self&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        queryset = Teacher.objects.defer(&lt;span class=&#34;string&#34;&gt;&amp;#x27;subject&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;try&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            sno = self.request.GET.get(&lt;span class=&#34;string&#34;&gt;&amp;#x27;sno&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            queryset = queryset.&lt;span class=&#34;built_in&#34;&gt;filter&lt;/span&gt;(subject__no=sno)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; queryset&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;except&lt;/span&gt; ValueError:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;keyword&#34;&gt;raise&lt;/span&gt; Http404(&lt;span class=&#34;string&#34;&gt;&amp;#x27;No teachers found.&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;除了上述方式之外，还可以使用三方库&lt;code&gt;django-filter&lt;/code&gt;来配合DRF实现对数据的筛选，使用&lt;code&gt;django-filter&lt;/code&gt;后，可以通过为视图类配置&lt;code&gt;filter-backends&lt;/code&gt;属性并指定使用&lt;code&gt;DjangoFilterBackend&lt;/code&gt;来支持数据筛选。在完成上述配置后，可以使用&lt;code&gt;filter_fields&lt;/code&gt; 属性或&lt;code&gt;filterset_class&lt;/code&gt;属性来指定如何筛选数据，有兴趣的读者可以自行研究。&lt;/p&gt;

 &lt;h2 id=&#34;RESTful架构和DRF入门&#34;&gt;&lt;a href=&#34;#RESTful架构和DRF入门&#34; class=&#34;headerlink&#34; title=&#34;RESTful架构和DRF入门&#34;&gt;&lt;/a&gt;RESTful架构和DRF入门&lt;/h2&gt;&lt;p&gt;把软件（Software）、平台（Platform）、基础设施（Infrastructure）做成服务（Service）是很多IT企业都一直在做的事情，这就是大家经常听到的SasS（软件即服务）、PasS（平台即服务）和IasS（基础设置即服务）。实现面向服务的架构（SOA）有诸多的方式，包括RPC（远程过程调用）、Web Service、REST等，在技术层面上，SOA是一种&lt;strong&gt;抽象的、松散耦合的粗粒度软件架构&lt;/strong&gt;；在业务层面上，SOA的核心概念是“&lt;strong&gt;重用&lt;/strong&gt;”和“&lt;strong&gt;互操作&lt;/strong&gt;”，它将系统资源整合成可操作的、标准的服务，使得这些资源能够被重新组合和应用。在实现SOA的诸多方案中，REST被认为是最适合互联网应用的架构，符合REST规范的架构也经常被称作RESTful架构。&lt;/p&gt;
&lt;h3 id=&#34;REST概述&#34;&gt;&lt;a href=&#34;#REST概述&#34; class=&#34;headerlink&#34; title=&#34;REST概述&#34;&gt;&lt;/a&gt;REST概述&lt;/h3&gt;&lt;p&gt;REST这个词，是&lt;strong&gt;Roy Thomas Fielding&lt;/strong&gt;在他2000年的博士论文中提出的，Roy是HTTP协议（1.0和1.1版）的主要设计者、Apache服务器软件主要作者、Apache基金会第一任主席。在他的博士论文中，Roy把他对互联网软件的架构原则定名为REST，即&lt;strong&gt;RE&lt;/strong&gt;presentational &lt;strong&gt;S&lt;/strong&gt;tate &lt;strong&gt;T&lt;/strong&gt;ransfer的缩写，中文通常翻译为“&lt;strong&gt;表现层状态转移&lt;/strong&gt;”或“&lt;strong&gt;表述状态转移&lt;/strong&gt;”。&lt;/p&gt;
&lt;p&gt;这里的“表现层”其实指的是“资源”的“表现层”。所谓资源，就是网络上的一个实体，或者说是网络上的一个具体信息。它可以是一段文本、一张图片、一首歌曲或一种服务。我们可以用一个URI（统一资源定位符）指向资源，要获取到这个资源，访问它的URI即可，URI就是资源在互联网上的唯一标识。资源可以有多种外在表现形式。我们把资源具体呈现出来的形式，叫做它的“表现层”。比如，文本可以用&lt;code&gt;text/plain&lt;/code&gt;格式表现，也可以用&lt;code&gt;text/html&lt;/code&gt;格式、&lt;code&gt;text/xml&lt;/code&gt;格式、&lt;code&gt;application/json&lt;/code&gt;格式表现，甚至可以采用二进制格式；图片可以用&lt;code&gt;image/jpeg&lt;/code&gt;格式表现，也可以用&lt;code&gt;image/png&lt;/code&gt;格式表现。URI只代表资源的实体，不代表它的表现形式。严格地说，有些网址最后的&lt;code&gt;.html&lt;/code&gt;后缀名是不必要的，因为这个后缀名表示格式，属于“表现层”范畴，而URI应该只代表“资源”的位置，它的具体表现形式，应该在HTTP请求的头信息中用&lt;code&gt;Accept&lt;/code&gt;和&lt;code&gt;Content-Type&lt;/code&gt;字段指定，这两个字段才是对“表现层”的描述。&lt;/p&gt;
&lt;p&gt;访问一个网站，就代表了客户端和服务器的一个互动过程。在这个过程中，势必涉及到数据和状态的变化。Web应用通常使用HTTP作为其通信协议，客户端想要操作服务器，必须通过HTTP请求，让服务器端发生“状态转移”，而这种转移是建立在表现层之上的，所以就是“表现层状态转移”。客户端通过HTTP的动词GET、POST、PUT（或PATCH）、DELETE，分别对应对资源的四种基本操作，其中GET用来获取资源，POST用来新建资源（也可以用于更新资源），PUT（或PATCH）用来更新资源，DELETE用来删除资源。&lt;/p&gt;
&lt;p&gt;简单的说RESTful架构就是：“每一个URI代表一种资源，客户端通过四个HTTP动词，对服务器端资源进行操作，实现资源的表现层状态转移”。&lt;/p&gt;
&lt;p&gt;我们在设计Web应用时，如果需要向客户端提供资源，就可以使用REST风格的URI，这是实现RESTful架构的第一步。当然，真正的RESTful架构并不只是URI符合REST风格，更为重要的是“无状态”和“幂等性”两个词，我们在后面的课程中会为大家阐述这两点。下面的例子给出了一些符合REST风格的URI，供大家在设计URI时参考。&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;请求方法（HTTP动词）&lt;/th&gt;
&lt;th&gt;URI&lt;/th&gt;
&lt;th&gt;解释&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;GET&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;/students/&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;获取所有学生&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;POST&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;/students/&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;新建一个学生&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;GET&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;/students/ID/&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;获取指定ID的学生信息&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;PUT&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;/students/ID/&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;更新指定ID的学生信息（提供该学生的全部信息）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;PATCH&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;/students/ID/&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;更新指定ID的学生信息（提供该学生的部分信息）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;DELETE&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;/students/ID/&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;删除指定ID的学生信息&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;GET&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;/students/ID/friends/&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;列出指定ID的学生的所有朋友&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;DELETE&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;/students/ID/friends/ID/&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;删除指定ID的学生的指定ID的朋友&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;h3 id=&#34;DRF使用入门&#34;&gt;&lt;a href=&#34;#DRF使用入门&#34; class=&#34;headerlink&#34; title=&#34;DRF使用入门&#34;&gt;&lt;/a&gt;DRF使用入门&lt;/h3&gt;&lt;p&gt;在Django项目中，如果要实现REST架构，即将网站的资源发布成REST风格的API接口，可以使用著名的三方库&lt;code&gt;djangorestframework&lt;/code&gt; ，我们通常将其简称为DRF。&lt;/p&gt;
&lt;h4 id=&#34;安装和配置DRF&#34;&gt;&lt;a href=&#34;#安装和配置DRF&#34; class=&#34;headerlink&#34; title=&#34;安装和配置DRF&#34;&gt;&lt;/a&gt;安装和配置DRF&lt;/h4&gt;&lt;p&gt;安装DRF。&lt;/p&gt;
&lt;figure class=&#34;highlight shell&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;pip install djangorestframework&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;配置DRF。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;INSTALLED_APPS = [&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;#x27;rest_framework&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 下面的配置根据项目需要进行设置&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;REST_FRAMEWORK = &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 配置默认页面大小&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# &amp;#x27;PAGE_SIZE&amp;#x27;: 10,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 配置默认的分页类&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# &amp;#x27;DEFAULT_PAGINATION_CLASS&amp;#x27;: &amp;#x27;...&amp;#x27;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 配置异常处理器&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# &amp;#x27;EXCEPTION_HANDLER&amp;#x27;: &amp;#x27;...&amp;#x27;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 配置默认解析器&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# &amp;#x27;DEFAULT_PARSER_CLASSES&amp;#x27;: (&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;#     &amp;#x27;rest_framework.parsers.JSONParser&amp;#x27;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;#     &amp;#x27;rest_framework.parsers.FormParser&amp;#x27;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;#     &amp;#x27;rest_framework.parsers.MultiPartParser&amp;#x27;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# ),&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 配置默认限流类&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# &amp;#x27;DEFAULT_THROTTLE_CLASSES&amp;#x27;: (&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;#     &amp;#x27;...&amp;#x27;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# ),&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 配置默认授权类&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# &amp;#x27;DEFAULT_PERMISSION_CLASSES&amp;#x27;: (&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;#     &amp;#x27;...&amp;#x27;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# ),&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 配置默认认证类&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# &amp;#x27;DEFAULT_AUTHENTICATION_CLASSES&amp;#x27;: (&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;#     &amp;#x27;...&amp;#x27;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# ),&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h4 id=&#34;编写序列化器&#34;&gt;&lt;a href=&#34;#编写序列化器&#34; class=&#34;headerlink&#34; title=&#34;编写序列化器&#34;&gt;&lt;/a&gt;编写序列化器&lt;/h4&gt;&lt;p&gt;前后端分离的开发需要后端为前端、移动端提供API数据接口，而API接口通常情况下都是返回JSON格式的数据，这就需要对模型对象进行序列化处理。DRF中封装了&lt;code&gt;Serializer&lt;/code&gt;类和&lt;code&gt;ModelSerializer&lt;/code&gt;类用于实现序列化操作，通过继承&lt;code&gt;Serializer&lt;/code&gt;类或&lt;code&gt;ModelSerializer&lt;/code&gt;类，我们可以自定义序列化器，用于将对象处理成字典，代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; rest_framework &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; serializers &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;class&lt;/span&gt; &lt;span class=&#34;title class_&#34;&gt;SubjectSerializer&lt;/span&gt;(serializers.ModelSerializer):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;class&lt;/span&gt; &lt;span class=&#34;title class_&#34;&gt;Meta&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        model = Subject&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        fields = &lt;span class=&#34;string&#34;&gt;&amp;#x27;__all__&amp;#x27;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;上面的代码直接继承了&lt;code&gt;ModelSerializer&lt;/code&gt;，通过&lt;code&gt;Meta&lt;/code&gt;类的&lt;code&gt;model&lt;/code&gt;属性指定要序列化的模型以及&lt;code&gt;fields&lt;/code&gt;属性指定需要序列化的模型字段，稍后我们就可以在视图函数中使用该类来实现对&lt;code&gt;Subject&lt;/code&gt;模型的序列化。&lt;/p&gt;
&lt;h4 id=&#34;编写视图函数&#34;&gt;&lt;a href=&#34;#编写视图函数&#34; class=&#34;headerlink&#34; title=&#34;编写视图函数&#34;&gt;&lt;/a&gt;编写视图函数&lt;/h4&gt;&lt;p&gt;DRF框架支持两种实现数据接口的方式，一种是FBV（基于函数的视图），另一种是CBV（基于类的视图）。我们先看看FBV的方式如何实现数据接口，代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; rest_framework.decorators &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; api_view&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; rest_framework.response &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; Response&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;meta&#34;&gt;@api_view(&lt;span class=&#34;params&#34;&gt;(&lt;span class=&#34;params&#34;&gt;&lt;span class=&#34;string&#34;&gt;&amp;#x27;GET&amp;#x27;&lt;/span&gt;, &lt;/span&gt;)&lt;/span&gt;)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;show_subjects&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;request: HttpRequest&lt;/span&gt;) -&amp;gt; HttpResponse:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    subjects = Subject.objects.&lt;span class=&#34;built_in&#34;&gt;all&lt;/span&gt;().order_by(&lt;span class=&#34;string&#34;&gt;&amp;#x27;no&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 创建序列化器对象并指定要序列化的模型&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    serializer = SubjectSerializer(subjects, many=&lt;span class=&#34;literal&#34;&gt;True&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 通过序列化器的data属性获得模型对应的字典并通过创建Response对象返回JSON格式的数据&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; Response(serializer.data)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;对比上一个章节的使用&lt;code&gt;bpmapper&lt;/code&gt;实现模型序列化的代码，使用DRF的代码更加简单明了，而且DRF本身自带了一套页面，可以方便我们查看我们使用DRF定制的数据接口，如下图所示。&lt;/p&gt;
&lt;p&gt;&lt;img src=&#34;/res/drf-app.png&#34;&gt;&lt;/p&gt;
&lt;p&gt;直接使用上一节写好的页面，就可以通过Vue.js把上面接口提供的学科数据渲染并展示出来，此处不再进行赘述。&lt;/p&gt;
&lt;h4 id=&#34;实现老师信息数据接口&#34;&gt;&lt;a href=&#34;#实现老师信息数据接口&#34; class=&#34;headerlink&#34; title=&#34;实现老师信息数据接口&#34;&gt;&lt;/a&gt;实现老师信息数据接口&lt;/h4&gt;&lt;p&gt;编写序列化器。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;class&lt;/span&gt; &lt;span class=&#34;title class_&#34;&gt;SubjectSimpleSerializer&lt;/span&gt;(serializers.ModelSerializer):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;class&lt;/span&gt; &lt;span class=&#34;title class_&#34;&gt;Meta&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        model = Subject&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        fields = (&lt;span class=&#34;string&#34;&gt;&amp;#x27;no&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;name&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;class&lt;/span&gt; &lt;span class=&#34;title class_&#34;&gt;TeacherSerializer&lt;/span&gt;(serializers.ModelSerializer):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;class&lt;/span&gt; &lt;span class=&#34;title class_&#34;&gt;Meta&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        model = Teacher&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        exclude = (&lt;span class=&#34;string&#34;&gt;&amp;#x27;subject&amp;#x27;&lt;/span&gt;, )&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;编写视图函数。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;meta&#34;&gt;@api_view(&lt;span class=&#34;params&#34;&gt;(&lt;span class=&#34;params&#34;&gt;&lt;span class=&#34;string&#34;&gt;&amp;#x27;GET&amp;#x27;&lt;/span&gt;, &lt;/span&gt;)&lt;/span&gt;)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;show_teachers&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;request: HttpRequest&lt;/span&gt;) -&amp;gt; HttpResponse:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;try&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        sno = &lt;span class=&#34;built_in&#34;&gt;int&lt;/span&gt;(request.GET.get(&lt;span class=&#34;string&#34;&gt;&amp;#x27;sno&amp;#x27;&lt;/span&gt;))&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        subject = Subject.objects.only(&lt;span class=&#34;string&#34;&gt;&amp;#x27;name&amp;#x27;&lt;/span&gt;).get(no=sno)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        teachers = Teacher.objects.&lt;span class=&#34;built_in&#34;&gt;filter&lt;/span&gt;(subject=subject).defer(&lt;span class=&#34;string&#34;&gt;&amp;#x27;subject&amp;#x27;&lt;/span&gt;).order_by(&lt;span class=&#34;string&#34;&gt;&amp;#x27;no&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        subject_seri = SubjectSimpleSerializer(subject)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        teacher_seri = TeacherSerializer(teachers, many=&lt;span class=&#34;literal&#34;&gt;True&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; Response(&amp;#123;&lt;span class=&#34;string&#34;&gt;&amp;#x27;subject&amp;#x27;&lt;/span&gt;: subject_seri.data, &lt;span class=&#34;string&#34;&gt;&amp;#x27;teachers&amp;#x27;&lt;/span&gt;: teacher_seri.data&amp;#125;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;except&lt;/span&gt; (TypeError, ValueError, Subject.DoesNotExist):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; Response(status=&lt;span class=&#34;number&#34;&gt;404&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;配置URL映射。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;urlpatterns = [&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    path(&lt;span class=&#34;string&#34;&gt;&amp;#x27;api/teachers/&amp;#x27;&lt;/span&gt;, show_teachers),&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;]&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;通过Vue.js渲染页面。&lt;/p&gt;
&lt;figure class=&#34;highlight html&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;meta&#34;&gt;&amp;lt;!DOCTYPE &lt;span class=&#34;keyword&#34;&gt;html&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;html&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;lang&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;en&amp;quot;&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;head&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;meta&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;charset&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;UTF-8&amp;quot;&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;title&lt;/span&gt;&amp;gt;&lt;/span&gt;老师信息&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;title&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;style&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;span class=&#34;language-css&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-css&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;/* 此处省略掉层叠样式表 */&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-css&#34;&gt;    &lt;/span&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;style&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;head&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;body&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;div&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;id&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;container&amp;quot;&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;h1&lt;/span&gt;&amp;gt;&lt;/span&gt;&amp;#123;&amp;#123; subject.name &amp;#125;&amp;#125;学科的老师信息&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;h1&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;hr&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;h2&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;v-if&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;loaded &amp;amp;&amp;amp; teachers.length == 0&amp;quot;&lt;/span&gt;&amp;gt;&lt;/span&gt;暂无该学科老师信息&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;h2&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;div&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;class&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;teacher&amp;quot;&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;v-for&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;teacher in teachers&amp;quot;&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;div&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;class&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;photo&amp;quot;&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;img&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;:src&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;&amp;#x27;/static/images/&amp;#x27; + teacher.photo&amp;quot;&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;height&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;140&amp;quot;&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;alt&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;&amp;quot;&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;div&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;div&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;class&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;info&amp;quot;&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;div&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                    &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;span&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;strong&lt;/span&gt;&amp;gt;&lt;/span&gt;姓名：&amp;#123;&amp;#123; teacher.name &amp;#125;&amp;#125;&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;strong&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;span&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                    &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;span&lt;/span&gt;&amp;gt;&lt;/span&gt;性别：&amp;#123;&amp;#123; teacher.sex | maleOrFemale &amp;#125;&amp;#125;&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;span&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                    &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;span&lt;/span&gt;&amp;gt;&lt;/span&gt;出生日期：&amp;#123;&amp;#123; teacher.birth &amp;#125;&amp;#125;&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;span&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                &lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;div&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;div&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;class&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;intro&amp;quot;&lt;/span&gt;&amp;gt;&lt;/span&gt;&amp;#123;&amp;#123; teacher.intro &amp;#125;&amp;#125;&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;div&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;div&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;class&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;comment&amp;quot;&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                    &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;a&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;href&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;&amp;quot;&lt;/span&gt; @&lt;span class=&#34;attr&#34;&gt;click.prevent&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;vote(teacher, true)&amp;quot;&lt;/span&gt;&amp;gt;&lt;/span&gt;好评&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;a&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;span class=&#34;symbol&#34;&gt;&amp;amp;nbsp;&lt;/span&gt;&lt;span class=&#34;symbol&#34;&gt;&amp;amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                    (&lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;strong&lt;/span&gt;&amp;gt;&lt;/span&gt;&amp;#123;&amp;#123; teacher.good_count &amp;#125;&amp;#125;&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;strong&lt;/span&gt;&amp;gt;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                    &lt;span class=&#34;symbol&#34;&gt;&amp;amp;nbsp;&lt;/span&gt;&lt;span class=&#34;symbol&#34;&gt;&amp;amp;nbsp;&lt;/span&gt;&lt;span class=&#34;symbol&#34;&gt;&amp;amp;nbsp;&lt;/span&gt;&lt;span class=&#34;symbol&#34;&gt;&amp;amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                    &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;a&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;href&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;&amp;quot;&lt;/span&gt; @&lt;span class=&#34;attr&#34;&gt;click.prevent&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;vote(teacher, false)&amp;quot;&lt;/span&gt;&amp;gt;&lt;/span&gt;差评&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;a&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;span class=&#34;symbol&#34;&gt;&amp;amp;nbsp;&lt;/span&gt;&lt;span class=&#34;symbol&#34;&gt;&amp;amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                    (&lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;strong&lt;/span&gt;&amp;gt;&lt;/span&gt;&amp;#123;&amp;#123; teacher.bad_count &amp;#125;&amp;#125;&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;strong&lt;/span&gt;&amp;gt;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                &lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;div&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;div&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;div&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;a&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;href&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;/static/html/subjects.html&amp;quot;&lt;/span&gt;&amp;gt;&lt;/span&gt;返回首页&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;a&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;div&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;script&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;src&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;https://cdn.bootcdn.net/ajax/libs/vue/2.6.11/vue.min.js&amp;quot;&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;script&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;script&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;span class=&#34;language-javascript&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;let&lt;/span&gt; app = &lt;span class=&#34;keyword&#34;&gt;new&lt;/span&gt; &lt;span class=&#34;title class_&#34;&gt;Vue&lt;/span&gt;(&amp;#123;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;            &lt;span class=&#34;attr&#34;&gt;el&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;#container&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;            &lt;span class=&#34;attr&#34;&gt;data&lt;/span&gt;: &amp;#123;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;                &lt;span class=&#34;attr&#34;&gt;subject&lt;/span&gt;: &amp;#123;&amp;#125;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;                &lt;span class=&#34;attr&#34;&gt;teachers&lt;/span&gt;: [],&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;                &lt;span class=&#34;attr&#34;&gt;loaded&lt;/span&gt;: &lt;span class=&#34;literal&#34;&gt;false&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;            &amp;#125;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;            &lt;span class=&#34;title function_&#34;&gt;created&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;&lt;/span&gt;) &amp;#123;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;                &lt;span class=&#34;title function_&#34;&gt;fetch&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&amp;#x27;/api/teachers/&amp;#x27;&lt;/span&gt; + location.&lt;span class=&#34;property&#34;&gt;search&lt;/span&gt;)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;                    .&lt;span class=&#34;title function_&#34;&gt;then&lt;/span&gt;(&lt;span class=&#34;function&#34;&gt;&lt;span class=&#34;params&#34;&gt;resp&lt;/span&gt; =&amp;gt;&lt;/span&gt; resp.&lt;span class=&#34;title function_&#34;&gt;json&lt;/span&gt;())&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;                    .&lt;span class=&#34;title function_&#34;&gt;then&lt;/span&gt;(&lt;span class=&#34;function&#34;&gt;&lt;span class=&#34;params&#34;&gt;json&lt;/span&gt; =&amp;gt;&lt;/span&gt; &amp;#123;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;                        &lt;span class=&#34;variable language_&#34;&gt;this&lt;/span&gt;.&lt;span class=&#34;property&#34;&gt;subject&lt;/span&gt; = json.&lt;span class=&#34;property&#34;&gt;subject&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;                        &lt;span class=&#34;variable language_&#34;&gt;this&lt;/span&gt;.&lt;span class=&#34;property&#34;&gt;teachers&lt;/span&gt; = json.&lt;span class=&#34;property&#34;&gt;teachers&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;                    &amp;#125;)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;            &amp;#125;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;            &lt;span class=&#34;attr&#34;&gt;filters&lt;/span&gt;: &amp;#123;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;                &lt;span class=&#34;title function_&#34;&gt;maleOrFemale&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;sex&lt;/span&gt;) &amp;#123;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;                    &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; sex? &lt;span class=&#34;string&#34;&gt;&amp;#x27;男&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;女&amp;#x27;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;                &amp;#125;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;            &amp;#125;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;            &lt;span class=&#34;attr&#34;&gt;methods&lt;/span&gt;: &amp;#123;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;               &lt;span class=&#34;title function_&#34;&gt;vote&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;teacher, flag&lt;/span&gt;) &amp;#123;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;                    &lt;span class=&#34;keyword&#34;&gt;let&lt;/span&gt; url = flag? &lt;span class=&#34;string&#34;&gt;&amp;#x27;/praise/&amp;#x27;&lt;/span&gt; : &lt;span class=&#34;string&#34;&gt;&amp;#x27;/criticize/&amp;#x27;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;                    url += &lt;span class=&#34;string&#34;&gt;&amp;#x27;?tno=&amp;#x27;&lt;/span&gt; + teacher.&lt;span class=&#34;property&#34;&gt;no&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;                    &lt;span class=&#34;title function_&#34;&gt;fetch&lt;/span&gt;(url).&lt;span class=&#34;title function_&#34;&gt;then&lt;/span&gt;(&lt;span class=&#34;function&#34;&gt;&lt;span class=&#34;params&#34;&gt;resp&lt;/span&gt; =&amp;gt;&lt;/span&gt; resp.&lt;span class=&#34;title function_&#34;&gt;json&lt;/span&gt;()).&lt;span class=&#34;title function_&#34;&gt;then&lt;/span&gt;(&lt;span class=&#34;function&#34;&gt;&lt;span class=&#34;params&#34;&gt;json&lt;/span&gt; =&amp;gt;&lt;/span&gt; &amp;#123;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;                        &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (json.&lt;span class=&#34;property&#34;&gt;code&lt;/span&gt; === &lt;span class=&#34;number&#34;&gt;10000&lt;/span&gt;) &amp;#123;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;                            &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; (flag) &amp;#123;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;                                teacher.&lt;span class=&#34;property&#34;&gt;good_count&lt;/span&gt; = json.&lt;span class=&#34;property&#34;&gt;count&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;                            &amp;#125; &lt;span class=&#34;keyword&#34;&gt;else&lt;/span&gt; &amp;#123;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;                                teacher.&lt;span class=&#34;property&#34;&gt;bad_count&lt;/span&gt; = json.&lt;span class=&#34;property&#34;&gt;count&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;                            &amp;#125;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;                        &amp;#125;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;                    &amp;#125;)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;                &amp;#125;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;            &amp;#125;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;        &amp;#125;)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;    &lt;/span&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;script&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;body&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;html&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h3 id=&#34;前后端分离下的用户登录&#34;&gt;&lt;a href=&#34;#前后端分离下的用户登录&#34; class=&#34;headerlink&#34; title=&#34;前后端分离下的用户登录&#34;&gt;&lt;/a&gt;前后端分离下的用户登录&lt;/h3&gt;&lt;p&gt;之前我们提到过， HTTP是无状态的，一次请求结束连接断开，下次服务器再收到请求，它就不知道这个请求是哪个用户发过来的。但是对于一个Web应用而言，它是需要有状态管理的，这样才能让服务器知道HTTP请求来自哪个用户，从而判断是否允许该用户请求以及为用户提供更好的服务，这个过程就是常说的&lt;strong&gt;会话管理&lt;/strong&gt;。&lt;/p&gt;
&lt;p&gt;之前我们做会话管理（用户跟踪）的方法是：用户登录成功后，在服务器端通过一个session对象保存用户相关数据，然后把session对象的ID写入浏览器的cookie中；下一次请求时，HTTP请求头中携带cookie的数据，服务器从HTTP请求头读取cookie中的sessionid，根据这个标识符找到对应的session对象，这样就能够获取到之前保存在session中的用户数据。我们刚才说过，REST架构是最适合互联网应用的架构，它强调了HTTP的无状态性，这样才能保证应用的水平扩展能力（当并发访问量增加时，可以通过增加新的服务器节点来为系统扩容）。显然，基于session实现用户跟踪的方式需要服务器保存session对象，在做水平扩展增加新的服务器节点时，需要复制和同步session对象，这显然是非常麻烦的。解决这个问题有两种方案，一种是架设缓存服务器（如Redis），让多个服务器节点共享缓存服务并将session对象直接置于缓存服务器中；另一种方式放弃基于session的用户跟踪，使用&lt;strong&gt;基于token的用户跟踪&lt;/strong&gt;。&lt;/p&gt;
&lt;p&gt;基于token的用户跟踪是在用户登录成功后，为用户生成身份标识并保存在浏览器本地存储（localStorage、sessionStorage、cookie等）中，这样的话服务器不需要保存用户状态，从而可以很容易的做到水平扩展。基于token的用户跟踪具体流程如下：&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;用户登录时，如果登录成功就按照某种方式为用户生成一个令牌（token），该令牌中通常包含了用户标识、过期时间等信息而且需要加密并生成指纹（避免伪造或篡改令牌），服务器将令牌返回给前端；&lt;/li&gt;
&lt;li&gt;前端获取到服务器返回的token，保存在浏览器本地存储中（可以保存在&lt;code&gt;localStorage&lt;/code&gt;或&lt;code&gt;sessionStorage&lt;/code&gt;中，对于使用Vue.js的前端项目来说，还可以通过Vuex进行状态管理）；&lt;/li&gt;
&lt;li&gt;对于使用了前端路由的项目来说，前端每次路由跳转，可以先判断&lt;code&gt;localStroage&lt;/code&gt;中有无token，如果没有则跳转到登录页；&lt;/li&gt;
&lt;li&gt;每次请求后端数据接口，在HTTP请求头里携带token；后端接口判断请求头有无token，如果没有token以及token是无效的或过期的，服务器统一返回401；&lt;/li&gt;
&lt;li&gt;如果前端收到HTTP响应状态码401，则重定向到登录页面。&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;通过上面的描述，相信大家已经发现了，基于token的用户跟踪最为关键是在用户登录成功时，要为用户生成一个token作为用户的身份标识。生成token的方法很多，其中一种比较成熟的解决方案是使用JSON Web Token。&lt;/p&gt;
&lt;h4 id=&#34;JWT概述&#34;&gt;&lt;a href=&#34;#JWT概述&#34; class=&#34;headerlink&#34; title=&#34;JWT概述&#34;&gt;&lt;/a&gt;JWT概述&lt;/h4&gt;&lt;p&gt;JSON Web Token通常简称为JWT，它是一种开放标准（RFC 7519）。随着RESTful架构的流行，越来越多的项目使用JWT作为用户身份认证的方式。JWT相当于是三个JSON对象经过编码后，用&lt;code&gt;.&lt;/code&gt;分隔并组合到一起，这三个JSON对象分别是头部（header）、载荷（payload）和签名（signature），如下图所示。&lt;/p&gt;
&lt;p&gt;&lt;img src=&#34;/res/json-web-token.png&#34;&gt;&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;&lt;p&gt;头部&lt;/p&gt;
 &lt;figure class=&#34;highlight json&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;punctuation&#34;&gt;&amp;#123;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;&amp;quot;alg&amp;quot;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;HS256&amp;quot;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;&amp;quot;typ&amp;quot;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;JWT&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;punctuation&#34;&gt;&amp;#125;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; 其中，&lt;code&gt;alg&lt;/code&gt;属性表示签名的算法，默认是HMAC SHA256（简写成&lt;code&gt;HS256&lt;/code&gt;）；&lt;code&gt;typ&lt;/code&gt;属性表示这个令牌的类型，JWT中都统一书写为&lt;code&gt;JWT&lt;/code&gt;。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;载荷&lt;/p&gt;
&lt;p&gt; 载荷部分用来存放实际需要传递的数据。JWT官方文档中规定了7个可选的字段：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;iss ：签发人&lt;/li&gt;
&lt;li&gt;exp：过期时间&lt;/li&gt;
&lt;li&gt;sub：主题&lt;/li&gt;
&lt;li&gt;aud：受众&lt;/li&gt;
&lt;li&gt;nbf：生效时间&lt;/li&gt;
&lt;li&gt;iat：签发时间&lt;/li&gt;
&lt;li&gt;jti：编号&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt; 除了官方定义的字典，我们可以根据应用的需要添加自定义的字段，如下所示。&lt;/p&gt;
 &lt;figure class=&#34;highlight json&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;punctuation&#34;&gt;&amp;#123;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;&amp;quot;sub&amp;quot;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;1234567890&amp;quot;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;&amp;quot;nickname&amp;quot;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;jackfrued&amp;quot;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;&amp;quot;role&amp;quot;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;admin&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;punctuation&#34;&gt;&amp;#125;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;签名&lt;/p&gt;
&lt;p&gt; 签名部分是对前面两部分生成一个指纹，防止数据伪造和篡改。实现签名首先需要指定一个密钥。这个密钥只有服务器才知道，不能泄露给用户。然后，使用头部指定的签名算法（默认是&lt;code&gt;HS256&lt;/code&gt;），按照下面的公式产生签名。&lt;/p&gt;
 &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;HS256(base64Encode(header) + &lt;span class=&#34;string&#34;&gt;&amp;#x27;.&amp;#x27;&lt;/span&gt; + base64Encode(payload), secret)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; 算出签名以后，把头部、载荷、签名三个部分拼接成一个字符串，每个部分用&lt;code&gt;.&lt;/code&gt;进行分隔，这样一个JWT就生成好了。&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;h4 id=&#34;JWT的优缺点&#34;&gt;&lt;a href=&#34;#JWT的优缺点&#34; class=&#34;headerlink&#34; title=&#34;JWT的优缺点&#34;&gt;&lt;/a&gt;JWT的优缺点&lt;/h4&gt;&lt;p&gt;使用JWT的优点非常明显，包括：&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;更容易实现水平扩展，因为令牌保存在浏览器中，服务器不需要做状态管理。&lt;/li&gt;
&lt;li&gt;更容易防范CSRF攻击，因为在请求头中添加&lt;code&gt;localStorage&lt;/code&gt;或&lt;code&gt;sessionStorage&lt;/code&gt;中的token必须靠JavaScript代码完成，而不是自动添加到请求头中的。&lt;/li&gt;
&lt;li&gt;可以防伪造和篡改，因为JWT有签名，伪造和篡改的令牌无法通过签名验证，会被认定是无效的令牌。&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;当然，任何技术不可能只有优点没有缺点，JWT也有诸多缺点，大家需要在使用的时候引起注意，具体包括：&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;可能会遭受到XSS攻击（跨站脚本攻击），通过注入恶意脚本执行JavaScript代码获取到用户令牌。&lt;/li&gt;
&lt;li&gt;在令牌过期之前，无法作废已经颁发的令牌，要解决这个问题，还需要额外的中间层和代码来辅助。&lt;/li&gt;
&lt;li&gt;JWT是用户的身份令牌，一旦泄露，任何人都可以获得该用户的所有权限。为了降低令牌被盗用后产生的风险，JWT的有效期应该设置得比较短。对于一些比较重要的权限，使用时应通过其他方式再次对用户进行认证，例如短信验证码等。&lt;/li&gt;
&lt;/ol&gt;
&lt;h4 id=&#34;使用PyJWT&#34;&gt;&lt;a href=&#34;#使用PyJWT&#34; class=&#34;headerlink&#34; title=&#34;使用PyJWT&#34;&gt;&lt;/a&gt;使用PyJWT&lt;/h4&gt;&lt;p&gt;在Python代码中，可以使用三方库&lt;code&gt;PyJWT&lt;/code&gt;生成和验证JWT，下面是安装&lt;code&gt;PyJWT&lt;/code&gt;的命令。&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;pip install pyjwt&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;生成令牌。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;payload = &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;#x27;exp&amp;#x27;&lt;/span&gt;: datetime.datetime.utcnow() + datetime.timedelta(days=&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;),&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;#x27;userid&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;number&#34;&gt;10001&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;token = jwt.encode(payload, settings.SECRET_KEY).decode()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;验证令牌。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;try&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    token = &lt;span class=&#34;string&#34;&gt;&amp;#x27;eyJ0eXAiOiJKV1QiLCJhbGciOiJIUzI1NiJ9.eyJleHAiOjE1OTQ4NzIzOTEsInVzZXJpZCI6MTAwMDF9.FM-bNxemWLqQQBIsRVvc4gq71y42I9m2zt5nlFxNHUo&amp;#x27;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    payload = jwt.decode(token, settings.SECRET_KEY)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;except&lt;/span&gt; InvalidTokenError:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;raise&lt;/span&gt; AuthenticationFailed(&lt;span class=&#34;string&#34;&gt;&amp;#x27;无效的令牌或令牌已经过期&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;如果不清楚JWT具体的使用方式，可以先看看第55天的内容，里面提供了完整的投票项目代码的地址。&lt;/p&gt;

 &lt;h2 id=&#34;前后端分离开发入门&#34;&gt;&lt;a href=&#34;#前后端分离开发入门&#34; class=&#34;headerlink&#34; title=&#34;前后端分离开发入门&#34;&gt;&lt;/a&gt;前后端分离开发入门&lt;/h2&gt;&lt;p&gt;在传统的Web应用开发中，大多数的程序员会将浏览器作为前后端的分界线。将浏览器中为用户进行页面展示的部分称之为前端，而将运行在服务器为前端提供业务逻辑和数据准备的所有代码统称为后端。所谓前后端分离的开发，就是前后端工程师约定好数据交互接口，并行的进行开发和测试，后端只提供数据，不负责将数据渲染到页面上，前端通过HTTP请求获取数据并负责将数据渲染到页面上，这个工作是交给浏览器中的JavaScript代码来完成。&lt;/p&gt;
&lt;p&gt;使用前后端分离开发有诸多的好处，下面我们简要的说下这些好处：&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;&lt;strong&gt;提升开发效率&lt;/strong&gt;。前后端分离以后，可以实现前后端代码的解耦，只要前后端沟通约定好应用所需接口以及接口参数，便可以开始并行开发，无需等待对方的开发工作结束。在这种情况下，前后端工程师都可以只专注于自己的开发工作，有助于打造出更好的团队。除此之外，在前后端分离的开发模式下，即使需求发生变更，只要接口与数据格式不变，后端开发人员就不需要修改代码，只要前端进行变动即可。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;增强代码的可维护性&lt;/strong&gt;。前后端分离后，应用的代码不再是前后端混合，只有在运行期才会有调用依赖关系，这样的话维护代码的工作将变得轻松愉快很多，再不会牵一发而动全身。当你的代码变得简明且整洁时，代码的可读性和可维护性都会有质的提升。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;支持多终端和服务化架构&lt;/strong&gt;。前后端分离后，同一套数据接口可以为不同的终端提供服务，更有助于打造多终端应用；此外，由于后端提供的接口之间可以通过HTTP(S)进行调用，有助于打造服务化架构（包括微服务）。&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;接下来我们就用前后端分离的方式来改写之前的投票应用。&lt;/p&gt;
&lt;h3 id=&#34;返回JSON格式的数据&#34;&gt;&lt;a href=&#34;#返回JSON格式的数据&#34; class=&#34;headerlink&#34; title=&#34;返回JSON格式的数据&#34;&gt;&lt;/a&gt;返回JSON格式的数据&lt;/h3&gt;&lt;p&gt;刚才说过，在前后端分离的开发模式下，后端需要为前端提供数据接口，这些接口通常返回JSON格式的数据。在Django项目中，我们可以先将对象处理成字典，然后就可以利用Django封装的&lt;code&gt;JsonResponse&lt;/code&gt;向浏览器返回JSON格式的数据，具体的做法如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;show_subjects&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;request&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    queryset = Subject.objects.&lt;span class=&#34;built_in&#34;&gt;all&lt;/span&gt;()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    subjects = []&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; subject &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; queryset:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        subjects.append(&amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;string&#34;&gt;&amp;#x27;no&amp;#x27;&lt;/span&gt;: subject.no,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;string&#34;&gt;&amp;#x27;name&amp;#x27;&lt;/span&gt;: subject.name,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;string&#34;&gt;&amp;#x27;intro&amp;#x27;&lt;/span&gt;: subject.intro,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;string&#34;&gt;&amp;#x27;isHot&amp;#x27;&lt;/span&gt;: subject.is_hot&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &amp;#125;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; JsonResponse(subjects, safe=&lt;span class=&#34;literal&#34;&gt;False&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;上面的代码中，我们通过循环遍历查询学科得到的&lt;code&gt;QuerySet&lt;/code&gt;对象，将每个学科的数据处理成一个字典，在将字典保存在名为&lt;code&gt;subjects&lt;/code&gt;的列表容器中，最后利用&lt;code&gt;JsonResponse&lt;/code&gt;完成对列表的序列化，向浏览器返回JSON格式的数据。由于&lt;code&gt;JsonResponse&lt;/code&gt;序列化的是一个列表而不是字典，所以需要指定&lt;code&gt;safe&lt;/code&gt;参数的值为&lt;code&gt;False&lt;/code&gt;才能完成对&lt;code&gt;subjects&lt;/code&gt;的序列化，否则会产生&lt;code&gt;TypeError&lt;/code&gt;异常。&lt;/p&gt;
&lt;p&gt;可能大家已经发现了，自己写代码将一个对象转成字典是比较麻烦的，如果对象的属性很多而且某些属性又关联到一个比较复杂的对象时，情况会变得更加糟糕。为此我们可以使用一个名为&lt;code&gt;bpmappers&lt;/code&gt;的三方库来简化将对象转成字典的操作，这个三方库本身也提供了对Django框架的支持。&lt;/p&gt;
&lt;p&gt;安装三方库&lt;code&gt;bpmappers&lt;/code&gt;。&lt;/p&gt;
&lt;figure class=&#34;highlight shell&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;pip install bpmappers&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;编写映射器（实现对象到字典转换）。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; bpmappers.djangomodel &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; ModelMapper&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; poll2.models &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; Subject&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;class&lt;/span&gt; &lt;span class=&#34;title class_&#34;&gt;SubjectMapper&lt;/span&gt;(&lt;span class=&#34;title class_ inherited__&#34;&gt;ModelMapper&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;   &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;class&lt;/span&gt; &lt;span class=&#34;title class_&#34;&gt;Meta&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        model = Subject&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;修改视图函数。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;show_subjects&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;request&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    queryset = Subject.objects.&lt;span class=&#34;built_in&#34;&gt;all&lt;/span&gt;()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    subjects = []&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; subject &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; queryset:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        subjects.append(SubjectMapper(subject).as_dict())&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; JsonResponse(subjects, safe=&lt;span class=&#34;literal&#34;&gt;False&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;配置URL映射。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;urlpatterns = [&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    path(&lt;span class=&#34;string&#34;&gt;&amp;#x27;api/subjects/&amp;#x27;&lt;/span&gt;, show_subjects),&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;]&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;然后访问该接口，可以得到如下所示的JSON格式数据。&lt;/p&gt;
&lt;figure class=&#34;highlight json&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;punctuation&#34;&gt;[&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;punctuation&#34;&gt;&amp;#123;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;attr&#34;&gt;&amp;quot;no&amp;quot;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;:&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;attr&#34;&gt;&amp;quot;name&amp;quot;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;Python全栈+人工智能&amp;quot;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;attr&#34;&gt;&amp;quot;intro&amp;quot;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;Python是一种计算机程序设计语言。是一种面向对象的动态类型语言，最初被设计用于编写自动化脚本(shell)，随着版本的不断更新和语言新功能的添加，越来越多被用于独立的、大型项目的开发。&amp;quot;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;attr&#34;&gt;&amp;quot;is_hot&amp;quot;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;:&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;true&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;punctuation&#34;&gt;&amp;#125;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;// 此处省略下面的内容&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;punctuation&#34;&gt;]&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;如果不希望在JSON数据中显示学科的成立时间，我们可以在映射器中排除&lt;code&gt;create_date&lt;/code&gt;属性；如果希望将是否为热门学科对应的键取名为&lt;code&gt;isHot&lt;/code&gt;（默认的名字是&lt;code&gt;is_hot&lt;/code&gt;），也可以通过修改映射器来做到。具体的做法如下所示：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; bpmappers &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; RawField&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; bpmappers.djangomodel &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; ModelMapper&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; poll2.models &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; Subject&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;class&lt;/span&gt; &lt;span class=&#34;title class_&#34;&gt;SubjectMapper&lt;/span&gt;(&lt;span class=&#34;title class_ inherited__&#34;&gt;ModelMapper&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    isHot = RawField(&lt;span class=&#34;string&#34;&gt;&amp;#x27;is_hot&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;class&lt;/span&gt; &lt;span class=&#34;title class_&#34;&gt;Meta&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        model = Subject&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        exclude = (&lt;span class=&#34;string&#34;&gt;&amp;#x27;is_hot&amp;#x27;&lt;/span&gt;, )&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;再次查看学科接口返回的JSON数据。&lt;/p&gt;
&lt;figure class=&#34;highlight json&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;punctuation&#34;&gt;[&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;punctuation&#34;&gt;&amp;#123;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;attr&#34;&gt;&amp;quot;no&amp;quot;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;:&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;101&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;attr&#34;&gt;&amp;quot;name&amp;quot;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;Python全栈+人工智能&amp;quot;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;attr&#34;&gt;&amp;quot;intro&amp;quot;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;Python是一种计算机程序设计语言。是一种面向对象的动态类型语言，最初被设计用于编写自动化脚本(shell)，随着版本的不断更新和语言新功能的添加，越来越多被用于独立的、大型项目的开发。&amp;quot;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;attr&#34;&gt;&amp;quot;isHot&amp;quot;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;:&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;true&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;punctuation&#34;&gt;&amp;#125;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;// 此处省略下面的内容&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;punctuation&#34;&gt;]&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;关于&lt;code&gt;bpmappers&lt;/code&gt;详细的使用指南，请参考它的&lt;a href=&#34;https://bpmappers.readthedocs.io/en/stable/&#34;&gt;官方文档&lt;/a&gt;，这个官方文档是用日语书写的，可以使用浏览器的翻译功能将它翻译成你熟悉的语言即可。&lt;/p&gt;
&lt;h3 id=&#34;使用Vue-js渲染页面&#34;&gt;&lt;a href=&#34;#使用Vue-js渲染页面&#34; class=&#34;headerlink&#34; title=&#34;使用Vue.js渲染页面&#34;&gt;&lt;/a&gt;使用Vue.js渲染页面&lt;/h3&gt;&lt;p&gt;接下来我们通过前端框架Vue.js来实现页面的渲染。如果希望全面的了解和学习Vue.js，建议阅读它的&lt;a href=&#34;https://cn.vuejs.org/v2/guide/&#34;&gt;官方教程&lt;/a&gt;或者在&lt;a href=&#34;https://www.youtube.com/&#34;&gt;YouTube&lt;/a&gt;上搜索Vue.js的新手教程（Vue.js Crash Course）进行学习。&lt;/p&gt;
&lt;p&gt;重新改写subjects.html页面，使用Vue.js来渲染页面。&lt;/p&gt;
&lt;figure class=&#34;highlight html&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;meta&#34;&gt;&amp;lt;!DOCTYPE &lt;span class=&#34;keyword&#34;&gt;html&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;html&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;lang&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;en&amp;quot;&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;head&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;meta&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;charset&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;UTF-8&amp;quot;&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;title&lt;/span&gt;&amp;gt;&lt;/span&gt;学科信息&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;title&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;style&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;span class=&#34;language-css&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-css&#34;&gt;		&lt;span class=&#34;comment&#34;&gt;/* 此处省略层叠样式表 */&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-css&#34;&gt;    &lt;/span&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;style&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;head&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;body&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;div&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;id&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;container&amp;quot;&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;h1&lt;/span&gt;&amp;gt;&lt;/span&gt;扣丁学堂所有学科&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;h1&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;hr&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;div&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;id&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;main&amp;quot;&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;dl&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;v-for&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;subject in subjects&amp;quot;&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;dt&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                    &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;a&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;:href&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;&amp;#x27;/static/html/teachers.html?sno=&amp;#x27; + subject.no&amp;quot;&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                        &amp;#123;&amp;#123; subject.name &amp;#125;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                    &lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;a&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                    &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;img&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;v-if&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;subject.is_hot&amp;quot;&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;src&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;/static/images/hot-icon-small.png&amp;quot;&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                &lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;dt&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;dd&lt;/span&gt;&amp;gt;&lt;/span&gt;&amp;#123;&amp;#123; subject.intro &amp;#125;&amp;#125;&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;dd&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;dl&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;div&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;div&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;script&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;src&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;https://cdn.bootcdn.net/ajax/libs/vue/2.6.11/vue.min.js&amp;quot;&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;script&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;script&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;span class=&#34;language-javascript&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;let&lt;/span&gt; app = &lt;span class=&#34;keyword&#34;&gt;new&lt;/span&gt; &lt;span class=&#34;title class_&#34;&gt;Vue&lt;/span&gt;(&amp;#123;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;            &lt;span class=&#34;attr&#34;&gt;el&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;#main&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;            &lt;span class=&#34;attr&#34;&gt;data&lt;/span&gt;: &amp;#123;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;                &lt;span class=&#34;attr&#34;&gt;subjects&lt;/span&gt;: []&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;            &amp;#125;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;            &lt;span class=&#34;title function_&#34;&gt;created&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;&lt;/span&gt;) &amp;#123;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;                &lt;span class=&#34;title function_&#34;&gt;fetch&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&amp;#x27;/api/subjects/&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;                    .&lt;span class=&#34;title function_&#34;&gt;then&lt;/span&gt;(&lt;span class=&#34;function&#34;&gt;&lt;span class=&#34;params&#34;&gt;resp&lt;/span&gt; =&amp;gt;&lt;/span&gt; resp.&lt;span class=&#34;title function_&#34;&gt;json&lt;/span&gt;())&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;                    .&lt;span class=&#34;title function_&#34;&gt;then&lt;/span&gt;(&lt;span class=&#34;function&#34;&gt;&lt;span class=&#34;params&#34;&gt;json&lt;/span&gt; =&amp;gt;&lt;/span&gt; &amp;#123;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;                        &lt;span class=&#34;variable language_&#34;&gt;this&lt;/span&gt;.&lt;span class=&#34;property&#34;&gt;subjects&lt;/span&gt; = json&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;                    &amp;#125;)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;            &amp;#125;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;        &amp;#125;)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;    &lt;/span&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;script&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;body&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;html&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;前后端分离的开发需要将前端页面作为静态资源进行部署，项目实际上线的时候，我们会对整个Web应用进行动静分离，静态资源通过Nginx或Apache服务器进行部署，生成动态内容的Python程序部署在uWSGI或者Gunicorn服务器上，对动态内容的请求由Nginx或Apache路由到uWSGI或Gunicorn服务器上。&lt;/p&gt;
&lt;p&gt;在开发阶段，我们通常会使用Django自带的测试服务器，如果要尝试前后端分离，可以先将静态页面放在之前创建的放静态资源的目录下，具体的做法可以参考&lt;a href=&#34;https://gitee.com/jackfrued/django19062&#34;&gt;项目完整代码&lt;/a&gt;。&lt;/p&gt;

 &lt;h2 id=&#34;中间件的应用&#34;&gt;&lt;a href=&#34;#中间件的应用&#34; class=&#34;headerlink&#34; title=&#34;中间件的应用&#34;&gt;&lt;/a&gt;中间件的应用&lt;/h2&gt;&lt;p&gt;之前我们已经实现了用户必须登录才能投票的限制，但是一个新的问题来了。如果我们的应用中有很多功能都需要用户先登录才能执行，例如将前面导出Excel报表和查看统计图表的功能都做了必须登录才能访问的限制，那么我们是不是需要在每个视图函数中添加代码来检查session中是否包含&lt;code&gt;userid&lt;/code&gt;的代码呢？答案是否定的，如果这样做了，我们的视图函数中必然会充斥着大量的重复代码。编程大师&lt;em&gt;Martin Fowler&lt;/em&gt;曾经说过：&lt;strong&gt;代码有很多种坏味道，重复是最坏的一种&lt;/strong&gt;。在Python程序中，我们可以通过装饰器来为函数提供额外的能力；在Django项目中，我们可以把类似于验证用户是否登录这样的重复性代码放到&lt;strong&gt;中间件&lt;/strong&gt;中。&lt;/p&gt;
&lt;h3 id=&#34;Django中间件概述&#34;&gt;&lt;a href=&#34;#Django中间件概述&#34; class=&#34;headerlink&#34; title=&#34;Django中间件概述&#34;&gt;&lt;/a&gt;Django中间件概述&lt;/h3&gt;&lt;p&gt;中间件是安插在Web应用请求和响应过程之间的组件，它在整个Web应用中扮演了拦截过滤器的角色，通过中间件可以拦截请求和响应，并对请求和响应进行过滤（简单的说就是执行额外的处理）。通常，一个中间件组件只专注于完成一件特定的事，例如：Django框架通过&lt;code&gt;SessionMiddleware&lt;/code&gt;中间件实现了对session的支持，又通过&lt;code&gt;AuthenticationMiddleware&lt;/code&gt;中间件实现了基于session的请求认证。通过把多个中间件组合在一起，我们可以完成更为复杂的任务，Django框架就是这么做的。&lt;/p&gt;
&lt;p&gt;Django项目的配置文件中就包含了对中间件的配置，代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;MIDDLEWARE = [&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;#x27;django.middleware.security.SecurityMiddleware&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;#x27;django.contrib.sessions.middleware.SessionMiddleware&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;#x27;django.middleware.common.CommonMiddleware&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;#x27;django.middleware.csrf.CsrfViewMiddleware&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;#x27;django.contrib.auth.middleware.AuthenticationMiddleware&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;#x27;django.contrib.messages.middleware.MessageMiddleware&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;#x27;django.middleware.clickjacking.XFrameOptionsMiddleware&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;]&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;我们稍微为大家解释一下这些中间件的作用：&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;&lt;code&gt;CommonMiddleware&lt;/code&gt; - 基础设置中间件，可以处理以下一些配置参数。&lt;ul&gt;
&lt;li&gt;DISALLOWED_USER_AGENTS - 不被允许的用户代理（浏览器）&lt;/li&gt;
&lt;li&gt;APPEND_SLASH - 是否追加&lt;code&gt;/&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;USE_ETAG - 浏览器缓存相关&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;code&gt;SecurityMiddleware&lt;/code&gt; - 安全相关中间件，可以处理和安全相关的配置项。&lt;ul&gt;
&lt;li&gt;SECURE_HSTS_SECONDS - 强制使用HTTPS的时间&lt;/li&gt;
&lt;li&gt;SECURE_HSTS_INCLUDE_SUBDOMAINS - HTTPS是否覆盖子域名&lt;/li&gt;
&lt;li&gt;SECURE_CONTENT_TYPE_NOSNIFF - 是否允许浏览器推断内容类型&lt;/li&gt;
&lt;li&gt;SECURE_BROWSER_XSS_FILTER - 是否启用跨站脚本攻击过滤器&lt;/li&gt;
&lt;li&gt;SECURE_SSL_REDIRECT - 是否重定向到HTTPS连接&lt;/li&gt;
&lt;li&gt;SECURE_REDIRECT_EXEMPT - 免除重定向到HTTPS&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;code&gt;SessionMiddleware&lt;/code&gt; - 会话中间件。&lt;/li&gt;
&lt;li&gt;&lt;code&gt;CsrfViewMiddleware&lt;/code&gt; - 通过生成令牌，防范跨请求份伪的造中间件。&lt;/li&gt;
&lt;li&gt;&lt;code&gt;XFrameOptionsMiddleware&lt;/code&gt; - 通过设置请求头参数，防范点击劫持攻击的中间件。&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;在请求的过程中，上面的中间件会按照书写的顺序从上到下执行，然后是URL解析，最后请求才会来到视图函数；在响应的过程中，上面的中间件会按照书写的顺序从下到上执行，与请求时中间件执行的顺序正好相反。&lt;/p&gt;
&lt;h3 id=&#34;自定义中间件&#34;&gt;&lt;a href=&#34;#自定义中间件&#34; class=&#34;headerlink&#34; title=&#34;自定义中间件&#34;&gt;&lt;/a&gt;自定义中间件&lt;/h3&gt;&lt;p&gt;Django中的中间件有两种实现方式：基于类的实现方式和基于函数的实现方式，后者更接近于装饰器的写法。装饰器实际上是代理模式的应用，将横切关注功能（与正常业务逻辑没有必然联系的功能，例如：身份认证、日志记录、编码转换之类的功能）置于代理中，由代理对象来完成被代理对象的行为并添加额外的功能。中间件对用户请求和响应进行拦截过滤并增加额外的处理，在这一点上它跟装饰器是完全一致的，所以基于函数的写法来实现中间件就跟装饰器的写法几乎一模一样。下面我们用自定义的中间件来实现用户登录验证的功能。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;&amp;quot;&amp;quot;&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;middlewares.py&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;&amp;quot;&amp;quot;&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; django.http &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; JsonResponse&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; django.shortcuts &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; redirect&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 需要登录才能访问的资源路径&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;LOGIN_REQUIRED_URLS = &amp;#123;&lt;span class=&#34;string&#34;&gt;&amp;#x27;/praise/&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;/criticize/&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;/excel/&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;/teachers_data/&amp;#x27;&lt;/span&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;check_login_middleware&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;get_resp&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;wrapper&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;request, *args, **kwargs&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;# 请求的资源路径在上面的集合中&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; request.path &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; LOGIN_REQUIRED_URLS:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;comment&#34;&gt;# 会话中包含userid则视为已经登录&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;#x27;userid&amp;#x27;&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;not&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; request.session:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                &lt;span class=&#34;comment&#34;&gt;# 判断是不是Ajax请求&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; request.is_ajax():&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                    &lt;span class=&#34;comment&#34;&gt;# Ajax请求返回JSON数据提示用户登录&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                    &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; JsonResponse(&amp;#123;&lt;span class=&#34;string&#34;&gt;&amp;#x27;code&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;number&#34;&gt;10003&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;hint&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;请先登录&amp;#x27;&lt;/span&gt;&amp;#125;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                &lt;span class=&#34;keyword&#34;&gt;else&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                    backurl = request.get_full_path()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                    &lt;span class=&#34;comment&#34;&gt;# 非Ajax请求直接重定向到登录页&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                    &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; redirect(&lt;span class=&#34;string&#34;&gt;f&amp;#x27;/login/?backurl=&lt;span class=&#34;subst&#34;&gt;&amp;#123;backurl&amp;#125;&lt;/span&gt;&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; get_resp(request, *args, **kwargs)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; wrapper&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;当然，我们也可以定义一个类来充当装饰器，如果类中有&lt;code&gt;__call__&lt;/code&gt;魔术方法，这个类的对象就像函数一样可调用，所以下面是另一种实现中间件的方式，道理跟上面的代码完全一样。&lt;/p&gt;
&lt;p&gt;还有一种基于类实现中间件的方式，这种方式在较新版本的Django中已经不推荐使用了，但是大家接触到的代码中，仍然有可能遇到这种写法，大致的代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; django.utils.deprecation &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; MiddlewareMixin&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;class&lt;/span&gt; &lt;span class=&#34;title class_&#34;&gt;MyMiddleware&lt;/span&gt;(&lt;span class=&#34;title class_ inherited__&#34;&gt;MiddlewareMixin&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;process_request&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;self, request&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;pass&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;process_view&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;self, request, view_func, view_args, view_kwargs&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;pass&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;process_template_response&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;self, request, response&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;pass&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;process_response&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;self, request, response&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;pass&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;process_exception&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;self, request, exception&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;pass&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;上面类中的五个方法都是中间件的钩子函数，分别在收到用户请求、进入视图函数之前、渲染模板、返回响应和出现异常的时候被回调。当然，写不写这些方法是根据中间件的需求来确定的，并不是所有的场景都需要重写五个方法，下面的图相信能够帮助大家理解这种写法。&lt;/p&gt;
&lt;p&gt;&lt;img src=&#34;/res/django-middleware.png&#34;&gt;&lt;/p&gt;
&lt;p&gt;写好中间件代码后，需要修改配置文件来激活中间件使其生效。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;MIDDLEWARE = [&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;#x27;django.middleware.security.SecurityMiddleware&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;#x27;django.contrib.sessions.middleware.SessionMiddleware&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;#x27;django.middleware.common.CommonMiddleware&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;#x27;django.middleware.csrf.CsrfViewMiddleware&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;#x27;django.contrib.auth.middleware.AuthenticationMiddleware&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;#x27;django.contrib.messages.middleware.MessageMiddleware&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;#x27;django.middleware.clickjacking.XFrameOptionsMiddleware&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;#x27;debug_toolbar.middleware.DebugToolbarMiddleware&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;#x27;vote.middlewares.check_login_middleware&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;]&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;注意上面这个中间件列表中元素的顺序，当收到来自用户的请求时，中间件按照从上到下的顺序依次执行，这行完这些中间件以后，请求才会最终到达视图函数。当然，在这个过程中，用户的请求可以被拦截，就像上面我们自定义的中间件那样，如果用户在没有登录的情况下访问了受保护的资源，中间件会将请求直接重定向到登录页，后面的中间件和视图函数将不再执行。在响应用户请求的过程中，上面的中间件会按照从下到上的顺序依次执行，这样的话我们还可以对响应做进一步的处理。&lt;/p&gt;
&lt;p&gt;中间件执行的顺序是非常重要的，对于有依赖关系的中间件必须保证被依赖的中间件要置于依赖它的中间件的前面，就好比我们刚才自定义的中间件要放到&lt;code&gt;SessionMiddleware&lt;/code&gt;的后面，因为我们要依赖这个中间件为请求绑定的&lt;code&gt;session&lt;/code&gt;对象才能判定用户是否登录。&lt;/p&gt;

 &lt;h2 id=&#34;日志和调试工具栏&#34;&gt;&lt;a href=&#34;#日志和调试工具栏&#34; class=&#34;headerlink&#34; title=&#34;日志和调试工具栏&#34;&gt;&lt;/a&gt;日志和调试工具栏&lt;/h2&gt;&lt;h3 id=&#34;配置日志&#34;&gt;&lt;a href=&#34;#配置日志&#34; class=&#34;headerlink&#34; title=&#34;配置日志&#34;&gt;&lt;/a&gt;配置日志&lt;/h3&gt;&lt;p&gt;项目开发阶段，显示足够的调试信息以辅助开发人员调试代码还是非常必要的；项目上线以后，将系统运行时出现的警告、错误等信息记录下来以备相关人员了解系统运行状况并维护代码也是很有必要的。与此同时，采集日志数据也是为网站做数字化运营奠定一个基础，通过对系统运行日志的分析，我们可以监测网站的流量以及流量分布，同时还可以挖掘出用户的使用习惯和行为模式。&lt;/p&gt;
&lt;p&gt;接下来，我们先看看如何通过Django的配置文件来配置日志。Django的日志配置基本可以参照官方文档再结合项目实际需求来进行，这些内容基本上可以从官方文档上复制下来，然后进行局部的调整即可，下面给出一些参考配置。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;LOGGING = &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;#x27;version&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 是否禁用已经存在的日志器&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;#x27;disable_existing_loggers&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;literal&#34;&gt;False&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 日志格式化器&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;#x27;formatters&amp;#x27;&lt;/span&gt;: &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;string&#34;&gt;&amp;#x27;simple&amp;#x27;&lt;/span&gt;: &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;string&#34;&gt;&amp;#x27;format&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;%(asctime)s %(module)s.%(funcName)s: %(message)s&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;string&#34;&gt;&amp;#x27;datefmt&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;%Y-%m-%d %H:%M:%S&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &amp;#125;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;string&#34;&gt;&amp;#x27;verbose&amp;#x27;&lt;/span&gt;: &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;string&#34;&gt;&amp;#x27;format&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;%(asctime)s %(levelname)s [%(process)d-%(threadName)s] &amp;#x27;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                      &lt;span class=&#34;string&#34;&gt;&amp;#x27;%(module)s.%(funcName)s line %(lineno)d: %(message)s&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;string&#34;&gt;&amp;#x27;datefmt&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;%Y-%m-%d %H:%M:%S&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &amp;#125;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 日志过滤器&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;#x27;filters&amp;#x27;&lt;/span&gt;: &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;# 只有在Django配置文件中DEBUG值为True时才起作用&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;string&#34;&gt;&amp;#x27;require_debug_true&amp;#x27;&lt;/span&gt;: &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;string&#34;&gt;&amp;#x27;()&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;django.utils.log.RequireDebugTrue&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &amp;#125;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &amp;#125;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 日志处理器&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;#x27;handlers&amp;#x27;&lt;/span&gt;: &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;# 输出到控制台&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;string&#34;&gt;&amp;#x27;console&amp;#x27;&lt;/span&gt;: &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;string&#34;&gt;&amp;#x27;class&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;logging.StreamHandler&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;string&#34;&gt;&amp;#x27;level&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;DEBUG&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;string&#34;&gt;&amp;#x27;filters&amp;#x27;&lt;/span&gt;: [&lt;span class=&#34;string&#34;&gt;&amp;#x27;require_debug_true&amp;#x27;&lt;/span&gt;],&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;string&#34;&gt;&amp;#x27;formatter&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;simple&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &amp;#125;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;# 输出到文件(每周切割一次)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;string&#34;&gt;&amp;#x27;file1&amp;#x27;&lt;/span&gt;: &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;string&#34;&gt;&amp;#x27;class&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;logging.handlers.TimedRotatingFileHandler&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;string&#34;&gt;&amp;#x27;filename&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;access.log&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;string&#34;&gt;&amp;#x27;when&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;W0&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;string&#34;&gt;&amp;#x27;backupCount&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;number&#34;&gt;12&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;string&#34;&gt;&amp;#x27;formatter&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;simple&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;string&#34;&gt;&amp;#x27;level&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;INFO&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &amp;#125;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;comment&#34;&gt;# 输出到文件(每天切割一次)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;string&#34;&gt;&amp;#x27;file2&amp;#x27;&lt;/span&gt;: &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;string&#34;&gt;&amp;#x27;class&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;logging.handlers.TimedRotatingFileHandler&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;string&#34;&gt;&amp;#x27;filename&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;error.log&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;string&#34;&gt;&amp;#x27;when&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;D&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;string&#34;&gt;&amp;#x27;backupCount&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;number&#34;&gt;31&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;string&#34;&gt;&amp;#x27;formatter&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;verbose&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;string&#34;&gt;&amp;#x27;level&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;WARNING&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &amp;#125;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &amp;#125;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 日志器记录器&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;#x27;loggers&amp;#x27;&lt;/span&gt;: &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;string&#34;&gt;&amp;#x27;django&amp;#x27;&lt;/span&gt;: &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;comment&#34;&gt;# 需要使用的日志处理器&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;string&#34;&gt;&amp;#x27;handlers&amp;#x27;&lt;/span&gt;: [&lt;span class=&#34;string&#34;&gt;&amp;#x27;console&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;file1&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;file2&amp;#x27;&lt;/span&gt;],&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;comment&#34;&gt;# 是否向上传播日志信息&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;string&#34;&gt;&amp;#x27;propagate&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;literal&#34;&gt;True&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;comment&#34;&gt;# 日志级别(不一定是最终的日志级别)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;string&#34;&gt;&amp;#x27;level&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;DEBUG&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &amp;#125;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;大家可能已经注意到了，上面日志配置中的&lt;code&gt;formatters&lt;/code&gt;是&lt;strong&gt;日志格式化器&lt;/strong&gt;，它代表了如何格式化输出日志，其中格式占位符分别表示：&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;&lt;code&gt;%(name)s&lt;/code&gt; - 记录器的名称&lt;/li&gt;
&lt;li&gt;&lt;code&gt;%(levelno)s&lt;/code&gt; - 数字形式的日志记录级别&lt;/li&gt;
&lt;li&gt;&lt;code&gt;%(levelname)s&lt;/code&gt; - 日志记录级别的文本名称&lt;/li&gt;
&lt;li&gt;&lt;code&gt;%(filename)s&lt;/code&gt; - 执行日志记录调用的源文件的文件名称&lt;/li&gt;
&lt;li&gt;&lt;code&gt;%(pathname)s&lt;/code&gt; - 执行日志记录调用的源文件的路径名称&lt;/li&gt;
&lt;li&gt;&lt;code&gt;%(funcName)s&lt;/code&gt; - 执行日志记录调用的函数名称&lt;/li&gt;
&lt;li&gt;&lt;code&gt;%(module)s&lt;/code&gt; - 执行日志记录调用的模块名称&lt;/li&gt;
&lt;li&gt;&lt;code&gt;%(lineno)s&lt;/code&gt; - 执行日志记录调用的行号&lt;/li&gt;
&lt;li&gt;&lt;code&gt;%(created)s&lt;/code&gt; - 执行日志记录的时间&lt;/li&gt;
&lt;li&gt;&lt;code&gt;%(asctime)s&lt;/code&gt; - 日期和时间&lt;/li&gt;
&lt;li&gt;&lt;code&gt;%(msecs)s&lt;/code&gt; - 毫秒部分&lt;/li&gt;
&lt;li&gt;&lt;code&gt;%(thread)d&lt;/code&gt; - 线程ID（整数）&lt;/li&gt;
&lt;li&gt;&lt;code&gt;%(threadName)s&lt;/code&gt; - 线程名称&lt;/li&gt;
&lt;li&gt;&lt;code&gt;%(process)d&lt;/code&gt; - 进程ID （整数）&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;日志配置中的handlers用来指定&lt;strong&gt;日志处理器&lt;/strong&gt;，简单的说就是指定将日志输出到控制台还是文件又或者是网络上的服务器，可用的处理器包括：&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;&lt;code&gt;logging.StreamHandler(stream=None)&lt;/code&gt; - 可以向类似与&lt;code&gt;sys.stdout&lt;/code&gt;或者&lt;code&gt;sys.stderr&lt;/code&gt;的任何文件对象输出信息&lt;/li&gt;
&lt;li&gt;&lt;code&gt;logging.FileHandler(filename, mode=&amp;#39;a&amp;#39;, encoding=None, delay=False)&lt;/code&gt; - 将日志消息写入文件&lt;/li&gt;
&lt;li&gt;&lt;code&gt;logging.handlers.DatagramHandler(host, port)&lt;/code&gt; - 使用UDP协议，将日志信息发送到指定主机和端口的网络主机上&lt;/li&gt;
&lt;li&gt;&lt;code&gt;logging.handlers.HTTPHandler(host, url)&lt;/code&gt; - 使用HTTP的GET或POST方法将日志消息上传到一台HTTP 服务器&lt;/li&gt;
&lt;li&gt;&lt;code&gt;logging.handlers.RotatingFileHandler(filename, mode=&amp;#39;a&amp;#39;, maxBytes=0, backupCount=0, encoding=None, delay=False)&lt;/code&gt; - 将日志消息写入文件，如果文件的大小超出&lt;code&gt;maxBytes&lt;/code&gt;指定的值，那么将重新生成一个文件来记录日志&lt;/li&gt;
&lt;li&gt;&lt;code&gt;logging.handlers.SocketHandler(host, port)&lt;/code&gt; - 使用TCP协议，将日志信息发送到指定主机和端口的网络主机上 &lt;/li&gt;
&lt;li&gt;&lt;code&gt;logging.handlers.SMTPHandler(mailhost, fromaddr, toaddrs, subject, credentials=None, secure=None, timeout=1.0)&lt;/code&gt; - 将日志输出到指定的邮件地址&lt;/li&gt;
&lt;li&gt;&lt;code&gt;logging.MemoryHandler(capacity, flushLevel=ERROR, target=None, flushOnClose=True)&lt;/code&gt; - 将日志输出到内存指定的缓冲区中&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;上面每个日志处理器都指定了一个名为&lt;code&gt;level&lt;/code&gt;的属性，它代表了日志的级别，不同的日志级别反映出日志中记录信息的严重性。Python中定义了六个级别的日志，按照从低到高的顺序依次是：NOTSET、DEBUG、INFO、WARNING、ERROR、CRITICAL。&lt;/p&gt;
&lt;p&gt;最后配置的&lt;strong&gt;日志记录器&lt;/strong&gt;是用来真正输出日志的，Django框架提供了如下所示的内置记录器：&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;&lt;code&gt;django&lt;/code&gt; - 在Django层次结构中的所有消息记录器&lt;/li&gt;
&lt;li&gt;&lt;code&gt;django.request&lt;/code&gt; - 与请求处理相关的日志消息。5xx响应被视为错误消息；4xx响应被视为为警告消息&lt;/li&gt;
&lt;li&gt;&lt;code&gt;django.server&lt;/code&gt; - 与通过runserver调用的服务器所接收的请求相关的日志消息。5xx响应被视为错误消息；4xx响应被记录为警告消息；其他一切都被记录为INFO&lt;/li&gt;
&lt;li&gt;&lt;code&gt;django.template&lt;/code&gt; - 与模板渲染相关的日志消息&lt;/li&gt;
&lt;li&gt;&lt;code&gt;django.db.backends&lt;/code&gt; - 有与数据库交互产生的日志消息，如果希望显示ORM框架执行的SQL语句，就可以使用该日志记录器。&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;日志记录器中配置的日志级别有可能不是最终的日志级别，因为还要参考日志处理器中配置的日志级别，取二者中级别较高者作为最终的日志级别。&lt;/p&gt;
&lt;h3 id=&#34;配置Django-Debug-Toolbar&#34;&gt;&lt;a href=&#34;#配置Django-Debug-Toolbar&#34; class=&#34;headerlink&#34; title=&#34;配置Django-Debug-Toolbar&#34;&gt;&lt;/a&gt;配置Django-Debug-Toolbar&lt;/h3&gt;&lt;p&gt;如果想调试你的Django项目，你一定不能不过名为Django-Debug-Toolbar的神器，它是项目开发阶段辅助调试和优化的必备工具，只要配置了它，就可以很方便的查看到如下表所示的项目运行信息，这些信息对调试项目和优化Web应用性能都是至关重要的。&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;项目&lt;/th&gt;
&lt;th&gt;说明&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;Versions&lt;/td&gt;
&lt;td&gt;Django的版本&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Time&lt;/td&gt;
&lt;td&gt;显示视图耗费的时间&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Settings&lt;/td&gt;
&lt;td&gt;配置文件中设置的值&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Headers&lt;/td&gt;
&lt;td&gt;HTTP请求头和响应头的信息&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Request&lt;/td&gt;
&lt;td&gt;和请求相关的各种变量及其信息&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;StaticFiles&lt;/td&gt;
&lt;td&gt;静态文件加载情况&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Templates&lt;/td&gt;
&lt;td&gt;模板的相关信息&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Cache&lt;/td&gt;
&lt;td&gt;缓存的使用情况&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Signals&lt;/td&gt;
&lt;td&gt;Django内置的信号信息&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Logging&lt;/td&gt;
&lt;td&gt;被记录的日志信息&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;SQL&lt;/td&gt;
&lt;td&gt;向数据库发送的SQL语句及其执行时间&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;ol&gt;
&lt;li&gt;&lt;p&gt;安装Django-Debug-Toolbar。&lt;/p&gt;
&lt;figure class=&#34;highlight shell&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;pip install django-debug-toolbar&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;配置 - 修改settings.py。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;INSTALLED_APPS = [&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;#x27;debug_toolbar&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;MIDDLEWARE = [&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;#x27;debug_toolbar.middleware.DebugToolbarMiddleware&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;DEBUG_TOOLBAR_CONFIG = &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 引入jQuery库&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;#x27;JQUERY_URL&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;https://cdn.bootcss.com/jquery/3.3.1/jquery.min.js&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 工具栏是否折叠&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;#x27;SHOW_COLLAPSED&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;literal&#34;&gt;True&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 是否显示工具栏&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;#x27;SHOW_TOOLBAR_CALLBACK&amp;#x27;&lt;/span&gt;: &lt;span class=&#34;keyword&#34;&gt;lambda&lt;/span&gt; x: &lt;span class=&#34;literal&#34;&gt;True&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;配置 - 修改urls.py。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; settings.DEBUG:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; debug_toolbar&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    urlpatterns.insert(&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;, path(&lt;span class=&#34;string&#34;&gt;&amp;#x27;__debug__/&amp;#x27;&lt;/span&gt;, include(debug_toolbar.urls)))&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;在配置好Django-Debug-Toolbar之后，页面右侧会看到一个调试工具栏，如下图所示，上面包括了如前所述的各种调试信息，包括执行时间、项目设置、请求头、SQL、静态资源、模板、缓存、信号等，查看起来非常的方便。&lt;/p&gt;
&lt;p&gt;&lt;img src=&#34;/res/debug-toolbar.png&#34;&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;h3 id=&#34;优化ORM代码&#34;&gt;&lt;a href=&#34;#优化ORM代码&#34; class=&#34;headerlink&#34; title=&#34;优化ORM代码&#34;&gt;&lt;/a&gt;优化ORM代码&lt;/h3&gt;&lt;p&gt;在配置了日志或Django-Debug-Toolbar之后，我们可以查看一下之前将老师数据导出成Excel报表的视图函数执行情况，这里我们关注的是ORM框架生成的SQL查询到底是什么样子的，相信这里的结果会让你感到有一些意外。执行&lt;code&gt;Teacher.objects.all()&lt;/code&gt;之后我们可以注意到，在控制台看到的或者通过Django-Debug-Toolbar输出的SQL是下面这样的：&lt;/p&gt;
&lt;figure class=&#34;highlight sql&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;SELECT&lt;/span&gt; `tb_teacher`.`&lt;span class=&#34;keyword&#34;&gt;no&lt;/span&gt;`, `tb_teacher`.`name`, `tb_teacher`.`detail`, `tb_teacher`.`photo`, `tb_teacher`.`good_count`, `tb_teacher`.`bad_count`, `tb_teacher`.`sno` &lt;span class=&#34;keyword&#34;&gt;FROM&lt;/span&gt; `tb_teacher`; args&lt;span class=&#34;operator&#34;&gt;=&lt;/span&gt;()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;SELECT&lt;/span&gt; `tb_subject`.`&lt;span class=&#34;keyword&#34;&gt;no&lt;/span&gt;`, `tb_subject`.`name`, `tb_subject`.`intro`, `tb_subject`.`create_date`, `tb_subject`.`is_hot` &lt;span class=&#34;keyword&#34;&gt;FROM&lt;/span&gt; `tb_subject` &lt;span class=&#34;keyword&#34;&gt;WHERE&lt;/span&gt; `tb_subject`.`&lt;span class=&#34;keyword&#34;&gt;no&lt;/span&gt;` &lt;span class=&#34;operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;101&lt;/span&gt;; args&lt;span class=&#34;operator&#34;&gt;=&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;101&lt;/span&gt;,)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;SELECT&lt;/span&gt; `tb_subject`.`&lt;span class=&#34;keyword&#34;&gt;no&lt;/span&gt;`, `tb_subject`.`name`, `tb_subject`.`intro`, `tb_subject`.`create_date`, `tb_subject`.`is_hot` &lt;span class=&#34;keyword&#34;&gt;FROM&lt;/span&gt; `tb_subject` &lt;span class=&#34;keyword&#34;&gt;WHERE&lt;/span&gt; `tb_subject`.`&lt;span class=&#34;keyword&#34;&gt;no&lt;/span&gt;` &lt;span class=&#34;operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;101&lt;/span&gt;; args&lt;span class=&#34;operator&#34;&gt;=&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;101&lt;/span&gt;,)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;SELECT&lt;/span&gt; `tb_subject`.`&lt;span class=&#34;keyword&#34;&gt;no&lt;/span&gt;`, `tb_subject`.`name`, `tb_subject`.`intro`, `tb_subject`.`create_date`, `tb_subject`.`is_hot` &lt;span class=&#34;keyword&#34;&gt;FROM&lt;/span&gt; `tb_subject` &lt;span class=&#34;keyword&#34;&gt;WHERE&lt;/span&gt; `tb_subject`.`&lt;span class=&#34;keyword&#34;&gt;no&lt;/span&gt;` &lt;span class=&#34;operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;101&lt;/span&gt;; args&lt;span class=&#34;operator&#34;&gt;=&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;101&lt;/span&gt;,)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;SELECT&lt;/span&gt; `tb_subject`.`&lt;span class=&#34;keyword&#34;&gt;no&lt;/span&gt;`, `tb_subject`.`name`, `tb_subject`.`intro`, `tb_subject`.`create_date`, `tb_subject`.`is_hot` &lt;span class=&#34;keyword&#34;&gt;FROM&lt;/span&gt; `tb_subject` &lt;span class=&#34;keyword&#34;&gt;WHERE&lt;/span&gt; `tb_subject`.`&lt;span class=&#34;keyword&#34;&gt;no&lt;/span&gt;` &lt;span class=&#34;operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;101&lt;/span&gt;; args&lt;span class=&#34;operator&#34;&gt;=&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;101&lt;/span&gt;,)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;SELECT&lt;/span&gt; `tb_subject`.`&lt;span class=&#34;keyword&#34;&gt;no&lt;/span&gt;`, `tb_subject`.`name`, `tb_subject`.`intro`, `tb_subject`.`create_date`, `tb_subject`.`is_hot` &lt;span class=&#34;keyword&#34;&gt;FROM&lt;/span&gt; `tb_subject` &lt;span class=&#34;keyword&#34;&gt;WHERE&lt;/span&gt; `tb_subject`.`&lt;span class=&#34;keyword&#34;&gt;no&lt;/span&gt;` &lt;span class=&#34;operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;103&lt;/span&gt;; args&lt;span class=&#34;operator&#34;&gt;=&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;103&lt;/span&gt;,)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;SELECT&lt;/span&gt; `tb_subject`.`&lt;span class=&#34;keyword&#34;&gt;no&lt;/span&gt;`, `tb_subject`.`name`, `tb_subject`.`intro`, `tb_subject`.`create_date`, `tb_subject`.`is_hot` &lt;span class=&#34;keyword&#34;&gt;FROM&lt;/span&gt; `tb_subject` &lt;span class=&#34;keyword&#34;&gt;WHERE&lt;/span&gt; `tb_subject`.`&lt;span class=&#34;keyword&#34;&gt;no&lt;/span&gt;` &lt;span class=&#34;operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;103&lt;/span&gt;; args&lt;span class=&#34;operator&#34;&gt;=&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;103&lt;/span&gt;,)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;这里的问题通常被称为“1+N查询”（有的地方也将其称之为“N+1查询”），原本获取老师的数据只需要一条SQL，但是由于老师关联了学科，当我们查询到&lt;code&gt;N&lt;/code&gt;条老师的数据时，Django的ORM框架又向数据库发出了&lt;code&gt;N&lt;/code&gt;条SQL去查询老师所属学科的信息。每条SQL执行都会有较大的开销而且会给数据库服务器带来压力，如果能够在一条SQL中完成老师和学科的查询肯定是更好的做法，这一点也很容易做到，相信大家已经想到怎么做了。是的，我们可以使用连接查询，但是在使用Django的ORM框架时如何做到这一点呢？对于多对一关联（如投票应用中的老师和学科），我们可以使用&lt;code&gt;QuerySet&lt;/code&gt;的用&lt;code&gt;select_related()&lt;/code&gt;方法来加载关联对象；而对于多对多关联（如电商网站中的订单和商品），我们可以使用&lt;code&gt;prefetch_related()&lt;/code&gt;方法来加载关联对象。&lt;/p&gt;
&lt;p&gt;在导出老师Excel报表的视图函数中，我们可以按照下面的方式优化代码。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;queryset = Teacher.objects.&lt;span class=&#34;built_in&#34;&gt;all&lt;/span&gt;().select_related(&lt;span class=&#34;string&#34;&gt;&amp;#x27;subject&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;事实上，用ECharts生成前端报表的视图函数中，查询老师好评和差评数据的操作也能够优化，因为在这个例子中，我们只需要获取老师的姓名、好评数和差评数这三项数据，但是在默认的情况生成的SQL会查询老师表的所有字段。可以用&lt;code&gt;QuerySet&lt;/code&gt;的&lt;code&gt;only()&lt;/code&gt;方法来指定需要查询的属性，也可以用&lt;code&gt;QuerySet&lt;/code&gt;的&lt;code&gt;defer()&lt;/code&gt;方法来指定暂时不需要查询的属性，这样生成的SQL会通过投影操作来指定需要查询的列，从而改善查询性能，代码如下所示：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;queryset = Teacher.objects.&lt;span class=&#34;built_in&#34;&gt;all&lt;/span&gt;().only(&lt;span class=&#34;string&#34;&gt;&amp;#x27;name&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;good_count&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;bad_count&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;当然，如果要统计出每个学科的老师好评和差评的平均数，利用Django的ORM框架也能够做到，代码如下所示：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;queryset = Teacher.objects.values(&lt;span class=&#34;string&#34;&gt;&amp;#x27;subject&amp;#x27;&lt;/span&gt;).annotate(good=Avg(&lt;span class=&#34;string&#34;&gt;&amp;#x27;good_count&amp;#x27;&lt;/span&gt;), bad=Avg(&lt;span class=&#34;string&#34;&gt;&amp;#x27;bad_count&amp;#x27;&lt;/span&gt;))&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;这里获得的&lt;code&gt;QuerySet&lt;/code&gt;中的元素是字典对象，每个字典中有三组键值对，分别是代表学科编号的&lt;code&gt;subject&lt;/code&gt;、代表好评数的&lt;code&gt;good&lt;/code&gt;和代表差评数的&lt;code&gt;bad&lt;/code&gt;。如果想要获得学科的名称而不是编号，可以按照如下所示的方式调整代码：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;queryset = Teacher.objects.values(&lt;span class=&#34;string&#34;&gt;&amp;#x27;subject__name&amp;#x27;&lt;/span&gt;).annotate(good=Avg(&lt;span class=&#34;string&#34;&gt;&amp;#x27;good_count&amp;#x27;&lt;/span&gt;), bad=Avg(&lt;span class=&#34;string&#34;&gt;&amp;#x27;bad_count&amp;#x27;&lt;/span&gt;))&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;可见，Django的ORM框架允许我们用面向对象的方式完成关系数据库中的分组和聚合查询。&lt;/p&gt;

 &lt;h2 id=&#34;制作报表&#34;&gt;&lt;a href=&#34;#制作报表&#34; class=&#34;headerlink&#34; title=&#34;制作报表&#34;&gt;&lt;/a&gt;制作报表&lt;/h2&gt;&lt;h3 id=&#34;导出Excel报表&#34;&gt;&lt;a href=&#34;#导出Excel报表&#34; class=&#34;headerlink&#34; title=&#34;导出Excel报表&#34;&gt;&lt;/a&gt;导出Excel报表&lt;/h3&gt;&lt;p&gt;报表就是用表格、图表等格式来动态显示数据，所以有人用这样的公式来描述报表：&lt;/p&gt;
&lt;figure class=&#34;highlight fix&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attr&#34;&gt;报表 &lt;/span&gt;=&lt;span class=&#34;string&#34;&gt; 多样的格式 + 动态的数据&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;有很多的三方库支持在Python程序中写Excel文件，包括&lt;a href=&#34;https://xlwt.readthedocs.io/en/latest/&#34;&gt;&lt;code&gt;xlwt&lt;/code&gt;&lt;/a&gt;、&lt;a href=&#34;https://docs.xlwings.org/en/latest/quickstart.html&#34;&gt;&lt;code&gt;xlwings&lt;/code&gt;&lt;/a&gt;、&lt;a href=&#34;https://openpyxl.readthedocs.io/en/latest/&#34;&gt;&lt;code&gt;openpyxl&lt;/code&gt;&lt;/a&gt;、&lt;a href=&#34;https://xlsxwriter.readthedocs.io/&#34;&gt;&lt;code&gt;xlswriter&lt;/code&gt;&lt;/a&gt;等，其中的xlwt虽然只支持写xls格式的Excel文件，但在性能方面的表现还是不错的。下面我们就以&lt;code&gt;xlwt&lt;/code&gt;为例，来演示如何在Django项目中导出Excel报表。&lt;/p&gt;
&lt;p&gt;安装&lt;code&gt;xlwt&lt;/code&gt;。&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;pip install xlwt&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;导出包含所有老师信息的Excel表格的视图函数。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;export_teachers_excel&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;request&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 创建工作簿&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    wb = xlwt.Workbook()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 添加工作表&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    sheet = wb.add_sheet(&lt;span class=&#34;string&#34;&gt;&amp;#x27;老师信息表&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 查询所有老师的信息&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    queryset = Teacher.objects.&lt;span class=&#34;built_in&#34;&gt;all&lt;/span&gt;()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 向Excel表单中写入表头&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    colnames = (&lt;span class=&#34;string&#34;&gt;&amp;#x27;姓名&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;介绍&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;好评数&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;差评数&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;学科&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; index, name &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; &lt;span class=&#34;built_in&#34;&gt;enumerate&lt;/span&gt;(colnames):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        sheet.write(&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;, index, name)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 向单元格中写入老师的数据&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    props = (&lt;span class=&#34;string&#34;&gt;&amp;#x27;name&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;detail&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;good_count&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;bad_count&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;subject&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; row, teacher &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; &lt;span class=&#34;built_in&#34;&gt;enumerate&lt;/span&gt;(queryset):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; col, prop &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; &lt;span class=&#34;built_in&#34;&gt;enumerate&lt;/span&gt;(props):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            value = &lt;span class=&#34;built_in&#34;&gt;getattr&lt;/span&gt;(teacher, prop, &lt;span class=&#34;string&#34;&gt;&amp;#x27;&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; &lt;span class=&#34;built_in&#34;&gt;isinstance&lt;/span&gt;(value, Subject):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                value = value.name&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            sheet.write(row + &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, col, value)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 保存Excel&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    buffer = BytesIO()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    wb.save(buffer)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 将二进制数据写入响应的消息体中并设置MIME类型&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    resp = HttpResponse(buffer.getvalue(), content_type=&lt;span class=&#34;string&#34;&gt;&amp;#x27;application/vnd.ms-excel&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 中文文件名需要处理成百分号编码&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    filename = quote(&lt;span class=&#34;string&#34;&gt;&amp;#x27;老师.xls&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 通过响应头告知浏览器下载该文件以及对应的文件名&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    resp[&lt;span class=&#34;string&#34;&gt;&amp;#x27;content-disposition&amp;#x27;&lt;/span&gt;] = &lt;span class=&#34;string&#34;&gt;f&amp;#x27;attachment; filename*=utf-8\&amp;#x27;\&amp;#x27;&lt;span class=&#34;subst&#34;&gt;&amp;#123;filename&amp;#125;&lt;/span&gt;&amp;#x27;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; resp&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;映射URL。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;urlpatterns = [&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    path(&lt;span class=&#34;string&#34;&gt;&amp;#x27;excel/&amp;#x27;&lt;/span&gt;, views.export_teachers_excel),&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;]&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h3 id=&#34;导出PDF报表&#34;&gt;&lt;a href=&#34;#导出PDF报表&#34; class=&#34;headerlink&#34; title=&#34;导出PDF报表&#34;&gt;&lt;/a&gt;导出PDF报表&lt;/h3&gt;&lt;p&gt;在Django项目中，如果需要导出PDF报表，可以借助三方库&lt;code&gt;reportlab&lt;/code&gt;来生成PDF文件的内容，再将文件的二进制数据输出给浏览器并指定MIME类型为&lt;code&gt;application/pdf&lt;/code&gt;，具体的代码如下所示。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;export_pdf&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;request: HttpRequest&lt;/span&gt;) -&amp;gt; HttpResponse:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    buffer = io.BytesIO()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    pdf = canvas.Canvas(buffer)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    pdf.setFont(&lt;span class=&#34;string&#34;&gt;&amp;quot;Helvetica&amp;quot;&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;80&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    pdf.setFillColorRGB(&lt;span class=&#34;number&#34;&gt;0.2&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0.5&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0.3&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    pdf.drawString(&lt;span class=&#34;number&#34;&gt;100&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;550&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;hello, world!&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    pdf.showPage()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    pdf.save()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    resp = HttpResponse(buffer.getvalue(), content_type=&lt;span class=&#34;string&#34;&gt;&amp;#x27;application/pdf&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    resp[&lt;span class=&#34;string&#34;&gt;&amp;#x27;content-disposition&amp;#x27;&lt;/span&gt;] = &lt;span class=&#34;string&#34;&gt;&amp;#x27;inline; filename=&amp;quot;demo.pdf&amp;quot;&amp;#x27;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; resp&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;关于如何用&lt;code&gt;reportlab&lt;/code&gt;定制PDF报表的内容，可以参考reportlab的&lt;a href=&#34;https://www.reportlab.com/docs/reportlab-userguide.pdf&#34;&gt;官方文档&lt;/a&gt;。&lt;/p&gt;
&lt;h3 id=&#34;生成前端统计图表&#34;&gt;&lt;a href=&#34;#生成前端统计图表&#34; class=&#34;headerlink&#34; title=&#34;生成前端统计图表&#34;&gt;&lt;/a&gt;生成前端统计图表&lt;/h3&gt;&lt;p&gt;如果项目中需要生成前端统计图表，可以使用百度的&lt;a href=&#34;https://echarts.baidu.com/&#34;&gt;ECharts&lt;/a&gt;。具体的做法是后端通过提供数据接口返回统计图表所需的数据，前端使用ECharts来渲染出柱状图、折线图、饼图、散点图等图表。例如我们要生成一个统计所有老师好评数和差评数的报表，可以按照下面的方式来做。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;get_teachers_data&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;request&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    queryset = Teacher.objects.&lt;span class=&#34;built_in&#34;&gt;all&lt;/span&gt;()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    names = [teacher.name &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; teacher &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; queryset]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    good_counts = [teacher.good_count &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; teacher &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; queryset]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    bad_counts = [teacher.bad_count &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; teacher &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; queryset]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; JsonResponse(&amp;#123;&lt;span class=&#34;string&#34;&gt;&amp;#x27;names&amp;#x27;&lt;/span&gt;: names, &lt;span class=&#34;string&#34;&gt;&amp;#x27;good&amp;#x27;&lt;/span&gt;: good_counts, &lt;span class=&#34;string&#34;&gt;&amp;#x27;bad&amp;#x27;&lt;/span&gt;: bad_counts&amp;#125;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;映射URL。&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;urlpatterns = [&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    path(&lt;span class=&#34;string&#34;&gt;&amp;#x27;teachers_data/&amp;#x27;&lt;/span&gt;, views.get_teachers_data),&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;]&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;使用ECharts生成柱状图。&lt;/p&gt;
&lt;figure class=&#34;highlight html&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;meta&#34;&gt;&amp;lt;!DOCTYPE &lt;span class=&#34;keyword&#34;&gt;html&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;html&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;lang&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;en&amp;quot;&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;head&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;meta&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;charset&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;UTF-8&amp;quot;&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;title&lt;/span&gt;&amp;gt;&lt;/span&gt;老师评价统计&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;title&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;head&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;body&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;div&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;id&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;main&amp;quot;&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;style&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;width: 600px; height: 400px&amp;quot;&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;div&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;p&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;a&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;href&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;/&amp;quot;&lt;/span&gt;&amp;gt;&lt;/span&gt;返回首页&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;a&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;p&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;script&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;src&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;https://cdn.bootcss.com/echarts/4.2.1-rc1/echarts.min.js&amp;quot;&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;script&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;script&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;span class=&#34;language-javascript&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;var&lt;/span&gt; myChart = echarts.&lt;span class=&#34;title function_&#34;&gt;init&lt;/span&gt;(&lt;span class=&#34;variable language_&#34;&gt;document&lt;/span&gt;.&lt;span class=&#34;title function_&#34;&gt;querySelector&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&amp;#x27;#main&amp;#x27;&lt;/span&gt;))&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;        &lt;span class=&#34;title function_&#34;&gt;fetch&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&amp;#x27;/teachers_data/&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;            .&lt;span class=&#34;title function_&#34;&gt;then&lt;/span&gt;(&lt;span class=&#34;function&#34;&gt;&lt;span class=&#34;params&#34;&gt;resp&lt;/span&gt; =&amp;gt;&lt;/span&gt; resp.&lt;span class=&#34;title function_&#34;&gt;json&lt;/span&gt;())&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;            .&lt;span class=&#34;title function_&#34;&gt;then&lt;/span&gt;(&lt;span class=&#34;function&#34;&gt;&lt;span class=&#34;params&#34;&gt;json&lt;/span&gt; =&amp;gt;&lt;/span&gt; &amp;#123;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;                &lt;span class=&#34;keyword&#34;&gt;var&lt;/span&gt; option = &amp;#123;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;                    &lt;span class=&#34;attr&#34;&gt;color&lt;/span&gt;: [&lt;span class=&#34;string&#34;&gt;&amp;#x27;#f00&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;#00f&amp;#x27;&lt;/span&gt;],&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;                    &lt;span class=&#34;attr&#34;&gt;title&lt;/span&gt;: &amp;#123;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;                        &lt;span class=&#34;attr&#34;&gt;text&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;老师评价统计图&amp;#x27;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;                    &amp;#125;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;                    &lt;span class=&#34;attr&#34;&gt;tooltip&lt;/span&gt;: &amp;#123;&amp;#125;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;                    &lt;span class=&#34;attr&#34;&gt;legend&lt;/span&gt;: &amp;#123;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;                        &lt;span class=&#34;attr&#34;&gt;data&lt;/span&gt;:[&lt;span class=&#34;string&#34;&gt;&amp;#x27;好评&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;差评&amp;#x27;&lt;/span&gt;]&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;                    &amp;#125;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;                    &lt;span class=&#34;attr&#34;&gt;xAxis&lt;/span&gt;: &amp;#123;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;                        &lt;span class=&#34;attr&#34;&gt;data&lt;/span&gt;: json.&lt;span class=&#34;property&#34;&gt;names&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;                    &amp;#125;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;                    &lt;span class=&#34;attr&#34;&gt;yAxis&lt;/span&gt;: &amp;#123;&amp;#125;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;                    &lt;span class=&#34;attr&#34;&gt;series&lt;/span&gt;: [&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;                        &amp;#123;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;                            &lt;span class=&#34;attr&#34;&gt;name&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;好评&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;                            &lt;span class=&#34;attr&#34;&gt;type&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;bar&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;                            &lt;span class=&#34;attr&#34;&gt;data&lt;/span&gt;: json.&lt;span class=&#34;property&#34;&gt;good&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;                        &amp;#125;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;                        &amp;#123;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;                            &lt;span class=&#34;attr&#34;&gt;name&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;差评&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;                            &lt;span class=&#34;attr&#34;&gt;type&lt;/span&gt;: &lt;span class=&#34;string&#34;&gt;&amp;#x27;bar&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;                            &lt;span class=&#34;attr&#34;&gt;data&lt;/span&gt;: json.&lt;span class=&#34;property&#34;&gt;bad&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;                        &amp;#125;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;                    ]&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;                &amp;#125;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;                myChart.&lt;span class=&#34;title function_&#34;&gt;setOption&lt;/span&gt;(option)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;            &amp;#125;)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-javascript&#34;&gt;    &lt;/span&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;script&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;body&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;html&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;运行效果如下图所示。&lt;/p&gt;
&lt;p&gt;&lt;img src=&#34;/./res/echarts_bar_graph.png&#34;&gt;&lt;/p&gt;

 &lt;h2 id=&#34;Cookie和Session&#34;&gt;&lt;a href=&#34;#Cookie和Session&#34; class=&#34;headerlink&#34; title=&#34;Cookie和Session&#34;&gt;&lt;/a&gt;Cookie和Session&lt;/h2&gt;&lt;p&gt;我们继续来完成上一章节中的项目，实现“用户登录”的功能，并限制只有登录的用户才能投票。&lt;/p&gt;
&lt;h3 id=&#34;用户登录的准备工作&#34;&gt;&lt;a href=&#34;#用户登录的准备工作&#34; class=&#34;headerlink&#34; title=&#34;用户登录的准备工作&#34;&gt;&lt;/a&gt;用户登录的准备工作&lt;/h3&gt;&lt;p&gt;我们先为实现用户登录做一些准备工作。&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;&lt;p&gt;创建用户模型。之前我们讲解过如果通过Django的ORM实现从二维表到模型的转换（反向工程），这次我们尝试把模型变成二维表（正向工程）。&lt;/p&gt;
 &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;class&lt;/span&gt; &lt;span class=&#34;title class_&#34;&gt;User&lt;/span&gt;(models.Model):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;&amp;quot;&amp;quot;用户&amp;quot;&amp;quot;&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    no = models.AutoField(primary_key=&lt;span class=&#34;literal&#34;&gt;True&lt;/span&gt;, verbose_name=&lt;span class=&#34;string&#34;&gt;&amp;#x27;编号&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    username = models.CharField(max_length=&lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;, unique=&lt;span class=&#34;literal&#34;&gt;True&lt;/span&gt;, verbose_name=&lt;span class=&#34;string&#34;&gt;&amp;#x27;用户名&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    password = models.CharField(max_length=&lt;span class=&#34;number&#34;&gt;32&lt;/span&gt;, verbose_name=&lt;span class=&#34;string&#34;&gt;&amp;#x27;密码&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    tel = models.CharField(max_length=&lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;, verbose_name=&lt;span class=&#34;string&#34;&gt;&amp;#x27;手机号&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    reg_date = models.DateTimeField(auto_now_add=&lt;span class=&#34;literal&#34;&gt;True&lt;/span&gt;, verbose_name=&lt;span class=&#34;string&#34;&gt;&amp;#x27;注册时间&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    last_visit = models.DateTimeField(null=&lt;span class=&#34;literal&#34;&gt;True&lt;/span&gt;, verbose_name=&lt;span class=&#34;string&#34;&gt;&amp;#x27;最后登录时间&amp;#x27;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;class&lt;/span&gt; &lt;span class=&#34;title class_&#34;&gt;Meta&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        db_table = &lt;span class=&#34;string&#34;&gt;&amp;#x27;tb_user&amp;#x27;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        verbose_name = &lt;span class=&#34;string&#34;&gt;&amp;#x27;用户&amp;#x27;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        verbose_name_plural = &lt;span class=&#34;string&#34;&gt;&amp;#x27;用户&amp;#x27;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;使用下面的命令生成迁移文件并执行迁移，将&lt;code&gt;User&lt;/code&gt;模型直接变成关系型数据库中的二维表&lt;code&gt;tb_user&lt;/code&gt;。&lt;/p&gt;
 &lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;python manage.py makemigrations polls&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;python manage.py migrate polls&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;用下面的SQL语句直接插入两条测试数据，通常不能将用户的密码直接保存在数据库中，因此我们将用户密码处理成对应的MD5摘要。MD5消息摘要算法是一种被广泛使用的密码哈希函数（散列函数），可以产生出一个128位（比特）的哈希值（散列值），用于确保信息传输完整一致。在使用哈希值时，通常会将哈希值表示为16进制字符串，因此128位的MD5摘要通常表示为32个十六进制符号。&lt;/p&gt;
 &lt;figure class=&#34;highlight sql&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;insert&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;into&lt;/span&gt; `tb_user`&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    (`username`, `password`, `tel`, `reg_date`)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;values&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    (&lt;span class=&#34;string&#34;&gt;&amp;#x27;wangdachui&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;1c63129ae9db9c60c3e8aa94d3e00495&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;13122334455&amp;#x27;&lt;/span&gt;, now()),&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    (&lt;span class=&#34;string&#34;&gt;&amp;#x27;hellokitty&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;c6f8cf68e5f68b0aa4680e089ee4742c&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;13890006789&amp;#x27;&lt;/span&gt;, now());&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;说明&lt;/strong&gt;：上面创建的两个用户&lt;code&gt;wangdachui&lt;/code&gt;和&lt;code&gt;hellokitty&lt;/code&gt;密码分别是&lt;code&gt;1qaz2wsx&lt;/code&gt;和&lt;code&gt;Abc123!!&lt;/code&gt;。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;我们在应用下增加一个名为&lt;code&gt;utils.py&lt;/code&gt;的模块用来保存需要使用的工具函数。Python标准库中的&lt;code&gt;hashlib&lt;/code&gt;模块封装了常用的哈希算法，包括：MD5、SHA1、SHA256等。下面是使用&lt;code&gt;hashlib&lt;/code&gt;中的&lt;code&gt;md5&lt;/code&gt;类将字符串处理成MD5摘要的函数如下所示。&lt;/p&gt;
 &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; hashlib&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;gen_md5_digest&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;content&lt;/span&gt;):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; hashlib.md5(content.encode()).hexdigest()&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;编写用户登录的视图函数和模板页。&lt;/p&gt;
&lt;p&gt; 添加渲染登录页面的视图函数：&lt;/p&gt;
 &lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;login&lt;/span&gt;(&lt;span class=&#34;params&#34;&gt;request: HttpRequest&lt;/span&gt;) -&amp;gt; HttpResponse:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    hint = &lt;span class=&#34;string&#34;&gt;&amp;#x27;&amp;#x27;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; render(request, &lt;span class=&#34;string&#34;&gt;&amp;#x27;login.html&amp;#x27;&lt;/span&gt;, &amp;#123;&lt;span class=&#34;string&#34;&gt;&amp;#x27;hint&amp;#x27;&lt;/span&gt;: hint&amp;#125;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt; 增加&lt;code&gt;login.html&lt;/code&gt;模板页：&lt;/p&gt;
 &lt;figure class=&#34;highlight html&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;meta&#34;&gt;&amp;lt;!DOCTYPE &lt;span class=&#34;keyword&#34;&gt;html&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;html&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;lang&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;en&amp;quot;&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;head&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;meta&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;charset&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;UTF-8&amp;quot;&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;title&lt;/span&gt;&amp;gt;&lt;/span&gt;用户登录&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;title&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;style&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;span class=&#34;language-css&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-css&#34;&gt;        &lt;span class=&#34;selector-id&#34;&gt;#container&lt;/span&gt; &amp;#123;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-css&#34;&gt;            &lt;span class=&#34;attribute&#34;&gt;width&lt;/span&gt;: &lt;span class=&#34;number&#34;&gt;520px&lt;/span&gt;;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-css&#34;&gt;            &lt;span class=&#34;attribute&#34;&gt;margin&lt;/span&gt;: &lt;span class=&#34;number&#34;&gt;10px&lt;/span&gt; auto;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-css&#34;&gt;        &amp;#125;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-css&#34;&gt;        &lt;span class=&#34;selector-class&#34;&gt;.input&lt;/span&gt; &amp;#123;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-css&#34;&gt;            &lt;span class=&#34;attribute&#34;&gt;margin&lt;/span&gt;: &lt;span class=&#34;number&#34;&gt;20px&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-css&#34;&gt;            &lt;span class=&#34;attribute&#34;&gt;width&lt;/span&gt;: &lt;span class=&#34;number&#34;&gt;460px&lt;/span&gt;;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-css&#34;&gt;            &lt;span class=&#34;attribute&#34;&gt;height&lt;/span&gt;: &lt;span class=&#34;number&#34;&gt;40px&lt;/span&gt;;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-css&#34;&gt;        &amp;#125;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-css&#34;&gt;        &lt;span class=&#34;selector-class&#34;&gt;.input&lt;/span&gt;&amp;gt;&lt;span class=&#34;selector-tag&#34;&gt;label&lt;/span&gt; &amp;#123;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-css&#34;&gt;            &lt;span class=&#34;attribute&#34;&gt;display&lt;/span&gt;: inline-block;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;language-css&#34;&gt;            &lt;span class=&#34;attribute&#34;&g